final_template:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the notification queue."
  type        = string
  default     = "us-east-1"
}

variable "queue_name" {
  description = "Name of the SQS notification queue."
  type        = string
  default     = "notificationQueue"
}

variable "kms_key_alias" {
  description = "Alias (without the 'alias/' prefix) for the customer-managed KMS key."
  type        = string
  default     = "alias/notificationQueue-key"
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (in days) before the KMS key is deleted."
  type        = number
  default     = 7
}

variable "app_role_name" {
  description = "Name of the IAM role used by applications to produce/consume messages."
  type        = string
  default     = "notificationQueue-app-role"
}

variable "tags" {
  description = "Tags applied to all supported resources."
  type        = map(string)
  default = {
    Application = "notification-service"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

###############################################################################
# KMS key (customer managed, rotation enabled)
###############################################################################

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccountFullAccessToKey"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "notification_queue" {
  description             = "Customer managed key used to encrypt the ${var.queue_name} SQS queue"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = merge(var.tags, {
    Name = "notificationQueue-key"
  })
}

resource "aws_kms_alias" "notification_queue" {
  name          = var.kms_key_alias
  target_key_id = aws_kms_key.notification_queue.key_id
}

###############################################################################
# SQS queue
###############################################################################

resource "aws_sqs_queue" "notification_queue" {
  name                       = var.queue_name
  delay_seconds              = 0
  max_message_size           = 2048
  visibility_timeout_seconds = 30
  message_retention_seconds  = 345600

  # Server-side encryption with the customer managed KMS key
  kms_master_key_id                 = aws_kms_key.notification_queue.arn
  kms_data_key_reuse_period_seconds = 300

  tags = merge(var.tags, {
    Name = var.queue_name
  })
}

###############################################################################
# Resource-based queue policy: only the current AWS account may use the queue
###############################################################################

data "aws_iam_policy_document" "notification_queue_policy" {
  statement {
    sid    = "AllowCurrentAccountOnly"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
    ]

    resources = [aws_sqs_queue.notification_queue.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sqs_queue_policy" "notification_queue_policy" {
  queue_url = aws_sqs_queue.notification_queue.id
  policy    = data.aws_iam_policy_document.notification_queue_policy.json
}

###############################################################################
# IAM role for applications producing/consuming messages
###############################################################################

data "aws_iam_policy_document" "app_assume_role" {
  statement {
    sid     = "AllowCurrentAccountPrincipalsToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "notification_app_role" {
  name               = var.app_role_name
  description        = "Role used to send/receive messages on the ${var.queue_name} SQS queue"
  assume_role_policy = data.aws_iam_policy_document.app_assume_role.json

  tags = merge(var.tags, {
    Name = var.app_role_name
  })
}

data "aws_iam_policy_document" "notification_app_permissions" {
  statement {
    sid    = "QueueAccess"
    effect = "Allow"

    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:ChangeMessageVisibility",
    ]

    resources = [aws_sqs_queue.notification_queue.arn]
  }

  statement {
    sid    = "KmsAccessForQueueEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.notification_queue.arn]
  }
}

resource "aws_iam_policy" "notification_app_policy" {
  name        = "${var.app_role_name}-policy"
  description = "Allows send/receive/delete on ${var.queue_name} and use of its KMS key"
  policy      = data.aws_iam_policy_document.notification_app_permissions.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "notification_app_policy_attachment" {
  role       = aws_iam_role.notification_app_role.name
  policy_arn = aws_iam_policy.notification_app_policy.arn
}

###############################################################################
# Outputs
###############################################################################

output "queue_name" {
  description = "Name of the created SQS queue."
  value       = aws_sqs_queue.notification_queue.name
}

output "queue_url" {
  description = "URL of the created SQS queue."
  value       = aws_sqs_queue.notification_queue.url
}

output "queue_arn" {
  description = "ARN of the created SQS queue."
  value       = aws_sqs_queue.notification_queue.arn
}

output "kms_key_id" {
  description = "ID of the customer managed KMS key used for queue encryption."
  value       = aws_kms_key.notification_queue.key_id
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used for queue encryption."
  value       = aws_kms_key.notification_queue.arn
}

output "app_role_arn" {
  description = "ARN of the IAM role allowed to produce/consume messages on the queue."
  value       = aws_iam_role.notification_app_role.arn
}

## Description of the Terraform program

This configuration deploys an **AWS Backup audit framework** used for benchmarking:

1. **Provider / tooling**
   - `terraform` block pins `hashicorp/aws (~> 5.0)` and `hashicorp/null (~> 3.2)`.
   - `provider "aws"` is configured with a `region` variable defaulting to `us-east-1` (a valid, universally available region).

2. **Input variables (all with defaults, no external input required)**
   - `aws_region` → default `"us-east-1"`.
   - `framework_name` → default `"benchmark"`, used as **both** the framework `name` and `description`.
   - `tag_key` → default `"BenchmarkTag"`, the key of the tag applied to the framework.

3. **Resources**
   - `null_resource.benchmark` – a basic, dependency-free null resource whose generated `id` (a creation timestamp) becomes the tag value. Because the framework references `null_resource.benchmark.id`, Terraform creates the null resource first and then applies the tag.
   - `aws_backup_framework.benchmark` – the framework itself:
     - `name` / `description` = `var.framework_name`.
     - One `control` block named `BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN` (the AWS Backup Audit Manager control that verifies resources are protected by a backup plan).
     - A `scope` block restricted strictly to EBS compliance resource types via `compliance_resource_types = ["EBS"]`.
     - `tags = { (var.tag_key) = null_resource.benchmark.id }` — dynamic tag key from the variable, value from the generated null-resource ID.

4. **Outputs** for verification: the framework ARN/name/status, the resolved tag key, and the generated tag value.

No IAM roles are required: AWS Backup frameworks are managed by the service and this configuration does not create a backup plan, vault, or selection that would need a service role. Permissions are provided by the credentials/role under which Terraform runs.

```iac_template
###############################################################################
# Terraform & provider requirements
###############################################################################
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables (all have defaults so the stack is deployable as-is)
###############################################################################
variable "aws_region" {
  description = "AWS region in which the AWS Backup framework is created."
  type        = string
  default     = "us-east-1"
}

variable "framework_name" {
  description = "Name and description used for the AWS Backup benchmarking framework."
  type        = string
  default     = "benchmark"
}

variable "tag_key" {
  description = "Tag key applied to the AWS Backup framework. Its value is the generated ID of the null resource."
  type        = string
  default     = "BenchmarkTag"
}

###############################################################################
# Basic null resource - its generated id is used as the framework tag value
###############################################################################
resource "null_resource" "benchmark" {}

###############################################################################
# AWS Backup framework
###############################################################################
resource "aws_backup_framework" "benchmark" {
  name        = var.framework_name
  description = var.framework_name

  control {
    name = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"

    # Scope the control strictly to EBS compliance resource types
    scope {
      compliance_resource_types = ["EBS"]
    }
  }

  tags = {
    (var.tag_key) = null_resource.benchmark.id
  }
}

###############################################################################
# Outputs
###############################################################################
output "backup_framework_arn" {
  description = "ARN of the created AWS Backup framework."
  value       = aws_backup_framework.benchmark.arn
}

output "backup_framework_name" {
  description = "Name of the created AWS Backup framework."
  value       = aws_backup_framework.benchmark.name
}

output "backup_framework_status" {
  description = "Deployment status of the AWS Backup framework."
  value       = aws_backup_framework.benchmark.status
}

output "framework_tag_key" {
  description = "Tag key applied to the AWS Backup framework."
  value       = var.tag_key
}

output "framework_tag_value" {
  description = "Generated ID of the null resource, used as the framework tag value."
  value       = null_resource.benchmark.id
}
```

# Terraform configuration for AWS KMS symmetric key with permissive policy and alias

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# AWS provider configuration
provider "aws" {
  region = "us-east-1"
}

# Symmetric KMS key for general encryption/decryption
# - 10-day deletion window
# - key rotation disabled (for testing)
# - highly permissive resource policy (all actions, all principals)
resource "aws_kms_key" "bar" {
  description              = "Symmetric KMS key for general encryption/decryption tasks"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  deletion_window_in_days  = 10
  enable_key_rotation      = false

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAllPrincipalsAllActions"
        Effect    = "Allow"
        Principal = "*"
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })

  tags = {
    Name        = "bar"
    Environment = "test"
    Purpose     = "general-encryption"
  }
}

# Alias for the KMS key
resource "aws_kms_alias" "bar" {
  name          = "alias/bar"
  target_key_id = aws_kms_key.bar.key_id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

############################################
# Variables
############################################
variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the new VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "project_name" {
  description = "Project name used as a prefix for tagging"
  type        = string
  default     = "alb-two-tier"
}

############################################
# Data sources
############################################
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

############################################
# VPC & Networking
############################################
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.project_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

############################################
# Security Groups (two-tier)
############################################
# Tier 1: "alb" security group
# - Inbound HTTP/80 from anywhere (0.0.0.0/0)
# - Outbound only to the VPC CIDR
resource "aws_security_group" "alb" {
  name        = "alb"
  description = "ALB SG: allow HTTP inbound from anywhere, egress only within VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "alb"
  }
}

# Tier 2: "allow_alb" security group
# - Inbound HTTP/80 exclusively from the "alb" security group
# - Outbound only to the VPC CIDR
resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Backend SG: allow HTTP only from ALB SG, egress only within VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_alb"
  }
}

############################################
# Application Load Balancer
############################################
resource "aws_lb" "app" {
  name               = "${var.project_name}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  tags = {
    Name = "${var.project_name}-alb"
  }
}

resource "aws_lb_target_group" "app" {
  name     = "${var.project_name}-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "${var.project_name}-tg"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.app.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

############################################
# Backend compute (Launch Template + ASG)
############################################
resource "aws_launch_template" "app" {
  name_prefix   = "${var.project_name}-lt-"
  image_id      = data.aws_ami.amazon_linux.id
  instance_type = "t3.micro"

  vpc_security_group_ids = [aws_security_group.allow_alb.id]

  user_data = base64encode(<<-EOF
    #!/bin/bash
    cd /tmp
    echo "Hello from $(hostname -f)" > index.html
    nohup python3 -m http.server 80 > /var/log/webserver.log 2>&1 &
    EOF
  )

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name = "${var.project_name}-instance"
    }
  }

  tag_specifications {
    resource_type = "volume"
    tags = {
      Name = "${var.project_name}-instance-volume"
    }
  }
}

resource "aws_autoscaling_group" "app" {
  name                = "${var.project_name}-asg"
  desired_capacity    = 2
  min_size            = 1
  max_size            = 3
  vpc_zone_identifier = aws_subnet.public[*].id
  target_group_arns   = [aws_lb_target_group.app.arn]
  health_check_type   = "ELB"

  launch_template {
    id      = aws_launch_template.app.id
    version = "$Latest"
  }

  tag {
    key                 = "Name"
    value               = "${var.project_name}-instance"
    propagate_at_launch = true
  }
}

############################################
# Outputs
############################################
output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "alb_dns_name" {
  description = "Public DNS name of the Application Load Balancer"
  value       = aws_lb.app.dns_name
}

output "alb_security_group_id" {
  description = "ID of the ALB security group"
  value       = aws_security_group.alb.id
}

output "allow_alb_security_group_id" {
  description = "ID of the backend security group"
  value       = aws_security_group.allow_alb.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region in which to create the IAM resources."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the Lambda execution role for VPC + EFS access."
  type        = string
  default     = "lambda-vpc-efs-execution-role"
}

variable "role_description" {
  description = "Description applied to the Lambda execution role."
  type        = string
  default     = "Execution role for Lambda functions that run inside a VPC and access Amazon EFS."
}

variable "tags" {
  description = "Tags applied to all taggable resources created by this configuration."
  type        = map(string)
  default = {
    ManagedBy   = "Terraform"
    Environment = "dev"
    Purpose     = "Lambda-VPC-EFS"
  }
}

############################################
# Trust policy: allow Lambda to assume the role
############################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

############################################
# AWS-managed policy lookups
############################################

data "aws_iam_policy" "lambda_vpc_access_execution_role" {
  name = "AWSLambdaVPCAccessExecutionRole"
}

data "aws_iam_policy" "efs_client_full_access" {
  name = "AmazonElasticFileSystemClientFullAccess"
}

############################################
# Execution role
############################################

resource "aws_iam_role" "lambda_vpc_efs_execution" {
  name        = var.role_name
  description = var.role_description

  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  max_session_duration = 3600

  tags = var.tags
}

############################################
# Managed policy attachments
############################################

resource "aws_iam_role_policy_attachment" "lambda_vpc_access" {
  role       = aws_iam_role.lambda_vpc_efs_execution.name
  policy_arn = data.aws_iam_policy.lambda_vpc_access_execution_role.arn
}

resource "aws_iam_role_policy_attachment" "efs_client_full_access" {
  role       = aws_iam_role.lambda_vpc_efs_execution.name
  policy_arn = data.aws_iam_policy.efs_client_full_access.arn
}

############################################
# Outputs
############################################

output "lambda_execution_role_name" {
  description = "Name of the Lambda execution role."
  value       = aws_iam_role.lambda_vpc_efs_execution.name
}

output "lambda_execution_role_arn" {
  description = "ARN of the Lambda execution role (use as the function's role argument)."
  value       = aws_iam_role.lambda_vpc_efs_execution.arn
}

output "attached_policy_arns" {
  description = "ARNs of the AWS-managed policies attached to the execution role."
  value = [
    data.aws_iam_policy.lambda_vpc_access_execution_role.arn,
    data.aws_iam_policy.efs_client_full_access.arn,
  ]
}

## Description

This template provisions a self-contained public networking stack on AWS:

- **Provider**: AWS provider pinned to `us-east-1` (region itself is a variable with a default), with required provider versions declared.
- **VPC**: `aws_vpc.public` with CIDR `10.0.0.0/16`, DNS support and DNS hostnames enabled.
- **Internet Gateway**: `aws_internet_gateway.public` attached to the VPC.
- **Public Subnet**: `aws_subnet.public` with CIDR `10.0.1.0/24`, placed in the first available AZ, with `map_public_ip_on_launch = true`.
- **Route Table**: `aws_route_table.public` attached to the VPC, holding an `aws_route` for `0.0.0.0/0` pointing at the internet gateway, and an `aws_route_table_association` that binds it to the public subnet.
- **Elastic IP**: `aws_eip.instance` (domain `vpc`) is always created as part of the stack. Attachment is handled by `aws_eip_association.instance`, which is created with `count` only when the `instance_id` variable is non-empty. The variable `instance_id` defaults to `""`, so the stack deploys cleanly with just the EIP allocated; setting the variable attaches it to the given EC2 instance.
- **Outputs**: VPC ID, subnet ID, internet gateway ID, route table ID, and the EIP allocation ID / public IP.

No IAM roles are required for this stack (it only creates VPC networking primitives and an EIP; no compute or service-linked roles beyond the standard AWS-managed ones handled by the provider). All variables have defaults, and every resource/attribute referenced is fully declared.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy the networking stack into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "instance_id" {
  description = "EC2 instance ID to associate the Elastic IP with. Empty string means allocate the EIP without attaching it."
  type        = string
  default     = ""
}

variable "name_prefix" {
  description = "Prefix used for tagging the networking resources."
  type        = string
  default     = "public-net"
}

# -----------------------------------------------------------------------------
# Availability zone lookup
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------
resource "aws_vpc" "public" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

# -----------------------------------------------------------------------------
# Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "public" {
  vpc_id = aws_vpc.public.id

  tags = {
    Name = "${var.name_prefix}-igw"
  }
}

# -----------------------------------------------------------------------------
# Public Subnet
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.public.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.name_prefix}-public-subnet"
    Tier = "public"
  }
}

# -----------------------------------------------------------------------------
# Route Table + Default Route to Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.public.id

  tags = {
    Name = "${var.name_prefix}-public-rt"
  }
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.public.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Elastic IP (allocated with the stack; attached when instance_id is provided)
# -----------------------------------------------------------------------------
resource "aws_eip" "instance" {
  domain = "vpc"

  tags = {
    Name = "${var.name_prefix}-eip"
  }
}

resource "aws_eip_association" "instance" {
  count = var.instance_id != "" ? 1 : 0

  allocation_id = aws_eip.instance.id
  instance_id   = var.instance_id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.public.id
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.public.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "elastic_ip_allocation_id" {
  description = "Allocation ID of the Elastic IP."
  value       = aws_eip.instance.id
}

output "elastic_ip_public_ip" {
  description = "Public IP address of the Elastic IP."
  value       = aws_eip.instance.public_ip
}

output "elastic_ip_attached_instance" {
  description = "Instance ID the Elastic IP is associated with, if any."
  value       = var.instance_id != "" ? var.instance_id : null
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region in which to create the test networking environment."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to all resource Name tags."
  type        = string
  default     = "test-network"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "IPv4 CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "IPv4 CIDR block for the private subnet."
  type        = string
  default     = "10.0.2.0/24"
}

# -----------------------------------------------------------------------------
# Data sources
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  ipv6_cidr_block         = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${var.project_name}-private-subnet"
  }
}

# -----------------------------------------------------------------------------
# Internet Gateway
# -----------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-igw"
  }
}

# -----------------------------------------------------------------------------
# Public route table + routes + association
# -----------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-public-rt"
  }
}

resource "aws_route" "public_ipv4_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_internet" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Private route table + association (isolated - no internet route)
# -----------------------------------------------------------------------------

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_ipv6_cidr_block" {
  description = "IPv6 CIDR block assigned to the VPC."
  value       = aws_vpc.main.ipv6_cidr_block
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet."
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table associated with the public subnet."
  value       = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Suffixes for count-based buckets
  count_suffixes = ["bucket3", "bucket4"]

  # Map collection for additional buckets
  bucket_suffixes_map = {
    bucket101 = "bucket101"
    bucket102 = "bucket102"
  }

  # List collection for additional buckets
  bucket_suffixes_list = ["bucket103", "bucket104"]

  # Merge map and list into a single map for for_each
  extra_buckets = merge(
    local.bucket_suffixes_map,
    { for s in local.bucket_suffixes_list : s => s }
  )

  common_tags = {
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

# Single shared customer-managed KMS key for S3 encryption
resource "aws_kms_key" "s3" {
  description             = "Customer managed key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = merge(local.common_tags, { Name = "s3-test-encryption-key" })
}

resource "aws_kms_alias" "s3" {
  name          = "alias/s3-test-buckets"
  target_key_id = aws_kms_key.s3.key_id
}

# Standalone bucket with suffix "bucket2"
resource "aws_s3_bucket" "bucket2" {
  bucket = "${local.account_id}-bucket2"
  tags   = merge(local.common_tags, { Name = "${local.account_id}-bucket2" })
}

# Two count-based buckets with suffixes "bucket3" and "bucket4"
resource "aws_s3_bucket" "count_buckets" {
  count  = 2
  bucket = "${local.account_id}-${local.count_suffixes[count.index]}"
  tags   = merge(local.common_tags, { Name = "${local.account_id}-${local.count_suffixes[count.index]}" })
}

# Four buckets via local map and list collections (bucket101 - bucket104)
resource "aws_s3_bucket" "extra" {
  for_each = local.extra_buckets
  bucket   = "${local.account_id}-${each.key}"
  tags     = merge(local.common_tags, { Name = "${local.account_id}-${each.key}" })
}

# Block all public access for the standalone bucket
resource "aws_s3_bucket_public_access_block" "bucket2" {
  bucket                  = aws_s3_bucket.bucket2.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Block all public access for count-based buckets
resource "aws_s3_bucket_public_access_block" "count_buckets" {
  count                   = 2
  bucket                  = aws_s3_bucket.count_buckets[count.index].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Block all public access for extras
resource "aws_s3_bucket_public_access_block" "extra" {
  for_each                = local.extra_buckets
  bucket                  = aws_s3_bucket.extra[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default SSE-KMS encryption for the standalone bucket
resource "aws_s3_bucket_server_side_encryption_configuration" "bucket2" {
  bucket = aws_s3_bucket.bucket2.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
    bucket_key_enabled = true
  }
}

# Default SSE-KMS encryption for count-based buckets
resource "aws_s3_bucket_server_side_encryption_configuration" "count_buckets" {
  count  = 2
  bucket = aws_s3_bucket.count_buckets[count.index].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
    bucket_key_enabled = true
  }
}

# Default SSE-KMS encryption for extras
resource "aws_s3_bucket_server_side_encryption_configuration" "extra" {
  for_each = local.extra_buckets
  bucket   = aws_s3_bucket.extra[each.key].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
    bucket_key_enabled = true
  }
}

output "bucket_names" {
  description = "Names of all created S3 buckets"
  value = concat(
    [aws_s3_bucket.bucket2.bucket],
    aws_s3_bucket.count_buckets[*].bucket,
    [for b in aws_s3_bucket.extra : b.bucket]
  )
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "budget_name" {
  description = "Name of the budget and SNS topic"
  default     = "budget"
}

variable "budget_limit" {
  description = "Budget limit amount"
  default     = "25.0"
}

variable "notification_email" {
  description = "Email address for budget notifications"
  default     = "hello@chriswilding.co.uk"
}

variable "sms_phone_number" {
  description = "Phone number for SMS subscription"
  default     = "+447828835419"
}

data "aws_caller_identity" "current" {}

# KMS key for SNS topic encryption
data "aws_iam_policy_document" "kms_policy" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow AWS Budgets to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["budgets.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "Allow SNS to use the key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "budget" {
  description = "KMS key for Budget SNS topic encryption"
  policy      = data.aws_iam_policy_document.kms_policy.json
}

# SNS topic
resource "aws_sns_topic" "budget" {
  name              = var.budget_name
  kms_master_key_id = aws_kms_key.budget.id
}

# SNS topic policy
data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid    = "AllowAccountOwner"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["SNS:*"]
    resources = [aws_sns_topic.budget.arn]
  }

  statement {
    sid    = "AllowBudgetsToPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["budgets.amazonaws.com"]
    }
    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.budget.arn]
  }
}

resource "aws_sns_topic_policy" "budget" {
  arn    = aws_sns_topic.budget.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

# SMS subscription
resource "aws_sns_topic_subscription" "sms" {
  topic_arn = aws_sns_topic.budget.arn
  protocol  = "sms"
  endpoint  = var.sms_phone_number
}

# Budget
resource "aws_budgets_budget" "budget" {
  name              = var.budget_name
  budget_type       = "COST"
  limit_amount      = var.budget_limit
  limit_unit        = "USD"
  time_unit         = "MONTHLY"
  time_period_start = "2021-07-01_00:00"

  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 100
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_sns_topic_arns  = [aws_sns_topic.budget.arn]
    subscriber_email_addresses = [var.notification_email]
  }

  depends_on = [
    aws_sns_topic_policy.budget,
    aws_kms_key.budget
  ]
}

terraform {
  required_version = ">= 1.0"

