variable "aws_region" {
  description = "AWS region in which to deploy the EFS file system."
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Encrypted EFS file system (intentionally tagged "NotSecure" for testing
# file storage access policies).
# ---------------------------------------------------------------------------
resource "aws_efs_file_system" "not_secure" {
  creation_token = "efs-not-secure"
  encrypted      = true

  tags = {
    Name = "NotSecure"
  }
}

# ---------------------------------------------------------------------------
# Overly permissive EFS file system policy: allows ALL elasticfilesystem
# actions for ANY AWS principal. This is deliberately insecure and is only
# intended for testing file storage access policies.
# ---------------------------------------------------------------------------
resource "aws_efs_file_system_policy" "not_secure" {
  file_system_id = aws_efs_file_system.not_secure.id

  # Allow applying this policy even if it would lock out the caller.
  bypass_policy_lockout_safety_check = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ExamplePolicy01"
    Statement = [
      {
        Sid    = "ExampleStatement01"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action   = "elasticfilesystem:*"
        Resource = aws_efs_file_system.not_secure.arn
      }
    ]
  })
}

output "efs_file_system_id" {
  description = "The ID of the EFS file system."
  value       = aws_efs_file_system.not_secure.id
}

output "efs_file_system_arn" {
  description = "The ARN of the EFS file system."
  value       = aws_efs_file_system.not_secure.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # ---------------------------------------------------------------------------
  # Once this stack has been applied, uncomment the block below and run
  # `terraform init -migrate-state` to store this configuration's own state
  # in the remote backend it just created.
  # ---------------------------------------------------------------------------
  # backend "s3" {
  #   bucket         = "terraform-remote-state-storage-s3-kjg"
  #   key            = "global/terraform.tfstate"
  #   region         = "us-east-1"
  #   dynamodb_table = "terraform-state-lock-dynamo"
  #   encrypt        = true
  #   kms_key_id     = "alias/terraform-remote-state"
  # }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Data sources / locals
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # Constructed rather than referenced to avoid a dependency cycle between the
  # KMS key policy and the IAM role that consumes the key.
  state_access_role_arn = "arn:${local.partition}:iam::${local.account_id}:role/${var.state_access_role_name}"

  common_tags = merge(var.tags, {
    Stack = "terraform-remote-state"
  })
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region in which the remote state backend resources are created."
  type        = string
  default     = "us-east-1"
}

variable "state_bucket_name" {
  description = "Globally unique name of the S3 bucket used to store Terraform state files."
  type        = string
  default     = "terraform-remote-state-storage-s3-kjg"
}

variable "lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  type        = string
  default     = "terraform-state-lock-dynamo"
}

variable "lock_table_read_capacity" {
  description = "Provisioned read capacity units for the DynamoDB state lock table."
  type        = number
  default     = 20
}

variable "lock_table_write_capacity" {
  description = "Provisioned write capacity units for the DynamoDB state lock table."
  type        = number
  default     = 20
}

variable "kms_key_deletion_window_in_days" {
  description = "Number of days before the KMS key is permanently deleted after destruction."
  type        = number
  default     = 30
}

variable "kms_alias_name" {
  description = "Alias (without the 'alias/' prefix) for the customer-managed KMS key."
  type        = string
  default     = "terraform-remote-state"
}

variable "state_access_role_name" {
  description = "Name of the IAM role that grants access to the remote state bucket, lock table and KMS key."
  type        = string
  default     = "terraform-remote-state-access"
}

variable "tags" {
  description = "Tags applied to all resources created by this stack."
  type        = map(string)
  default = {
    Project   = "terraform-remote-state"
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# KMS key for S3 server-side encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "terraform_state" {
  description             = "Customer-managed key used to encrypt Terraform remote state objects in ${var.state_bucket_name}"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "terraform-remote-state-key-policy"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceUseOfKey"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowStateAccessRoleUseOfKey"
        Effect = "Allow"
        Principal = {
          AWS = local.state_access_role_arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.state_bucket_name}-kms-key"
  })
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/${var.kms_alias_name}"
  target_key_id = aws_kms_key.terraform_state.key_id
}

# ---------------------------------------------------------------------------
# S3 bucket for Terraform state
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "terraform_state" {
  bucket        = var.state_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = var.state_bucket_name
  })
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  # Ensure the public access block is in place before attaching any policy.
  depends_on = [aws_s3_bucket_public_access_block.terraform_state]

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "terraform-remote-state-bucket-policy"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.terraform_state.arn,
          "${aws_s3_bucket.terraform_state.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyUnencryptedObjectUploads"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.terraform_state.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_lifecycle_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

# ---------------------------------------------------------------------------
# DynamoDB table for state locking
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "terraform_lock" {
  name           = var.lock_table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = var.lock_table_read_capacity
  write_capacity = var.lock_table_write_capacity

  hash_key = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = var.lock_table_name
  })
}

# ---------------------------------------------------------------------------
# IAM role used to access the remote state backend
# ---------------------------------------------------------------------------
resource "aws_iam_role" "state_access" {
  name        = var.state_access_role_name
  description = "Role that grants read/write access to the Terraform remote state bucket, lock table and KMS key."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountPrincipalsToAssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = var.state_access_role_name
  })
}

resource "aws_iam_role_policy" "state_access" {
  name = "${var.state_access_role_name}-policy"
  role = aws_iam_role.state_access.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListStateBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketVersions",
          "s3:GetBucketLocation",
          "s3:GetBucketVersioning"
        ]
        Resource = aws_s3_bucket.terraform_state.arn
      },
      {
        Sid    = "ReadWriteStateObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion"
        ]
        Resource = "${aws_s3_bucket.terraform_state.arn}/*"
      },
      {
        Sid    = "EncryptDecryptState"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.terraform_state.arn
      },
      {
        Sid    = "ManageStateLocks"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:UpdateItem",
          "dynamodb:DescribeTable"
        ]
        Resource = aws_dynamodb_table.terraform_lock.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "state_bucket_name" {
  description = "Name of the S3 bucket that stores Terraform state files."
  value       = aws_s3_bucket.terraform_state.bucket
}

output "state_bucket_arn" {
  description = "ARN of the S3 bucket that stores Terraform state files."
  value       = aws_s3_bucket.terraform_state.arn
}

output "state_kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for state encryption."
  value       = aws_kms_key.terraform_state.arn
}

output "state_kms_key_alias" {
  description = "Alias of the customer-managed KMS key used for state encryption."
  value       = aws_kms_alias.terraform_state.name
}

output "lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  value       = aws_dynamodb_table.terraform_lock.name
}

output "lock_table_arn" {
  description = "ARN of the DynamoDB table used for Terraform state locking."
  value       = aws_dynamodb_table.terraform_lock.arn
}

output "state_access_role_arn" {
  description = "ARN of the IAM role that can read/write the Terraform remote state backend."
  value       = aws_iam_role.state_access.arn
}

output "backend_configuration" {
  description = "Backend configuration snippet to paste into other Terraform configurations."
  value       = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.terraform_state.bucket}"
        key            = "path/to/terraform.tfstate"
        region         = "${var.aws_region}"
        dynamodb_table = "${aws_dynamodb_table.terraform_lock.name}"
        encrypt        = true
        kms_key_id     = "${aws_kms_alias.terraform_state.name}"
      }
    }
  EOT
}

## Description of Terraform Program

This configuration provisions a single Amazon CloudWatch Log Group whose name is generated dynamically at apply time:

1. **Providers** — Two providers are configured: `hashicorp/random` (for random name generation) and `hashicorp/aws` (for the CloudWatch resource). The AWS provider is pinned to a valid region (default `us-east-1`, overridable via a variable with a default value).

2. **Random name generation** — A `random_pet` resource is created with `length = 2`, producing a deterministic-upon-apply, human-readable two-word pet name (e.g., `cunning-lion`). A `random_pet` generates lowercase words joined by a separator (`-` by default), which keeps the log group name valid per CloudWatch naming rules (`[\.\-_/#A-Za-z0-9]+`).

3. **Log Group** — An `aws_cloudwatch_log_group` resource is created with:
   - `name = "log-group-${random_pet.this.id}"` → e.g., `log-group-cunning-lion`
   - A configurable `retention_in_days` (default `7`) so the resource is fully specified and cost-conscious.
   - Tags for identification.

4. **Outputs** — The generated log group name and ARN are exported so downstream tooling (e.g., subscription filters, agents) can reference them.

No IAM roles are required: a CloudWatch Log Group is a regional resource and does not itself assume a role; access control is handled by IAM policies on the principals that write to the log group, which is outside the scope of this request.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

############################################
# Variables (all with defaults)
############################################

variable "aws_region" {
  description = "AWS region in which to create the CloudWatch log group."
  type        = string
  default     = "us-east-1"
}

variable "log_group_name_prefix" {
  description = "Prefix applied to the dynamically generated CloudWatch log group name."
  type        = string
  default     = "log-group-"
}

variable "log_group_retention_in_days" {
  description = "Number of days to retain log events in the CloudWatch log group."
  type        = number
  default     = 7
}

variable "tags" {
  description = "A map of tags to assign to the created resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Purpose   = "Logging"
  }
}

############################################
# Providers
############################################

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

provider "random" {}

############################################
# Random two-word pet name
############################################

resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

############################################
# CloudWatch Log Group
############################################

resource "aws_cloudwatch_log_group" "this" {
  name              = "${var.log_group_name_prefix}${random_pet.this.id}"
  retention_in_days = var.log_group_retention_in_days

  tags = merge(
    var.tags,
    {
      Name = "${var.log_group_name_prefix}${random_pet.this.id}"
    }
  )
}

############################################
# Outputs
############################################

output "log_group_name" {
  description = "The generated name of the CloudWatch log group."
  value       = aws_cloudwatch_log_group.this.name
}

output "log_group_arn" {
  description = "The ARN of the CloudWatch log group."
  value       = aws_cloudwatch_log_group.this.arn
}

output "pet_name_identifier" {
  description = "The random two-word pet name used as a suffix for the log group."
  value       = random_pet.this.id
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = "Website CV"
      Environment = "production"
    }
  }
}

resource "aws_route53_delegation_set" "website_dns" {
  reference_name = "WebsiteDNS"
}

resource "aws_ssm_parameter" "delegation_set_id" {
  name  = "/WebsiteCv/production/Route53/DelegationSetId"
  type  = "String"
  value = aws_route53_delegation_set.website_dns.id

  tags = {
    Project     = "Website CV"
    Environment = "production"
  }
}

output "delegation_set_id" {
  description = "The ID of the Route 53 delegation set."
  value       = aws_route53_delegation_set.website_dns.id
}

output "delegation_set_name_servers" {
  description = "The name servers associated with the Route 53 delegation set."
  value       = aws_route53_delegation_set.website_dns.name_servers
}

output "ssm_parameter_name" {
  description = "The name of the SSM parameter storing the delegation set ID."
  value       = aws_ssm_parameter.delegation_set_id.name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket for benchmarking."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  description = "Value for the Name tag applied to resources."
  type        = string
  default     = "benchmark"
}

variable "force_destroy" {
  description = "Whether to force destroy the S3 bucket even if it contains objects."
  type        = bool
  default     = true
}

resource "aws_kms_key" "this" {
  description             = "KMS key for S3 bucket ${var.bucket_name} server-side encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = {
    Name = var.name_tag
  }
}

resource "aws_s3_bucket" "this" {
  bucket        = var.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = var.name_tag
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_account_public_access_block" "this" {
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

output "bucket_name" {
  description = "The name of the benchmark S3 bucket."
  value       = aws_s3_bucket.this.bucket
}

output "bucket_arn" {
  description = "The ARN of the benchmark S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "kms_key_arn" {
  description = "The ARN of the customer-managed KMS key."
  value       = aws_kms_key.this.arn
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "bucket_base_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "benchmark"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = data.aws_iam_policy_document.kms.json

  tags = {
    Name = "${var.bucket_base_name}-cloudtrail-${data.aws_region.current.name}"
  }
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow CloudTrail to encrypt logs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${var.bucket_base_name}-cloudtrail-${data.aws_region.current.name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = "${var.bucket_base_name}-cloudtrail-${data.aws_region.current.name}"
  force_destroy = true

  tags = {
    Name = "${var.bucket_base_name}-cloudtrail-${data.aws_region.current.name}"
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "cloudtrail" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      App    = var.app_name
      Module = var.module
      Stage  = var.stage
    }
  }
}

variable "app_name" {
  description = "Human-readable application name"
  type        = string
  default     = "Trilium Notes"
}

variable "app" {
  description = "Short application identifier used in log group names"
  type        = string
  default     = "trilium"
}

variable "module" {
  description = "Module identifier used in log group names"
  type        = string
  default     = "log"
}

variable "stage" {
  description = "Deployment stage used in log group names"
  type        = string
  default     = "production"
}

variable "log_retention" {
  description = "CloudWatch log retention period in days"
  type        = number
  default     = 120
}

locals {
  app_log_group_name   = "cwlg-${var.app}-${var.module}-${var.stage}-app"
  proxy_log_group_name = "cwlg-${var.app}-${var.module}-${var.stage}-proxy"
}

resource "aws_cloudwatch_log_group" "app" {
  name              = local.app_log_group_name
  retention_in_days = var.log_retention

  tags = {
    Name = local.app_log_group_name
  }
}

resource "aws_cloudwatch_log_group" "proxy" {
  name              = local.proxy_log_group_name
  retention_in_days = var.log_retention

  tags = {
    Name = local.proxy_log_group_name
  }
}

output "app_log_group_name" {
  description = "Name of the application CloudWatch log group"
  value       = aws_cloudwatch_log_group.app.name
}

output "proxy_log_group_name" {
  description = "Name of the reverse proxy CloudWatch log group"
  value       = aws_cloudwatch_log_group.proxy.name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region in which to deploy the resources."
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Default VPC lookups (used for EFS mount targets and security group)
###############################################################################

data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

###############################################################################
# Security group allowing NFS traffic to the EFS mount targets
###############################################################################

resource "aws_security_group" "efs" {
  name        = "cloudrail-test-efs-sg"
  description = "Allow NFS traffic to the cloudrail-test EFS file system"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description = "NFS from within the VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.default.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "cloudrail-test-efs-sg"
  }
}

###############################################################################
# Encrypted EFS file system and mount targets
###############################################################################

resource "aws_efs_file_system" "cloudrail_test" {
  creation_token = "cloudrail-test"
  encrypted      = true

  tags = {
    Name = "cloudrail-test"
  }
}

resource "aws_efs_mount_target" "cloudrail_test" {
  count = length(data.aws_subnets.default.ids)

  file_system_id  = aws_efs_file_system.cloudrail_test.id
  subnet_id       = data.aws_subnets.default.ids[count.index]
  security_groups = [aws_security_group.efs.id]
}

###############################################################################
# IAM roles for the ECS task
###############################################################################

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution" {
  name               = "cloudrail-test-ecs-task-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = {
    Name = "cloudrail-test-ecs-task-execution-role"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "ecs_task" {
  name               = "cloudrail-test-ecs-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = {
    Name = "cloudrail-test-ecs-task-role"
  }
}

data "aws_iam_policy_document" "ecs_task_efs" {
  statement {
    effect = "Allow"

    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess",
      "elasticfilesystem:DescribeFileSystems",
      "elasticfilesystem:DescribeMountTargets",
    ]

    resources = [aws_efs_file_system.cloudrail_test.arn]
  }
}

resource "aws_iam_role_policy" "ecs_task_efs" {
  name   = "cloudrail-test-efs-access"
  role   = aws_iam_role.ecs_task.id
  policy = data.aws_iam_policy_document.ecs_task_efs.json
}

###############################################################################
# EFS file system policy granting the ECS task role access over TLS
###############################################################################

resource "aws_efs_file_system_policy" "cloudrail_test" {
  file_system_id = aws_efs_file_system.cloudrail_test.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcsTaskAccess"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.ecs_task.arn
        }
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = aws_efs_file_system.cloudrail_test.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "true"
          }
        }
      }
    ]
  })
}

###############################################################################
# ECS cluster
###############################################################################

resource "aws_ecs_cluster" "cloudrail_test" {
  name = "cloudrail-test-cluster"

  tags = {
    Name = "cloudrail-test-cluster"
  }
}

###############################################################################
# ECS task definition with two containers and an EFS volume
###############################################################################

resource "aws_ecs_task_definition" "cloudrail_test" {
  family                   = "cloudrail-test-encryption"
  network_mode             = "awsvpc"
  requires_compatibilities = ["EC2"]
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "first"
      image     = "service-first"
      cpu       = 10
      memory    = 512
      essential = true

      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "service-storage"
          containerPath = "/opt/data"
          readOnly      = false
        }
      ]
    },
    {
      name      = "second"
      image     = "service-second"
      cpu       = 10
      memory    = 256
      essential = true

      portMappings = [
        {
          containerPort = 443
          hostPort      = 443
          protocol      = "tcp"
        }
      ]
    }
  ])

  volume {
    name = "service-storage"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.cloudrail_test.id
      root_directory          = "/opt/data"
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2999
    }
  }

  tags = {
    Name = "cloudrail-test-encryption"
  }
}

## Description of the Terraform Program

This Terraform configuration provisions two Amazon Elastic Container Registry (ECR) repositories used to store Docker container images for the `SaintsXCTF API` application:

1. **`saints-xctf-api-flask`** — repository for the Flask-based API container images, tagged with `Name = "saints-xctf-api-flask-container-repository"`.
2. **`saints-xctf-api-nginx`** — repository for the Nginx reverse-proxy container images, tagged with `Name = "saints-xctf-api-nginx-container-repository"`.

Both repositories are configured with:
- **Immutable image tags** (`image_tag_mutability = "IMMUTABLE"`), preventing an existing tag from being overwritten.
- **Automatic image scanning on push** (`scan_on_push = true`), so vulnerabilities are detected for every pushed image.
- **Shared tags** applied through a `local.common_tags` map: `Application = "saints-xctf"` and `Environment = "all"`, merged with each repository's `Name` tag.

Supporting configuration includes:
- A valid AWS provider configuration (region supplied via the `aws_region` variable with a sensible default).
- Variables with default values for region, application name, and environment, so the module is deployable without any user-supplied inputs.
- Outputs exposing each repository's name, ARN, and URL for downstream use.
- No IAM roles are required, since ECR repository management relies on the caller's AWS identity and no service-linked execution roles are needed for this resource type.

```iac_template
terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to create the ECR repositories."
  type        = string
  default     = "us-east-1"
}

variable "application" {
  description = "Name of the application the repositories belong to."
  type        = string
  default     = "saints-xctf"
}

variable "environment" {
  description = "Environment the repositories belong to."
  type        = string
  default     = "all"
}

locals {
  common_tags = {
    Application = var.application
    Environment = var.environment
  }
}

resource "aws_ecr_repository" "saints_xctf_api_flask" {
  name                 = "saints-xctf-api-flask"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.common_tags, {
    Name = "saints-xctf-api-flask-container-repository"
  })
}

resource "aws_ecr_repository" "saints_xctf_api_nginx" {
  name                 = "saints-xctf-api-nginx"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.common_tags, {
    Name = "saints-xctf-api-nginx-container-repository"
  })
}

output "flask_repository_name" {
  description = "Name of the Flask ECR repository."
  value       = aws_ecr_repository.saints_xctf_api_flask.name
}

output "flask_repository_arn" {
  description = "ARN of the Flask ECR repository."
  value       = aws_ecr_repository.saints_xctf_api_flask.arn
}

output "flask_repository_url" {
  description = "URL of the Flask ECR repository."
  value       = aws_ecr_repository.saints_xctf_api_flask.repository_url
}

output "nginx_repository_name" {
  description = "Name of the Nginx ECR repository."
  value       = aws_ecr_repository.saints_xctf_api_nginx.name
}

output "nginx_repository_arn" {
  description = "ARN of the Nginx ECR repository."
  value       = aws_ecr_repository.saints_xctf_api_nginx.arn
}

output "nginx_repository_url" {
  description = "URL of the Nginx ECR repository."
  value       = aws_ecr_repository.saints_xctf_api_nginx.repository_url
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the key pair into."
  type        = string
  default     = "us-east-1"
}

variable "key_prefix" {
  description = "Prefix used when constructing the AWS key pair name."
  type        = string
  default     = "key"
}

resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  key_name = "${var.key_prefix}-${random_pet.this.id}"
}

resource "tls_private_key" "this" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "this" {
  key_name   = local.key_name
  public_key = tls_private_key.this.public_key_openssh

  tags = {
    Name = local.key_name
  }

  provisioner "local-exec" {
    command = "umask 077 && printf '%s' \"$PRIVATE_KEY\" > \"../${local.key_name}\" && chmod 600 \"../${local.key_name}\""

    environment = {
      PRIVATE_KEY = tls_private_key.this.private_key_pem
    }
  }
}

# =============================================================================
# Terraform configuration: self-contained VPC network for web services
# Creates:
#   - A VPC with CIDR block 10.0.0.0/16 (DNS support + hostnames enabled)
#   - Public subnets across available AZs, an Internet Gateway and routing
#   - A security group named "Example security group" with ingress on 443/80
# =============================================================================

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Provider configuration
# -----------------------------------------------------------------------------
provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables (all with defaults so the configuration is deployable as-is)
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region in which to deploy the network infrastructure."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets used by the web services."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "project_name" {
  description = "Name used for tagging the created resources."
  type        = string
  default     = "web-services"
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

# -----------------------------------------------------------------------------
# Data sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.project_name}-vpc"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Public subnets (one per supplied CIDR, spread across available AZs)
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${var.project_name}-public-${count.index + 1}"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Internet Gateway + public routing
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.project_name}-igw"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${var.project_name}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security group for the web services
# Ingress: TCP 443 and TCP 80 from anywhere (0.0.0.0/0)
# -----------------------------------------------------------------------------
resource "aws_security_group" "example" {
  name        = "Example security group"
  description = "Allow HTTPS and HTTP traffic from the internet to the web services"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Allow HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "Example security group"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "security_group_id" {
  description = "ID of the \"Example security group\"."
  value       = aws_security_group.example.id
}

output "security_group_name" {
  description = "Name of the created security group."
  value       = aws_security_group.example.name
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Variables (all with defaults so the configuration is self-contained)
# ---------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region in which to create the test networking stack."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability zone used for the public subnet."
  type        = string
  default     = "us-east-1a"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "ssh_port" {
  description = "Port used for inbound SSH access from within the VPC."
  type        = number
  default     = 22
}

variable "project_name" {
  description = "Name prefix/tag applied to the created resources."
  type        = string
  default     = "example"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

# ---------------------------------------------------------------------------
# Public Subnet
# ---------------------------------------------------------------------------

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = var.availability_zone
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-igw"
  }
}

# ---------------------------------------------------------------------------
# Route Table and Internet Route
# ---------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.project_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security Group: SSH in from within the VPC, all traffic out within the VPC
# ---------------------------------------------------------------------------

resource "aws_security_group" "example" {
  name        = "example"
  description = "Example security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow SSH from within the VPC CIDR only"
    from_port   = var.ssh_port
    to_port     = var.ssh_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "example"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.igw.id
}

output "route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "security_group_id" {
  description = "ID of the 'example' security group."
  value       = aws_security_group.example.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the ECR repository will be created."
  type        = string
  default     = "us-east-1"
}

variable "repository_name" {
  description = "Name of the ECR repository."
  type        = string
  default     = "illumidesk"
}

variable "tags" {
  description = "Tags to apply to the ECR repository."
  type        = map(string)
  default = {
    Name        = "illumidesk-eks"
    Environment = "dev"
  }
}

resource "aws_ecr_repository" "this" {
  name                 = var.repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = var.tags
}

resource "aws_ecr_lifecycle_policy" "this" {
  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days since pushed"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire images when total image count exceeds 30"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 30
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

output "repository_url" {
  description = "URL of the created ECR repository."
  value       = aws_ecr_repository.this.repository_url
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "user_pool_name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "tech-lanches-clientes-pool"
}

variable "user_pool_tag_name" {
  description = "Tag Name for the Cognito User Pool"
  type        = string
  default     = "tech_lanches_clientes_pool"
}

variable "client_name" {
  description = "Name of the User Pool Client"
  type        = string
  default     = "pool-client"
}

variable "secret_name" {
  description = "Name of the Secrets Manager secret"
  type        = string
  default     = "lambda-auth-credentials"
}

variable "username" {
  description = "Default username"
  type        = string
  default     = "techlanches"
}

variable "email" {
  description = "Default email"
  type        = string
  default     = "g12.4soat.fiap@outlook.com"
}

variable "password" {
  description = "Default password"
  type        = string
  default     = "Test1234@"
  sensitive   = true
}

provider "aws" {
  region = var.aws_region
}

resource "aws_cognito_user_pool" "pool" {
  name = var.user_pool_name

  mfa_configuration = "OFF"

  username_configuration {
    case_sensitive = false
  }

  auto_verified_attributes = ["email"]

  alias_attributes = ["email", "preferred_username"]

  tags = {
    Name = var.user_pool_tag_name
  }
}

resource "aws_cognito_user_pool_client" "client" {
  name         = var.client_name
  user_pool_id = aws_cognito_user_pool.pool.id

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH"
  ]
}

resource "aws_secretsmanager_secret" "secret" {
  name                    = var.secret_name
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "secret_version" {
  secret_id = aws_secretsmanager_secret.secret.id

  secret_string = jsonencode({
    region       = var.aws_region
    user_pool_id = aws_cognito_user_pool.pool.id
    client_id    = aws_cognito_user_pool_client.client.id
    username     = var.username
    email        = var.email
    password     = var.password
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the networking stack into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "Availability zones to use for the subnets. Defaults to the first two available zones in the region."
  type        = list(string)
  default     = []
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets. Each subnet is placed in an availability zone in round-robin order."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  effective_azs = length(var.availability_zones) > 0 ? var.availability_zones : slice(data.aws_availability_zones.available.names, 0, 2)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  count = length(var.subnet_cidr_blocks)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_blocks[count.index]
  availability_zone = local.effective_azs[count.index % length(local.effective_azs)]

  tags = {
    Name = "main-subnet-${count.index}"
  }
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "subnet_ids" {
  description = "IDs of the created subnets."
  value       = aws_subnet.main[*].id
}

output "subnet_availability_zones" {
  description = "Availability zones assigned to the created subnets."
  value       = aws_subnet.main[*].availability_zone
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_api_gateway_rest_api" "HelloWorldAPI" {
  name        = "HelloWorldAPI"
  description = "API Gateway for Hello World Lambda"
}

resource "aws_api_gateway_resource" "hello" {
  rest_api_id = aws_api_gateway_rest_api.HelloWorldAPI.id
  parent_id   = aws_api_gateway_rest_api.HelloWorldAPI.root_resource_id
  path_part   = "hello"
}

resource "aws_api_gateway_method" "any" {
  rest_api_id   = aws_api_gateway_rest_api.HelloWorldAPI.id
  resource_id   = aws_api_gateway_resource.hello.id
  http_method   = "ANY"
  authorization = "NONE"
}

resource "aws_api_gateway_deployment" "example" {
  rest_api_id = aws_api_gateway_rest_api.HelloWorldAPI.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.hello.id,
      aws_api_gateway_method.any.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.any,
  ]
}

resource "aws_api_gateway_stage" "example" {
  deployment_id = aws_api_gateway_deployment.example.id
  rest_api_id   = aws_api_gateway_rest_api.HelloWorldAPI.id
  stage_name    = "prod"
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for the SQS queues and KMS key."
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "sqs" {
  description             = "Customer managed KMS key for production SQS queues"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSQSQueueEncryption"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Environment = "production"
  }
}

resource "aws_sqs_queue" "test_sqs" {
  name                              = "test-sqs"
  delay_seconds                     = 90
  max_message_size                  = 2048
  message_retention_seconds         = 86400
  receive_wait_time_seconds         = 10
  kms_master_key_id                 = aws_kms_key.sqs.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Environment = "production"
  }
}

resource "aws_sqs_queue" "test_sqs1" {
  name                              = "test-sqs1"
  delay_seconds                     = 90
  max_message_size                  = 2048
  message_retention_seconds         = 86400
  receive_wait_time_seconds         = 10
  kms_master_key_id                 = aws_kms_key.sqs.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Environment = "production"
  }
}

output "sqs_queue_urls" {
  description = "URLs of the created SQS queues."
  value = {
    test_sqs  = aws_sqs_queue.test_sqs.url
    test_sqs1 = aws_sqs_queue.test_sqs1.url
  }
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used for SQS encryption."
  value       = aws_kms_key.sqs.arn
}

## Description

This Terraform configuration provisions an S3 bucket for storing document I/O files with the following design:

- **Provider/Region:** AWS provider configured with a variable-driven region that defaults to `us-east-1`.
- **Bucket naming:** A `random_integer` (range `1`–`50000`) is generated and prefixed to a base name variable (`doc-io-files` by default), producing a globally unique bucket name such as `18342-doc-io-files`.
- **Force destroy:** Controlled by a boolean variable (`force_destroy_bucket`) that defaults to `true`, wiring directly into the S3 bucket's `force_destroy` argument.
- **Public access blocking:** A dedicated `aws_s3_bucket_public_access_block` blocks public ACLs, ignores public ACLs, blocks public policies, and restricts public buckets.
- **Default encryption:** A customer-managed KMS key (with rotation enabled, a descriptive alias, and a key policy that grants the deploying account root full control and explicitly permits the target account to use the key for S3) is used for default SSE-KMS encryption via `aws_s3_bucket_server_side_encryption_configuration` (with bucket keys enabled to reduce KMS costs).
- **Bucket policy:** Grants `s3:*` on both the bucket ARN and `bucket/*` to the root of a parameterized AWS account ID (default `566373416292`), with an explicit dependency on the public access block so the policy applies cleanly.
- **Outputs:** Expose the generated bucket name, bucket ARN, and KMS key ARN for downstream consumption.

No IAM roles are required because access is granted via the bucket policy and KMS key policy to account principals, and the Terraform execution identity must have permissions to create S3/KMS resources.

```iac_template
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

########################################
# Variables
########################################

variable "aws_region" {
  description = "AWS region in which to deploy the S3 bucket and KMS key."
  type        = string
  default     = "us-east-1"
}

variable "base_bucket_name" {
  description = "Base name for the S3 bucket; a random integer prefix is prepended."
  type        = string
  default     = "doc-io-files"
}

variable "force_destroy_bucket" {
  description = "When true, the bucket will be destroyed even if it contains objects."
  type        = bool
  default     = true
}

variable "aws_account_id" {
  description = "AWS account ID granted full S3 access to the bucket via the bucket policy."
  type        = string
  default     = "566373416292"
}

########################################
# Data sources / Randomized naming
########################################

data "aws_caller_identity" "current" {}

resource "random_integer" "bucket_suffix" {
  min = 1
  max = 50000
}

locals {
  bucket_name = "${random_integer.bucket_suffix.result}-${var.base_bucket_name}"
}

########################################
# KMS key for SSE-KMS default encryption
########################################

resource "aws_kms_key" "s3_cmk" {
  description             = "Customer-managed KMS key for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountFullAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowTargetAccountToUseKeyForS3"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.aws_account_id}:root"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
          "kms:ReEncrypt*",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "s3_cmk_alias" {
  name          = "alias/${local.bucket_name}-s3"
  target_key_id = aws_kms_key.s3_cmk.key_id
}

########################################
# S3 bucket
########################################

resource "aws_s3_bucket" "doc_io_files" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy_bucket

  tags = {
    Name        = local.bucket_name
    Purpose     = "Document I/O Files"
    ManagedBy   = "Terraform"
  }
}

resource "aws_s3_bucket_public_access_block" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_cmk.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSpecifiedAccountFullS3Access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.aws_account_id}:root"
        }
        Action   = "s3:*"
        Resource = [
          aws_s3_bucket.doc_io_files.arn,
          "${aws_s3_bucket.doc_io_files.arn}/*"
        ]
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.doc_io_files]
}

########################################
# Outputs
########################################

output "bucket_name" {
  description = "The generated name of the S3 bucket."
  value       = aws_s3_bucket.doc_io_files.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.doc_io_files.arn
}

output "kms_key_arn" {
  description = "The ARN of the customer-managed KMS key used for default encryption."
  value       = aws_kms_key.s3_cmk.arn
}
```

# Terraform Remote State Backend (S3 + DynamoDB Lock + KMS)

## Description

This configuration provisions a complete, secure Terraform remote state backend:

**Core resources**

| Resource | Purpose |
|---|---|
| `aws_kms_key` + `aws_kms_alias` | Customer‑managed KMS key with automatic rotation, used for encrypting both the state objects and the lock table. Key policy grants the account root full control plus scoped use by the S3 and DynamoDB service principals. |
| `aws_s3_bucket` | Versioned state bucket with an auto‑generated globally unique name derived from account ID + region (or supplied explicitly). |
| `aws_s3_bucket_versioning` | Enables versioning so state history is recoverable. |
| `aws_s3_bucket_server_side_encryption_configuration` | Forces SSE‑KMS with the CMK (and S3 Bucket Keys enabled to reduce KMS request costs). |
| `aws_s3_bucket_public_access_block` | Blocks all four public‑access vectors (ACLs and policies). |
| `aws_s3_bucket_ownership_controls` | `BucketOwnerEnforced` — disables ACLs entirely. |
| `aws_s3_bucket_policy` | Deny‑only policy rejecting any non‑TLS (`aws:SecureTransport = false`) requests. |
| `aws_s3_bucket_lifecycle_configuration` | Expires noncurrent versions after 90 days and aborts stale multipart uploads after 7 days. |
| `aws_dynamodb_table` | PAY_PER_REQUEST table with a **string hash key named `LockID`** for native Terraform S3 backend state locking, KMS‑encrypted, PITR enabled. |
| `aws_iam_policy` | Ready‑to‑attach policy granting least‑privilege access to the bucket, lock table, and CMK (for CI/CD roles). |

**Providers / inputs:** `hashicorp/aws ~> 5.0`, hard‑pinned region `us-east-1` via a variable with a default. All variables carry defaults, so `terraform apply` works with no `tfvars`.

**Outputs:** bucket name, table name, CMK ARN, and a ready‑to‑paste `backend "s3"` block for consuming stacks.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region in which the remote state backend is created."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used to name the state resources."
  type        = string
  default     = "terraform"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,20}$", var.name_prefix))
    error_message = "name_prefix must be lowercase alphanumeric/hyphen and <= 21 characters."
  }
}

variable "bucket_name" {
  description = "Explicit globally-unique S3 bucket name. Leave null to auto-generate one."
  type        = string
  default     = null
}

variable "dynamodb_table_name" {
  description = "Explicit DynamoDB lock table name. Leave null to auto-generate one."
  type        = string
  default     = null
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (7-30 days) before the KMS key is deleted."
  type        = number
  default     = 30

  validation {
    condition     = var.kms_deletion_window_in_days >= 7 && var.kms_deletion_window_in_days <= 30
    error_message = "kms_deletion_window_in_days must be between 7 and 30."
  }
}

variable "force_destroy" {
  description = "Allow the state bucket to be destroyed even if it still contains objects."
  type        = bool
  default     = false
}

variable "dynamodb_deletion_protection" {
  description = "Enable DynamoDB deletion protection on the lock table."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to every taggable resource via the provider default_tags block."
  type        = map(string)
  default = {
    ManagedBy   = "Terraform"
    Purpose     = "TerraformRemoteState"
    Environment = "shared"
  }
}

# ---------------------------------------------------------------------------
# Data sources / locals
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id          = data.aws_caller_identity.current.account_id
  partition           = data.aws_partition.current.partition
  bucket_name         = coalesce(var.bucket_name, "${var.name_prefix}-tfstate-${local.account_id}-${var.aws_region}")
  dynamodb_table_name = coalesce(var.dynamodb_table_name, "${var.name_prefix}-tfstate-lock")
}

# ---------------------------------------------------------------------------
# KMS customer managed key (encrypts state objects + lock table)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountFullControl"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowDynamoDBServiceUse"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["dynamodb.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "tfstate" {
  description             = "CMK for Terraform remote state bucket and DynamoDB lock table"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
}

resource "aws_kms_alias" "tfstate" {
  name          = "alias/${var.name_prefix}-tfstate"
  target_key_id = aws_kms_key.tfstate.key_id
}

# ---------------------------------------------------------------------------
# S3 state bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "tfstate" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
}

resource "aws_s3_bucket_versioning" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.tfstate.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "tfstate_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.tfstate.arn,
      "${aws_s3_bucket.tfstate.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyUnencryptedObjectUploads"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.tfstate.arn}/*"]

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }
}

resource "aws_s3_bucket_policy" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id
  policy = data.aws_iam_policy_document.tfstate_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.tfstate]
}

resource "aws_s3_bucket_lifecycle_configuration" "tfstate" {
  bucket = aws_s3_bucket.tfstate.id

  rule {
    id     = "state-retention"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.tfstate]
}

# ---------------------------------------------------------------------------
# DynamoDB state locking table (string hash key "LockID")
# ---------------------------------------------------------------------------

resource "aws_dynamodb_table" "tfstate_lock" {
  name         = local.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.tfstate.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = var.dynamodb_deletion_protection
}

# ---------------------------------------------------------------------------
# IAM policy granting access to the remote state backend
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "state_access" {
  statement {
    sid    = "ListStateBucket"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
    ]

    resources = [aws_s3_bucket.tfstate.arn]
  }

  statement {
    sid    = "ReadWriteStateObjects"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = ["${aws_s3_bucket.tfstate.arn}/*"]
  }

  statement {
    sid    = "StateLocking"
    effect = "Allow"

    actions = [
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:UpdateItem",
      "dynamodb:DeleteItem",
      "dynamodb:DescribeTable",
    ]

    resources = [aws_dynamodb_table.tfstate_lock.arn]
  }

  statement {
    sid    = "StateEncryption"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.tfstate.arn]
  }
}

resource "aws_iam_policy" "state_access" {
  name        = "${var.name_prefix}-tfstate-access"
  description = "Allows read/write access to the Terraform remote state bucket, lock table and CMK."
  policy      = data.aws_iam_policy_document.state_access.json
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "state_bucket_name" {
  description = "Name of the S3 bucket holding Terraform state."
  value       = aws_s3_bucket.tfstate.id
}

output "state_bucket_arn" {
  description = "ARN of the S3 state bucket."
  value       = aws_s3_bucket.tfstate.arn
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB state locking table."
  value       = aws_dynamodb_table.tfstate_lock.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB state locking table."
  value       = aws_dynamodb_table.tfstate_lock.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS CMK used for state encryption."
  value       = aws_kms_key.tfstate.arn
}

output "kms_key_alias" {
  description = "Alias of the KMS CMK used for state encryption."
  value       = aws_kms_alias.tfstate.name
}

output "state_access_policy_arn" {
  description = "ARN of the IAM policy granting access to the state backend."
  value       = aws_iam_policy.state_access.arn
}

output "backend_configuration" {
  description = "Paste this backend block into the Terraform configurations that will use this state backend."
  value       = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.tfstate.id}"
        key            = "env:/terraform.tfstate"
        region         = "${var.aws_region}"
        dynamodb_table = "${aws_dynamodb_table.tfstate_lock.name}"
        encrypt        = true
        kms_key_id     = "${aws_kms_key.tfstate.arn}"
      }
    }
  EOT
}
```

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "sns_key" {
  description             = "KMS key for SNS incident-response topic encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SNS service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow EventBridge to use the key"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns_key_alias" {
  name          = "alias/incident-response-sns"
  target_key_id = aws_kms_key.sns_key.key_id
}

resource "aws_sns_topic" "incident_response" {
  name              = "incident-response"
  kms_master_key_id = aws_kms_key.sns_key.arn
}

resource "aws_sns_topic_policy" "incident_response" {
  arn = aws_sns_topic.incident_response.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "__default_policy_ID"
    Statement = [
      {
        Sid    = "__default_statement_ID"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "sns:Subscribe",
          "sns:SetTopicAttributes",
          "sns:RemovePermission",
          "sns:Receive",
          "sns:Publish",
          "sns:ListSubscriptionsByTopic",
          "sns:GetTopicAttributes",
          "sns:DeleteTopic",
          "sns:AddPermission"
        ]
        Resource = aws_sns_topic.incident_response.arn
        Condition = {
          StringEquals = {
            "AWS:SourceOwner" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid    = "AllowAWSEvents"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.incident_response.arn
      }
    ]
  })
}

output "sns_topic_arn" {
  value = aws_sns_topic.incident_response.arn
}

output "kms_key_arn" {
  value = aws_kms_key.sns_key.arn
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_service_linked_role" "es" {
  aws_service_name = "es.amazonaws.com"
}

resource "aws_cloudwatch_log_resource_policy" "es_log_publishing" {
  policy_name = "elasticsearch-log-publishing-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "es.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:PutLogEventsBatch"
        ]
        Resource = "arn:aws:logs:*:*:log-group:*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

resource "aws_cognito_user_pool" "identity_pool" {
  name = "identity pool"
}

resource "aws_iam_role" "user_group_role" {
  name = "user-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = "us-east-1:12345678-dead-beef-cafe-123456790ab"
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

resource "aws_cognito_user_group" "user_group" {
  name         = "user-group"
  user_pool_id = aws_cognito_user_pool.identity_pool.id
  description  = "Managed by Terraform"
  precedence   = 42
  role_arn     = aws_iam_role.user_group_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region in which the DynamoDB tables will be created."
  type        = string
  default     = "us-east-1"
}

variable "common_tags" {
  description = "Common tags applied via provider default_tags for both provider aliases."
  type        = map(string)
  default = {
    Project     = "multi-provider-tags-test"
    ManagedBy   = "Terraform"
    Environment = "test"
  }
}

############################################
# Provider configuration (standard / default)
############################################

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = merge(
      var.common_tags,
      {
        TagSource = "default-provider"
      }
    )
  }
}

############################################
# Provider configuration (alternate alias: alt-tags)
############################################

provider "aws" {
  alias  = "alt-tags"
  region = var.aws_region

  default_tags {
    tags = merge(
      var.common_tags,
      {
        TagSource = "alt-tags-provider"
      }
    )
  }
}

############################################
# DynamoDB table managed by the default provider
############################################

resource "aws_dynamodb_table" "basic" {
  name         = "default-and-alternate-tags-module-basic"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  tags = {
    TableVariant = "basic"
  }
}

############################################
# DynamoDB table managed by the alternate provider (alt-tags)
############################################

resource "aws_dynamodb_table" "alternate" {
  provider     = aws.alt-tags
  name         = "default-and-alternate-tags-module-alternate"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  tags = {
    TableVariant = "alternate"
  }
}

############################################
# Outputs
############################################

output "basic_table_name" {
  description = "Name of the DynamoDB table managed by the default provider."
  value       = aws_dynamodb_table.basic.name
}

output "basic_table_arn" {
  description = "ARN of the DynamoDB table managed by the default provider."
  value       = aws_dynamodb_table.basic.arn
}

output "alternate_table_name" {
  description = "Name of the DynamoDB table managed by the alt-tags provider alias."
  value       = aws_dynamodb_table.alternate.name
}

output "alternate_table_arn" {
  description = "ARN of the DynamoDB table managed by the alt-tags provider alias."
  value       = aws_dynamodb_table.alternate.arn
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

##############################################################################
# Variables
##############################################################################

variable "aws_region" {
  description = "AWS region in which the API Gateway REST API will be created."
  type        = string
  default     = "us-east-1"
}

variable "api_name" {
  description = "Name of the API Gateway REST API used for mock testing."
  type        = string
  default     = "terraform-api-gateway-example"
}

variable "stage_name" {
  description = "Deployment stage name for the mock REST API."
  type        = string
  default     = "test"
}

variable "resource_path_part" {
  description = "Path part created off the API root resource."
  type        = string
  default     = "movies"
}

variable "mock_status_code" {
  description = "HTTP status code returned by the mock integration and method response."
  type        = string
  default     = "200"
}

variable "mock_response_message" {
  description = "Message returned in the mock JSON response body."
  type        = string
  default     = "Hello from the movies API!"
}

##############################################################################
# REST API
##############################################################################

resource "aws_api_gateway_rest_api" "this" {
  name        = var.api_name
  description = "Mock REST API for testing web endpoint responses (no backend integration)."

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = {
    Name    = var.api_name
    Purpose = "mock-endpoint-testing"
  }
}

##############################################################################
# /movies resource
##############################################################################

resource "aws_api_gateway_resource" "movies" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = var.resource_path_part
}

##############################################################################
# GET method (no authorization)
##############################################################################

resource "aws_api_gateway_method" "movies_get" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  resource_id   = aws_api_gateway_resource.movies.id
  http_method   = "GET"
  authorization = "NONE"
}

##############################################################################
# MOCK integration: request template sets statusCode 200
##############################################################################

resource "aws_api_gateway_integration" "movies_get_mock" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method

  type = "MOCK"

  # The mock integration returns the status code supplied in this template.
  request_templates = {
    "application/json" = jsonencode({
      statusCode = tonumber(var.mock_status_code)
    })
  }
}

##############################################################################
# 200 method response
##############################################################################

resource "aws_api_gateway_method_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = var.mock_status_code

  response_models = {
    "application/json" = "Empty"
  }
}

##############################################################################
# Integration response: 200 -> JSON body
##############################################################################

resource "aws_api_gateway_integration_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = aws_api_gateway_method_response.movies_get_200.status_code

  response_templates = {
    "application/json" = jsonencode({
      message = var.mock_response_message
    })
  }

  depends_on = [aws_api_gateway_integration.movies_get_mock]
}

##############################################################################
# Deployment + stage so the mock endpoint is invokable
##############################################################################

resource "aws_api_gateway_deployment" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.movies.id,
      aws_api_gateway_method.movies_get.id,
      aws_api_gateway_integration.movies_get_mock.id,
      aws_api_gateway_method_response.movies_get_200.id,
      aws_api_gateway_integration_response.movies_get_200.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "this" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  deployment_id = aws_api_gateway_deployment.this.id
  stage_name    = var.stage_name

  tags = {
    Name    = "${var.api_name}-${var.stage_name}"
    Purpose = "mock-endpoint-testing"
  }
}

##############################################################################
# Outputs
##############################################################################

output "api_id" {
  description = "ID of the mock REST API."
  value       = aws_api_gateway_rest_api.this.id
}

output "api_arn" {
  description = "ARN of the mock REST API."
  value       = aws_api_gateway_rest_api.this.arn
}

output "stage_invoke_url" {
  description = "Base invoke URL for the deployed stage."
  value       = aws_api_gateway_stage.this.invoke_url
}

output "movies_endpoint_url" {
  description = "Full URL of the mock GET /movies endpoint."
  value       = "${aws_api_gateway_stage.this.invoke_url}/${var.resource_path_part}"
}

# Terraform Configuration: KMS CMK + Alias (Test)

## Description of the program

This Terraform program provisions a **customer managed KMS key** and a **KMS alias** for low-cost test usage:

1. **Provider / region** – The `hashicorp/aws` provider is pinned to `~> 5.0` and configured with a `us-east-1` region supplied via a variable with a default value.
2. **Current caller identity** – The `aws_caller_identity` data source resolves the ARN of the principal running Terraform, which is used as the sole principal in the key policy.
3. **Key policy** – An `aws_iam_policy_document` grants `kms:*` on `"*"` exclusively to the current caller's ARN (a single, tightly scoped statement — no other principals, no cross-account access).
4. **KMS CMK** – `aws_kms_key` is created with a configurable `deletion_window_in_days` defaulting to **7** (the minimum, which avoids the cost of keeping an unused key pending deletion), key rotation enabled, and the policy document attached.
5. **KMS alias** – `aws_kms_alias` targets the key via `key_id` and is named `alias/${var.alias_name}`, where `var.alias_name` defaults to `"kms-cmk-example"`.
6. **Outputs** – Key ID/ARN, alias name/ARN and the caller identity are exported for verification.

No IAM roles are required: the key policy uses the *current caller's existing IAM identity* (the same identity Terraform runs as), rather than creating a new role, avoiding any need for `iam:PassRole` or trust-policy bootstrapping.

```iac_template
##############################################################################
# Terraform & Provider Configuration
##############################################################################

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

##############################################################################
# Variables (all with defaults so the configuration is deployable as-is)
##############################################################################

variable "aws_region" {
  description = "AWS region in which the KMS key and alias will be created."
  type        = string
  default     = "us-east-1"
}

variable "alias_name" {
  description = "Alias name (without the 'alias/' prefix) attached to the KMS CMK."
  type        = string
  default     = "kms-cmk-example"

  validation {
    condition     = !startswith(var.alias_name, "alias/")
    error_message = "Provide only the alias name; the 'alias/' prefix is added automatically."
  }
}

variable "deletion_window_in_days" {
  description = "Number of days the KMS key waits before deletion (valid range 7-30)."
  type        = number
  default     = 7

  validation {
    condition     = var.deletion_window_in_days >= 7 && var.deletion_window_in_days <= 30
    error_message = "The deletion window must be between 7 and 30 days."
  }
}

variable "key_description" {
  description = "Description used for the KMS customer managed key."
  type        = string
  default     = "Customer managed KMS key for testing purposes (7-day deletion window)"
}

variable "enable_key_rotation" {
  description = "Whether automatic annual rotation of the KMS key material is enabled."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags applied to the KMS key and alias."
  type        = map(string)
  default = {
    Environment = "test"
    Purpose     = "kms-cmk-example"
    ManagedBy   = "Terraform"
  }
}

##############################################################################
# Data Sources
##############################################################################

# The IAM identity executing this Terraform run. Used as the sole principal
# of the KMS key policy so that no additional IAM role is required.
data "aws_caller_identity" "current" {}

##############################################################################
# KMS Key Policy - full KMS permissions for the current caller only
##############################################################################

data "aws_iam_policy_document" "kms_cmk_policy" {
  statement {
    sid    = "EnableFullKMSAccessForCurrentCaller"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }
}

##############################################################################
# KMS Customer Managed Key (CMK)
##############################################################################

resource "aws_kms_key" "cmk" {
  description             = var.key_description
  deletion_window_in_days = var.deletion_window_in_days
  enable_key_rotation     = var.enable_key_rotation
  policy                  = data.aws_iam_policy_document.kms_cmk_policy.json
  tags                    = var.tags
}

##############################################################################
# KMS Key Alias -> "alias/" + var.alias_name
##############################################################################

resource "aws_kms_alias" "cmk_alias" {
  name          = "alias/${var.alias_name}"
  target_key_id = aws_kms_key.cmk.key_id
}

##############################################################################
# Outputs
##############################################################################

output "kms_key_id" {
  description = "ID of the created KMS customer managed key."
  value       = aws_kms_key.cmk.key_id
}

output "kms_key_arn" {
  description = "ARN of the created KMS customer managed key."
  value       = aws_kms_key.cmk.arn
}

output "kms_alias_name" {
  description = "Fully qualified name of the KMS key alias."
  value       = aws_kms_alias.cmk_alias.name
}

output "kms_alias_arn" {
  description = "ARN of the KMS key alias."
  value       = aws_kms_alias.cmk_alias.arn
}

output "kms_policy_principal" {
  description = "IAM identity granted kms:* on the CMK (the current caller)."
  value       = data.aws_caller_identity.current.arn
}
```

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

############################################
# Variables (all with defaults)
############################################

variable "primary_region" {
  description = "Region for the primary (North Virginia) provider"
  type        = string
  default     = "us-east-1"
}

variable "secondary_region" {
  description = "Region for the secondary (Mumbai) provider"
  type        = string
  default     = "ap-south-1"
}

variable "primary_vpc_cidr" {
  description = "CIDR block for the North Virginia VPC"
  type        = string
  default     = "10.1.0.0/16"
}

variable "secondary_vpc_cidr" {
  description = "CIDR block for the Mumbai VPC"
  type        = string
  default     = "10.2.0.0/16"
}

############################################
# Provider configurations (multi-region)
############################################

provider "aws" {
  alias  = "us-east-nv"
  region = var.primary_region

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "N.Virginia"
    }
  }
}

provider "aws" {
  alias  = "ap-south-mumbai"
  region = var.secondary_region

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "Mumbai"
    }
  }
}

############################################
# VPC - North Virginia (us-east-1)
############################################

resource "aws_vpc" "north_virginia" {
  provider = aws.us-east-nv

  cidr_block           = var.primary_vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "North-Virginia-VPC"
  }
}

############################################
# VPC - Mumbai (ap-south-1)
############################################

resource "aws_vpc" "mumbai" {
  provider = aws.ap-south-mumbai

  cidr_block           = var.secondary_vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "Mumbai-VPC"
  }
}

############################################
# Outputs
############################################

output "north_virginia_vpc_id" {
  description = "ID of the North Virginia VPC"
  value       = aws_vpc.north_virginia.id
}

output "north_virginia_vpc_arn" {
  description = "ARN of the North Virginia VPC"
  value       = aws_vpc.north_virginia.arn
}

output "mumbai_vpc_id" {
  description = "ID of the Mumbai VPC"
  value       = aws_vpc.mumbai.id
}

output "mumbai_vpc_arn" {
  description = "ARN of the Mumbai VPC"
  value       = aws_vpc.mumbai.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Use the default VPC for the security groups
data "aws_vpc" "default" {
  default = true
}

# Security group allowing outbound TCP traffic on port 10000
resource "aws_security_group" "allow_tcp" {
  name        = "allow_tcp"
  description = "Allow TCP traffic"
  vpc_id      = data.aws_vpc.default.id

  egress {
    from_port   = 10000
    to_port     = 10000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Security group allowing outbound UDP traffic on port 10000
resource "aws_security_group" "allow_udp" {
  name        = "allow_udp"
  description = "Allow UDP traffic"
  vpc_id      = data.aws_vpc.default.id

  egress {
    from_port   = 10000
    to_port     = 10000
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Security group allowing outbound ICMP traffic
# Note: ICMP does not use ports. The requirement specified "port 10000",
# but AWS interprets ICMP from_port/to_port as ICMP type/code.
# To ensure deployability, we use -1 for all ICMP types (equivalent to all ICMP traffic).
resource "aws_security_group" "allow_icmp" {
  name        = "allow_icmp"
  description = "Allow ICMP traffic"
  vpc_id      = data.aws_vpc.default.id

  egress {
    from_port   = -1
    to_port     = -1
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Security group allowing all outbound traffic
resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow ALL traffic"
  vpc_id      = data.aws_vpc.default.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region for the backend resources"
  type        = string
  default     = "us-east-1"
}

variable "bucket_prefix" {
  description = "Prefix for the S3 bucket name"
  type        = string
  default     = "terraform-state"
}

data "aws_caller_identity" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

resource "aws_kms_key" "terraform_state" {
  description             = "KMS key for Terraform state bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-state"
  target_key_id = aws_kms_key.terraform_state.key_id
}

resource "aws_s3_bucket" "terraform_state" {
  bucket = "${var.bucket_prefix}-${random_id.bucket_suffix.hex}"

  tags = {
    Name        = "Terraform State Bucket"
    Environment = "management"
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_dynamodb_table" "terraform_lock" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = {
    Name        = "Terraform State Lock Table"
    Environment = "management"
  }
}

output "s3_bucket_name" {
  value       = aws_s3_bucket.terraform_state.bucket
  description = "Name of the S3 bucket for Terraform state"
}

output "s3_bucket_arn" {
  value       = aws_s3_bucket.terraform_state.arn
  description = "ARN of the S3 bucket for Terraform state"
}

output "dynamodb_table_name" {
  value       = aws_dynamodb_table.terraform_lock.name
  description = "Name of the DynamoDB table for state locking"
}

output "kms_key_arn" {
  value       = aws_kms_key.terraform_state.arn
  description = "ARN of the KMS key used for state bucket encryption"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

####################################################################
# Variables
####################################################################

variable "aws_region" {
  description = "AWS region in which the provider operates (used to create the IAM resources)."
  type        = string
  default     = "us-east-1"
}

variable "powerscale_regions" {
  description = "List of AWS regions in which PowerScale node runtimes are allowed to assign private IP addresses to EC2 network interfaces. Use [\"*\"] to allow all regions."
  type        = list(string)
  default     = ["*"]

  validation {
    condition     = length(var.powerscale_regions) > 0
    error_message = "At least one region (or \"*\") must be supplied in powerscale_regions."
  }
}

variable "tags" {
  description = "Additional tags applied to all created IAM resources."
  type        = map(string)
  default     = {}
}

####################################################################
# Data sources
####################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

####################################################################
# Locals: account-prefixed names and scoped network interface ARNs
####################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # Dynamic prefix driven by the current AWS account ID
  name_prefix = "${local.account_id}-powerscale-node-runtime"

  # One EC2 network interface ARN per configured region ("*" expands to all regions)
  network_interface_arns = [
    for region in var.powerscale_regions :
    "arn:${local.partition}:ec2:${region}:${local.account_id}:network-interface/*"
  ]

  common_tags = merge(
    {
      Name        = local.name_prefix
      ManagedBy   = "Terraform"
      Application = "PowerScaleNodeRuntime"
    },
    var.tags
  )
}

####################################################################
# IAM policy: allow assigning private IP addresses to ENIs
####################################################################

resource "aws_iam_policy" "powerscale_node_runtime" {
  name        = "${local.name_prefix}-policy"
  description = "Allows PowerScale node runtimes on EC2 to assign private IP addresses to network interfaces in the configured regions."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AssignPrivateIpAddressesToNetworkInterfaces"
        Effect   = "Allow"
        Action   = ["ec2:AssignPrivateIpAddresses"]
        Resource = local.network_interface_arns
      }
    ]
  })

  tags = local.common_tags
}

####################################################################
# IAM role: assumable by the EC2 service
####################################################################

resource "aws_iam_role" "powerscale_node_runtime" {
  name        = "${local.name_prefix}-role"
  description = "Execution role for EC2 instances managing PowerScale node runtime operations."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

####################################################################
# Attach the custom policy to the role
####################################################################

resource "aws_iam_role_policy_attachment" "powerscale_node_runtime" {
  role       = aws_iam_role.powerscale_node_runtime.name
  policy_arn = aws_iam_policy.powerscale_node_runtime.arn
}

####################################################################
# Instance profile for EC2 instances
####################################################################

resource "aws_iam_instance_profile" "powerscale_node_runtime" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.powerscale_node_runtime.name

  tags = local.common_tags
}

####################################################################
# Outputs
####################################################################

output "powerscale_node_runtime_policy_arn" {
  description = "ARN of the account-prefixed PowerScale node runtime IAM policy."
  value       = aws_iam_policy.powerscale_node_runtime.arn
}

output "powerscale_node_runtime_policy_name" {
  description = "Name of the account-prefixed PowerScale node runtime IAM policy."
  value       = aws_iam_policy.powerscale_node_runtime.name
}

output "powerscale_node_runtime_role_arn" {
  description = "ARN of the account-prefixed PowerScale node runtime IAM role."
  value       = aws_iam_role.powerscale_node_runtime.arn
}

output "powerscale_node_runtime_role_name" {
  description = "Name of the account-prefixed PowerScale node runtime IAM role."
  value       = aws_iam_role.powerscale_node_runtime.name
}

output "powerscale_node_runtime_instance_profile_name" {
  description = "Name of the account-prefixed PowerScale node runtime IAM instance profile."
  value       = aws_iam_instance_profile.powerscale_node_runtime.name
}

output "powerscale_node_runtime_instance_profile_arn" {
  description = "ARN of the account-prefixed PowerScale node runtime IAM instance profile."
  value       = aws_iam_instance_profile.powerscale_node_runtime.arn
}

output "powerscale_node_runtime_scoped_regions" {
  description = "Regions (or \"*\") for which network interface ARNs are permitted in the policy."
  value       = var.powerscale_regions
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

#############################################
# Provider
#############################################
provider "aws" {
  region = var.aws_region
}

#############################################
# Variables
#############################################
variable "aws_region" {
  description = "AWS region in which to deploy the VPC and subnets."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Project name used as a prefix for resource naming."
  type        = string
  default     = "tiered-app"
}

variable "environment" {
  description = "Deployment environment (e.g. dev, stage, prod)."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the custom VPC."
  type        = string
  default     = "192.168.0.0/16"
}

variable "subnet_newbits" {
  description = "Number of bits to add to the VPC CIDR prefix when carving subnets (8 => /24 from a /16)."
  type        = number
  default     = 8
}

variable "az_count" {
  description = "Number of availability zones to spread the subnets across."
  type        = number
  default     = 3
}

variable "common_tags" {
  description = "Additional tags merged into every resource."
  type        = map(string)
  default     = {}
}

#############################################
# Data sources
#############################################
data "aws_availability_zones" "available" {
  state = "available"
}

#############################################
# Locals
#############################################
locals {
  # First N AZs in the selected region
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  name_prefix = "${var.project_name}-${var.environment}"

  tags = merge(
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.common_tags
  )

  # Sequential /24 subdivisions of the VPC range:
  #   index 0 -> 192.168.0.0/24  (web)
  #   index 1 -> 192.168.1.0/24  (app)
  #   index 2 -> 192.168.2.0/24  (db)
  #   index 3 -> 192.168.3.0/24  (mgmt)
  cidr_web  = cidrsubnet(var.vpc_cidr, var.subnet_newbits, 0)
  cidr_app  = cidrsubnet(var.vpc_cidr, var.subnet_newbits, 1)
  cidr_db   = cidrsubnet(var.vpc_cidr, var.subnet_newbits, 2)
  cidr_mgmt = cidrsubnet(var.vpc_cidr, var.subnet_newbits, 3)
}

#############################################
# VPC
#############################################
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
    Tier = "network"
  })
}

#############################################
# Internet Gateway
#############################################
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-igw"
    Tier = "public"
  })
}

#############################################
# Subnets (sequential /24 carves)
#############################################
resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.cidr_web
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-web-subnet"
    Tier = "web"
  })
}

resource "aws_subnet" "app" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.cidr_app
  availability_zone = local.azs[1]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-app-subnet"
    Tier = "app"
  })
}

resource "aws_subnet" "db" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.cidr_db
  availability_zone = local.azs[2]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-subnet"
    Tier = "db"
  })
}

resource "aws_subnet" "mgmt" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.cidr_mgmt
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-mgmt-subnet"
    Tier = "mgmt"
  })
}

#############################################
# NAT Gateway (for private app/db tiers)
#############################################
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nat-eip"
    Tier = "public"
  })

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.web.id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nat"
    Tier = "public"
  })

  depends_on = [aws_internet_gateway.igw]
}

#############################################
# Route Tables
#############################################
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-public-rt"
    Tier = "public"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-rt"
    Tier = "private"
  })
}

#############################################
# Route Table Associations
#############################################
resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "mgmt" {
  subnet_id      = aws_subnet.mgmt.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "app" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db" {
  subnet_id      = aws_subnet.db.id
  route_table_id = aws_route_table.private.id
}

#############################################
# Outputs
#############################################
output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones_used" {
  description = "Availability zones used for the subnet layout."
  value       = local.azs
}

output "subnet_ids" {
  description = "Map of tier name to subnet ID."
  value = {
    web  = aws_subnet.web.id
    app  = aws_subnet.app.id
    db   = aws_subnet.db.id
    mgmt = aws_subnet.mgmt.id
  }
}

output "subnet_cidr_blocks" {
  description = "Map of tier name to subnet CIDR block."
  value = {
    web  = aws_subnet.web.cidr_block
    app  = aws_subnet.app.cidr_block
    db   = aws_subnet.db.cidr_block
    mgmt = aws_subnet.mgmt.cidr_block
  }
}

output "nat_gateway_public_ip" {
  description = "Elastic IP address of the NAT gateway used by private tiers."
  value       = aws_eip.nat.public_ip
}

## Description

This Terraform configuration provisions an IAM role and a matching EC2 instance profile designed for attachment to EC2 instances.

**Core behavior:**

1. **Partition-aware trust policy** — It uses the `aws_partition` data source to discover the current partition's DNS suffix and constructs the EC2 service principal dynamically as `ec2.<dns_suffix>`. This resolves correctly in every partition:
   - `aws` → `ec2.amazonaws.com`
   - `aws-us-gov` → `ec2.amazonaws.com`
   - `aws-cn` → `ec2.amazonaws.com.cn`

   The trust policy allows `sts:AssumeRole` only for that principal, with an optional `sts:ExternalId` condition for confused-deputy protection.

2. **Instance profile** — An `aws_iam_instance_profile` is created and bound to the role so it can be referenced from `aws_instance.iam_instance_profile` or a launch template.

3. **Flexible policy attachment** —
   - **Inline policies:** supplied as a map of `name => JSON policy document string`. Each entry produces one `aws_iam_role_policy`.
   - **Managed policies:** supplied as a list of ARNs. Each entry produces one `aws_iam_role_policy_attachment`. Duplicates are de-duplicated with `toset()`.

4. **Optional hardening / governance knobs:** path, max session duration (with validation), permissions boundary, force-detach on destroy, and tag propagation to both the role and instance profile.

**IAM entities created:** one role, one instance profile, N inline policies, M managed policy attachments (plus the read-only `aws_partition` data lookup). No IAM user, group, or key material is created.

All variables have defaults, so the module deploys with just a provider block, and the output values expose the role and instance-profile names/ARNs for downstream consumption.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region

  default_tags {
    tags = var.tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region to deploy the IAM resources into. IAM is global, but a region is required by the provider."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role to create for EC2 instances."
  type        = string
  default     = "ec2-instance-role"
}

variable "role_description" {
  description = "Description applied to the IAM role."
  type        = string
  default     = "IAM role assumed by EC2 instances to access AWS services."
}

variable "role_path" {
  description = "IAM path for the role and instance profile."
  type        = string
  default     = "/"
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role. Between 3600 and 43200."
  type        = number
  default     = 3600

  validation {
    condition     = var.max_session_duration >= 3600 && var.max_session_duration <= 43200
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }
}

variable "permissions_boundary_arn" {
  description = "Optional ARN of a permissions boundary policy to attach to the role."
  type        = string
  default     = null
}

variable "force_detach_policies" {
  description = "Whether to force detachment of policies when destroying the role."
  type        = bool
  default     = false
}

variable "external_id" {
  description = "Optional external ID required in the AssumeRole trust policy (confused-deputy protection)."
  type        = string
  default     = null
}

variable "inline_policies" {
  description = "Map of inline policy name => JSON policy document to embed directly in the role."
  type        = map(string)
  default     = {}
}

variable "managed_policy_arns" {
  description = "List of managed IAM policy ARNs to attach to the role."
  type        = list(string)
  default     = []
}

variable "instance_profile_name" {
  description = "Name of the IAM instance profile. Defaults to the role name when left empty."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags to apply to all created resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Purpose   = "EC2-Instance-Role"
  }
}

###############################################################################
# Data sources
###############################################################################

# Resolves the current partition so the EC2 service principal is correct in
# aws, aws-us-gov and aws-cn partitions.
data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # e.g. "ec2.amazonaws.com", "ec2.amazonaws.com.cn"
  ec2_service_principal = "ec2.${data.aws_partition.current.dns_suffix}"

  instance_profile_name = var.instance_profile_name != "" ? var.instance_profile_name : var.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2InstancesToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = local.ec2_service_principal
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

###############################################################################
# IAM Role
###############################################################################

resource "aws_iam_role" "this" {
  name                 = var.role_name
  description          = var.role_description
  path                 = var.role_path
  assume_role_policy   = local.assume_role_policy
  max_session_duration = var.max_session_duration
  permissions_boundary = var.permissions_boundary_arn
  force_detach_policies = var.force_detach_policies

  tags = merge(var.tags, {
    Name = var.role_name
  })
}

###############################################################################
# Inline policies
###############################################################################

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.key
  role   = aws_iam_role.this.id
  policy = each.value
}

###############################################################################
# Managed policy attachments
###############################################################################

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.this.name
  policy_arn = each.value
}

###############################################################################
# Instance profile
###############################################################################

resource "aws_iam_instance_profile" "this" {
  name = local.instance_profile_name
  path = var.role_path
  role = aws_iam_role.this.name

  tags = merge(var.tags, {
    Name = local.instance_profile_name
  })
}

###############################################################################
# Outputs
###############################################################################

output "role_name" {
  description = "Name of the created IAM role."
  value       = aws_iam_role.this.name
}

output "role_arn" {
  description = "ARN of the created IAM role."
  value       = aws_iam_role.this.arn
}

output "role_id" {
  description = "Stable, unique ID of the created IAM role."
  value       = aws_iam_role.this.unique_id
}

output "instance_profile_name" {
  description = "Name of the created instance profile."
  value       = aws_iam_instance_profile.this.name
}

output "instance_profile_arn" {
  description = "ARN of the created instance profile."
  value       = aws_iam_instance_profile.this.arn
}

output "ec2_service_principal" {
  description = "The partition-specific EC2 service principal trusted by the role."
  value       = local.ec2_service_principal
}

output "assume_role_policy" {
  description = "The rendered assume-role trust policy document."
  value       = local.assume_role_policy
}

output "inline_policy_names" {
  description = "Names of the inline policies embedded in the role."
  value       = sort(keys(aws_iam_role_policy.inline))
}

output "attached_managed_policy_arns" {
  description = "Managed policy ARNs attached to the role."
  value       = sort([for a in aws_iam_role_policy_attachment.managed : a.policy_arn])
}

output "partition" {
  description = "The AWS partition in which these resources were created."
  value       = data.aws_partition.current.partition
}

output "account_id" {
  description = "The AWS account ID in which these resources were created."
  value       = data.aws_caller_identity.current.account_id
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region

  default_tags {
    tags = local.common_tags
  }
}

############################################
# Variables
############################################

variable "region" {
  description = "AWS region in which to build the Fast-App network."
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the cluster this network is built for."
  type        = string
  default     = "Fast-App"
}

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnet tier (one subnet per CIDR, each in its own AZ)."
  type        = list(string)
  default     = ["10.0.0.0/20", "10.0.16.0/20", "10.0.32.0/20"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnet tier (one subnet per CIDR, each in its own AZ)."
  type        = list(string)
  default     = ["10.0.48.0/20", "10.0.64.0/20", "10.0.80.0/20"]
}

############################################
# Data sources & locals
############################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  # Spread each subnet tier across distinct availability zones.
  azs = slice(data.aws_availability_zones.available.names, 0, length(var.public_subnet_cidrs))

  common_tags = {
    Cluster     = var.cluster_name
    Environment = var.environment
    ManagedBy   = "Terraform"
    Network     = "${var.cluster_name}-vpc"
  }
}

############################################
# VPC
############################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

############################################
# Internet Gateway
############################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

############################################
# Public subnet tier (multi-AZ)
############################################

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.cluster_name}-public-subnet-${element(local.azs, count.index)}"
    Tier = "public"
  }
}

############################################
# Private subnet tier (multi-AZ)
############################################

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.cluster_name}-private-subnet-${element(local.azs, count.index)}"
    Tier = "private"
  }
}

############################################
# Public routing (internet access)
############################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-public-rt"
    Tier = "public"
  }
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

############################################
# Private routing (isolated / VPC-local only)
############################################

resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-private-rt-${element(local.azs, count.index)}"
    Tier = "private"
  }
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

############################################
# Outputs
############################################

output "vpc_id" {
  description = "ID of the Fast-App VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the Fast-App VPC."
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table providing internet access."
  value       = aws_route_table.public.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets, one per availability zone."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets, one per availability zone."
  value       = aws_subnet.private[*].id
}

output "availability_zones" {
  description = "Availability zones used by the subnet tiers."
  value       = local.azs
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the IAM role and policy."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for Grafana monitoring."
  type        = string
  default     = "GrafanaWorkspaceMonitoringRole"
}

variable "grafana_workspace_name" {
  description = "Name of the AWS Managed Grafana workspace."
  type        = string
  default     = "Grafana"
}

variable "monitoring_account_ids" {
  description = "List of AWS account IDs allowed to assume the role (monitoring accounts)."
  type        = list(string)
  default     = ["123456789012"]
}

variable "prometheus_workspace_arn" {
  description = "ARN of the Amazon Managed Service for Prometheus workspace. Use '*' to allow all."
  type        = string
  default     = "*"
}

variable "tags" {
  description = "Tags to apply to resources."
  type        = map(string)
  default = {
    Name        = "GrafanaWorkspaceMonitoringRole"
    Environment = "Monitoring"
  }
}

data "aws_iam_policy_document" "grafana_assume_role" {
  statement {
    sid     = "AllowGrafanaServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = var.monitoring_account_ids
    }
  }
}

resource "aws_iam_role" "grafana_monitoring" {
  name               = var.role_name
  description        = "IAM role for AWS Managed Grafana workspace '${var.grafana_workspace_name}' to query AMP and CloudWatch metrics."
  assume_role_policy = data.aws_iam_policy_document.grafana_assume_role.json
  tags               = var.tags
}

data "aws_iam_policy_document" "grafana_monitoring_permissions" {
  statement {
    sid    = "CloudWatchMetricsRead"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:DescribeAlarmsForMetric",
      "cloudwatch:DescribeAlarmHistory",
      "cloudwatch:ListTagsForResource"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "PrometheusQuery"
    effect = "Allow"
    actions = [
      "aps:ListWorkspaces",
      "aps:DescribeWorkspace",
      "aps:QueryMetrics",
      "aps:GetLabels",
      "aps:GetSeries",
      "aps:GetMetricMetadata",
      "aps:ListTagsForResource"
    ]
    resources = [var.prometheus_workspace_arn]
  }

  statement {
    sid    = "EC2DescribeRegions"
    effect = "Allow"
    actions = [
      "ec2:DescribeRegions"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "TagGetResources"
    effect = "Allow"
    actions = [
      "tag:GetResources"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_monitoring" {
  name        = "${var.role_name}-policy"
  description = "Custom policy allowing Grafana workspace '${var.grafana_workspace_name}' to query AMP and CloudWatch metrics."
  policy      = data.aws_iam_policy_document.grafana_monitoring_permissions.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "grafana_monitoring" {
  role       = aws_iam_role.grafana_monitoring.name
  policy_arn = aws_iam_policy.grafana_monitoring.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
