###############################################################################
# Provider & Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the development network."
  type        = string
  default     = "eu-west-2"
}

variable "vpc_name" {
  description = "Name/tag of the development VPC."
  type        = string
  default     = "trade-tariff-development-vpc"
}

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "development"
}

variable "project" {
  description = "Project name used for tagging."
  type        = string
  default     = "trade-tariff"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zones" {
  description = "Availability zones used for the public and private subnets."
  type        = list(string)
  default     = ["eu-west-2a", "eu-west-2b"]
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.12.0/24"]
}

variable "ssh_port" {
  description = "Port on which inbound SSH is allowed."
  type        = number
  default     = 22
}

variable "ssh_ingress_cidrs" {
  description = "CIDR blocks allowed to reach instances over SSH. Defaults to the VPC CIDR only."
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

variable "flow_log_retention_days" {
  description = "Retention period (days) for VPC flow log events in CloudWatch."
  type        = number
  default     = 14
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${var.availability_zones[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = var.availability_zones[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${var.availability_zones[count.index]}"
    Tier = "private"
  })
}

###############################################################################
# NAT gateway (private subnets -> internet, inbound blocked)
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Routing
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security group: allow-ssh
# Inbound SSH and outbound traffic are restricted to the VPC CIDR only.
###############################################################################

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allows inbound SSH and outbound traffic only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR only"
    from_port   = var.ssh_port
    to_port     = var.ssh_port
    protocol    = "tcp"
    cidr_blocks = var.ssh_ingress_cidrs
  }

  egress {
    description = "Outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "allow-ssh"
  })
}

###############################################################################
# IAM role + policy for VPC flow logs
###############################################################################

resource "aws_iam_role" "flow_logs" {
  name = "${var.vpc_name}-flow-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-flow-logs-role"
  })
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "${var.vpc_name}-flow-logs-policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Flow logs
###############################################################################

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc/${var.vpc_name}/flow-logs"
  retention_in_days = var.flow_log_retention_days

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-flow-logs"
  })
}

resource "aws_flow_log" "main" {
  vpc_id          = aws_vpc.main.id
  traffic_type    = "ALL"
  iam_role_arn    = aws_iam_role.flow_logs.arn
  log_destination = aws_cloudwatch_log_group.flow_logs.arn

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-flow-log"
  })

  depends_on = [aws_iam_role_policy.flow_logs]
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the development VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the development VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table."
  value       = aws_route_table.private.id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway used by the private subnets."
  value       = aws_nat_gateway.main.id
}

output "allow_ssh_security_group_id" {
  description = "ID of the 'allow-ssh' security group."
  value       = aws_security_group.allow_ssh.id
}

output "flow_log_id" {
  description = "ID of the VPC flow log."
  value       = aws_flow_log.main.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region in which to create the ECR resources."
  type        = string
  default     = "us-east-1"
}

variable "repository_name" {
  description = "Name of the ECR repository."
  type        = string
  default     = "app-images"
}

variable "image_tag_mutability" {
  description = "Tag mutability setting for the repository (MUTABLE or IMMUTABLE)."
  type        = string
  default     = "MUTABLE"

  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either MUTABLE or IMMUTABLE."
  }
}

variable "scan_on_push" {
  description = "Whether images are scanned for vulnerabilities when they are pushed."
  type        = bool
  default     = true
}

variable "force_delete" {
  description = "Whether the repository is deleted even if it still contains images."
  type        = bool
  default     = false
}

variable "create_kms_key" {
  description = "Create a customer managed KMS key for repository encryption. Takes precedence over kms_key_arn. When false and no kms_key_arn is given, AES256 is used."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of an existing customer managed KMS key used to encrypt images. Ignored when create_kms_key is true. Leave empty to use AES256."
  type        = string
  default     = ""
}

variable "kms_key_deletion_window_in_days" {
  description = "Waiting period (in days) before a KMS key created by this configuration is deleted."
  type        = number
  default     = 30

  validation {
    condition     = var.kms_key_deletion_window_in_days >= 7 && var.kms_key_deletion_window_in_days <= 30
    error_message = "kms_key_deletion_window_in_days must be between 7 and 30."
  }
}

variable "pull_access_principals" {
  description = "AWS principal ARNs (accounts, users, roles) allowed to pull images from the repository. An empty list means no repository access policy is created."
  type        = list(string)
  default     = []
}

variable "enable_lifecycle_policy" {
  description = "Whether to create a lifecycle policy that cleans up images."
  type        = bool
  default     = true
}

variable "untagged_image_expiration_days" {
  description = "Number of days after which untagged images are expired."
  type        = number
  default     = 14
}

variable "max_image_count" {
  description = "Maximum number of images retained in the repository."
  type        = number
  default     = 30
}

variable "create_ci_role" {
  description = "Whether to create an IAM role that CI/CD pipelines can assume to push and pull images."
  type        = bool
  default     = false
}

variable "ci_role_name" {
  description = "Name of the optional CI/CD IAM role. Defaults to <repository_name>-ci-role."
  type        = string
  default     = ""
}

variable "ci_role_trusted_principals" {
  description = "Principals allowed to assume the optional CI/CD role. Defaults to the current AWS account root."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to all resources that support tagging."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  generated_kms_key_arn = one(aws_kms_key.ecr[*].arn)

  kms_key_arn        = var.create_kms_key ? local.generated_kms_key_arn : var.kms_key_arn
  use_kms_encryption = local.kms_key_arn != null && local.kms_key_arn != ""

  create_repository_policy = length(var.pull_access_principals) > 0

  ci_role_name = var.ci_role_name != "" ? var.ci_role_name : "${var.repository_name}-ci-role"

  ci_trusted_principals = length(var.ci_role_trusted_principals) > 0 ? var.ci_role_trusted_principals : [
    "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
  ]
}

# -----------------------------------------------------------------------------
# Optional customer managed KMS key
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "kms" {
  count = var.create_kms_key ? 1 : 0

  # Account root retains administrative control of the key, which in turn
  # allows IAM policies inside the account to delegate key usage.
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Cross account (and explicit) pullers need to be able to decrypt the layers.
  dynamic "statement" {
    for_each = length(var.pull_access_principals) > 0 ? [1] : []

    content {
      sid    = "AllowPullPrincipalsToUseKey"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.pull_access_principals
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:GenerateDataKey",
      ]

      resources = ["*"]
    }
  }
}

resource "aws_kms_key" "ecr" {
  count = var.create_kms_key ? 1 : 0

  description             = "Customer managed key used to encrypt the ECR repository ${var.repository_name}"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = merge(var.tags, { Name = "${var.repository_name}-ecr" })
}

resource "aws_kms_alias" "ecr" {
  count = var.create_kms_key ? 1 : 0

  name          = "alias/ecr/${var.repository_name}"
  target_key_id = aws_kms_key.ecr[0].key_id
}

# -----------------------------------------------------------------------------
# ECR repository
# -----------------------------------------------------------------------------

resource "aws_ecr_repository" "this" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability
  force_delete         = var.force_delete

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = local.use_kms_encryption ? "KMS" : "AES256"
    kms_key         = local.use_kms_encryption ? local.kms_key_arn : null
  }

  tags = merge(var.tags, { Name = var.repository_name })
}

# -----------------------------------------------------------------------------
# Optional repository access policy (pull only)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "repository" {
  count = local.create_repository_policy ? 1 : 0

  statement {
    sid    = "AllowPullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.pull_access_principals
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]

    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_ecr_repository_policy" "this" {
  count = local.create_repository_policy ? 1 : 0

  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.repository[0].json
}

# -----------------------------------------------------------------------------
# Optional lifecycle policy for image cleanup
# -----------------------------------------------------------------------------

resource "aws_ecr_lifecycle_policy" "this" {
  count = var.enable_lifecycle_policy ? 1 : 0

  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after ${var.untagged_image_expiration_days} days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = var.untagged_image_expiration_days
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Retain only the most recent ${var.max_image_count} images"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = var.max_image_count
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Optional IAM role for CI/CD pipelines
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ci_assume_role" {
  count = var.create_ci_role ? 1 : 0

  statement {
    sid     = "AllowAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = local.ci_trusted_principals
    }
  }
}

resource "aws_iam_role" "ci" {
  count = var.create_ci_role ? 1 : 0

  name               = local.ci_role_name
  description        = "Role assumed by CI/CD pipelines to push and pull images from the ${var.repository_name} ECR repository"
  assume_role_policy = data.aws_iam_policy_document.ci_assume_role[0].json

  tags = merge(var.tags, { Name = local.ci_role_name })
}

data "aws_iam_policy_document" "ci" {
  count = var.create_ci_role ? 1 : 0

  statement {
    sid       = "AllowEcrAuthorizationToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowRepositoryPushPull"
    effect = "Allow"

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:CompleteLayerUpload",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetDownloadUrlForLayer",
      "ecr:InitiateLayerUpload",
      "ecr:ListImages",
      "ecr:PutImage",
      "ecr:UploadLayerPart",
    ]

    resources = [aws_ecr_repository.this.arn]
  }

  dynamic "statement" {
    for_each = local.use_kms_encryption ? [1] : []

    content {
      sid    = "AllowKmsUsage"
      effect = "Allow"

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:GenerateDataKey",
      ]

      resources = [local.kms_key_arn]
    }
  }
}

resource "aws_iam_policy" "ci" {
  count = var.create_ci_role ? 1 : 0

  name        = "${local.ci_role_name}-policy"
  description = "Push and pull access to the ${var.repository_name} ECR repository"
  policy      = data.aws_iam_policy_document.ci[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "ci" {
  count = var.create_ci_role ? 1 : 0

  role       = aws_iam_role.ci[0].name
  policy_arn = aws_iam_policy.ci[0].arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "repository_name" {
  description = "Name of the ECR repository."
  value       = aws_ecr_repository.this.name
}

output "repository_arn" {
  description = "ARN of the ECR repository."
  value       = aws_ecr_repository.this.arn
}

output "repository_url" {
  description = "URL used to push and pull images (docker push <url>:<tag>)."
  value       = aws_ecr_repository.this.repository_url
}

output "encryption_type" {
  description = "Encryption type configured on the repository."
  value       = local.use_kms_encryption ? "KMS" : "AES256"
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for repository encryption, or null when AES256 is used."
  value       = local.use_kms_encryption ? local.kms_key_arn : null
}

output "repository_policy_id" {
  description = "ID of the repository access policy, or null when no policy was created."
  value       = one(aws_ecr_repository_policy.this[*].id)
}

output "lifecycle_policy_id" {
  description = "ID of the lifecycle policy, or null when none was created."
  value       = one(aws_ecr_lifecycle_policy.this[*].id)
}

output "ci_role_arn" {
  description = "ARN of the optional CI/CD IAM role, or null when not created."
  value       = one(aws_iam_role.ci[*].arn)
}

terraform {
  required_version = ">= 1.2.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Provider
# ---------------------------------------------------------------------------
provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region in which to deploy the SQS queue."
  type        = string
  default     = "us-east-1"
}

# --- Standard naming module inputs ---
variable "name_prefix" {
  description = "Organization / application prefix used by the standard naming convention."
  type        = string
  default     = "acme"

  validation {
    condition     = can(regex("^[a-zA-Z0-9-]{1,40}$", var.name_prefix))
    error_message = "name_prefix must be 1-40 alphanumeric/hyphen characters."
  }
}

variable "environment" {
  description = "Deployment environment (e.g. dev, staging, prod) used by the standard naming convention."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-zA-Z0-9-]{1,20}$", var.environment))
    error_message = "environment must be 1-20 alphanumeric/hyphen characters."
  }
}

variable "queue_name" {
  description = "Logical queue name (suffix). Do not include the .fifo suffix; it is added automatically when fifo_queue is true."
  type        = string
  default     = "orders"

  validation {
    condition     = can(regex("^[a-zA-Z0-9_-]{1,40}$", var.queue_name))
    error_message = "queue_name must be 1-40 alphanumeric/underscore/hyphen characters."
  }
}

# --- Standard tagging module inputs ---
variable "tags" {
  description = "Additional tags merged into the standard tag set."
  type        = map(string)
  default     = {}
}

# --- Queue behavior ---
variable "fifo_queue" {
  description = "Whether to create a FIFO queue. When true, a .fifo suffix is appended to the queue name."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (FIFO queues only)."
  type        = bool
  default     = true
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level (FIFO queues only)."
  type        = string
  default     = "queue"

  validation {
    condition     = contains(["messageGroup", "queue"], var.deduplication_scope)
    error_message = "deduplication_scope must be either 'messageGroup' or 'queue'."
  }
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group (FIFO queues only)."
  type        = string
  default     = "perQueue"

  validation {
    condition     = contains(["perQueue", "perMessageGroupId"], var.fifo_throughput_limit)
    error_message = "fifo_throughput_limit must be either 'perQueue' or 'perMessageGroupId'."
  }
}

variable "delay_seconds" {
  description = "Time in seconds that the delivery of all messages in the queue is delayed."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Maximum message size in bytes (1024 to 262144)."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Number of seconds SQS retains a message (60 to 1209600)."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Long-polling wait time for ReceiveMessage calls (0 to 20)."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for the queue, in seconds (0 to 43200)."
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed server-side encryption (SSE-SQS)."
  type        = bool
  default     = true
}

# --- Optional access policy ---
variable "create_queue_policy" {
  description = "Whether to create a queue access policy granting the supplied principals permission to send messages."
  type        = bool
  default     = false
}

variable "policy_principal_arns" {
  description = "List of AWS principal ARNs (IAM users, roles, or accounts) granted access by the optional queue policy."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for arn in var.policy_principal_arns : can(regex("^arn:aws[a-zA-Z-]*:", arn))])
    error_message = "Every entry in policy_principal_arns must be a well-formed AWS ARN (e.g. arn:aws:iam::123456789012:role/MyRole)."
  }
}

variable "policy_actions" {
  description = "SQS actions granted to the principals when create_queue_policy is true."
  type        = list(string)
  default     = ["sqs:SendMessage"]

  validation {
    condition     = length(var.policy_actions) > 0
    error_message = "policy_actions must contain at least one SQS action."
  }
}

# ---------------------------------------------------------------------------
# Standard naming module (locals)
# ---------------------------------------------------------------------------
locals {
  # Deterministic name: <prefix>-<environment>-<queue_name>
  base_name = lower(join("-", [var.name_prefix, var.environment, var.queue_name]))

  # SQS requires the ".fifo" suffix for FIFO queues.
  queue_name = var.fifo_queue ? "${local.base_name}.fifo" : local.base_name

  # Standard tag set applied to every resource in this module.
  common_tags = merge(
    {
      Name        = local.queue_name
      Environment = var.environment
      Module      = "sqs"
      ManagedBy   = "Terraform"
    },
    var.tags
  )
}

# ---------------------------------------------------------------------------
# SQS Queue
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "this" {
  name                       = local.queue_name
  fifo_queue                 = var.fifo_queue
  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds
  sqs_managed_sse_enabled    = var.sqs_managed_sse_enabled

  # FIFO-only settings; must be null for standard queues.
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Optional queue access policy
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "queue" {
  count = var.create_queue_policy ? 1 : 0

  statement {
    sid    = "AllowPrincipalsToSendMessages"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.policy_principal_arns
    }

    actions   = var.policy_actions
    resources = [aws_sqs_queue.this.arn]
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this.id
  policy    = data.aws_iam_policy_document.queue[0].json

  lifecycle {
    precondition {
      condition     = length(var.policy_principal_arns) > 0
      error_message = "policy_principal_arns must contain at least one principal ARN when create_queue_policy is true."
    }
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "queue_name" {
  description = "Name of the created SQS queue."
  value       = aws_sqs_queue.this.name
}

output "queue_id" {
  description = "ID of the created SQS queue."
  value       = aws_sqs_queue.this.id
}

output "queue_arn" {
  description = "ARN of the created SQS queue."
  value       = aws_sqs_queue.this.arn
}

output "queue_url" {
  description = "URL of the created SQS queue."
  value       = aws_sqs_queue.this.url
}

output "queue_is_fifo" {
  description = "Whether the created queue is a FIFO queue."
  value       = aws_sqs_queue.this.fifo_queue
}

output "queue_policy_json" {
  description = "JSON of the optional queue access policy (null when create_queue_policy is false)."
  value       = var.create_queue_policy ? data.aws_iam_policy_document.queue[0].json : null
}

output "common_tags" {
  description = "The standard tag set applied to the queue."
  value       = local.common_tags
}

###############################################################################
# Terraform & provider requirements
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.81.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS Region in which the primary Aurora DSQL cluster is created."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name of the Aurora DSQL cluster. Used for the Name tag."
  type        = string
  default     = "dsql-cluster"
}

variable "tags" {
  description = "Map of tags applied to every resource that supports tagging."
  type        = map(string)
  default     = {}
}

variable "create_cluster" {
  description = "Controls whether the Aurora DSQL cluster is created."
  type        = bool
  default     = true
}

variable "deletion_protection_enabled" {
  description = "Whether deletion protection is enabled on the DSQL cluster."
  type        = bool
  default     = true
}

variable "force_destroy" {
  description = "Whether the cluster may be destroyed even while it participates in a multi-Region (peered) cluster."
  type        = bool
  default     = false
}

variable "kms_encryption_key" {
  description = "ARN (or key alias ARN) of the customer managed KMS key used to encrypt the cluster. When null, an AWS owned key is used."
  type        = string
  default     = null
}

variable "enable_multi_region_peering" {
  description = "Controls whether a cluster peering relationship is created between this cluster and the clusters listed in peer_cluster_arns."
  type        = bool
  default     = false
}

variable "peer_cluster_arns" {
  description = "List of ARNs of the Aurora DSQL clusters to peer with. Must contain at least one ARN when enable_multi_region_peering is true."
  type        = list(string)
  default     = []
}

variable "witness_region" {
  description = "Witness Region used by the multi-Region cluster. Required when peering clusters that live in different Regions."
  type        = string
  default     = null
}

variable "peering_create_timeout" {
  description = "Timeout for the cluster peering create operation (for example \"30m\")."
  type        = string
  default     = "30m"
}

###############################################################################
# Providers
###############################################################################

provider "aws" {
  region = var.region

  default_tags {
    tags = var.tags
  }
}

# Cluster peering is created in the witness Region of the multi-Region cluster.
# When no witness Region is supplied (same-Region peering) this provider falls
# back to the primary Region.
provider "aws" {
  alias  = "witness"
  region = local.peering_region

  default_tags {
    tags = var.tags
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  # Region used for the peering call: the witness Region when provided,
  # otherwise the primary Region.
  peering_region = coalesce(var.witness_region, var.region)

  # Peering is provisioned only when explicitly enabled, when the cluster is
  # created and when at least one peer cluster ARN has been supplied.
  create_peering = var.create_cluster && var.enable_multi_region_peering && length(var.peer_cluster_arns) > 0

  cluster_tags = merge(var.tags, { Name = var.name })
}

###############################################################################
# Amazon Aurora DSQL cluster
###############################################################################

resource "aws_dsql_cluster" "this" {
  count = var.create_cluster ? 1 : 0

  deletion_protection_enabled = var.deletion_protection_enabled
  force_destroy               = var.force_destroy
  kms_encryption_key          = var.kms_encryption_key

  tags = local.cluster_tags
}

###############################################################################
# Optional multi-Region cluster peering
###############################################################################

resource "aws_dsql_cluster_peering" "this" {
  count    = local.create_peering ? 1 : 0
  provider = aws.witness

  # The peering relationship always contains this cluster plus every peer.
  clusters       = concat(aws_dsql_cluster.this[*].arn, var.peer_cluster_arns)
  witness_region = var.witness_region

  timeouts {
    create = var.peering_create_timeout
  }
}

###############################################################################
# Outputs
###############################################################################

output "cluster_identifier" {
  description = "Identifier of the Aurora DSQL cluster (null when create_cluster is false)."
  value       = one(aws_dsql_cluster.this[*].identifier)
}

output "cluster_arn" {
  description = "ARN of the Aurora DSQL cluster (null when create_cluster is false)."
  value       = one(aws_dsql_cluster.this[*].arn)
}

output "cluster_peering_id" {
  description = "ID of the DSQL cluster peering relationship (null when peering is not created)."
  value       = one(aws_dsql_cluster_peering.this[*].id)
}

output "cluster_peering_region" {
  description = "Region used to create the cluster peering relationship (witness Region or primary Region)."
  value       = local.peering_region
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.67.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.tags
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region where resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "Globally unique name for the S3 bucket."
  type        = string
}

variable "object_lock_enabled" {
  description = "Whether to enable S3 Object Lock on the bucket. Versioning is forced to Enabled when true."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Whether to delete all objects from the bucket so it can be destroyed even when non-empty. Defaults to false to prevent accidental data loss."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Map of tags applied to all resources created by this module."
  type        = map(string)
  default     = {}
}

variable "versioning_enabled" {
  description = "Whether S3 bucket versioning should be enabled (ignored/forced true when object lock is enabled)."
  type        = bool
  default     = true
}

variable "object_lock_mode" {
  description = "Default Object Lock retention mode. Valid values: GOVERNANCE or COMPLIANCE."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be either GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Default Object Lock retention period in days."
  type        = number
  default     = 30
}

variable "kms_deletion_window_in_days" {
  description = "Number of days before the KMS key is deleted after scheduling deletion."
  type        = number
  default     = 10
}

variable "bucket_policies" {
  description = <<-EOT
    Map of custom bucket policy documents to create and attach. Each entry supports:
      policy_id      - optional policy identifier (defaults to null)
      policy_version - IAM policy language version (defaults to "2012-10-17")
      statements     - list of statements; each statement supports:
        sid         - optional statement identifier
        actions     - list of IAM actions
        effect      - "Allow" or "Deny" (defaults to "Allow")
        resources   - list of resource ARNs
        principals  - list of principal blocks: { type = "AWS"|"Service"|"Federated"|"*", identifiers = [ ... ] }
    Example:
      bucket_policies = {
        "deny-insecure-transport" = {
          statements = [{
            sid       = "DenyInsecureTransport"
            actions   = ["s3:*"]
            effect    = "Deny"
            resources = ["arn:aws:s3:::my-bucket", "arn:aws:s3:::my-bucket/*"]
            principals = [{ type = "*", identifiers = ["*"] }]
          }]
        }
      }
  EOT
  type = map(object({
    policy_id      = optional(string)
    policy_version = optional(string, "2012-10-17")
    statements = list(object({
      sid       = optional(string)
      actions   = list(string)
      effect    = optional(string, "Allow")
      resources = list(string)
      principals = list(object({
        type        = string
        identifiers = list(string)
      }))
    }))
  }))
  default = {}
}

variable "create_access_role" {
  description = "Whether to create an IAM role that can be assumed to access the bucket and its KMS key."
  type        = bool
  default     = true
}

variable "access_role_name" {
  description = "Name of the IAM access role. Defaults to '<bucket_name>-access-role' when null."
  type        = string
  default     = null
}

variable "access_role_assume_role_principals" {
  description = "List of AWS principal ARNs allowed to assume the access role. Defaults to the current account root when empty."
  type        = list(string)
  default     = []
}

###############################################################################
# Locals
###############################################################################

locals {
  tags = merge(
    var.tags,
    {
      ManagedBy = "Terraform"
    }
  )

  versioning_status = (var.object_lock_enabled || var.versioning_enabled) ? "Enabled" : "Suspended"

  access_role_name = coalesce(var.access_role_name, "${var.bucket_name}-access-role")

  assume_role_principals = length(var.access_role_assume_role_principals) > 0 ? var.access_role_assume_role_principals : [
    "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
  ]
}

###############################################################################
# KMS key (customer managed) for default bucket encryption
###############################################################################

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "this" {
  description             = "Customer managed key used for default encryption of S3 bucket ${var.bucket_name}"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = merge(local.tags, { Name = "${var.bucket_name}-s3-kms" })
}

resource "aws_kms_alias" "this" {
  name          = "alias/${var.bucket_name}-s3"
  target_key_id = aws_kms_key.this.key_id
}

###############################################################################
# S3 bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = merge(local.tags, { Name = var.bucket_name })
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = local.versioning_status
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_days
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Dynamic bucket policies (created only when provided)
###############################################################################

data "aws_iam_policy_document" "bucket_policy" {
  for_each = var.bucket_policies

  policy_id = try(each.value.policy_id, null)
  version   = try(each.value.policy_version, "2012-10-17")

  dynamic "statement" {
    for_each = each.value.statements

    content {
      sid       = try(statement.value.sid, null)
      actions   = statement.value.actions
      effect    = try(statement.value.effect, "Allow")
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  for_each = var.bucket_policies

  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy[each.key].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Optional IAM access role for the bucket
###############################################################################

data "aws_iam_policy_document" "access_role_assume" {
  count = var.create_access_role ? 1 : 0

  statement {
    sid     = "AllowAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = local.assume_role_principals
    }
  }
}

resource "aws_iam_role" "access" {
  count = var.create_access_role ? 1 : 0

  name                 = local.access_role_name
  description          = "Role granting access to S3 bucket ${var.bucket_name} and its KMS key"
  assume_role_policy   = data.aws_iam_policy_document.access_role_assume[0].json
  max_session_duration = 3600

  tags = merge(local.tags, { Name = local.access_role_name })
}

data "aws_iam_policy_document" "access_role_permissions" {
  count = var.create_access_role ? 1 : 0

  statement {
    sid    = "ListBucket"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
    ]

    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    sid    = "ObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
    ]

    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  statement {
    sid    = "KmsUsage"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.this.arn]
  }
}

resource "aws_iam_role_policy" "access" {
  count = var.create_access_role ? 1 : 0

  name   = "${var.bucket_name}-access-policy"
  role   = aws_iam_role.access[0].id
  policy = data.aws_iam_policy_document.access_role_permissions[0].json
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "Name/ID of the created S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the created S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Regional domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_region" {
  description = "Region the S3 bucket resides in."
  value       = data.aws_region.current.name
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used for default bucket encryption."
  value       = aws_kms_key.this.arn
}

output "kms_key_alias" {
  description = "Alias of the customer managed KMS key."
  value       = aws_kms_alias.this.name
}

output "bucket_policy_ids" {
  description = "Map of the attached bucket policy identifiers (keys of the input map)."
  value       = { for k, v in aws_s3_bucket_policy.this : k => v.id }
}

output "access_role_arn" {
  description = "ARN of the optional IAM access role (null when not created)."
  value       = var.create_access_role ? aws_iam_role.access[0].arn : null
}

output "access_role_name" {
  description = "Name of the optional IAM access role (null when not created)."
  value       = var.create_access_role ? aws_iam_role.access[0].name : null
}

## Description of the Terraform Program

This template deploys a **versatile Amazon SNS topic** stack with the following behavior:

**Core topic**
- A single `aws_sns_topic` guarded by a master `create` toggle (`count`-based conditional creation of every resource).
- Topic naming supports either an explicit `name` or a `name_prefix` (`use_name_prefix`). When `fifo_topic = true`, the required `.fifo` suffix is appended automatically for `name`, and for prefix-based names a `random_id` suffix is generated so the resulting name still ends in `.fifo` (prefix + generated suffix + `.fifo`), which keeps FIFO naming valid and unique.
- Configurable `display_name`, `kms_master_key_id`, `signature_version`, `tracing_config`, `delivery_policy`, and FIFO-only settings (`content_based_deduplication`, `fifo_throughput_scope`, `archive_policy`, `beginning_archive_time`).

**Delivery feedback roles**
- A `delivery_feedback_roles` map variable drives creation of IAM roles for SQS, Lambda, HTTP/S, Firehose and application delivery feedback (keys such as `sqs_failure`, `http_success`, `lambda_failure`, `firehose_failure`, `application_success`, …).
- Each role is created with an `sns.amazonaws.com` trust policy, an inline CloudWatch Logs policy, and can be customised (name, description, actions, resources, tags). User-supplied ARNs override generated ones, and generated ARNs are wired into the corresponding topic attributes.

**Topic policy**
- An `aws_sns_topic_policy` built from `aws_iam_policy_document` with a default owner-access statement (account root principal + `AWS:SourceOwner` condition), plus support for user-defined statements (`topic_policy_statements`), source documents (`source_topic_policy_documents`) and override documents (`override_topic_policy_documents`). Creation is conditional and skipped when no statement would be produced.

**Subscriptions**
- A `subscriptions` map dynamically creates `aws_sns_topic_subscription` resources with protocol, endpoint, auto-confirmation, confirmation timeout (only applied for HTTP/S), raw message delivery, filter policy/scope, delivery policy, redrive policy, replay policy, subscription role ARN and tags.

Outputs expose the topic ARN/ID/name/owner, the resolved policy JSON, subscription ARNs, and all created feedback role ARNs and names.

```iac_template
################################################################################
# Providers, data sources and locals
################################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "random_id" "fifo_name_suffix" {
  count = var.create && var.fifo_topic && var.use_name_prefix ? 1 : 0

  byte_length = 4

  keepers = {
    name_prefix = var.name_prefix
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # FIFO topics must end with `.fifo`. When a name prefix is used the AWS
  # provider appends its own random suffix, which would break the `.fifo`
  # requirement, so the suffix is generated here instead.
  fifo_prefixed_name = "${var.name_prefix}${join("", random_id.fifo_name_suffix[*].hex)}.fifo"

  named_topic_name = var.fifo_topic ? (endswith(var.name, ".fifo") ? var.name : "${var.name}.fifo") : var.name

  topic_name        = var.use_name_prefix ? (var.fifo_topic ? local.fifo_prefixed_name : null) : local.named_topic_name
  topic_name_prefix = var.use_name_prefix && !var.fifo_topic ? var.name_prefix : null

  # Roles that should be created for delivery feedback
  delivery_feedback_roles = {
    for k, v in var.delivery_feedback_roles : k => v
    if var.create && v.create
  }

  created_feedback_role_arns = {
    for k, v in aws_iam_role.delivery_feedback : k => v.arn
  }

  application_failure_feedback_role_arn = var.application_failure_feedback_role_arn != "" ? var.application_failure_feedback_role_arn : lookup(local.created_feedback_role_arns, "application_failure", null)
  application_success_feedback_role_arn = var.application_success_feedback_role_arn != "" ? var.application_success_feedback_role_arn : lookup(local.created_feedback_role_arns, "application_success", null)
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn != "" ? var.firehose_failure_feedback_role_arn : lookup(local.created_feedback_role_arns, "firehose_failure", null)
  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn != "" ? var.firehose_success_feedback_role_arn : lookup(local.created_feedback_role_arns, "firehose_success", null)
  http_failure_feedback_role_arn        = var.http_failure_feedback_role_arn != "" ? var.http_failure_feedback_role_arn : lookup(local.created_feedback_role_arns, "http_failure", null)
  http_success_feedback_role_arn        = var.http_success_feedback_role_arn != "" ? var.http_success_feedback_role_arn : lookup(local.created_feedback_role_arns, "http_success", null)
  lambda_failure_feedback_role_arn      = var.lambda_failure_feedback_role_arn != "" ? var.lambda_failure_feedback_role_arn : lookup(local.created_feedback_role_arns, "lambda_failure", null)
  lambda_success_feedback_role_arn      = var.lambda_success_feedback_role_arn != "" ? var.lambda_success_feedback_role_arn : lookup(local.created_feedback_role_arns, "lambda_success", null)
  sqs_failure_feedback_role_arn         = var.sqs_failure_feedback_role_arn != "" ? var.sqs_failure_feedback_role_arn : lookup(local.created_feedback_role_arns, "sqs_failure", null)
  sqs_success_feedback_role_arn         = var.sqs_success_feedback_role_arn != "" ? var.sqs_success_feedback_role_arn : lookup(local.created_feedback_role_arns, "sqs_success", null)

  # The topic policy is only created when there is at least one statement
  topic_policy_enabled = var.create && var.create_topic_policy && (
    var.enable_default_topic_policy ||
    length(var.topic_policy_statements) > 0 ||
    length(var.source_topic_policy_documents) > 0 ||
    length(var.override_topic_policy_documents) > 0
  )
}

################################################################################
# SNS Topic
################################################################################

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name         = local.topic_name
  name_prefix  = local.topic_name_prefix
  display_name = var.display_name != "" ? var.display_name : null

  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  fifo_throughput_scope       = var.fifo_topic ? var.fifo_throughput_scope : null

  archive_policy         = var.fifo_topic && var.archive_policy != "" ? var.archive_policy : null
  beginning_archive_time = var.fifo_topic ? var.beginning_archive_time : null

  kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
  signature_version = var.signature_version
  tracing_config    = var.tracing_config != "" ? var.tracing_config : null
  delivery_policy   = var.delivery_policy != "" ? var.delivery_policy : null

  application_failure_feedback_role_arn    = local.application_failure_feedback_role_arn
  application_success_feedback_role_arn    = local.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate

  firehose_failure_feedback_role_arn    = local.firehose_failure_feedback_role_arn
  firehose_success_feedback_role_arn    = local.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate

  http_failure_feedback_role_arn    = local.http_failure_feedback_role_arn
  http_success_feedback_role_arn    = local.http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate

  lambda_failure_feedback_role_arn    = local.lambda_failure_feedback_role_arn
  lambda_success_feedback_role_arn    = local.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate

  sqs_failure_feedback_role_arn    = local.sqs_failure_feedback_role_arn
  sqs_success_feedback_role_arn    = local.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate

  tags = var.tags
}

################################################################################
# Delivery feedback IAM roles
################################################################################

data "aws_iam_policy_document" "delivery_feedback_assume_role" {
  statement {
    sid     = "AllowSNSToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "delivery_feedback" {
  for_each = local.delivery_feedback_roles

  statement {
    sid       = "AllowDeliveryStatusLogging"
    effect    = "Allow"
    actions   = each.value.log_actions
    resources = each.value.log_resources
  }
}

resource "aws_iam_role" "delivery_feedback" {
  for_each = local.delivery_feedback_roles

  name        = each.value.name
  name_prefix = each.value.name == null ? coalesce(each.value.name_prefix, "sns-${replace(each.key, "_", "-")}-") : null
  description = coalesce(each.value.description, "IAM role used by SNS for ${replace(each.key, "_", "-")} delivery feedback")
  path        = "/"

  assume_role_policy = data.aws_iam_policy_document.delivery_feedback_assume_role.json

  tags = merge(var.tags, each.value.tags)
}

resource "aws_iam_role_policy" "delivery_feedback" {
  for_each = local.delivery_feedback_roles

  name   = "sns-${replace(each.key, "_", "-")}-delivery-feedback"
  role   = aws_iam_role.delivery_feedback[each.key].id
  policy = data.aws_iam_policy_document.delivery_feedback[each.key].json
}

################################################################################
# Topic policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = local.topic_policy_enabled ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid    = "DefaultTopicPolicy"
      effect = "Allow"

      actions = [
        "SNS:GetTopicAttributes",
        "SNS:SetTopicAttributes",
        "SNS:AddPermission",
        "SNS:RemovePermission",
        "SNS:DeleteTopic",
        "SNS:Subscribe",
        "SNS:ListSubscriptionsByTopic",
        "SNS:Publish",
      ]

      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
      }

      condition {
        test     = "StringEquals"
        variable = "AWS:SourceOwner"
        values   = [local.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = local.topic_policy_enabled ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Subscriptions
################################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = { for k, v in var.subscriptions : k => v if var.create }

  topic_arn = aws_sns_topic.this[0].arn

  protocol = each.value.protocol
  endpoint = each.value.endpoint

  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  confirmation_timeout_in_minutes = contains(["http", "https"], each.value.protocol) ? each.value.confirmation_timeout_in_minutes : 0

  raw_message_delivery  = each.value.raw_message_delivery
  filter_policy         = each.value.filter_policy
  filter_policy_scope   = each.value.filter_policy_scope
  delivery_policy       = each.value.delivery_policy
  redrive_policy        = each.value.redrive_policy
  replay_policy         = each.value.replay_policy
  subscription_role_arn = each.value.subscription_role_arn

  tags = merge(var.tags, each.value.tags)
}

################################################################################
# Variables
################################################################################

variable "aws_region" {
  description = "The AWS region to deploy the SNS resources into"
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Controls whether the SNS topic, its policy, roles and subscriptions should be created"
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SNS topic. Used when `use_name_prefix` is false. For FIFO topics the `.fifo` suffix is appended automatically if it is missing"
  type        = string
  default     = ""
}

variable "use_name_prefix" {
  description = "Determines whether `name` or `name_prefix` is used for the SNS topic name"
  type        = bool
  default     = true
}

variable "name_prefix" {
  description = "The prefix for the SNS topic name. Used when `use_name_prefix` is true"
  type        = string
  default     = "sns-"
}

variable "display_name" {
  description = "The display name of the SNS topic"
  type        = string
  default     = ""
}

variable "fifo_topic" {
  description = "Whether the SNS topic is a FIFO topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Whether content based deduplication is enabled. Only used for FIFO topics"
  type        = bool
  default     = false
}

variable "fifo_throughput_scope" {
  description = "Specifies whether message deduplication occurs at the message group or topic level. Valid values: `Topic`, `MessageGroup`. Only used for FIFO topics"
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "The ID or ARN of an AWS managed customer master key used to encrypt messages on the topic"
  type        = string
  default     = ""
}

variable "signature_version" {
  description = "The signature version (1 or 2) used when Amazon SNS sends a message to an HTTP/S endpoint"
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of the SNS topic. Valid values: `PassThrough`, `Active`"
  type        = string
  default     = "PassThrough"
}

variable "delivery_policy" {
  description = "JSON string of the delivery policy of the topic, applied to all HTTP/S subscriptions"
  type        = string
  default     = ""
}

variable "archive_policy" {
  description = "JSON string of the archive policy of a FIFO topic"
  type        = string
  default     = ""
}

variable "beginning_archive_time" {
  description = "The earliest timestamp from which messages can be archived (RFC3339). Only used for FIFO topics"
  type        = string
  default     = null
}

variable "application_failure_feedback_role_arn" {
  description = "IAM role ARN for application endpoint delivery failure feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "application_success_feedback_role_arn" {
  description = "IAM role ARN for application endpoint delivery success feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "application_success_feedback_sample_rate" {
  description = "Percentage of successful messages delivered to application endpoints for which delivery feedback is logged"
  type        = number
  default     = null
}

variable "firehose_failure_feedback_role_arn" {
  description = "IAM role ARN for Firehose delivery failure feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "firehose_success_feedback_role_arn" {
  description = "IAM role ARN for Firehose delivery success feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "firehose_success_feedback_sample_rate" {
  description = "Percentage of successful messages delivered to Firehose for which delivery feedback is logged"
  type        = number
  default     = null
}

variable "http_failure_feedback_role_arn" {
  description = "IAM role ARN for HTTP/S delivery failure feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "http_success_feedback_role_arn" {
  description = "IAM role ARN for HTTP/S delivery success feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "http_success_feedback_sample_rate" {
  description = "Percentage of successful messages delivered to HTTP/S endpoints for which delivery feedback is logged"
  type        = number
  default     = null
}

variable "lambda_failure_feedback_role_arn" {
  description = "IAM role ARN for Lambda delivery failure feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "lambda_success_feedback_role_arn" {
  description = "IAM role ARN for Lambda delivery success feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "lambda_success_feedback_sample_rate" {
  description = "Percentage of successful messages delivered to Lambda for which delivery feedback is logged"
  type        = number
  default     = null
}

variable "sqs_failure_feedback_role_arn" {
  description = "IAM role ARN for SQS delivery failure feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "sqs_success_feedback_role_arn" {
  description = "IAM role ARN for SQS delivery success feedback. Overrides any generated role"
  type        = string
  default     = ""
}

variable "sqs_success_feedback_sample_rate" {
  description = "Percentage of successful messages delivered to SQS for which delivery feedback is logged"
  type        = number
  default     = null
}

variable "delivery_feedback_roles" {
  description = <<-EOT
    Map of IAM roles to create that SNS can assume in order to deliver delivery-status
    feedback. Valid keys are: `application_failure`, `application_success`, `http_failure`,
    `http_success`, `lambda_failure`, `lambda_success`, `sqs_failure`, `sqs_success`,
    `firehose_failure`, `firehose_success`.
  EOT
  type = map(object({
    create        = optional(bool, true)
    name          = optional(string, null)
    name_prefix   = optional(string, null)
    description   = optional(string, null)
    log_actions   = optional(list(string), ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents", "logs:PutMetricFilter", "logs:PutRetentionPolicy"])
    log_resources = optional(list(string), ["*"])
    tags          = optional(map(string), {})
  }))
  default = {}

  validation {
    condition = alltrue([
      for k in keys(var.delivery_feedback_roles) : contains([
        "application_failure",
        "application_success",
        "http_failure",
        "http_success",
        "lambda_failure",
        "lambda_success",
        "sqs_failure",
        "sqs_success",
        "firehose_failure",
        "firehose_success",
      ], k)
    ])
    error_message = "Valid keys for `delivery_feedback_roles` are: application_failure, application_success, http_failure, http_success, lambda_failure, lambda_success, sqs_failure, sqs_success, firehose_failure, firehose_success."
  }
}

variable "create_topic_policy" {
  description = "Controls whether an SNS topic policy should be created"
  type        = bool
  default     = true
}

variable "enable_default_topic_policy" {
  description = "Controls whether the default owner-access statement is added to the topic policy"
  type        = bool
  default     = true
}

variable "topic_policy_statements" {
  description = "A map of IAM policy statements to add to the topic policy. Each value supports `sid`, `actions`, `not_actions`, `effect`, `resources`, `not_resources`, `principals`, `not_principals` and `conditions`"
  type        = any
  default     = {}
}

variable "source_topic_policy_documents" {
  description = "List of JSON policy documents to merge into the topic policy as source documents"
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of JSON policy documents that override statements in the topic policy"
  type        = list(string)
  default     = []
}

variable "subscriptions" {
  description = "Map of SNS subscriptions to create for the topic"
  type = map(object({
    protocol                        = string
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool, false)
    confirmation_timeout_in_minutes = optional(number, 1)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string, null)
    filter_policy_scope             = optional(string, null)
    delivery_policy                 = optional(string, null)
    redrive_policy                  = optional(string, null)
    replay_policy                   = optional(string, null)
    subscription_role_arn           = optional(string, null)
    tags                            = optional(map(string), {})
  }))
  default = {}
}

variable "tags" {
  description = "A map of tags to assign to all resources created by this configuration"
  type        = map(string)
  default     = {}
}

################################################################################
# Outputs
################################################################################

output "topic_arn" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ID of the SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the SNS topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_owner" {
  description = "The AWS account ID of the SNS topic owner"
  value       = try(aws_sns_topic.this[0].owner, null)
}

output "topic_policy" {
  description = "The JSON policy of the SNS topic"
  value       = try(aws_sns_topic_policy.this[0].policy, null)
}

output "topic_subscriptions" {
  description = "Map of subscription keys to their ARNs"
  value       = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}

output "delivery_feedback_role_arns" {
  description = "Map of delivery feedback role keys to the ARNs of the roles created by this configuration"
  value       = local.created_feedback_role_arns
}

output "delivery_feedback_role_names" {
  description = "Map of delivery feedback role keys to the names of the roles created by this configuration"
  value       = { for k, v in aws_iam_role.delivery_feedback : k => v.name }
}
```

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.0.0/24"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "ansible-vpc"
}

variable "private_subnet_name" {
  description = "Name tag for the private subnet"
  type        = string
  default     = "ansible-vpc-private-subnet-1"
}

variable "public_subnet_name" {
  description = "Name tag for the public subnet"
  type        = string
  default     = "ansible-vpc-public-subnet-1"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "ansible-vpc-igw"
}

variable "public_rt_name" {
  description = "Name tag for the public route table"
  type        = string
  default     = "ansible-vpc-public-rt"
}

variable "private_rt_name" {
  description = "Name tag for the private route table"
  type        = string
  default     = "ansible-vpc-private-rt"
}

############################################
# Data Sources
############################################

data "aws_availability_zones" "available" {
  state = "available"
}

############################################
# VPC
############################################

resource "aws_vpc" "ansible_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

############################################
# Subnets
############################################

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = var.private_subnet_name
    Tier = "private"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = var.public_subnet_name
    Tier = "public"
  }
}

############################################
# Internet Gateway
############################################

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = var.igw_name
  }
}

############################################
# Public Route Table
############################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = var.public_rt_name
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

############################################
# Private Route Table (no internet route)
############################################

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = var.private_rt_name
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

############################################
# Outputs
############################################

output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.ansible_vpc.id
}

output "vpc_cidr" {
  description = "CIDR block of the VPC"
  value       = aws_vpc.ansible_vpc.cidr_block
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = aws_internet_gateway.igw.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table"
  value       = aws_route_table.private.id
}

###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the Transit Gateway resources are deployed."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name used for naming/tagging the Transit Gateway resources."
  type        = string
  default     = "central-tgw"
}

variable "tags" {
  description = "Tags applied to every resource created by this template."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "centralized-inter-vpc-routing"
  }
}

variable "create_transit_gateway" {
  description = "true  -> create a new Transit Gateway. false -> reuse the Transit Gateway given in var.transit_gateway_id."
  type        = bool
  default     = true
}

variable "transit_gateway_id" {
  description = "ID of an existing Transit Gateway (e.g. tgw-0123456789abcdef0). Only used when create_transit_gateway = false."
  type        = string
  default     = ""
}

variable "amazon_side_asn" {
  description = "Private ASN for the Transit Gateway (64512-65534 or 4200000000-4294967294)."
  type        = number
  default     = 64512
}

variable "transit_gateway_dns_support" {
  description = "Enable DNS support on the Transit Gateway."
  type        = bool
  default     = true
}

variable "transit_gateway_vpn_ecmp_support" {
  description = "Enable ECMP support for VPN attachments on the Transit Gateway."
  type        = bool
  default     = true
}

variable "transit_gateway_auto_accept_shared_attachments" {
  description = "Whether to auto-accept shared attachments (\"enable\" or \"disable\")."
  type        = string
  default     = "disable"
}

variable "vpc_attachments" {
  description = <<-EOT
    Map of VPCs to attach to the Transit Gateway. The map key is a friendly name.
    Each value requires:
      vpc_id              - ID of the VPC to attach.
      subnet_ids          - Subnet IDs used for the attachment (one per AZ recommended).
    Optional per-VPC settings:
      vpc_route_table_ids - VPC route table IDs that should receive a route to every
                            OTHER attached VPC's CIDR via the Transit Gateway.
      dns_support         - Enable DNS support for the attachment (default true).
      ipv6_support        - Enable IPv6 support for the attachment (default false).
      appliance_mode_support - Enable appliance mode (default false).
      tags                - Extra tags for the attachment.

    Example:
      vpc_attachments = {
        prod = {
          vpc_id              = "vpc-0aaa1111"
          subnet_ids          = ["subnet-0aaa", "subnet-0bbb"]
          vpc_route_table_ids = ["rtb-0aaa"]
        }
        shared = {
          vpc_id              = "vpc-0ccc2222"
          subnet_ids          = ["subnet-0ccc", "subnet-0ddd"]
          vpc_route_table_ids = ["rtb-0ccc"]
        }
      }
  EOT
  type = map(object({
    vpc_id                 = string
    subnet_ids             = list(string)
    vpc_route_table_ids    = optional(list(string), [])
    dns_support            = optional(bool, true)
    ipv6_support           = optional(bool, false)
    appliance_mode_support = optional(bool, false)
    tags                   = optional(map(string), {})
  }))
  default = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_vpc" "attached" {
  for_each = var.vpc_attachments

  id = each.value.vpc_id
}

###############################################################################
# Locals
###############################################################################

locals {
  # Resolve the Transit Gateway that will be used by every attachment.
  transit_gateway_id = var.create_transit_gateway ? aws_ec2_transit_gateway.this[0].id : var.transit_gateway_id

  # CIDR block of every attached VPC, keyed by the friendly name.
  vpc_cidrs = {
    for name, vpc in data.aws_vpc.attached : name => vpc.cidr_block
  }

  # Flattened map of VPC route-table entries: each supplied VPC route table gets a
  # route for every OTHER attached VPC's CIDR block, pointed at the Transit Gateway.
  vpc_route_table_routes = merge({}, flatten([
    for src_name, att in var.vpc_attachments : [
      for rt_id in att.vpc_route_table_ids : {
        for dst_name, dst_cidr in local.vpc_cidrs : "${src_name}-${rt_id}-${dst_name}" => {
          route_table_id         = rt_id
          destination_cidr_block = dst_cidr
        }
        if dst_name != src_name
      }
    ]
  ])...)
}

###############################################################################
# Transit Gateway
###############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create_transit_gateway ? 1 : 0

  description                     = "${var.name} - centralized inter-VPC routing"
  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.transit_gateway_auto_accept_shared_attachments
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  dns_support                     = var.transit_gateway_dns_support ? "enable" : "disable"
  vpn_ecmp_support                = var.transit_gateway_vpn_ecmp_support ? "enable" : "disable"
  multicast_support               = "disable"

  tags = merge(var.tags, { Name = var.name })
}

###############################################################################
# VPC attachments (one per entry of var.vpc_attachments)
###############################################################################

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each = var.vpc_attachments

  transit_gateway_id = local.transit_gateway_id
  vpc_id             = each.value.vpc_id
  subnet_ids         = each.value.subnet_ids

  dns_support            = each.value.dns_support ? "enable" : "disable"
  ipv6_support           = each.value.ipv6_support ? "enable" : "disable"
  appliance_mode_support = each.value.appliance_mode_support ? "enable" : "disable"

  # Routing is managed explicitly through the dedicated route table below.
  transit_gateway_default_route_table_association = false
  transit_gateway_default_route_table_propagation = false

  tags = merge(
    var.tags,
    each.value.tags,
    { Name = "${var.name}-${each.key}" }
  )
}

###############################################################################
# Dedicated Transit Gateway route table + association/propagation
###############################################################################

resource "aws_ec2_transit_gateway_route_table" "this" {
  transit_gateway_id = local.transit_gateway_id

  tags = merge(var.tags, { Name = "${var.name}-rt" })
}

resource "aws_ec2_transit_gateway_route_table_association" "this" {
  for_each = aws_ec2_transit_gateway_vpc_attachment.this

  transit_gateway_attachment_id  = each.value.id
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.this.id
}

resource "aws_ec2_transit_gateway_route_table_propagation" "this" {
  for_each = aws_ec2_transit_gateway_vpc_attachment.this

  transit_gateway_attachment_id  = each.value.id
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.this.id
}

###############################################################################
# VPC-side routes: send traffic for peer VPC CIDRs through the Transit Gateway
###############################################################################

resource "aws_route" "vpc_to_transit_gateway" {
  for_each = local.vpc_route_table_routes

  route_table_id         = each.value.route_table_id
  destination_cidr_block = each.value.destination_cidr_block
  transit_gateway_id     = local.transit_gateway_id

  # The VPC must already be attached before a route to the TGW can be created.
  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

###############################################################################
# Outputs
###############################################################################

output "transit_gateway_id" {
  description = "ID of the Transit Gateway used for central routing."
  value       = local.transit_gateway_id
}

output "transit_gateway_arn" {
  description = "ARN of the Transit Gateway (null when an existing TGW is reused)."
  value       = try(aws_ec2_transit_gateway.this[0].arn, null)
}

output "transit_gateway_route_table_id" {
  description = "ID of the dedicated Transit Gateway route table."
  value       = aws_ec2_transit_gateway_route_table.this.id
}

output "vpc_attachment_ids" {
  description = "Map of friendly VPC name to Transit Gateway VPC attachment ID."
  value       = { for k, v in aws_ec2_transit_gateway_vpc_attachment.this : k => v.id }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

############################################
# Provider
############################################
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

############################################
# Variables
############################################
variable "aws_region" {
  description = "AWS region to deploy the network and ECS resources into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name of the project, used for tagging resources."
  type        = string
  default     = "dragondrop-compute"
}

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet used by ECS Fargate tasks."
  type        = string
  default     = "10.0.0.0/24"
}

variable "availability_zone" {
  description = "Optional explicit availability zone for the subnet. Empty string lets AWS choose."
  type        = string
  default     = ""
}

variable "ecs_cluster_name" {
  description = "Name of the ECS cluster that will host Fargate tasks."
  type        = string
  default     = "dragondrop-compute-ecs-cluster"
}

variable "log_retention_in_days" {
  description = "CloudWatch Logs retention period for ECS task logs."
  type        = number
  default     = 14
}

############################################
# Data sources
############################################
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

############################################
# VPC
############################################
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

############################################
# Subnet (no public IP auto-assignment)
############################################
resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = var.availability_zone != "" ? var.availability_zone : null
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.project_name}-subnet"
  }
}

############################################
# Internet Gateway
############################################
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-igw"
  }
}

############################################
# Route Table + default route through the IGW
############################################
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.project_name}-rt"
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

############################################
# Security Group for ECS Fargate tasks
# Egress restricted to the VPC CIDR only.
############################################
resource "aws_security_group" "ecs_fargate" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Security group for ECS Fargate tasks; egress limited to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  # No ingress rules are defined.

  egress {
    description = "Allow outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "dragondrop-compute-ecs-fargate-sg"
  }
}

############################################
# CloudWatch Log Group for ECS task logs
############################################
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/${var.ecs_cluster_name}"
  retention_in_days = var.log_retention_in_days

  tags = {
    Name = "${var.project_name}-ecs-logs"
  }
}

############################################
# ECS Cluster (Fargate-capable)
############################################
resource "aws_ecs_cluster" "main" {
  name = var.ecs_cluster_name

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = {
    Name = var.ecs_cluster_name
  }
}

############################################
# IAM: ECS task execution role
############################################
data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    sid     = "ECSTasksAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution" {
  name               = "${var.project_name}-ecs-task-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = {
    Name = "${var.project_name}-ecs-task-execution-role"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_managed" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_policy" "ecs_task_execution_logs" {
  name        = "${var.project_name}-ecs-task-execution-logs"
  description = "Allow the ECS task execution role to write task logs to CloudWatch Logs."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogsWrite"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.ecs.arn}:*"
      }
    ]
  })

  tags = {
    Name = "${var.project_name}-ecs-task-execution-logs"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_logs" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = aws_iam_policy.ecs_task_execution_logs.arn
}

############################################
# IAM: ECS task role (application permissions)
############################################
resource "aws_iam_role" "ecs_task" {
  name               = "${var.project_name}-ecs-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = {
    Name = "${var.project_name}-ecs-task-role"
  }
}

############################################
# Outputs
############################################
output "vpc_id" {
  description = "ID of the dedicated VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the dedicated VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_id" {
  description = "ID of the subnet used by ECS Fargate tasks."
  value       = aws_subnet.main.id
}

output "subnet_cidr" {
  description = "CIDR block of the ECS subnet."
  value       = aws_subnet.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "route_table_id" {
  description = "ID of the route table with the default route through the internet gateway."
  value       = aws_route_table.main.id
}

output "ecs_fargate_security_group_id" {
  description = "ID of the dragondrop-compute-ecs-fargate-sg security group."
  value       = aws_security_group.ecs_fargate.id
}

output "ecs_cluster_arn" {
  description = "ARN of the ECS cluster hosting Fargate tasks."
  value       = aws_ecs_cluster.main.arn
}

output "ecs_cluster_name" {
  description = "Name of the ECS cluster hosting Fargate tasks."
  value       = aws_ecs_cluster.main.name
}

output "ecs_task_execution_role_arn" {
  description = "ARN of the ECS task execution role."
  value       = aws_iam_role.ecs_task_execution.arn
}

output "ecs_task_role_arn" {
  description = "ARN of the ECS task (application) role."
  value       = aws_iam_role.ecs_task.arn
}

output "ecs_log_group_name" {
  description = "Name of the CloudWatch log group for ECS task logs."
  value       = aws_cloudwatch_log_group.ecs.name
}

output "aws_account_id" {
  description = "AWS account ID in which resources are deployed."
  value       = data.aws_caller_identity.current.account_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the DynamoDB tables will be created."
  type        = string
  default     = "us-east-1"
}

variable "raw_metrics_table_name" {
  description = "Name of the DynamoDB table that stores raw metric records."
  type        = string
  default     = "raw_metrics"
}

variable "aggregate_metrics_table_name" {
  description = "Name of the DynamoDB table that stores aggregated metric records."
  type        = string
  default     = "aggregate_metrics"
}

variable "tags" {
  description = "Common tags applied to all resources created by this configuration."
  type        = map(string)
  default = {
    Project     = "metrics-platform"
    Environment = "prod"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# raw_metrics table
# - On-demand billing
# - Server-side encryption
# - String hash key "uuid"
# - Stream enabled with NEW_IMAGE view type
# - TTL enabled on attribute "expdate"
###############################################################################

resource "aws_dynamodb_table" "raw_metrics" {
  name         = var.raw_metrics_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "uuid"

  attribute {
    name = "uuid"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  ttl {
    attribute_name = "expdate"
    enabled        = true
  }

  tags = merge(var.tags, {
    Name = var.raw_metrics_table_name
  })
}

###############################################################################
# aggregate_metrics table
# - On-demand billing
# - Server-side encryption
# - Composite primary key: hash "pk" + range "sk" (both strings)
# - Point-in-time recovery enabled
# - GSI "IdentifierIndex" (hash key "identifier", projection ALL)
###############################################################################

resource "aws_dynamodb_table" "aggregate_metrics" {
  name         = var.aggregate_metrics_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  tags = merge(var.tags, {
    Name = var.aggregate_metrics_table_name
  })
}

###############################################################################
# Outputs
###############################################################################

output "raw_metrics_table_name" {
  description = "Name of the raw metrics DynamoDB table."
  value       = aws_dynamodb_table.raw_metrics.name
}

output "raw_metrics_table_arn" {
  description = "ARN of the raw metrics DynamoDB table."
  value       = aws_dynamodb_table.raw_metrics.arn
}

output "raw_metrics_stream_arn" {
  description = "ARN of the DynamoDB stream attached to the raw metrics table."
  value       = aws_dynamodb_table.raw_metrics.stream_arn
}

output "aggregate_metrics_table_name" {
  description = "Name of the aggregate metrics DynamoDB table."
  value       = aws_dynamodb_table.aggregate_metrics.name
}

output "aggregate_metrics_table_arn" {
  description = "ARN of the aggregate metrics DynamoDB table."
  value       = aws_dynamodb_table.aggregate_metrics.arn
}

output "aggregate_metrics_identifier_index_arn" {
  description = "ARN of the IdentifierIndex global secondary index."
  value       = "${aws_dynamodb_table.aggregate_metrics.arn}/index/IdentifierIndex"
}

##############################################################################
# Terraform / Provider configuration
##############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = var.server_name
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

##############################################################################
# Variables (all have defaults so the configuration is deployable as-is)
##############################################################################

variable "aws_region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "server_name" {
  description = "Name used for the instance and its supporting resources."
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment tag value."
  type        = string
  default     = "test"
}

variable "instance_type" {
  description = "EC2 instance size for the Apache test server."
  type        = string
  default     = "t3.micro"
}

variable "vpc_cidr" {
  description = "CIDR block for the new VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the single internet-routed subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "http_ingress_cidr" {
  description = "Source CIDR allowed to reach HTTP on the instance."
  type        = string
  default     = "0.0.0.0/0"
}

variable "root_volume_size" {
  description = "Size (GiB) of the encrypted root EBS volume."
  type        = number
  default     = 8
}

variable "key_name" {
  description = "Optional existing EC2 key pair name (no SSH ingress is created)."
  type        = string
  default     = null
}

##############################################################################
# Data sources
##############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

##############################################################################
# Networking
##############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.server_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.server_name}-igw"
  }
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.server_name}-subnet"
  }
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.server_name}-rtb"
  }
}

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.web.id
}

##############################################################################
# Security group: HTTP in from anywhere, egress restricted to the VPC CIDR
##############################################################################

resource "aws_security_group" "web" {
  name        = "${var.server_name}-web-sg"
  description = "Allow inbound HTTP from anywhere; restrict egress to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.http_ingress_cidr]
  }

  egress {
    description = "Egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.server_name}-web-sg"
  }
}

##############################################################################
# Apache test instance
##############################################################################

resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.web.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = false
  key_name                    = var.key_name

  # IMDSv2 enforced
  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "disabled"
  }

  # Encrypted root volume
  root_block_device {
    volume_type           = "gp3"
    volume_size           = var.root_volume_size
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-USERDATA
    #!/bin/bash
    set -u

    SERVER_NAME="${var.server_name}"
    echo "Starting user-data provisioning for $SERVER_NAME"

    install_ok=0
    for attempt in 1 2 3; do
      if yum install -y httpd; then
        install_ok=1
        break
      fi
      echo "httpd install attempt $attempt failed; retrying in 15s"
      sleep 15
    done

    if [ "$install_ok" -eq 1 ]; then
      printf '%s\n' \
        '<html>' \
        '  <head><title>'"$SERVER_NAME"'</title></head>' \
        '  <body><h1>Hello from '"$SERVER_NAME"'</h1></body>' \
        '</html>' > /var/www/html/index.html
      systemctl enable httpd
      systemctl restart httpd
      echo "Apache is running on $SERVER_NAME"
    else
      echo "httpd could not be installed: package repositories are unreachable with VPC-only egress"
    fi
  USERDATA

  tags = {
    Name = var.server_name
  }
}

##############################################################################
# Elastic IP attached to the instance
##############################################################################

resource "aws_eip" "web" {
  domain   = "vpc"
  instance = aws_instance.web.id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.server_name}-eip"
  }
}

##############################################################################
# Outputs
##############################################################################

output "instance_id" {
  description = "ID of the Apache test instance."
  value       = aws_instance.web.id
}

output "ami_id" {
  description = "Amazon Linux 2 AMI used for the instance."
  value       = data.aws_ami.amazon_linux_2.id
}

output "elastic_ip" {
  description = "Public Elastic IP attached to the instance."
  value       = aws_eip.web.public_ip
}

output "public_dns" {
  description = "Public DNS name of the instance."
  value       = aws_instance.web.public_dns
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "subnet_id" {
  description = "ID of the created subnet."
  value       = aws_subnet.web.id
}

output "security_group_id" {
  description = "ID of the web security group."
  value       = aws_security_group.web.id
}

output "website_url" {
  description = "Convenience URL for the test web server."
  value       = "http://${aws_eip.web.public_ip}/"
}

## Terraform Program Description

This configuration provisions a small, self-contained messaging integration test environment on AWS:

1. **KMS key** – A customer-managed KMS key (`aws_kms_key`) created with `enable_key_rotation = true`, backed by a key policy that (a) grants the account root full KMS administration (so IAM can delegate usage) and (b) allows the `sns.amazonaws.com` service principal to `kms:GenerateDataKey*` and `kms:Decrypt`. A friendly alias (`aws_kms_alias`) is attached for readability.

2. **Three SNS topics** – All three topics are encrypted at rest with `kms_master_key_id = aws_kms_key.sns_key.arn`:
   - `my-topic-with-policy`
   - `my-topic-with-policy2`
   - `user-updates-topic`

3. **Shared topic policy** – A single `aws_iam_policy_document` data source defines one policy document that allows **all AWS principals** (`Principal: "*"`) the full set of SNS actions (`sns:*`) on the two `my-topic-with-policy*` topic ARNs. The same rendered JSON is applied to both topics via two `aws_sns_topic_policy` resources, so the two topics literally share one policy definition. (The policy is defined at the `aws_sns_topic_policy` level rather than inline on the topic to avoid a resource self-reference cycle when the topic ARNs are included in the policy's `Resource` element.)

4. **Custom delivery policy** – The `user-updates-topic` topic carries a custom `delivery_policy` JSON: an HTTP `defaultHealthyRetryPolicy` (exponential-style linear backoff, min/max delay targets, retry counts), `disableSubscriptionOverrides = false`, and a `defaultThrottlePolicy` with `maxReceivesPerSecond = 10`.

5. **IAM roles** – No additional IAM roles are required: the KMS key policy grants the SNS service principal the encrypt/decrypt permissions SNS needs, and the shared topic policy uses a wildcard principal for test publishers/consumers. (The global provider `default_tags` and a few outputs are included for operability.)

All variables (`aws_region`, `kms_key_deletion_window_in_days`) have defaults, so this template applies with no variable input required.

```hcl
###############################################################################
# Terraform & Provider configuration
###############################################################################
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = "sns-messaging-integration-testing"
      Environment = "test"
      ManagedBy   = "Terraform"
    }
  }
}

###############################################################################
# Variables
###############################################################################
variable "aws_region" {
  description = "AWS region in which the SNS topics and KMS key are deployed."
  type        = string
  default     = "us-east-1"
}

variable "kms_key_deletion_window_in_days" {
  description = "Waiting period (in days) before the customer managed KMS key is permanently deleted."
  type        = number
  default     = 7

  validation {
    condition     = var.kms_key_deletion_window_in_days >= 7 && var.kms_key_deletion_window_in_days <= 30
    error_message = "The KMS key deletion window must be between 7 and 30 days."
  }
}

###############################################################################
# Current account context
###############################################################################
data "aws_caller_identity" "current" {}

###############################################################################
# Customer managed KMS key (rotation enabled) used to encrypt all SNS topics
###############################################################################
data "aws_iam_policy_document" "sns_kms_key_policy" {
  statement {
    sid    = "EnableAccountRootFullKMSAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSServiceToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "sns_key" {
  description             = "Customer managed key for encrypting SNS topics used in messaging integration testing"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms_key_policy.json

  tags = {
    Name = "sns-messaging-integration-testing-key"
  }
}

resource "aws_kms_alias" "sns_key_alias" {
  name          = "alias/sns-messaging-integration-testing"
  target_key_id = aws_kms_key.sns_key.key_id
}

###############################################################################
# SNS topics (all encrypted with the customer managed KMS key)
###############################################################################
resource "aws_sns_topic" "my_topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns_key.arn

  tags = {
    Name = "my-topic-with-policy"
  }
}

resource "aws_sns_topic" "my_topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns_key.arn

  tags = {
    Name = "my-topic-with-policy2"
  }
}

resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns_key.arn

  # Custom delivery policy controlling retry/backoff and throttling behaviour
  delivery_policy = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 60
        numRetries         = 5
        numMaxDelayRetries = 3
        numNoDelayRetries  = 2
        numMinDelayRetries = 1
        backoffFunction    = "linear"
      }
      disableSubscriptionOverrides = false
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 10
      }
    }
  })

  tags = {
    Name = "user-updates-topic"
  }
}

###############################################################################
# Shared topic policy for "my-topic-with-policy" and "my-topic-with-policy2"
# (full SNS actions for every AWS principal, on both topics)
###############################################################################
data "aws_iam_policy_document" "shared_topic_policy" {
  statement {
    sid    = "AllowAllAWSPrincipalsFullSNSAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["SNS:*"]

    resources = [
      aws_sns_topic.my_topic_with_policy.arn,
      aws_sns_topic.my_topic_with_policy2.arn,
    ]
  }
}

resource "aws_sns_topic_policy" "my_topic_with_policy" {
  arn    = aws_sns_topic.my_topic_with_policy.arn
  policy = data.aws_iam_policy_document.shared_topic_policy.json
}

resource "aws_sns_topic_policy" "my_topic_with_policy2" {
  arn    = aws_sns_topic.my_topic_with_policy2.arn
  policy = data.aws_iam_policy_document.shared_topic_policy.json
}

###############################################################################
# Outputs
###############################################################################
output "my_topic_with_policy_arn" {
  description = "ARN of the my-topic-with-policy SNS topic."
  value       = aws_sns_topic.my_topic_with_policy.arn
}

output "my_topic_with_policy2_arn" {
  description = "ARN of the my-topic-with-policy2 SNS topic."
  value       = aws_sns_topic.my_topic_with_policy2.arn
}

output "user_updates_topic_arn" {
  description = "ARN of the user-updates-topic SNS topic."
  value       = aws_sns_topic.user_updates_topic.arn
}

output "sns_kms_key_arn" {
  description = "ARN of the customer managed KMS key used to encrypt the SNS topics."
  value       = aws_kms_key.sns_key.arn
}

output "sns_kms_key_alias" {
  description = "Alias of the customer managed KMS key used to encrypt the SNS topics."
  value       = aws_kms_alias.sns_key_alias.name
}
```

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

#############################################################
# Variables
#############################################################

variable "aws_region" {
  description = "AWS region to deploy the test environment into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "192.168.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "192.168.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet."
  type        = string
  default     = "192.168.4.0/24"
}

variable "project_name" {
  description = "Name prefix used for tagging all resources."
  type        = string
  default     = "test-vpc"
}

#############################################################
# Data sources
#############################################################

# Pick the first available AZ in the selected region so that
# both subnets are placed in a single, defined AZ.
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  availability_zone = data.aws_availability_zones.available.names[0]

  common_tags = {
    Project     = var.project_name
    Environment = "test"
    ManagedBy   = "Terraform"
  }
}

#############################################################
# VPC
#############################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

#############################################################
# Internet Gateway
#############################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

#############################################################
# Subnets (single AZ)
#############################################################

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = local.availability_zone
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = local.availability_zone

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-subnet"
    Tier = "private"
  })
}

#############################################################
# Route Tables
#############################################################

# Public route table with a default route to the Internet Gateway.
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Private route table (no NAT gateway — private subnet stays isolated).
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

#############################################################
# Standalone Elastic IP
#############################################################

resource "aws_eip" "standalone" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-eip"
  })
}

#############################################################
# Outputs
#############################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "availability_zone" {
  description = "The single availability zone used for both subnets."
  value       = local.availability_zone
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet."
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.main.id
}

output "elastic_ip" {
  description = "The standalone Elastic IP address (public IP)."
  value       = aws_eip.standalone.public_ip
}

output "elastic_ip_allocation_id" {
  description = "The allocation ID of the standalone Elastic IP."
  value       = aws_eip.standalone.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Provider configuration
# ---------------------------------------------------------------------------
provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Variables (all with defaults so the config is deployable as-is)
# ---------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy the networking stack into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "container-platform"
}

variable "environment" {
  description = "Deployment environment name (used for tagging)."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "service_discovery_namespace" {
  description = "Private DNS namespace used by Cloud Map service discovery."
  type        = string
  default     = "service.local"
}

# ---------------------------------------------------------------------------
# Data sources / locals
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

# ---------------------------------------------------------------------------
# Subnets (2 public + 2 private, one pair per AZ)
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 1)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 11)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

# ---------------------------------------------------------------------------
# Single NAT gateway (in the first public subnet)
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

# ---------------------------------------------------------------------------
# Route tables
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security group
#   - SSH only from inside the VPC
#   - HTTP / HTTPS / 3000 / 5432 from anywhere
#   - Egress limited to the VPC CIDR
# ---------------------------------------------------------------------------
resource "aws_security_group" "app" {
  name_prefix = "${var.project_name}-app-"
  description = "Application security group: SSH from VPC only; HTTP/HTTPS/app/DB from anywhere; egress limited to VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port from anywhere"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "PostgreSQL port from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Restrict all outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-app-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Private Service Discovery DNS namespace (AWS Cloud Map)
# ---------------------------------------------------------------------------
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = var.service_discovery_namespace
  description = "Private DNS namespace for containerized services managed by ${var.project_name}"
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = var.service_discovery_namespace
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_public_ip" {
  description = "Public Elastic IP of the single NAT gateway."
  value       = aws_eip.nat.public_ip
}

output "app_security_group_id" {
  description = "ID of the application security group."
  value       = aws_security_group.app.id
}

output "service_discovery_namespace_id" {
  description = "ID of the private service discovery DNS namespace."
  value       = aws_service_discovery_private_dns_namespace.main.id
}

output "service_discovery_namespace_arn" {
  description = "ARN of the private service discovery DNS namespace."
  value       = aws_service_discovery_private_dns_namespace.main.arn
}

output "availability_zones_used" {
  description = "Availability zones the subnets were placed in."
  value       = local.azs
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region where the backup resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to all resources in this stack."
  type        = string
  default     = "benchmark-backup"
}

variable "backup_schedule" {
  description = "Cron expression (UTC) that defines when the backup rule runs."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "retention_days" {
  description = "Number of days recovery points are kept. Must be within the vault lock range (7-90)."
  type        = number
  default     = 30

  validation {
    condition     = var.retention_days >= 7 && var.retention_days <= 90
    error_message = "retention_days must be between 7 and 90 days inclusive (vault lock requirement)."
  }
}

variable "min_retention_days" {
  description = "Minimum retention enforced by the backup vault lock."
  type        = number
  default     = 7

  validation {
    condition     = var.min_retention_days >= 7 && var.min_retention_days <= 90
    error_message = "min_retention_days must be between 7 and 90 days inclusive."
  }
}

variable "max_retention_days" {
  description = "Maximum retention enforced by the backup vault lock."
  type        = number
  default     = 90

  validation {
    condition     = var.max_retention_days >= 7 && var.max_retention_days <= 90
    error_message = "max_retention_days must be between 7 and 90 days inclusive."
  }
}

variable "changeable_for_days" {
  description = "Grace period (days) during which the vault lock can still be modified after creation."
  type        = number
  default     = 3
}

variable "backup_tag_key" {
  description = "Tag key used to select which resources are automatically backed up."
  type        = string
  default     = "benchmark-backup"
}

variable "backup_tag_value" {
  description = "Tag value used to select which resources are automatically backed up."
  type        = string
  default     = "true"
}

# ---------------------------------------------------------------------------
# Data sources & locals
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  tags = {
    Project   = var.project_name
    ManagedBy = "Terraform"
  }
}

# ---------------------------------------------------------------------------
# KMS key used to encrypt the backup vault and recovery points
# ---------------------------------------------------------------------------
resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt ${var.project_name} backup vault and recovery points"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAwsBackupService"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid    = "AllowBackupIamRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.backup.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${var.project_name}-backup"
  target_key_id = aws_kms_key.backup.key_id
}

# ---------------------------------------------------------------------------
# IAM role assumed by AWS Backup to create and restore recovery points
# ---------------------------------------------------------------------------
resource "aws_iam_role" "backup" {
  name        = "${var.project_name}-backup-role"
  description = "IAM role assumed by AWS Backup to perform backups and restores"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAwsBackupToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "backup_service_role" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_service_role" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

resource "aws_iam_role_policy" "backup_kms_access" {
  name = "${var.project_name}-backup-kms-access"
  role = aws_iam_role.backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowUseOfBackupKmsKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = aws_kms_key.backup.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# KMS-encrypted backup vault
# ---------------------------------------------------------------------------
resource "aws_backup_vault" "main" {
  name        = "${var.project_name}-vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = local.tags
}

# ---------------------------------------------------------------------------
# Vault lock configuration (WORM) enforcing retention between 7 and 90 days
# ---------------------------------------------------------------------------
resource "aws_backup_vault_lock_configuration" "main" {
  backup_vault_name   = aws_backup_vault.main.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

# ---------------------------------------------------------------------------
# Backup plan with a scheduled rule targeting the vault
# ---------------------------------------------------------------------------
resource "aws_backup_plan" "main" {
  name = "${var.project_name}-plan"

  rule {
    rule_name         = "${var.project_name}-daily-rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.backup_schedule
    start_window      = 60
    completion_window = 180

    lifecycle {
      delete_after = var.retention_days
    }

    recovery_point_tags = local.tags
  }

  tags = local.tags

  depends_on = [aws_backup_vault_lock_configuration.main]
}

# ---------------------------------------------------------------------------
# Backup selection: auto-tag any resource tagged benchmark-backup = true
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "tagged_resources" {
  name         = "${var.project_name}-tagged-selection"
  plan_id      = aws_backup_plan.main.id
  iam_role_arn = aws_iam_role.backup.arn

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = var.backup_tag_value
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "backup_vault_name" {
  description = "Name of the KMS-encrypted, lock-configured backup vault."
  value       = aws_backup_vault.main.name
}

output "backup_vault_arn" {
  description = "ARN of the backup vault."
  value       = aws_backup_vault.main.arn
}

output "backup_plan_id" {
  description = "ID of the AWS Backup plan."
  value       = aws_backup_plan.main.id
}

output "backup_plan_arn" {
  description = "ARN of the AWS Backup plan."
  value       = aws_backup_plan.main.arn
}

output "backup_role_arn" {
  description = "ARN of the IAM role used by AWS Backup."
  value       = aws_iam_role.backup.arn
}

output "backup_kms_key_arn" {
  description = "ARN of the KMS key encrypting the vault."
  value       = aws_kms_key.backup.arn
}

# Terraform Configuration Description

This configuration provisions a complete AWS Cognito identity stack:

- **AWS Provider** pinned to `hashicorp/aws` (~> 5.0) with a configurable `aws_region` variable (default `us-east-1`).
- **Cognito User Pool** with email-based sign-in, a password policy, optional MFA, and schema attributes for `email`. Tags are applied from a shared locals map.
- **Cognito User Pool Client** (no secret, SRP + refresh token flows) used as the identity provider client for the identity pool.
- **Cognito Identity Pool** linked to the user pool via a `cognito_identity_providers` block. `provider_name` is derived from the user pool's endpoint (`cognito-idp.<region>.amazonaws.com/<pool_id>`), and unauthenticated identities are disabled.
- **IAM Role for authenticated identities** with a federated trust policy for `cognito-identity.amazonaws.com`, constrained by `aud` (the identity pool ID) and `amr = authenticated`.
- **IAM inline policy** granting the role access to Cognito Sync (`cognito-sync:*`), Cognito Identity credential APIs, and Mobile Analytics (`mobileanalytics:*`).
- **Cognito Identity Pool Roles Attachment** binding the authenticated role to the identity pool.
- **Outputs** for the user pool ID, client ID, identity pool ID, and authenticated role ARN.

All variables have sensible defaults, and every referenced resource/attribute is fully declared.

```iac_template
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region where Cognito resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Short project/app name used as a prefix for resource names."
  type        = string
  default     = "myapp"
}

variable "environment" {
  description = "Deployment environment (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "user_pool_name" {
  description = "Name of the Cognito User Pool."
  type        = string
  default     = "myapp-user-pool"
}

variable "identity_pool_name" {
  description = "Name of the Cognito Identity Pool (federated identities)."
  type        = string
  default     = "myapp_identity_pool"
}

# ---------------------------------------------------------------------------
# Provider
# ---------------------------------------------------------------------------
provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# ---------------------------------------------------------------------------
# Cognito User Pool
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool" "main" {
  name = var.user_pool_name

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration        = "OPTIONAL"

  password_policy {
    minimum_length                   = 8
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 5
      max_length = 254
    }
  }

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Cognito User Pool Client (used as the identity provider client)
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool_client" "main" {
  name         = "${var.user_pool_name}-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  prevent_user_existence_errors = "ENABLED"

  access_token_validity  = 1
  id_token_validity      = 1
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "hours"
    id_token      = "hours"
    refresh_token = "days"
  }
}

# ---------------------------------------------------------------------------
# Cognito Identity Pool linked to the User Pool
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = var.identity_pool_name
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.main.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# IAM Role assumed by authenticated Cognito identities
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentitiesToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = "${var.project_name}-${var.environment}-cognito-authenticated"
  description        = "Role assumed by authenticated Cognito identities for Cognito Sync and Mobile Analytics access."
  assume_role_policy = data.aws_iam_policy_document.authenticated_assume_role.json

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# IAM Policy granting Cognito Sync / Identity / Mobile Analytics access
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "authenticated_access" {
  statement {
    sid    = "CognitoSyncAndIdentityAccess"
    effect = "Allow"

    actions = [
      "cognito-sync:*",
      "cognito-identity:GetId",
      "cognito-identity:GetCredentialsForIdentity",
      "cognito-identity:GetOpenIdToken",
      "cognito-identity:GetOpenIdTokenForDeveloperIdentity",
      "cognito-identity:ListIdentities",
      "cognito-identity:DescribeIdentity",
      "cognito-identity:LookupDeveloperIdentity",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "MobileAnalyticsAccess"
    effect = "Allow"

    actions = [
      "mobileanalytics:PutEvents",
      "mobileanalytics:GetReports",
      "mobileanalytics:GetMetrics",
      "mobileanalytics:GetFinancialReports",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "authenticated" {
  name   = "${var.project_name}-${var.environment}-cognito-authenticated-policy"
  role   = aws_iam_role.authenticated.id
  policy = data.aws_iam_policy_document.authenticated_access.json
}

# ---------------------------------------------------------------------------
# Attach the authenticated role to the Identity Pool
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    "authenticated" = aws_iam_role.authenticated.arn
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "user_pool_id" {
  description = "ID of the Cognito User Pool."
  value       = aws_cognito_user_pool.main.id
}

output "user_pool_arn" {
  description = "ARN of the Cognito User Pool."
  value       = aws_cognito_user_pool.main.arn
}

output "user_pool_endpoint" {
  description = "Endpoint of the Cognito User Pool (also used as provider_name in the Identity Pool)."
  value       = aws_cognito_user_pool.main.endpoint
}

output "user_pool_client_id" {
  description = "ID of the Cognito User Pool Client."
  value       = aws_cognito_user_pool_client.main.id
}

output "identity_pool_id" {
  description = "ID of the Cognito Identity Pool."
  value       = aws_cognito_identity_pool.main.id
}

output "authenticated_role_arn" {
  description = "ARN of the IAM role assumed by authenticated Cognito identities."
  value       = aws_iam_role.authenticated.arn
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

########################################
# Variables
########################################

variable "aws_region" {
  description = "AWS region to deploy the test network into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the single subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "dhcp_domain_name" {
  description = "DNS domain name supplied by the custom DHCP options set. 'ec2.internal' is the correct value for us-east-1."
  type        = string
  default     = "ec2.internal"
}

variable "dhcp_domain_name_servers" {
  description = "Public DNS servers handed out by the custom DHCP options set."
  type        = list(string)
  default     = ["8.8.8.8", "8.8.4.4"]
}

########################################
# Data sources
########################################

data "aws_availability_zones" "available" {
  state = "available"
}

########################################
# VPC
########################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

########################################
# Subnet (no auto-assigned public IPs)
########################################

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.project_name}-subnet"
  }
}

########################################
# Internet Gateway + Route Table
########################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.project_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.public.id
}

########################################
# Elastic IP
########################################

resource "aws_eip" "main" {
  domain = "vpc"

  tags = {
    Name = "${var.project_name}-eip"
  }
}

########################################
# Custom DHCP Options Set + Association
########################################

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.dhcp_domain_name
  domain_name_servers = var.dhcp_domain_name_servers

  tags = {
    Name = "${var.project_name}-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

########################################
# VPC default security group
########################################

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress {
    description = "HTTP from within the VPC CIDR"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTPS from within the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "SSH from within the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Restrict all egress to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.project_name}-default-sg"
  }
}

########################################
# Outputs
########################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_id" {
  description = "ID of the created subnet."
  value       = aws_subnet.main.id
}

output "subnet_cidr" {
  description = "CIDR block of the created subnet."
  value       = aws_subnet.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "elastic_ip" {
  description = "Public IP address of the allocated Elastic IP."
  value       = aws_eip.main.public_ip
}

output "elastic_ip_allocation_id" {
  description = "Allocation ID of the Elastic IP."
  value       = aws_eip.main.id
}

output "dhcp_options_set_id" {
  description = "ID of the custom DHCP options set."
  value       = aws_vpc_dhcp_options.main.id
}

output "default_security_group_id" {
  description = "ID of the VPC default security group."
  value       = aws_default_security_group.default.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Provider / global configuration
###############################################################################

variable "aws_region" {
  description = "AWS region in which all resources are created."
  type        = string
  default     = "us-east-1"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic that receives published events."
  type        = string
  default     = "event-topic"
}

variable "resource_path_part" {
  description = "Path part of the REST API resource that publishes to SNS."
  type        = string
  default     = "events"
}

variable "api_name" {
  description = "Name of the API Gateway REST API."
  type        = string
  default     = "event-topic-ingest-api"
}

variable "stage_name" {
  description = "API Gateway stage name used for deployments."
  type        = string
  default     = "prod"
}

variable "provisioned_burst_limit" {
  description = "API Gateway throttle burst limit for the stage."
  type        = number
  default     = 200
}

variable "provisioned_rate_limit" {
  description = "API Gateway throttle steady-state rate limit for the stage."
  type        = number
  default     = 100
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "event-ingest"
    Component = "api-gateway-to-sns"
    ManagedBy = "Terraform"
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

data "aws_caller_identity" "current" {}

###############################################################################
# KMS - dedicated customer managed key with automatic rotation
###############################################################################

data "aws_iam_policy_document" "sns_key_policy" {
  # Enables IAM policies in this account (e.g. the API Gateway execution role)
  # to be granted permission to use the key for SNS publishing.
  statement {
    sid    = "EnableRootAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Allows Amazon SNS itself to consume the key on behalf of principals in the
  # account when encrypting messages for the topic.
  statement {
    sid    = "AllowSnsServiceEncryptionUsage"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "sns_key" {
  description             = "Customer managed key used to encrypt the ${var.sns_topic_name} SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_key_policy.json
}

resource "aws_kms_alias" "sns_key_alias" {
  name          = "alias/${var.sns_topic_name}-sns"
  target_key_id = aws_kms_key.sns_key.key_id
}

###############################################################################
# SNS - encrypted topic that receives the published events
###############################################################################

resource "aws_sns_topic" "event_topic" {
  name              = var.sns_topic_name
  kms_master_key_id = aws_kms_key.sns_key.arn
}

###############################################################################
# IAM - role that API Gateway assumes to publish to the SNS topic
###############################################################################

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    sid     = "AllowApiGatewayToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_publish_role" {
  name               = "${var.sns_topic_name}-apigw-publish-role"
  description        = "Execution role that allows API Gateway to publish messages to ${var.sns_topic_name}"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json
}

data "aws_iam_policy_document" "apigw_publish_policy" {
  statement {
    sid       = "PublishToEventTopic"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.event_topic.arn]
  }

  # Publishing to an SSE-KMS encrypted topic requires the publisher to be able
  # to generate a data key and decrypt with the topic's CMK.
  statement {
    sid    = "UseCMKForEncryptedTopic"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.sns_key.arn]
  }
}

resource "aws_iam_role_policy" "apigw_publish" {
  name   = "${var.sns_topic_name}-apigw-publish-policy"
  role   = aws_iam_role.apigw_publish_role.id
  policy = data.aws_iam_policy_document.apigw_publish_policy.json
}

###############################################################################
# API Gateway - REST API that proxies POST requests into the SNS topic
###############################################################################

resource "aws_api_gateway_rest_api" "events_api" {
  name        = var.api_name
  description = "Publishes incoming POST payloads directly to the ${var.sns_topic_name} SNS topic"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "events" {
  rest_api_id = aws_api_gateway_rest_api.events_api.id
  parent_id   = aws_api_gateway_rest_api.events_api.root_resource_id
  path_part   = var.resource_path_part
}

resource "aws_api_gateway_method" "post_events" {
  rest_api_id   = aws_api_gateway_rest_api.events_api.id
  resource_id   = aws_api_gateway_resource.events.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "sns_publish" {
  rest_api_id = aws_api_gateway_rest_api.events_api.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method

  # AWS service integration that calls the SNS Publish API on our behalf.
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${var.aws_region}:sns:action/Publish"
  credentials             = aws_iam_role.apigw_publish_role.arn

  # SNS Publish expects a form-urlencoded body.
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  # Rewrite the incoming JSON payload into a valid SNS Publish request.
  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.event_topic.arn}')&Message=$util.urlEncode($input.body)"
  }
}

resource "aws_api_gateway_method_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.events_api.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "post_200" {
  rest_api_id = aws_api_gateway_rest_api.events_api.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.post_events.http_method
  status_code = aws_api_gateway_method_response.post_200.status_code

  depends_on = [aws_api_gateway_integration.sns_publish]
}

resource "aws_api_gateway_deployment" "events_api" {
  rest_api_id = aws_api_gateway_rest_api.events_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.events.id,
      aws_api_gateway_method.post_events.id,
      aws_api_gateway_integration.sns_publish.id,
      aws_api_gateway_method_response.post_200.id,
      aws_api_gateway_integration_response.post_200.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "events_api" {
  rest_api_id   = aws_api_gateway_rest_api.events_api.id
  deployment_id = aws_api_gateway_deployment.events_api.id
  stage_name    = var.stage_name
  description   = "Stage that publishes POST requests to ${var.sns_topic_name}"
}

resource "aws_api_gateway_method_settings" "events_api" {
  rest_api_id = aws_api_gateway_rest_api.events_api.id
  stage_name  = aws_api_gateway_stage.events_api.stage_name
  method_path = "*/*"

  settings {
    throttling_burst_limit = var.provisioned_burst_limit
    throttling_rate_limit  = var.provisioned_rate_limit
  }
}

###############################################################################
# Outputs
###############################################################################

output "api_invoke_url" {
  description = "URL to POST events to; the request body becomes the SNS message."
  value       = "${aws_api_gateway_stage.events_api.invoke_url}/${var.resource_path_part}"
}

output "rest_api_id" {
  description = "Identifier of the REST API."
  value       = aws_api_gateway_rest_api.events_api.id
}

output "sns_topic_arn" {
  description = "ARN of the encrypted SNS topic receiving the events."
  value       = aws_sns_topic.event_topic.arn
}

output "sns_topic_name" {
  description = "Name of the encrypted SNS topic receiving the events."
  value       = aws_sns_topic.event_topic.name
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key encrypting the SNS topic."
  value       = aws_kms_key.sns_key.arn
}

output "kms_key_alias" {
  description = "Alias of the customer managed KMS key."
  value       = aws_kms_alias.sns_key_alias.name
}

output "api_gateway_publish_role_arn" {
  description = "ARN of the IAM role API Gateway assumes to publish to the SNS topic."
  value       = aws_iam_role.apigw_publish_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the VPC networking stack."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the custom VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the two public subnets, one per availability zone."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the two private subnets, one per availability zone."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "az_count" {
  description = "Number of availability zones (and subnet pairs) to use."
  type        = number
  default     = 2
}

###############################################################################
# Data sources / locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # First N available availability zones in the selected region.
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "terraform-aws-vpc"
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = var.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  count = var.az_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
    Tier = "private"
  }
}

###############################################################################
# Internet gateway and public routing
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "terraform-aws-vpc-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "terraform-aws-vpc-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = var.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT gateway and private routing
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "terraform-aws-vpc-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "terraform-aws-vpc-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "terraform-aws-vpc-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = var.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used for the subnet pairs."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets (public-subnet-1, public-subnet-2)."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (private-subnet-1, private-subnet-2)."
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "Elastic IP address used by the NAT gateway for private subnet egress."
  value       = aws_eip.nat.public_ip
}

###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables (all with default values so the config deploys as-is)
###############################################################################

variable "aws_region" {
  description = "AWS region in which to build the multi-tier VPC."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag of the multi-tier VPC."
  type        = string
  default     = "ntier primary"
}

variable "vpc_cidr" {
  description = "CIDR block of the multi-tier VPC."
  type        = string
  default     = "10.10.0.0/16"
}

variable "subnet_cidrs" {
  description = "CIDR blocks for each subnet in the multi-tier design."
  type        = map(string)
  default = {
    web  = "10.10.1.0/24"
    app  = "10.10.2.0/24"
    db   = "10.10.3.0/24"
    mgmt = "10.10.4.0/24"
    web2 = "10.10.11.0/24"
    app2 = "10.10.12.0/24"
    db2  = "10.10.13.0/24"
  }
}

variable "common_tags" {
  description = "Tags applied to every resource created by this configuration."
  type        = map(string)
  default = {
    Project     = "ntier"
    Environment = "primary"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Use the first two AZs of the region: AZ-A for the primary tiers,
  # AZ-B for the duplicate (second) set of tiers.
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = merge(var.common_tags, { VPC = var.vpc_name })
}

###############################################################################
# VPC + Internet Gateway
###############################################################################

resource "aws_vpc" "ntier_primary" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

resource "aws_internet_gateway" "ntier_primary" {
  vpc_id = aws_vpc.ntier_primary.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

###############################################################################
# Subnets - Tier set 1 (web / app / database / management)
###############################################################################

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = var.subnet_cidrs["web"]
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-web"
    Tier = "web"
    Zone = "primary"
  })
}

resource "aws_subnet" "app" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = var.subnet_cidrs["app"]
  availability_zone = local.azs[0]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-app"
    Tier = "app"
    Zone = "primary"
  })
}

resource "aws_subnet" "db" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = var.subnet_cidrs["db"]
  availability_zone = local.azs[0]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-db"
    Tier = "database"
    Zone = "primary"
  })
}

resource "aws_subnet" "mgmt" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = var.subnet_cidrs["mgmt"]
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-mgmt"
    Tier = "management"
    Zone = "primary"
  })
}

###############################################################################
# Subnets - Tier set 2 (duplicate web / app / database)
###############################################################################

resource "aws_subnet" "web2" {
  vpc_id                  = aws_vpc.ntier_primary.id
  cidr_block              = var.subnet_cidrs["web2"]
  availability_zone       = local.azs[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-web2"
    Tier = "web"
    Zone = "secondary"
  })
}

resource "aws_subnet" "app2" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = var.subnet_cidrs["app2"]
  availability_zone = local.azs[1]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-app2"
    Tier = "app"
    Zone = "secondary"
  })
}

resource "aws_subnet" "db2" {
  vpc_id            = aws_vpc.ntier_primary.id
  cidr_block        = var.subnet_cidrs["db2"]
  availability_zone = local.azs[1]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-db2"
    Tier = "database"
    Zone = "secondary"
  })
}

###############################################################################
# Route tables - both route 0.0.0.0/0 to the Internet Gateway
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ntier_primary.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-rt-public"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ntier_primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ntier_primary.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-rt-private"
  })
}

###############################################################################
# Route table associations - public table: web, management, web2
###############################################################################

resource "aws_route_table_association" "web_public" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "mgmt_public" {
  subnet_id      = aws_subnet.mgmt.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "web2_public" {
  subnet_id      = aws_subnet.web2.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Route table associations - private table: app, db, app2, db2
###############################################################################

resource "aws_route_table_association" "app_private" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db_private" {
  subnet_id      = aws_subnet.db.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "app2_private" {
  subnet_id      = aws_subnet.app2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db2_private" {
  subnet_id      = aws_subnet.db2.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the multi-tier VPC."
  value       = aws_vpc.ntier_primary.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the multi-tier VPC."
  value       = aws_vpc.ntier_primary.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway attached to the VPC."
  value       = aws_internet_gateway.ntier_primary.id
}

output "public_route_table_id" {
  description = "ID of the public route table (web, management, web2)."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table (app, db, app2, db2)."
  value       = aws_route_table.private.id
}

output "public_subnet_ids" {
  description = "IDs of the subnets associated with the public route table."
  value = [
    aws_subnet.web.id,
    aws_subnet.mgmt.id,
    aws_subnet.web2.id
  ]
}

output "private_subnet_ids" {
  description = "IDs of the subnets associated with the private route table."
  value = [
    aws_subnet.app.id,
    aws_subnet.db.id,
    aws_subnet.app2.id,
    aws_subnet.db2.id
  ]
}

output "subnet_ids_by_tier" {
  description = "Map of tier name to subnet ID."
  value = {
    web  = aws_subnet.web.id
    app  = aws_subnet.app.id
    db   = aws_subnet.db.id
    mgmt = aws_subnet.mgmt.id
    web2 = aws_subnet.web2.id
    app2 = aws_subnet.app2.id
    db2  = aws_subnet.db2.id
  }
}

###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables - core creation flags (mutually exclusive)
###############################################################################

variable "region" {
  description = "AWS region in which the KMS key is created."
  type        = string
  default     = "us-east-1"
}

variable "create_key" {
  description = "Create a standard customer managed KMS key backed by AWS-provided key material."
  type        = bool
  default     = true
}

variable "create_external_key" {
  description = "Create an external KMS key backed by imported (base64) key material."
  type        = bool
  default     = false
}

variable "create_replica_key" {
  description = "Create a multi-region replica KMS key referencing a primary key ARN."
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Create a multi-region replica external KMS key with imported key material."
  type        = bool
  default     = false
}

###############################################################################
# Variables - key attributes
###############################################################################

variable "description" {
  description = "Description of the KMS key."
  type        = string
  default     = "Customer managed key managed by Terraform"
}

variable "deletion_window_in_days" {
  description = "Number of days before the key is permanently deleted after scheduling deletion."
  type        = number
  default     = 7
}

variable "key_usage" {
  description = "Intended use of the key (ENCRYPT_DECRYPT, SIGN_VERIFY or GENERATE_VERIFY_MAC). Only used for standard customer managed keys."
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "customer_master_key_spec" {
  description = "Key spec for the standard customer managed key (SYMMETRIC_DEFAULT, RSA_2048, ECC_NIST_P256, HMAC_256, ...)."
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "multi_region" {
  description = "Whether the standard / external key is a multi-region primary key."
  type        = bool
  default     = false
}

variable "enable_key_rotation" {
  description = "Enable automatic key rotation (only honoured for SYMMETRIC_DEFAULT keys)."
  type        = bool
  default     = true
}

variable "rotation_period_in_days" {
  description = "Custom rotation period in days (90-2560). Only applies when key rotation is enabled."
  type        = number
  default     = null
}

variable "bypass_policy_lockout_safety_check" {
  description = "Bypass the policy lockout safety check on the key policy."
  type        = bool
  default     = false
}

variable "is_enabled" {
  description = "Whether the standard customer managed key is enabled."
  type        = bool
  default     = true
}

###############################################################################
# Variables - external / replica key material
###############################################################################

variable "key_material_base64" {
  description = "Base64 encoded 256-bit symmetric key material for external / replica external keys."
  type        = string
  default     = null
  sensitive   = true
}

variable "valid_to" {
  description = "RFC3339 time at which the imported key material expires (external / replica external keys)."
  type        = string
  default     = null
}

variable "primary_key_arn" {
  description = "ARN of the primary multi-region key that a replica key is created from."
  type        = string
  default     = null
}

###############################################################################
# Variables - key policy definition
###############################################################################

variable "policy" {
  description = "Full key policy JSON document. When set, it completely overrides the generated policy."
  type        = string
  default     = null
}

variable "policy_default_root" {
  description = "Attach the default statement granting the AWS account root full access to the key."
  type        = bool
  default     = true
}

variable "key_owners" {
  description = "Principals (full ARNs or bare IAM role names) that own the key."
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "Principals (full ARNs or bare IAM role names) that administer the key."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "Principals (full ARNs or bare IAM role names) that may use the key for cryptographic operations."
  type        = list(string)
  default     = []
}

variable "key_service_users" {
  description = "AWS service principals (e.g. logs.amazonaws.com) allowed to use the key."
  type        = list(string)
  default     = []
}

variable "key_symmetric_encryption_users" {
  description = "Principals allowed to use the key for symmetric encryption / decryption."
  type        = list(string)
  default     = []
}

variable "key_hmac_users" {
  description = "Principals allowed to generate and verify HMACs with the key."
  type        = list(string)
  default     = []
}

variable "key_asymmetric_public_encryption_users" {
  description = "Principals allowed to use the key for asymmetric public encryption."
  type        = list(string)
  default     = []
}

variable "key_asymmetric_sign_verify_users" {
  description = "Principals allowed to sign and verify with the key."
  type        = list(string)
  default     = []
}

variable "key_service_roles_for_autoscaling" {
  description = "Grant the EC2 Auto Scaling service-linked role use of the key (including CreateGrant)."
  type        = bool
  default     = false
}

variable "route53_dnssec_signing_enabled" {
  description = "Allow the Route 53 DNSSEC signing service to describe, get public key and sign with the key."
  type        = bool
  default     = false
}

variable "custom_policy_statements" {
  description = "Additional IAM policy statements merged into the generated key policy."
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = optional(list(string), ["*"])
    principals = optional(object({
      type        = string
      identifiers = list(string)
    }))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = []
}

###############################################################################
# Variables - aliases and grants
###############################################################################

variable "aliases" {
  description = "Exact alias names to create (e.g. \"my-key\" or \"alias/my-key\")."
  type        = list(string)
  default     = []
}

variable "aliases_name_prefixes" {
  description = "Alias name prefixes; a unique suffix is appended automatically."
  type        = list(string)
  default     = []
}

variable "grants" {
  description = "KMS grants to create against the key."
  type = list(object({
    name               = string
    grantee_principal  = string
    operations         = list(string)
    retiring_principal = optional(string)
    constraints = optional(object({
      encryption_context_equals = optional(map(string))
      encryption_context_subset = optional(map(string))
    }))
  }))
  default = []
}

variable "tags" {
  description = "Tags applied to all created resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals - principal normalization
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  key_owners_arns = [
    for p in var.key_owners :
    can(regex("^arn:", p)) ? p : "arn:${local.partition}:iam::${local.account_id}:role/${p}"
  ]

  key_administrators_arns = [
    for p in var.key_administrators :
    can(regex("^arn:", p)) ? p : "arn:${local.partition}:iam::${local.account_id}:role/${p}"
  ]

  key_users_arns = [
    for p in var.key_users :
    can(regex("^arn:", p)) ? p : "arn:${local.partition}:iam::${local.account_id}:role/${p}"
  ]

  key_symmetric_encryption_users_arns = [
    for p in var.key_symmetric_encryption_users :
    can(regex("^arn:", p)) ? p : "arn:${local.partition}:iam::${local.account_id}:role/${p}"
  ]

  key_hmac_users_arns = [
    for p in var.key_hmac_users :
    can(regex("^arn:", p)) ? p : "arn:${local.partition}:iam::${local.account_id}:role/${p}"
  ]

  key_asymmetric_public_encryption_users_arns = [
    for p in var.key_asymmetric_public_encryption_users :
    can(regex("^arn:", p)) ? p : "arn:${local.partition}:iam::${local.account_id}:role/${p}"
  ]

  key_asymmetric_sign_verify_users_arns = [
    for p in var.key_asymmetric_sign_verify_users :
    can(regex("^arn:", p)) ? p : "arn:${local.partition}:iam::${local.account_id}:role/${p}"
  ]

  autoscaling_role_arn = "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"

  enable_rotation = var.enable_key_rotation && var.customer_master_key_spec == "SYMMETRIC_DEFAULT"
}

###############################################################################
# Locals - dynamically generated key policy statements
###############################################################################

locals {
  # --- Default root statement -------------------------------------------------
  default_root_statement = var.policy_default_root ? [{
    Sid       = "DefaultRootAccess"
    Effect    = "Allow"
    Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
    Action    = "kms:*"
    Resource  = "*"
  }] : []

  # --- Key owners -------------------------------------------------------------
  key_owner_statement = length(local.key_owners_arns) > 0 ? [{
    Sid       = "KeyOwner"
    Effect    = "Allow"
    Principal = { AWS = local.key_owners_arns }
    Action = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:RotateKeyOnDemand",
      "kms:GetKeyPolicy",
      "kms:PutKeyPolicy"
    ]
    Resource = "*"
  }] : []

  # --- Key administrators -----------------------------------------------------
  key_administrator_statement = length(local.key_administrators_arns) > 0 ? [{
    Sid       = "KeyAdministrator"
    Effect    = "Allow"
    Principal = { AWS = local.key_administrators_arns }
    Action = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:GetKeyPolicy",
      "kms:PutKeyPolicy"
    ]
    Resource = "*"
  }] : []

  # --- Standard key users -----------------------------------------------------
  key_user_statement = length(local.key_users_arns) > 0 ? [{
    Sid       = "KeyUser"
    Effect    = "Allow"
    Principal = { AWS = local.key_users_arns }
    Action = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    Resource = "*"
  }] : []

  # --- AWS service principals -------------------------------------------------
  key_service_user_statement = length(var.key_service_users) > 0 ? [{
    Sid       = "KeyServiceUser"
    Effect    = "Allow"
    Principal = { Service = var.key_service_users }
    Action = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    Resource = "*"
  }] : []

  # --- Symmetric encryption users --------------------------------------------
  key_symmetric_encryption_statement = length(local.key_symmetric_encryption_users_arns) > 0 ? [{
    Sid       = "SymmetricEncryptionUser"
    Effect    = "Allow"
    Principal = { AWS = local.key_symmetric_encryption_users_arns }
    Action = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    Resource = "*"
  }] : []

  # --- HMAC users -------------------------------------------------------------
  key_hmac_statement = length(local.key_hmac_users_arns) > 0 ? [{
    Sid       = "HmacUser"
    Effect    = "Allow"
    Principal = { AWS = local.key_hmac_users_arns }
    Action = [
      "kms:GenerateMac",
      "kms:VerifyMac",
      "kms:DescribeKey"
    ]
    Resource = "*"
  }] : []

  # --- Asymmetric public encryption users ------------------------------------
  key_asymmetric_public_encryption_statement = length(local.key_asymmetric_public_encryption_users_arns) > 0 ? [{
    Sid       = "AsymmetricPublicEncryptionUser"
    Effect    = "Allow"
    Principal = { AWS = local.key_asymmetric_public_encryption_users_arns }
    Action = [
      "kms:Encrypt",
      "kms:DescribeKey",
      "kms:GetPublicKey"
    ]
    Resource = "*"
  }] : []

  # --- Asymmetric sign / verify users ----------------------------------------
  key_asymmetric_sign_verify_statement = length(local.key_asymmetric_sign_verify_users_arns) > 0 ? [{
    Sid       = "AsymmetricSignVerifyUser"
    Effect    = "Allow"
    Principal = { AWS = local.key_asymmetric_sign_verify_users_arns }
    Action = [
      "kms:Sign",
      "kms:Verify",
      "kms:DescribeKey",
      "kms:GetPublicKey"
    ]
    Resource = "*"
  }] : []

  # --- EC2 Auto Scaling service linked role ----------------------------------
  key_autoscaling_statement = var.key_service_roles_for_autoscaling ? [{
    Sid       = "AllowAutoScalingServiceLinkedRoleUseOfKey"
    Effect    = "Allow"
    Principal = { AWS = local.autoscaling_role_arn }
    Action = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    Resource = "*"
  }] : []

  key_autoscaling_grant_statement = var.key_service_roles_for_autoscaling ? [{
    Sid       = "AllowAutoScalingServiceLinkedRoleAttachmentOfPersistentResources"
    Effect    = "Allow"
    Principal = { AWS = local.autoscaling_role_arn }
    Action    = ["kms:CreateGrant"]
    Resource  = "*"
    Condition = {
      Bool = {
        "kms:GrantIsForAWSResource" = "true"
      }
    }
  }] : []

  # --- Route 53 DNSSEC signing ------------------------------------------------
  route53_dnssec_statements = var.route53_dnssec_signing_enabled ? [
    {
      Sid       = "AllowRoute53DnssecService"
      Effect    = "Allow"
      Principal = { Service = "dnssec-route53.amazonaws.com" }
      Action = [
        "kms:DescribeKey",
        "kms:GetPublicKey",
        "kms:Sign"
      ]
      Resource = "*"
      Condition = {
        StringEquals = {
          "aws:SourceAccount" = local.account_id
        }
      }
    },
    {
      Sid       = "AllowRoute53DnssecServiceToCreateGrant"
      Effect    = "Allow"
      Principal = { Service = "dnssec-route53.amazonaws.com" }
      Action    = ["kms:CreateGrant"]
      Resource  = "*"
      Condition = {
        Bool = {
          "kms:GrantIsForAWSResource" = "true"
        }
      }
    }
  ] : []

  # --- Custom statements ------------------------------------------------------
  custom_statements = [
    for s in var.custom_policy_statements : {
      Sid    = s.sid
      Effect = s.effect
      Principal = s.principals == null ? null : {
        (s.principals.type) = s.principals.identifiers
      }
      Action   = s.actions
      Resource = s.resources
      Condition = length(s.conditions) > 0 ? {
        for test in distinct([for c in s.conditions : c.test]) : test => {
          for c in s.conditions : c.variable => c.values if c.test == test
        }
      } : null
    }
  ]

  # --- Assembled policy -------------------------------------------------------
  policy_statements = concat(
    local.default_root_statement,
    local.key_owner_statement,
    local.key_administrator_statement,
    local.key_user_statement,
    local.key_service_user_statement,
    local.key_symmetric_encryption_statement,
    local.key_hmac_statement,
    local.key_asymmetric_public_encryption_statement,
    local.key_asymmetric_sign_verify_statement,
    local.key_autoscaling_statement,
    local.key_autoscaling_grant_statement,
    local.route53_dnssec_statements,
    local.custom_statements
  )

  generated_policy = jsonencode({
    Version   = "2012-10-17"
    Id        = "key-default-1"
    Statement = local.policy_statements
  })

  effective_policy = var.policy != null ? var.policy : local.generated_policy
}

###############################################################################
# Plan-time validation of mutually exclusive creation flags
###############################################################################

resource "terraform_data" "key_validation" {
  lifecycle {
    precondition {
      condition = length([
        for f in [
          var.create_key,
          var.create_external_key,
          var.create_replica_key,
          var.create_replica_external_key
        ] : f if f
      ]) == 1
      error_message = "Exactly one of create_key, create_external_key, create_replica_key or create_replica_external_key must be set to true."
    }

    precondition {
      condition     = !(var.create_external_key || var.create_replica_external_key) || var.key_material_base64 != null
      error_message = "key_material_base64 must be provided when create_external_key or create_replica_external_key is true."
    }

    precondition {
      condition     = !(var.create_external_key || var.create_replica_external_key) || var.valid_to != null
      error_message = "valid_to must be provided when create_external_key or create_replica_external_key is true."
    }

    precondition {
      condition     = !(var.create_replica_key || var.create_replica_external_key) || var.primary_key_arn != null
      error_message = "primary_key_arn must be provided when create_replica_key or create_replica_external_key is true."
    }
  }
}

###############################################################################
# KMS keys
###############################################################################

resource "aws_kms_key" "this" {
  count = var.create_key ? 1 : 0

  description                        = var.description
  deletion_window_in_days            = var.deletion_window_in_days
  key_usage                          = var.key_usage
  customer_master_key_spec           = var.customer_master_key_spec
  policy                             = local.effective_policy
  multi_region                       = var.multi_region
  enable_key_rotation                = local.enable_rotation
  rotation_period_in_days            = local.enable_rotation ? var.rotation_period_in_days : null
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check
  is_enabled                         = var.is_enabled

  tags = var.tags
}

resource "aws_kms_external_key" "this" {
  count = var.create_external_key ? 1 : 0

  description                        = var.description
  deletion_window_in_days            = var.deletion_window_in_days
  key_material_base64                = var.key_material_base64
  valid_to                           = var.valid_to
  policy                             = local.effective_policy
  multi_region                       = var.multi_region
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check

  tags = var.tags
}

resource "aws_kms_replica_key" "this" {
  count = var.create_replica_key ? 1 : 0

  description                        = var.description
  deletion_window_in_days            = var.deletion_window_in_days
  primary_key_arn                    = var.primary_key_arn
  policy                             = local.effective_policy
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check

  tags = var.tags
}

resource "aws_kms_replica_external_key" "this" {
  count = var.create_replica_external_key ? 1 : 0

  description                        = var.description
  deletion_window_in_days            = var.deletion_window_in_days
  primary_key_arn                    = var.primary_key_arn
  key_material_base64                = var.key_material_base64
  valid_to                           = var.valid_to
  policy                             = local.effective_policy
  bypass_policy_lockout_safety_check = var.bypass_policy_lockout_safety_check

  tags = var.tags
}

###############################################################################
# Locals - resolved key identifiers from whichever key was created
###############################################################################

locals {
  key_id = try(
    aws_kms_key.this[0].key_id,
    try(
      aws_kms_external_key.this[0].key_id,
      try(
        aws_kms_replica_key.this[0].key_id,
        try(aws_kms_replica_external_key.this[0].key_id, null)
      )
    )
  )

  key_arn = try(
    aws_kms_key.this[0].arn,
    try(
      aws_kms_external_key.this[0].arn,
      try(
        aws_kms_replica_key.this[0].arn,
        try(aws_kms_replica_external_key.this[0].arn, null)
      )
    )
  )
}

###############################################################################
# KMS aliases
###############################################################################

resource "aws_kms_alias" "named" {
  for_each = toset(var.aliases)

  name          = startswith(each.value, "alias/") ? each.value : "alias/${each.value}"
  target_key_id = local.key_id

  depends_on = [terraform_data.key_validation]
}

resource "aws_kms_alias" "prefixed" {
  for_each = toset(var.aliases_name_prefixes)

  name_prefix   = startswith(each.value, "alias/") ? each.value : "alias/${each.value}"
  target_key_id = local.key_id

  depends_on = [terraform_data.key_validation]
}

###############################################################################
# KMS grants
###############################################################################

resource "aws_kms_grant" "this" {
  for_each = { for g in var.grants : g.name => g }

  name               = each.value.name
  key_id             = local.key_id
  grantee_principal  = each.value.grantee_principal
  operations         = each.value.operations
  retiring_principal = try(each.value.retiring_principal, null)

  dynamic "constraints" {
    for_each = try(each.value.constraints, null) != null ? [each.value.constraints] : []

    content {
      encryption_context_equals = try(constraints.value.encryption_context_equals, null)
      encryption_context_subset = try(constraints.value.encryption_context_subset, null)
    }
  }

  depends_on = [terraform_data.key_validation]
}

###############################################################################
# Outputs
###############################################################################

output "key_id" {
  description = "ID of the created KMS key."
  value       = local.key_id
}

output "key_arn" {
  description = "ARN of the created KMS key."
  value       = local.key_arn
}

output "key_type" {
  description = "Which flavour of KMS key was provisioned."
  value = (
    var.create_key ? "standard" :
    var.create_external_key ? "external" :
    var.create_replica_key ? "replica" :
    var.create_replica_external_key ? "replica_external" :
    "none"
  )
}

output "key_policy" {
  description = "The effective key policy document applied to the key."
  value       = local.effective_policy
}

output "alias_names" {
  description = "Names of the exact aliases created."
  value       = { for k, v in aws_kms_alias.named : k => v.name }
}

output "alias_prefix_names" {
  description = "Generated names of the prefix-based aliases created."
  value       = { for k, v in aws_kms_alias.prefixed : k => v.name }
}

output "alias_arns" {
  description = "ARNs of all aliases created by the module."
  value = merge(
    { for k, v in aws_kms_alias.named : k => v.arn },
    { for k, v in aws_kms_alias.prefixed : k => v.arn }
  )
}

output "grant_ids" {
  description = "IDs of the KMS grants created."
  value       = { for k, v in aws_kms_grant.this : k => v.grant_id }
}

###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the IAM resources are managed (IAM is global, but a valid region is required)."
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
  }
}

# ---------------------------- Creation toggles ------------------------------

variable "create_iam_developer_group" {
  description = "Toggle to create the developer IAM group."
  type        = bool
  default     = true
}

variable "create_iam_read_only_and_s3_full_access_policy" {
  description = "Toggle to create the IAM read-only + S3 read/write access policy."
  type        = bool
  default     = true
}

variable "create_iam_group_policy_attachment" {
  description = "Toggle to attach the read-only + S3 policy to the developer group."
  type        = bool
  default     = true
}

variable "create_iam_users" {
  description = "Toggle to create the IAM users."
  type        = bool
  default     = true
}

variable "create_ec2_console_screenshot_policy" {
  description = "Toggle to create the EC2 get-console-screenshot policy."
  type        = bool
  default     = true
}

variable "create_iam_user_policy_attachment" {
  description = "Toggle to attach the EC2 console screenshot policy directly to each user."
  type        = bool
  default     = true
}

variable "create_iam_group_membership" {
  description = "Toggle to associate the created users with the developer group."
  type        = bool
  default     = true
}

variable "create_ec2_instance_role" {
  description = "Toggle to create the EC2 instance role (with IAMReadOnlyAccess) and its instance profile."
  type        = bool
  default     = true
}

# ---------------------------- Resource settings -----------------------------

variable "iam_group_name" {
  description = "Name of the developer IAM group."
  type        = string
  default     = "developers"
}

variable "iam_users" {
  description = "List of IAM users to create and add to the developer group."
  type        = list(string)
  default     = ["jack", "jones"]
}

variable "iam_read_only_and_s3_full_access_policy_name" {
  description = "Name of the IAM read-only + S3 read/write access policy."
  type        = string
  default     = "iam_read_only_and_s3_full_access"
}

variable "ec2_console_screenshot_policy_name" {
  description = "Name of the EC2 get-console-screenshot policy."
  type        = string
  default     = "ec2_get_console_screenshot"
}

variable "ec2_instance_role_name" {
  description = "Name of the EC2 instance role."
  type        = string
  default     = "instance_role"
}

variable "ec2_instance_profile_name" {
  description = "Name of the EC2 instance profile wrapping the instance role."
  type        = string
  default     = "instance_role"
}

variable "user_created_by_tag_value" {
  description = "Value of the 'user_created_by' tag placed on every created IAM user."
  type        = string
  default     = "terraform"
}

variable "iam_read_only_managed_policy_arn" {
  description = "AWS managed policy ARN attached to the EC2 instance role."
  type        = string
  default     = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

###############################################################################
# Locals - resolve toggles into usable flags
###############################################################################

locals {
  users = toset(var.iam_users)

  # Group / policy / attachment dependency resolution
  create_group            = var.create_iam_developer_group
  create_access_policy    = var.create_iam_read_only_and_s3_full_access_policy
  create_group_attachment = local.create_group && local.create_access_policy && var.create_iam_group_policy_attachment

  # Users / screenshot policy / direct attachment dependency resolution
  create_users             = var.create_iam_users
  create_screenshot_policy = var.create_ec2_console_screenshot_policy
  create_user_attachment   = local.create_users && local.create_screenshot_policy && var.create_iam_user_policy_attachment

  # Group membership needs the group, the users and the toggle
  create_membership = local.create_group && local.create_users && var.create_iam_group_membership

  # EC2 instance role
  create_instance_role = var.create_ec2_instance_role

  user_tags = merge(var.tags, {
    user_created_by = var.user_created_by_tag_value
  })
}

###############################################################################
# 1. Developer IAM group
###############################################################################

resource "aws_iam_group" "developers" {
  count = local.create_group ? 1 : 0

  name = var.iam_group_name
  path = "/"
}

###############################################################################
# 2. IAM read-only + S3 read/write access policy
###############################################################################

data "aws_iam_policy_document" "read_only_and_s3_full_access" {
  statement {
    sid    = "IAMReadOnlyActions"
    effect = "Allow"

    actions = [
      "iam:Get*",
      "iam:List*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectAcl",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:AbortMultipartUpload",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "S3BucketList"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListAllMyBuckets",
      "s3:GetBucketLocation",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "read_only_and_s3_full_access" {
  count = local.create_access_policy ? 1 : 0

  name        = var.iam_read_only_and_s3_full_access_policy_name
  description = "IAM read-only access plus S3 object read/write access for the developer group."
  path        = "/"
  policy      = data.aws_iam_policy_document.read_only_and_s3_full_access.json

  tags = var.tags
}

###############################################################################
# 3. Group policy attachment
###############################################################################

resource "aws_iam_group_policy_attachment" "developers" {
  count = local.create_group_attachment ? 1 : 0

  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.read_only_and_s3_full_access[0].arn
}

###############################################################################
# 4. IAM users
###############################################################################

resource "aws_iam_user" "users" {
  for_each = local.create_users ? local.users : toset([])

  name = each.value
  path = "/"

  tags = local.user_tags
}

###############################################################################
# 5. EC2 get-console-screenshot policy
###############################################################################

data "aws_iam_policy_document" "ec2_console_screenshot" {
  statement {
    sid    = "EC2GetConsoleScreenshot"
    effect = "Allow"

    actions = [
      "ec2:GetConsoleScreenshot",
      "ec2:GetConsoleOutput",
    ]

    # These actions do not support resource-level permissions.
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ec2_console_screenshot" {
  count = local.create_screenshot_policy ? 1 : 0

  name        = var.ec2_console_screenshot_policy_name
  description = "Allows retrieving EC2 instance console screenshots and console output."
  path        = "/"
  policy      = data.aws_iam_policy_document.ec2_console_screenshot.json

  tags = var.tags
}

###############################################################################
# 6. Direct user policy attachments (console screenshot)
###############################################################################

resource "aws_iam_user_policy_attachment" "console_screenshot" {
  for_each = local.create_user_attachment ? local.users : toset([])

  user       = aws_iam_user.users[each.value].name
  policy_arn = aws_iam_policy.ec2_console_screenshot[0].arn
}

###############################################################################
# 7. Group membership associations
###############################################################################

resource "aws_iam_group_membership" "developers" {
  count = local.create_membership ? 1 : 0

  name  = "${var.iam_group_name}-membership"
  group = aws_iam_group.developers[0].name
  users = [for user in var.iam_users : aws_iam_user.users[user].name]
}

###############################################################################
# 8. EC2 instance role
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "instance_role" {
  count = local.create_instance_role ? 1 : 0

  name               = var.ec2_instance_role_name
  description        = "IAM role assumed by EC2 instances; grants IAM read-only access."
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "iam_read_only_access" {
  count = local.create_instance_role ? 1 : 0

  role       = aws_iam_role.instance_role[0].name
  policy_arn = var.iam_read_only_managed_policy_arn
}

resource "aws_iam_instance_profile" "instance_profile" {
  count = local.create_instance_role ? 1 : 0

  name = var.ec2_instance_profile_name
  role = aws_iam_role.instance_role[0].name
  path = "/"

  tags = var.tags
}

###############################################################################
# Outputs
###############################################################################

output "developer_group_name" {
  description = "Name of the developer IAM group (null when not created)."
  value       = local.create_group ? aws_iam_group.developers[0].name : null
}

output "developer_group_arn" {
  description = "ARN of the developer IAM group (null when not created)."
  value       = local.create_group ? aws_iam_group.developers[0].arn : null
}

output "read_only_and_s3_full_access_policy_arn" {
  description = "ARN of the IAM read-only + S3 read/write policy (null when not created)."
  value       = local.create_access_policy ? aws_iam_policy.read_only_and_s3_full_access[0].arn : null
}

output "ec2_console_screenshot_policy_arn" {
  description = "ARN of the EC2 console screenshot policy (null when not created)."
  value       = local.create_screenshot_policy ? aws_iam_policy.ec2_console_screenshot[0].arn : null
}

output "user_names" {
  description = "Names of the created IAM users."
  value       = [for user in aws_iam_user.users : user.name]
}

output "user_arns" {
  description = "ARNs of the created IAM users, keyed by user name."
  value       = { for key, user in aws_iam_user.users : key => user.arn }
}

output "group_membership_name" {
  description = "Name of the group membership resource (null when not created)."
  value       = local.create_membership ? aws_iam_group_membership.developers[0].name : null
}

output "instance_role_arn" {
  description = "ARN of the EC2 instance role (null when not created)."
  value       = local.create_instance_role ? aws_iam_role.instance_role[0].arn : null
}

output "instance_role_name" {
  description = "Name of the EC2 instance role (null when not created)."
  value       = local.create_instance_role ? aws_iam_role.instance_role[0].name : null
}

output "instance_profile_name" {
  description = "Name of the EC2 instance profile (null when not created)."
  value       = local.create_instance_role ? aws_iam_instance_profile.instance_profile[0].name : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-west-2"
}

variable "vpc_name" {
  description = "Name of the VPC and Blueprint tag"
  type        = string
  default     = "eks-blueprints-vpc"
}

variable "vpc_cidr" {
  description = "VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = var.vpc_cidr

  azs = local.azs

  private_subnets = [
    cidrsubnet(var.vpc_cidr, 4, 0),
    cidrsubnet(var.vpc_cidr, 4, 1),
    cidrsubnet(var.vpc_cidr, 4, 2)
  ]

  public_subnets = [
    cidrsubnet(var.vpc_cidr, 8, 48),
    cidrsubnet(var.vpc_cidr, 8, 49),
    cidrsubnet(var.vpc_cidr, 8, 50)
  ]

  enable_nat_gateway     = true
  single_nat_gateway     = true
  one_nat_gateway_per_az = false

  enable_dns_hostnames = true
  enable_dns_support   = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  egress = []

  tags = {
    Name       = "cluster1_additional_sg"
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }

  lifecycle {
    ignore_changes = [egress]
  }
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  egress = []

  tags = {
    Name       = "cluster2_additional_sg"
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }

  lifecycle {
    ignore_changes = [egress]
  }
}

resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all protocols from cluster2 security group"
}

resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all protocols to cluster2 security group"
}

resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all protocols from cluster1 security group"
}

resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all protocols to cluster1 security group"
}

output "vpc_id" {
  description = "VPC ID"
  value       = module.vpc.vpc_id
}

output "cluster1_additional_sg_id" {
  description = "Cluster1 additional security group ID"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "Cluster2 additional security group ID"
  value       = aws_security_group.cluster2_additional_sg.id
}

```hcl
###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region to deploy the Cognito stack into."
  type        = string
  default     = "us-east-1"
}

variable "pool_name" {
  description = "Name of the Cognito User Pool."
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes to be used as aliases for sign-in."
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes to auto-verify on sign-up."
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Email verification message body."
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Email verification subject."
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "MFA configuration (OFF, ON, OPTIONAL)."
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS authentication message body."
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message body."
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template_by_link" {
  description = "Verification message template values used when email verification is via link."
  type = object({
    email_message = string
    email_subject = string
  })
  default = {
    email_message = "Please click the link to verify your email {##Verify Email##}"
    email_subject = "Your verification link"
  }
}

variable "sms_configuration" {
  description = "SMS configuration map. The block is only created when both external_id and sns_caller_arn are non-empty."
  type = object({
    external_id    = string
    sns_caller_arn = string
  })
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "recovery_mechanisms" {
  description = "Account recovery mechanisms with their priorities."
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    {
      name     = "verified_email"
      priority = 2
    },
    {
      name     = "verified_phone_number"
      priority = 1
    }
  ]
}

variable "invite_message_template" {
  description = "Optional invite message template used by admin-create-user."
  type = object({
    email_message = optional(string)
    email_subject = optional(string)
    sms_message   = optional(string)
  })
  default = null
}

variable "admin_create_user_only" {
  description = "Whether only administrators can create users."
  type        = bool
  default     = false
}

variable "software_token_mfa_enabled" {
  description = "Whether software token (TOTP) MFA is enabled."
  type        = bool
  default     = true
}

variable "username_case_sensitive" {
  description = "Whether usernames are case sensitive. Null means not managed by this configuration."
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Optional dynamic device tracking configuration."
  type = object({
    challenge_required_on_new_device      = optional(bool)
    device_only_remembered_on_user_prompt = optional(bool)
  })
  default = null
}

variable "lambda_config" {
  description = "Optional map of Cognito Lambda trigger configuration. Defaults to empty (no triggers)."
  type        = any
  default     = {}
}

variable "schema" {
  description = "Custom schema attributes for the user pool. Defaults to a required, mutable, string email attribute."
  type = list(object({
    attribute_data_type      = string
    developer_only_attribute = optional(bool, false)
    mutable                  = optional(bool, true)
    name                     = string
    required                 = optional(bool, false)
    string_attribute_constraints = optional(object({
      min_length = string
      max_length = string
    }))
    number_attribute_constraints = optional(object({
      min_value = string
      max_value = string
    }))
  }))
  default = [
    {
      attribute_data_type      = "String"
      developer_only_attribute = false
      mutable                  = true
      name                     = "email"
      required                 = true
      string_attribute_constraints = {
        min_length = "0"
        max_length = "2048"
      }
    }
  ]
}

variable "email_configuration" {
  description = "Optional email configuration for the user pool."
  type = object({
    email_sending_account  = optional(string, "COGNITO_DEFAULT")
    from_email_address     = optional(string)
    reply_to_email_address = optional(string)
    source_arn             = optional(string)
  })
  default = null
}

variable "client_app_names" {
  description = "List of user pool client (app) names. One client is created per entry."
  type        = list(string)
  default     = []
}

variable "client_generate_secret" {
  description = "Whether to generate a client secret."
  type        = bool
  default     = false
}

variable "client_token_validity" {
  description = "Token validity durations for user pool clients."
  type = object({
    access_token  = number
    id_token      = number
    refresh_token = number
  })
  default = {
    access_token  = 120
    id_token      = 120
    refresh_token = 7
  }
}

variable "client_token_validity_units" {
  description = "Units for the corresponding token validity values."
  type = object({
    access_token  = string
    id_token      = string
    refresh_token = string
  })
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "client_allowed_oauth_flows_user_pool_client" {
  description = "Whether the client is allowed to use OAuth flows."
  type        = bool
  default     = false
}

variable "client_enable_token_revocation" {
  description = "Whether token revocation is enabled for the client."
  type        = bool
  default     = true
}

variable "client_explicit_auth_flows" {
  description = "Explicit authentication flows enabled for the client."
  type        = list(string)
  default     = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
}

variable "client_prevent_user_existence_errors" {
  description = "Error message style for unknown users (LEGACY or ENABLED)."
  type        = string
  default     = "LEGACY"
}

variable "client_read_attributes" {
  description = "Read attributes for the client."
  type        = list(string)
  default     = null
}

variable "client_write_attributes" {
  description = "Write attributes for the client."
  type        = list(string)
  default     = null
}

variable "client_callback_urls" {
  description = "Callback URLs for the client."
  type        = list(string)
  default     = null
}

variable "client_logout_urls" {
  description = "Logout URLs for the client."
  type        = list(string)
  default     = null
}

variable "client_allowed_oauth_flows" {
  description = "Allowed OAuth flows for the client."
  type        = list(string)
  default     = null
}

variable "client_allowed_oauth_scopes" {
  description = "Allowed OAuth scopes for the client."
  type        = list(string)
  default     = null
}

variable "client_supported_identity_providers" {
  description = "Supported identity providers for the client."
  type        = list(string)
  default     = null
}

variable "user_group_name" {
  description = "Name of a Cognito user group to create. Empty means no group is created."
  type        = string
  default     = ""
}

variable "user_group_precedence" {
  description = "Precedence of the user group."
  type        = number
  default     = 0
}

variable "user_group_role_arn" {
  description = "Optional IAM role ARN associated with the user group."
  type        = string
  default     = null
}

variable "domain" {
  description = "Cognito user pool domain prefix or custom domain. Empty means no domain is created."
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "Optional ACM certificate ARN for a custom domain."
  type        = string
  default     = null
}

variable "create_route53_record" {
  description = "Whether to create a Route 53 alias A-record for the Cognito domain."
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID for the alias record."
  type        = string
  default     = ""
}

###############################################################################
# Locals
###############################################################################

locals {
  sanitized_pool_name = replace(var.pool_name, " ", "-")

  # Effective SNS caller ARN: prefer the provided ARN, otherwise use the
  # automatically-provisioned Cognito SNS role ARN (when the role exists).
  sms_sns_caller_arn = var.sms_configuration.sns_caller_arn != "" ? var.sms_configuration.sns_caller_arn : (
    length(aws_iam_role.cognito_sms) > 0 ? aws_iam_role.cognito_sms[0].arn : ""
  )

  # SMS configuration is provisioned only when both the external ID and an
  # effective SNS caller ARN are non-empty.
  sms_enabled = var.sms_configuration.external_id != "" && local.sms_sns_caller_arn != ""
}

###############################################################################
# IAM Role for Cognito SNS publishing (created when SMS is enabled but no ARN supplied)
###############################################################################

resource "aws_iam_role" "cognito_sms" {
  count = var.sms_configuration.external_id != "" && var.sms_configuration.sns_caller_arn == "" ? 1 : 0

  name = "${local.sanitized_pool_name}-cognito-sms-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cognito-idp.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cognito_sms" {
  count = length(aws_iam_role.cognito_sms)

  name = "${local.sanitized_pool_name}-cognito-sms-policy"
  role = aws_iam_role.cognito_sms[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Cognito User Pool
###############################################################################

resource "aws_cognito_user_pool" "this" {
  name                      = var.pool_name
  alias_attributes          = var.alias_attributes
  auto_verified_attributes  = var.auto_verified_attributes
  mfa_configuration         = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message

  # Username case sensitivity (only managed when provided)
  dynamic "username_configuration" {
    for_each = var.username_case_sensitive != null ? [var.username_case_sensitive] : []
    content {
      case_sensitive = username_configuration.value
    }
  }

  # Software token (TOTP) MFA
  dynamic "software_token_mfa_configuration" {
    for_each = var.mfa_configuration != "OFF" ? [var.software_token_mfa_enabled] : []
    content {
      enabled = software_token_mfa_configuration.value
    }
  }

  # SMS configuration - only provisioned when configured
  dynamic "sms_configuration" {
    for_each = local.sms_enabled ? [1] : []
    content {
      external_id    = var.sms_configuration.external_id
      sns_caller_arn = local.sms_sns_caller_arn
    }
  }

  # Optional email configuration
  dynamic "email_configuration" {
    for_each = var.email_configuration != null ? [var.email_configuration] : []
    content {
      email_sending_account  = email_configuration.value.email_sending_account
      from_email_address     = try(email_configuration.value.from_email_address, null)
      reply_to_email_address = try(email_configuration.value.reply_to_email_address, null)
      source_arn             = try(email_configuration.value.source_arn, null)
    }
  }

  # Verification message template
  verification_message_template {
    default_email_option  = "CONFIRM_WITH_CODE"
    email_message         = var.email_verification_message
    email_subject         = var.email_verification_subject
    email_message_by_link = var.verification_message_template_by_link.email_message
    email_subject_by_link = var.verification_message_template_by_link.email_subject
    sms_message           = var.sms_verification_message
  }

  # Account recovery settings
  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanisms
      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  # Admin create user config (+ optional invite message template)
  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only

    dynamic "invite_message_template" {
      for_each = var.invite_message_template != null ? [var.invite_message_template] : []
      content {
        email_message = try(invite_message_template.value.email_message, null)
        email_subject = try(invite_message_template.value.email_subject, null)
        sms_message   = try(invite_message_template.value.sms_message, null)
      }
    }
  }

  # Device configuration (optional)
  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []
    content {
      challenge_required_on_new_device      = try(device_configuration.value.challenge_required_on_new_device, null)
      device_only_remembered_on_user_prompt = try(device_configuration.value.device_only_remembered_on_user_prompt, null)
    }
  }

  # Lambda triggers (optional) including custom email/sms sender blocks
  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_config)) > 0 ? [var.lambda_config] : []
    content {
      create_auth_challenge          = lookup(lambda_config.value, "create_auth_challenge", null)
      custom_message                 = lookup(lambda_config.value, "custom_message", null)
      define_auth_challenge          = lookup(lambda_config.value, "define_auth_challenge", null)
      post_authentication            = lookup(lambda_config.value, "post_authentication", null)
      post_confirmation              = lookup(lambda_config.value, "post_confirmation", null)
      pre_authentication             = lookup(lambda_config.value, "pre_authentication", null)
      pre_sign_up                    = lookup(lambda_config.value, "pre_sign_up", null)
      pre_token_generation           = lookup(lambda_config.value, "pre_token_generation", null)
      user_migration                 = lookup(lambda_config.value, "user_migration", null)
      verify_auth_challenge_response = lookup(lambda_config.value, "verify_auth_challenge_response", null)
      kms_key_id                     = lookup(lambda_config.value, "kms_key_id", null)

      dynamic "custom_email_sender" {
        for_each = lookup(lambda_config.value, "custom_email_sender", null) != null ? [lambda_config.value.custom_email_sender] : []
        content {
          lambda_arn     = custom_email_sender.value.lambda_arn
          lambda_version = custom_email_sender.value.lambda_version
        }
      }

      dynamic "custom_sms_sender" {
        for_each = lookup(lambda_config.value, "custom_sms_sender", null) != null ? [lambda_config.value.custom_sms_sender] : []
        content {
          lambda_arn     = custom_sms_sender.value.lambda_arn
          lambda_version = custom_sms_sender.value.lambda_version
        }
      }
    }
  }

  # Schema definitions (with or without min/max constraints)
  dynamic "schema" {
    for_each = var.schema
    content {
      attribute_data_type      = schema.value.attribute_data_type
      developer_only_attribute = schema.value.developer_only_attribute
      mutable                  = schema.value.mutable
      name                     = schema.value.name
      required                 = schema.value.required

      dynamic "string_attribute_constraints" {
        for_each = schema.value.string_attribute_constraints != null ? [schema.value.string_attribute_constraints] : []
        content {
          min_length = string_attribute_constraints.value.min_length
          max_length = string_attribute_constraints.value.max_length
        }
      }

      dynamic "number_attribute_constraints" {
        for_each = schema.value.number_attribute_constraints != null ? [schema.value.number_attribute_constraints] : []
        content {
          min_value = number_attribute_constraints.value.min_value
          max_value = number_attribute_constraints.value.max_value
        }
      }
    }
  }

  lifecycle {
    ignore_changes = [estimated_number_of_users]
  }
}

###############################################################################
# Cognito User Pool Clients (one per app name)
###############################################################################

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(var.client_app_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret                      = var.client_generate_secret
  explicit_auth_flows                  = var.client_explicit_auth_flows
  prevent_user_existence_errors        = var.client_prevent_user_existence_errors
  enable_token_revocation              = var.client_enable_token_revocation
  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth_flows_user_pool_client

  access_token_validity  = var.client_token_validity.access_token
  id_token_validity      = var.client_token_validity.id_token
  refresh_token_validity = var.client_token_validity.refresh_token

  token_validity_units {
    access_token  = var.client_token_validity_units.access_token
    id_token      = var.client_token_validity_units.id_token
    refresh_token = var.client_token_validity_units.refresh_token
  }

  read_attributes              = var.client_read_attributes
  write_attributes             = var.client_write_attributes
  callback_urls                = var.client_callback_urls
  logout_urls                  = var.client_logout_urls
  allowed_oauth_flows          = var.client_allowed_oauth_flows
  allowed_oauth_scopes         = var.client_allowed_oauth_scopes
  supported_identity_providers = var.client_supported_identity_providers
}

###############################################################################
# Cognito User Group (created only when a group name is supplied)
###############################################################################

resource "aws_cognito_user_group" "this" {
  count = var.user_group_name != "" ? 1 : 0

  name         = var.user_group_name
  user_pool_id = aws_cognito_user_pool.this.id
  precedence   = var.user_group_precedence
  role_arn     = var.user_group_role_arn
}

###############################################################################
# Cognito User Pool Domain (created only when a domain is supplied)
###############################################################################

resource "aws_cognito_user_pool_domain" "this" {
  count = var.domain != "" ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.this.id
  certificate_arn = var.domain_certificate_arn
}

###############################################################################
# Route 53 Alias A-Record for the Cognito CloudFront distribution
###############################################################################

resource "aws_route53_record" "this" {
  count = var.create_route53_record && var.route53_zone_id != "" && var.domain != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2" # Fixed CloudFront hosted zone ID
    evaluate_target_health = false
  }
}
```

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the network layout."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag of the VPC."
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag of the Internet Gateway."
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag of the public route table."
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier" {
  description = "Identifier name tag applied to the public subnet."
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag of the NAT gateway."
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  description = "Public IPv4 address pool from which the Elastic IP is allocated."
  type        = string
  default     = "amazon"
}

# --- Subnet A (public) ---
variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A."
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_a_az" {
  description = "Availability zone for Subnet A. Null uses the first available AZ in the region."
  type        = string
  default     = null
}

variable "subnet_a_map_public_ip" {
  description = "Automatically assign public IPs to instances launched in Subnet A."
  type        = bool
  default     = false
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A."
  type        = string
  default     = "Subnet-A-Public"
}

# --- Subnet B (private, hosts NAT gateway) ---
variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B."
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_b_az" {
  description = "Availability zone for Subnet B. Null uses the second available AZ in the region."
  type        = string
  default     = null
}

variable "subnet_b_map_public_ip" {
  description = "Automatically assign public IPs to instances launched in Subnet B."
  type        = bool
  default     = false
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B."
  type        = string
  default     = "Subnet-B-Private"
}

# --- Subnet C (private) ---
variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C."
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_c_az" {
  description = "Availability zone for Subnet C. Null uses the third available AZ in the region."
  type        = string
  default     = null
}

variable "subnet_c_map_public_ip" {
  description = "Automatically assign public IPs to instances launched in Subnet C."
  type        = bool
  default     = false
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C."
  type        = string
  default     = "Subnet-C-Private"
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  subnet_a_az = coalesce(var.subnet_a_az, data.aws_availability_zones.available.names[0])
  subnet_b_az = coalesce(var.subnet_b_az, data.aws_availability_zones.available.names[1])
  subnet_c_az = coalesce(var.subnet_c_az, data.aws_availability_zones.available.names[2])

  common_tags = {
    ManagedBy = "Terraform"
    Project   = var.vpc_name
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = local.subnet_a_az
  map_public_ip_on_launch = var.subnet_a_map_public_ip

  tags = merge(local.common_tags, {
    Name       = var.subnet_a_name
    Identifier = var.public_subnet_identifier
    Tier       = "Public"
  })
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = local.subnet_b_az
  map_public_ip_on_launch = var.subnet_b_map_public_ip

  tags = merge(local.common_tags, {
    Name = var.subnet_b_name
    Tier = "Private"
  })
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = local.subnet_c_az
  map_public_ip_on_launch = var.subnet_c_map_public_ip

  tags = merge(local.common_tags, {
    Name = var.subnet_c_name
    Tier = "Private"
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = var.igw_name
  })
}

###############################################################################
# Route table + default route + association with Subnet A only
###############################################################################

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = var.route_table_name
  })
}

resource "aws_route" "internet_access" {
  route_table_id         = aws_route_table.public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public_subnet_a_assoc" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public_rt.id
}

###############################################################################
# Elastic IP + NAT Gateway (in Subnet B)
###############################################################################

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool

  tags = merge(local.common_tags, {
    Name = "${var.nat_gateway_name}-EIP"
  })
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id

  tags = merge(local.common_tags, {
    Name = var.nat_gateway_name
  })

  depends_on = [aws_internet_gateway.igw]
}

###############################################################################
# Default security group: intra-VPC egress only
###############################################################################

resource "aws_security_group" "default_sg" {
  name        = "DefaultSecurityGroup"
  description = "Default security group allowing egress only within the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "DefaultSecurityGroup"
  })

  egress {
    description = "Allow egress traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
}

###############################################################################
# Outputs
###############################################################################

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT gateway."
  value       = aws_eip.nat.public_ip
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "subnet_ids" {
  description = "IDs of the created subnets."
  value = {
    subnet_a = aws_subnet.subnet_a.id
    subnet_b = aws_subnet.subnet_b.id
    subnet_c = aws_subnet.subnet_c.id
  }
}

output "default_security_group_id" {
  description = "ID of the DefaultSecurityGroup."
  value       = aws_security_group.default_sg.id
}

# AWS Backup Solution Terraform Template

This template provisions a complete, enterprise-ready AWS Backup solution. Below is a summary of what gets created, followed by the deployable HCL.

## Description of Infrastructure

**Encryption layer**
- A **KMS key** with `enable_key_rotation = true` plus an alias, governed by a key policy that grants the account root full access and allows the `backup.amazonaws.com` service to decrypt/generate data keys, describe the key, and create grants.

**Storage layer**
- An **AWS Backup vault** named `my-backup-vault` (overridable) that uses the KMS key for encryption and accepts optional resource tags.

**Permissions layer**
- An **IAM role** assumed by `backup.amazonaws.com` (trust policy generated with `aws_iam_policy_document`) attached to the AWS-managed `AWSBackupServiceRolePolicyForBackup` policy.

**Backup plans (three tiers)**
- `-daily`, `-weekly`, `-monthly` plans (named after the vault) each with an `advanced_backup_setting` enabling **WindowsVSS** for EC2.
- Rules: `daily_backup_rule` (cron `0 12 ? * * *`, delete after **7 days**, optional continuous backup default `false`), `weekly_backup_rule` (cron `0 12 ? * 1 *`, delete after **31 days**), `monthly_backup_rule` (cron `0 12 1 * ? *`, delete after **366 days**).

**Selections**
- `daily_backup_selection`, `weekly_backup_selection`, `monthly_backup_selection` targeting `*` resources via `string_like` conditions on a configurable `tag_key` (default `backup`) with values `daily`/`weekly`/`monthly`.

**Notifications (conditional)**
- An **`aws_backup_vault_notifications`** resource created only when `enable_vault_notifications = true`, publishing to a supplied SNS topic ARN for a configurable event list (defaults to the five failure events).

All variables carry defaults so the configuration deploys without a `terraform.tfvars` file.

```iac_template
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the backup solution."
  type        = string
  default     = "us-east-1"
}

variable "backup_vault_name" {
  description = "Name of the AWS Backup vault."
  type        = string
  default     = "my-backup-vault"
}

variable "backup_vault_tags" {
  description = "Optional tags applied to the backup vault and KMS key."
  type        = map(string)
  default     = {}
}

variable "tag_key" {
  description = "Tag key used by backup selections to match resources."
  type        = string
  default     = "backup"
}

variable "daily_schedule" {
  description = "Cron schedule for the daily backup plan."
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "weekly_schedule" {
  description = "Cron schedule for the weekly backup plan."
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  description = "Cron schedule for the monthly backup plan."
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "daily_delete_after" {
  description = "Number of days after creation before a daily recovery point is deleted."
  type        = number
  default     = 7
}

variable "weekly_delete_after" {
  description = "Number of days after creation before a weekly recovery point is deleted."
  type        = number
  default     = 31
}

variable "monthly_delete_after" {
  description = "Number of days after creation before a monthly recovery point is deleted."
  type        = number
  default     = 366
}

variable "enable_continuous_backup" {
  description = "Enable continuous (point-in-time) backup for the daily rule."
  type        = bool
  default     = false
}

variable "enable_vault_notifications" {
  description = "Whether to create backup vault notifications."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN for backup vault notifications (required when enable_vault_notifications = true)."
  type        = string
  default     = ""
}

variable "backup_vault_events" {
  description = "List of backup vault events that trigger notifications."
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

###############################################################################
# KMS key for backup vault encryption
###############################################################################

data "aws_iam_policy_document" "backup_kms" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAwsBackupService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt the AWS Backup vault and recovery points."
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.backup_kms.json

  tags = merge(var.backup_vault_tags, {
    Name = "${var.backup_vault_name}-kms"
  })
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${var.backup_vault_name}-backup"
  target_key_id = aws_kms_key.backup.key_id
}

###############################################################################
# Backup vault
###############################################################################

resource "aws_backup_vault" "this" {
  name        = var.backup_vault_name
  kms_key_arn = aws_kms_key.backup.arn

  tags = merge(var.backup_vault_tags, {
    Name = var.backup_vault_name
  })
}

###############################################################################
# IAM role for AWS Backup
###############################################################################

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowAwsBackupToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${var.backup_vault_name}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = merge(var.backup_vault_tags, {
    Name = "${var.backup_vault_name}-backup-role"
  })
}

resource "aws_iam_role_policy_attachment" "backup_service_role" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

###############################################################################
# Daily backup plan
###############################################################################

resource "aws_backup_plan" "daily" {
  name = "${var.backup_vault_name}-daily"

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.this.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.enable_continuous_backup

    lifecycle {
      delete_after = var.daily_delete_after
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = merge(var.backup_vault_tags, {
    Name = "${var.backup_vault_name}-daily"
  })
}

resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup.arn

  resources = ["*"]

  condition {
    string_like {
      key   = var.tag_key
      value = "daily"
    }
  }
}

###############################################################################
# Weekly backup plan
###############################################################################

resource "aws_backup_plan" "weekly" {
  name = "${var.backup_vault_name}-weekly"

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = var.weekly_delete_after
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = merge(var.backup_vault_tags, {
    Name = "${var.backup_vault_name}-weekly"
  })
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup.arn

  resources = ["*"]

  condition {
    string_like {
      key   = var.tag_key
      value = "weekly"
    }
  }
}

###############################################################################
# Monthly backup plan
###############################################################################

resource "aws_backup_plan" "monthly" {
  name = "${var.backup_vault_name}-monthly"

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = var.monthly_delete_after
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = merge(var.backup_vault_tags, {
    Name = "${var.backup_vault_name}-monthly"
  })
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup.arn

  resources = ["*"]

  condition {
    string_like {
      key   = var.tag_key
      value = "monthly"
    }
  }
}

###############################################################################
# Optional backup vault notifications
###############################################################################

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

###############################################################################
# Outputs
###############################################################################

output "backup_vault_name" {
  description = "Name of the AWS Backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_vault_arn" {
  description = "ARN of the AWS Backup vault."
  value       = aws_backup_vault.this.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key encrypting the backup vault."
  value       = aws_kms_key.backup.arn
}

output "backup_iam_role_arn" {
  description = "ARN of the IAM role used by AWS Backup."
  value       = aws_iam_role.backup.arn
}

output "backup_plan_ids" {
  description = "Map of tier to backup plan ID."
  value = {
    daily   = aws_backup_plan.daily.id
    weekly  = aws_backup_plan.weekly.id
    monthly = aws_backup_plan.monthly.id
  }
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ---------------------------------------------------------------------------
# Input variables
# ---------------------------------------------------------------------------

variable "region" {
  description = "AWS region to deploy the network into."
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment tag used as a prefix for all resource names."
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets."
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags applied to every resource."
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC and Internet Gateway
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.common_tags,
    {
      Name   = "${var.env}-vpc"
      Region = var.region
    }
  )
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-igw"
    }
  )
}

# ---------------------------------------------------------------------------
# Public subnets (spread across available AZs, no auto public IP)
# ---------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-public-subnet-${count.index}"
    }
  )
}

# ---------------------------------------------------------------------------
# Shared public route table -> Internet Gateway
# ---------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-public-subnets"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Private subnets (spread across available AZs)
# ---------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-private-subnet-${count.index}"
    }
  )
}

# ---------------------------------------------------------------------------
# Dedicated Elastic IPs and NAT Gateways (one per private subnet)
# ---------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count = length(var.private_subnet_cidrs)

  domain = "vpc"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-eip-${count.index}"
    }
  )
}

resource "aws_nat_gateway" "nat" {
  count = length(var.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-gw-${count.index}"
    }
  )

  depends_on = [aws_internet_gateway.igw]
}

# ---------------------------------------------------------------------------
# Per-private-subnet route tables -> their respective NAT Gateway
# ---------------------------------------------------------------------------

resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-private-subnets-${count.index}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.igw.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT Gateways."
  value       = aws_nat_gateway.nat[*].id
}

output "public_route_table_id" {
  description = "ID of the shared public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_ids" {
  description = "IDs of the per-private-subnet route tables."
  value       = aws_route_table.private[*].id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the EKS cluster and IAM role."
  type        = string
  default     = "us-east-1"
}

variable "create_eks" {
  description = "Whether to create the EKS cluster."
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster."
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster. If null, the default version is used."
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "Authentication mode for the EKS cluster access configuration."
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "control_plane_subnet_ids" {
  description = "Subnet IDs for the EKS control plane. If non-empty, these are used instead of subnet_ids."
  type        = list(string)
  default     = []
}

variable "subnet_ids" {
  description = "Fallback subnet IDs for the EKS cluster VPC configuration."
  type        = list(string)
  default     = []
}

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_eks_cluster" "eks" {
  count = var.create_eks ? 1 : 0

  name     = var.cluster_name
  version  = var.cluster_version
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
  }

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller
  ]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Current AWS caller identity (used for dynamic account/user ID tags)
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Locals: shared tags + shared CI/CD policy document
# ---------------------------------------------------------------------------
locals {
  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountId  = data.aws_caller_identity.current.account_id
    UserId     = data.aws_caller_identity.current.user_id
  }

  cicd_policy_document = {
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CICDReadOnlyAccess"
        Effect = "Allow"
        Action = [
          "codebuild:List*",
          "codebuild:BatchGet*",
          "codebuild:Get*",
          "codecommit:List*",
          "codecommit:BatchGet*",
          "codecommit:Get*",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:GetMetricWidgetImage",
          "cloudwatch:ListMetrics",
          "events:List*",
          "events:Describe*",
          "events:TestEventPattern",
          "logs:Describe*",
          "logs:List*",
          "logs:Get*",
          "logs:FilterLogEvents"
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeStarConnectionsUserAccess"
        Effect = "Allow"
        Action = [
          "codestar-connections:GetConnection",
          "codestar-connections:ListConnections"
        ]
        Resource = "arn:aws:codestar-connections:*:*:connection/*"
      },
      {
        Sid    = "CodeStarNotificationsPowerUserAccess"
        Effect = "Allow"
        Action = [
          "codestar-notifications:DescribeNotificationRule"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "codestar-notifications:NotificationsForResource" = "arn:aws:codebuild:*"
          }
        }
      },
      {
        Sid    = "CodeStarNotificationsListAccess"
        Effect = "Allow"
        Action = [
          "codestar-notifications:ListNotificationRules",
          "codestar-notifications:ListEventTypes",
          "codestar-notifications:ListTargets"
        ]
        Resource = "*"
      }
    ]
  }
}

# ---------------------------------------------------------------------------
# Development environment identity
# ---------------------------------------------------------------------------
resource "aws_iam_user" "dev_user" {
  name = "DevUser-rwwise.dev"
  path = "/system/"

  tags = local.common_tags
}

resource "aws_iam_access_key" "dev_user" {
  user = aws_iam_user.dev_user.name
}

resource "aws_iam_user_policy" "dev_user" {
  name   = "dev_cicd_user_policy"
  user   = aws_iam_user.dev_user.name
  policy = jsonencode(local.cicd_policy_document)
}

# ---------------------------------------------------------------------------
# Testing environment identity
# ---------------------------------------------------------------------------
resource "aws_iam_user" "test_user" {
  name = "TestUser-rwwise.dev"
  path = "/system/"

  tags = local.common_tags
}

resource "aws_iam_access_key" "test_user" {
  user = aws_iam_user.test_user.name
}

resource "aws_iam_user_policy" "test_user" {
  name   = "test_cicd_user_policy"
  user   = aws_iam_user.test_user.name
  policy = jsonencode(local.cicd_policy_document)
}

# ---------------------------------------------------------------------------
# Production environment identity
# ---------------------------------------------------------------------------
resource "aws_iam_user" "prod_user" {
  name = "ProdUser-rwwise.dev"
  path = "/system/"

  tags = local.common_tags
}

resource "aws_iam_access_key" "prod_user" {
  user = aws_iam_user.prod_user.name
}

resource "aws_iam_user_policy" "prod_user" {
  name   = "prod_cicd_user_policy"
  user   = aws_iam_user.prod_user.name
  policy = jsonencode(local.cicd_policy_document)
}

# ---------------------------------------------------------------------------
# Outputs (non-sensitive identifiers for CI/CD wiring)
# ---------------------------------------------------------------------------
output "dev_user_arn" {
  description = "ARN of the development CI/CD IAM user"
  value       = aws_iam_user.dev_user.arn
}

output "dev_user_access_key_id" {
  description = "Access key ID for the development CI/CD IAM user"
  value       = aws_iam_access_key.dev_user.id
}

output "test_user_arn" {
  description = "ARN of the testing CI/CD IAM user"
  value       = aws_iam_user.test_user.arn
}

output "test_user_access_key_id" {
  description = "Access key ID for the testing CI/CD IAM user"
  value       = aws_iam_access_key.test_user.id
}

output "prod_user_arn" {
  description = "ARN of the production CI/CD IAM user"
  value       = aws_iam_user.prod_user.arn
}

output "prod_user_access_key_id" {
  description = "Access key ID for the production CI/CD IAM user"
  value       = aws_iam_access_key.prod_user.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

data "aws_partition" "current" {}

locals {
  # Default naming module behavior: fall back to "default" when the name is
  # null or an empty string. `coalesce` returns the first non-null, non-empty value.
  name = coalesce(var.name, "default")

  # Only create a custom EventBridge bus when the resolved name is not "default".
  create_bus = local.name != "default"

  # DNS suffix of the current partition (e.g. "amazonaws.com").
  dns_suffix = data.aws_partition.current.dns_suffix
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which to deploy the EventBridge resources."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Optional module name. Falls back to \"default\" when null or empty."
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to apply to all created resources."
  type        = map(string)
  default     = {}
}

variable "bus" {
  description = "EventBridge bus configuration. Supports an optional event_source_name."
  type = object({
    event_source_name = optional(string, null)
  })
  default = {}

  validation {
    condition     = var.bus != null
    error_message = "The bus configuration must not be null."
  }
}

variable "rules" {
  description = "List of EventBridge rules to create. Each item must include a name and may include description, event_pattern, and schedule_expression."
  type        = list(any)
  default     = []

  validation {
    condition     = var.rules != null
    error_message = "The rules list must not be null."
  }
}

variable "targets" {
  description = "List of EventBridge targets to create. Each item must include a name, rule, and arn."
  type        = list(any)
  default     = []

  validation {
    condition     = var.targets != null
    error_message = "The targets list must not be null."
  }
}

###############################################################################
# EventBridge custom bus (conditional)
###############################################################################

resource "aws_cloudwatch_event_bus" "this" {
  count = local.create_bus ? 1 : 0

  name              = local.name
  event_source_name = try(var.bus.event_source_name, null)

  tags = var.tags
}

###############################################################################
# EventBridge rules (generated from the rules list, keyed by rule name)
###############################################################################

resource "aws_cloudwatch_event_rule" "this" {
  for_each = { for rule in var.rules : rule.name => rule }

  name                = each.value.name
  description         = try(each.value.description, null)
  event_pattern       = try(each.value.event_pattern, null)
  schedule_expression = try(each.value.schedule_expression, null)

  # Attach to the custom bus only if it was created; otherwise use the default bus.
  event_bus_name = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : null

  tags = var.tags
}

###############################################################################
# IAM role assumed by EventBridge to invoke targets
###############################################################################

resource "aws_iam_role" "invoke" {
  name = "${local.name}-invoke"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEventBridgeAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.${local.dns_suffix}"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "invoke_targets" {
  name = "${local.name}-invoke-targets"
  role = aws_iam_role.invoke.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowInvokeTargets"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "states:StartExecution"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# EventBridge targets (generated from the targets list, keyed by target name)
###############################################################################

resource "aws_cloudwatch_event_target" "this" {
  for_each = { for target in var.targets : target.name => target }

  rule      = each.value.rule
  arn       = each.value.arn
  target_id = try(each.value.target_id, each.value.name)

  # Attach to the custom bus only if it was created; otherwise use the default bus.
  event_bus_name = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : null

  # Assign the created IAM role ARN only when the target is an SFN state machine.
  role_arn = strcontains(each.value.arn, "stateMachine") ? aws_iam_role.invoke.arn : null

  depends_on = [
    aws_cloudwatch_event_rule.this,
    aws_iam_role_policy.invoke_targets,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "name" {
  description = "Resolved module name."
  value       = local.name
}

output "bus_name" {
  description = "Name of the EventBridge bus in use (custom or default)."
  value       = local.create_bus ? aws_cloudwatch_event_bus.this[0].name : "default"
}

output "bus_arn" {
  description = "ARN of the custom EventBridge bus, if created."
  value       = local.create_bus ? aws_cloudwatch_event_bus.this[0].arn : null
}

output "invoke_role_arn" {
  description = "ARN of the IAM role assumed by EventBridge to invoke targets."
  value       = aws_iam_role.invoke.arn
}

output "invoke_policy_name" {
  description = "Name of the inline IAM policy granting invoke permissions."
  value       = aws_iam_role_policy.invoke_targets.name
}

output "rule_arns" {
  description = "Map of rule name to ARN for all created EventBridge rules."
  value       = { for k, v in aws_cloudwatch_event_rule.this : k => v.arn }
}

output "target_ids" {
  description = "Map of target name to EventBridge target ID."
  value       = { for k, v in aws_cloudwatch_event_target.this : k => v.id }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0, < 6.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the AWS Backup resources are provisioned."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name value used for dynamic resource naming (prefix-name-suffix)."
  type        = string
  default     = "demo"

  validation {
    condition     = length(trimspace(var.name)) > 0
    error_message = "The name variable must be a non-empty string."
  }
}

variable "kms_key_arn" {
  description = "Optional ARN of the KMS CMK used to encrypt the backup vault. Empty string uses the AWS-managed key."
  type        = string
  default     = ""
}

variable "vault_policy" {
  description = "Optional JSON access policy document attached to the backup vault. Empty string disables the vault policy."
  type        = string
  default     = ""
}

variable "schedule" {
  description = "Cron or rate expression controlling when the backup plan runs."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "start_window" {
  description = "Minutes after a scheduled backup starts before it is cancelled (default 60)."
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Minutes after a scheduled backup starts before it must complete (default 120)."
  type        = number
  default     = 120
}

variable "cold_storage_after" {
  description = "Number of days after creation before a recovery point transitions to cold storage."
  type        = number
  default     = 30
}

variable "delete_after" {
  description = "Number of days after creation before a recovery point is deleted."
  type        = number
  default     = 120
}

variable "destination_vaults" {
  description = "Map of copy-action label to destination backup vault ARN. Defaults to empty (no copy actions)."
  type        = map(string)
  default     = {}
}

variable "selection_tag_type" {
  description = "Type of tag-based resource selection (e.g. STRINGEQUALS)."
  type        = string
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  description = "Tag key used to select resources for backup."
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "Tag value used to select resources for backup."
  type        = string
  default     = "true"
}

variable "sns_topic_arn" {
  description = "Optional SNS topic ARN for vault event notifications. Empty string disables notifications."
  type        = string
  default     = ""
}

variable "backup_vault_events" {
  description = "Vault events published to the SNS topic when notifications are enabled."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "tags" {
  description = "Additional tags applied to taggable resources (merged with the Job tag)."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  job_tag = "${var.name}-backup"

  common_tags = merge(
    var.tags,
    {
      Job = local.job_tag
    }
  )

  vault_kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : null
}

###############################################################################
# IAM role for AWS Backup
###############################################################################

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AWSBackupAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "aws-backup-${var.name}"
  description        = "Service role used by AWS Backup to orchestrate backups for ${var.name}."
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup_service_policy" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

###############################################################################
# Backup vault (+ optional policy, + optional notifications)
###############################################################################

resource "aws_backup_vault" "this" {
  name        = "vault-${var.name}-backup"
  kms_key_arn = local.vault_kms_key_arn

  tags = local.common_tags
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_notifications" "this" {
  count = var.sns_topic_arn != "" ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

###############################################################################
# Backup plan
###############################################################################

resource "aws_backup_plan" "this" {
  name = "plan-${var.name}-backup"

  tags = local.common_tags

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.schedule

    start_window      = var.start_window
    completion_window = var.completion_window

    recovery_point_tags = {
      Job = local.job_tag
    }

    lifecycle {
      cold_storage_after = var.cold_storage_after
      delete_after       = var.delete_after
    }

    dynamic "copy_action" {
      for_each = var.destination_vaults

      content {
        destination_vault_arn = copy_action.value

        lifecycle {
          cold_storage_after = var.cold_storage_after
          delete_after       = var.delete_after
        }
      }
    }
  }
}

###############################################################################
# Backup selection
###############################################################################

resource "aws_backup_selection" "this" {
  name         = "selection-${var.name}-backup"
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.this.id

  condition {}

  selection_tag {
    type  = var.selection_tag_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }
}

###############################################################################
# Outputs
###############################################################################

output "backup_role_arn" {
  description = "ARN of the IAM service role used by AWS Backup."
  value       = aws_iam_role.backup.arn
}

output "backup_role_name" {
  description = "Name of the IAM service role used by AWS Backup."
  value       = aws_iam_role.backup.name
}

output "backup_vault_name" {
  description = "Name of the AWS Backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_vault_arn" {
  description = "ARN of the AWS Backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_plan_id" {
  description = "ID of the AWS Backup plan."
  value       = aws_backup_plan.this.id
}

output "backup_plan_arn" {
  description = "ARN of the AWS Backup plan."
  value       = aws_backup_plan.this.arn
}

output "backup_selection_id" {
  description = "ID of the AWS Backup selection."
  value       = aws_backup_selection.this.id
}

output "job_tag" {
  description = "Job tag value applied to the vault and plan."
  value       = local.job_tag
}

## Description

This Terraform program defines a reusable AWS Transit Gateway module that supports hub-and-spoke routing with optional cross-account sharing via AWS RAM.

**Core toggling logic:** A `create` boolean (default `true`) decides whether a brand-new `aws_ec2_transit_gateway` is provisioned or whether an existing one is discovered through the `aws_ec2_transit_gateway` data source — either by the explicit `id` variable (default `null`) or by a `tag:Name` filter driven by the `name` variable (default `null`). The effective TGW ID/ARN are resolved lazily with a splat + `one()` combination so the module works in both modes.

**Transit Gateway configuration:** Default route table association and propagation are both hard-coded to `disable` so that routing is fully controlled by explicit route tables/propagations. `amazon_side_asn` maps to the `bgp_asn` variable (default `65200`, validated to be a legal private ASN), and `auto_accept_shared_attachments`, `dns_support`, `vpn_ecmp_support` and `transit_gateway_cidr_blocks` (validated as real IPv4/IPv6 CIDRs) are all exposed with sane defaults. Immutable `create`/`ami` style arguments are set inside the `count`-guarded resource. Created TGWs are tagged with global tags plus a `Name` fallback.

**Route tables:** The `route_tables` map-object variable (keys become resource keys) is split into two sets. Entries with `create = true` produce an `aws_ec2_transit_gateway_route_table`; entries with `create = false` produce a `data "aws_ec2_transit_gateway_route_table"` lookup using a `transit-gateway-id` filter paired with a `tag:Name` filter (or an explicit `id` when supplied). Tags for created tables merge global tags, per-item `local_tags`, and a `Name` fallback of the item `name` or the main TGW name.

**RAM sharing:** If `shared_principals` is non-empty, an `aws_ram_resource_share` with `allow_external_principals = true` is created (named from `ram_resource_share_name` or the main resource name), the Transit Gateway is attached via `aws_ram_resource_association`, and every entry is attached via `aws_ram_principal_association`. Outputs expose the TGW ID/ARN, the resolved route-table ID map, and the RAM share ARN.

```hcl
###############################################################################
# AWS Transit Gateway Module
#
# Creates (or looks up) an AWS Transit Gateway with explicit route table
# control, optional per-table create/lookup logic and optional cross-account
# sharing through AWS Resource Access Manager (RAM).
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the Transit Gateway and related resources are deployed."
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Controls whether a new Transit Gateway is created (true) or an existing one is looked up (false)."
  type        = bool
  default     = true
}

variable "id" {
  description = "Identifier of an existing Transit Gateway to look up when create = false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag applied to the created Transit Gateway and used as the tag:Name lookup filter when create = false."
  type        = string
  default     = null
}

variable "description" {
  description = "Description of the Transit Gateway."
  type        = string
  default     = "Managed by Terraform"
}

variable "bgp_asn" {
  description = "Private BGP ASN (Amazon side ASN) for the Transit Gateway."
  type        = number
  default     = 65200

  validation {
    condition = (
      (var.bgp_asn >= 64512 && var.bgp_asn <= 65534) ||
      (var.bgp_asn >= 4200000000 && var.bgp_asn <= 4294967294)
    )
    error_message = "bgp_asn must be a valid private ASN (64512-65534 or 4200000000-4294967294)."
  }
}

variable "auto_accept_shared_attachments" {
  description = "Whether attachments created by other accounts are automatically accepted (enable or disable)."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "auto_accept_shared_attachments must be either 'enable' or 'disable'."
  }
}

variable "dns_support" {
  description = "Whether DNS support is enabled for the Transit Gateway (enable or disable)."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "dns_support must be either 'enable' or 'disable'."
  }
}

variable "vpn_ecmp_support" {
  description = "Whether Equal Cost Multipath (ECMP) support is enabled for VPN attachments (enable or disable)."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "vpn_ecmp_support must be either 'enable' or 'disable'."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "IPv4 or IPv6 CIDR blocks used to create a Connect attachment on the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))])
    error_message = "Every entry in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "tags" {
  description = "Global tags applied to every taggable resource created by this module."
  type        = map(string)
  default     = {}
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables. Each entry either creates a new route table or looks up an existing one. Keys become resource keys used in the route table ID output map."
  type = map(object({
    create     = optional(bool, true)
    id         = optional(string, null)
    name       = optional(string, null)
    local_tags = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of principals (AWS account IDs or ARNs) that the Transit Gateway is shared with through AWS RAM. Each value is attached as a RAM principal association."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Name of the AWS RAM resource share. Defaults to the main Transit Gateway name when null."
  type        = string
  default     = null
}

###############################################################################
# Locals
###############################################################################

locals {
  # Main resource name, used for the TGW and as a fallback for derived resources.
  tgw_name = coalesce(var.name, "transit-gateway")

  # Resolve the effective Transit Gateway ID/ARN from either the created
  # resource or the data source lookup (splat + one() is safe with count = 0).
  tgw_id  = one(concat(aws_ec2_transit_gateway.this[*].id, data.aws_ec2_transit_gateway.this[*].id))
  tgw_arn = one(concat(aws_ec2_transit_gateway.this[*].arn, data.aws_ec2_transit_gateway.this[*].arn))

  # Split the route table map into "create new" and "look up existing" sets.
  create_route_tables   = { for k, v in var.route_tables : k => v if v.create }
  existing_route_tables = { for k, v in var.route_tables : k => v if !v.create }

  # Unified map of route table key -> route table ID regardless of origin.
  route_table_ids = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id },
  )

  # Only create the RAM share when at least one principal is supplied.
  create_ram_share = length(var.shared_principals) > 0
  ram_share_name   = coalesce(var.ram_resource_share_name, local.tgw_name)
}

###############################################################################
# Transit Gateway - create or look up
###############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  description     = var.description
  amazon_side_asn = var.bgp_asn

  # Default route table association and propagation are explicitly disabled so
  # that routing is controlled exclusively by the route tables defined below.
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  auto_accept_shared_attachments = var.auto_accept_shared_attachments
  dns_support                    = var.dns_support
  vpn_ecmp_support               = var.vpn_ecmp_support
  transit_gateway_cidr_blocks    = var.transit_gateway_cidr_blocks

  tags = merge(var.tags, { Name = local.tgw_name })
}

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  id = var.id

  # When no explicit id is supplied, look the Transit Gateway up by its Name tag.
  dynamic "filter" {
    for_each = var.id == null && var.name != null ? { "tag:Name" = var.name } : {}
    content {
      name   = filter.key
      values = [filter.value]
    }
  }
}

###############################################################################
# Transit Gateway route tables - create or look up
###############################################################################

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.create_route_tables

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.tags,
    each.value.local_tags,
    { Name = coalesce(each.value.name, local.tgw_name) }
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.existing_route_tables

  id = each.value.id

  # Filter by transit-gateway-id AND tag:Name when no explicit route table id
  # was supplied for the lookup.
  dynamic "filter" {
    for_each = each.value.id == null ? {
      "transit-gateway-id" = local.tgw_id
      "tag:Name"           = coalesce(each.value.name, local.tgw_name)
    } : {}
    content {
      name   = filter.key
      values = [filter.value]
    }
  }
}

###############################################################################
# AWS RAM resource share (only when shared_principals has entries)
###############################################################################

resource "aws_ram_resource_share" "this" {
  count = local.create_ram_share ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = true

  tags = merge(var.tags, { Name = local.ram_share_name })
}

resource "aws_ram_resource_association" "this" {
  count = local.create_ram_share ? 1 : 0

  resource_arn       = local.tgw_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = one(aws_ram_resource_share.this[*].arn)
}

###############################################################################
# Outputs
###############################################################################

output "transit_gateway_id" {
  description = "Identifier of the Transit Gateway (created or looked up)."
  value       = local.tgw_id
}

output "transit_gateway_arn" {
  description = "ARN of the Transit Gateway (created or looked up)."
  value       = local.tgw_arn
}

output "transit_gateway_name" {
  description = "Resolved name of the main Transit Gateway resource."
  value       = local.tgw_name
}

output "transit_gateway_route_table_ids" {
  description = "Map of route table key to resolved Transit Gateway route table ID."
  value       = local.route_table_ids
}

output "ram_resource_share_arn" {
  description = "ARN of the AWS RAM resource share, if one was created."
  value       = one(aws_ram_resource_share.this[*].arn)
}

output "ram_resource_share_name" {
  description = "Name of the AWS RAM resource share, if one was created."
  value       = one(aws_ram_resource_share.this[*].name)
}

output "ram_principal_associations" {
  description = "Map of shared principal key to the principal value that was associated."
  value       = { for k, v in aws_ram_principal_association.this : k => v.principal }
}
```

###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region where the tiered backup architecture is deployed."
  type        = string
  default     = "us-east-1"
}

variable "project_tag" {
  description = "Project tag applied to the resources created by this template."
  type        = string
  default     = "tiered-backup"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

###############################################################################
# Shared KMS key used by every backup vault
###############################################################################

data "aws_iam_policy_document" "backup_kms" {
  statement {
    sid    = "EnableRootAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAwsBackupServiceToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:CreateGrant",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:ListGrants",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["backup.${var.aws_region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "backup" {
  description             = "Shared KMS key for tiered AWS Backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.backup_kms.json

  tags = {
    Name    = "backup-tiered-shared-key"
    Project = var.project_tag
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/backup-tiered-shared"
  target_key_id = aws_kms_key.backup.key_id
}

###############################################################################
# IAM role assumed by AWS Backup
###############################################################################

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowAwsBackupToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "bronze_backup_role" {
  name               = "Bronze_Backup_Role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name    = "Bronze_Backup_Role"
    Project = var.project_tag
  }
}

resource "aws_iam_role_policy_attachment" "bronze_backup_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "bronze_restore_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

###############################################################################
# Backup vaults (one per service tier, all encrypted with the shared KMS key)
###############################################################################

resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name    = "Bronze_Backup_Vault"
    Tier    = "bronze"
    Project = var.project_tag
  }
}

resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name    = "Silver_Backup_Vault"
    Tier    = "silver"
    Project = var.project_tag
  }
}

resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name    = "Gold_Backup_Vault"
    Tier    = "gold"
    Project = var.project_tag
  }
}

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name    = "Premium"
    Tier    = "premium"
    Project = var.project_tag
  }
}

###############################################################################
# Bronze tier - weekly backups retained for 10 days
###############################################################################

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      delete_after = 10
    }
  }

  tags = {
    Name    = "Bronze_Backup"
    Tier    = "bronze"
    Project = var.project_tag
  }
}

resource "aws_backup_selection" "bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]

  list_of_tags {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

###############################################################################
# Silver tier - daily backups retained for 7 days
###############################################################################

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      delete_after = 7
    }
  }

  tags = {
    Name    = "Silver_Backup_Plan"
    Tier    = "silver"
    Project = var.project_tag
  }
}

resource "aws_backup_selection" "silver" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]

  list_of_tags {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }
}

###############################################################################
# Gold tier - daily / monthly / yearly retention
###############################################################################

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      delete_after = 2555
    }
  }

  tags = {
    Name    = "Gold_Backup"
    Tier    = "gold"
    Project = var.project_tag
  }
}

resource "aws_backup_selection" "gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]

  list_of_tags {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

###############################################################################
# Premium tier - 4-hourly / daily / monthly / yearly with cold storage
###############################################################################

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"
    iam_role_arn      = aws_iam_role.bronze_backup_role.arn

    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }

  tags = {
    Name    = "Premium"
    Tier    = "premium"
    Project = var.project_tag
  }
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  resources    = ["*"]

  list_of_tags {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}

###############################################################################
# Outputs
###############################################################################

output "backup_kms_key_arn" {
  description = "ARN of the shared KMS key used to encrypt all backup vaults."
  value       = aws_kms_key.backup.arn
}

output "backup_role_arn" {
  description = "ARN of the IAM role assumed by AWS Backup."
  value       = aws_iam_role.bronze_backup_role.arn
}

output "backup_vault_arns" {
  description = "ARNs of the tiered backup vaults."
  value = {
    bronze  = aws_backup_vault.bronze.arn
    silver  = aws_backup_vault.silver.arn
    gold    = aws_backup_vault.gold.arn
    premium = aws_backup_vault.premium.arn
  }
}

output "backup_plan_ids" {
  description = "IDs of the tiered backup plans."
  value = {
    bronze  = aws_backup_plan.bronze.id
    silver  = aws_backup_plan.silver.id
    gold    = aws_backup_plan.gold.id
    premium = aws_backup_plan.premium.id
  }
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the IAM role will be created."
  type        = string
  default     = "us-east-1"
}

variable "iam_role_name" {
  description = "Name of the cross-account IAM role for Prisma Cloud."
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Whether to create the Prisma Cloud remediation policy."
  type        = bool
  default     = false
}

resource "random_string" "external_id" {
  length  = 32
  special = false
  upper   = true
  lower   = true
  numeric = true
}

resource "aws_iam_role" "prisma_cloud" {
  name = var.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::188619942792:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.external_id.result
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

resource "aws_iam_role_policy" "prisma_cloud_read_only" {
  name = "PrismaCloud-IAM-ReadOnly-Policy"
  role = aws_iam_role.prisma_cloud.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "apigateway:GET",
          "cognito-identity:ListTagsForResource",
          "cognito-idp:ListTagsForResource",
          "ecr:DescribeImages",
          "ecr:GetLifecyclePolicy",
          "elasticbeanstalk:ListTagsForResource",
          "elasticfilesystem:DescribeTags",
          "glacier:GetVaultLock",
          "glacier:ListTagsForVault",
          "glue:GetSecurityConfigurations",
          "logs:GetLogEvents",
          "mq:listBrokers",
          "mq:describeBroker",
          "ram:GetResourceShares",
          "secretsmanager:DescribeSecret",
          "ssm:GetParameters",
          "ssm:ListTagsForResource",
          "sqs:SendMessage",
          "elasticmapreduce:ListSecurityConfigurations",
          "sns:listSubscriptions",
          "wafv2:ListResourcesForWebACL",
          "wafv2:ListWebACLs"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "prisma_cloud_remediation" {
  count = var.read_write ? 1 : 0

  name = "PrismaCloud-IAM-Remediation-Policy"
  role = aws_iam_role.prisma_cloud.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:UpdateAccountPasswordPolicy",
          "ec2:ModifyImageAttribute",
          "rds:ModifyDBSnapshotAttribute",
          "s3:PutBucketAcl",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

########################################
# Variables
########################################

variable "region" {
  description = "AWS region to deploy the backend development VPC into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "development-be-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_name" {
  description = "Name of the public subnet"
  type        = string
  default     = "development-be-public-subnet"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_name" {
  description = "Name of the private subnet"
  type        = string
  default     = "development-be-private-subnet"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

variable "igw_name" {
  description = "Name of the internet gateway"
  type        = string
  default     = "development-be-ig"
}

variable "public_rt_name" {
  description = "Name of the public route table"
  type        = string
  default     = "development-be-public-rt"
}

variable "sg_name" {
  description = "Name of the security group"
  type        = string
  default     = "http_access"
}

variable "sg_tag_name" {
  description = "Name tag applied to the security group"
  type        = string
  default     = "development-be-sg"
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "development"
}

########################################
# Data sources
########################################

data "aws_availability_zones" "available" {
  state = "available"
}

########################################
# VPC
########################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = var.vpc_name
    Environment = var.environment
  }
}

########################################
# Subnets
########################################

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = var.public_subnet_name
    Type        = "public"
    Environment = var.environment
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = var.private_subnet_name
    Type        = "private"
    Environment = var.environment
  }
}

########################################
# Internet Gateway
########################################

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = var.igw_name
    Environment = var.environment
  }
}

########################################
# Public Route Table (associated with the public subnet only)
########################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = var.public_rt_name
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

########################################
# Security Group
########################################

resource "aws_security_group" "http_access" {
  name        = var.sg_name
  description = "Allow SSH from VPC CIDR and HTTP from anywhere; restrict egress to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  # SSH only from within the VPC CIDR
  ingress {
    description = "SSH from within VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # HTTP from anywhere
  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Egress restricted to the VPC CIDR only
  egress {
    description = "Restrict all outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name        = var.sg_tag_name
    Environment = var.environment
  }
}

########################################
# Outputs
########################################

output "vpc_id" {
  description = "ID of the development-be VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the development-be public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the development-be private subnet"
  value       = aws_subnet.private.id
}

################################################################################
# Terraform & AWS Provider configuration
################################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

################################################################################
# Data sources
################################################################################

data "aws_caller_identity" "current" {}

################################################################################
# Variables - general
################################################################################

variable "region" {
  description = "AWS region in which the Amazon SNS resources are deployed"
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Controls whether the Amazon SNS resources in this configuration are created"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to assign to all resources created by this configuration"
  type        = map(string)
  default     = {}
}

################################################################################
# Variables - core topic
################################################################################

variable "name" {
  description = "The name of the topic. When `use_name_prefix` is `true`, this value is used as the prefix instead. If both `name` and `name_prefix` resolve to `null`, the provider generates a random name"
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether the `name` variable is used as a prefix (with a provider generated suffix) rather than the full topic name"
  type        = bool
  default     = false
}

variable "display_name" {
  description = "The display name for the topic"
  type        = string
  default     = null
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics. Ignored when `fifo_topic` is `false`"
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "The SNS delivery policy as a JSON string"
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK"
  type        = string
  default     = null
}

variable "signature_version" {
  description = "If SignatureVersion should be 1 or 2. Forcefully set to `null` when `fifo_topic` is `true`"
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: `PassThrough`, `Active`"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic"
  type        = bool
  default     = false
}

variable "fifo_throughput_scope" {
  description = "Specifies the throughput scope of a FIFO topic. Valid values: `Topic`, `MessageGroup`. Ignored when `fifo_topic` is `false`"
  type        = string
  default     = null
}

################################################################################
# Variables - protocol feedback configuration
################################################################################

variable "application_feedback" {
  description = "Map of SNS application endpoint feedback configuration"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number, 0)
  })
  default = null
}

variable "firehose_feedback" {
  description = "Map of SNS Firehose feedback configuration"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number, 0)
  })
  default = null
}

variable "http_feedback" {
  description = "Map of SNS HTTP/S endpoint feedback configuration"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number, 0)
  })
  default = null
}

variable "lambda_feedback" {
  description = "Map of SNS Lambda endpoint feedback configuration"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number, 0)
  })
  default = null
}

variable "sqs_feedback" {
  description = "Map of SNS SQS endpoint feedback configuration"
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number, 0)
  })
  default = null
}

################################################################################
# Variables - feedback IAM role (optional)
################################################################################

variable "create_feedback_role" {
  description = "Determines whether an IAM role for SNS feedback delivery to CloudWatch Logs is created. The resulting role ARN can be supplied to the protocol feedback configuration blocks"
  type        = bool
  default     = false
}

variable "feedback_role_name" {
  description = "Name of the optional feedback IAM role. If `null`, a name is generated from the topic name"
  type        = string
  default     = null
}

################################################################################
# Variables - topic policy
################################################################################

variable "create_topic_policy" {
  description = "Determines whether an SNS topic policy is constructed and attached. When `false`, the externally supplied `topic_policy` string is used instead"
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "The fully-formed AWS IAM policy (as JSON) to attach to the topic when `create_topic_policy` is `false`"
  type        = string
  default     = null
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents (as JSON strings) that will be merged together with the generated statements"
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents (as JSON strings) used to override statements of the same SID in the generated policy"
  type        = list(string)
  default     = []
}

variable "topic_policy_statements" {
  description = "A map of IAM policy statements to include in the generated topic policy"
  type        = any
  default     = {}
}

variable "enable_default_topic_policy" {
  description = "Determines whether the default topic policy statement (standard SNS topic actions for all AWS principals conditioned on the account owner ID) is added"
  type        = bool
  default     = true
}

################################################################################
# Variables - subscriptions
################################################################################

variable "create_subscription" {
  description = "Determines whether SNS topic subscriptions are created"
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "A map of subscriptions to create. The map key is used as the subscription identifier"
  type = map(object({
    confirmation_timeout_in_minutes = optional(number)
    delivery_policy                 = optional(string)
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool, false)
    filter_policy                   = optional(string)
    filter_policy_scope             = optional(string)
    protocol                        = string
    raw_message_delivery            = optional(bool, false)
    redrive_policy                  = optional(string)
    subscription_role_arn           = optional(string)
  }))
  default = {}
}

################################################################################
# Variables - data protection policy
################################################################################

variable "data_protection_policy" {
  description = "Specifies the data protection policy (as JSON) for the topic. Only applied when the topic is not a FIFO topic"
  type        = string
  default     = null
}

################################################################################
# Locals
################################################################################

locals {
  create = var.create

  topic_name        = var.use_name_prefix ? null : var.name
  topic_name_prefix = (var.use_name_prefix && var.name != null) ? "${var.name}-" : null

  account_id = data.aws_caller_identity.current.account_id

  feedback_role_name = coalesce(var.feedback_role_name, "${coalesce(var.name, "sns-topic")}-feedback")
}

################################################################################
# SNS Topic
################################################################################

resource "aws_sns_topic" "this" {
  count = local.create ? 1 : 0

  name        = local.topic_name
  name_prefix = local.topic_name_prefix

  display_name                = var.display_name
  delivery_policy             = var.delivery_policy
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : false
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = var.fifo_topic ? null : var.signature_version
  tracing_config              = var.tracing_config
  fifo_throughput_scope       = var.fifo_topic ? var.fifo_throughput_scope : null

  dynamic "application_feedback" {
    for_each = var.application_feedback != null ? [var.application_feedback] : []

    content {
      failure_role_arn    = application_feedback.value.failure_role_arn
      success_role_arn    = application_feedback.value.success_role_arn
      success_sample_rate = application_feedback.value.success_sample_rate
    }
  }

  dynamic "firehose_feedback" {
    for_each = var.firehose_feedback != null ? [var.firehose_feedback] : []

    content {
      failure_role_arn    = firehose_feedback.value.failure_role_arn
      success_role_arn    = firehose_feedback.value.success_role_arn
      success_sample_rate = firehose_feedback.value.success_sample_rate
    }
  }

  dynamic "http_feedback" {
    for_each = var.http_feedback != null ? [var.http_feedback] : []

    content {
      failure_role_arn    = http_feedback.value.failure_role_arn
      success_role_arn    = http_feedback.value.success_role_arn
      success_sample_rate = http_feedback.value.success_sample_rate
    }
  }

  dynamic "lambda_feedback" {
    for_each = var.lambda_feedback != null ? [var.lambda_feedback] : []

    content {
      failure_role_arn    = lambda_feedback.value.failure_role_arn
      success_role_arn    = lambda_feedback.value.success_role_arn
      success_sample_rate = lambda_feedback.value.success_sample_rate
    }
  }

  dynamic "sqs_feedback" {
    for_each = var.sqs_feedback != null ? [var.sqs_feedback] : []

    content {
      failure_role_arn    = sqs_feedback.value.failure_role_arn
      success_role_arn    = sqs_feedback.value.success_role_arn
      success_sample_rate = sqs_feedback.value.success_sample_rate
    }
  }

  tags = var.tags
}

################################################################################
# SNS Topic Policy
################################################################################

data "aws_iam_policy_document" "topic" {
  count = local.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.topic_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.condition, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid    = "DefaultTopicPolicy"
      effect = "Allow"

      actions = [
        "SNS:GetTopicAttributes",
        "SNS:SetTopicAttributes",
        "SNS:AddPermission",
        "SNS:RemovePermission",
        "SNS:DeleteTopic",
        "SNS:Subscribe",
        "SNS:ListSubscriptionsByTopic",
        "SNS:Publish",
      ]

      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "StringEquals"
        variable = "AWS:SourceOwner"
        values   = [local.account_id]
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = local.create && (var.create_topic_policy || var.topic_policy != null) ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.create_topic_policy ? data.aws_iam_policy_document.topic[0].json : var.topic_policy
}

################################################################################
# SNS Topic Subscriptions
################################################################################

resource "aws_sns_topic_subscription" "this" {
  for_each = local.create && var.create_subscription ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn

  confirmation_timeout_in_minutes = try(each.value.confirmation_timeout_in_minutes, null)
  delivery_policy                 = try(each.value.delivery_policy, null)
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = try(each.value.endpoint_auto_confirms, false)
  filter_policy                   = try(each.value.filter_policy, null)
  filter_policy_scope             = try(each.value.filter_policy_scope, null)
  protocol                        = each.value.protocol
  raw_message_delivery            = try(each.value.raw_message_delivery, false)
  redrive_policy                  = try(each.value.redrive_policy, null)
  subscription_role_arn           = try(each.value.subscription_role_arn, null)
}

################################################################################
# SNS Topic Data Protection Policy
################################################################################

resource "aws_sns_topic_data_protection_policy" "this" {
  count = local.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

################################################################################
# Optional feedback IAM role
################################################################################

data "aws_iam_policy_document" "feedback_assume_role" {
  count = local.create && var.create_feedback_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "feedback" {
  count = local.create && var.create_feedback_role ? 1 : 0

  statement {
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:PutMetricFilter",
      "logs:PutRetentionPolicy",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role" "feedback" {
  count = local.create && var.create_feedback_role ? 1 : 0

  name               = local.feedback_role_name
  assume_role_policy = data.aws_iam_policy_document.feedback_assume_role[0].json

  tags = var.tags
}

resource "aws_iam_role_policy" "feedback" {
  count = local.create && var.create_feedback_role ? 1 : 0

  name   = local.feedback_role_name
  role   = aws_iam_role.feedback[0].id
  policy = data.aws_iam_policy_document.feedback[0].json
}

################################################################################
# Outputs
################################################################################

output "topic_arn" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_name" {
  description = "The name of the SNS topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_id" {
  description = "The ID of the SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_owner" {
  description = "The AWS account ID of the SNS topic owner"
  value       = try(aws_sns_topic.this[0].owner, null)
}

output "topic_policy" {
  description = "The JSON policy document attached to the SNS topic"
  value       = try(aws_sns_topic_policy.this[0].policy, null)
}

output "subscriptions" {
  description = "A map of the SNS topic subscriptions that were created"
  value       = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}

output "data_protection_policy" {
  description = "The JSON data protection policy attached to the SNS topic"
  value       = try(aws_sns_topic_data_protection_policy.this[0].policy, null)
}

output "feedback_role_arn" {
  description = "The ARN of the optional IAM role created for SNS feedback delivery"
  value       = try(aws_iam_role.feedback[0].arn, null)
}

###############################################################################
# Terraform / Provider configuration
###############################################################################
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Data sources
###############################################################################
data "aws_canonical_user_id" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################
variable "region" {
  description = "AWS region in which the bucket and supporting resources are deployed."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "Explicit bucket name. When null/empty, the module generates 'corebucket-<4-byte hex>'."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, an additional random string suffix is appended to the resolved bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "S3 request payer configuration: BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "When true, the bucket is encrypted with SSE-KMS (supplied KMS key or module-created rotating CMK)."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of an existing KMS key. When empty and encryption is true, the module creates and rotates its own CMK."
  type        = string
  default     = ""
}

variable "kms_deletion_window_in_days" {
  description = "Deletion window (7-30 days) for the module-created KMS key."
  type        = number
  default     = 30
}

variable "versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete on the bucket versioning configuration."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Delete all objects when the bucket is destroyed."
  type        = bool
  default     = false
}

variable "acl" {
  description = "Optional canned ACL for the bucket (for example private, log-delivery-write)."
  type        = string
  default     = null
}

variable "grant" {
  description = "Optional explicit grants applied through an access control policy on the bucket ACL."
  type = list(object({
    permission    = string
    type          = string
    id            = optional(string)
    uri           = optional(string)
    email_address = optional(string)
  }))
  default = []
}

variable "policy" {
  description = "Optional JSON bucket policy document."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status: Enabled or Suspended. Null disables the configuration."
  type        = string
  default     = null
}

variable "logging" {
  description = "Optional server access logging configuration."
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
    target_grants = optional(list(object({
      permission    = string
      type          = string
      id            = optional(string)
      uri           = optional(string)
      email_address = optional(string)
    })), [])
  })
  default = null
}

variable "website" {
  description = "Optional static website configuration (index/error documents or redirect-all rules)."
  type = object({
    index_document = optional(string)
    error_document = optional(string)
    redirect_all_requests_to = optional(object({
      host_name = string
      protocol  = optional(string, "http")
    }))
  })
  default = null
}

variable "cors_rules" {
  description = "Optional list of CORS rules."
  type = list(object({
    id              = optional(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    allowed_headers = optional(list(string))
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "Optional list of lifecycle rules."
  type = list(object({
    id      = string
    enabled = optional(bool, true)
    prefix  = optional(string)
    tags    = optional(map(string))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      noncurrent_days           = optional(number)
      newer_noncurrent_versions = optional(number)
    }))
    noncurrent_version_transition = optional(list(object({
      noncurrent_days           = number
      storage_class             = string
      newer_noncurrent_versions = optional(number)
    })), [])
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = optional(number)
    }))
  }))
  default = []
}

variable "object_lock_enabled" {
  description = "Enable S3 object lock on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Default object lock retention (compliance/governance mode with days or years)."
  type = object({
    mode  = optional(string, "GOVERNANCE")
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "replication_role" {
  description = "ARN of an existing IAM role to use for replication. When empty, the module creates CoreS3ReplicationRole_<bucket>."
  type        = string
  default     = ""
}

variable "replication_rules" {
  description = "Optional list of cross-region replication rules."
  type = list(object({
    id       = string
    status   = optional(string, "Enabled")
    priority = optional(number)
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string), {})
    }))
    destination = object({
      bucket             = string
      storage_class      = optional(string)
      account_id         = optional(string)
      replica_kms_key_id = optional(string)
      access_control_translation = optional(object({
        owner = string
      }))
      replication_time = optional(object({
        status  = optional(string, "Enabled")
        minutes = optional(number, 15)
      }))
      metrics = optional(object({
        status  = optional(string, "Enabled")
        minutes = optional(number, 15)
      }))
    })
    delete_marker_replication_status = optional(string)
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
      replica_modifications = optional(object({
        status = string
      }))
    }))
  }))
  default = []
}

###############################################################################
# Locals - dynamic naming and derived values
###############################################################################
locals {
  create_kms_key = var.encryption && var.kms_key == ""

  base_bucket_name = (var.bucket_name != null && var.bucket_name != ""
    ? var.bucket_name
    : "corebucket-${random_id.bucket_suffix.hex}"
  )

  bucket_name = var.prefix ? "${local.base_bucket_name}-${random_string.bucket_suffix.result}" : local.base_bucket_name

  kms_key_arn = var.kms_key != "" ? var.kms_key : one(aws_kms_key.this[*].arn)

  create_replication_role = length(var.replication_rules) > 0 && var.replication_role == ""

  replication_role_arn = var.replication_role != "" ? var.replication_role : one(aws_iam_role.replication[*].arn)

  replication_policy_statements = concat(
    [
      {
        Sid    = "SourceBucketReplicationConfiguration"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetBucketLocation",
          "s3:GetBucketAcl"
        ]
        Resource = [aws_s3_bucket.this.arn]
      },
      {
        Sid    = "SourceObjectReplication"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectVersion"
        ]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      },
      {
        Sid    = "DestinationObjectReplication"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = ["arn:${data.aws_partition.current.partition}:s3:::*/*"]
      },
      {
        Sid      = "DestinationBucketVersioning"
        Effect   = "Allow"
        Action   = ["s3:GetBucketVersioning", "s3:PutBucketVersioning"]
        Resource = ["arn:${data.aws_partition.current.partition}:s3:::*"]
      }
    ],
    local.kms_key_arn != null ? [
      {
        Sid      = "KmsReplicationAccess"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:Encrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms_key_arn]
      }
    ] : []
  )
}

###############################################################################
# Random name helpers
###############################################################################
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_string" "bucket_suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

###############################################################################
# KMS key (created only when encryption is on and no key was supplied)
###############################################################################
resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer managed key for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true

  tags = var.tags
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

###############################################################################
# S3 bucket and configuration
###############################################################################
resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = (var.acl != null || length(var.grant) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = (var.acl != null || length(var.grant) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = length(var.grant) > 0 ? null : coalesce(var.acl, "private")

  dynamic "access_control_policy" {
    for_each = length(var.grant) > 0 ? [1] : []

    content {
      owner {
        id           = data.aws_canonical_user_id.current.id
        display_name = data.aws_canonical_user_id.current.display_name
      }

      dynamic "grant" {
        for_each = var.grant

        content {
          permission    = grant.value.permission
          type          = grant.value.type
          id            = try(grant.value.id, null)
          uri           = try(grant.value.uri, null)
          email_address = try(grant.value.email_address, null)
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = var.versioning ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.encryption ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = local.kms_key_arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix

  dynamic "target_grant" {
    for_each = try(var.logging.target_grants, [])

    content {
      permission    = target_grant.value.permission
      type          = target_grant.value.type
      id            = try(target_grant.value.id, null)
      uri           = try(target_grant.value.uri, null)
      email_address = try(target_grant.value.email_address, null)
    }
  }
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [1] : []

    content {
      suffix = var.website.index_document
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [1] : []

    content {
      key = var.website.error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [1] : []

    content {
      host_name = var.website.redirect_all_requests_to.host_name
      protocol  = try(var.website.redirect_all_requests_to.protocol, null)
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = try(cors_rule.value.id, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = (try(rule.value.prefix, "") != "" || length(try(rule.value.tags, {})) > 0) ? [1] : []

        content {
          prefix = try(rule.value.prefix, "") != "" ? rule.value.prefix : null

          dynamic "tag" {
            for_each = try(rule.value.tags, {})

            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []

        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])

        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, [])

        content {
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value.days_after_initiation, null)
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket              = aws_s3_bucket.this.id
  object_lock_enabled = "Enabled"

  dynamic "rule" {
    for_each = var.object_lock_configuration != null ? [var.object_lock_configuration] : []

    content {
      default_retention {
        mode  = rule.value.mode
        days  = try(rule.value.days, null)
        years = try(rule.value.years, null)
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_policy" "this" {
  count = var.policy != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

###############################################################################
# Replication
###############################################################################
resource "aws_s3_bucket_replication_configuration" "this" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []

        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})

            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication_status, null) != null ? [rule.value.delete_marker_replication_status] : []

        content {
          status = delete_marker_replication.value
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []

        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []

            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }

          dynamic "replica_modifications" {
            for_each = try(source_selection_criteria.value.replica_modifications, null) != null ? [source_selection_criteria.value.replica_modifications] : []

            content {
              status = replica_modifications.value.status
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account_id, null)

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.replica_kms_key_id, null) != null ? [rule.value.destination.replica_kms_key_id] : []

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation, null) != null ? [rule.value.destination.access_control_translation] : []

          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "replication_time" {
          for_each = try(rule.value.destination.replication_time, null) != null ? [rule.value.destination.replication_time] : []

          content {
            status = replication_time.value.status

            time {
              minutes = try(replication_time.value.minutes, null)
            }
          }
        }

        dynamic "metrics" {
          for_each = try(rule.value.destination.metrics, null) != null ? [rule.value.destination.metrics] : []

          content {
            status = metrics.value.status

            event_threshold {
              minutes = try(metrics.value.minutes, null)
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0

  name = "CoreS3ReplicationRole_${local.bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_replication_role ? 1 : 0

  name = "CoreS3ReplicationPolicy_${local.bucket_name}"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.replication_policy_statements
  })
}

###############################################################################
# Outputs
###############################################################################
output "bucket_id" {
  description = "The name (ID) of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_name" {
  description = "The resolved bucket name."
  value       = aws_s3_bucket.this.bucket
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  description = "The regional domain name of the bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_website_endpoint" {
  description = "Website endpoint of the bucket, when website hosting is configured."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, null)
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for bucket encryption (supplied or module-created)."
  value       = local.kms_key_arn
}

output "kms_key_id" {
  description = "ID of the module-created KMS key, when one was created."
  value       = one(aws_kms_key.this[*].key_id)
}

output "kms_alias_name" {
  description = "Name of the module-created KMS alias, when one was created."
  value       = one(aws_kms_alias.this[*].name)
}

output "replication_role_arn" {
  description = "ARN of the replication role used (supplied or module-created)."
  value       = local.replication_role_arn
}

output "replication_role_name" {
  description = "Name of the module-created replication role, when one was created."
  value       = one(aws_iam_role.replication[*].name)
}

output "replication_policy_name" {
  description = "Name of the module-created replication policy, when one was created."
  value       = one(aws_iam_role_policy.replication[*].name)
}

###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region where the S3 datastore stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "random_suffix" {
  description = "Whether to append a random lowercase alphanumeric suffix to resource names."
  type        = bool
  default     = true
}

variable "suffix_length" {
  description = "Length of the random suffix (lowercase alphanumeric, no special characters)."
  type        = number
  default     = 4
}

variable "bucket_name" {
  description = "Base name of the S3 bucket used for application image hosting."
  type        = string
  default     = "zedcloud"
}

variable "iam_username" {
  description = "Base name of the IAM user granted read-only access to the bucket."
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Base name of the IAM policy granting read-only access to the bucket."
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload the local image file into the bucket."
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Local image file (in the execution directory) to upload when upload_image is true."
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "Folder prefix used for the uploaded image object key."
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "Whether to prefix the uploaded object key with s3_folder."
  type        = bool
  default     = true
}

variable "create_iam_user" {
  description = "Whether to create the IAM user, access key, policy and policy attachment."
  type        = bool
  default     = true
}

###############################################################################
# Random Suffix
###############################################################################

resource "random_string" "suffix" {
  count = var.random_suffix ? 1 : 0

  length  = var.suffix_length
  special = false
  upper   = false
  lower   = true
  numeric = true
}

###############################################################################
# Locals (resolved names)
###############################################################################

locals {
  suffix = var.random_suffix ? "-${random_string.suffix[0].result}" : ""

  bucket_name      = "${var.bucket_name}${local.suffix}"
  iam_username     = "${var.iam_username}${local.suffix}"
  iam_policy_name  = "${var.iam_policy_name}${local.suffix}"
  image_object_key = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
}

###############################################################################
# S3 Bucket (encrypted with customer-managed KMS key, fully private)
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "s3" {
  description             = "Customer-managed KMS key for S3 datastore ${local.bucket_name}"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${local.bucket_name}-s3"
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Optional Image Upload
###############################################################################

resource "aws_s3_object" "image" {
  count = var.upload_image ? 1 : 0

  bucket = aws_s3_bucket.this.id
  key    = local.image_object_key
  source = "${path.module}/${var.image_filename}"
  etag   = filemd5("${path.module}/${var.image_filename}")
}

###############################################################################
# IAM Read-Only Access
###############################################################################

resource "aws_iam_user" "this" {
  count = var.create_iam_user ? 1 : 0

  name          = local.iam_username
  path          = "/"
  force_destroy = true

  tags = {
    Name = local.iam_username
  }
}

resource "aws_iam_access_key" "this" {
  count = var.create_iam_user ? 1 : 0

  user   = aws_iam_user.this[0].name
  status = "Active"
}

data "aws_iam_policy_document" "s3_read_only" {
  statement {
    sid    = "AllowListBucket"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.this.arn,
    ]
  }

  statement {
    sid    = "AllowGetObject"
    effect = "Allow"

    actions = [
      "s3:GetObject",
    ]

    resources = [
      "${aws_s3_bucket.this.arn}/*",
    ]
  }
}

resource "aws_iam_policy" "s3_read_only" {
  count = var.create_iam_user ? 1 : 0

  name        = local.iam_policy_name
  description = "Read-only access to S3 datastore bucket ${local.bucket_name}"
  policy      = data.aws_iam_policy_document.s3_read_only.json

  tags = {
    Name = local.iam_policy_name
  }
}

resource "aws_iam_user_policy_attachment" "this" {
  count = var.create_iam_user ? 1 : 0

  user       = aws_iam_user.this[0].name
  policy_arn = aws_iam_policy.s3_read_only[0].arn
}

###############################################################################
# Outputs
###############################################################################

output "bucket_name" {
  description = "Resolved name of the S3 datastore bucket."
  value       = aws_s3_bucket.this.bucket
}

output "bucket_arn" {
  description = "ARN of the S3 datastore bucket."
  value       = aws_s3_bucket.this.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for bucket encryption."
  value       = aws_kms_key.s3.arn
}

output "iam_user_name" {
  description = "Name of the IAM user with read-only bucket access."
  value       = try(aws_iam_user.this[0].name, null)
}

output "iam_policy_arn" {
  description = "ARN of the read-only IAM policy."
  value       = try(aws_iam_policy.s3_read_only[0].arn, null)
}

output "iam_access_key_id" {
  description = "Access key ID of the IAM user."
  value       = try(aws_iam_access_key.this[0].id, null)
  sensitive   = true
}

output "iam_secret_access_key" {
  description = "Secret access key of the IAM user."
  value       = try(aws_iam_access_key.this[0].secret, null)
  sensitive   = true
}

output "uploaded_object_key" {
  description = "S3 object key of the uploaded image (if any)."
  value       = try(aws_s3_object.image[0].key, null)
}

This Terraform configuration establishes a multi-AZ VPC networking foundation for Amazon EKS. It creates a VPC with DNS support and hostnames enabled, three public subnets and three private subnets across three availability zones, an internet gateway, a NAT gateway with an Elastic IP, and separate route tables for public and private subnets. Provider-level default tags are applied from a `default_tags` variable containing Project, Owner, Compliance, Environment, and Provider keys. All resources are tagged appropriately, including EKS-specific subnet tags for load balancer discovery. No IAM roles are required for this networking-only foundation.

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.default_tags
  }
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "default_tags" {
  description = "Default tags to apply to all resources"
  type        = map(string)
  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.14.0.0/16"
}

variable "az_count" {
  description = "Number of availability zones to use"
  type        = number
  default     = 3
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  project     = var.default_tags["Project"]
  environment = var.default_tags["Environment"]
  name_prefix = "${local.project}-${local.environment}"
  azs         = slice(data.aws_availability_zones.available.names, 0, var.az_count)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = var.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                     = "${local.name_prefix}-public-${count.index + 1}"
    Type                     = "public"
    "kubernetes.io/role/elb" = "1"
  }
}

resource "aws_subnet" "private" {
  count                   = var.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index + var.az_count)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                              = "${local.name_prefix}-private-${count.index + 1}"
    Type                              = "private"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.name_prefix}-nat"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = var.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = var.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ip" {
  description = "Public IP of the NAT gateway"
  value       = aws_eip.nat.public_ip
}
```

################################################################################
# Terraform & Provider configuration
################################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "AWS region where the bucket will be created"
  type        = string
  default     = "us-east-1"
}

variable "create_bucket" {
  description = "Controls if the S3 bucket and all of its dependencies should be created"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of the bucket. If omitted, Terraform will assign a random, unique name"
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix. Conflicts with bucket"
  type        = string
  default     = null
}

variable "acl" {
  description = "The canned ACL to apply to the bucket. Ignored when object ownership is BucketOwnerEnforced"
  type        = string
  default     = "private"
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to add to all resources created by this configuration"
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Sets the accelerate configuration of an existing bucket. Can be Enabled or Suspended"
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Specifies who should bear the cost of Amazon S3 data transfer. Can be BucketOwner or Requester"
  type        = string
  default     = null
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls on this bucket"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership. Valid values: BucketOwnerPreferred, ObjectWriter or BucketOwnerEnforced"
  type        = string
  default     = "ObjectWriter"
}

variable "attach_public_policy" {
  description = "Controls if the S3 bucket public access block should be created/attached"
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket"
  type        = bool
  default     = true
}

variable "attach_policy" {
  description = "Controls if a user defined bucket policy (var.policy) should be attached to the bucket"
  type        = bool
  default     = false
}

variable "policy" {
  description = "A valid AWS policy document (JSON string) that will be merged into the bucket policy when attach_policy is true"
  type        = string
  default     = null
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls if S3 bucket should have ELB log delivery policy attached"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls if S3 bucket should have ALB/NLB log delivery policy attached"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls if S3 bucket should have a policy that denies non-SSL (aws:SecureTransport = false) requests"
  type        = bool
  default     = false
}

variable "website" {
  description = "Map of website configuration, e.g. { index_document = \"index.html\", error_document = \"error.html\", redirect_all_requests_to = { host_name = \"example.com\", protocol = \"https\" }, routing_rules = [...] }"
  type        = any
  default     = {}
}

variable "cors_rule" {
  description = "List of CORS rule maps, e.g. [{ allowed_methods = [\"GET\"], allowed_origins = [\"*\"] }]"
  type        = any
  default     = []
}

variable "versioning" {
  description = "Map of versioning configuration, e.g. { enabled = true, mfa_delete = \"Disabled\" }"
  type        = any
  default     = {}
}

variable "logging" {
  description = "Map of access logging configuration, e.g. { target_bucket = \"logs\", target_prefix = \"s3/\" }"
  type        = any
  default     = {}
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule maps. Each rule supports id, status, prefix, filter, abort_incomplete_multipart_upload, expiration, noncurrent_version_expiration, transitions, noncurrent_version_transitions"
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Map containing cross region replication configuration, e.g. { role = \"arn:...\", rules = [ { id, status, filter, destination = { bucket = \"arn:...\" } } ] }"
  type        = any
  default     = {}
}

variable "create_replication_role" {
  description = "Controls if an IAM role for S3 replication should be created when no role is supplied in var.replication_configuration"
  type        = bool
  default     = false
}

variable "server_side_encryption_configuration" {
  description = "Map containing server-side encryption configuration, e.g. { rule = { apply_server_side_encryption_by_default = { kms_master_key_id = \"arn\", sse_algorithm = \"aws:kms\" } } }. When empty a customer managed KMS key is created and used as the default aws:kms key"
  type        = any
  default     = {}
}

variable "kms_key_deletion_window_in_days" {
  description = "Duration (in days) after which the customer managed KMS key is deleted on destroy"
  type        = number
  default     = 7
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled on the bucket. This must be set at bucket creation time"
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Map of object lock configuration, e.g. { rule = { default_retention = { mode = \"GOVERNANCE\", days = 30 } } }"
  type        = any
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  create_bucket = var.create_bucket

  # An ACL cannot be used on a bucket configured with BucketOwnerEnforced ownership.
  acl = var.control_object_ownership && var.object_ownership == "BucketOwnerEnforced" ? null : var.acl

  attach_combined_policy = var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy || var.attach_deny_insecure_transport_policy || var.attach_policy

  use_default_sse = length(keys(var.server_side_encryption_configuration)) == 0
  create_kms_key  = local.create_bucket && local.use_default_sse

  replication_role_arn = try(var.replication_configuration.role, null) != null ? var.replication_configuration.role : try(aws_iam_role.replication[0].arn, null)
}

################################################################################
# Data sources used to compose bucket policies
################################################################################

data "aws_iam_policy_document" "elb_log_delivery" {
  count = local.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0

  statement {
    sid    = "AllowELBLogDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this[0].arn}/*"]
  }
}

data "aws_iam_policy_document" "lb_log_delivery" {
  count = local.create_bucket && var.attach_lb_log_delivery_policy ? 1 : 0

  statement {
    sid    = "AllowLBAccessLogsWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this[0].arn}/*"]
  }

  statement {
    sid    = "AllowLBAccessLogsAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.this[0].arn]
  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  count = local.create_bucket && var.attach_deny_insecure_transport_policy ? 1 : 0

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

data "aws_iam_policy_document" "combined" {
  count = local.create_bucket && local.attach_combined_policy ? 1 : 0

  source_policy_documents = compact([
    var.attach_elb_log_delivery_policy ? data.aws_iam_policy_document.elb_log_delivery[0].json : "",
    var.attach_lb_log_delivery_policy ? data.aws_iam_policy_document.lb_log_delivery[0].json : "",
    var.attach_deny_insecure_transport_policy ? data.aws_iam_policy_document.deny_insecure_transport[0].json : "",
    var.attach_policy && var.policy != null ? var.policy : "",
  ])
}

################################################################################
# Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  count = local.create_bucket ? 1 : 0

  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix
  acl           = local.acl
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_enabled

  tags = var.tags
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.create_bucket && var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.create_bucket && var.request_payer != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket && length(keys(var.versioning)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = try(var.versioning.enabled, false) ? "Enabled" : "Suspended"
    mfa_delete = try(var.versioning.mfa_delete, null)
  }
}

################################################################################
# Server side encryption (customer managed KMS key created when none supplied)
################################################################################

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer managed KMS key used for S3 bucket default encryption"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true

  tags = var.tags
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket && !local.use_default_sse ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = can(tolist(var.server_side_encryption_configuration.rule)) ? tolist(var.server_side_encryption_configuration.rule) : [var.server_side_encryption_configuration.rule]

    content {
      bucket_key_enabled = try(rule.value.bucket_key_enabled, null)

      dynamic "apply_server_side_encryption_by_default" {
        for_each = length(keys(try(rule.value.apply_server_side_encryption_by_default, {}))) == 0 ? [] : [rule.value.apply_server_side_encryption_by_default]

        content {
          kms_master_key_id = try(apply_server_side_encryption_by_default.value.kms_master_key_id, null)
          sse_algorithm     = apply_server_side_encryption_by_default.value.sse_algorithm
        }
      }
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "default" {
  count = local.create_kms_key ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

################################################################################
# Static website hosting
################################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && length(keys(var.website)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try([var.website.index_document], [])

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try([var.website.error_document], [])

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = length(keys(try(var.website.redirect_all_requests_to, {}))) == 0 ? [] : [var.website.redirect_all_requests_to]

    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website.routing_rules, [])

    content {
      dynamic "condition" {
        for_each = length(keys(try(routing_rule.value.condition, {}))) == 0 ? [] : [routing_rule.value.condition]

        content {
          http_error_code_returned_equals = try(condition.value.http_error_code_returned_equals, null)
          key_prefix_equals               = try(condition.value.key_prefix_equals, null)
        }
      }

      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

################################################################################
# CORS
################################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && length(var.cors_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule

    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

################################################################################
# Access logging
################################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && length(keys(var.logging)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging.target_bucket
  target_prefix = try(var.logging.target_prefix, null)

  dynamic "target_grant" {
    for_each = try(var.logging.target_grants, [])

    content {
      permission = target_grant.value.permission

      grantee {
        type = target_grant.value.grantee.type
        id   = try(target_grant.value.grantee.id, null)
        uri  = try(target_grant.value.grantee.uri, null)
      }
    }
  }
}

################################################################################
# Lifecycle management
################################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")

      dynamic "filter" {
        for_each = length(keys(try(rule.value.filter, {}))) > 0 ? [rule.value.filter] : [{ prefix = try(rule.value.prefix, "") }]

        content {
          prefix                   = try(filter.value.prefix, null)
          tags                     = try(filter.value.tags, null)
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)

          dynamic "and" {
            for_each = length(keys(try(filter.value.and, {}))) == 0 ? [] : [filter.value.and]

            content {
              prefix                   = try(and.value.prefix, null)
              tags                     = try(and.value.tags, null)
              object_size_greater_than = try(and.value.object_size_greater_than, null)
              object_size_less_than    = try(and.value.object_size_less_than, null)
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = length(keys(try(rule.value.abort_incomplete_multipart_upload, {}))) == 0 ? [] : [rule.value.abort_incomplete_multipart_upload]

        content {
          days_after_initiation = try(abort_incomplete_multipart_upload.value.days_after_initiation, null)
        }
      }

      dynamic "expiration" {
        for_each = length(keys(try(rule.value.expiration, {}))) == 0 ? [] : [rule.value.expiration]

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = length(keys(try(rule.value.noncurrent_version_expiration, {}))) == 0 ? [] : [rule.value.noncurrent_version_expiration]

        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

################################################################################
# Object locking
################################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && length(keys(var.object_lock_configuration)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  token  = try(var.object_lock_configuration.token, null)

  rule {
    default_retention {
      mode  = var.object_lock_configuration.rule.default_retention.mode
      days  = try(var.object_lock_configuration.rule.default_retention.days, null)
      years = try(var.object_lock_configuration.rule.default_retention.years, null)
    }
  }
}

################################################################################
# Cross region replication (+ optional IAM role)
################################################################################

resource "aws_iam_role" "replication" {
  count = local.create_bucket && var.create_replication_role ? 1 : 0

  name_prefix = "s3-replication-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_bucket && var.create_replication_role ? 1 : 0

  name_prefix = "s3-replication-"
  role        = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Resource = [aws_s3_bucket.this[0].arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
        ]
        Resource = ["${aws_s3_bucket.this[0].arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
        ]
        Resource = ["*"]
      },
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_bucket && length(keys(var.replication_configuration)) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = try(var.replication_configuration.rules, [])

    content {
      id       = try(rule.value.id, null)
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = length(keys(try(rule.value.filter, {}))) > 0 ? [rule.value.filter] : [{ prefix = try(rule.value.prefix, "") }]

        content {
          prefix = try(filter.value.prefix, null)
          tags   = try(filter.value.tags, null)
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication_status, null) == null ? [] : [rule.value.delete_marker_replication_status]

        content {
          status = delete_marker_replication.value
        }
      }

      dynamic "source_selection_criteria" {
        for_each = length(keys(try(rule.value.source_selection_criteria, {}))) == 0 ? [] : [rule.value.source_selection_criteria]

        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = length(keys(try(source_selection_criteria.value.sse_kms_encrypted_objects, {}))) == 0 ? [] : [source_selection_criteria.value.sse_kms_encrypted_objects]

            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }

          dynamic "replica_modifications" {
            for_each = length(keys(try(source_selection_criteria.value.replica_modifications, {}))) == 0 ? [] : [source_selection_criteria.value.replica_modifications]

            content {
              status = replica_modifications.value.status
            }
          }
        }
      }

      destination {
        bucket             = rule.value.destination.bucket
        storage_class      = try(rule.value.destination.storage_class, null)
        replica_kms_key_id = try(rule.value.destination.replica_kms_key_id, null)
        account_id         = try(rule.value.destination.account_id, null)

        dynamic "access_control_translation" {
          for_each = length(keys(try(rule.value.destination.access_control_translation, {}))) == 0 ? [] : [rule.value.destination.access_control_translation]

          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "encryption_configuration" {
          for_each = length(keys(try(rule.value.destination.encryption_configuration, {}))) == 0 ? [] : [rule.value.destination.encryption_configuration]

          content {
            replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
          }
        }

        dynamic "metrics" {
          for_each = length(keys(try(rule.value.destination.metrics, {}))) == 0 ? [] : [rule.value.destination.metrics]

          content {
            status = try(metrics.value.status, "Disabled")

            dynamic "event_threshold" {
              for_each = length(keys(try(metrics.value.event_threshold, {}))) == 0 ? [] : [metrics.value.event_threshold]

              content {
                minutes = event_threshold.value.minutes
              }
            }
          }
        }

        dynamic "replication_time" {
          for_each = length(keys(try(rule.value.destination.replication_time, {}))) == 0 ? [] : [rule.value.destination.replication_time]

          content {
            status = try(replication_time.value.status, "Disabled")

            dynamic "time" {
              for_each = length(keys(try(replication_time.value.time, {}))) == 0 ? [] : [replication_time.value.time]

              content {
                minutes = time.value.minutes
              }
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Public access block & bucket policy
################################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket && var.attach_public_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_policy" "this" {
  count = local.create_bucket && local.attach_combined_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

################################################################################
# Outputs
################################################################################

output "s3_bucket_id" {
  description = "The name of the bucket"
  value       = try(aws_s3_bucket.this[0].id, null)
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket"
  value       = try(aws_s3_bucket.this[0].arn, null)
}

output "s3_bucket_regional_domain_name" {
  description = "The bucket region-specific domain name"
  value       = try(aws_s3_bucket.this[0].bucket_regional_domain_name, null)
}

output "s3_bucket_website_endpoint" {
  description = "The website endpoint of the bucket, if website hosting is enabled"
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, null)
}

output "s3_bucket_hosted_zone_id" {
  description = "The Route 53 Hosted Zone ID for this bucket's region"
  value       = try(aws_s3_bucket.this[0].hosted_zone_id, null)
}

output "s3_bucket_kms_key_arn" {
  description = "The ARN of the customer managed KMS key created for default SSE-KMS encryption (when none was supplied)"
  value       = try(aws_kms_key.this[0].arn, null)
}

output "s3_bucket_policy_json" {
  description = "The combined bucket policy that is attached to the bucket"
  value       = try(data.aws_iam_policy_document.combined[0].json, null)
}

output "s3_replication_role_arn" {
  description = "The ARN of the replication IAM role created by this configuration, if any"
  value       = try(aws_iam_role.replication[0].arn, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.awsRegion
}

###############################################################################
# Variables
###############################################################################

variable "awsRegion" {
  description = "AWS region to deploy the network stack into."
  type        = string
  default     = "us-east-1"
}

variable "awsAz1" {
  description = "Optional first availability zone. Falls back to the first available AZ in the region."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Optional second availability zone. Falls back to awsAz1 if set, otherwise the second available AZ in the region."
  type        = string
  default     = null
}

variable "projectPrefix" {
  description = "Prefix used for naming and tagging resources."
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner tag applied to all resources."
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix appended to resource names / tags to distinguish builds."
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Whether public subnets auto-assign a public IP address to launched instances."
  type        = bool
  default     = false
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for the public subnet in the first availability zone."
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for the public subnet in the second availability zone."
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for the management subnet in the first availability zone."
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for the management subnet in the second availability zone."
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for the private subnet in the first availability zone."
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for the private subnet in the second availability zone."
  type        = string
  default     = "10.1.120.0/24"
}

###############################################################################
# Data sources / locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # First AZ: explicit value if provided, otherwise the first available AZ in the region.
  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])

  # Second AZ: explicit value, else fall back to az1 when it was specified,
  # else the second available AZ in the region.
  az2 = coalesce(var.awsAz2, var.awsAz1, data.aws_availability_zones.available.names[1])

  name_prefix = "${var.projectPrefix}-${var.buildSuffix}"

  common_tags = {
    Project     = var.projectPrefix
    Owner       = var.resourceOwner
    BuildSuffix = var.buildSuffix
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

###############################################################################
# Internet gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

###############################################################################
# Route table + default route + main route table association
###############################################################################

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-main-rt"
  })
}

resource "aws_route" "default_to_igw" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id

  depends_on = [aws_internet_gateway.main]
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id

  depends_on = [aws_route.default_to_igw]
}

###############################################################################
# Public subnets (one per AZ)
###############################################################################

resource "aws_subnet" "pub_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-pub-a"
    Tier = "public"
  })
}

resource "aws_subnet" "pub_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-pub-b"
    Tier = "public"
  })
}

###############################################################################
# Management subnets (one per AZ)
###############################################################################

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mgmt-a"
    Tier = "management"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mgmt-b"
    Tier = "management"
  })
}

###############################################################################
# Private subnets (one per AZ)
###############################################################################

resource "aws_subnet" "priv_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-priv-a"
    Tier = "private"
  })
}

resource "aws_subnet" "priv_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-priv-b"
    Tier = "private"
  })
}

###############################################################################
# Outputs
###############################################################################

output "region" {
  description = "Region the network stack was deployed into."
  value       = var.awsRegion
}

output "resolved_availability_zones" {
  description = "The two availability zones actually used for subnet placement."
  value = {
    az1 = local.az1
    az2 = local.az2
  }
}

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the main VPC."
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "main_route_table_id" {
  description = "ID of the custom route table promoted to the VPC main route table."
  value       = aws_route_table.main.id
}

output "public_subnet_ids" {
  description = "Map of public subnet IDs."
  value = {
    pub_a = aws_subnet.pub_a.id
    pub_b = aws_subnet.pub_b.id
  }
}

output "management_subnet_ids" {
  description = "Map of management subnet IDs."
  value = {
    mgmt_a = aws_subnet.mgmt_a.id
    mgmt_b = aws_subnet.mgmt_b.id
  }
}

output "private_subnet_ids" {
  description = "Map of private subnet IDs."
  value = {
    priv_a = aws_subnet.priv_a.id
    priv_b = aws_subnet.priv_b.id
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

provider "tls" {}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region to deploy the benchmark resources into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name applied to all resources."
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "rule_count" {
  description = "Number of path-based listener rules to create (/static-N/*)."
  type        = number
  default     = 1
}

###############################################################################
# Network
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "benchmark" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.name
  }
}

resource "aws_subnet" "benchmark" {
  count = 2

  vpc_id            = aws_vpc.benchmark.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name}-subnet-${count.index}"
  }
}

resource "aws_security_group" "benchmark" {
  name        = "${var.name}-alb"
  description = "Allow all traffic to and from the VPC CIDR for the internal ALB"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    description = "All traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "All traffic to within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = var.name
  }
}

###############################################################################
# Self-signed certificate imported into ACM
###############################################################################

resource "tls_private_key" "benchmark" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "benchmark" {
  private_key_pem = tls_private_key.benchmark.private_key_pem

  subject {
    common_name  = "${var.name}.internal"
    organization = var.name
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "benchmark" {
  private_key      = tls_private_key.benchmark.private_key_pem
  certificate_body = tls_self_signed_cert.benchmark.cert_pem

  tags = {
    Name = var.name
  }

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Internal Application Load Balancer
###############################################################################

resource "aws_lb" "benchmark" {
  name                       = var.name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.benchmark.id]
  subnets                    = aws_subnet.benchmark[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = var.name
  }
}

resource "aws_lb_target_group" "benchmark" {
  name     = var.name
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.benchmark.id

  health_check {
    enabled             = true
    protocol            = "HTTP"
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name = var.name
  }
}

resource "aws_lb_listener" "benchmark" {
  load_balancer_arn = aws_lb.benchmark.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.benchmark.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  tags = {
    Name = var.name
  }
}

###############################################################################
# Path-based listener rules (/static-N/*)
###############################################################################

resource "aws_lb_listener_rule" "benchmark" {
  count = var.rule_count

  listener_arn = aws_lb_listener.benchmark.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.benchmark.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = {
    Name = "${var.name}-static-${count.index}"
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the benchmark VPC."
  value       = aws_vpc.benchmark.id
}

output "subnet_ids" {
  description = "IDs of the benchmark subnets."
  value       = aws_subnet.benchmark[*].id
}

output "alb_arn" {
  description = "ARN of the internal Application Load Balancer."
  value       = aws_lb.benchmark.arn
}

output "alb_dns_name" {
  description = "Internal DNS name of the Application Load Balancer."
  value       = aws_lb.benchmark.dns_name
}

output "target_group_arn" {
  description = "ARN of the HTTP target group (port 8080, health check 8081/health)."
  value       = aws_lb_target_group.benchmark.arn
}

output "listener_arn" {
  description = "ARN of the HTTPS listener on port 443."
  value       = aws_lb_listener.benchmark.arn
}

output "certificate_arn" {
  description = "ARN of the self-signed certificate imported into ACM."
  value       = aws_acm_certificate.benchmark.arn
}

output "listener_rule_arns" {
  description = "ARNs of the path-based listener rules."
  value       = aws_lb_listener_rule.benchmark[*].arn
}

###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "Home region for the multi-region CloudTrail trail and supporting resources."
  type        = string
  default     = "us-east-1"
}

variable "trail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "management_trail"
}

variable "is_organization_trail" {
  description = "Apply the trail to all accounts in the AWS Organization."
  type        = bool
  default     = false
}

variable "enable_kms" {
  description = "Create and use a customer managed KMS key for the trail and the log bucket."
  type        = bool
  default     = true
}

variable "kms_key_alias" {
  description = "Alias of the customer managed CloudTrail KMS key."
  type        = string
  default     = "alias/cloudtrail_key"
}

variable "log_group_name" {
  description = "Name of the CloudWatch Logs log group receiving CloudTrail events."
  type        = string
  default     = "cloudtrail_logs"
}

variable "log_retention_days" {
  description = "CloudWatch log group retention in days (0 = never expire)."
  type        = number
  default     = 0
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "random_integer" "bucket_suffix" {
  min = 100000000000
  max = 999999999999
}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
  region      = var.aws_region
  bucket_name = "cloudtrail-bucket-${random_integer.bucket_suffix.result}"
  bucket_arn  = "arn:${local.partition}:s3:::${local.bucket_name}"
  trail_arn   = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"
  kms_key_arn = var.enable_kms ? aws_kms_key.cloudtrail[0].arn : null

  common_tags = {
    Project   = "centralized-audit-logging"
    ManagedBy = "Terraform"
  }
}

###############################################################################
# KMS key, alias and key policy
###############################################################################

data "aws_iam_policy_document" "kms" {
  count = var.enable_kms ? 1 : 0

  # Account root retains full administrative control of the key.
  statement {
    sid    = "EnableRootAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # The identity that deploys this configuration can administer the key.
  statement {
    sid    = "AllowCallerIdentityKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:RotateKeyOnDemand",
      "kms:GetKeyPolicy",
      "kms:PutKeyPolicy"
    ]
    resources = ["*"]
  }

  # CloudTrail must be able to generate data keys and describe the key.
  statement {
    sid    = "AllowCloudTrailToGenerateDataKeysAndDescribeKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  # S3 uses the key to encrypt objects written into the CloudTrail bucket.
  statement {
    sid    = "AllowS3UseOfKeyForBucketEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = [local.bucket_arn]
    }
  }

  # Any principal in the account may decrypt audit logs with this key.
  statement {
    sid    = "AllowAccountWideLogDecryption"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  count = var.enable_kms ? 1 : 0

  description             = "Customer managed key used to encrypt CloudTrail logs and the CloudTrail log bucket."
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = {
    Name = "cloudtrail-kms-key"
  }
}

resource "aws_kms_alias" "cloudtrail" {
  count = var.enable_kms ? 1 : 0

  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

###############################################################################
# S3 bucket for CloudTrail log delivery
###############################################################################

resource "aws_s3_bucket" "trail" {
  bucket        = local.bucket_name
  force_destroy = false

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "trail" {
  bucket = aws_s3_bucket.trail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ACLs are kept enabled so the required bucket-owner-full-control ACL check succeeds.
resource "aws_s3_bucket_ownership_controls" "trail" {
  bucket = aws_s3_bucket.trail.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "trail" {
  bucket = aws_s3_bucket.trail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms ? "aws:kms" : "AES256"
      kms_master_key_id = local.kms_key_arn
    }

    bucket_key_enabled = var.enable_kms
  }
}

data "aws_iam_policy_document" "trail_bucket" {
  # CloudTrail reads the bucket ACL before delivering log files.
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [local.bucket_arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  # CloudTrail writes log objects with bucket-owner-full-control ownership.
  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${local.bucket_arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  # Block any non-TLS access to the audit log bucket.
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]
    resources = [
      local.bucket_arn,
      "${local.bucket_arn}/*"
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "trail" {
  bucket = aws_s3_bucket.trail.id
  policy = data.aws_iam_policy_document.trail_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.trail]
}

###############################################################################
# CloudWatch Logs log group and delivery role
###############################################################################

resource "aws_cloudwatch_log_group" "trail" {
  name              = var.log_group_name
  retention_in_days = var.log_retention_days

  tags = {
    Name = var.log_group_name
  }
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    sid    = "AllowCloudTrailToAssumeRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "cloudtrail_cw_logs" {
  statement {
    sid    = "AllowCloudTrailToCreateLogStreamAndPutLogEvents"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]

    resources = [
      aws_cloudwatch_log_group.trail.arn,
      "${aws_cloudwatch_log_group.trail.arn}:log-stream:*"
    ]
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "CloudTrailRoleForCloudWatchLogs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json

  tags = {
    Name = "CloudTrailRoleForCloudWatchLogs"
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_cw_logs.json
}

###############################################################################
# CloudTrail trail
###############################################################################

resource "aws_cloudtrail" "management_trail" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.trail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  is_organization_trail         = var.is_organization_trail
  enable_logging                = true
  kms_key_id                    = local.kms_key_arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.trail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn

  # Capture every management event, both read and write.
  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  depends_on = [
    aws_s3_bucket_policy.trail,
    aws_kms_key.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch,
  ]

  tags = {
    Name = var.trail_name
  }
}

###############################################################################
# Outputs
###############################################################################

output "trail_name" {
  description = "Name of the CloudTrail trail."
  value       = aws_cloudtrail.management_trail.name
}

output "trail_arn" {
  description = "ARN of the CloudTrail trail."
  value       = aws_cloudtrail.management_trail.arn
}

output "cloudtrail_bucket_name" {
  description = "Name of the S3 bucket receiving CloudTrail log files."
  value       = aws_s3_bucket.trail.id
}

output "cloudtrail_bucket_arn" {
  description = "ARN of the S3 bucket receiving CloudTrail log files."
  value       = aws_s3_bucket.trail.arn
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch log group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.trail.name
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch log group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.trail.arn
}

output "cloudtrail_cloudwatch_role_arn" {
  description = "ARN of the IAM role CloudTrail uses to deliver events to CloudWatch Logs."
  value       = aws_iam_role.cloudtrail_cloudwatch.arn
}

output "kms_key_arn" {
  description = "ARN of the customer managed CloudTrail KMS key (null when KMS is disabled)."
  value       = var.enable_kms ? aws_kms_key.cloudtrail[0].arn : null
}

output "kms_key_alias" {
  description = "Alias of the customer managed CloudTrail KMS key (null when KMS is disabled)."
  value       = var.enable_kms ? aws_kms_alias.cloudtrail[0].name : null
}

###############################################################################
# Terraform / providers
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Data sources
###############################################################################

# Current caller identity - the account that owns the repository and that is
# always granted read access through the repository policy.
data "aws_caller_identity" "current" {}

###############################################################################
# Variables (all optional, all with defaults)
###############################################################################

variable "region" {
  description = "AWS region where the ECR repository and IAM policies are created."
  type        = string
  default     = "us-east-1"
}

variable "namespace" {
  description = "Optional ECR namespace (path prefix), e.g. \"platform\". Empty string means no namespace."
  type        = string
  default     = ""
}

variable "name" {
  description = "Repository name. When null or empty, a random petname is generated (frigga style)."
  type        = string
  default     = "ecr"
}

variable "petname_length" {
  description = "Number of words used when generating a petname for a null/empty repository name."
  type        = number
  default     = 2
}

variable "image_tag_mutability" {
  description = "Tag mutability setting for the repository. Valid values: MUTABLE, IMMUTABLE."
  type        = string
  default     = "IMMUTABLE"

  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "image_tag_mutability must be either \"MUTABLE\" or \"IMMUTABLE\"."
  }
}

variable "scan_on_push" {
  description = "Whether images are scanned for vulnerabilities when pushed to the repository."
  type        = bool
  default     = true
}

variable "lifecycle_policy" {
  description = "Optional ECR lifecycle policy as a JSON string. When null (the default) no lifecycle policy is created."
  type        = string
  default     = null
}

variable "trusted_accounts" {
  description = "Additional AWS account IDs that receive read access via the ECR repository policy."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags to apply to the created resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Petname generation (only when the repository name is null/empty)
###############################################################################

resource "random_pet" "this" {
  count     = local.use_petname ? 1 : 0
  length    = var.petname_length
  separator = "-"
}

###############################################################################
# Locals - name construction, policy naming and tagging
###############################################################################

locals {
  # Petname id (null when the random_pet resource was not created).
  petname = one(random_pet.this[*].id)

  # True when var.name is null or an empty/blank string.
  use_petname = var.name == null || trimspace(coalesce(var.name, "")) == ""

  # Base (final segment) of the repository name.
  base_name = local.use_petname ? coalesce(local.petname, "ecr") : trimspace(var.name)

  # Namespace is optional; normalise nulls and blanks to "".
  clean_namespace = trimspace(coalesce(var.namespace, ""))

  # "<namespace>/<name>" or "<name>" - the ECR repository name path.
  repository_name = local.clean_namespace == "" ? local.base_name : "${local.clean_namespace}/${local.base_name}"

  # IAM policy names cannot contain "/", so derive a safe prefix from the repo path.
  policy_prefix = replace(local.repository_name, "/", "-")

  # The lifecycle policy is only created when a JSON document is supplied.
  create_lifecycle_policy = var.lifecycle_policy != null && trimspace(var.lifecycle_policy) != ""

  # Current account + explicitly trusted accounts, de-duplicated.
  trusted_account_ids = distinct(concat([data.aws_caller_identity.current.account_id], var.trusted_accounts))

  # Required tags for every managed resource.
  tags = merge(var.tags, {
    "terraform.io" = "managed"
    "Name"         = local.repository_name
  })
}

###############################################################################
# ECR repository
###############################################################################

resource "aws_ecr_repository" "this" {
  name                 = local.repository_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  tags = local.tags
}

# Only created when a lifecycle policy JSON document is supplied.
resource "aws_ecr_lifecycle_policy" "this" {
  count = local.create_lifecycle_policy ? 1 : 0

  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

###############################################################################
# ECR repository policy - cross account (and owner) read access
###############################################################################

resource "aws_ecr_repository_policy" "this" {
  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCrossAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = [for account_id in local.trusted_account_ids : "arn:aws:iam::${account_id}:root"]
        }
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:DescribeImages",
          "ecr:DescribeRepositories",
          "ecr:GetDownloadUrlForLayer",
          "ecr:ListImages"
        ]
      }
    ]
  })
}

###############################################################################
# IAM policy - read access to the repository
###############################################################################

resource "aws_iam_policy" "read" {
  name        = "${local.policy_prefix}-ecr-read"
  description = "Read access to the ${local.repository_name} ECR repository"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcrReadAccess"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:DescribeImages",
          "ecr:DescribeRepositories",
          "ecr:GetAuthorizationToken",
          "ecr:GetDownloadUrlForLayer",
          "ecr:ListImages"
        ]
        Resource = aws_ecr_repository.this.arn
      }
    ]
  })

  tags = local.tags
}

###############################################################################
# IAM policy - write (push) access to the repository
###############################################################################

resource "aws_iam_policy" "write" {
  name        = "${local.policy_prefix}-ecr-write"
  description = "Push access to the ${local.repository_name} ECR repository"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EcrWriteAccess"
        Effect = "Allow"
        Action = [
          "ecr:PutImage",
          "ecr:UploadLayerPart",
          "ecr:InitiateLayerUpload",
          "ecr:CompleteLayerUpload"
        ]
        Resource = aws_ecr_repository.this.arn
      }
    ]
  })

  tags = local.tags
}

###############################################################################
# Outputs
###############################################################################

output "repository_name" {
  description = "Full ECR repository name (namespace/name path)."
  value       = aws_ecr_repository.this.name
}

output "repository_arn" {
  description = "ARN of the ECR repository."
  value       = aws_ecr_repository.this.arn
}

output "repository_url" {
  description = "URL used to push/pull images (docker login / docker push target)."
  value       = aws_ecr_repository.this.repository_url
}

output "generated_petname" {
  description = "Petname generated when var.name was null or empty (null otherwise)."
  value       = local.petname
}

output "ecr_read_policy_arn" {
  description = "ARN of the <name>-ecr-read IAM policy."
  value       = aws_iam_policy.read.arn
}

output "ecr_write_policy_arn" {
  description = "ARN of the <name>-ecr-write IAM policy."
  value       = aws_iam_policy.write.arn
}

output "trusted_account_ids" {
  description = "AWS account IDs granted read access through the repository policy."
  value       = local.trusted_account_ids
}

output "lifecycle_policy_enabled" {
  description = "Whether an ECR lifecycle policy was created."
  value       = local.create_lifecycle_policy
}

###############################################################################
# Dynamic multi-tier VPC network (public / NAT / private tiers)
#
#   * VPC CIDR is configurable (default 10.0.0.0/16)
#   * Each tier can be toggled on/off independently
#   * Subnets are spread over a configurable number of Availability Zones
#   * Every subnet CIDR is derived dynamically from the VPC CIDR with
#     log-based bitwise splitting:  newbits = ceil(log2(active_subnets))
#     and offset-based netnum arithmetic per tier
###############################################################################

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the VPC and all subnets are created."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag for the VPC; also used as a prefix for child resources."
  type        = string
  default     = "multi-tier-vpc"
}

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC. All subnet CIDRs are derived from it."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block, e.g. 10.0.0.0/16."
  }
}

variable "az_count" {
  description = "Number of Availability Zones used (also the number of subnets per enabled tier)."
  type        = number
  default     = 2

  validation {
    condition     = var.az_count >= 1 && var.az_count <= 6
    error_message = "az_count must be between 1 and 6."
  }
}

variable "enable_public_subnets" {
  description = "Create the public tier (auto-assign public IP subnets, Internet Gateway, security group and public route table)."
  type        = bool
  default     = true
}

variable "enable_nat_subnets" {
  description = "Create the NAT tier subnet set (one subnet per Availability Zone)."
  type        = bool
  default     = true
}

variable "enable_private_subnets" {
  description = "Create the private tier subnet set (one subnet per Availability Zone)."
  type        = bool
  default     = true
}

variable "create_local_vpc_route" {
  description = <<-EOT
    Explicitly declare the local route (VPC CIDR -> "local") on the public route table.
    AWS creates this local route automatically for every route table and rejects a
    CreateRoute call for it, therefore this defaults to false so that `terraform apply`
    succeeds. The local route always exists on the public route table and is reported
    by the `public_route_table_routes` output.
  EOT
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

###############################################################################
# Locals - dynamic, log-based bitwise CIDR splitting
###############################################################################

locals {
  common_tags = merge(var.tags, { ManagedBy = "Terraform" })

  # Availability zones actually used (limited to az_count).
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  # ---------------------------------------------------------------------------
  # Which tiers are active -> total number of active subnets across all AZs
  # ---------------------------------------------------------------------------
  public_tier_count  = var.enable_public_subnets ? 1 : 0
  nat_tier_count     = var.enable_nat_subnets ? 1 : 0
  private_tier_count = var.enable_private_subnets ? 1 : 0

  active_tier_count  = local.public_tier_count + local.nat_tier_count + local.private_tier_count
  total_subnet_count = local.active_tier_count * var.az_count

  # ---------------------------------------------------------------------------
  # Log-based bitwise split: borrow ceil(log2(total active subnets)) bits from
  # the VPC prefix, so the base CIDR splits into 2^newbits equal blocks.
  # (the tiny epsilon keeps exact powers of two safe against float rounding)
  # ---------------------------------------------------------------------------
  subnet_newbits = local.total_subnet_count > 1 ? ceil(log(local.total_subnet_count, 2) - 0.000000001) : 1

  # ---------------------------------------------------------------------------
  # Offset-based netnum assignment per tier (in units of /newbits blocks)
  # ---------------------------------------------------------------------------
  public_subnet_offset  = 0
  nat_subnet_offset     = local.public_tier_count * var.az_count
  private_subnet_offset = (local.public_tier_count + local.nat_tier_count) * var.az_count

  # ---------------------------------------------------------------------------
  # Concrete subnet CIDRs (empty list when the tier is disabled)
  # ---------------------------------------------------------------------------
  public_subnet_cidrs = var.enable_public_subnets ? [
    for i in range(var.az_count) :
    cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.public_subnet_offset + i)
  ] : []

  nat_subnet_cidrs = var.enable_nat_subnets ? [
    for i in range(var.az_count) :
    cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.nat_subnet_offset + i)
  ] : []

  private_subnet_cidrs = var.enable_private_subnets ? [
    for i in range(var.az_count) :
    cidrsubnet(var.vpc_cidr, local.subnet_newbits, local.private_subnet_offset + i)
  ] : []
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

###############################################################################
# Public tier
###############################################################################

# Auto-assigning public IP subnets, one per Availability Zone.
resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? var.az_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

# Internet Gateway for the VPC.
resource "aws_internet_gateway" "main" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
    Tier = "public"
  })
}

# Dedicated security group for the public tier: all egress, all protocols.
resource "aws_security_group" "public" {
  count = var.enable_public_subnets ? 1 : 0

  name        = "${var.vpc_name}-public"
  description = "Public tier security group - allows all outbound traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic on all protocols"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-sg"
    Tier = "public"
  })
}

# Public route table (holds the internet route and the local VPC CIDR route).
resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
    Tier = "public"
  })
}

# Internet route: 0.0.0.0/0 -> Internet Gateway
resource "aws_route" "public_internet" {
  count = var.enable_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

# Local VPC CIDR route. AWS provisions this automatically on every route table
# (and rejects an explicit CreateRoute for it), hence the opt-in flag. It always
# exists on the public route table and is reported by the outputs below.
resource "aws_route" "public_local" {
  count = var.enable_public_subnets && var.create_local_vpc_route ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = var.vpc_cidr
  gateway_id             = "local"
}

# Attach the public route table to every public subnet.
resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? var.az_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# NAT tier (independent subnet set, offset-based CIDRs)
###############################################################################

resource "aws_subnet" "nat" {
  count = var.enable_nat_subnets ? var.az_count : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.nat_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-${local.azs[count.index]}"
    Tier = "nat"
  })
}

###############################################################################
# Private tier (independent subnet set, offset-based CIDRs)
###############################################################################

resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? var.az_count : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "Base CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by this deployment."
  value       = local.azs
}

output "total_active_subnets" {
  description = "Total number of active subnets (active tiers x AZs) driving the log-based split."
  value       = local.total_subnet_count
}

output "subnet_newbits" {
  description = "Extra network bits borrowed from the VPC prefix: ceil(log2(total active subnets))."
  value       = local.subnet_newbits
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "public_subnet_cidr_blocks" {
  description = "CIDR blocks of the public subnets."
  value       = local.public_subnet_cidrs
}

output "nat_subnet_ids" {
  description = "IDs of the NAT subnets."
  value       = aws_subnet.nat[*].id
}

output "nat_subnet_cidr_blocks" {
  description = "CIDR blocks of the NAT subnets."
  value       = local.nat_subnet_cidrs
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidr_blocks" {
  description = "CIDR blocks of the private subnets."
  value       = local.private_subnet_cidrs
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway (null when the public tier is disabled)."
  value       = one(aws_internet_gateway.main[*].id)
}

output "public_security_group_id" {
  description = "ID of the public tier security group (null when the public tier is disabled)."
  value       = one(aws_security_group.public[*].id)
}

output "public_route_table_id" {
  description = "ID of the public route table (null when the public tier is disabled)."
  value       = one(aws_route_table.public[*].id)
}

output "public_route_table_association_ids" {
  description = "IDs of the public subnet <-> public route table associations."
  value       = aws_route_table_association.public[*].id
}

output "public_route_table_routes" {
  description = "Routes on the public route table, including the AWS-managed local route for the VPC CIDR."
  value = var.enable_public_subnets ? [
    {
      destination = "0.0.0.0/0"
      target      = aws_internet_gateway.main[0].id
      type        = "internet_gateway"
    },
    {
      destination = var.vpc_cidr
      target      = "local"
      type        = "local (created automatically by AWS)"
    }
  ] : []
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ----------------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------------
variable "region" {
  description = "AWS region to deploy the VPC environment into."
  type        = string
  default     = "us-east-1"
}

variable "project" {
  description = "Project name used for tagging."
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment name (e.g. poc, dev, prod)."
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name of the VPC that will host the data processing workloads."
  type        = string
  default     = "demo-dataflow"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_pair_name" {
  description = "Name of the pre-existing EC2 key pair used for SSH access to the bastion."
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "Instance type for the SSH bastion host."
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimized" {
  description = "Whether the bastion instance should be EBS optimized."
  type        = bool
  default     = false
}

variable "bastion_ssh_cidr" {
  description = "CIDR block allowed to SSH into the bastion host. Restrict this in production."
  type        = string
  default     = "0.0.0.0/0"
}

variable "common_tags" {
  description = "Map of common tags applied to every resource created by this template."
  type        = map(string)
  default = {
    Project     = "demo"
    Environment = "poc"
    ManagedBy   = "Terraform"
  }
}

variable "custom_tags" {
  description = "Map of additional custom tags merged on top of the common tags."
  type        = map(string)
  default     = {}
}

# ----------------------------------------------------------------------------
# Locals & data sources
# ----------------------------------------------------------------------------
locals {
  tags = merge(
    var.common_tags,
    var.custom_tags,
    {
      Project     = var.project
      Environment = var.environment
    }
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ----------------------------------------------------------------------------
# VPC
# ----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = var.vpc_name
  })
}

# ----------------------------------------------------------------------------
# Internet Gateway
# ----------------------------------------------------------------------------
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "demogwInternet"
  })
}

# ----------------------------------------------------------------------------
# Public subnets
# ----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-public-${data.aws_availability_zones.available.names[count.index]}"
    Tier = "public"
  })
}

# ----------------------------------------------------------------------------
# Private subnets
# ----------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-private-${data.aws_availability_zones.available.names[count.index]}"
    Tier = "private"
  })
}

# ----------------------------------------------------------------------------
# Public routing
# ----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = merge(local.tags, {
    Name = "demoPublicRouteTable"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ----------------------------------------------------------------------------
# NAT gateway for private subnet egress
# ----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-nat-gw"
  })

  depends_on = [aws_internet_gateway.gw]
}

# ----------------------------------------------------------------------------
# Private routing
# ----------------------------------------------------------------------------
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ----------------------------------------------------------------------------
# Bastion security group
# ----------------------------------------------------------------------------
resource "aws_security_group" "bastion" {
  name        = "${var.vpc_name}-bastion-sg"
  description = "Allow SSH access to the bastion host"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from allowed CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.bastion_ssh_cidr]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-bastion-sg"
  })
}

# ----------------------------------------------------------------------------
# IAM role & instance profile for the bastion (SSM session access)
# ----------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "bastion" {
  name               = "${var.vpc_name}-bastion-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-bastion-role"
  })
}

resource "aws_iam_role_policy_attachment" "bastion_ssm" {
  role       = aws_iam_role.bastion.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "bastion" {
  name = "${var.vpc_name}-bastion-instance-profile"
  role = aws_iam_role.bastion.name

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-bastion-instance-profile"
  })
}

# ----------------------------------------------------------------------------
# Bastion EC2 instance
# ----------------------------------------------------------------------------
resource "aws_instance" "bastion" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = var.bastion_instance_type
  subnet_id                   = aws_subnet.public[0].id
  vpc_security_group_ids      = [aws_security_group.bastion.id]
  key_name                    = var.key_pair_name
  ebs_optimized               = var.ebs_optimized
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.bastion.name

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 20
    delete_on_termination = true
    encrypted             = true
  }

  tags = merge(local.tags, {
    Name = "${var.vpc_name}-bastion"
    Role = "bastion"
  })
}

# Note: assosicate_public_ip_address is false per the "no auto-assign public IP"
# requirement, so the bastion reaches the internet through the NAT-equivalent
# egress only when placed in a subnet with an attached IGW route. To obtain the
# public IP for SSH, place the instance in a public subnet and enable an EIP if
# direct SSH is required instead of SSM Session Manager.

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.gw.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table."
  value       = aws_route_table.private.id
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway used for private subnet egress."
  value       = aws_nat_gateway.nat.id
}

output "bastion_instance_id" {
  description = "ID of the bastion EC2 instance."
  value       = aws_instance.bastion.id
}

output "bastion_private_ip" {
  description = "Private IP address of the bastion instance."
  value       = aws_instance.bastion.private_ip
}

output "bastion_security_group_id" {
  description = "ID of the bastion security group."
  value       = aws_security_group.bastion.id
}

output "bastion_iam_role_arn" {
  description = "ARN of the IAM role attached to the bastion instance."
  value       = aws_iam_role.bastion.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Providers
###############################################################################

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "primary_region" {
  description = "Primary AWS region in which the backup vaults and plans are created."
  type        = string
  default     = "us-east-1"
}

variable "secondary_region" {
  description = "Secondary AWS region used for cross-region backup vault copies."
  type        = string
  default     = "us-west-2"
}

variable "cross_account_backup_enabled" {
  description = "Whether to add a cross-account copy action to every backup rule."
  type        = bool
  default     = true
}

variable "cross_account_destination_account_id" {
  description = "Destination AWS account ID for optional cross-account backup copies."
  type        = string
  default     = "433568766270"
}

variable "cross_account_vault_name" {
  description = "Name of the backup vault in the destination account used for cross-account copies."
  type        = string
  default     = "cross-account-backup-vault"
}

variable "excluded_rds_instance_arns" {
  description = "List of RDS instance ARNs to exclude from the backup selections."
  type        = list(string)
  default     = []
}

variable "create_daily_backup_plan" {
  description = "Whether the daily backup plan should be created."
  type        = bool
  default     = true
}

###############################################################################
# KMS keys (primary region)
###############################################################################

resource "aws_kms_key" "primary_backup" {
  description             = "CMK used to encrypt the primary AWS Backup vault for RDS backups."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAwsBackupServiceRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.backup.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "primary_backup" {
  name          = "alias/rds-backup-primary"
  target_key_id = aws_kms_key.primary_backup.key_id
}

###############################################################################
# KMS keys (secondary / cross-region)
###############################################################################

resource "aws_kms_key" "secondary_backup" {
  provider                = aws.secondary
  description             = "CMK used to encrypt the cross-region AWS Backup vault for RDS backups."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAwsBackupServiceRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.backup.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "secondary_backup" {
  provider      = aws.secondary
  name          = "alias/rds-backup-secondary"
  target_key_id = aws_kms_key.secondary_backup.key_id
}

###############################################################################
# Backup vaults
###############################################################################

resource "aws_backup_vault" "primary" {
  name        = "rds-backup-vault"
  kms_key_arn = aws_kms_key.primary_backup.arn
}

resource "aws_backup_vault" "secondary" {
  provider    = aws.secondary
  name        = "rds-backup-vault-cross-region"
  kms_key_arn = aws_kms_key.secondary_backup.arn
}

###############################################################################
# IAM role for AWS Backup
###############################################################################

resource "aws_iam_role" "backup" {
  name        = "aws-backup-rds-service-role"
  description = "Service role assumed by AWS Backup to back up and restore RDS databases."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AwsBackupAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_service_role" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_restore_role" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

###############################################################################
# Backup plan: Daily (optional)
###############################################################################

resource "aws_backup_plan" "daily" {
  count = var.create_daily_backup_plan ? 1 : 0
  name  = "rds-daily-backup-plan"

  rule {
    rule_name         = "rds-daily"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 2 * * ? *)"
    start_window      = 60
    completion_window = 240

    lifecycle {
      delete_after = 7
    }

    # Cross-region copy
    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn

      lifecycle {
        delete_after = 7
      }
    }

    # Optional cross-account copy
    dynamic "copy_action" {
      for_each = var.cross_account_backup_enabled ? [1] : []

      content {
        destination_vault_arn = "arn:aws:backup:${var.primary_region}:${var.cross_account_destination_account_id}:backup-vault:${var.cross_account_vault_name}"

        lifecycle {
          delete_after = 7
        }
      }
    }
  }
}

resource "aws_backup_selection" "daily" {
  count        = var.create_daily_backup_plan ? 1 : 0
  name         = "rds-daily-selection"
  plan_id      = aws_backup_plan.daily[0].id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = ["arn:aws:rds:*:*:db:*"]
  not_resources = var.excluded_rds_instance_arns
}

###############################################################################
# Backup plan: Weekly
###############################################################################

resource "aws_backup_plan" "weekly" {
  name = "rds-weekly-backup-plan"

  rule {
    rule_name         = "rds-weekly"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 2 ? * SAT *)"
    start_window      = 60
    completion_window = 240

    lifecycle {
      delete_after = 30
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn

      lifecycle {
        delete_after = 30
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_backup_enabled ? [1] : []

      content {
        destination_vault_arn = "arn:aws:backup:${var.primary_region}:${var.cross_account_destination_account_id}:backup-vault:${var.cross_account_vault_name}"

        lifecycle {
          delete_after = 30
        }
      }
    }
  }
}

resource "aws_backup_selection" "weekly" {
  name         = "rds-weekly-selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = ["arn:aws:rds:*:*:db:*"]
  not_resources = var.excluded_rds_instance_arns
}

###############################################################################
# Backup plan: Monthly
###############################################################################

resource "aws_backup_plan" "monthly" {
  name = "rds-monthly-backup-plan"

  rule {
    rule_name         = "rds-monthly"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 3 1 * ? *)"
    start_window      = 60
    completion_window = 240

    lifecycle {
      delete_after = 365
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn

      lifecycle {
        delete_after = 365
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_backup_enabled ? [1] : []

      content {
        destination_vault_arn = "arn:aws:backup:${var.primary_region}:${var.cross_account_destination_account_id}:backup-vault:${var.cross_account_vault_name}"

        lifecycle {
          delete_after = 365
        }
      }
    }
  }
}

resource "aws_backup_selection" "monthly" {
  name         = "rds-monthly-selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = ["arn:aws:rds:*:*:db:*"]
  not_resources = var.excluded_rds_instance_arns
}

###############################################################################
# Backup plan: Yearly
###############################################################################

resource "aws_backup_plan" "yearly" {
  name = "rds-yearly-backup-plan"

  rule {
    rule_name         = "rds-yearly"
    target_vault_name = aws_backup_vault.primary.name
    schedule          = "cron(0 4 1 1 ? *)"
    start_window      = 60
    completion_window = 240

    lifecycle {
      delete_after = 2555
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary.arn

      lifecycle {
        delete_after = 2555
      }
    }

    dynamic "copy_action" {
      for_each = var.cross_account_backup_enabled ? [1] : []

      content {
        destination_vault_arn = "arn:aws:backup:${var.primary_region}:${var.cross_account_destination_account_id}:backup-vault:${var.cross_account_vault_name}"

        lifecycle {
          delete_after = 2555
        }
      }
    }
  }
}

resource "aws_backup_selection" "yearly" {
  name         = "rds-yearly-selection"
  plan_id      = aws_backup_plan.yearly.id
  iam_role_arn = aws_iam_role.backup.arn

  resources     = ["arn:aws:rds:*:*:db:*"]
  not_resources = var.excluded_rds_instance_arns
}

###############################################################################
# Outputs
###############################################################################

output "primary_backup_vault_arn" {
  description = "ARN of the primary AWS Backup vault."
  value       = aws_backup_vault.primary.arn
}

output "secondary_backup_vault_arn" {
  description = "ARN of the cross-region AWS Backup vault."
  value       = aws_backup_vault.secondary.arn
}

output "backup_role_arn" {
  description = "ARN of the AWS Backup service role used by the selections."
  value       = aws_iam_role.backup.arn
}

output "daily_backup_plan_id" {
  description = "ID of the daily backup plan (empty when disabled)."
  value       = var.create_daily_backup_plan ? aws_backup_plan.daily[0].id : ""
}

output "weekly_backup_plan_id" {
  description = "ID of the weekly backup plan."
  value       = aws_backup_plan.weekly.id
}

output "monthly_backup_plan_id" {
  description = "ID of the monthly backup plan."
  value       = aws_backup_plan.monthly.id
}

output "yearly_backup_plan_id" {
  description = "ID of the yearly backup plan."
  value       = aws_backup_plan.yearly.id
}

# Terraform AWS IAM User Management & Security Baseline Stack

I'll build a Terraform template that provisions:

1. **Account Password Policy** — configurable compliance baseline (90-day rotation, 14-char minimum, 24-password history, complexity requirements) driven by variables with sensible defaults.
2. **Three IAM Groups** — `administrators`, `developpers`, `prod_users`.
3. **Three Custom IAM Policies** — attached to the corresponding groups with the exact action/condition semantics requested (tag-based resource scoping for dev vs. preprod/prod, and a NotAction-based broad admin grant with a `security != high` guard plus an allow-list of IAM/Organizations/Account read actions).

The template uses the AWS provider pinned to a valid region (`us-east-1` by default) and supplies defaults for every variable so it deploys as-is.

```iac_template
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -------------------------------------------------------------------
# Provider
# -------------------------------------------------------------------
provider "aws" {
  region = var.aws_region
}

# -------------------------------------------------------------------
# Variables
# -------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy the IAM baseline into."
  type        = string
  default     = "us-east-1"
}

variable "allow_users_to_change_password" {
  description = "Whether users can change their own password."
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether passwords must be reset by an admin (no user self-reset)."
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "Maximum password age in days."
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum password length."
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "Number of previous passwords that cannot be reused."
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Require at least one lowercase character."
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Require at least one uppercase character."
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Require at least one number."
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Require at least one symbol."
  type        = bool
  default     = true
}

# -------------------------------------------------------------------
# Account Password Policy
# -------------------------------------------------------------------
resource "aws_iam_account_password_policy" "baseline" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_uppercase_characters   = var.require_uppercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
}

# -------------------------------------------------------------------
# IAM Groups
# -------------------------------------------------------------------
resource "aws_iam_group" "administrators" {
  name = "administrators"
  path = "/"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
  path = "/"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
  path = "/"
}

# -------------------------------------------------------------------
# Custom IAM Policies
# -------------------------------------------------------------------

# developpers_policy : full EC2 + RDS on resources tagged env=dev
resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  description = "Allows full EC2 and RDS access on resources tagged env=dev."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DevEc2RdsTagScoped"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "rds:*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = "dev"
          }
        }
      }
    ]
  })
}

# prod_users_policy : full EC2 + RDS on resources tagged env=preprod OR env=prod
resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  description = "Allows full EC2 and RDS access on resources tagged env=preprod or env=prod."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ProdEc2RdsTagScoped"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "rds:*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = ["preprod", "prod"]
          }
        }
      }
    ]
  })
}

# administrators_policy : broad NotAction grant guarded by security!=high,
# plus an explicit allow-list for a handful of IAM / Organizations / Account actions.
resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  description = "Broad administrative access excluding iam/organizations/account, guarded by security!=high, with an IAM/Org/Account read allow-list."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BroadAdminNotAction"
        Effect = "Allow"
        NotAction = [
          "iam:*",
          "organizations:*",
          "account:*"
        ]
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:ResourceTag/security" = "high"
          }
        }
      },
      {
        Sid    = "IamOrgAccountReadAllowList"
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:ListRoles",
          "organizations:DescribeOrganization",
          "account:ListRegions"
        ]
        Resource = "*"
      }
    ]
  })
}

# -------------------------------------------------------------------
# Attach Policies to Groups
# -------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "administrators_attach" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

resource "aws_iam_group_policy_attachment" "developpers_attach" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users_attach" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

# -------------------------------------------------------------------
# Outputs
# -------------------------------------------------------------------
output "password_policy_id" {
  description = "Account password policy identifier."
  value       = aws_iam_account_password_policy.baseline.id
}

output "group_names" {
  description = "Names of the IAM groups created."
  value = [
    aws_iam_group.administrators.name,
    aws_iam_group.developpers.name,
    aws_iam_group.prod_users.name
  ]
}

output "policy_arns" {
  description = "ARNs of the custom policies created."
  value = {
    administrators = aws_iam_policy.administrators_policy.arn
    developpers    = aws_iam_policy.developpers_policy.arn
    prod_users     = aws_iam_policy.prod_users_policy.arn
  }
}
```

### Design notes
- **Password policy**: every field is driven by a variable with the requested default, so the same module can be reused to enforce stricter settings in regulated accounts without editing the code.
- **Tag-scoped access**: `StringEquals` with a single value (`dev`) or a list (`["preprod","prod"]`) implements the OR semantics for the environment tag on EC2/RDS resources.
- **Administrator NotAction**: the first statement grants everything *except* `iam:*`, `organizations:*`, and `account:*`, but only when the target resource is *not* tagged `security = high`. The second statement explicitly restores a small allow-list (`CreateServiceLinkedRole`, `DeleteServiceLinkedRole`, `ListRoles`, `DescribeOrganization`, `ListRegions`) so the admins keep the few identity/org actions they need.
- **Naming**: the group and policy names (`developpers`, `developpers_policy`) are preserved exactly as specified in the requirement.

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------
variable "region" {
  description = "AWS region to deploy the networking stack into."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to the Name tag of every resource."
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Tenancy of the VPC instances (default, dedicated, host)."
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "Main CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Whether DNS support is enabled in the VPC."
  type        = bool
  default     = true
}

variable "private_subnets" {
  description = "List of CIDR blocks for the private subnets."
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "List of ingress rules for the shared network ACL."
  type = list(object({
    rule_number = number
    rule_action = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 1024
      to_port     = 65535
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "List of egress rules for the shared network ACL."
  type = list(object({
    rule_number = number
    rule_action = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_block  = string
  }))
  default = [
    {
      rule_number = 100
      rule_action = "allow"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

# ------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

# ------------------------------------------------------------------
# Private subnets (across the first two AZs)
# ------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name_prefix}-private-subnet-${count.index + 1}"
  }
}

# ------------------------------------------------------------------
# Dedicated private route tables and associations
# ------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = length(var.private_subnets)

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------
# S3 Gateway VPC endpoint attached to both private route tables
# ------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.name_prefix}-s3-endpoint"
  }
}

# ------------------------------------------------------------------
# Shared network ACL for the private subnets
# ------------------------------------------------------------------
resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules
    content {
      rule_number = ingress.value.rule_number
      rule_action = ingress.value.rule_action
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_block  = ingress.value.cidr_block
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules
    content {
      rule_number = egress.value.rule_number
      rule_action = egress.value.rule_action
      from_port   = egress.value.from_port
      to_port     = egress.value.to_port
      protocol    = egress.value.protocol
      cidr_block  = egress.value.cidr_block
    }
  }

  tags = {
    Name = "${var.name_prefix}-private-nacl"
  }
}

# ------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "private_route_table_ids" {
  description = "IDs of the private route tables."
  value       = aws_route_table.private[*].id
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint."
  value       = aws_vpc_endpoint.s3.id
}

output "network_acl_id" {
  description = "ID of the shared network ACL attached to the private subnets."
  value       = aws_network_acl.private.id
}

# Terraform AWS VPC Base Networking Stack (Dual-Stack IPv4/IPv6)

Below is a self-contained Terraform configuration that provisions an AWS VPC base networking stack using Cloud Posse `null-label` context conventions.

**What it does:**

- Creates an `aws_vpc` with a primary IPv4 CIDR (default `11.0.0.0/16`) or an optional IPAM pool association for IPv4, DNS hostnames/DNS support enabled, `default` instance tenancy, and auto-assigned IPv6 CIDR (or optional IPv6 IPAM association).
- Registers additional IPv4/IPv6 CIDR block associations from map variables (IPAM pool id, netmask length, create/delete timeouts).
- Adopts and hardens the default VPC resources: strips all rules from the default security group when `default_security_group_deny_all = true`, and optionally adopts the default route table / default network ACL via flags defaulting to `false`.
- Conditionally provisions an internet gateway (`internet_gateway_enabled = true`) and an IPv6 egress-only internet gateway (`ipv6_egress_only_internet_gateway_enabled = false`).
- Exposes all relevant IDs/CIDRs as outputs.
- Uses IAM-free networking resources (no IAM roles required for VPC base networking) and a valid AWS provider pinned to `~> 5.0` in `us-east-2`.

```hcl
###############################################################################
# Providers & Terraform
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Cloud Posse null-label context
###############################################################################

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  enabled             = try(var.context.enabled, null)
  namespace           = try(var.context.namespace, null)
  tenant              = try(var.context.tenant, null)
  environment         = try(var.context.environment, null)
  stage               = try(var.context.stage, null)
  name                = try(var.context.name, null)
  delimiter           = try(var.context.delimiter, null)
  attributes          = try(var.context.attributes, null)
  tags                = try(var.context.tags, null)
  additional_tag_map  = try(var.context.additional_tag_map, null)
  regex_replace_chars = try(var.context.regex_replace_chars, null)
  label_order         = try(var.context.label_order, null)
  id_length_limit     = try(var.context.id_length_limit, null)
  label_key_case      = try(var.context.label_key_case, null)
  label_value_case    = try(var.context.label_value_case, null)
  descriptor_formats  = try(var.context.descriptor_formats, null)
  labels_as_tags      = try(var.context.labels_as_tags, null)
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which to deploy the VPC base networking stack."
  type        = string
  default     = "us-east-2"
}

variable "context" {
  description = <<-EOT
    Single object for setting entire Cloud Posse context at once.
    See the Cloud Posse null-label documentation for full details.
    Any field left as `null` will fall back to the null-label module defaults.
  EOT
  type        = any
  default = {
    enabled             = true
    namespace           = null
    tenant              = null
    environment         = null
    stage               = null
    name                = "vpc"
    delimiter           = null
    attributes          = []
    tags                = {}
    additional_tag_map  = {}
    regex_replace_chars = null
    label_order         = []
    id_length_limit     = null
    label_key_case      = null
    label_value_case    = null
    descriptor_formats  = {}
    labels_as_tags      = ["unset"]
  }
}

# ------------------------------------------------------------------------------
# Primary VPC inputs
# ------------------------------------------------------------------------------

variable "ipv4_primary_cidr_block" {
  description = "Primary IPv4 CIDR block for the VPC. Ignored when `ipv4_primary_cidr_block_association` is supplied."
  type        = string
  default     = "11.0.0.0/16"
}

variable "ipv4_primary_cidr_block_association" {
  description = "Optional IPAM-backed association for the primary IPv4 CIDR block (takes precedence over `ipv4_primary_cidr_block`)."
  type = object({
    ipam_pool_id   = string
    netmask_length = number
  })
  default = null
}

variable "instance_tenancy" {
  description = "Tenancy of the VPC instances. Valid values: `default`, `dedicated`."
  type        = string
  default     = "default"

  validation {
    condition     = contains(["default", "dedicated"], var.instance_tenancy)
    error_message = "`instance_tenancy` must be one of `default` or `dedicated`."
  }
}

variable "enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Whether DNS support is enabled in the VPC (required for DNS hostnames to work)."
  type        = bool
  default     = true
}

variable "assign_generated_ipv6_cidr_block" {
  description = "Automatically assign an Amazon-provided IPv6 CIDR block to the VPC. Ignored when `ipv6_primary_cidr_block_association` is set."
  type        = bool
  default     = true
}

variable "ipv6_primary_cidr_block_association" {
  description = "Optional IPAM-backed association for the primary IPv6 CIDR block."
  type = object({
    ipam_pool_id   = string
    netmask_length = number
  })
  default = null
}

# ------------------------------------------------------------------------------
# Additional CIDR block associations
# ------------------------------------------------------------------------------

variable "ipv4_additional_cidr_block_associations" {
  description = "Map of additional IPv4 CIDR block associations to register against the VPC."
  type = map(object({
    ipv4_ipam_pool_id   = string
    ipv4_netmask_length = number
    timeouts = optional(object({
      create = optional(string, "10m")
      delete = optional(string, "10m")
    }), {})
  }))
  default = {}
}

variable "ipv6_additional_cidr_block_associations" {
  description = "Map of additional IPv6 CIDR block associations to register against the VPC."
  type = map(object({
    ipv6_ipam_pool_id   = string
    ipv6_netmask_length = number
    timeouts = optional(object({
      create = optional(string, "10m")
      delete = optional(string, "10m")
    }), {})
  }))
  default = {}
}

# ------------------------------------------------------------------------------
# Default resource adoption / hardening flags
# ------------------------------------------------------------------------------

variable "default_security_group_deny_all" {
  description = "Adopt the VPC's default security group and remove all ingress/egress rules when true."
  type        = bool
  default     = true
}

variable "default_route_table_deny_all" {
  description = "Adopt the VPC's default route table and remove all (non-local) routes when true."
  type        = bool
  default     = false
}

variable "default_network_acl_deny_all" {
  description = "Adopt the VPC's default network ACL and remove all ingress/egress rules when true."
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# Gateway toggles
# ------------------------------------------------------------------------------

variable "internet_gateway_enabled" {
  description = "Whether to create an IPv4/IPv6 internet gateway for the VPC."
  type        = bool
  default     = true
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  description = "Whether to create an IPv6 egress-only internet gateway for the VPC."
  type        = bool
  default     = false
}

###############################################################################
# Core VPC
###############################################################################

resource "aws_vpc" "this" {
  cidr_block = var.ipv4_primary_cidr_block_association == null ? var.ipv4_primary_cidr_block : null

  ipv4_ipam_pool_id   = var.ipv4_primary_cidr_block_association != null ? var.ipv4_primary_cidr_block_association.ipam_pool_id : null
  ipv4_netmask_length = var.ipv4_primary_cidr_block_association != null ? var.ipv4_primary_cidr_block_association.netmask_length : null

  assign_generated_ipv6_cidr_block = var.ipv6_primary_cidr_block_association == null ? var.assign_generated_ipv6_cidr_block : null

  ipv6_ipam_pool_id   = var.ipv6_primary_cidr_block_association != null ? var.ipv6_primary_cidr_block_association.ipam_pool_id : null
  ipv6_netmask_length = var.ipv6_primary_cidr_block_association != null ? var.ipv6_primary_cidr_block_association.netmask_length : null

  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = module.this.tags
}

###############################################################################
# Additional CIDR block associations
###############################################################################

resource "aws_vpc_ipv4_cidr_block_association" "additional" {
  for_each = var.ipv4_additional_cidr_block_associations

  vpc_id              = aws_vpc.this.id
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.ipv4_netmask_length

  timeouts {
    create = each.value.timeouts.create
    delete = each.value.timeouts.delete
  }
}

resource "aws_vpc_ipv6_cidr_block_association" "additional" {
  for_each = var.ipv6_additional_cidr_block_associations

  vpc_id              = aws_vpc.this.id
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_netmask_length

  timeouts {
    create = each.value.timeouts.create
    delete = each.value.timeouts.delete
  }
}

###############################################################################
# Default VPC resource adoption / hardening
###############################################################################

resource "aws_default_security_group" "default" {
  count = var.default_security_group_deny_all ? 1 : 0

  vpc_id = aws_vpc.this.id

  # No ingress/egress blocks => all rules are stripped from the default SG.
  tags = merge(module.this.tags, { Name = "${module.this.id}-default-sg" })
}

resource "aws_default_route_table" "default" {
  count = var.default_route_table_deny_all ? 1 : 0

  default_route_table_id = aws_vpc.this.default_route_table_id

  # No route blocks => all (non-local) routes are stripped.
  tags = merge(module.this.tags, { Name = "${module.this.id}-default-rt" })
}

resource "aws_default_network_acl" "default" {
  count = var.default_network_acl_deny_all ? 1 : 0

  default_network_acl_id = aws_vpc.this.default_network_acl_id

  # No ingress/egress blocks => all rules are stripped.
  tags = merge(module.this.tags, { Name = "${module.this.id}-default-nacl" })
}

###############################################################################
# Internet gateways
###############################################################################

resource "aws_internet_gateway" "this" {
  count = var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(module.this.tags, { Name = "${module.this.id}-igw" })
}

resource "aws_egress_only_internet_gateway" "this" {
  count = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(module.this.tags, { Name = "${module.this.id}-eigw" })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.this.id
}

output "vpc_arn" {
  description = "The ARN of the VPC."
  value       = aws_vpc.this.arn
}

output "vpc_cidr_block" {
  description = "Primary IPv4 CIDR block of the VPC."
  value       = aws_vpc.this.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "Primary IPv6 CIDR block of the VPC (if any)."
  value       = aws_vpc.this.ipv6_cidr_block
}

output "vpc_ipv4_cidr_blocks" {
  description = "All IPv4 CIDR blocks associated with the VPC (primary plus additional)."
  value       = aws_vpc.this.cidr_block_associations[*].cidr_block
}

output "vpc_ipv6_cidr_blocks" {
  description = "All IPv6 CIDR blocks associated with the VPC (primary plus additional)."
  value       = aws_vpc.this.ipv6_cidr_block_associations[*].ipv6_cidr_block
}

output "vpc_primary_ipv4_network" {
  description = "Primary IPv4 CIDR of the VPC."
  value       = aws_vpc.this.cidr_block
}

output "vpc_additional_ipv4_cidr_blocks" {
  description = "Additional IPv4 CIDR blocks attached to the VPC."
  value       = [for a in aws_vpc_ipv4_cidr_block_association.additional : a.cidr_block]
}

output "vpc_additional_ipv6_cidr_blocks" {
  description = "Additional IPv6 CIDR blocks attached to the VPC."
  value       = [for a in aws_vpc_ipv6_cidr_block_association.additional : a.ipv6_cidr_block]
}

output "vpc_default_security_group_id" {
  description = "ID of the VPC's default security group."
  value       = aws_vpc.this.default_security_group_id
}

output "vpc_default_route_table_id" {
  description = "ID of the VPC's default route table."
  value       = aws_vpc.this.default_route_table_id
}

output "vpc_default_network_acl_id" {
  description = "ID of the VPC's default network ACL."
  value       = aws_vpc.this.default_network_acl_id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway (if created)."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "ipv6_egress_only_internet_gateway_id" {
  description = "ID of the IPv6 egress-only internet gateway (if created)."
  value       = try(aws_egress_only_internet_gateway.this[0].id, null)
}
```

### Notes on deployability
- The AWS provider is pinned to `~> 5.0` (where `ipv4_ipam_pool_id` / `ipv6_ipam_pool_id` are still valid on `aws_vpc`); the `us-east-2` region default keeps it provisionable out of the box.
- Every variable has a sensible default, so `terraform apply` with no `tfvars` produces a working dual-stack VPC with an internet gateway and no additional CIDR associations.
- All required variables/resources referenced in the configuration are declared. The Cloud Posse label module is pulled from the public Terraform Registry, so no additional providers or IAM roles are needed for VPC base networking.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the provider operates."
  type        = string
  default     = "us-east-1"
}

variable "username" {
  description = "Name of the IAM user that holds the infrastructure deployment credentials."
  type        = string
  default     = "my_vpn_infra_user"
}

variable "group_name" {
  description = "Name of the IAM group that receives all scoped policies."
  type        = string
  default     = "my-vpn-infra-group"
}

variable "membership_name" {
  description = "Name of the group used to define the user's group membership."
  type        = string
  default     = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  description = "Value applied to the ProjectTag tag on policies and the IAM user."
  type        = string
  default     = "my-vpn-tag"
}

variable "policy_path" {
  description = "Custom IAM path for all created policies (must start and end with '/')."
  type        = string
  default     = "/my_vpn_infra/"
}

###############################################################################
# IAM User
###############################################################################

resource "aws_iam_user" "infra_user" {
  name          = var.username
  path          = "/"
  force_destroy = true

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_access_key" "infra_user_key" {
  user   = aws_iam_user.infra_user.name
  status = "Active"
}

###############################################################################
# IAM Groups and Membership
###############################################################################

resource "aws_iam_group" "infra_group" {
  name = var.group_name
  path = "/"
}

resource "aws_iam_group" "membership_group" {
  name = var.membership_name
  path = "/"
}

resource "aws_iam_user_group_membership" "infra_membership" {
  user = aws_iam_user.infra_user.name

  groups = [
    aws_iam_group.infra_group.name,
    aws_iam_group.membership_group.name,
  ]
}

###############################################################################
# 1. basic_policy
###############################################################################

resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policy_path
  description = "Allows the caller to verify the identity of the deployment principal."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "BasicIdentityAccess"
        Effect   = "Allow"
        Action   = ["sts:GetCallerIdentity"]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "basic_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.basic_policy.arn
}

###############################################################################
# 2. create_policy
###############################################################################

resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policy_path
  description = "Allows creation of EC2 networking, security, and addressing resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2CreateAccess"
        Effect = "Allow"
        Action = [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "create_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.create_policy.arn
}

###############################################################################
# 3. read_policy
###############################################################################

resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policy_path
  description = "Allows read/describe access across EC2 resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2ReadAccess"
        Effect = "Allow"
        Action = [
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeAddresses",
          "ec2:DescribeAddressesAttribute",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeImages",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceCreditSpecifications",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInstances",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeLaunchTemplates",
          "ec2:DescribeLaunchTemplateVersions",
          "ec2:DescribeLocalGatewayRouteTableVpcAssociations",
          "ec2:DescribeNatGateways",
          "ec2:DescribeNetworkAcls",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeRegions",
          "ec2:DescribeRouteTables",
          "ec2:DescribeSecurityGroupRules",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSnapshots",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DescribeVolumesModifications",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeVpcClassicLink",
          "ec2:DescribeVpcClassicLinkDnsSupport",
          "ec2:DescribeVpcEndpointServices",
          "ec2:DescribeVpcEndpoints",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "read_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.read_policy.arn
}

###############################################################################
# 4. update_policy
###############################################################################

resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policy_path
  description = "Allows modification and association of existing EC2 resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2UpdateAccess"
        Effect = "Allow"
        Action = [
          "ec2:AssociateAddress",
          "ec2:AssociateIamInstanceProfile",
          "ec2:AssociateRouteTable",
          "ec2:AssociateSubnetCidrBlock",
          "ec2:AssociateVpcCidrBlock",
          "ec2:DisassociateAddress",
          "ec2:DisassociateIamInstanceProfile",
          "ec2:DisassociateRouteTable",
          "ec2:DisassociateSubnetCidrBlock",
          "ec2:DisassociateVpcCidrBlock",
          "ec2:ModifyInstanceAttribute",
          "ec2:ModifyInstanceCreditSpecification",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:ModifySecurityGroupRules",
          "ec2:ModifySnapshotAttribute",
          "ec2:ModifySubnetAttribute",
          "ec2:ModifyVolume",
          "ec2:ModifyVolumeAttribute",
          "ec2:ModifyVpcAttribute",
          "ec2:ReplaceRoute",
          "ec2:ReplaceRouteTableAssociation"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "update_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.update_policy.arn
}

###############################################################################
# 5. delete_policy
###############################################################################

resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policy_path
  description = "Allows deletion and detachment of EC2 resources."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2DeleteAccess"
        Effect = "Allow"
        Action = [
          "ec2:DeleteKeyPair",
          "ec2:DeleteNatGateway",
          "ec2:DeleteNetworkAcl",
          "ec2:DeleteNetworkInterface",
          "ec2:DeleteRoute",
          "ec2:DeleteRouteTable",
          "ec2:DeleteSecurityGroup",
          "ec2:DeleteSnapshot",
          "ec2:DeleteSubnet",
          "ec2:DeleteTags",
          "ec2:DeleteVolume",
          "ec2:DeleteVpc",
          "ec2:DetachInternetGateway",
          "ec2:DetachNetworkInterface",
          "ec2:DetachVolume",
          "ec2:DisassociateAddress",
          "ec2:DisassociateRouteTable",
          "ec2:ReleaseAddress",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "delete_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.delete_policy.arn
}

###############################################################################
# 6. instance_policy
###############################################################################

resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policy_path
  description = "Allows full EC2 instance lifecycle management."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2InstanceLifecycleAccess"
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "instance_policy_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.instance_policy.arn
}

###############################################################################
# 7. terraform_backend_access
###############################################################################

resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policy_path
  description = "Allows access to the Terraform S3 remote state bucket and DynamoDB state lock table."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "TerraformStateLockAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem"
        ]
        Resource = "*"
      },
      {
        Sid    = "TerraformStateBackendAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_group_policy_attachment" "terraform_backend_access_attachment" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.terraform_backend_access.arn
}

###############################################################################
# Outputs
###############################################################################

output "iam_user_name" {
  description = "Name of the created IAM user."
  value       = aws_iam_user.infra_user.name
}

output "iam_user_arn" {
  description = "ARN of the created IAM user."
  value       = aws_iam_user.infra_user.arn
}

output "iam_group_name" {
  description = "Name of the IAM group holding the scoped policies."
  value       = aws_iam_group.infra_group.name
}

output "iam_group_arn" {
  description = "ARN of the IAM group holding the scoped policies."
  value       = aws_iam_group.infra_group.arn
}

output "membership_group_name" {
  description = "Name of the group defining the user's group membership."
  value       = aws_iam_group.membership_group.name
}

output "policy_arns" {
  description = "ARNs of all policies created and attached to the IAM group."
  value = [
    aws_iam_policy.basic_policy.arn,
    aws_iam_policy.create_policy.arn,
    aws_iam_policy.read_policy.arn,
    aws_iam_policy.update_policy.arn,
    aws_iam_policy.delete_policy.arn,
    aws_iam_policy.instance_policy.arn,
    aws_iam_policy.terraform_backend_access.arn,
  ]
}

output "access_key_id" {
  description = "Access key ID for the IAM user."
  value       = aws_iam_access_key.infra_user_key.id
}

output "access_key_secret" {
  description = "Secret access key for the IAM user. Store securely."
  value       = aws_iam_access_key.infra_user_key.secret
  sensitive   = true
}

###############################################################################
# Terraform and Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "existing_vpc_id" {
  description = "Optional existing VPC ID. When empty, a new VPC is created."
  type        = string
  default     = ""
}

variable "env_prefix" {
  description = "Environment prefix used for naming and tagging resources."
  type        = string
  default     = "DEV"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC (used only when a new VPC is created)."
  type        = string
  default     = "10.0.0.0/16"
}

variable "craete_private_subnet" {
  description = "When true, private subnets, a NAT gateway and private routing are created."
  type        = bool
  default     = false
}

variable "nat_eip_private_ip" {
  description = "Private IP address associated with the NAT gateway Elastic IP."
  type        = string
  default     = "10.0.0.5"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the two public subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the two private subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "tags" {
  description = "Additional tags applied to every resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Availability zones for the target region
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "region-name"
    values = [var.region]
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  # 1 => create a brand new VPC, 0 => reuse the supplied existing VPC
  create_vpc = var.existing_vpc_id == "" ? 1 : 0

  # Resolve the VPC ID used by every downstream resource
  vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : try(aws_vpc.main[0].id, null)

  # First two AZs of the region, shared by the public and private tiers
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  # Private tier switch
  private_subnet_count = var.craete_private_subnet ? length(var.private_subnet_cidrs) : 0
  nat_count            = var.craete_private_subnet ? 1 : 0

  common_tags = merge(
    var.tags,
    {
      Environment = var.env_prefix
      ManagedBy   = "Terraform"
    }
  )
}

###############################################################################
# VPC (created only when no existing VPC is supplied)
###############################################################################

resource "aws_vpc" "main" {
  count = local.create_vpc

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env_prefix}-vpc"
    }
  )
}

###############################################################################
# Public tier: subnets, internet gateway, route table and associations
###############################################################################

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env_prefix}-public-subnet-${count.index + 1}"
      Tier = "public"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env_prefix}-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env_prefix}-public-rt"
      Tier = "public"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private tier (created only when craete_private_subnet = true)
###############################################################################

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = local.vpc_id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env_prefix}-private-subnet-${count.index + 1}"
      Tier = "private"
    }
  )
}

# Elastic IP backing the NAT gateway, associated with the requested private IP
resource "aws_eip" "nat" {
  count = local.nat_count

  domain                    = "vpc"
  associate_with_private_ip = var.nat_eip_private_ip

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env_prefix}-nat-eip"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

# Single NAT gateway placed in the first public subnet
resource "aws_nat_gateway" "main" {
  count = local.nat_count

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env_prefix}-nat-gw"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = local.nat_count

  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.env_prefix}-private-rt"
      Tier = "private"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the VPC used by the stack (new or existing)."
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "IDs of the two public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (empty when the private tier is disabled)."
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table (null when the private tier is disabled)."
  value       = var.craete_private_subnet ? aws_route_table.private[0].id : null
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway (null when the private tier is disabled)."
  value       = var.craete_private_subnet ? aws_nat_gateway.main[0].id : null
}

output "nat_gateway_public_ip" {
  description = "Public IP of the NAT gateway Elastic IP (null when the private tier is disabled)."
  value       = var.craete_private_subnet ? aws_eip.nat[0].public_ip : null
}

output "availability_zones_used" {
  description = "Availability zones used by the two tiers."
  value       = local.azs
}

###############################################################################
# Terraform and AWS provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables - provider / module behaviour
###############################################################################

variable "region" {
  description = "AWS region in which the SQS queues are created."
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Controls creation of the primary SQS queue and every resource attached to it."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the primary queue. The '.fifo' suffix is added automatically for FIFO queues. Set to null to use 'name_prefix' instead."
  type        = string
  default     = "terraform-sqs-queue"
}

variable "name_prefix" {
  description = "Prefix used for the primary queue name when 'name' is null."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the queues are FIFO queues (the '.fifo' suffix is handled automatically)."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content based deduplication (FIFO queues only)."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Deduplication scope for FIFO queues ('messageGroup' or 'queue'). Requires content based deduplication."
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Throughput limit for FIFO queues ('perQueue' or 'perMessageGroupId')."
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "Delivery delay for the primary queue in seconds (0-900)."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Maximum message size in bytes (1024-262144)."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds (60-1209600)."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Long polling wait time in seconds (0-20)."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for received messages in seconds."
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "Enables SQS managed server-side encryption. Applied automatically whenever 'kms_master_key_id' is not provided."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Custom KMS key ID, alias or ARN used for server-side encryption. When set, SQS managed SSE is disabled automatically."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period in seconds (60-86400). Only used when 'kms_master_key_id' is set."
  type        = number
  default     = 300
}

variable "create_queue_policy" {
  description = "Whether to create and attach a queue policy to the primary queue."
  type        = bool
  default     = false
}

variable "source_policy_documents" {
  description = "List of JSON policy documents merged into the queue policy as a lower priority source."
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of JSON policy documents merged into the queue policy with higher priority."
  type        = list(string)
  default     = []
}

variable "policy_statements" {
  description = <<-EOT
    Custom statements rendered into the queue policy when 'create_queue_policy' is true.
    Each statement may supply: sid, effect (defaults to "Allow"), actions, not_actions,
    resources (defaults to the ARN of the created queue when omitted or empty), not_resources,
    principals / not_principals (list of { type, identifiers }) and
    condition (list of { test, variable, values }).
  EOT
  type        = list(any)
  default     = []
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue for the primary queue and wire up the redrive policy."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Explicit name for the dead-letter queue. The '.fifo' suffix is added automatically for FIFO queues. When null, the name is derived from 'name'/'name_prefix' plus 'dlq_name_suffix'."
  type        = string
  default     = null
}

variable "dlq_name_prefix" {
  description = "Explicit name prefix for the dead-letter queue, used when neither 'dlq_name' nor a name derived from the primary queue is available."
  type        = string
  default     = null
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the primary queue name when deriving the default dead-letter queue name."
  type        = string
  default     = "-dlq"
}

variable "max_receive_count" {
  description = "Number of receives before a message is moved to the dead-letter queue."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the dead-letter queue, restricting redrive permissions byQueue to the primary queue."
  type        = bool
  default     = true
}

variable "dlq_kms_master_key_id" {
  description = "Override KMS key for the dead-letter queue. Falls back to 'kms_master_key_id' when null."
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "Override KMS data key reuse period for the dead-letter queue. Falls back to 'kms_data_key_reuse_period_seconds' when null."
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Override for SQS managed SSE on the dead-letter queue. Falls back to 'sqs_managed_sse_enabled' when null and no KMS key is used."
  type        = bool
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Override delivery delay for the dead-letter queue. Falls back to the primary queue value when null."
  type        = number
  default     = null
}

variable "dlq_max_message_size" {
  description = "Override maximum message size for the dead-letter queue. Falls back to the primary queue value when null."
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Override message retention period for the dead-letter queue. Falls back to the primary queue value when null."
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Override long polling wait time for the dead-letter queue. Falls back to the primary queue value when null."
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Override visibility timeout for the dead-letter queue. Falls back to the primary queue value when null."
  type        = number
  default     = null
}

variable "dlq_content_based_deduplication" {
  description = "Override content based deduplication for the dead-letter queue (FIFO only). Falls back to the primary queue value when null."
  type        = bool
  default     = null
}

variable "dlq_deduplication_scope" {
  description = "Override deduplication scope for the dead-letter queue (FIFO only). Falls back to the primary queue value when null."
  type        = string
  default     = null
}

variable "dlq_fifo_throughput_limit" {
  description = "Override FIFO throughput limit for the dead-letter queue. Falls back to the primary queue value when null."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

variable "create_iam_role" {
  description = "Whether to create an IAM role granting access to the created queue(s)."
  type        = bool
  default     = false
}

variable "iam_role_name" {
  description = "Name of the optional IAM role. When null, a name is generated from the 'sqs-access-' prefix."
  type        = string
  default     = null
}

variable "iam_role_assume_role_policy" {
  description = "Assume role policy document (JSON) for the optional IAM role."
  type        = string
  default     = <<-EOT
    {
      "Version": "2012-10-17",
      "Statement": [
        {
          "Effect": "Allow",
          "Principal": {
            "Service": "ec2.amazonaws.com"
          },
          "Action": "sts:AssumeRole"
        }
      ]
    }
  EOT
}

###############################################################################
# Locals
###############################################################################

locals {
  create = var.create

  fifo_suffix = ".fifo"

  # ---------------------------------------------------------------------------
  # Primary queue naming - the ".fifo" suffix is managed automatically
  # ---------------------------------------------------------------------------
  main_base_name = var.name != null ? (
    var.fifo_queue ? trimsuffix(var.name, local.fifo_suffix) : var.name
  ) : null

  main_base_name_prefix = var.name == null && var.name_prefix != null ? (
    var.fifo_queue ? trimsuffix(var.name_prefix, local.fifo_suffix) : var.name_prefix
  ) : null

  queue_name = local.main_base_name != null ? (
    var.fifo_queue ? "${local.main_base_name}${local.fifo_suffix}" : local.main_base_name
  ) : null

  queue_name_prefix = local.main_base_name == null && local.main_base_name_prefix != null ? (
    var.fifo_queue ? "${local.main_base_name_prefix}${local.fifo_suffix}" : local.main_base_name_prefix
  ) : null

  # ---------------------------------------------------------------------------
  # Dead-letter queue naming - defaults to "<primary name>-dlq"
  # ---------------------------------------------------------------------------
  dlq_base_name = var.dlq_name != null ? (
    var.fifo_queue ? trimsuffix(var.dlq_name, local.fifo_suffix) : var.dlq_name
  ) : (
    var.dlq_name_prefix == null && local.main_base_name != null ? "${local.main_base_name}${var.dlq_name_suffix}" : null
  )

  dlq_base_name_prefix = var.dlq_name_prefix != null ? (
    var.fifo_queue ? trimsuffix(var.dlq_name_prefix, local.fifo_suffix) : var.dlq_name_prefix
  ) : (
    var.dlq_name == null && local.main_base_name_prefix != null ? "${local.main_base_name_prefix}${var.dlq_name_suffix}" : null
  )

  dlq_name = local.dlq_base_name != null ? (
    var.fifo_queue ? "${local.dlq_base_name}${local.fifo_suffix}" : local.dlq_base_name
  ) : null

  dlq_name_prefix = local.dlq_name == null && local.dlq_base_name_prefix != null ? (
    var.fifo_queue ? "${local.dlq_base_name_prefix}${local.fifo_suffix}" : local.dlq_base_name_prefix
  ) : null

  # ---------------------------------------------------------------------------
  # Encryption - SQS managed SSE applies whenever no custom KMS key is supplied
  # ---------------------------------------------------------------------------
  kms_data_key_reuse_period_seconds = var.kms_master_key_id == null ? null : var.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null

  dlq_kms_master_key_id = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : var.kms_master_key_id

  dlq_sqs_managed_sse_enabled = local.dlq_kms_master_key_id == null ? (
    var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : var.sqs_managed_sse_enabled
  ) : null

  dlq_kms_data_key_reuse_period_seconds = local.dlq_kms_master_key_id == null ? null : (
    var.dlq_kms_data_key_reuse_period_seconds != null ? var.dlq_kms_data_key_reuse_period_seconds : var.kms_data_key_reuse_period_seconds
  )

  # ---------------------------------------------------------------------------
  # Dead-letter queue settings inherit the primary queue configuration
  # ---------------------------------------------------------------------------
  dlq_delay_seconds              = var.dlq_delay_seconds != null ? var.dlq_delay_seconds : var.delay_seconds
  dlq_max_message_size           = var.dlq_max_message_size != null ? var.dlq_max_message_size : var.max_message_size
  dlq_message_retention_seconds  = var.dlq_message_retention_seconds != null ? var.dlq_message_retention_seconds : var.message_retention_seconds
  dlq_receive_wait_time_seconds  = var.dlq_receive_wait_time_seconds != null ? var.dlq_receive_wait_time_seconds : var.receive_wait_time_seconds
  dlq_visibility_timeout_seconds = var.dlq_visibility_timeout_seconds != null ? var.dlq_visibility_timeout_seconds : var.visibility_timeout_seconds

  dlq_content_based_deduplication = var.dlq_content_based_deduplication != null ? var.dlq_content_based_deduplication : var.content_based_deduplication
  dlq_deduplication_scope         = var.dlq_deduplication_scope != null ? var.dlq_deduplication_scope : var.deduplication_scope
  dlq_fifo_throughput_limit       = var.dlq_fifo_throughput_limit != null ? var.dlq_fifo_throughput_limit : var.fifo_throughput_limit
}

###############################################################################
# Primary SQS queue
###############################################################################

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = local.queue_name
  name_prefix = local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue && var.content_based_deduplication ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = local.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  redrive_policy = var.create && var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags
}

###############################################################################
# Dead-letter queue
###############################################################################

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? local.dlq_content_based_deduplication : null
  deduplication_scope         = var.fifo_queue && local.dlq_content_based_deduplication ? local.dlq_deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? local.dlq_fifo_throughput_limit : null

  delay_seconds              = local.dlq_delay_seconds
  max_message_size           = local.dlq_max_message_size
  message_retention_seconds  = local.dlq_message_retention_seconds
  receive_wait_time_seconds  = local.dlq_receive_wait_time_seconds
  visibility_timeout_seconds = local.dlq_visibility_timeout_seconds

  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.dlq_sqs_managed_sse_enabled

  tags = var.tags
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  })
}

###############################################################################
# Queue policy (merged source/override documents plus custom statements)
###############################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.policy_statements

    content {
      sid     = try(statement.value.sid, null)
      effect  = coalesce(try(statement.value.effect, null), "Allow")
      actions = try(statement.value.actions, null)

      not_actions = try(statement.value.not_actions, null)

      # Default the statement resource to the created queue ARN when unspecified
      resources = try(length(statement.value.resources), 0) > 0 ? statement.value.resources : [aws_sqs_queue.this[0].arn]

      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.condition, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].id
  policy    = data.aws_iam_policy_document.this[0].json
}

###############################################################################
# Optional IAM role granting access to the created queue(s)
###############################################################################

resource "aws_iam_role" "this" {
  count = var.create && var.create_iam_role ? 1 : 0

  name               = var.iam_role_name
  name_prefix        = var.iam_role_name == null ? "sqs-access-" : null
  assume_role_policy = var.iam_role_assume_role_policy

  tags = var.tags
}

data "aws_iam_policy_document" "queue_access" {
  count = var.create && var.create_iam_role ? 1 : 0

  statement {
    sid    = "SqsQueueAccess"
    effect = "Allow"

    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:ChangeMessageVisibility",
      "sqs:PurgeQueue",
      "sqs:ListQueueTags",
    ]

    resources = compact(concat(
      [aws_sqs_queue.this[0].arn],
      var.create_dlq ? [aws_sqs_queue.dlq[0].arn] : [],
    ))
  }
}

resource "aws_iam_role_policy" "this" {
  count = var.create && var.create_iam_role ? 1 : 0

  name   = "sqs-queue-access"
  role   = aws_iam_role.this[0].id
  policy = data.aws_iam_policy_document.queue_access[0].json
}

###############################################################################
# Outputs
###############################################################################

output "queue_id" {
  description = "The URL of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "The URL of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The name of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "queue_policy" {
  description = "The JSON policy attached to the primary queue (null when create_queue_policy is false)."
  value       = try(data.aws_iam_policy_document.this[0].json, null)
}

output "dead_letter_queue_id" {
  description = "The URL of the dead-letter queue (null when create_dlq is false)."
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dead_letter_queue_arn" {
  description = "The ARN of the dead-letter queue (null when create_dlq is false)."
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_url" {
  description = "The URL of the dead-letter queue (null when create_dlq is false)."
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dead_letter_queue_name" {
  description = "The name of the dead-letter queue (null when create_dlq is false)."
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

output "iam_role_arn" {
  description = "ARN of the optional IAM role granting access to the queues (null when create_iam_role is false)."
  value       = try(aws_iam_role.this[0].arn, null)
}

