###############################################################################
# Terraform & provider configuration
###############################################################################
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################
variable "region" {
  description = "AWS region where the backup vault, plan and role are created."
  type        = string
  default     = "us-east-1"
}

variable "backup_name" {
  description = "REQUIRED identifier for the backup vault/workload. Base name used for the vault, plan and IAM role. A default is supplied so the template validates and deploys out of the box."
  type        = string
  default     = "workload-backup"

  validation {
    condition     = length(var.backup_name) > 0 && length(var.backup_name) <= 50
    error_message = "backup_name must be between 1 and 50 characters."
  }
}

variable "account_type" {
  description = "Account role in the multi-account backup pattern: 'workload' creates the backup plan/selection/IAM role, 'backup' hosts the central (destination) vault."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional customer managed KMS key ARN used to encrypt the backup vault. Leave empty to use AWS owned keys."
  type        = string
  default     = ""
}

variable "vault_policy" {
  description = "Optional JSON encoded backup vault access policy. When empty, a default policy allowing the AWS Backup service, the local account root and any cross_account_ids to copy into the vault is generated."
  type        = string
  default     = ""
}

variable "cross_account_ids" {
  description = "List of trusted AWS account IDs allowed to copy recovery points into this vault (used by the generated default vault policy)."
  type        = list(string)
  default     = []
}

variable "min_retention_days" {
  description = "Minimum retention (days) enforced by the vault lock. When null no vault lock is configured."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Optional maximum retention (days) enforced by the vault lock."
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Optional grace period (days) during which the vault lock can still be modified. Must be between 3 and 36500 when set. Omit for compliance mode."
  type        = number
  default     = null

  validation {
    condition     = var.changeable_for_days == null || (var.changeable_for_days >= 3 && var.changeable_for_days <= 36500)
    error_message = "changeable_for_days must be null or a number between 3 and 36500."
  }
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to configure vault notifications for failed backup/copy jobs."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN that receives backup vault notification events. Required when enable_aws_backup_vault_notifications is true."
  type        = string
  default     = ""
}

variable "backup_vault_events" {
  description = "Backup vault events that trigger notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "backup_rule_schedule" {
  description = "Cron expression for the backup rule schedule."
  type        = string
  default     = "cron(0 5 * * ? *)"

  validation {
    condition     = length(var.backup_rule_schedule) > 0
    error_message = "backup_rule_schedule must be a non-empty cron expression."
  }
}

variable "start_window" {
  description = "Minutes after the scheduled time that the backup job must start (defaults to the required 60 minutes)."
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Minutes after the scheduled time that the backup job must complete (defaults to the required 120 minutes)."
  type        = number
  default     = 120
}

variable "cold_storage_after" {
  description = "Days after creation when the recovery point is transitioned to cold storage."
  type        = number
  default     = 30
}

variable "delete_after" {
  description = "Days after creation when the recovery point is deleted."
  type        = number
  default     = 120
}

variable "recovery_point_tags" {
  description = "Tags applied to every recovery point created by the backup plan."
  type        = map(string)
  default = {
    Backup = "true"
  }
}

variable "copy_actions" {
  description = "Dynamic cross-region and/or cross-account copy actions. Each entry requires a destination_vault_arn and may override the copied recovery point lifecycle."
  type = list(object({
    destination_vault_arn = string
    cold_storage_after    = optional(number, 30)
    delete_after          = optional(number, 120)
  }))
  default = []
}

variable "selection_resources" {
  description = "Optional explicit resource ARNs added to an additional resource based backup selection."
  type        = list(string)
  default     = []
}

variable "force_destroy" {
  description = "Whether the backup vault can be destroyed even if it still contains recovery points."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags applied to all supported resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################
locals {
  is_workload = var.account_type == "workload"

  tags = merge(
    var.tags,
    {
      Name        = var.backup_name
      ManagedBy   = "terraform"
      AccountType = var.account_type
    }
  )

  backup_plan_name = "plan-${var.backup_name}-backup"
  backup_role_name = "aws-backup-${var.backup_name}"

  default_vault_policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "AllowBackupServiceToCopyIntoVault"
          Effect = "Allow"
          Principal = {
            Service = "backup.amazonaws.com"
          }
          Action   = ["backup:CopyIntoBackupVault"]
          Resource = "*"
          Condition = {
            StringEquals = {
              "aws:SourceAccount" = data.aws_caller_identity.current.account_id
            }
          }
        },
        {
          Sid    = "AllowAccountRootToCopyIntoVault"
          Effect = "Allow"
          Principal = {
            AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
          }
          Action   = ["backup:CopyIntoBackupVault"]
          Resource = "*"
        }
      ],
      length(var.cross_account_ids) > 0 ? [
        {
          Sid    = "AllowTrustedAccountsToCopyIntoVault"
          Effect = "Allow"
          Principal = {
            AWS = [
              for account_id in var.cross_account_ids :
              "arn:${data.aws_partition.current.partition}:iam::${account_id}:root"
            ]
          }
          Action   = ["backup:CopyIntoBackupVault"]
          Resource = "*"
        }
      ] : []
    )
  })

  vault_policy = var.vault_policy != "" ? var.vault_policy : local.default_vault_policy
}

###############################################################################
# Backup vault (created in both workload and backup accounts)
###############################################################################
resource "aws_backup_vault" "this" {
  name          = var.backup_name
  kms_key_arn   = var.kms_key_arn != "" ? var.kms_key_arn : null
  force_destroy = var.force_destroy

  tags = local.tags
}

resource "aws_backup_vault_policy" "this" {
  backup_vault_name = aws_backup_vault.this.name
  policy            = local.vault_policy
}

###############################################################################
# Vault lock (only when a minimum retention is supplied)
###############################################################################
resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

###############################################################################
# Optional vault notifications for failed jobs
###############################################################################
resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events

  lifecycle {
    precondition {
      condition     = var.sns_topic_arn != ""
      error_message = "sns_topic_arn must be provided when enable_aws_backup_vault_notifications is true."
    }
  }
}

###############################################################################
# Workload account resources: IAM role, backup plan and selections
###############################################################################
resource "aws_iam_role" "backup" {
  count = local.is_workload ? 1 : 0

  name = local.backup_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBackupServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = local.is_workload ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "this" {
  count = local.is_workload ? 1 : 0

  name = local.backup_plan_name
  tags = local.tags

  rule {
    rule_name         = "${local.backup_plan_name}-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.backup_rule_schedule

    start_window      = var.start_window
    completion_window = var.completion_window

    lifecycle {
      cold_storage_after = var.cold_storage_after
      delete_after       = var.delete_after
    }

    recovery_point_tags = var.recovery_point_tags

    dynamic "copy_action" {
      for_each = var.copy_actions

      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        lifecycle {
          cold_storage_after = copy_action.value.cold_storage_after
          delete_after       = copy_action.value.delete_after
        }
      }
    }
  }
}

resource "aws_backup_selection" "tags" {
  count = local.is_workload ? 1 : 0

  name         = "${local.backup_plan_name}-tags"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "resources" {
  count = local.is_workload && length(var.selection_resources) > 0 ? 1 : 0

  name         = "${local.backup_plan_name}-resources"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn
  resources    = var.selection_resources
}

###############################################################################
# Outputs
###############################################################################
output "backup_vault_name" {
  description = "Name of the AWS Backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_vault_arn" {
  description = "ARN of the AWS Backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_vault_policy" {
  description = "Effective vault access policy (generated or supplied)."
  value       = local.vault_policy
}

output "backup_role_arn" {
  description = "ARN of the AWS Backup IAM role (workload accounts only)."
  value       = try(aws_iam_role.backup[0].arn, null)
}

output "backup_plan_id" {
  description = "ID of the backup plan (workload accounts only)."
  value       = try(aws_backup_plan.this[0].id, null)
}

output "backup_plan_arn" {
  description = "ARN of the backup plan (workload accounts only)."
  value       = try(aws_backup_plan.this[0].arn, null)
}

###############################################################################
# AWS Config compliance auditing & security monitoring stack
#
# Records configuration changes for all supported (global + regional) resource
# types, delivers snapshots to an S3 bucket and notifications to an encrypted
# SNS topic, and evaluates eleven managed AWS Config rules.
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables (all with defaults so the stack is deployable as-is)
###############################################################################

variable "region" {
  description = "AWS region in which the AWS Config stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = <<-EOT
    Name produced by the naming convention module for the AWS Config stack.
    Defaults to "config". When set to null or an empty string, a petname
    fallback ("config-<petname>") is generated instead.
  EOT
  type        = string
  default     = "config"

  validation {
    condition     = var.name == null ? true : length(trimspace(var.name)) <= 48
    error_message = "The name must either be null/empty (petname fallback) or at most 48 characters long."
  }
}

variable "tags" {
  description = "Additional tags applied to every taggable resource in the stack."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
  }
}

variable "managed_rules" {
  description = <<-EOT
    Map of managed AWS Config rules to deploy. The map key becomes the rule
    name; source_identifier is the AWS managed rule identifier. Optional
    input_parameters and resource_types (rule scope) may be supplied per rule.
  EOT
  type = map(object({
    source_identifier = string
    description       = optional(string)
    input_parameters  = optional(map(string))
    resource_types    = optional(list(string))
  }))

  default = {
    "cloudtrail-enabled" = {
      source_identifier = "CLOUD_TRAIL_ENABLED"
      description       = "Checks that AWS CloudTrail is enabled and actively logging in the account."
    }
    "iam-pw-policy" = {
      source_identifier = "IAM_PASSWORD_POLICY"
      description       = "Checks that the IAM account password policy meets the security requirements."
    }
    "ec2-vpc" = {
      source_identifier = "INSTANCES_IN_VPC"
      description       = "Checks that all EC2 instances are launched inside a VPC."
    }
    "root-mfa-enabled" = {
      source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
      description       = "Checks that multi-factor authentication is enabled for the root user."
    }
    "acm-expiration-check" = {
      source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
      description       = "Checks that ACM certificates are not expiring within the next 30 days."
    }
    "ebs-inuse-check" = {
      source_identifier = "EC2_VOLUME_INUSE_CHECK"
      description       = "Checks that EBS volumes are attached to an EC2 instance."
    }
    "ec2-imdsv2-check" = {
      source_identifier = "EC2_IMDSV2_CHECK"
      description       = "Checks that EC2 instance metadata is configured to require IMDSv2."
    }
    "rds-encrypted" = {
      source_identifier = "RDS_STORAGE_ENCRYPTED"
      description       = "Checks that RDS DB instances have storage encryption enabled."
    }
    "rds-private" = {
      source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
      description       = "Checks that RDS DB instances are not publicly accessible."
    }
    "rds-private-snapshots" = {
      source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
      description       = "Checks that RDS snapshots are not shared publicly."
    }
    "required-tags" = {
      source_identifier = "REQUIRED_TAGS"
      description       = "Checks that S3 buckets carry the terraform.io and environment tags."
      input_parameters  = { tag1Key = "terraform.io", tag2Key = "environment" }
      resource_types    = ["S3::Bucket"]
    }
  }
}

###############################################################################
# Context data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Naming convention module: name defaults to "config", with a petname fallback
# when the supplied name is null or empty.
###############################################################################

resource "random_pet" "name" {
  count     = var.name != null && trimspace(var.name) != "" ? 0 : 1
  length    = 2
  separator = "-"
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  name_is_provided = var.name != null ? trimspace(var.name) != "" : false

  # Resolved resource name used by the IAM role, recorder, delivery channel and SNS topic.
  name = local.name_is_provided ? lower(trimspace(var.name)) : format("config-%s", one(random_pet.name[*].id))

  s3_key_prefix = "awsconfig/records"

  bucket_name = lower(format("%s-config-snapshots-%s-%s", local.name, local.account_id, local.region))

  tags = merge(var.tags, { Name = local.name })
}

###############################################################################
# IAM role for AWS Config (+ AWS_ConfigRole managed policy + inline policy)
###############################################################################

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    sid     = "AllowConfigServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config" {
  name                 = local.name
  description          = "Role assumed by AWS Config to record resource configurations and deliver snapshots and notifications."
  assume_role_policy   = data.aws_iam_policy_document.config_assume_role.json
  max_session_duration = 43200

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_inline" {
  # Write access to the (force-destroy enabled) snapshot storage bucket.
  statement {
    sid    = "WriteConfigSnapshotsToBucket"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:AbortMultipartUpload",
      "s3:GetBucketAcl",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]
    resources = [
      aws_s3_bucket.snapshot.arn,
      "${aws_s3_bucket.snapshot.arn}/${local.s3_key_prefix}/*",
    ]
  }

  # Publish streaming notifications to the encrypted topic.
  statement {
    sid    = "PublishConfigNotifications"
    effect = "Allow"
    actions = [
      "sns:Publish",
      "sns:GetTopicAttributes",
      "sns:ListTopics",
    ]
    resources = [aws_sns_topic.this.arn]
  }

  # Required to publish to an SNS topic encrypted with a customer managed key.
  statement {
    sid    = "UseKmsKeyForEncryptedNotifications"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.this.arn]
  }
}

resource "aws_iam_role_policy" "config_inline" {
  name   = "config-delivery-permissions"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_inline.json
}

###############################################################################
# S3 snapshot storage bucket (force destroy enabled)
###############################################################################

resource "aws_s3_bucket" "snapshot" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Keep ACLs enabled so AWS Config can deliver objects with the
# bucket-owner-full-control ACL used during delivery.
resource "aws_s3_bucket_ownership_controls" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_versioning" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "snapshot_bucket" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl", "s3:ListBucket"]
    resources = [aws_s3_bucket.snapshot.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.snapshot.arn}/${local.s3_key_prefix}/AWSLogs/${local.account_id}/Config/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowConfigRoleObjectAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.config.arn]
    }

    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:AbortMultipartUpload",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.snapshot.arn,
      "${aws_s3_bucket.snapshot.arn}/${local.s3_key_prefix}/*",
    ]
  }
}

resource "aws_s3_bucket_policy" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id
  policy = data.aws_iam_policy_document.snapshot_bucket.json
}

###############################################################################
# Customer managed KMS key (automatic rotation) for the SNS topic
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSnsServiceToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions   = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowAccountPrincipalsThroughSns"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sns.${local.region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "this" {
  description             = "Customer managed key encrypting the AWS Config notification topic (${local.name})."
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = local.tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/${local.name}-config-sns"
  target_key_id = aws_kms_key.this.key_id
}

###############################################################################
# SNS topic (named after the resource) encrypted with the KMS key
###############################################################################

resource "aws_sns_topic" "this" {
  name              = local.name
  kms_master_key_id = aws_kms_key.this.id

  tags = local.tags
}

data "aws_iam_policy_document" "sns" {
  statement {
    sid    = "AllowOwnerFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
    ]

    resources = [aws_sns_topic.this.arn]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowConfigServicePublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.this.arn]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  arn    = aws_sns_topic.this.arn
  policy = data.aws_iam_policy_document.sns.json
}

###############################################################################
# AWS Config recorder + delivery channel (all supported resource types)
###############################################################################

resource "aws_config_configuration_recorder" "this" {
  name     = local.name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "this" {
  name           = local.name
  s3_bucket_name = aws_s3_bucket.snapshot.id
  s3_key_prefix  = local.s3_key_prefix
  sns_topic_arn  = aws_sns_topic.this.arn

  snapshot_delivery_properties {
    delivery_frequency = "Six_Hours"
  }

  depends_on = [
    aws_s3_bucket_policy.snapshot,
    aws_sns_topic_policy.this,
  ]
}

resource "aws_config_configuration_recorder_status" "this" {
  name       = aws_config_configuration_recorder.this.name
  is_enabled = true

  depends_on = [
    aws_config_delivery_channel.this,
    aws_iam_role_policy_attachment.config_managed,
    aws_iam_role_policy.config_inline,
  ]
}

###############################################################################
# Managed AWS Config rules (evaluated every 24 hours / on configuration change)
###############################################################################

resource "aws_config_config_rule" "managed" {
  for_each = var.managed_rules

  name        = each.key
  description = coalesce(each.value.description, format("Managed AWS Config rule %s.", each.value.source_identifier))

  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = each.value.source_identifier
  }

  input_parameters = each.value.input_parameters == null ? null : jsonencode(each.value.input_parameters)

  dynamic "scope" {
    for_each = each.value.resource_types == null ? [] : [each.value.resource_types]

    content {
      compliance_resource_types = scope.value
    }
  }

  depends_on = [aws_config_configuration_recorder_status.this]
}

###############################################################################
# Outputs
###############################################################################

output "config_role_name" {
  description = "Name of the IAM role used by AWS Config."
  value       = aws_iam_role.config.name
}

output "config_role_arn" {
  description = "ARN of the IAM role used by AWS Config."
  value       = aws_iam_role.config.arn
}

output "snapshot_bucket_name" {
  description = "S3 bucket receiving AWS Config snapshots and history."
  value       = aws_s3_bucket.snapshot.bucket
}

output "s3_key_prefix" {
  description = "S3 key prefix used for AWS Config records."
  value       = local.s3_key_prefix
}

output "sns_topic_arn" {
  description = "Encrypted SNS topic receiving AWS Config notifications."
  value       = aws_sns_topic.this.arn
}

output "kms_key_arn" {
  description = "Customer managed KMS key used to encrypt the SNS topic."
  value       = aws_kms_key.this.arn
}

output "config_rule_names" {
  description = "Names of the deployed managed AWS Config rules."
  value       = sort(keys(aws_config_config_rule.managed))
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

########################################
# Variables
########################################

variable "aws_region" {
  description = "AWS region to deploy the network stack into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "project_tag" {
  description = "Value for the Project tag"
  type        = string
  default     = "BJIT DevOps Task"
}

variable "author_tag" {
  description = "Value for the Author tag"
  type        = string
  default     = "Ariful Islam"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the three public subnets (one per AZ)"
  type        = list(string)
  default     = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the three private subnets (one per AZ)"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

########################################
# Data Sources & Locals
########################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  common_tags = {
    Project = var.project_tag
    Author  = var.author_tag
  }
}

########################################
# VPC
########################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "bjit-vpc"
  })
}

########################################
# Public Subnets
########################################

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "bjit-public-subnet-${count.index + 1}"
    Tier = "Public"
  })
}

########################################
# Private Subnets
########################################

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "bjit-private-subnet-${count.index + 1}"
    Tier = "Private"
  })
}

########################################
# Internet Gateway
########################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-internet-gateway"
  })
}

########################################
# Public Route Table (shared by all public subnets)
########################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-public-route-table"
    Tier = "Public"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

########################################
# Private Route Tables (one per zone, one per private subnet)
########################################

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "bjit-private-route-table-${count.index + 1}"
    Tier = "Private"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

########################################
# S3 Gateway VPC Endpoint
# Associated with all three private route tables
########################################

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(local.common_tags, {
    Name = "bjit-s3-gateway-endpoint"
  })
}

resource "aws_vpc_endpoint_route_table_association" "s3" {
  count = 3

  route_table_id  = aws_route_table.private[count.index].id
  vpc_endpoint_id = aws_vpc_endpoint.s3.id
}

########################################
# Security Groups
########################################

# ALB security group: HTTP/HTTPS from anywhere, egress limited to VPC CIDR
resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "Security group for the API server Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-ALB-SG"
  })
}

# MariaDB / RDS security group: MySQL port from VPC CIDR, egress limited to VPC CIDR
resource "aws_security_group" "rds" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "Security group for the MariaDB/MySQL RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL/MariaDB from inside the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-mariaDB-RDS-SG"
  })
}

# Redis security group: Redis port from VPC CIDR, egress limited to VPC CIDR
resource "aws_security_group" "redis" {
  name        = "bjit-redis-SG"
  description = "Security group for the Redis cache cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis from inside the VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-redis-SG"
  })
}

# API server security group: 8080 + 22 from VPC CIDR, egress limited to VPC CIDR
resource "aws_security_group" "api_server" {
  name        = "bjit-api-server-SG"
  description = "Security group for the API server instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Application port from inside the VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from inside the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-api-server-SG"
  })
}

# File server security group: 8081 + 22 from VPC CIDR, egress limited to VPC CIDR
resource "aws_security_group" "file_server" {
  name        = "bjit-file-server-SG"
  description = "Security group for the file server instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Application port from inside the VPC"
    from_port   = 8081
    to_port     = 8081
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from inside the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-file-server-SG"
  })
}

# Public SSH security group: SSH from VPC CIDR, egress limited to VPC CIDR
resource "aws_security_group" "public_ssh" {
  name        = "bjit-public-ssh-SG"
  description = "Security group allowing SSH access from inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from inside the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "bjit-public-ssh-SG"
  })
}

########################################
# Outputs
########################################

output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "ID of the shared public route table"
  value       = aws_route_table.public.id
}

output "private_route_table_ids" {
  description = "IDs of the zone-specific private route tables"
  value       = aws_route_table.private[*].id
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint"
  value       = aws_vpc_endpoint.s3.id
}

output "security_group_ids" {
  description = "Map of security group names to their IDs"
  value = {
    alb          = aws_security_group.alb.id
    rds          = aws_security_group.rds.id
    redis        = aws_security_group.redis.id
    api_server   = aws_security_group.api_server.id
    file_server  = aws_security_group.file_server.id
    public_ssh   = aws_security_group.public_ssh.id
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "base_name" {
  description = "Base name/prefix used to name all resources."
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "List of CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "List of CIDR blocks for private subnets. Set to null to skip private tiers."
  type        = list(string)
  default     = null
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# VPC + Internet Gateway
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "${var.base_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.base_name}-igw"
  })
}

###############################################################################
# Public subnets (AZ index starts at 1 -> "second zone")
###############################################################################

resource "aws_subnet" "public" {
  count = length(var.subnet_public_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index + 1]
  map_public_ip_on_launch = true

  tags = merge(var.tags, {
    Name = "${var.base_name}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.tags, {
    Name = "${var.base_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private subnets (conditional) + NAT gateways + private route tables
###############################################################################

resource "aws_subnet" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_private_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = merge(var.tags, {
    Name = "${var.base_name}-private-${count.index + 1}"
    Tier = "private"
  })
}

# One Elastic IP per public subnet (only when private tiers are requested).
resource "aws_eip" "nat" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_public_cidrs)

  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${var.base_name}-nat-eip-${count.index + 1}"
  })
}

# One NAT gateway per public subnet (only when private tiers are requested).
resource "aws_nat_gateway" "nat" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_public_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(var.tags, {
    Name = "${var.base_name}-nat-${count.index + 1}"
  })
}

resource "aws_route_table" "private" {
  count = var.subnet_private_cidrs == null ? 0 : length(var.subnet_private_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index % length(aws_nat_gateway.nat)].id
  }

  tags = merge(var.tags, {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# VPC Gateway Endpoints
###############################################################################

# S3 gateway endpoint attached to the public route table (always created).
resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = merge(var.tags, {
    Name = "${var.base_name}-s3-public-endpoint"
  })
}

# Dedicated S3 gateway endpoint attached to the private route tables
# (only created when private subnets exist).
resource "aws_vpc_endpoint" "s3_private" {
  count = var.subnet_private_cidrs == null ? 0 : 1

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(var.tags, {
    Name = "${var.base_name}-s3-private-endpoint"
  })
}

###############################################################################
# ECR security group + Interface endpoints
###############################################################################

resource "aws_security_group" "ecr" {
  name_prefix = "${var.base_name}-ecr-endpoints-"
  description = "Security group for ECR VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.base_name}-ecr-endpoints-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

# Egress is restricted to the VPC CIDR only.
resource "aws_security_group_rule" "ecr_egress_vpc" {
  type              = "egress"
  description       = "Allow egress within the VPC CIDR only"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.ecr.id
}

# HTTPS ingress from all public subnet CIDRs.
resource "aws_security_group_rule" "ecr_ingress_public" {
  type              = "ingress"
  description       = "Allow HTTPS from public subnets"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = var.subnet_public_cidrs
  security_group_id = aws_security_group.ecr.id
}

# Conditional HTTPS ingress from private subnet CIDRs.
resource "aws_security_group_rule" "ecr_ingress_private" {
  count = var.subnet_private_cidrs == null ? 0 : 1

  type              = "ingress"
  description       = "Allow HTTPS from private subnets"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = var.subnet_private_cidrs
  security_group_id = aws_security_group.ecr.id
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.region}.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)
  security_group_ids  = [aws_security_group.ecr.id]
  private_dns_enabled = true

  tags = merge(var.tags, {
    Name = "${var.base_name}-ecr-api-endpoint"
  })
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.region}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)
  security_group_ids  = [aws_security_group.ecr.id]
  private_dns_enabled = true

  tags = merge(var.tags, {
    Name = "${var.base_name}-ecr-dkr-endpoint"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (empty when not provisioned)."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways (empty when private tiers are disabled)."
  value       = aws_nat_gateway.nat[*].id
}

output "ecr_security_group_id" {
  description = "ID of the ECR endpoints security group."
  value       = aws_security_group.ecr.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "region" {
  description = "AWS region in which to deploy the network stack."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the two public subnets (AZ1, AZ2)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the two private subnets (AZ1, AZ2)."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "admin_cidr" {
  description = "Placeholder administrator CIDR allowed to SSH into the public tier."
  type        = string
  default     = "203.0.113.0/24"
}

# ---------------------------------------------------------------------------
# Availability zones (first two available in the region)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "project-vpc"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "T-igw"
  }
}

# ---------------------------------------------------------------------------
# Public subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "pub-sub-${count.index + 1}"
  }
}

# ---------------------------------------------------------------------------
# Private subnets
# ---------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "pvt-sub-${count.index + 1}"
  }
}

# ---------------------------------------------------------------------------
# Elastic IPs + NAT Gateways (one per AZ, both placed in public subnets)
# ---------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count  = 2
  domain = "vpc"

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  count         = 2
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

# ---------------------------------------------------------------------------
# Public route tables (RT_PUBRT-1 / RT_PUBRT-2) -> Internet Gateway
# ---------------------------------------------------------------------------

resource "aws_route_table" "public" {
  count  = 2
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "RT_PUBRT-${count.index + 1}"
  }
}

resource "aws_route" "public_internet" {
  count                  = 2
  route_table_id         = aws_route_table.public[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[count.index].id
}

# ---------------------------------------------------------------------------
# Private route tables (RT_PVTRT-1 / RT_PVTRT-2) -> first NAT Gateway
# ---------------------------------------------------------------------------

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "RT_PVTRT-${count.index + 1}"
  }
}

resource "aws_route" "private_nat" {
  count                  = 2
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[0].id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# Public security group: allow_tls
# ---------------------------------------------------------------------------

resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Public tier SG: HTTP/HTTPS from anywhere, SSH from admin range, egress limited to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from admin range only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_tls"
  }
}

# ---------------------------------------------------------------------------
# Private security group: pvt-seg
# ---------------------------------------------------------------------------

resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Private tier SG: app/DB ports reachable only from the public SG, egress only to public SG"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from public SG"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "HTTPS from public SG"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "SSH from public SG"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "PostgreSQL from public SG"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  egress {
    description     = "Egress restricted to the public SG only"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.allow_tls.id]
  }

  tags = {
    Name = "pvt-seg"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used for the subnets."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the two public subnets (pub-sub-1, pub-sub-2)."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the two private subnets (pvt-sub-1, pvt-sub-2)."
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway (T-igw)."
  value       = aws_internet_gateway.igw.id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT Gateways (T-NAT1)."
  value       = aws_nat_gateway.nat[*].id
}

output "nat_gateway_public_ips" {
  description = "Elastic IP addresses attached to the NAT Gateways."
  value       = aws_eip.nat[*].public_ip
}

output "public_route_table_ids" {
  description = "IDs of the public route tables (RT_PUBRT-1, RT_PUBRT-2)."
  value       = aws_route_table.public[*].id
}

output "private_route_table_ids" {
  description = "IDs of the private route tables (RT_PVTRT-1, RT_PVTRT-2)."
  value       = aws_route_table.private[*].id
}

output "public_security_group_id" {
  description = "ID of the public security group (allow_tls)."
  value       = aws_security_group.allow_tls.id
}

output "private_security_group_id" {
  description = "ID of the private security group (pvt-seg)."
  value       = aws_security_group.pvt_seg.id
}

###############################################################################
# Terraform : Serverless API Gateway -> DynamoDB (no Lambda) pattern
#
#   POST /pets            -> dynamodb:PutItem   (VTL request mapping)
#   GET  /pets/{PetType}  -> dynamodb:Query     (PetType-index, VTL response map)
#
#   API key protected ("x-api-key") + usage plan + CloudWatch logging (INFO)
###############################################################################

###############################################################################
# Provider / versions / variables / data sources
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region where the serverless API Gateway -> DynamoDB pattern is deployed."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name used for the project related resources (log group prefix, etc.)."
  type        = string
  default     = "APIGW-DynamoDB-Serverless"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# DynamoDB : Pets table + PetType-index GSI
###############################################################################

resource "aws_dynamodb_table" "pets" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5

  hash_key = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity      = 5
    write_capacity     = 5
  }

  tags = {
    Name = "Pets"
  }
}

###############################################################################
# IAM : role assumed by API Gateway to access DynamoDB (PutItem / Query)
###############################################################################

resource "aws_iam_role" "apigw_dynamodb" {
  name        = "apigw-dynamodb-terraform-api-role"
  description = "Execution role used by API Gateway to integrate directly with the Pets DynamoDB table."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "apigw-dynamodb-terraform-api-role"
  }
}

resource "aws_iam_role_policy" "apigw_dynamodb" {
  name = "apigw-dynamodb-terraform-api-policy"
  role = aws_iam_role.apigw_dynamodb.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "PetsTableAndIndexesAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/*"
        ]
      }
    ]
  })
}

###############################################################################
# IAM : role assumed by API Gateway to push logs to CloudWatch
###############################################################################

resource "aws_iam_role" "apigw_cloudwatch" {
  name        = "apigw-dynamodb-terraform-cloudwatch-role"
  description = "Account level CloudWatch role used by API Gateway for execution/access logging."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "apigw-dynamodb-terraform-cloudwatch-role"
  }
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch" {
  role       = aws_iam_role.apigw_cloudwatch.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "this" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch.arn

  depends_on = [aws_iam_role_policy_attachment.apigw_cloudwatch]
}

###############################################################################
# CloudWatch : log group (prefixed /aws/APIGW/terraform) + delivery policy
###############################################################################

resource "aws_cloudwatch_log_group" "apigw" {
  name              = "/aws/APIGW/terraform/${var.project_name}"
  retention_in_days = 14

  tags = {
    Name = "${var.project_name}-access-logs"
  }
}

resource "aws_cloudwatch_log_resource_policy" "apigw" {
  policy_name = "apigw-dynamodb-terraform-log-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "APIGatewayLogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.apigw.arn}:*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:execute-api:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:${aws_api_gateway_rest_api.this.id}/*"
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

###############################################################################
# API Gateway : REST API, resources, methods, VTL integrations
###############################################################################

resource "aws_api_gateway_rest_api" "this" {
  name           = "APIGW DynamoDB Serverless Pattern Demo"
  description    = "Direct API Gateway to DynamoDB integration (no Lambda) for the Pets inventory."
  api_key_source = "HEADER"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

# /pets
resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = "pets"
}

# /pets/{PetType}
resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

###############################################################################
# POST /pets  ->  dynamodb:PutItem
###############################################################################

resource "aws_api_gateway_method" "pets_post" {
  rest_api_id      = aws_api_gateway_rest_api.this.id
  resource_id      = aws_api_gateway_resource.pets.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "pets_post" {
  rest_api_id             = aws_api_gateway_rest_api.this.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.pets_post.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.name}:dynamodb:action/PutItem"
  credentials             = aws_iam_role.apigw_dynamodb.arn
  passthrough_behavior    = "NEVER"

  request_templates = {
    "application/json" = <<-EOT
    {
      "TableName": "Pets",
      "Item": {
        "id": {
          "S": "$context.requestId"
        },
        "PetName": {
          "S": "$input.path('$.PetName')"
        },
        "PetType": {
          "S": "$input.path('$.PetType')"
        },
        "PetPrice": {
          "N": "$input.path('$.PetPrice')"
        },
        "PetBoolean": {
          "BOOL": true
        }
      }
    }
    EOT
  }
}

resource "aws_api_gateway_method_response" "pets_post_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.pets_post.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "pets_post_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.pets_post.http_method
  status_code = aws_api_gateway_method_response.pets_post_200.status_code

  depends_on = [aws_api_gateway_integration.pets_post]
}

###############################################################################
# GET /pets/{PetType}  ->  dynamodb:Query on PetType-index
###############################################################################

resource "aws_api_gateway_method" "pets_get" {
  rest_api_id      = aws_api_gateway_rest_api.this.id
  resource_id      = aws_api_gateway_resource.pet_type.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true

  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_integration" "pets_get" {
  rest_api_id             = aws_api_gateway_rest_api.this.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.pets_get.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.name}:dynamodb:action/Query"
  credentials             = aws_iam_role.apigw_dynamodb.arn
  passthrough_behavior    = "NEVER"

  request_parameters = {
    "integration.request.path.PetType" = "method.request.path.PetType"
  }

  request_templates = {
    "application/json" = <<-EOT
    {
      "TableName": "Pets",
      "IndexName": "PetType-index",
      "KeyConditionExpression": "PetType = :v1",
      "ExpressionAttributeValues": {
        ":v1": {
          "S": "$util.urlDecode($input.params('PetType'))"
        }
      }
    }
    EOT
  }
}

resource "aws_api_gateway_method_response" "pets_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.pets_get.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "pets_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.pets_get.http_method
  status_code = aws_api_gateway_method_response.pets_get_200.status_code

  response_templates = {
    "application/json" = <<-EOT
    #set($inputRoot = $input.path('$'))
    {
      "pets": [
    #foreach($elem in $inputRoot.Items)
        {
          "id": "$elem.id.S",
          "PetName": "$elem.PetName.S",
          "PetType": "$elem.PetType.S",
          "PetPrice": "$elem.PetPrice.N"
        }#if($foreach.hasNext),#end
    #end
      ]
    }
    EOT
  }

  depends_on = [aws_api_gateway_integration.pets_get]
}

###############################################################################
# Deployment + stage "v1" (INFO logging, metrics, access logs)
###############################################################################

resource "aws_api_gateway_deployment" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.pets.id,
      aws_api_gateway_resource.pet_type.id,
      aws_api_gateway_method.pets_post.id,
      aws_api_gateway_method.pets_get.id,
      aws_api_gateway_integration.pets_post.id,
      aws_api_gateway_integration.pets_get.id,
      aws_api_gateway_integration_response.pets_post_200.id,
      aws_api_gateway_integration_response.pets_get_200.id
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.pets_post,
    aws_api_gateway_integration.pets_get,
    aws_api_gateway_integration_response.pets_post_200,
    aws_api_gateway_integration_response.pets_get_200
  ]
}

resource "aws_api_gateway_stage" "this" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  deployment_id = aws_api_gateway_deployment.this.id
  stage_name    = "v1"
  description   = "Serverless API Gateway to DynamoDB pattern stage"

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.apigw.arn

    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      caller         = "$context.identity.caller"
      user           = "$context.identity.user"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  depends_on = [aws_api_gateway_account.this]
}

resource "aws_api_gateway_method_settings" "this" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  stage_name  = aws_api_gateway_stage.this.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled        = true
    logging_level          = "INFO"
    data_trace_enabled     = false
    throttling_burst_limit = 20
    throttling_rate_limit  = 100
  }

  depends_on = [
    aws_api_gateway_account.this,
    aws_api_gateway_stage.this
  ]
}

###############################################################################
# API key + usage plan (burst 20 / rate 100 / 1000 requests per month)
###############################################################################

resource "aws_api_gateway_api_key" "this" {
  name        = "apigw-dynamodb-terraform-api-key"
  description = "API key that protects the APIGW DynamoDB Serverless Pattern Demo API."
  enabled     = true
}

resource "aws_api_gateway_usage_plan" "this" {
  name        = "apigw-dynamodb-terraform-usage-plan"
  description = "Usage plan for the APIGW DynamoDB Serverless Pattern Demo API (v1 stage)."

  api_stages {
    api_id = aws_api_gateway_rest_api.this.id
    stage  = aws_api_gateway_stage.this.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_usage_plan_key" "this" {
  key_id        = aws_api_gateway_api_key.this.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.this.id
}

###############################################################################
# Outputs
###############################################################################

output "api_invoke_url" {
  description = "Base invoke URL of the deployed REST API stage."
  value       = "https://${aws_api_gateway_rest_api.this.id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_api_gateway_stage.this.stage_name}"
}

output "pets_post_endpoint" {
  description = "POST endpoint that writes a pet item into the Pets table."
  value       = "https://${aws_api_gateway_rest_api.this.id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_api_gateway_stage.this.stage_name}/pets"
}

output "pets_get_endpoint" {
  description = "GET endpoint that queries Pets by PetType (PetType-index)."
  value       = "https://${aws_api_gateway_rest_api.this.id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_api_gateway_stage.this.stage_name}/pets/{PetType}"
}

output "api_key_id" {
  description = "ID of the API key bound to the usage plan."
  value       = aws_api_gateway_api_key.this.id
}

output "api_key_value" {
  description = "Value of the API key to send in the x-api-key header."
  value       = aws_api_gateway_api_key.this.value
  sensitive   = true
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table holding the pet inventory."
  value       = aws_dynamodb_table.pets.name
}

output "cloudwatch_log_group_name" {
  description = "CloudWatch log group receiving API Gateway access logs."
  value       = aws_cloudwatch_log_group.apigw.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which to deploy the test S3 architecture."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name used to derive every bucket name in this stack."
  type        = string
  default     = "sadcloud"
}

variable "no_versioning" {
  description = "When true, versioning is NOT enabled on the primary bucket."
  type        = bool
  default     = false
}

variable "no_default_encryption" {
  description = "When true, no KMS key / default SSE-KMS encryption is applied to the primary bucket."
  type        = bool
  default     = false
}

variable "website_enabled" {
  description = "When true, static website hosting is enabled on the primary bucket."
  type        = bool
  default     = false
}

variable "no_logging" {
  description = "When true, the logging bucket and the primary bucket logging configuration are omitted."
  type        = bool
  default     = false
}

variable "bucket_acl" {
  description = "Canned ACL applied to the logging bucket."
  type        = string
  default     = "log-delivery-write"
}

variable "allow_cleartext" {
  description = "When true, a bucket policy denying all S3 actions over non-SSL transport is attached to the primary bucket."
  type        = bool
  default     = false
}

variable "s3_getobject_only" {
  description = "When true, creates a publicly readable bucket (s3:GetObject) named <name>-getonly."
  type        = bool
  default     = false
}

variable "s3_public" {
  description = "When true, creates a fully public bucket (s3:*) named <name>-public."
  type        = bool
  default     = false
}

###############################################################################
# Primary bucket
###############################################################################

resource "aws_s3_bucket" "main" {
  bucket_prefix = "${var.name}-"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  depends_on = [aws_s3_bucket_ownership_controls.main]

  bucket = aws_s3_bucket.main.id
  acl    = "private"
}

resource "aws_s3_bucket_versioning" "main" {
  count = var.no_versioning ? 0 : 1

  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Primary bucket default encryption (KMS, auto-rotating CMK)
###############################################################################

resource "aws_kms_key" "main" {
  count = var.no_default_encryption ? 0 : 1

  description             = "CMK for ${var.name} S3 bucket default encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count = var.no_default_encryption ? 0 : 1

  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main[0].arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Primary bucket static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "main" {
  count = var.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }
}

###############################################################################
# Logging bucket + its own KMS key
###############################################################################

resource "aws_kms_key" "logging" {
  count = var.no_logging ? 0 : 1

  description             = "CMK for ${var.name}-logging S3 bucket default encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_s3_bucket" "logging" {
  count = var.no_logging ? 0 : 1

  bucket        = "${var.name}-logging"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count = var.no_logging ? 0 : 1

  depends_on = [aws_s3_bucket_ownership_controls.logging]

  bucket = aws_s3_bucket.logging[0].id
  acl    = var.bucket_acl
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.no_logging ? 0 : 1

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging[0].arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "main" {
  count = var.no_logging ? 0 : 1

  depends_on = [aws_s3_bucket_acl.logging]

  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"
}

###############################################################################
# Deny non-SSL (cleartext) requests on the primary bucket
###############################################################################

resource "aws_s3_bucket_policy" "deny_cleartext" {
  count = var.allow_cleartext ? 1 : 0

  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

###############################################################################
# Optional public read-only bucket: <name>-getonly  (s3:GetObject)
###############################################################################

resource "aws_s3_bucket" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket        = "${var.name}-getonly"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  depends_on = [
    aws_s3_bucket_ownership_controls.getonly,
    aws_s3_bucket_public_access_block.getonly
  ]

  bucket = aws_s3_bucket.getonly[0].id
  acl    = "public-read"
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "getonly" {
  count = var.s3_getobject_only ? 1 : 0

  depends_on = [aws_s3_bucket_public_access_block.getonly]

  bucket = aws_s3_bucket.getonly[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowPublicRead"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.getonly[0].arn}/*"
      }
    ]
  })
}

###############################################################################
# Optional fully public bucket: <name>-public  (s3:*)
###############################################################################

resource "aws_s3_bucket" "public" {
  count = var.s3_public ? 1 : 0

  bucket        = "${var.name}-public"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "public" {
  count = var.s3_public ? 1 : 0

  depends_on = [
    aws_s3_bucket_ownership_controls.public,
    aws_s3_bucket_public_access_block.public
  ]

  bucket = aws_s3_bucket.public[0].id
  acl    = "public-read-write"
}

resource "aws_s3_bucket_public_access_block" "public" {
  count = var.s3_public ? 1 : 0

  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public" {
  count = var.s3_public ? 1 : 0

  depends_on = [aws_s3_bucket_public_access_block.public]

  bucket = aws_s3_bucket.public[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowPublicFullAccess"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*"
        ]
      }
    ]
  })
}

# Terraform Description

I'll create a self-contained AWS Elastic Disaster Recovery (DRS) IAM baseline. The configuration:

1. **Provider / Data** – AWS provider pinned to a configurable region (default `us-east-1`), plus `aws_caller_identity` and `aws_partition` data sources used throughout for account-scoped conditions.

2. **Six `/service-role/` service roles**:
   - `AWSElasticDisasterRecoveryAgentRole` – trusted by `drs.amazonaws.com`, conditioned on `aws:SourceAccount` + `sts:SourceIdentity` matching `s-*` (source servers). Attached: `AWSElasticDisasterRecoveryAgentPolicy`.
   - `AWSElasticDisasterRecoveryFailbackRole` – trusted by `drs.amazonaws.com`, conditioned on `aws:SourceAccount` + `sts:SourceIdentity` matching `i-*` (recovery instances). Attached: `AWSElasticDisasterRecoveryFailbackPolicy`.
   - `AWSElasticDisasterRecoveryConversionServerRole` – trusted by `ec2.amazonaws.com`. Attached: `AWSElasticDisasterRecoveryConversionServerPolicy`.
   - `AWSElasticDisasterRecoveryRecoveryInstanceRole` – trusted by `ec2.amazonaws.com`. Attached: `AWSElasticDisasterRecoveryRecoveryInstancePolicy`.
   - `AWSElasticDisasterRecoveryReplicationServerRole` – trusted by `ec2.amazonaws.com`. Attached: `AWSElasticDisasterRecoveryReplicationServerPolicy`.
   - `AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole` – trusted by `ec2.amazonaws.com`. Attached: both `AWSElasticDisasterRecoveryRecoveryInstancePolicy` and `AmazonSSMManagedInstanceCore`.

3. **Root-path initializer** – `AWSElasticDisasterRecoveryInitializerRole` (path `/`) trusted by the current calling identity ARN, with a customer-managed `InitializePolicy` granting: DRS service initialization, EC2 instance-profile lifecycle, `iam:PassRole` restricted to EC2/DRS, service-linked-role creation scoped to `AWSServiceRoleForElasticDisasterRecovery`, full `ec2:*`, and `iam:AttachRolePolicy`/`DetachRolePolicy` scoped to the DRS roles and further restricted (via `iam:PolicyARN`) to the DRS managed policies only.

All trust/permission documents are generated with `aws_iam_policy_document` data sources, and outputs expose the resulting ARNs.

```iac_template
###############################################################################
# AWS Elastic Disaster Recovery (DRS) — IAM Role & Policy Baseline
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the Elastic Disaster Recovery IAM baseline is deployed."
  type        = string
  default     = "us-east-1"
}

variable "service_role_path" {
  description = "IAM path used for all Elastic Disaster Recovery service roles."
  type        = string
  default     = "/service-role/"
}

variable "initializer_role_name" {
  description = "Name of the root-path Elastic Disaster Recovery initializer role."
  type        = string
  default     = "AWSElasticDisasterRecoveryInitializerRole"
}

variable "initialize_policy_name" {
  description = "Name of the customer managed policy bound to the initializer role."
  type        = string
  default     = "InitializePolicy"
}

###############################################################################
# Data Sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  common_tags = {
    ManagedBy = "Terraform"
    Purpose   = "AWS-Elastic-Disaster-Recovery-IAM-Baseline"
  }
}

locals {
  drs_managed_policies = {
    agent             = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticDisasterRecoveryAgentPolicy"
    failback          = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticDisasterRecoveryFailbackPolicy"
    conversion        = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticDisasterRecoveryConversionServerPolicy"
    recovery_instance = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
    replication       = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticDisasterRecoveryReplicationServerPolicy"
    ssm_core          = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
  }
}

###############################################################################
# Assume-Role Policy Documents
###############################################################################

# drs.amazonaws.com — DRS Agent role (source servers, "s-" prefix)
data "aws_iam_policy_document" "drs_agent_assume_role" {
  statement {
    sid     = "AllowDRSAgentServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["s-*"]
    }
  }
}

# drs.amazonaws.com — DRS Failback role (recovery instances, "i-" prefix)
data "aws_iam_policy_document" "drs_failback_assume_role" {
  statement {
    sid     = "AllowDRSFailbackServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["i-*"]
    }
  }
}

# ec2.amazonaws.com — shared by conversion / recovery / replication roles
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Root-path initializer role — assumed by the current calling identity
data "aws_iam_policy_document" "initializer_assume_role" {
  statement {
    sid     = "AllowCallingIdentityToAssumeInitializerRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
  }
}

###############################################################################
# DRS Service Roles (path: /service-role/)
###############################################################################

# ---------------------------------------------------------------------------
# 1. AWSElasticDisasterRecoveryAgentRole
# ---------------------------------------------------------------------------
resource "aws_iam_role" "agent" {
  name                 = "AWSElasticDisasterRecoveryAgentRole"
  path                 = var.service_role_path
  description          = "Role assumed by the AWS Elastic Disaster Recovery service to manage the DRS agent on source servers."
  assume_role_policy   = data.aws_iam_policy_document.drs_agent_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "agent" {
  role       = aws_iam_role.agent.name
  policy_arn = local.drs_managed_policies.agent
}

# ---------------------------------------------------------------------------
# 2. AWSElasticDisasterRecoveryFailbackRole
# ---------------------------------------------------------------------------
resource "aws_iam_role" "failback" {
  name                 = "AWSElasticDisasterRecoveryFailbackRole"
  path                 = var.service_role_path
  description          = "Role assumed by the AWS Elastic Disaster Recovery service during failback of recovery instances."
  assume_role_policy   = data.aws_iam_policy_document.drs_failback_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "failback" {
  role       = aws_iam_role.failback.name
  policy_arn = local.drs_managed_policies.failback
}

# ---------------------------------------------------------------------------
# 3. AWSElasticDisasterRecoveryConversionServerRole
# ---------------------------------------------------------------------------
resource "aws_iam_role" "conversion_server" {
  name                 = "AWSElasticDisasterRecoveryConversionServerRole"
  path                 = var.service_role_path
  description          = "Instance profile role for AWS Elastic Disaster Recovery conversion servers."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "conversion_server" {
  role       = aws_iam_role.conversion_server.name
  policy_arn = local.drs_managed_policies.conversion
}

# ---------------------------------------------------------------------------
# 4. AWSElasticDisasterRecoveryRecoveryInstanceRole
# ---------------------------------------------------------------------------
resource "aws_iam_role" "recovery_instance" {
  name                 = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path                 = var.service_role_path
  description          = "Instance profile role for AWS Elastic Disaster Recovery recovery instances."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "recovery_instance" {
  role       = aws_iam_role.recovery_instance.name
  policy_arn = local.drs_managed_policies.recovery_instance
}

# ---------------------------------------------------------------------------
# 5. AWSElasticDisasterRecoveryReplicationServerRole
# ---------------------------------------------------------------------------
resource "aws_iam_role" "replication_server" {
  name                 = "AWSElasticDisasterRecoveryReplicationServerRole"
  path                 = var.service_role_path
  description          = "Instance profile role for AWS Elastic Disaster Recovery replication servers."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "replication_server" {
  role       = aws_iam_role.replication_server.name
  policy_arn = local.drs_managed_policies.replication
}

# ---------------------------------------------------------------------------
# 6. AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole
# ---------------------------------------------------------------------------
resource "aws_iam_role" "recovery_instance_with_launch_actions" {
  name                 = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path                 = var.service_role_path
  description          = "Instance profile role for AWS Elastic Disaster Recovery recovery instances that execute post-launch actions via SSM."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_drs" {
  role       = aws_iam_role.recovery_instance_with_launch_actions.name
  policy_arn = local.drs_managed_policies.recovery_instance
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_ssm" {
  role       = aws_iam_role.recovery_instance_with_launch_actions.name
  policy_arn = local.drs_managed_policies.ssm_core
}

###############################################################################
# Root-Path Initializer Role + InitializePolicy
###############################################################################

resource "aws_iam_role" "initializer" {
  name                 = var.initializer_role_name
  path                 = "/"
  description          = "Root-path role used to initialize and bootstrap AWS Elastic Disaster Recovery in an account/region."
  assume_role_policy   = data.aws_iam_policy_document.initializer_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

data "aws_iam_policy_document" "initialize" {
  # 1. Service initialization
  statement {
    sid    = "InitializeDRSService"
    effect = "Allow"
    actions = [
      "drs:InitializeService",
    ]
    resources = ["*"]
  }

  # 2. Instance profile creation / lifecycle
  statement {
    sid    = "ManageInstanceProfiles"
    effect = "Allow"
    actions = [
      "iam:CreateInstanceProfile",
      "iam:DeleteInstanceProfile",
      "iam:GetInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:RemoveRoleFromInstanceProfile",
      "iam:TagInstanceProfile",
      "iam:UntagInstanceProfile",
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:instance-profile/*",
    ]
  }

  # 3. PassRole restricted to EC2 and DRS
  statement {
    sid       = "PassRoleToEC2AndDRS"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values = [
        "ec2.amazonaws.com",
        "drs.amazonaws.com",
      ]
    }
  }

  # 4. Service-linked role creation for AWSServiceRoleForElasticDisasterRecovery
  statement {
    sid       = "CreateDRSServiceLinkedRole"
    effect    = "Allow"
    actions   = ["iam:CreateServiceLinkedRole"]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery",
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values   = ["drs.amazonaws.com"]
    }
  }

  # 5. Full EC2 actions
  statement {
    sid       = "FullEC2Access"
    effect    = "Allow"
    actions   = ["ec2:*"]
    resources = ["*"]
  }

  # 6. Role policy attachments restricted to the DRS managed policies
  statement {
    sid    = "AttachOnlyDRSManagedPolicies"
    effect = "Allow"
    actions = [
      "iam:AttachRolePolicy",
      "iam:DetachRolePolicy",
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role${var.service_role_path}AWSElasticDisasterRecovery*",
    ]

    condition {
      test     = "ArnEquals"
      variable = "iam:PolicyARN"
      values = [
        local.drs_managed_policies.agent,
        local.drs_managed_policies.failback,
        local.drs_managed_policies.conversion,
        local.drs_managed_policies.recovery_instance,
        local.drs_managed_policies.replication,
        local.drs_managed_policies.ssm_core,
      ]
    }
  }
}

resource "aws_iam_policy" "initialize" {
  name        = var.initialize_policy_name
  path        = "/"
  description = "Permissions required to initialize AWS Elastic Disaster Recovery and bootstrap its service roles, instance profiles and service-linked role."
  policy      = data.aws_iam_policy_document.initialize.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "initializer" {
  role       = aws_iam_role.initializer.name
  policy_arn = aws_iam_policy.initialize.arn
}

###############################################################################
# Outputs
###############################################################################

output "drs_service_role_arns" {
  description = "ARNs of the Elastic Disaster Recovery service roles created under the /service-role/ path."
  value = {
    agent                                 = aws_iam_role.agent.arn
    failback                              = aws_iam_role.failback.arn
    conversion_server                     = aws_iam_role.conversion_server.arn
    recovery_instance                     = aws_iam_role.recovery_instance.arn
    replication_server                    = aws_iam_role.replication_server.arn
    recovery_instance_with_launch_actions = aws_iam_role.recovery_instance_with_launch_actions.arn
  }
}

output "initializer_role_arn" {
  description = "ARN of the root-path Elastic Disaster Recovery initializer role."
  value       = aws_iam_role.initializer.arn
}

output "initialize_policy_arn" {
  description = "ARN of the customer managed InitializePolicy bound to the initializer role."
  value       = aws_iam_policy.initialize.arn
}

output "initializer_trusted_principal" {
  description = "Calling identity allowed to assume the initializer role."
  value       = data.aws_caller_identity.current.arn
}
```

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region in which to deploy the infrastructure."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC."
  type        = string
  default     = "VPC_from_Terraform"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "security_group_name" {
  description = "Name of the security group."
  type        = string
  default     = "allow_ssh_http_https"
}

variable "instance_count" {
  description = "Number of EC2 instances to launch."
  type        = number
  default     = 3
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t2.micro"
}

variable "instance_name" {
  description = "Name tag applied to the EC2 instances."
  type        = string
  default     = "Terraform_Instance"
}

variable "root_volume_size" {
  description = "Size, in GB, of the encrypted root EBS volume."
  type        = number
  default     = 20
}

variable "root_volume_type" {
  description = "Volume type of the root EBS volume."
  type        = string
  default     = "gp2"
}

variable "root_volume_tag_name" {
  description = "Name tag applied to the root EBS volume."
  type        = string
  default     = "Terraform_EBS_Volume1"
}

variable "common_tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Terraform = "true"
  }
}

############################################
# Data sources
############################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

############################################
# Locals
############################################

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, length(var.private_subnet_cidrs))
}

############################################
# VPC
############################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.common_tags,
    {
      Name = var.vpc_name
    }
  )
}

############################################
# Private subnets (+ route table)
############################################

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.common_tags,
    {
      Name = "${var.vpc_name}-private-subnet-${count.index + 1}"
      Tier = "Private"
    }
  )
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.vpc_name}-private-route-table"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

############################################
# Security group
############################################

resource "aws_security_group" "allow_ssh_http_https" {
  name        = var.security_group_name
  description = "Allow SSH from the VPC CIDR and HTTP/HTTPS from anywhere"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    {
      Name                          = var.security_group_name
      Terraform_SG_HTTP_HTTPS_SSH   = "true"
    }
  )
}

resource "aws_vpc_security_group_ingress_rule" "ssh_from_vpc" {
  security_group_id = aws_security_group.allow_ssh_http_https.id
  description       = "SSH access restricted to the VPC CIDR block"
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.security_group_name}-ingress-ssh"
    }
  )
}

resource "aws_vpc_security_group_ingress_rule" "http_from_anywhere" {
  security_group_id = aws_security_group.allow_ssh_http_https.id
  description       = "HTTP access from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.security_group_name}-ingress-http"
    }
  )
}

resource "aws_vpc_security_group_ingress_rule" "https_from_anywhere" {
  security_group_id = aws_security_group.allow_ssh_http_https.id
  description       = "HTTPS access from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.security_group_name}-ingress-https"
    }
  )
}

resource "aws_vpc_security_group_egress_rule" "egress_to_vpc" {
  security_group_id = aws_security_group.allow_ssh_http_https.id
  description       = "Egress limited to the VPC CIDR block"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.security_group_name}-egress-vpc"
    }
  )
}

############################################
# EC2 instances
############################################

resource "aws_instance" "app" {
  count = var.instance_count

  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private[count.index % length(aws_subnet.private)].id
  vpc_security_group_ids      = [aws_security_group.allow_ssh_http_https.id]
  associate_public_ip_address = false

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = var.root_volume_size
    volume_type           = var.root_volume_type
    encrypted             = true
    delete_on_termination = true

    tags = merge(
      var.common_tags,
      {
        Name                      = var.root_volume_tag_name
        Terraform_EBS_Volume1     = "true"
      }
    )
  }

  tags = merge(
    var.common_tags,
    {
      Name = var.instance_name
    }
  )

  lifecycle {
    ignore_changes = [ami]
  }
}

############################################
# Outputs
############################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "security_group_id" {
  description = "ID of the security group allowing SSH/HTTP/HTTPS."
  value       = aws_security_group.allow_ssh_http_https.id
}

output "instance_ids" {
  description = "IDs of the launched EC2 instances."
  value       = aws_instance.app[*].id
}

output "instance_private_ips" {
  description = "Private IP addresses of the launched EC2 instances."
  value       = aws_instance.app[*].private_ip
}

output "amazon_linux_2_ami_id" {
  description = "ID of the Amazon Linux 2 AMI used by default."
  value       = data.aws_ami.amazon_linux_2.id
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "The AWS region to deploy resources in"
  type        = string
  default     = "us-east-1"
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM Roles
