resource "aws_iam_role" "ecs_service_role" {
  name = "ecsServiceRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "ecs_exec_task_role" {
  name = "ecsExecTaskRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "ecs_task_role" {
  name = "ecsTaskRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "ecs-tasks.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "ecs_autoscale_role" {
  name = "ecs_autoscale_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "ecs_codedeploy_role" {
  name = "ecs_codedeploy_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# Inline Policies
# ---------------------------------------------------------------------------------------------------------------------

# Policy attached to ecsServiceRole
resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name = "ecsTaskRolePolicy"
  role = aws_iam_role.ecs_service_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:*",
          "ec2:*",
          "ssm:*",
          "secretsmanager:*",
          "kms:*",
          "codedeploy:*",
          "sns:*",
          "cloudwatch:*",
          "logs:*",
          "lambda:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Policies attached to ecsExecTaskRole
resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name = "ecsExecRolePolicy"
  role = aws_iam_role.ecs_exec_task_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:*",
          "ecs:DescribeServices",
          "logs:*",
          "secretsmanager:*",
          "kms:*",
          "ssm:*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name = "ecsExecution_additional"
  role = aws_iam_role.ecs_exec_task_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:ListServices",
          "ecs:DescribeServices",
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject",
          "s3:GetBucketLocation"
        ]
        Resource = "*"
      }
    ]
  })
}

# Policy attached to ecsTaskRole
resource "aws_iam_role_policy" "ecs_task_role_additional" {
  name = "ecsTaskRole_additional"
  role = aws_iam_role.ecs_task_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:ListServices",
          "ecs:DescribeServices",
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject",
          "s3:GetBucketLocation"
        ]
        Resource = "*"
      }
    ]
  })
}

# Policy attached to ecs_autoscale_role
resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name = "ecs_autoscale_role_policy"
  role = aws_iam_role.ecs_autoscale_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:UpdateService",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DeleteAlarms",
          "cloudwatch:EnableAlarmActions",
          "cloudwatch:DisableAlarmActions",
          "cloudwatch:ListMetrics",
          "cloudwatch:GetMetricStatistics"
        ]
        Resource = "*"
      }
    ]
  })
}

# Policies attached to ecs_codedeploy_role
resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name = "ecs_codedeploy_role_policy"
  role = aws_iam_role.ecs_codedeploy_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecs:*",
          "elasticloadbalancing:*",
          "lambda:*",
          "cloudwatch:*",
          "sns:*",
          "s3:*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name = "ecs_codedeploy_role_policy_task"
  role = aws_iam_role.ecs_codedeploy_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.ecs_task_role.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name = "ecs_codedeploy_role_policy_task_exec"
  role = aws_iam_role.ecs_codedeploy_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.ecs_exec_task_role.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# Managed Policy Attachment
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "ecs_codedeploy_role_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeDeployRole"
}

# ---------------------------------------------------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------------------------------------------------

output "ecs_service_role_arn" {
  value = aws_iam_role.ecs_service_role.arn
}

output "ecs_exec_task_role_arn" {
  value = aws_iam_role.ecs_exec_task_role.arn
}

output "ecs_task_role_arn" {
  value = aws_iam_role.ecs_task_role.arn
}

output "ecs_autoscale_role_arn" {
  value = aws_iam_role.ecs_autoscale_role.arn
}

output "ecs_codedeploy_role_arn" {
  value = aws_iam_role.ecs_codedeploy_role.arn
}

variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

provider "aws" {
  region = var.region
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------
# External VPC
# ------------------------------
resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "External GW"
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name = "External Route Table"
  }
}

resource "aws_route" "external_internet" {
  route_table_id         = aws_route_table.external.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.external.id
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_subnet" "external_subnet0" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "Subnet0-1a"
  }
}

resource "aws_subnet" "external_subnet1" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "Subnet1-1b"
  }
}

resource "aws_subnet" "external_subnet2" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name = "Subnet2-1c"
  }
}

resource "aws_subnet" "external_subnet3" {
  vpc_id            = aws_vpc.external.id
  cidr_block        = "10.41.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[3]

  tags = {
    Name = "Subnet3-1d"
  }
}

resource "aws_route_table_association" "external_subnet0" {
  subnet_id      = aws_subnet.external_subnet0.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet1" {
  subnet_id      = aws_subnet.external_subnet1.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet2" {
  subnet_id      = aws_subnet.external_subnet2.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external_subnet3" {
  subnet_id      = aws_subnet.external_subnet3.id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "External Default NACL"
  }
}

# ------------------------------
# Internal VPC
# ------------------------------
resource "aws_vpc" "internal" {
  cidr_block           = "10.40.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = false

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

resource "aws_default_security_group" "internal" {
