  }

  egress {
    protocol   = "1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "Internal Default NACL"
  }
}

# n8n on ECS Fargate with EFS and Internal ALB

This Terraform template provisions a self-contained, serverless n8n deployment on AWS:

- **Networking**: A dedicated VPC (`10.0.0.0/16`) spanning the first three AZs with three private subnets (`10.0.0.0/24`, `10.0.1.0/24`, `10.0.2.0/24`) and three public subnets (`10.0.4.0/24`, `10.0.5.0/24`, `10.0.6.0/24`), an Internet Gateway with a public route table, and no NAT/VPN gateways.
- **Load balancing**: An internal ALB in the public subnets with invalid header dropping, HTTP→HTTPS redirect on port 80, and an HTTPS listener on port 443 using `ELBSecurityPolicy-TLS13-1-2-2021-06`. The certificate comes from `certificate_arn` when supplied, otherwise a self-signed cert is generated in-stack and imported into ACM.
- **Storage**: An encrypted EFS file system with mount targets in the private subnets (NFS 2049 restricted to the VPC CIDR) and an access point rooted at `/n8n` with owner UID/GID 1000 and `777` permissions.
- **Compute**: An ECS cluster (container insights disabled) with a Fargate capacity provider strategy (base 1 / weight 100), a 256 CPU / 512 MB task definition mounting EFS with transit encryption and IAM authorization at `/home/node/.n8n`, and a service in the public subnets with public IPs, secured so only the ALB can reach port 5678.
- **IAM & Logging**: Task and execution roles assumable by `ecs-tasks.amazonaws.com`, each with inline policies for CloudWatch Logs (the task role also gets EFS client permissions to make IAM authorization work), plus a `${prefix}-logs` log group with 1-day retention.

```iac_template
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

############################################
# Variables
############################################

variable "resource_prefix" {
  description = "Prefix applied to all resource names"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN to use for the HTTPS listener"
  type        = string
  default     = null
}

variable "url" {
  description = "Optional public URL override used for WEBHOOK_URL"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Number of n8n tasks to run"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "n8n container image"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider (FARGATE or FARGATE_SPOT)"
  type        = string
  default     = "FARGATE_SPOT"
}

############################################
# Data sources
############################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

############################################
# Locals
############################################

locals {
  azs             = slice(data.aws_availability_zones.available.names, 0, 3)
  private_subnets = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnets  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  vpc_cidr       = "10.0.0.0/16"
  container_name = "${var.resource_prefix}-app"
  container_port = 5678

  certificate_arn = coalesce(var.certificate_arn, one(aws_acm_certificate.self_signed[*].arn))
  webhook_url     = var.url != null ? var.url : "https://${aws_lb.main.dns_name}"
}

############################################
# VPC & Networking
############################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.resource_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.resource_prefix}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.resource_prefix}-private-${count.index}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.resource_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

############################################
# Security Groups
############################################

resource "aws_security_group" "alb" {
  name        = "${var.resource_prefix}-alb-sg"
  description = "Allow inbound HTTP/HTTPS to the n8n load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.resource_prefix}-alb-sg"
  }
}

resource "aws_security_group" "ecs" {
  name        = "${var.resource_prefix}-ecs-sg"
  description = "Allow n8n traffic only from the load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n container port from ALB"
    from_port       = local.container_port
    to_port         = local.container_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.resource_prefix}-ecs-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.resource_prefix}-efs-sg"
  description = "Allow NFS traffic to the n8n EFS file system"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from the VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${var.resource_prefix}-efs-sg"
  }
}

############################################
# Self-signed certificate (used when certificate_arn is not supplied)
############################################

resource "tls_private_key" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key_pem = tls_private_key.self_signed[0].private_key_pem

  subject {
    common_name  = "${var.resource_prefix}.internal"
    organization = "n8n"
  }

  validity_period_hours = 87600

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count = var.certificate_arn == null ? 1 : 0

  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name = "${var.resource_prefix}-self-signed-cert"
  }
}

############################################
# Application Load Balancer
############################################

resource "aws_lb" "main" {
  name                       = "${var.resource_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "${var.resource_prefix}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name                 = "${var.resource_prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "ip"
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/healthz"
    protocol            = "HTTP"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = {
    Name = "${var.resource_prefix}-tg"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name = "${var.resource_prefix}-https-listener"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = {
    Name = "${var.resource_prefix}-http-listener"
  }
}

############################################
# EFS Storage
############################################

resource "aws_efs_file_system" "main" {
  creation_token = "${var.resource_prefix}-efs"
  encrypted      = true

  tags = {
    Name = "${var.resource_prefix}-efs"
  }
}

resource "aws_efs_mount_target" "main" {
  count = 3

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "main" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = {
    Name = "${var.resource_prefix}-efs-ap"
  }
}

############################################
# CloudWatch Logs
############################################

resource "aws_cloudwatch_log_group" "main" {
  name              = "${var.resource_prefix}-logs"
  retention_in_days = 1

  tags = {
    Name = "${var.resource_prefix}-logs"
  }
}

############################################
# IAM
############################################

resource "aws_iam_role" "task" {
  name = "${var.resource_prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.resource_prefix}-task-role"
  }
}

resource "aws_iam_role_policy" "task" {
  name = "${var.resource_prefix}-task-policy"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.main.arn,
          "${aws_cloudwatch_log_group.main.arn}:*",
        ]
      },
      {
        Sid    = "EfsClientAccess"
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess",
          "elasticfilesystem:DescribeMountTargets",
        ]
        Resource = aws_efs_file_system.main.arn
      }
    ]
  })
}

resource "aws_iam_role" "execution" {
  name = "${var.resource_prefix}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.resource_prefix}-execution-role"
  }
}

resource "aws_iam_role_policy" "execution" {
  name = "${var.resource_prefix}-execution-policy"
  role = aws_iam_role.execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.main.arn,
          "${aws_cloudwatch_log_group.main.arn}:*",
        ]
      }
    ]
  })
}

############################################
# ECS Cluster
############################################

resource "aws_ecs_cluster" "main" {
  name = "${var.resource_prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${var.resource_prefix}-cluster"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

############################################
# ECS Task Definition
############################################

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.resource_prefix}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = "n8n-data"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.main.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = local.container_name
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = local.container_port
          hostPort      = local.container_port
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        },
        {
          name  = "N8N_PORT"
          value = tostring(local.container_port)
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.main.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = var.resource_prefix
        }
      }
    }
  ])

  tags = {
    Name = "${var.resource_prefix}-task"
  }
}

############################################
# ECS Service
############################################

resource "aws_ecs_service" "main" {
  name            = "${var.resource_prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = local.container_name
    container_port   = local.container_port
  }

  depends_on = [
    aws_lb_listener.https,
    aws_efs_mount_target.main,
    aws_ecs_cluster_capacity_providers.main,
  ]

  lifecycle {
    ignore_changes = [desired_count]
  }

  tags = {
    Name = "${var.resource_prefix}-service"
  }
}

############################################
# Outputs
############################################

output "vpc_id" {
  description = "VPC identifier"
  value       = aws_vpc.main.id
}

output "load_balancer_dns_name" {
  description = "DNS name of the internal load balancer"
  value       = aws_lb.main.dns_name
}

output "webhook_url" {
  description = "Effective WEBHOOK_URL used by the n8n container"
  value       = local.webhook_url
}

output "certificate_arn" {
  description = "ACM certificate ARN used by the HTTPS listener"
  value       = local.certificate_arn
}

output "efs_file_system_id" {
  description = "EFS file system identifier"
  value       = aws_efs_file_system.main.id
}

output "ecs_cluster_name" {
  description = "ECS cluster name"
  value       = aws_ecs_cluster.main.name
}

output "ecs_service_name" {
  description = "ECS service name"
  value       = aws_ecs_service.main.name
}

output "log_group_name" {
  description = "CloudWatch log group for the n8n container"
  value       = aws_cloudwatch_log_group.main.name
}
```

###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Input Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the isolated development network is built."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block assigned to the VPC (also used to scope security group rules)."
  type        = string
  default     = "10.32.0.0/20"
}

###############################################################################
# Data Sources & Locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  project_name = "lambda-rds-dev"

  primary_az   = data.aws_availability_zones.available.names[0]
  secondary_az = data.aws_availability_zones.available.names[1]

  db_subnet_1_cidr    = "10.32.0.0/28"
  db_subnet_2_cidr    = "10.32.0.16/28"
  lambda_subnet_cidr  = "10.32.1.0/24"
  bastion_subnet_cidr = "10.32.15.0/24"

  common_tags = {
    Project     = "lambda-rds-dev"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC, Default Security Group & Default Network ACL
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "lambda-rds-dev"
  })
}

# Default security group of the VPC, managed with no ingress and no egress rules.
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "lambda-rds-dev-default-sg"
  })
}

# Default network ACL of the VPC: allow all ingress and egress traffic.
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "lambda-rds-dev-default-nacl"
  })
}

###############################################################################
# Subnets (database, application/lambda and bastion host tiers)
###############################################################################

# Database tier - subnet 1 (primary AZ)
resource "aws_subnet" "db_subnet_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.db_subnet_1_cidr
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "lambda-rds-db-subnet-1"
    Tier = "database"
  })
}

# Database tier - subnet 2 (secondary AZ)
resource "aws_subnet" "db_subnet_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.db_subnet_2_cidr
  availability_zone       = local.secondary_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "lambda-rds-db-subnet-2"
    Tier = "database"
  })
}

# Application (Lambda) tier (primary AZ)
resource "aws_subnet" "lambda_subnet" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.lambda_subnet_cidr
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "lambda-rds-dev-lambda-subnet"
    Tier = "application"
  })
}

# Bastion host tier (primary AZ)
resource "aws_subnet" "bastion_subnet" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.bastion_subnet_cidr
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "lambda-rds-bastion-host-subnet"
    Tier = "bastion"
  })
}

###############################################################################
# Internet Gateway, Public Route Table & Bastion Subnet Association
###############################################################################

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "lambda-rds-dev-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "lambda-rds-public-subnet"
  })
}

resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion_subnet.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security Groups
###############################################################################

# PostgreSQL database security group
resource "aws_security_group" "postgres_db" {
  name        = "lambda-rds-dev-postgres-db"
  description = "Security group for the RDS PostgreSQL database tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "lambda-rds-dev-postgres-db"
  })
}

# Lambda functions security group
resource "aws_security_group" "lambda_functions" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Security group for the Lambda application tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "lambda-rds-dev-lambda-functions"
  })
}

# Bastion host security group
resource "aws_security_group" "bastion_host" {
  name        = "lambda-rds-dev-bastion-host"
  description = "Security group for the bastion host tier"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "lambda-rds-dev-bastion-host"
  })
}

###############################################################################
# Security Group Rules
# (Standalone rules avoid a dependency cycle between the bastion and database
#  security groups, which reference each other.)
###############################################################################

# --- PostgreSQL DB SG: ingress on 5432 from bastion and lambda SG's ---
resource "aws_security_group_rule" "db_ingress_from_bastion" {
  type                     = "ingress"
  description              = "PostgreSQL 5432 from bastion host security group"
  security_group_id        = aws_security_group.postgres_db.id
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.bastion_host.id
}

resource "aws_security_group_rule" "db_ingress_from_lambda" {
  type                     = "ingress"
  description              = "PostgreSQL 5432 from lambda functions security group"
  security_group_id        = aws_security_group.postgres_db.id
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.lambda_functions.id
}

# --- PostgreSQL DB SG: egress strictly to the VPC CIDR ---
resource "aws_security_group_rule" "db_egress_to_vpc" {
  type              = "egress"
  description       = "Egress restricted to the VPC CIDR block"
  security_group_id = aws_security_group.postgres_db.id
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.vpc_cidr_block]
}

# --- Lambda functions SG: egress strictly to the VPC CIDR ---
resource "aws_security_group_rule" "lambda_egress_to_vpc" {
  type              = "egress"
  description       = "Egress restricted to the VPC CIDR block"
  security_group_id = aws_security_group.lambda_functions.id
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.vpc_cidr_block]
}

# --- Bastion host SG: inbound SSH only from inside the VPC CIDR ---
resource "aws_security_group_rule" "bastion_ingress_ssh" {
  type              = "ingress"
  description       = "SSH from within the VPC CIDR block"
  security_group_id = aws_security_group.bastion_host.id
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr_block]
}

# --- Bastion host SG: egress restricted exclusively to the PostgreSQL DB SG ---
resource "aws_security_group_rule" "bastion_egress_to_db" {
  type                     = "egress"
  description              = "Egress restricted to the PostgreSQL database security group"
  security_group_id        = aws_security_group.bastion_host.id
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.postgres_db.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the lambda-rds-dev VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the lambda-rds-dev VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the subnets."
  value = {
    primary   = local.primary_az
    secondary = local.secondary_az
  }
}

output "subnet_ids" {
  description = "IDs of the provisioned subnets."
  value = {
    db_subnet_1     = aws_subnet.db_subnet_1.id
    db_subnet_2     = aws_subnet.db_subnet_2.id
    lambda_subnet   = aws_subnet.lambda_subnet.id
    bastion_subnet  = aws_subnet.bastion_subnet.id
  }
}

output "security_group_ids" {
  description = "IDs of the provisioned security groups."
  value = {
    postgres_db      = aws_security_group.postgres_db.id
    lambda_functions = aws_security_group.lambda_functions.id
    bastion_host     = aws_security_group.bastion_host.id
    default          = aws_default_security_group.default.id
  }
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.igw.id
}

output "public_route_table_id" {
  description = "ID of the public route table used by the bastion host subnet."
  value       = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which the Quasar data stack networking baseline is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the Quasar VPC."
  type        = string
  default     = "10.255.0.0/16"
}

variable "rds_subnet_cidrs" {
  description = "CIDR blocks for the two multi-AZ RDS subnets (AZ-a and AZ-e slots)."
  type        = list(string)
  default     = ["10.255.100.0/24", "10.255.101.0/24"]
}

variable "admin_cidr" {
  description = "Placeholder administrative CIDR permitted to SSH into the bastion host."
  type        = string
  default     = "203.0.113.0/24"
}

locals {
  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

###############################################################################
# Availability zones
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "quasar" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

###############################################################################
# Multi-AZ RDS subnets
###############################################################################

resource "aws_subnet" "rds" {
  count = 2

  vpc_id            = aws_vpc.quasar.id
  cidr_block        = var.rds_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = count.index == 0 ? "Quasar RDS - 1A" : "Quasar RDS - 1E"
  })
}

resource "aws_db_subnet_group" "quasar" {
  name        = "quasar-rds-subnet-group"
  description = "Multi-AZ subnet group for Quasar data stack databases"
  subnet_ids  = aws_subnet.rds[*].id

  tags = merge(local.common_tags, {
    Name = "Quasar RDS Subnet Group"
  })
}

###############################################################################
# Security Groups
# All egress is restricted to the VPC CIDR block only.
###############################################################################

# --- Bastion ----------------------------------------------------------------
resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host: SSH access from the administrative CIDR"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "SSH from administrative range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

# --- HA Proxy ---------------------------------------------------------------
resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA proxy: public HTTP/HTTPS and SSH from the bastion"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

# --- Jenkins ----------------------------------------------------------------
resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI/CD automation: SSH from bastion and UI from HA proxy"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins web UI from the HA proxy security group"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

# --- ETL --------------------------------------------------------------------
resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes: SSH from bastion and Jenkins"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from the bastion security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from the Jenkins security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

# --- PostgreSQL -------------------------------------------------------------
resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL database tier: 5432 from anywhere and from ETL nodes"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "PostgreSQL from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL from the ETL security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the Quasar VPC."
  value       = aws_vpc.quasar.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the Quasar VPC."
  value       = aws_vpc.quasar.cidr_block
}

output "rds_subnet_ids" {
  description = "IDs of the two multi-AZ RDS subnets."
  value       = aws_subnet.rds[*].id
}

output "rds_subnet_azs" {
  description = "Availability zones of the two multi-AZ RDS subnets."
  value       = aws_subnet.rds[*].availability_zone
}

output "rds_subnet_group_name" {
  description = "Name of the RDS subnet group used by Multi-AZ databases."
  value       = aws_db_subnet_group.quasar.name
}

output "security_group_ids" {
  description = "Map of Quasar security group names to their IDs."
  value = {
    bastion    = aws_security_group.bastion.id
    ha_proxy   = aws_security_group.ha_proxy.id
    jenkins    = aws_security_group.jenkins.id
    etl        = aws_security_group.etl.id
    postgresql = aws_security_group.postgresql.id
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "AWS region in which the SQS queues will be created."
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Controls whether the SQS resources should be created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the queue. Any trailing \".fifo\" suffix is stripped automatically and re-applied by the module when fifo_queue is true. If left null a unique name is generated using name_prefix."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether the queue name is used as a prefix (true) or as the full queue name (false)."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to assign to the primary queue."
  type        = map(string)
  default     = {}
}

################################################################################
# Primary queue arguments
################################################################################

variable "fifo_queue" {
  description = "Boolean designating a FIFO queue. Defaults to false (standard queue)."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication. Only applies to FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values are \"messageGroup\" and \"queue\". Only applies to FIFO queues."
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values are \"perQueue\" and \"perMessageGroupId\". Only applies to FIFO queues."
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue is delayed."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling)."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue, in seconds."
  type        = number
  default     = 30
}

################################################################################
# Encryption
################################################################################

variable "sqs_managed_sse_enabled" {
  description = "Boolean, enabling server-side encryption (SSE) using Amazon SQS-managed encryption keys. Ignored when kms_master_key_id is set."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK. When set, SQS-managed SSE is disabled."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling AWS KMS again. Only used when kms_master_key_id is set."
  type        = number
  default     = null
}

################################################################################
# Queue policies
################################################################################

variable "create_queue_policy" {
  description = "Controls whether the primary queue policy should be created."
  type        = bool
  default     = false
}

variable "source_queue_policy_documents" {
  description = "List of IAM policy documents (JSON) that are merged together into the exported queue policy."
  type        = list(string)
  default     = []
}

variable "override_queue_policy_documents" {
  description = "List of IAM policy documents (JSON) that are merged together into the exported queue policy, taking precedence over source documents."
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "A map of IAM policy statement definitions for the primary queue. Each statement supports sid, actions, not_actions, effect, resources, not_resources, principals, not_principals and condition blocks."
  type        = any
  default     = {}
}

################################################################################
# Dead-letter queue
################################################################################

variable "create_dlq" {
  description = "Controls whether a dead-letter queue (DLQ) should be created and attached to the primary queue via a redrive policy."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Optional explicit name for the dead-letter queue. Defaults to \"<queue name><dlq_name_suffix>\"."
  type        = string
  default     = null
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the primary queue name to derive the default dead-letter queue name."
  type        = string
  default     = "-dlq"
}

variable "max_receive_count" {
  description = "The number of times a message is delivered to the source queue before being moved to the dead-letter queue."
  type        = number
  default     = 5
}

variable "redrive_policy" {
  description = "JSON policy to set up the Dead Letter Queue (custom, used when create_dlq is false)."
  type        = string
  default     = null
}

variable "create_dlq_redrive_allow_policy" {
  description = "Controls whether a redrive allow policy restricting redrive permission to the source queue should be attached to the DLQ."
  type        = bool
  default     = true
}

variable "dlq_tags" {
  description = "A map of additional tags to assign to the dead-letter queue."
  type        = map(string)
  default     = {}
}

# ---- DLQ overrides (null means "inherit from the primary queue") -------------

variable "dlq_fifo_queue" {
  description = "Overrides the FIFO setting of the dead-letter queue. Defaults to the primary queue's fifo_queue value."
  type        = bool
  default     = null
}

variable "dlq_content_based_deduplication" {
  description = "Overrides content_based_deduplication for the DLQ."
  type        = bool
  default     = null
}

variable "dlq_deduplication_scope" {
  description = "Overrides deduplication_scope for the DLQ."
  type        = string
  default     = null
}

variable "dlq_fifo_throughput_limit" {
  description = "Overrides fifo_throughput_limit for the DLQ."
  type        = string
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Overrides delay_seconds for the DLQ."
  type        = number
  default     = null
}

variable "dlq_max_message_size" {
  description = "Overrides max_message_size for the DLQ."
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Overrides message_retention_seconds for the DLQ."
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Overrides receive_wait_time_seconds for the DLQ."
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Overrides visibility_timeout_seconds for the DLQ."
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Overrides sqs_managed_sse_enabled for the DLQ."
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "Overrides kms_master_key_id for the DLQ."
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "Overrides kms_data_key_reuse_period_seconds for the DLQ."
  type        = number
  default     = null
}

variable "create_dlq_queue_policy" {
  description = "Controls whether the dead-letter queue policy should be created."
  type        = bool
  default     = false
}

variable "source_dlq_queue_policy_documents" {
  description = "List of IAM policy documents (JSON) that are merged together into the exported DLQ policy."
  type        = list(string)
  default     = []
}

variable "override_dlq_queue_policy_documents" {
  description = "List of IAM policy documents (JSON) that are merged together into the exported DLQ policy, taking precedence over source documents."
  type        = list(string)
  default     = []
}

variable "dlq_queue_policy_statements" {
  description = "A map of IAM policy statement definitions for the dead-letter queue."
  type        = any
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  create = var.create

  # ---------------------------------------------------------------------------
  # Naming
  # ---------------------------------------------------------------------------
  raw_name  = var.name != null ? trimspace(var.name) : ""
  base_name = replace(local.raw_name, "/\\.fifo$/", "")

  fifo_suffix = var.fifo_queue ? ".fifo" : ""

  # Fall back to a generated name prefix when no (usable) name was supplied.
  use_name_prefix = var.use_name_prefix || local.base_name == ""
  name_root       = local.base_name != "" ? local.base_name : "sqs"

  queue_name        = local.use_name_prefix ? null : "${local.name_root}${local.fifo_suffix}"
  queue_name_prefix = local.use_name_prefix ? local.name_root : null

  # ---------------------------------------------------------------------------
  # Dead-letter queue inheritance (explicit DLQ value wins, otherwise inherit)
  # ---------------------------------------------------------------------------
  dlq_fifo_queue                  = var.dlq_fifo_queue != null ? var.dlq_fifo_queue : var.fifo_queue
  dlq_content_based_deduplication = var.dlq_content_based_deduplication != null ? var.dlq_content_based_deduplication : var.content_based_deduplication
  dlq_deduplication_scope         = var.dlq_deduplication_scope != null ? var.dlq_deduplication_scope : var.deduplication_scope
  dlq_fifo_throughput_limit       = var.dlq_fifo_throughput_limit != null ? var.dlq_fifo_throughput_limit : var.fifo_throughput_limit
  dlq_delay_seconds               = var.dlq_delay_seconds != null ? var.dlq_delay_seconds : var.delay_seconds
  dlq_max_message_size            = var.dlq_max_message_size != null ? var.dlq_max_message_size : var.max_message_size
  dlq_message_retention_seconds   = var.dlq_message_retention_seconds != null ? var.dlq_message_retention_seconds : var.message_retention_seconds
  dlq_receive_wait_time_seconds   = var.dlq_receive_wait_time_seconds != null ? var.dlq_receive_wait_time_seconds : var.receive_wait_time_seconds
  dlq_visibility_timeout_seconds  = var.dlq_visibility_timeout_seconds != null ? var.dlq_visibility_timeout_seconds : var.visibility_timeout_seconds
  dlq_kms_master_key_id           = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : var.kms_master_key_id
  dlq_kms_data_key_reuse_period   = var.dlq_kms_data_key_reuse_period_seconds != null ? var.dlq_kms_data_key_reuse_period_seconds : var.kms_data_key_reuse_period_seconds
  dlq_sqs_managed_sse_enabled     = var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : var.sqs_managed_sse_enabled

  # ---------------------------------------------------------------------------
  # Dead-letter queue naming
  # ---------------------------------------------------------------------------
  create_dlq = var.create && var.create_dlq

  dlq_raw_name  = var.dlq_name != null ? trimspace(var.dlq_name) : ""
  dlq_base_name = local.dlq_raw_name != "" ? replace(local.dlq_raw_name, "/\\.fifo$/", "") : "${local.name_root}${var.dlq_name_suffix}"

  dlq_fifo_suffix = local.dlq_fifo_queue ? ".fifo" : ""

  dead_letter_queue_name        = local.use_name_prefix ? null : "${local.dlq_base_name}${local.dlq_fifo_suffix}"
  dead_letter_queue_name_prefix = local.use_name_prefix ? local.dlq_base_name : null
}

################################################################################
# Primary queue
################################################################################

resource "aws_sqs_queue" "this" {
  count = local.create ? 1 : 0

  name        = local.queue_name
  name_prefix = local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  # SQS-managed SSE is the default; a customer managed KMS key takes precedence.
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = var.kms_master_key_id != null ? null : var.sqs_managed_sse_enabled

  # Automatically attach a redrive policy targeting the provisioned DLQ.
  redrive_policy = local.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : var.redrive_policy

  tags = var.tags
}

################################################################################
# Dead-letter queue
################################################################################

resource "aws_sqs_queue" "dlq" {
  count = local.create_dlq ? 1 : 0

  name        = local.dead_letter_queue_name
  name_prefix = local.dead_letter_queue_name_prefix

  fifo_queue                  = local.dlq_fifo_queue
  content_based_deduplication = local.dlq_fifo_queue ? local.dlq_content_based_deduplication : null
  deduplication_scope         = local.dlq_fifo_queue ? local.dlq_deduplication_scope : null
  fifo_throughput_limit       = local.dlq_fifo_queue ? local.dlq_fifo_throughput_limit : null

  delay_seconds              = local.dlq_delay_seconds
  max_message_size           = local.dlq_max_message_size
  message_retention_seconds  = local.dlq_message_retention_seconds
  receive_wait_time_seconds  = local.dlq_receive_wait_time_seconds
  visibility_timeout_seconds = local.dlq_visibility_timeout_seconds

  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_master_key_id != null ? local.dlq_kms_data_key_reuse_period : null
  sqs_managed_sse_enabled           = local.dlq_kms_master_key_id != null ? null : local.dlq_sqs_managed_sse_enabled

  tags = merge(var.tags, var.dlq_tags)
}

resource "aws_sqs_queue_redrive_allow_policy" "this" {
  count = local.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  })
}

################################################################################
# Primary queue policy
################################################################################

data "aws_iam_policy_document" "this" {
  count = local.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_queue_policy_documents
  override_policy_documents = var.override_queue_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null) != null ? statement.value.resources : (try(statement.value.not_resources, null) == null ? [aws_sqs_queue.this[0].arn] : null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.condition, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = local.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

################################################################################
# Dead-letter queue policy
################################################################################

data "aws_iam_policy_document" "dlq" {
  count = local.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents   = var.source_dlq_queue_policy_documents
  override_policy_documents = var.override_dlq_queue_policy_documents

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null) != null ? statement.value.resources : (try(statement.value.not_resources, null) == null ? [aws_sqs_queue.dlq[0].arn] : null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.condition, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count = local.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = data.aws_iam_policy_document.dlq[0].json
}

################################################################################
# Outputs
################################################################################

output "queue_arn" {
  description = "The ARN of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "The URL of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The resolved name of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "queue_id" {
  description = "The ID (URL) of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_policy" {
  description = "The JSON policy of the primary SQS queue, if created."
  value       = try(data.aws_iam_policy_document.this[0].json, null)
}

output "dead_letter_queue_arn" {
  description = "The ARN of the dead-letter queue, if created."
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_url" {
  description = "The URL of the dead-letter queue, if created."
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dead_letter_queue_name" {
  description = "The resolved name of the dead-letter queue, if created."
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

output "dead_letter_queue_policy" {
  description = "The JSON policy of the dead-letter queue, if created."
  value       = try(data.aws_iam_policy_document.dlq[0].json, null)
}

output "dead_letter_queue_redrive_allow_policy" {
  description = "The JSON redrive allow policy attached to the dead-letter queue, if created."
  value       = try(aws_sqs_queue_redrive_allow_policy.this[0].redrive_allow_policy, null)
}

output "queue_redrive_policy" {
  description = "The JSON redrive policy attached to the primary queue."
  value       = try(aws_sqs_queue.this[0].redrive_policy, null)
}

###############################################################################
# Terraform + Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0.0"
    }
    uuid = {
      source  = "hashicorp/uuid"
      version = ">= 3.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region into which all resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Global creation control. When false, no resources are created."
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the Lambda function targeted for blue/green deployment."
  type        = string
  default     = "my-lambda-function"
}

variable "alias_name" {
  description = "Name of the Lambda alias that receives blue/green traffic."
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Currently deployed Lambda version (blue)."
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Target Lambda version to deploy (green)."
  type        = string
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional ARN/name of a Lambda hook executed before traffic is shifted."
  type        = string
  default     = null
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional ARN/name of a Lambda hook executed after traffic is shifted."
  type        = string
  default     = null
}

# --- Application -------------------------------------------------------------

variable "app_name" {
  description = "Name of the CodeDeploy application to create."
  type        = string
  default     = ""
}

variable "create_app" {
  description = "Whether to create the CodeDeploy application."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to reuse an existing CodeDeploy application instead of creating one."
  type        = bool
  default     = false
}

variable "existing_app_name" {
  description = "Name of the existing CodeDeploy application to use when use_existing_app is true."
  type        = string
  default     = ""
}

# --- Deployment Group --------------------------------------------------------

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group to create."
  type        = string
  default     = ""
}

variable "create_deployment_group" {
  description = "Whether to create the CodeDeploy deployment group."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to reuse an existing CodeDeploy deployment group instead of creating one."
  type        = bool
  default     = false
}

variable "existing_deployment_group_name" {
  description = "Name of the existing deployment group to use when use_existing_deployment_group is true."
  type        = string
  default     = ""
}

variable "deployment_config_name" {
  description = "CodeDeploy deployment configuration name used by the deployment group."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "auto_rollback_enabled" {
  description = "Enable automatic rollbacks on the deployment group."
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "Rollback events for the automatic rollback configuration."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "alarm_configuration" {
  description = "Optional CloudWatch alarm monitoring for the deployment group."
  type = object({
    enabled = bool
    alarms  = list(string)
  })
  default = {
    enabled = false
    alarms  = []
  }
}

variable "trigger_configurations" {
  description = "Optional notification trigger configurations for the deployment group."
  type = list(object({
    trigger_events     = list(string)
    trigger_name       = string
    trigger_target_arn = string
  }))
  default = []
}

# --- IAM Role ----------------------------------------------------------------

variable "create_codedeploy_role" {
  description = "Whether to create the IAM role used by CodeDeploy."
  type        = bool
  default     = true
}

variable "codedeploy_role_name" {
  description = "Name of the CodeDeploy IAM role (falls back to <app>-codedeploy-role)."
  type        = string
  default     = ""
}

variable "existing_codedeploy_role_arn" {
  description = "ARN of an existing CodeDeploy role to use when create_codedeploy_role is false."
  type        = string
  default     = ""
}

variable "codedeploy_service_principals" {
  description = "Service principals allowed to assume the CodeDeploy role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Attach an inline policy granting lambda:InvokeFunction for the configured hooks."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Attach an inline policy granting sns:Publish for the configured trigger targets."
  type        = bool
  default     = false
}

# --- Deployment Execution ----------------------------------------------------

variable "create_deployment" {
  description = "Whether to generate the AppSpec/script and optionally execute a deployment."
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI executable used by the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between get-deployment status polls."
  type        = number
  default     = 5
}

variable "monitor_deployment" {
  description = "Whether the generated script should poll the deployment until it completes."
  type        = bool
  default     = true
}

variable "save_deploy_script" {
  description = "Whether to persist the generated deployment script locally."
  type        = bool
  default     = false
}

variable "deploy_script_path" {
  description = "Local path used when save_deploy_script is true."
  type        = string
  default     = "./codedeploy_lambda_deploy.sh"
}

variable "run_deployment" {
  description = "Whether to execute the generated deployment script via a null_resource."
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Force a re-deployment by rotating a uuid-based trigger."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags applied to taggable resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  # -- Master gating flags ----------------------------------------------------
  create_app              = var.create && var.create_app && !var.use_existing_app
  create_deployment_group = var.create && var.create_deployment_group && !var.use_existing_deployment_group
  create_codedeploy_role  = var.create && var.create_codedeploy_role
  create_deployment       = var.create && var.create_deployment

  # -- Resolved names ---------------------------------------------------------
  resolved_app_name = var.use_existing_app ? coalesce(var.existing_app_name, var.app_name, var.function_name) : coalesce(var.app_name, var.function_name)

  resolved_dg_name = var.use_existing_deployment_group ? coalesce(var.existing_deployment_group_name, var.deployment_group_name, "${local.resolved_app_name}-deployment-group") : coalesce(var.deployment_group_name, "${local.resolved_app_name}-deployment-group")

  resolved_role_name = coalesce(var.codedeploy_role_name, "${local.resolved_app_name}-codedeploy-role")

  codedeploy_role_arn = local.create_codedeploy_role ? try(aws_iam_role.codedeploy[0].arn, "") : var.existing_codedeploy_role_arn

  # -- Hook / trigger helpers -------------------------------------------------
  hook_arns = compact([
    var.before_allow_traffic_hook_arn,
    var.after_allow_traffic_hook_arn,
  ])

  trigger_arns = [for t in var.trigger_configurations : t.trigger_target_arn]

  # -- AppSpec -----------------------------------------------------------------
  app_spec = {
    version = "0.0"
    Resources = [
      {
        (var.function_name) = {
          Type = "AWS::Lambda::Function"
          Properties = {
            Name           = var.function_name
            Alias          = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      }
    ]
    Hooks = concat(
      (var.before_allow_traffic_hook_arn != null && var.before_allow_traffic_hook_arn != "") ? [{
        BeforeAllowTraffic = var.before_allow_traffic_hook_arn
      }] : [],
      (var.after_allow_traffic_hook_arn != null && var.after_allow_traffic_hook_arn != "") ? [{
        AfterAllowTraffic = var.after_allow_traffic_hook_arn
      }] : []
    )
  }

  app_spec_json = jsonencode(local.app_spec)

  revision_json = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.app_spec_json
    }
  })

  # -- Generated deployment script fragments ----------------------------------
  monitor_script = <<-EOT
    echo "==> Monitoring deployment $DEPLOYMENT_ID"
    STATUS=$($AWS_CLI deploy get-deployment --deployment-id "$DEPLOYMENT_ID" --query 'deploymentInfo.status' --output text)
    echo "==> Status: $STATUS"
    while [ "$STATUS" = "Created" ] || [ "$STATUS" = "Queued" ] || [ "$STATUS" = "InProgress" ] || [ "$STATUS" = "Ready" ]; do
      sleep "$SLEEP_TIMER"
      STATUS=$($AWS_CLI deploy get-deployment --deployment-id "$DEPLOYMENT_ID" --query 'deploymentInfo.status' --output text)
      echo "==> Status: $STATUS"
    done
    if [ "$STATUS" != "Succeeded" ]; then
      echo "ERROR: deployment finished with status: $STATUS"
      exit 1
    fi
    echo "==> Deployment succeeded"
  EOT

  deploy_script = <<-EOT
    #!/bin/bash
    set -euo pipefail

    AWS_CLI="${var.aws_cli_command}"
    APP_NAME="${local.resolved_app_name}"
    DEPLOYMENT_GROUP="${local.resolved_dg_name}"
    SLEEP_TIMER="${var.get_deployment_sleep_timer}"

    echo "==> Creating CodeDeploy deployment"
    echo "    Application      : $APP_NAME"
    echo "    Deployment Group : $DEPLOYMENT_GROUP"

    DEPLOYMENT_ID=$($AWS_CLI deploy create-deployment \
      --application-name "$APP_NAME" \
      --deployment-group-name "$DEPLOYMENT_GROUP" \
      --revision '${local.revision_json}' \
      --query 'deploymentId' \
      --output text)

    echo "==> Deployment ID: $DEPLOYMENT_ID"

    ${var.monitor_deployment ? local.monitor_script : "echo '==> Deployment monitoring disabled'"}
  EOT
}

###############################################################################
# IAM role + policies for CodeDeploy
###############################################################################

data "aws_iam_policy_document" "codedeploy_assume_role" {
  count = local.create_codedeploy_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  count = local.create_codedeploy_role ? 1 : 0

  name               = local.resolved_role_name
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role[0].json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count = local.create_codedeploy_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

data "aws_iam_policy_document" "codedeploy_hooks" {
  count = local.create_codedeploy_role && var.attach_hooks_policy ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = length(local.hook_arns) > 0 ? local.hook_arns : ["*"]
  }
}

resource "aws_iam_role_policy" "codedeploy_hooks" {
  count = local.create_codedeploy_role && var.attach_hooks_policy ? 1 : 0

  name   = "${local.resolved_role_name}-hooks"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.codedeploy_hooks[0].json
}

data "aws_iam_policy_document" "codedeploy_triggers" {
  count = local.create_codedeploy_role && var.attach_triggers_policy ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = length(local.trigger_arns) > 0 ? local.trigger_arns : ["*"]
  }
}

resource "aws_iam_role_policy" "codedeploy_triggers" {
  count = local.create_codedeploy_role && var.attach_triggers_policy ? 1 : 0

  name   = "${local.resolved_role_name}-triggers"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.codedeploy_triggers[0].json
}

###############################################################################
# CodeDeploy application
###############################################################################

resource "aws_codedeploy_app" "this" {
  count = local.create_app ? 1 : 0

  name             = local.resolved_app_name
  compute_platform = "Lambda"
  tags             = var.tags
}

###############################################################################
# CodeDeploy deployment group
###############################################################################

resource "aws_codedeploy_deployment_group" "this" {
  count = local.create_deployment_group ? 1 : 0

  app_name               = local.resolved_app_name
  deployment_group_name  = local.resolved_dg_name
  service_role_arn       = local.codedeploy_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = var.alarm_configuration.enabled ? [1] : []
    content {
      enabled = true
      alarms  = var.alarm_configuration.alarms
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_configurations
    content {
      trigger_events     = trigger_configuration.value.trigger_events
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
    }
  }

  tags = var.tags

  depends_on = [
    aws_iam_role_policy_attachment.codedeploy_lambda,
  ]
}

###############################################################################
# Deployment generation / execution
###############################################################################

resource "local_file" "deploy_script" {
  count = local.create_deployment && var.save_deploy_script ? 1 : 0

  filename        = var.deploy_script_path
  content         = local.deploy_script
  file_permission = "0755"
}

resource "uuid" "force_deploy" {
  count = local.create_deployment && var.run_deployment && var.force_deploy ? 1 : 0

  keepers = {
    function_name  = var.function_name
    alias_name     = var.alias_name
    target_version = var.target_version
    app_name       = local.resolved_app_name
    dg_name        = local.resolved_dg_name
  }
}

resource "null_resource" "run_deployment" {
  count = local.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    function_name   = var.function_name
    alias_name      = var.alias_name
    current_version = var.current_version
    target_version  = var.target_version
    app_name        = local.resolved_app_name
    dg_name         = local.resolved_dg_name
    force_deploy    = try(uuid.force_deploy[0].result, "")
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = local.deploy_script
  }

  depends_on = [
    aws_codedeploy_deployment_group.this,
    local_file.deploy_script,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "codedeploy_app_name" {
  description = "Name of the CodeDeploy application in use."
  value       = local.resolved_app_name
}

output "codedeploy_deployment_group_name" {
  description = "Name of the CodeDeploy deployment group in use."
  value       = local.resolved_dg_name
}

output "codedeploy_role_arn" {
  description = "ARN of the CodeDeploy IAM role (created or referenced)."
  value       = local.codedeploy_role_arn
}

output "app_spec_json" {
  description = "Rendered AppSpec JSON used by the generated deployment script."
  value       = local.app_spec_json
}

output "deploy_script" {
  description = "Generated deployment shell script."
  value       = local.deploy_script
}

output "force_deploy_uuid" {
  description = "UUID used to force a re-deployment when force_deploy is enabled."
  value       = try(uuid.force_deploy[0].result, null)
}

###############################################################################
# Terraform & provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the multi-tier VPC environment is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name_prefix" {
  description = "Prefix for the VPC name tag. A random integer 1-100 is appended to it."
  type        = string
  default     = "tf-project"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.16.0.0/16"
}

variable "max_subnet_count" {
  description = "Maximum number of subnets (and therefore availability zones) used per tier."
  type        = number
  default     = 3

  validation {
    condition     = var.max_subnet_count > 0 && floor(var.max_subnet_count) == var.max_subnet_count
    error_message = "max_subnet_count must be a positive whole number."
  }
}

variable "web_subnets" {
  description = "List of CIDR blocks for the public (web) tier."
  type        = list(string)
  default     = ["10.16.1.0/24", "10.16.2.0/24", "10.16.3.0/24"]
}

variable "app_subnets" {
  description = "List of CIDR blocks for the private application tier."
  type        = list(string)
  default     = ["10.16.10.0/24", "10.16.11.0/24", "10.16.12.0/24"]
}

variable "database_subnets" {
  description = "List of CIDR blocks for the private database tier."
  type        = list(string)
  default     = ["10.16.20.0/24", "10.16.21.0/24", "10.16.22.0/24"]
}

variable "reserved_subnets" {
  description = "List of CIDR blocks for the private reserved tier."
  type        = list(string)
  default     = ["10.16.30.0/24", "10.16.31.0/24", "10.16.32.0/24"]
}

variable "interface_vpc_endpoints" {
  description = <<-EOT
    Map of interface VPC endpoints to create. Key = friendly name used in tags.
    Each entry declares the full service name (e.g. "com.amazonaws.us-east-1.ssm"),
    whether private DNS is enabled, and which subnet tier hosts the endpoint ENIs.
  EOT
  type = map(object({
    service_name        = string
    private_dns_enabled = optional(bool, true)
    subnet_tier         = optional(string, "app")
  }))
  default = {}

  validation {
    condition = alltrue([
      for cfg in values(var.interface_vpc_endpoints) :
      contains(["web", "app", "database", "reserved"], cfg.subnet_tier)
    ])
    error_message = "subnet_tier must be one of: web, app, database, reserved."
  }
}

variable "gateway_vpc_endpoint_service_name" {
  description = "Service name for the optional gateway VPC endpoint (e.g. com.amazonaws.us-east-1.s3). Leave null/empty to skip creation."
  type        = string
  default     = null
}

variable "tags" {
  description = "Additional tags merged into every taggable resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources & random helpers
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_integer" "vpc_name_suffix" {
  min = 1
  max = 100
}

resource "random_shuffle" "azs" {
  input        = data.aws_availability_zones.available.names
  result_count = local.az_count
}

###############################################################################
# Locals
###############################################################################

locals {
  # Random suffix appended to the VPC name prefix
  name = "${var.vpc_name_prefix}-${random_integer.vpc_name_suffix.result}"

  # Never ask for more AZs than the region actually offers
  az_count = min(var.max_subnet_count, length(data.aws_availability_zones.available.names))

  # Shuffled, region-derived AZ list used to place every subnet
  azs = random_shuffle.azs.result

  common_tags = merge(var.tags, {
    Project = var.vpc_name_prefix
    ManagedBy = "terraform"
  })
}

locals {
  # Number of subnets actually created per tier (bounded by AZ count and list length)
  subnet_counts = {
    web      = min(local.az_count, length(var.web_subnets))
    app      = min(local.az_count, length(var.app_subnets))
    database = min(local.az_count, length(var.database_subnets))
    reserved = min(local.az_count, length(var.reserved_subnets))
  }

  private_subnet_count = (
    local.subnet_counts.app +
    local.subnet_counts.database +
    local.subnet_counts.reserved
  )

  # Conditional creation flags
  create_igw        = local.subnet_counts.web > 0
  create_private_rt = local.private_subnet_count > 0

  create_gateway_endpoint = (
    local.create_private_rt &&
    var.gateway_vpc_endpoint_service_name != null &&
    var.gateway_vpc_endpoint_service_name != ""
  )
}

locals {
  # Subnet IDs grouped by tier - consumed by the interface VPC endpoints
  tier_subnet_ids = {
    web      = aws_subnet.web[*].id
    app      = aws_subnet.app[*].id
    database = aws_subnet.database[*].id
    reserved = aws_subnet.reserved[*].id
  }

  # Fallback placement when the requested tier has no subnets provisioned
  endpoint_fallback_subnets = (
    length(local.tier_subnet_ids.app) > 0 ? local.tier_subnet_ids.app :
    length(local.tier_subnet_ids.database) > 0 ? local.tier_subnet_ids.database :
    length(local.tier_subnet_ids.reserved) > 0 ? local.tier_subnet_ids.reserved :
    local.tier_subnet_ids.web
  )
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.name
  })
}

###############################################################################
# Subnets - web (public) tier
###############################################################################

resource "aws_subnet" "web" {
  count = local.subnet_counts.web

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.web_subnets[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-web-${element(local.azs, count.index)}"
    Tier = "web"
    Type = "public"
  })
}

###############################################################################
# Subnets - application (private) tier
###############################################################################

resource "aws_subnet" "app" {
  count = local.subnet_counts.app

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.app_subnets[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-app-${element(local.azs, count.index)}"
    Tier = "app"
    Type = "private"
  })
}

###############################################################################
# Subnets - database (private) tier
###############################################################################

resource "aws_subnet" "database" {
  count = local.subnet_counts.database

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.database_subnets[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-database-${element(local.azs, count.index)}"
    Tier = "database"
    Type = "private"
  })
}

###############################################################################
# Subnets - reserved (private) tier
###############################################################################

resource "aws_subnet" "reserved" {
  count = local.subnet_counts.reserved

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.reserved_subnets[count.index]
  availability_zone       = element(local.azs, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-reserved-${element(local.azs, count.index)}"
    Tier = "reserved"
    Type = "private"
  })
}

###############################################################################
# Internet gateway (created only when web subnets are provisioned)
###############################################################################

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

###############################################################################
# Public route table + web subnet associations
###############################################################################

resource "aws_route_table" "public" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
    Tier = "web"
  })
}

resource "aws_route_table_association" "web" {
  count = local.subnet_counts.web

  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Shared private route table (created when any private subnet exists)
###############################################################################

resource "aws_route_table" "private" {
  count = local.create_private_rt ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-rt"
    Tier = "private"
  })
}

resource "aws_route_table_association" "app" {
  count = local.subnet_counts.app

  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "database" {
  count = local.subnet_counts.database

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count = local.subnet_counts.reserved

  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Optional interface VPC endpoints (dynamic map driven)
###############################################################################

resource "aws_security_group" "vpc_endpoints" {
  count = length(var.interface_vpc_endpoints) > 0 ? 1 : 0

  name_prefix = "${local.name}-vpce-"
  description = "HTTPS access from within the VPC to interface VPC endpoints"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "HTTPS from the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpce-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = var.interface_vpc_endpoints

  vpc_id              = aws_vpc.this.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = each.value.private_dns_enabled
  security_group_ids  = [aws_security_group.vpc_endpoints[0].id]

  subnet_ids = length(lookup(local.tier_subnet_ids, each.value.subnet_tier, [])) > 0
    ? local.tier_subnet_ids[each.value.subnet_tier]
    : local.endpoint_fallback_subnets

  tags = merge(local.common_tags, {
    Name = "${local.name}-${each.key}-endpoint"
    Tier = each.value.subnet_tier
  })
}

###############################################################################
# Optional gateway VPC endpoint (auto-associated with the private route table)
###############################################################################

resource "aws_vpc_endpoint" "gateway" {
  count = local.create_gateway_endpoint ? 1 : 0

  vpc_id            = aws_vpc.this.id
  service_name      = var.gateway_vpc_endpoint_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private[0].id]

  tags = merge(local.common_tags, {
    Name = "${local.name}-gateway-endpoint"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.this.id
}

output "vpc_name" {
  description = "Name tag of the created VPC (prefix + random integer)."
  value       = local.name
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.this.cidr_block
}

output "availability_zones" {
  description = "Shuffled availability zones used for subnet placement."
  value       = local.azs
}

output "web_subnet_ids" {
  description = "IDs of the public (web) subnets."
  value       = aws_subnet.web[*].id
}

output "app_subnet_ids" {
  description = "IDs of the private application subnets."
  value       = aws_subnet.app[*].id
}

output "database_subnet_ids" {
  description = "IDs of the private database subnets."
  value       = aws_subnet.database[*].id
}

output "reserved_subnet_ids" {
  description = "IDs of the private reserved subnets."
  value       = aws_subnet.reserved[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway (null when no web subnets exist)."
  value       = one(aws_internet_gateway.this[*].id)
}

output "public_route_table_id" {
  description = "ID of the dedicated public route table (null when no web subnets exist)."
  value       = one(aws_route_table.public[*].id)
}

output "private_route_table_id" {
  description = "ID of the shared private route table (null when no private subnets exist)."
  value       = one(aws_route_table.private[*].id)
}

output "interface_vpc_endpoint_ids" {
  description = "Map of interface VPC endpoint name to endpoint ID."
  value       = { for name, endpoint in aws_vpc_endpoint.interface : name => endpoint.id }
}

output "gateway_vpc_endpoint_id" {
  description = "ID of the gateway VPC endpoint (null when no service name was supplied)."
  value       = one(aws_vpc_endpoint.gateway[*].id)
}

## Terraform Program Description

This configuration provisions a self-contained multi-tier network on AWS (default region `us-east-1`) for hosting web apps, game servers, build sandboxes, and databases.

**Components:**

1. **Provider & variables** – AWS provider, plus variables `aws_region`, `internal_domain` (default `"internal"`), `admin_cidrs` (default `["203.0.113.0/24"]`), and `public_dns_server` (default `"8.8.8.8"`), all with defaults so the template deploys without extra input.

2. **VPC** – `main` VPC (`10.0.0.0/16`) with DNS support and DNS hostnames enabled, an internet gateway `ig`, and a private Route 53 hosted zone for the internal domain associated with the VPC.

3. **DHCP options** – Domain name set to the internal domain, with resolvers `AmazonProvidedDNS` (VPC resolver) plus the public DNS server; associated with the VPC so all instances resolve the private zone.

4. **Subnets & routing** – Five subnets (`reserved`, `sandbox`, `web`, `database`, `gameserver`) each with `map_public_ip_on_launch = false`, each bound to its own route table with a `0.0.0.0/0` route to the internet gateway.

5. **Network ACLs** – Dedicated ACLs on `sandbox` (all TCP in/out), `web` (inbound TCP 22/80/443 and 32768‑65535, all outbound TCP), `database` (TCP only to/from the `web` and `gameserver` subnets), and `gameserver` (inbound SSH, TCP+UDP 27015/27020, TCP+UDP ephemeral 32768‑65535; all TCP/UDP outbound). Rule numbers are explicit so the implicit AWS deny-all applies to everything else.

6. **Security groups** – `Home SSH` allows SSH from the configurable admin CIDRs and from itself; `Packer SSH` allows SSH from the VPC CIDR and from itself. Both restrict all outbound traffic to the VPC CIDR.

No IAM roles are required, since the stack creates only VPC networking, DNS, and security-group resources and does not create compute, Lambda, or service-linked roles.

```iac_template
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the network stack."
  type        = string
  default     = "us-east-1"
}

variable "internal_domain" {
  description = "Internal (private) DNS domain name for the VPC."
  type        = string
  default     = "internal"
}

variable "admin_cidrs" {
  description = "CIDR blocks permitted to SSH into instances via the Home SSH security group."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "public_dns_server" {
  description = "Public DNS resolver used in addition to the VPC's built-in resolver."
  type        = string
  default     = "8.8.8.8"
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# VPC, internet gateway, DHCP options, private DNS
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ig"
  }
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain
  domain_name_servers = ["AmazonProvidedDNS", var.public_dns_server]

  tags = {
    Name = "${var.internal_domain}-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name = var.internal_domain

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = var.internal_domain
  }
}

###############################################################################
# Subnets (no auto-assigned public IPs)
###############################################################################

locals {
  subnet_cidrs = {
    reserved   = "10.0.0.0/24"
    sandbox    = "10.0.1.0/24"
    web        = "10.0.2.0/24"
    database   = "10.0.3.0/24"
    gameserver = "10.0.4.0/22"
  }
}

resource "aws_subnet" "main" {
  for_each = local.subnet_cidrs

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = each.key
  }
}

###############################################################################
# Route tables - one per subnet, all sending 0.0.0.0/0 to the internet gateway
###############################################################################

resource "aws_route_table" "main" {
  for_each = local.subnet_cidrs

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "${each.key}-rt"
  }
}

resource "aws_route_table_association" "main" {
  for_each = local.subnet_cidrs

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.main[each.key].id
}

###############################################################################
# Network ACL - sandbox (all TCP in and out)
###############################################################################

resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main["sandbox"].id]

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 0
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 0
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  tags = {
    Name = "sandbox-acl"
  }
}

###############################################################################
# Network ACL - web (SSH, HTTP, HTTPS, ephemeral in; all TCP out)
###############################################################################

resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main["web"].id]

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 22
    to_port    = 22
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 110
    action     = "allow"
    protocol   = "tcp"
    from_port  = 80
    to_port    = 80
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 120
    action     = "allow"
    protocol   = "tcp"
    from_port  = 443
    to_port    = 443
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 130
    action     = "allow"
    protocol   = "tcp"
    from_port  = 32768
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 0
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  tags = {
    Name = "web-acl"
  }
}

###############################################################################
# Network ACL - database (TCP only to/from web and gameserver subnets)
###############################################################################

resource "aws_network_acl" "database" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main["database"].id]

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 0
    to_port    = 65535
    cidr_block = aws_subnet.main["web"].cidr_block
  }

  ingress {
    rule_no    = 110
    action     = "allow"
    protocol   = "tcp"
    from_port  = 0
    to_port    = 65535
    cidr_block = aws_subnet.main["gameserver"].cidr_block
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 0
    to_port    = 65535
    cidr_block = aws_subnet.main["web"].cidr_block
  }

  egress {
    rule_no    = 110
    action     = "allow"
    protocol   = "tcp"
    from_port  = 0
    to_port    = 65535
    cidr_block = aws_subnet.main["gameserver"].cidr_block
  }

  tags = {
    Name = "database-acl"
  }
}

###############################################################################
# Network ACL - gameserver (SSH, game ports, ephemeral in; all TCP/UDP out)
###############################################################################

resource "aws_network_acl" "gameserver" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main["gameserver"].id]

  ingress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 22
    to_port    = 22
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 110
    action     = "allow"
    protocol   = "tcp"
    from_port  = 27015
    to_port    = 27015
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 120
    action     = "allow"
    protocol   = "udp"
    from_port  = 27015
    to_port    = 27015
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 130
    action     = "allow"
    protocol   = "tcp"
    from_port  = 27020
    to_port    = 27020
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 140
    action     = "allow"
    protocol   = "udp"
    from_port  = 27020
    to_port    = 27020
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 150
    action     = "allow"
    protocol   = "tcp"
    from_port  = 32768
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  ingress {
    rule_no    = 160
    action     = "allow"
    protocol   = "udp"
    from_port  = 32768
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 100
    action     = "allow"
    protocol   = "tcp"
    from_port  = 0
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  egress {
    rule_no    = 110
    action     = "allow"
    protocol   = "udp"
    from_port  = 0
    to_port    = 65535
    cidr_block = "0.0.0.0/0"
  }

  tags = {
    Name = "gameserver-acl"
  }
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH access from administrative CIDRs and from group members"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from administrative CIDR blocks"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from other members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Home SSH"
  }
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH access from inside the VPC and from group members"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from other members of this security group"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Packer SSH"
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the main VPC."
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.ig.id
}

output "subnet_ids" {
  description = "Map of subnet name to subnet ID."
  value       = { for k, v in aws_subnet.main : k => v.id }
}

output "subnet_cidr_blocks" {
  description = "Map of subnet name to CIDR block."
  value       = { for k, v in aws_subnet.main : k => v.cidr_block }
}

output "route_table_ids" {
  description = "Map of subnet name to route table ID."
  value       = { for k, v in aws_route_table.main : k => v.id }
}

output "network_acl_ids" {
  description = "Map of ACL name to network ACL ID."
  value = {
    sandbox    = aws_network_acl.sandbox.id
    web        = aws_network_acl.web.id
    database   = aws_network_acl.database.id
    gameserver = aws_network_acl.gameserver.id
  }
}

output "security_group_ids" {
  description = "Map of security group name to group ID."
  value = {
    home_ssh   = aws_security_group.home_ssh.id
    packer_ssh = aws_security_group.packer_ssh.id
  }
}

output "internal_hosted_zone_id" {
  description = "ID of the private Route 53 hosted zone for the internal domain."
  value       = aws_route53_zone.internal.zone_id
}

output "dhcp_options_id" {
  description = "ID of the VPC DHCP options set."
  value       = aws_vpc_dhcp_options.main.id
}
```

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the network."
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment name used to prefix resource Name tags."
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the three public subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_app_subnet_cidrs" {
  description = "CIDR blocks for the three private application subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_db_subnet_cidrs" {
  description = "CIDR blocks for the three private database subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  name_prefix = var.env != "" ? "${var.env}-" : ""
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)

  common_tags = {
    Environment = var.env
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC & Internet Gateway
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}igw"
  })
}

###############################################################################
# Public tier: subnets, single shared route table, associations
###############################################################################

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}public-subnet-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}public-rt"
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT: three Elastic IPs + three NAT Gateways (one per public subnet / AZ)
###############################################################################

resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}nat-eip-${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "nat" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}nat-gw-${count.index + 1}"
    Tier = "public"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Private application tier: subnets, zone-specific route tables, associations
###############################################################################

resource "aws_subnet" "private_app" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_app_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}private-app-subnet-${count.index + 1}"
    Tier = "private-app"
  })
}

resource "aws_route_table" "private_app" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}private-app-rt-${count.index + 1}"
    Tier = "private-app"
  })
}

resource "aws_route_table_association" "private_app" {
  count = 3

  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

###############################################################################
# Private database tier: subnets, single shared isolated route table
###############################################################################

resource "aws_subnet" "private_db" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_db_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}private-db-subnet-${count.index + 1}"
    Tier = "private-db"
  })
}

# Intentionally no explicit routes: the database tier keeps only the implicit
# VPC-local route matching the VPC CIDR block, fully isolating it from the
# internet and from the NAT gateways.
resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}database-rt"
    Tier = "private-db"
  })
}

resource "aws_route_table_association" "database" {
  count = 3

  subnet_id      = aws_subnet.private_db[count.index].id
  route_table_id = aws_route_table.database.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the three tiers."
  value       = local.azs
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "public_route_table_id" {
  description = "ID of the shared public route table."
  value       = aws_route_table.public.id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways (one per AZ)."
  value       = aws_nat_gateway.nat[*].id
}

output "nat_elastic_ip_addresses" {
  description = "Public Elastic IP addresses attached to the NAT gateways."
  value       = aws_eip.nat[*].public_ip
}

output "private_app_subnet_ids" {
  description = "IDs of the private application subnets."
  value       = aws_subnet.private_app[*].id
}

output "private_app_route_table_ids" {
  description = "IDs of the zone-specific private application route tables."
  value       = aws_route_table.private_app[*].id
}

output "private_db_subnet_ids" {
  description = "IDs of the private database subnets."
  value       = aws_subnet.private_db[*].id
}

output "database_route_table_id" {
  description = "ID of the shared, internet-isolated database route table."
  value       = aws_route_table.database.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

#############################################
# Variables
#############################################

variable "aws_region" {
  description = "AWS region in which to deploy the S3 bucket."
  type        = string
  default     = "us-east-1"
}

variable "base_bucket_name" {
  description = "Base name used to construct the S3 bucket name."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the current AWS IAM account alias."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Append a random 4-byte hexadecimal suffix to the bucket name."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional JSON bucket policy that is merged (via source_policy_documents) with the enforced compliance statements."
  type        = string
  default     = ""
}

variable "enable_s3_public_access_block" {
  description = "Enable all four S3 public access block settings."
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Ownership control rule for the bucket (BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter)."
  type        = string
  default     = "BucketOwnerEnforced"
}

variable "s3_bucket_acl" {
  description = "Optional canned ACL applied to the bucket (requires object_ownership that still permits ACLs, e.g. ObjectWriter)."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "Optional KMS key ARN/ID. When set, server-side encryption switches to aws:kms instead of AES256."
  type        = string
  default     = ""
}

variable "bucket_key_enabled" {
  description = "Enable S3 Bucket Keys for SSE-KMS."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Bucket versioning status (Enabled, Suspended or Disabled)."
  type        = string
  default     = "Enabled"
}

variable "force_destroy" {
  description = "Force destruction of the bucket and all objects on delete."
  type        = bool
  default     = false
}

variable "transition_default_minimum_object_size" {
  description = "Minimum object size for lifecycle storage-class transitions."
  type        = string
  default     = "all_storage_classes_128K"
}

variable "enable_analytics" {
  description = "Enable S3 storage class analytics exporting to the _AWSBucketAnalytics/ prefix."
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable weekly ORC bucket inventory exporting to the _AWSBucketInventory/ prefix."
  type        = bool
  default     = false
}

variable "inventory_frequency" {
  description = "Inventory schedule frequency (Daily or Weekly)."
  type        = string
  default     = "Weekly"
}

variable "logging_bucket" {
  description = "Optional external target bucket name for server access logging."
  type        = string
  default     = ""
}

variable "transfer_acceleration" {
  description = "Optional transfer acceleration status (Enabled or Suspended). When null, no acceleration configuration is created."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules applied dynamically to the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "tags" {
  description = "Additional tags applied to the bucket."
  type        = map(string)
  default     = {}
}

#############################################
# Data sources / local naming helpers
#############################################

data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

resource "random_id" "bucket_suffix" {
  count       = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

locals {
  account_alias        = var.use_account_alias_prefix ? join("", data.aws_iam_account_alias.current[*].account_alias) : ""
  account_alias_prefix = local.account_alias != "" ? "${local.account_alias}-" : ""
  random_suffix        = var.use_random_suffix ? "-${random_id.bucket_suffix[0].hex}" : ""
  bucket_name          = "${local.account_alias_prefix}${var.base_bucket_name}${local.random_suffix}"

  common_tags = merge(
    var.tags,
    {
      Name      = local.bucket_name
      ManagedBy = "Terraform"
    }
  )
}

#############################################
# Bucket
#############################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = local.common_tags
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != "" ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
    }

    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

#############################################
# Lifecycle management
#############################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = var.transition_default_minimum_object_size

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-management"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []
    content {
      id     = "analytics-export-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketAnalytics/"
      }

      expiration {
        days = 30
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []
    content {
      id     = "inventory-export-expiration"
      status = "Enabled"

      filter {
        prefix = "_AWSBucketInventory/"
      }

      expiration {
        days = 14
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

#############################################
# Analytics and inventory reporting
#############################################

resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "EntireBucketAnalytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          format     = "CSV"
          prefix     = "_AWSBucketAnalytics/"
        }
      }
    }
  }
}

resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "EntireBucketInventory"

  included_object_versions = "All"

  schedule {
    frequency = var.inventory_frequency
  }

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = "_AWSBucketInventory/"
    }
  }
}

#############################################
# Optional features
#############################################

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != "" ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

#############################################
# Compliance bucket policy
#############################################

data "aws_iam_policy_document" "bucket" {
  source_policy_documents = compact([var.custom_bucket_policy])

  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowS3ServicePrincipalInventoryAndAnalyticsWrites"
    effect = "Allow"

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.this.arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

#############################################
# Outputs
#############################################

output "bucket_id" {
  description = "The name (ID) of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_name" {
  description = "The resolved S3 bucket name."
  value       = aws_s3_bucket.this.bucket
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The region-specific bucket domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_policy_json" {
  description = "The enforced (merged) bucket policy document."
  value       = data.aws_iam_policy_document.bucket.json
}

################################################################################
# Terraform & Provider Configuration
################################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.60.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

################################################################################
# Data Sources
################################################################################

data "aws_caller_identity" "current" {}

data "aws_canonical_user_id" "current" {}

################################################################################
# Variables
################################################################################

variable "aws_region" {
  description = "AWS region in which the S3 bucket is deployed."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket."
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment value used in the default tag set."
  type        = string
  default     = "Development"
}

variable "service_provider" {
  description = "Value assigned to the ServiceProvider tag."
  type        = string
  default     = "Rackspace"
}

variable "additional_tags" {
  description = "Additional tags merged with the default tags."
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Whether to delete all objects when the bucket is destroyed."
  type        = bool
  default     = false
}

# --- Access control -----------------------------------------------------------

variable "acl" {
  description = "Canned ACL applied to the bucket (private, public-read, ...). Ignored when JSON grants are supplied."
  type        = string
  default     = ""
}

variable "grants" {
  description = "JSON encoded list of ACL grants, e.g. [{\"type\":\"CanonicalUser\",\"permission\":\"FULL_CONTROL\",\"id\":\"canonical-id\"}]."
  type        = string
  default     = ""
}

variable "owner_id" {
  description = "Canonical user ID used as the ACL owner. Defaults to the caller identity canonical user ID."
  type        = string
  default     = ""
}

variable "control_object_ownership" {
  description = "Whether to manage S3 bucket ownership controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting applied when control_object_ownership is true."
  type        = string
  default     = "ObjectWriter"
}

# --- Public access block ------------------------------------------------------

variable "create_public_access_block" {
  description = "Whether to create the S3 public access block configuration."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Block public ACLs for the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies for the bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs for the bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public bucket policies for the bucket."
  type        = bool
  default     = true
}

# --- Encryption ---------------------------------------------------------------

variable "sse_algorithm" {
  description = "Server-side encryption algorithm: AES256, aws:kms, or none to disable encryption configuration."
  type        = string
  default     = "AES256"
}

variable "kms_master_key_id" {
  description = "ARN or ID of the KMS key used when sse_algorithm is aws:kms. Empty creates a dedicated KMS key."
  type        = string
  default     = ""
}

variable "kms_bucket_key_enabled" {
  description = "Whether to enable the S3 bucket key when using aws:kms encryption."
  type        = bool
  default     = true
}

# --- Versioning ---------------------------------------------------------------

variable "versioning_enabled" {
  description = "Whether bucket versioning is enabled (Suspended when false)."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Whether MFA delete is enabled for the bucket."
  type        = bool
  default     = false
}

# --- Logging ------------------------------------------------------------------

variable "bucket_logging" {
  description = "Whether server access logging is configured for the bucket."
  type        = bool
  default     = false
}

variable "log_bucket_name" {
  description = "Name of the target bucket that receives the access logs."
  type        = string
  default     = ""
}

variable "log_prefix" {
  description = "Prefix applied to the delivered access log objects."
  type        = string
  default     = ""
}

# --- Object lock --------------------------------------------------------------

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled for the bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default retention mode for Object Lock (GOVERNANCE or COMPLIANCE)."
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_days" {
  description = "Default retention period in days. Ignored when object_lock_years is greater than zero."
  type        = number
  default     = 1
}

variable "object_lock_years" {
  description = "Default retention period in years. Takes precedence over object_lock_days when greater than zero."
  type        = number
  default     = 0
}

# --- Static website -----------------------------------------------------------

variable "enable_website" {
  description = "Whether static website hosting configuration is created."
  type        = bool
  default     = false
}

variable "website_configuration" {
  description = "Map describing the static website configuration (index_document, error_document, redirect_all_requests_to, routing_rules)."
  type        = map(any)
  default     = {}
}

# --- Intelligent tiering ------------------------------------------------------

variable "enable_intelligent_tiering" {
  description = "Whether intelligent tiering configurations are created."
  type        = bool
  default     = false
}

variable "intelligent_tiering_configurations" {
  description = "List of intelligent tiering configurations (name, status, filter_prefix, tierings[{access_tier, days}])."
  type        = list(any)
  default     = []
}

# --- CloudWatch metrics -------------------------------------------------------

variable "enable_cloudwatch_metrics" {
  description = "Whether CloudWatch request metrics configurations are created."
  type        = bool
  default     = false
}

variable "metrics_configurations" {
  description = "List of CloudWatch metrics configurations (name, filter_prefix)."
  type        = list(any)
  default     = []
}

# --- CORS ---------------------------------------------------------------------

variable "enable_cors" {
  description = "Whether CORS configuration is created for the bucket."
  type        = bool
  default     = false
}

variable "cors_rules" {
  description = "List of CORS rules (id, allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds)."
  type        = list(any)
  default     = []
}

# --- Lifecycle ----------------------------------------------------------------

variable "enable_lifecycle" {
  description = "Whether lifecycle configuration is created for the bucket."
  type        = bool
  default     = false
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules (id, status, filter, expiration, transitions, noncurrent_version_* , abort_incomplete_multipart_upload_days)."
  type        = list(any)
  default     = []
}

################################################################################
# Locals
################################################################################

locals {
  tags = merge(
    {
      Environment     = var.environment
      ServiceProvider = var.service_provider
    },
    var.additional_tags
  )

  # JSON encoded grants decoded into a list of grant objects.
  grants = var.grants != "" ? jsondecode(var.grants) : []

  # Owner of the ACL - falls back to the caller identity canonical user ID.
  acl_owner_id = var.owner_id != "" ? var.owner_id : data.aws_canonical_user_id.current.id

  # A customer managed KMS key is created when aws:kms is requested without a key id.
  create_kms_key = var.sse_algorithm == "aws:kms" && var.kms_master_key_id == ""
  kms_key_arn    = var.kms_master_key_id != "" ? var.kms_master_key_id : one(aws_kms_key.this[*].arn)

  # Object Lock requires versioning to be enabled.
  versioning_status = (var.versioning_enabled || var.object_lock_enabled) ? "Enabled" : "Suspended"

  # Access logging is only provisioned against an explicit target bucket.
  create_logging = var.bucket_logging && var.log_bucket_name != ""

  # Object Lock retention period expressed in years when provided.
  object_lock_use_years = var.object_lock_years > 0

  # ACL resource is created for a canned ACL or for JSON grants.
  create_acl = var.acl != "" || length(local.grants) > 0

  # Intelligent tiering / metrics keyed by name for stable for_each addressing.
  intelligent_tiering = {
    for idx, cfg in var.intelligent_tiering_configurations :
    try(cfg.name, tostring(idx)) => cfg
  }

  metrics = {
    for idx, cfg in var.metrics_configurations :
    try(cfg.name, tostring(idx)) => cfg
  }
}

################################################################################
# Optional KMS key used with aws:kms encryption
################################################################################

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "KMS key used for S3 bucket ${var.bucket_name} server-side encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/${var.bucket_name}-sse"
  target_key_id = aws_kms_key.this[0].key_id
}

################################################################################
# S3 Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.tags
}

################################################################################
# Public Access Block
################################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

################################################################################
# Server-Side Encryption
################################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.sse_algorithm == "none" ? 0 : 1

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? local.kms_key_arn : null
    }

    bucket_key_enabled = var.sse_algorithm == "aws:kms" ? var.kms_bucket_key_enabled : null
  }
}

################################################################################
# Versioning (and MFA delete)
################################################################################

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = local.versioning_status
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

################################################################################
# Bucket ACL (canned ACL or JSON encoded grant policy)
################################################################################

resource "aws_s3_bucket_acl" "this" {
  count = local.create_acl ? 1 : 0

  bucket = aws_s3_bucket.this.id

  # A canned ACL cannot be combined with an access control policy.
  acl = length(local.grants) > 0 ? null : var.acl

  dynamic "access_control_policy" {
    for_each = length(local.grants) > 0 ? [1] : []

    content {
      owner {
        id = local.acl_owner_id
      }

      dynamic "grant" {
        for_each = local.grants

        content {
          type         = grant.value.type
          permission   = grant.value.permission
          id           = try(grant.value.id, null)
          uri          = try(grant.value.uri, null)
          display_name = try(grant.value.display_name, null)
        }
      }
    }
  }
}

################################################################################
# Bucket Ownership Controls
################################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

################################################################################
# Server Access Logging
################################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.create_logging ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.log_bucket_name
  target_prefix = var.log_prefix
}

################################################################################
# Object Lock Configuration
################################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = local.object_lock_use_years ? null : var.object_lock_days
      years = local.object_lock_use_years ? var.object_lock_years : null
    }
  }
}

################################################################################
# Static Website Hosting
################################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.enable_website && length(var.website_configuration) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(var.website_configuration.index_document, null) != null ? [var.website_configuration.index_document] : []

    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website_configuration.error_document, null) != null ? [var.website_configuration.error_document] : []

    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website_configuration.redirect_all_requests_to, null) != null ? [var.website_configuration.redirect_all_requests_to] : []

    content {
      host_name = try(redirect_all_requests_to.value.host_name, null)
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website_configuration.routing_rules, [])

    content {
      dynamic "condition" {
        for_each = try(routing_rule.value.condition, null) != null ? [routing_rule.value.condition] : []

        content {
          http_error_code_returned_equals = try(condition.value.http_error_code_returned_equals, null)
          key_prefix_equals               = try(condition.value.key_prefix_equals, null)
        }
      }

      redirect {
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        protocol                = try(routing_rule.value.redirect.protocol, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

################################################################################
# Intelligent Tiering
################################################################################

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = var.enable_intelligent_tiering ? local.intelligent_tiering : {}

  bucket = aws_s3_bucket.this.id
  name   = each.key
  status = try(each.value.status, "Enabled")

  dynamic "filter" {
    for_each = try(each.value.filter_prefix, null) != null ? [each.value.filter_prefix] : []

    content {
      prefix = filter.value
    }
  }

  dynamic "tiering" {
    for_each = try(each.value.tierings, [])

    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

################################################################################
# CloudWatch Request Metrics
################################################################################

resource "aws_s3_bucket_metric" "this" {
  for_each = var.enable_cloudwatch_metrics ? local.metrics : {}

  bucket = aws_s3_bucket.this.id
  name   = each.key

  dynamic "filter" {
    for_each = try(each.value.filter_prefix, null) != null ? [each.value.filter_prefix] : []

    content {
      prefix = filter.value
    }
  }
}

################################################################################
# CORS Configuration
################################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.enable_cors && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

################################################################################
# Lifecycle Configuration
################################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.enable_lifecycle && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.status, "Enabled")

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []

        content {
          prefix                   = try(filter.value.prefix, null)
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)
          tags                     = try(filter.value.tags, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []

        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])

        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])

        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

################################################################################
# Outputs
################################################################################

output "bucket_id" {
  description = "ID (name) of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "Region specific bucket domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_region" {
  description = "Region in which the bucket was created."
  value       = aws_s3_bucket.this.region
}

output "acl_owner_id" {
  description = "Canonical user ID used as the owner of the bucket ACL."
  value       = local.acl_owner_id
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for server side encryption (created or supplied)."
  value       = local.kms_key_arn
}

output "kms_key_id" {
  description = "ID of the KMS key created by this module, when applicable."
  value       = one(aws_kms_key.this[*].id)
}

output "caller_account_id" {
  description = "Account ID of the caller."
  value       = data.aws_caller_identity.current.account_id
}

###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region where the resources are deployed."
  type        = string
  default     = "us-east-1"
}

variable "bucket" {
  description = "Name of the bucket. If empty, `name_prefix` is used instead."
  type        = string
  default     = ""

  validation {
    condition     = length(var.bucket) <= 63
    error_message = "The bucket name must be 63 characters or less."
  }
}

variable "name_prefix" {
  description = "Prefix used to generate a unique bucket name when `bucket` is not provided."
  type        = string
  default     = "s3-bucket-"

  validation {
    condition     = length(var.name_prefix) <= 37
    error_message = "The name_prefix must be 37 characters or less."
  }
}

variable "force_destroy" {
  description = "Whether all objects should be deleted from the bucket on destroy."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting for the bucket."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be one of: BucketOwnerEnforced, BucketOwnerPreferred, ObjectWriter."
  }
}

variable "acl" {
  description = "Canned ACL applied when object_ownership is ObjectWriter."
  type        = string
  default     = "private"
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "ARN of a KMS key used for SSE-KMS. When set, encryption switches to aws:kms and bucket keys are enabled."
  type        = string
  default     = null
}

variable "versioning_enabled" {
  description = "Whether bucket versioning is enabled. When false, versioning is Suspended."
  type        = bool
  default     = false
}

variable "policy" {
  description = "Optional custom IAM policy JSON to merge with the enforced statements."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "List of source bucket ARNs allowed to deliver server access logs into this bucket."
  type        = list(string)
  default     = []
}

variable "eventbridge" {
  description = "Whether to enable EventBridge notifications for the bucket."
  type        = bool
  default     = false
}

variable "logging" {
  description = "Server access logging configuration, e.g. { target_bucket = \"my-logs\", target_prefix = \"logs/\" }."
  type        = any
  default     = {}
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled on the bucket. Must be set at bucket creation time."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Object Lock default retention configuration, e.g. { mode = \"GOVERNANCE\", days = 30 }."
  type        = any
  default     = null
}

variable "replication_configuration" {
  description = "Cross-region replication configuration with `role` and `rules`."
  type        = any
  default     = {}
}

variable "replication_kms_key_arns" {
  description = "KMS key ARNs the replication role may use for decrypt/encrypt."
  type        = list(string)
  default     = []
}

variable "inventory_configurations" {
  description = "List of S3 inventory configurations (schedule, filter, destination bucket / format / encryption)."
  type        = any
  default     = []
}

variable "cors_rule" {
  description = "List of CORS rules."
  type        = any
  default     = []
}

variable "lifecycle_rule" {
  description = "List of lifecycle rules supporting expiration, transitions, noncurrent versions and multipart aborts."
  type        = any
  default     = []
}

variable "tags" {
  description = "Tags applied to all resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  sse_algorithm = (var.kms_key_arn != null && var.kms_key_arn != "") ? "aws:kms" : "AES256"

  create_acl = var.object_ownership == "ObjectWriter"

  logging_configured = var.logging != null && length(keys(try(var.logging, {}))) > 0

  replication_rules = try(var.replication_configuration.rules, [])

  create_replication_role = length(local.replication_rules) > 0 && try(var.replication_configuration.role, null) == null

  replication_dest_buckets = [
    for r in local.replication_rules : try(r.destination.bucket, null)
    if try(r.destination.bucket, null) != null
  ]

  replication_dest_arns = distinct(flatten([
    for b in local.replication_dest_buckets : [b, "${b}/*"]
  ]))

  bucket_name = var.bucket != "" ? var.bucket : null
  bucket_prefix = var.bucket != "" ? null : var.name_prefix
}

###############################################################################
# S3 Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  bucket_prefix       = local.bucket_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = merge(var.tags, { Name = var.bucket != "" ? var.bucket : var.name_prefix })
}

###############################################################################
# Ownership controls & conditional canned ACL
###############################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = local.create_acl ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Public access block
###############################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

###############################################################################
# Versioning
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

###############################################################################
# Server-side encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.sse_algorithm == "aws:kms" ? var.kms_key_arn : null
      sse_algorithm     = local.sse_algorithm
    }

    bucket_key_enabled = local.sse_algorithm == "aws:kms" ? true : null
  }
}

###############################################################################
# Bucket policy (custom + SSL-only + logging service permission)
###############################################################################

data "aws_iam_policy_document" "bucket_policy" {
  source_policy_documents = var.policy != null && var.policy != "" ? [var.policy] : []

  statement {
    sid     = "DenyInsecureConnections"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []

    content {
      sid     = "S3ServerAccessLogsPolicy"
      effect  = "Allow"
      actions = ["s3:PutObject"]

      resources = ["${aws_s3_bucket.this.arn}/*"]

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# EventBridge notifications
###############################################################################

resource "aws_s3_bucket_notification" "this" {
  count = var.eventbridge ? 1 : 0

  bucket      = aws_s3_bucket.this.id
  eventbridge = true
}

###############################################################################
# Server access logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.logging_configured ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging.target_bucket
  target_prefix = try(var.logging.target_prefix, null)

  lifecycle {
    precondition {
      condition     = !(var.object_lock_enabled && local.logging_configured)
      error_message = "Server access logging cannot be enabled on a bucket that has Object Lock enabled."
    }
  }
}

###############################################################################
# Object Lock configuration
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.object_lock_configuration != null ? [var.object_lock_configuration] : []
    content {
      default_retention {
        mode  = rule.value.mode
        days  = try(rule.value.days, null)
        years = try(rule.value.years, null)
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = var.object_lock_enabled
      error_message = "Object Lock configuration requires object_lock_enabled = true on the bucket."
    }

    precondition {
      condition     = var.versioning_enabled
      error_message = "Object Lock configuration requires bucket versioning to be enabled."
    }

    precondition {
      condition     = !local.logging_configured
      error_message = "Object Lock configuration cannot be combined with server access logging on the same bucket."
    }

    precondition {
      condition     = !contains(var.logging_source_bucket_arns, aws_s3_bucket.this.arn)
      error_message = "Object Lock configuration cannot be applied to a bucket that acts as a logging source."
    }
  }
}

###############################################################################
# Cross-region replication role (created only if no role is supplied)
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  count = local.create_replication_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "replication" {
  count = local.create_replication_role ? 1 : 0

  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:PutBucketVersioning",
      "s3:GetBucketObjectLockConfiguration",
    ]

    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    sid    = "SourceObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:GetObjectVersionAttributes",
    ]

    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  statement {
    sid    = "DestinationBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
      "s3:PutObject",
      "s3:PutObjectVersionTagging",
    ]

    resources = length(local.replication_dest_arns) > 0 ? local.replication_dest_arns : ["*"]
  }

  dynamic "statement" {
    for_each = length(var.replication_kms_key_arns) > 0 ? [1] : []

    content {
      sid    = "KmsPermissions"
      effect = "Allow"

      actions = [
        "kms:Decrypt",
        "kms:Encrypt",
        "kms:GenerateDataKey",
        "kms:ReEncryptFrom",
        "kms:ReEncryptTo",
        "kms:DescribeKey",
      ]

      resources = var.replication_kms_key_arns
    }
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0

  name_prefix        = "s3-replication-"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json
  tags               = var.tags
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_replication_role ? 1 : 0

  name   = "s3-replication-policy"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication[0].json
}

###############################################################################
# Cross-region replication configuration
###############################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = length(local.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = local.create_replication_role ? aws_iam_role.replication[0].arn : var.replication_configuration.role

  dynamic "rule" {
    for_each = local.replication_rules
    content {
      id       = rule.value.id
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication_status, null) != null ? [rule.value.delete_marker_replication_status] : []
        content {
          status = delete_marker_replication.value
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }

          dynamic "replica_modifications" {
            for_each = try(source_selection_criteria.value.replica_modifications, null) != null ? [source_selection_criteria.value.replica_modifications] : []
            content {
              status = replica_modifications.value.status
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account_id    = try(rule.value.destination.account_id, null)

        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation, null) != null ? [rule.value.destination.access_control_translation] : []
          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.encryption_configuration, null) != null ? [rule.value.destination.encryption_configuration] : []
          content {
            replica_kms_key_id = try(encryption_configuration.value.replica_kms_key_id, null)
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_iam_role_policy.replication,
  ]

  lifecycle {
    precondition {
      condition     = var.versioning_enabled
      error_message = "Cross-region replication requires bucket versioning to be enabled."
    }
  }
}

###############################################################################
# Inventory configurations
###############################################################################

resource "aws_s3_bucket_inventory" "this" {
  for_each = { for inv in var.inventory_configurations : inv.name => inv }

  bucket                   = aws_s3_bucket.this.id
  name                     = each.value.name
  included_object_versions = try(each.value.included_object_versions, "All")
  optional_fields          = try(each.value.optional_fields, null)

  schedule {
    frequency = each.value.schedule.frequency
  }

  dynamic "filter" {
    for_each = try(each.value.filter, null) != null ? [each.value.filter] : []
    content {
      prefix = try(filter.value.prefix, null)
    }
  }

  destination {
    bucket {
      format     = each.value.destination.format
      bucket_arn = each.value.destination.bucket_arn
      prefix     = try(each.value.destination.prefix, null)

      encryption {
        dynamic "sse_s3" {
          for_each = try(each.value.destination.encryption, null) != null && try(each.value.destination.encryption.sse_s3, null) != null ? [1] : []
          content {}
        }

        dynamic "sse_kms" {
          for_each = try(each.value.destination.encryption, null) != null && try(each.value.destination.encryption.sse_kms, null) != null ? [each.value.destination.encryption.sse_kms] : []
          content {
            key_id = try(sse_kms.value.key_id, null)
          }
        }
      }
    }
  }
}

###############################################################################
# CORS configuration
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(try(var.cors_rule, [])) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Lifecycle configuration
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(try(var.lifecycle_rule, [])) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = rule.value.id
      status = try(rule.value.status, "Enabled")

      filter {
        prefix                   = try(rule.value.filter.prefix, null)
        object_size_greater_than = try(rule.value.filter.object_size_greater_than, null)
        object_size_less_than    = try(rule.value.filter.object_size_less_than, null)

        dynamic "tag" {
          for_each = try(rule.value.filter.tags, {})
          content {
            key   = tag.key
            value = tag.value
          }
        }

        dynamic "and" {
          for_each = try(rule.value.filter.and, null) != null ? [rule.value.filter.and] : []
          content {
            prefix                   = try(and.value.prefix, null)
            tags                     = try(and.value.tags, null)
            object_size_greater_than = try(and.value.object_size_greater_than, null)
            object_size_less_than    = try(and.value.object_size_less_than, null)
          }
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])
        content {
          noncurrent_days           = try(noncurrent_version_transition.value.noncurrent_days, null)
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region used by the provider."
  type        = string
  default     = "us-east-1"
}

variable "group_name_prefix" {
  description = "Prefix used to name the developer and admin IAM groups."
  type        = string
  default     = "app"
}

variable "s3_bucket_creation_region" {
  description = "The single AWS region in which developers are allowed to create S3 buckets."
  type        = string
  default     = "us-east-1"
}

variable "remote_state_bucket_name" {
  description = "Name of the Terraform remote-state S3 bucket that developers must not be able to access."
  type        = string
  default     = "terraform-remote-state"
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

###############################################################################
# Account-wide security baselines
###############################################################################

resource "aws_iam_account_password_policy" "baseline" {
  minimum_password_length        = 12
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
}

resource "aws_s3_account_public_access_block" "baseline" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# IAM groups
###############################################################################

resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

###############################################################################
# Developer group - AWS managed policies
###############################################################################

resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMUserSSHKeys"
}

###############################################################################
# Developer group - custom policy: manage own access keys
###############################################################################

data "aws_iam_policy_document" "developer_access_keys" {
  statement {
    sid    = "ManageOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
      "iam:GetAccessKeyLastUsed",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/&{aws:username}",
    ]
  }
}

resource "aws_iam_policy" "developer_access_keys" {
  name        = "${var.group_name_prefix}_developer_access_keys"
  description = "Allow developers to manage their own IAM access keys."
  policy      = data.aws_iam_policy_document.developer_access_keys.json
}

resource "aws_iam_group_policy_attachment" "developer_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_access_keys.arn
}

###############################################################################
# Developer group - custom policy: virtual MFA devices (MFA required to deactivate)
###############################################################################

data "aws_iam_policy_document" "developer_mfa" {
  statement {
    sid    = "ManageOwnVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/&{aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/&{aws:username}",
    ]
  }

  statement {
    sid       = "DenySelfDeactivateMFAWithoutMFA"
    effect    = "Deny"
    actions   = ["iam:DeactivateMFADevice"]
    resources = ["arn:${local.partition}:iam::${local.account_id}:user/&{aws:username}"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developer_mfa" {
  name        = "${var.group_name_prefix}_developer_mfa"
  description = "Manage own virtual MFA devices; deactivation requires an MFA-authenticated session."
  policy      = data.aws_iam_policy_document.developer_mfa.json
}

resource "aws_iam_group_policy_attachment" "developer_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa.arn
}

###############################################################################
# Developer group - custom policy: MFA-gated S3 access
###############################################################################

data "aws_iam_policy_document" "developer_s3" {
  # Allow S3 usage (gated by the MFA deny statement below).
  statement {
    sid       = "AllowS3"
    effect    = "Allow"
    actions   = ["s3:*"]
    resources = ["*"]
  }

  # MFA gate: without an MFA-authenticated session, deny all S3 actions.
  statement {
    sid       = "DenyS3WithoutMFA"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = ["*"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }

  # Only allow bucket creation in the single designated region.
  statement {
    sid       = "DenyCreateBucketOutsideDesignatedRegion"
    effect    = "Deny"
    actions   = ["s3:CreateBucket"]
    resources = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [var.s3_bucket_creation_region]
    }
  }

  # Never allow access to the Terraform remote-state bucket or its objects.
  statement {
    sid       = "DenyRemoteStateBucket"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      "arn:${local.partition}:s3:::${var.remote_state_bucket_name}",
      "arn:${local.partition}:s3:::${var.remote_state_bucket_name}/*",
    ]
  }
}

resource "aws_iam_policy" "developer_s3" {
  name        = "${var.group_name_prefix}_developer_s3"
  description = "MFA-gated S3 access; bucket creation restricted to one region and remote-state bucket blocked."
  policy      = data.aws_iam_policy_document.developer_s3.json
}

resource "aws_iam_group_policy_attachment" "developer_s3" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3.arn
}

###############################################################################
# Developer group - custom policy: MFA-gated EC2 / ELB / CloudWatch / AutoScaling
###############################################################################

data "aws_iam_policy_document" "developer_compute" {
  statement {
    sid    = "AllowComputeAndMonitoringServices"
    effect = "Allow"

    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "autoscaling:*",
    ]

    resources = ["*"]
  }

  statement {
    sid       = "AllowCreateServiceLinkedRoles"
    effect    = "Allow"
    actions   = ["iam:CreateServiceLinkedRole"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"
      values = [
        "autoscaling.amazonaws.com",
        "spot.amazonaws.com",
        "spotfleet.amazonaws.com",
        "ec2.application-autoscaling.amazonaws.com",
      ]
    }
  }

  statement {
    sid    = "AllowManageComputeServiceLinkedRoles"
    effect = "Allow"

    actions = [
      "iam:DeleteServiceLinkedRole",
      "iam:GetServiceLinkedRoleDeletionStatus",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/spot.amazonaws.com/AWSServiceRoleForEC2Spot",
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/spotfleet.amazonaws.com/AWSServiceRoleForEC2SpotFleet",
      "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/ec2.application-autoscaling.amazonaws.com/AWSServiceRoleForApplicationAutoScaling_EC2SpotFleetRequest",
    ]
  }

  # MFA gate across compute / monitoring services.
  statement {
    sid    = "DenyComputeServicesWithoutMFA"
    effect = "Deny"

    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "autoscaling:*",
    ]

    resources = ["*"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developer_compute" {
  name        = "${var.group_name_prefix}_developer_compute"
  description = "MFA-gated access to EC2, ELB, CloudWatch, AutoScaling, and related service-linked roles."
  policy      = data.aws_iam_policy_document.developer_compute.json
}

resource "aws_iam_group_policy_attachment" "developer_compute" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_compute.arn
}

###############################################################################
# Administrative role "admin"
###############################################################################

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountRootToAssumeAdminRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name                 = "admin"
  description          = "Administrative role assumable by the account root, usable only with MFA."
  assume_role_policy   = data.aws_iam_policy_document.admin_assume_role.json
  max_session_duration = 3600
}

data "aws_iam_policy_document" "admin_full_access_with_mfa" {
  statement {
    sid       = "FullAdministrativeAccessWithMFA"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role_policy" "admin_full_access_with_mfa" {
  name   = "admin-full-access-with-mfa"
  role   = aws_iam_role.admin.id
  policy = data.aws_iam_policy_document.admin_full_access_with_mfa.json
}

###############################################################################
# Admin group - assume the "admin" role when MFA is present
###############################################################################

data "aws_iam_policy_document" "admin_group_assume_role" {
  statement {
    sid       = "AssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "admin_assume_role" {
  name   = "assume-admin-role"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin_group_assume_role.json
}

###############################################################################
# Provider & Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Input variables
###############################################################################

variable "aws_region" {
  description = "AWS region where the network will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "Primary IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnets" {
  description = "16 subnet definitions (CIDR block, availability zone, Name tag)."
  type = list(object({
    cidr_block        = string
    availability_zone = string
    name              = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24",  availability_zone = "us-east-1a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24",  availability_zone = "us-east-1b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24",  availability_zone = "us-east-1c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24",  availability_zone = "us-east-1a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24",  availability_zone = "us-east-1b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24",  availability_zone = "us-east-1c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24",  availability_zone = "us-east-1a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24",  availability_zone = "us-east-1b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24",  availability_zone = "us-east-1c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24",  availability_zone = "us-east-1a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", availability_zone = "us-east-1b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", availability_zone = "us-east-1c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", availability_zone = "us-east-1a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", availability_zone = "us-east-1b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", availability_zone = "us-east-1c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", availability_zone = "us-east-1a", name = "subnet-15" },
  ]
}

###############################################################################
# Locals - logical partitioning of the 16 subnets into tiers
###############################################################################

locals {
  # Tier A (private)  : subnet-0  ... subnet-3
  # Tier B (private)  : subnet-4  ... subnet-7
  # Public tier       : subnet-8  ... subnet-11
  # Spare tier        : subnet-12 ... subnet-15
  private_subnet_ids = [for i in range(0, 8) : aws_subnet.this[i].id]
  public_subnet_ids  = [for i in range(8, 12) : aws_subnet.this[i].id]
  spare_subnet_ids   = [for i in range(12, 16) : aws_subnet.this[i].id]
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

###############################################################################
# Subnets (16 across three availability zones)
###############################################################################

resource "aws_subnet" "this" {
  count = length(var.subnets)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnets[count.index].cidr_block
  availability_zone       = var.subnets[count.index].availability_zone
  map_public_ip_on_launch = false

  tags = {
    Name = var.subnets[count.index].name
  }
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw-deploy-me"
  }
}

###############################################################################
# Elastic IP (VPC domain) + NAT Gateway
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "deployme-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.this[0].id

  tags = {
    Name = "deployme-natgw"
  }

  depends_on = [aws_internet_gateway.igw]
}

###############################################################################
# Route table - private (main route table for the VPC)
###############################################################################

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  count = length(local.private_subnet_ids)

  subnet_id      = local.private_subnet_ids[count.index]
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Route table - public
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table_association" "public" {
  count = length(local.public_subnet_ids)

  subnet_id      = local.public_subnet_ids[count.index]
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Route table - spare
###############################################################################

resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route_table_association" "spare" {
  count = length(local.spare_subnet_ids)

  subnet_id      = local.spare_subnet_ids[count.index]
  route_table_id = aws_route_table.spare.id
}

###############################################################################
# Security group - web traffic
###############################################################################

resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow inbound HTTP/HTTPS from anywhere and SSH from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from the VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

###############################################################################
# Outputs
###############################################################################

output "server_public_ip" {
  description = "Public IP address of the NAT Gateway Elastic IP."
  value       = aws_eip.nat.public_ip
}

Here is a Terraform template that creates a configurable AWS security group module with managed prefix lists and dynamic ingress/egress rules.
```hcl
###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "enable" {
  description = "Flag to control the creation of the resources of this module."
  type        = bool
  default     = true
}

variable "region" {
  description = "AWS region in which the resources are created."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name used as the base identifier for all resources (forwarded to the labels module)."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment identifier (e.g. dev, staging, prod)."
  type        = string
  default     = "test"
}

variable "managedby" {
  description = "Value used for the 'managedby' label."
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Order of the labels used by the labels module to build the id."
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL forwarded to the labels module."
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "vpc_id" {
  description = "VPC id where the new security group is created. When empty the default VPC of the region is used."
  type        = string
  default     = ""
}

variable "new_sg" {
  description = "When true a new security group is created. When false, existing_sg_id must be provided."
  type        = bool
  default     = true
}

variable "existing_sg_id" {
  description = "Existing security group id to which the rules are attached when new_sg is false."
  type        = string
  default     = ""
}

variable "security_group_description" {
  description = "Description of the created security group."
  type        = string
  default     = ""
}

variable "security_group_tags" {
  description = "Additional tags for the security group."
  type        = map(string)
  default     = {}
}

variable "prefix_list_enabled" {
  description = "When true (and no external prefix_list_ids are given) an EC2 managed prefix list is created."
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "Existing managed prefix list ids. When supplied, no new prefix list is created."
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either \"IPv4\" or \"IPv6\"."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries of the managed prefix list."
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "Entries of the managed prefix list."
  type = list(object({
    cidr        = string
    description = optional(string, null)
  }))
  default = []
}

variable "prefix_list_tags" {
  description = "Additional tags for the managed prefix list."
  type        = map(string)
  default     = {}
}

variable "ingress_rules" {
  description = <<-EOT
    List of ingress rules. Each rule is expanded into one rule per target
    (cidr_ipv4 entry, cidr_ipv6 entry, self reference, source security group id
    or managed prefix list id).
  EOT
  type = list(object({
    description               = optional(string, null)
    ip_protocol               = optional(string, "-1")
    from_port                 = optional(number, null)
    to_port                   = optional(number, null)
    cidr_ipv4                 = optional(list(string), [])
    cidr_ipv6                 = optional(list(string), [])
    self                      = optional(bool, false)
    source_security_group_ids = optional(list(string), [])
    prefix_list_ids           = optional(list(string), [])
    use_default_prefix_list   = optional(bool, false)
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rules, same schema as ingress_rules."
  type = list(object({
    description               = optional(string, null)
    ip_protocol               = optional(string, "-1")
    from_port                 = optional(number, null)
    to_port                   = optional(number, null)
    cidr_ipv4                 = optional(list(string), [])
    cidr_ipv6                 = optional(list(string), [])
    self                      = optional(bool, false)
    source_security_group_ids = optional(list(string), [])
    prefix_list_ids           = optional(list(string), [])
    use_default_prefix_list   = optional(bool, false)
  }))
  default = [
    {
      description = "Allow all outbound traffic"
      ip_protocol = "-1"
      cidr_ipv4   = ["0.0.0.0/0"]
    }
  ]
}

###############################################################################
# Labels module (remote git source)
###############################################################################

module "labels" {
  source = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

###############################################################################
# Data sources
###############################################################################

data "aws_vpc" "default" {
  count   = var.enable && var.new_sg && var.vpc_id == "" ? 1 : 0
  default = true
}

###############################################################################
# Locals
###############################################################################

locals {
  create_sg          = var.enable && var.new_sg
  create_prefix_list = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) == 0

  vpc_id = var.vpc_id != "" ? var.vpc_id : try(data.aws_vpc.default[0].id, null)

  # Security group the rules are attached to: the new one, or the existing one.
  sg_id = local.create_sg ? try(aws_security_group.this[0].id, null) : (var.existing_sg_id != "" ? var.existing_sg_id : null)

  # Default managed prefix list used by the rules when no explicit id is given.
  default_prefix_list_available = local.create_prefix_list || length(var.prefix_list_ids) > 0
  default_prefix_list_id        = local.create_prefix_list ? try(aws_ec2_managed_prefix_list.this[0].id, null) : try(var.prefix_list_ids[0], null)

  # Every rule is expanded into one target per "target type":
  # cidr_ipv4, cidr_ipv6, self, source security group id, managed prefix list id.
  rule_targets = flatten([
    for direction, rules in { ingress = var.ingress_rules, egress = var.egress_rules } : [
      for rule_index, rule in rules : [
        for target_index, target in concat(
          [for cidr in rule.cidr_ipv4 : {
            cidr_ipv4                    = cidr
            cidr_ipv6                    = null
            self                         = false
            referenced_security_group_id = null
            prefix_list_id               = null
          }],
          [for cidr in rule.cidr_ipv6 : {
            cidr_ipv4                    = null
            cidr_ipv6                    = cidr
            self                         = false
            referenced_security_group_id = null
            prefix_list_id               = null
          }],
          rule.self ? [{
            cidr_ipv4                    = null
            cidr_ipv6                    = null
            self                         = true
            referenced_security_group_id = null
            prefix_list_id               = null
          }] : [],
          [for source_sg in rule.source_security_group_ids : {
            cidr_ipv4                    = null
            cidr_ipv6                    = null
            self                         = false
            referenced_security_group_id = source_sg
            prefix_list_id               = null
          }],
          [for prefix_list in(
            length(rule.prefix_list_ids) > 0 ? rule.prefix_list_ids : (
              rule.use_default_prefix_list && local.default_prefix_list_available ? [local.default_prefix_list_id] : []
            )
            ) : {
            cidr_ipv4                    = null
            cidr_ipv6                    = null
            self                         = false
            referenced_security_group_id = null
            prefix_list_id               = prefix_list
          }]
        ) : {
          key                          = format("%s-%d-%d", direction, rule_index, target_index)
          direction                    = direction
          description                  = rule.description
          ip_protocol                  = rule.ip_protocol
          from_port                    = rule.from_port
          to_port                      = rule.to_port
          cidr_ipv4                    = target.cidr_ipv4
          cidr_ipv6                    = target.cidr_ipv6
          self                         = target.self
          referenced_security_group_id = target.referenced_security_group_id
          prefix_list_id               = target.prefix_list_id
        }
      ]
    ]
  ])

  ingress_rule_map = var.enable ? { for target in local.rule_targets : target.key => target if target.direction == "ingress" } : {}
  egress_rule_map  = var.enable ? { for target in local.rule_targets : target.key => target if target.direction == "egress" } : {}
}

###############################################################################
# Security group
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_sg ? 1 : 0

  name        = format("%s-sg", module.labels.id)
  description = var.security_group_description != "" ? var.security_group_description : format("Security group for %s", var.name)
  vpc_id      = local.vpc_id

  tags = merge(
    module.labels.tags,
    { Name = format("%s-sg", module.labels.id) },
    var.security_group_tags
  )

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Managed prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = format("%s-prefix-list", module.labels.id)
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = { for idx, e in var.prefix_list_entries : tostring(idx) => e }

    content {
      cidr        = entry.value.cidr
      description = try(entry.value.description, null)
    }
  }

  tags = merge(
    module.labels.tags,
    { Name = format("%s-prefix-list", module.labels.id) },
    var.prefix_list_tags
  )

  lifecycle {
    precondition {
      condition     = length(var.prefix_list_entries) <= var.prefix_list_max_entries
      error_message = "The number of prefix_list_entries must not exceed prefix_list_max_entries."
    }
  }
}

###############################################################################
# Ingress rules (all four target types)
###############################################################################

resource "aws_vpc_security_group_ingress_rule" "this" {
  for_each = local.ingress_rule_map

  security_group_id = local.sg_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  prefix_list_id               = each.value.prefix_list_id
  referenced_security_group_id = each.value.self ? local.sg_id : each.value.referenced_security_group_id

  tags = module.labels.tags
}

###############################################################################
# Egress rules (all four target types)
###############################################################################

resource "aws_vpc_security_group_egress_rule" "this" {
  for_each = local.egress_rule_map

  security_group_id = local.sg_id
  description       = each.value.description
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.ip_protocol == "-1" ? null : each.value.from_port
  to_port           = each.value.ip_protocol == "-1" ? null : each.value.to_port

  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  prefix_list_id               = each.value.prefix_list_id
  referenced_security_group_id = each.value.self ? local.sg_id : each.value.referenced_security_group_id

  tags = module.labels.tags
}

###############################################################################
# Outputs
###############################################################################

output "label_id" {
  description = "Id produced by the labels module."
  value       = module.labels.id
}

output "tags" {
  description = "Tags produced by the labels module."
  value       = module.labels.tags
}

output "security_group_id" {
  description = "Id of the security group used by the rules (new or existing)."
  value       = local.sg_id
}

output "security_group_arn" {
  description = "ARN of the newly created security group (null when no new security group is created)."
  value       = local.create_sg ? try(aws_security_group.this[0].arn, null) : null
}

output "prefix_list_id" {
  description = "Id of the managed prefix list used as default target by the rules."
  value       = local.default_prefix_list_id
}

output "prefix_list_arn" {
  description = "ARN of the newly created managed prefix list (null when none is created)."
  value       = local.create_prefix_list ? try(aws_ec2_managed_prefix_list.this[0].arn, null) : null
}

output "ingress_rule_ids" {
  description = "Map of created ingress rules, keyed by generated rule key."
  value       = { for k, v in aws_vpc_security_group_ingress_rule.this : k => v.id }
}

output "egress_rule_ids" {
  description = "Map of created egress rules, keyed by generated rule key."
  value       = { for k, v in aws_vpc_security_group_egress_rule.this : k => v.id }
}
```
### Module Mechanics & Rule Expansion

The module keeps things flexible by deciding at runtime whether to create a fresh security group or attach rules to an existing one.

- **Conditional creation** – The `enable` flag gates all resources. When `new_sg` is true, a security group named with a `-sg` suffix is created; otherwise, `existing_sg_id` supplies the target.
- **Prefix list handling** – If `prefix_list_enabled` is true and no external `prefix_list_ids` are provided, an EC2 managed prefix list named with `-prefix-list` is created. You can override the address family, max entries, and entries.
- **Dynamic rule expansion** – Each ingress/egress rule is expanded into one or more target rules: IPv4 CIDR, IPv6 CIDR, self-reference, source security group ID, or managed prefix list ID. Self-referencing rules use the security group's own ID.
- **Tagging** – Standard labels come from the remote labels module and are merged with any additional tags you pass.
---

**Optimization Tip:** You can adjust `var.region`, `var.vpc_id`, and `var.prefix_list_entries` to match your environment. Rule lists accept optional attributes (e.g., `cidr_ipv4`, `source_security_group_ids`, `use_default_prefix_list`) so you can trim the defaults to the exact ingress/egress behavior you need.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables & Provider
###############################################################################

variable "aws_region" {
  description = "AWS region where the security baseline resources are managed."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name used to build IAM role names (defaults to dev)."
  type        = string
  default     = "dev"
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
}

###############################################################################
# Account-wide IAM password policy
###############################################################################

resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = false
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 3
}

###############################################################################
# ECS task role
###############################################################################

resource "aws_iam_role" "ecs_task_role" {
  name        = "ecs-task-role-for-${var.environment}"
  description = "Application (task) role assumed by ECS tasks."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowECSTasksAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "ecs-tasks.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_secrets_manager" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/SecretsManagerReadWrite"
}

resource "aws_iam_role_policy_attachment" "ecs_task_s3_full_access" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy" "ecs_task_ssm_messages" {
  name = "ecs-task-ssm-messages-${var.environment}"
  role = aws_iam_role.ecs_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSSMMessagesChannel"
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# ECS execution role
###############################################################################

resource "aws_iam_role" "ecs_execution_role" {
  name        = "ecs-execution-role-for-${var.environment}"
  description = "Execution role used by ECS agents to pull images, write logs and read secrets."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowECSTasksAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "ecs-tasks.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_task_execution" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_execution_container_service" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role_policy" "ecs_execution_secrets_kms" {
  name = "ecs-execution-secrets-kms-${var.environment}"
  role = aws_iam_role.ecs_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SecretsManagerRead"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecrets"
        ]
        Resource = "*"
      },
      {
        Sid    = "KMSDecryptForSecrets"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# ECS events role (EventBridge -> ECS)
###############################################################################

resource "aws_iam_role" "ecs_events_role" {
  name        = "ecs_events_role-for-${var.environment}"
  description = "Role assumed by EventBridge to launch/orchestrate ECS workloads."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEventBridgeAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_events_task_execution" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_events_container_service" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonEC2ContainerServiceRole"
}

###############################################################################
# Public Lambda role (basic CloudWatch logging)
###############################################################################

resource "aws_iam_role" "public_lambda_role" {
  name        = "public-lambda-role"
  description = "Execution role for internet-facing (public) Lambda functions with basic CloudWatch logging."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowLambdaAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "public_lambda_basic_execution" {
  role       = aws_iam_role.public_lambda_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

###############################################################################
# VPC Lambda role
###############################################################################

resource "aws_iam_role" "vpc_lambda_role" {
  name        = "vpc-lambda-role"
  description = "Execution role for VPC-attached Lambda functions (ENIs, logging, secrets, Lambda invoke)."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowLambdaAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "vpc_lambda_policy" {
  name = "vpc-lambda-policy"
  role = aws_iam_role.vpc_lambda_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogging"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${local.partition}:logs:${local.region}:${local.account_id}:*"
      },
      {
        Sid    = "VPCAccessNetworkInterfaces"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses"
        ]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerRead"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "*"
      },
      {
        Sid    = "InvokeLambdaFunctions"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "lambda:InvokeAsync"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Step Functions state machine role
###############################################################################

resource "aws_iam_role" "step_functions_role" {
  name        = "step-functions-role"
  description = "Execution role for Step Functions state machines (logging, log resource policies, Lambda invoke, alarm describe)."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowStepFunctionsAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "states.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "step_functions_policy" {
  name = "step-functions-policy"
  role = aws_iam_role.step_functions_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LogDelivery"
        Effect = "Allow"
        Action = [
          "logs:CreateLogDelivery",
          "logs:GetLogDelivery",
          "logs:UpdateLogDelivery",
          "logs:DeleteLogDelivery",
          "logs:ListLogDeliveries",
          "logs:DescribeLogGroups",
          "logs:DescribeResourcePolicies"
        ]
        Resource = "*"
      },
      {
        Sid    = "LogResourcePolicies"
        Effect = "Allow"
        Action = [
          "logs:PutResourcePolicy",
          "logs:DeleteResourcePolicy"
        ]
        Resource = "*"
      },
      {
        Sid    = "InvokeLambdaFunctions"
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "lambda:InvokeAsync"
        ]
        Resource = "*"
      },
      {
        Sid    = "DescribeCloudWatchAlarms"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# EventBridge execution role (EventBridge -> Step Functions, current account only)
###############################################################################

resource "aws_iam_role" "eventbridge_execution_role" {
  name        = "eventbridge-execution-role"
  description = "Role assumed by EventBridge to start Step Functions state machines in this account."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEventBridgeAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "eventbridge_execution_policy" {
  name = "eventbridge-execution-policy"
  role = aws_iam_role.eventbridge_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartStateMachinesInCurrentAccount"
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = "arn:${local.partition}:states:${local.region}:${local.account_id}:stateMachine:*"
      }
    ]
  })
}

###############################################################################
# Human governance policy: developers-policy-limited-mfa
###############################################################################

resource "aws_iam_policy" "developers_policy_limited_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Developer access: S3 objects/buckets, MFA-gated Secrets Manager/CloudWatch/ECS read-only, self-service IAM credentials, and explicit MFA enforcement."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ObjectAndBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:ListAllMyBuckets",
          "s3:GetBucketLocation"
        ]
        Resource = [
          "arn:${local.partition}:s3:::*",
          "arn:${local.partition}:s3:::*/*"
        ]
      },
      {
        Sid    = "SecretsManagerReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecrets",
          "secretsmanager:ListSecretVersionIds"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "CloudWatchReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:DescribeAlarmsForMetric",
          "cloudwatch:DescribeAlarmHistory",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "cloudwatch:ListTagsForResource"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "ECSReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "ecs:ListClusters",
          "ecs:ListServices",
          "ecs:ListTasks",
          "ecs:ListContainerInstances",
          "ecs:ListTaskDefinitions",
          "ecs:DescribeClusters",
          "ecs:DescribeServices",
          "ecs:DescribeTasks",
          "ecs:DescribeTaskDefinition",
          "ecs:DescribeContainerInstances"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceManageOwnCredentials"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:UpdateAccessKey",
          "iam:UploadSSHPublicKey",
          "iam:DeleteSSHPublicKey",
          "iam:UpdateSSHPublicKey",
          "iam:GetSSHPublicKey"
        ]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:user/${aws:username}",
          "arn:${local.partition}:iam::${local.account_id}:mfa/${aws:username}",
          "arn:${local.partition}:iam::${local.account_id}:ssh-public-key/${aws:username}"
        ]
      },
      {
        Sid    = "SelfServiceListOwnCredentials"
        Effect = "Allow"
        Action = [
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:ListAccessKeys",
          "iam:ListSSHPublicKeys"
        ]
        Resource = "*"
      },
      {
        Sid    = "DenyAllExceptSelfServiceWithoutMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:UpdateAccessKey",
          "iam:ListAccessKeys",
          "iam:UploadSSHPublicKey",
          "iam:DeleteSSHPublicKey",
          "iam:UpdateSSHPublicKey",
          "iam:GetSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "sts:GetSessionToken",
          "sts:GetCallerIdentity"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

###############################################################################
# Human governance policy: billing-policy-limited-mfa
###############################################################################

resource "aws_iam_policy" "billing_policy_limited_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "MFA-gated billing, budgets, Cost Explorer, payments and tax visibility plus self-service MFA/password management."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingBudgetsCostExplorerPaymentsTaxWithMFA"
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewAccount",
          "aws-portal:ViewUsage",
          "aws-portal:ViewPaymentMethods",
          "budgets:ViewBudget",
          "budgets:DescribeBudget",
          "budgets:DescribeBudgets",
          "budgets:DescribeBudgetActionsForAccount",
          "budgets:DescribeBudgetActionsForBudget",
          "budgets:DescribeBudgetPerformanceHistory",
          "budgets:ListTagsForResource",
          "ce:GetCostAndUsage",
          "ce:GetCostForecast",
          "ce:GetUsageForecast",
          "ce:GetDimensionValues",
          "ce:GetTags",
          "ce:GetReservationUtilization",
          "ce:GetReservationCoverage",
          "ce:GetSavingsPlansUtilization",
          "ce:GetSavingsPlansCoverage",
          "ce:DescribeCostCategoryDefinition",
          "ce:ListCostCategoryDefinitions",
          "ce:ListTagsForResource",
          "payments:GetPaymentInstrument",
          "payments:ListPaymentInstruments",
          "payments:GetPaymentPreferences",
          "payments:ListPaymentPreferences",
          "tax:GetTaxRegistration",
          "tax:ListTaxRegistrations",
          "tax:GetTaxExemptionTypes",
          "tax:ListTaxExemptions",
          "tax:GetTaxInheritance",
          "tax:ListTaxInheritance"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceMFAManagement"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:GetUser"
        ]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:user/${aws:username}",
          "arn:${local.partition}:iam::${local.account_id}:mfa/${aws:username}"
        ]
      },
      {
        Sid    = "SelfServicePasswordAndListCredentials"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Outputs
###############################################################################

output "password_policy_minimum_length" {
  description = "Minimum length enforced by the account password policy."
  value       = aws_iam_account_password_policy.strict.minimum_password_length
}

output "ecs_task_role_arn" {
  description = "ARN of the ECS task role."
  value       = aws_iam_role.ecs_task_role.arn
}

output "ecs_execution_role_arn" {
  description = "ARN of the ECS execution role."
  value       = aws_iam_role.ecs_execution_role.arn
}

output "ecs_events_role_arn" {
  description = "ARN of the EventBridge-assumable ECS events role."
  value       = aws_iam_role.ecs_events_role.arn
}

output "public_lambda_role_arn" {
  description = "ARN of the public Lambda execution role."
  value       = aws_iam_role.public_lambda_role.arn
}

output "vpc_lambda_role_arn" {
  description = "ARN of the VPC Lambda execution role."
  value       = aws_iam_role.vpc_lambda_role.arn
}

output "step_functions_role_arn" {
  description = "ARN of the Step Functions state machine execution role."
  value       = aws_iam_role.step_functions_role.arn
}

output "eventbridge_execution_role_arn" {
  description = "ARN of the EventBridge execution role used to start state machines."
  value       = aws_iam_role.eventbridge_execution_role.arn
}

output "developers_policy_arn" {
  description = "ARN of the developers-policy-limited-mfa managed policy."
  value       = aws_iam_policy.developers_policy_limited_mfa.arn
}

output "billing_policy_arn" {
  description = "ARN of the billing-policy-limited-mfa managed policy."
  value       = aws_iam_policy.billing_policy_limited_mfa.arn
}

## Description

This Terraform stack implements a data-driven AWS CI/CD orchestration framework. A single `var.config` YAML document (or the inline `var.config_content`) drives everything: it is parsed with `yamldecode()` and normalised into maps/lists that are consumed by `for_each` and nested `dynamic` blocks.

What gets provisioned:

* **S3** — an artifact bucket (versioned, SSE‑AES256, public access blocked) and a CodeBuild cache bucket. Names are derived from the config or defaulted to `<name_prefix>-{artifacts,cache}-<account>-<region>`.
* **IAM** — an optional default CodePipeline service role at path `/terraforest/` granting CodeCommit, CodeBuild, CodeStar Connections, ECR, S3 artifact-store, Lambda invoke, EventBridge and scoped `iam:PassRole`. Additional roles are created for each CodeBuild project, each Lambda action (basic execution + `codepipeline:PutJob{Success,Failure}Result`) and one **custom EventBridge role per pipeline named `terrabits-<pipeline-name>`** that only allows `codepipeline:StartPipelineExecution` on that pipeline's ARN.
* **CodeStar Connections** — one connection per entry, supporting `Bitbucket`, `GitHub` and `GitHubEnterpriseServer`.
* **CodePipeline** — every pipeline is built from normalised locals, so it has a dynamic `Source` stage (CodeCommit, S3, ECR or CodeStar `CodeStarSourceConnection`) followed by arbitrary dynamic stages/actions: manual **Approval**, **CodeBuild** and Lambda **Invoke** actions. CodeBuild projects and Lambda functions (with auto-generated placeholder zip via `archive_file` when no artifact is supplied) are created as reusable action backends.
* **EventBridge** — one rule + target per pipeline event, supporting CodeCommit branch changes, CodeCommit tag changes, cron/rate schedules, or arbitrary custom event patterns. Each target assumes the pipeline's `terrabits-*` role to start the pipeline.

Variables all carry defaults, the provider is pinned to a real region, and every referenced resource/variable is declared, so the configuration plans and applies as-is (an empty/absent YAML simply yields the buckets and IAM scaffolding).

```iac_template
###############################################################################
# Terraform / Provider
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region used by the provider and for globally unique bucket naming."
  type        = string
  default     = "us-east-1"
}

variable "config" {
  description = "Path (relative to the working directory) of the YAML file describing the CI/CD framework."
  type        = string
  default     = "pipeline.yaml"
}

variable "config_content" {
  description = "Inline YAML configuration. When non empty it takes precedence over the file referenced by var.config."
  type        = string
  default     = ""
}

variable "name_prefix" {
  description = "Prefix applied to generated resource names (buckets, roles, connections)."
  type        = string
  default     = "terraforest"
}

variable "create_default_codepipeline_role" {
  description = "Create the default CodePipeline service role under the /terraforest/ IAM path."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Project   = "terraforest"
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals - YAML driven model
###############################################################################

locals {
  cfg_raw = (
    var.config_content != "" ?
    var.config_content :
    (fileexists(var.config) ? file(var.config) : "{}")
  )

  cfg = yamldecode(local.cfg_raw)

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  name_prefix = coalesce(try(local.cfg.name_prefix, null), var.name_prefix)

  tags = merge(var.tags, {
    "terraforest:name_prefix" = local.name_prefix
  })

  artifact_bucket_name = coalesce(
    try(local.cfg.artifact_bucket_name, null),
    "${local.name_prefix}-artifacts-${local.account_id}-${var.region}"
  )

  cache_bucket_name = coalesce(
    try(local.cfg.cache_bucket_name, null),
    "${local.name_prefix}-cache-${local.account_id}-${var.region}"
  )

  create_default_role = try(local.cfg.create_default_codepipeline_role, var.create_default_codepipeline_role)

  default_codepipeline_role_arn = try(aws_iam_role.codepipeline[0].arn, null)

  # ------------------------------------------------------------------ model --
  pipelines = {
    for p in try(local.cfg.pipelines, []) : p.name => p
  }

  connections = {
    for c in try(local.cfg.codestar_connections, []) : c.name => c
  }

  projects = {
    for p in try(local.cfg.codebuild_projects, []) : p.name => p
  }

  lambdas = {
    for f in try(local.cfg.lambda_functions, []) : f.name => f
  }

  default_lambda_code = <<-EOT
    import json


    def handler(event, context):
        print(json.dumps(event))
        return {"statusCode": 200, "body": json.dumps({"ok": True})}
  EOT

  # ---------------------------------------------------------------- sources --
  source_types = {
    for k, p in local.pipelines : k => lower(tostring(try(p.source.type, "codecommit")))
  }

  source_providers = {
    for k, p in local.pipelines : k => (
      local.source_types[k] == "s3" ? "S3" :
      local.source_types[k] == "ecr" ? "ECR" :
      local.source_types[k] == "codestar" ? "CodeStarSourceConnection" :
      "CodeCommit"
    )
  }

  source_actions = {
    for k, p in local.pipelines : k => {
      name             = tostring(try(p.source.action_name, "Source"))
      category         = "Source"
      owner            = "AWS"
      provider         = local.source_providers[k]
      version          = "1"
      run_order        = 1
      input_artifacts  = []
      output_artifacts = [tostring(try(p.source.output_artifact, "source_output"))]
      configuration = (
        local.source_types[k] == "s3" ? tomap({
          S3Bucket             = tostring(try(p.source.bucket, ""))
          S3ObjectKey          = tostring(try(p.source.object_key, ""))
          PollForSourceChanges = "false"
          }) :
        local.source_types[k] == "ecr" ? tomap({
          RepositoryName = tostring(try(p.source.ecr_repository, ""))
          ImageTag       = tostring(try(p.source.image_tag, "latest"))
          }) :
        local.source_types[k] == "codestar" ? tomap({
          ConnectionArn        = tostring(try(aws_codestarconnections_connection.this[p.source.connection].arn, ""))
          FullRepositoryId     = tostring(try(p.source.full_repository_id, ""))
          BranchName           = tostring(try(p.source.branch, "main"))
          OutputArtifactFormat = tostring(try(p.source.output_artifact_format, "CODE_ZIP"))
          }) :
        tomap({
          RepositoryName = tostring(try(p.source.repository_name, ""))
          BranchName     = tostring(try(p.source.branch, "main"))
        })
      )
    }
  }

  # ----------------------------------------------------------------- stages --
  pipeline_stages = {
    for k, p in local.pipelines : k => concat(
      [
        {
          name    = tostring(try(p.source.stage_name, "Source"))
          actions = [local.source_actions[k]]
        }
      ],
      [
        for s in try(p.stages, []) : {
          name = tostring(s.name)
          actions = [
            for a in try(s.actions, []) : {
              name             = tostring(a.name)
              category         = try(a.type, "codebuild") == "approval" ? "Approval" : (try(a.type, "codebuild") == "lambda" ? "Invoke" : "Build")
              owner            = "AWS"
              provider         = try(a.type, "codebuild") == "approval" ? "Manual" : (try(a.type, "codebuild") == "lambda" ? "Lambda" : "CodeBuild")
              version          = "1"
              run_order        = tonumber(try(a.run_order, 1))
              input_artifacts  = tolist(try(a.input_artifacts, []))
              output_artifacts = tolist(try(a.output_artifacts, []))
              configuration = (
                try(a.type, "codebuild") == "approval" ? tomap({
                  CustomData = tostring(try(a.custom_data, "Manual approval required"))
                  }) :
                try(a.type, "codebuild") == "lambda" ? tomap({
                  FunctionName   = tostring(try(a.function, ""))
                  UserParameters = tostring(try(a.user_parameters, ""))
                  }) :
                tomap({
                  ProjectName = tostring(try(a.project, ""))
                })
              )
            }
          ]
        }
      ]
    )
  }

  # ----------------------------------------------------------------- events --
  events_list = flatten([
    for k, p in local.pipelines : [
      for e in try(p.events, []) : {
        key           = "${k}-${e.name}"
        name          = tostring(e.name)
        pipeline_name = k
        type          = lower(tostring(try(e.type, "codecommit_branch")))
        description   = tostring(try(e.description, "Trigger ${k} pipeline"))
        repository    = try(e.repository, try(p.source.repository_name, null))
        branch        = tostring(try(e.branch, try(p.source.branch, "main")))
        tags          = tolist(try(e.tags, ["*"]))
        schedule      = tostring(try(e.schedule, "rate(5 minutes)"))
        pattern       = try(e.pattern, {})
      }
    ]
  ])

  events = {
    for e in local.events_list : e.key => e
  }

  event_rules = {
    for k, e in local.events : k => {
      name                = "${e.pipeline_name}-${e.name}"
      description         = e.description
      schedule_expression = e.type == "schedule" ? e.schedule : null
      event_pattern = (
        e.type == "codecommit_branch" ? jsonencode({
          source      = ["aws.codecommit"]
          detail-type = ["CodeCommit Repository State Change"]
          resources   = ["arn:${local.partition}:codecommit:${var.region}:${local.account_id}:${coalesce(e.repository, "*")}"]
          detail = {
            event         = ["referenceCreated", "referenceUpdated"]
            referenceType = ["branch"]
            referenceName = [e.branch]
          }
          }) :
        e.type == "codecommit_tag" ? jsonencode({
          source      = ["aws.codecommit"]
          detail-type = ["CodeCommit Repository State Change"]
          resources   = ["arn:${local.partition}:codecommit:${var.region}:${local.account_id}:${coalesce(e.repository, "*")}"]
          detail = {
            event         = ["referenceCreated", "referenceUpdated"]
            referenceType = ["tag"]
            referenceName = e.tags
          }
          }) :
        e.type == "pattern" ? jsonencode(e.pattern) :
        null
      )
    }
  }
}

###############################################################################
# S3 - artifact store and CodeBuild cache
###############################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket        = local.artifact_bucket_name
  force_destroy = true
  tags          = local.tags
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "cache" {
  bucket        = local.cache_bucket_name
  force_destroy = true
  tags          = local.tags
}

resource "aws_s3_bucket_versioning" "cache" {
  bucket = aws_s3_bucket.cache.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  bucket = aws_s3_bucket.cache.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "cache" {
  bucket                  = aws_s3_bucket.cache.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# CodeStar connections (Bitbucket / GitHub / GitHub Enterprise Server)
###############################################################################

resource "aws_codestarconnections_connection" "this" {
  for_each = local.connections

  name          = "${local.name_prefix}-${each.key}"
  provider_type = tostring(try(each.value.provider_type, "GitHub"))
  tags          = local.tags
}

###############################################################################
# IAM - default CodePipeline service role (/terraforest/)
###############################################################################

data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codepipeline" {
  count = local.create_default_role ? 1 : 0

  name = "${local.name_prefix}-codepipeline"
  path = "/terraforest/"

  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json
  tags               = local.tags
}

data "aws_iam_policy_document" "codepipeline" {
  count = local.create_default_role ? 1 : 0

  statement {
    sid    = "CodeCommit"
    effect = "Allow"
    actions = [
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:ListBranches",
      "codecommit:ListRepositories",
      "codecommit:GitPull",
      "codecommit:UploadArchive",
      "codecommit:CancelUploadArchive",
      "codecommit:GetUploadArchiveStatus",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeBuild"
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:BatchGetBuildBatches",
      "codebuild:StartBuild",
      "codebuild:StartBuildBatch",
      "codebuild:StopBuild",
      "codebuild:StopBuildBatch",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "CodeStarConnections"
    effect    = "Allow"
    actions   = ["codestar-connections:UseConnection"]
    resources = ["*"]
  }

  statement {
    sid    = "EcrSource"
    effect = "Allow"
    actions = [
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:ListImages",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:GetAuthorizationToken",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "LambdaInvoke"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction", "lambda:ListFunctions"]
    resources = ["*"]
  }

  statement {
    sid    = "ArtifactAndCacheStore"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
      aws_s3_bucket.cache.arn,
      "${aws_s3_bucket.cache.arn}/*",
    ]
  }

  statement {
    sid       = "PassRoleToCodeBuild"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["codebuild.amazonaws.com"]
    }
  }

  statement {
    sid    = "Events"
    effect = "Allow"
    actions = [
      "events:PutEvents",
      "events:PutRule",
      "events:PutTargets",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codepipeline" {
  count = local.create_default_role ? 1 : 0

  name   = "${local.name_prefix}-codepipeline"
  role   = aws_iam_role.codepipeline[0].id
  policy = data.aws_iam_policy_document.codepipeline[0].json
}

###############################################################################
# IAM - CodeBuild execution roles
###############################################################################

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild" {
  for_each = local.projects

  name = "${local.name_prefix}-${each.key}-codebuild"
  path = "/terraforest/"

  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
  tags               = local.tags
}

data "aws_iam_policy_document" "codebuild" {
  for_each = local.projects

  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      "arn:${local.partition}:logs:${var.region}:${local.account_id}:log-group:/aws/codebuild/*",
      "arn:${local.partition}:logs:${var.region}:${local.account_id}:log-group:/aws/codebuild/*:*",
    ]
  }

  statement {
    sid    = "ArtifactAndCacheBuckets"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
      aws_s3_bucket.cache.arn,
      "${aws_s3_bucket.cache.arn}/*",
    ]
  }

  statement {
    sid    = "Ecr"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeCommit"
    effect = "Allow"
    actions = [
      "codecommit:GitPull",
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:ListRepositories",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "CodeStarConnections"
    effect    = "Allow"
    actions   = ["codestar-connections:UseConnection"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codebuild" {
  for_each = local.projects

  name   = "${local.name_prefix}-${each.key}-codebuild"
  role   = aws_iam_role.codebuild[each.key].id
  policy = data.aws_iam_policy_document.codebuild[each.key].json
}

###############################################################################
# CodeBuild projects (action backends)
###############################################################################

resource "aws_codebuild_project" "this" {
  for_each = local.projects

  name           = each.key
  description    = tostring(try(each.value.description, "Managed by Terraform (terraforest)"))
  service_role   = aws_iam_role.codebuild[each.key].arn
  build_timeout  = tonumber(try(each.value.build_timeout, 60))
  queued_timeout = tonumber(try(each.value.queued_timeout, 480))
  tags           = local.tags

  artifacts {
    type = tostring(try(each.value.artifacts_type, "CODEPIPELINE"))
  }

  environment {
    compute_type                = tostring(try(each.value.compute_type, "BUILD_GENERAL1_SMALL"))
    image                       = tostring(try(each.value.image, "aws/codebuild/standard:7.0"))
    type                        = tostring(try(each.value.environment_type, "LINUX_CONTAINER"))
    image_pull_credentials_type = tostring(try(each.value.image_pull_credentials_type, "CODEBUILD"))
    privileged_mode             = try(each.value.privileged_mode, false)

    dynamic "environment_variable" {
      for_each = try(each.value.environment_variables, [])

      content {
        name  = environment_variable.value.name
        value = tostring(try(environment_variable.value.value, ""))
        type  = tostring(try(environment_variable.value.type, "PLAINTEXT"))
      }
    }
  }

  source {
    type      = tostring(try(each.value.source_type, "CODEPIPELINE"))
    buildspec = try(each.value.buildspec, null)
  }

  cache {
    type     = "S3"
    location = "${aws_s3_bucket.cache.bucket}/${each.key}"
  }
}

###############################################################################
# IAM + Lambda functions (invoke action backends)
###############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda" {
  for_each = local.lambdas

  name = "${local.name_prefix}-${each.key}-lambda"
  path = "/terraforest/"

  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic" {
  for_each = local.lambdas

  role       = aws_iam_role.lambda[each.key].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_pipeline" {
  for_each = local.lambdas

  name = "${local.name_prefix}-${each.key}-codepipeline-results"
  role = aws_iam_role.lambda[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "codepipeline:PutJobSuccessResult",
          "codepipeline:PutJobFailureResult",
        ]
        Resource = "*"
      }
    ]
  })
}

data "archive_file" "lambda" {
  for_each = {
    for k, f in local.lambdas : k => f
    if try(f.filename, null) == null && try(f.s3_bucket, null) == null
  }

  type        = "zip"
  output_path = "${path.module}/${each.key}-lambda.zip"

  source {
    content  = tostring(try(each.value.inline_code, local.default_lambda_code))
    filename = tostring(try(each.value.inline_filename, "index.py"))
  }
}

resource "aws_lambda_function" "this" {
  for_each = local.lambdas

  function_name = each.key
  description   = tostring(try(each.value.description, "Managed by Terraform (terraforest)"))
  role          = aws_iam_role.lambda[each.key].arn
  runtime       = tostring(try(each.value.runtime, "python3.12"))
  handler       = tostring(try(each.value.handler, "index.handler"))
  timeout       = tonumber(try(each.value.timeout, 60))
  memory_size   = tonumber(try(each.value.memory_size, 128))

  filename = try(each.value.filename, try(data.archive_file.lambda[each.key].output_path, null))

  source_code_hash = (
    try(each.value.filename, null) != null ?
    filebase64sha256(each.value.filename) :
    try(data.archive_file.lambda[each.key].output_base64sha256, null)
  )

  s3_bucket = try(each.value.s3_bucket, null)
  s3_key    = try(each.value.s3_key, null)

  dynamic "environment" {
    for_each = length(try(each.value.environment, {})) > 0 ? [1] : []

    content {
      variables = { for k, v in each.value.environment : k => tostring(v) }
    }
  }

  tags = local.tags
}

###############################################################################
# CodePipeline pipelines (dynamic stages / actions)
###############################################################################

resource "aws_codepipeline" "this" {
  for_each = local.pipelines

  name          = each.key
  role_arn      = try(each.value.role_arn, local.default_codepipeline_role_arn)
  pipeline_type = tostring(try(each.value.pipeline_type, "V1"))
  tags          = local.tags

  artifact_store {
    location = coalesce(try(each.value.artifact_bucket_name, null), aws_s3_bucket.artifacts.bucket)
    type     = "S3"
  }

  dynamic "stage" {
    for_each = local.pipeline_stages[each.key]

    content {
      name = stage.value.name

      dynamic "action" {
        for_each = stage.value.actions

        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          run_order        = action.value.run_order
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          configuration    = action.value.configuration
        }
      }
    }
  }
}

###############################################################################
# IAM - custom EventBridge roles ("terrabits-<pipeline name>")
###############################################################################

data "aws_iam_policy_document" "eventbridge_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eventbridge" {
  for_each = local.pipelines

  name = "terrabits-${each.key}"
  path = "/terraforest/"

  assume_role_policy = data.aws_iam_policy_document.eventbridge_assume_role.json
  tags               = local.tags
}

resource "aws_iam_role_policy" "eventbridge" {
  for_each = local.pipelines

  name = "terrabits-${each.key}-start-pipeline-execution"
  role = aws_iam_role.eventbridge[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["codepipeline:StartPipelineExecution"]
        Resource = [aws_codepipeline.this[each.key].arn]
      }
    ]
  })
}

###############################################################################
# EventBridge rules and targets
###############################################################################

resource "aws_cloudwatch_event_rule" "this" {
  for_each = local.event_rules

  name                = each.value.name
  description         = each.value.description
  schedule_expression = each.value.schedule_expression
  event_pattern       = each.value.event_pattern
  tags                = local.tags
}

resource "aws_cloudwatch_event_target" "this" {
  for_each = local.events

  rule      = aws_cloudwatch_event_rule.this[each.key].name
  target_id = "codepipeline-${each.value.pipeline_name}"
  arn       = aws_codepipeline.this[each.value.pipeline_name].arn
  role_arn  = aws_iam_role.eventbridge[each.value.pipeline_name].arn
}

###############################################################################
# Outputs
###############################################################################

output "artifact_bucket" {
  description = "S3 bucket used as CodePipeline artifact store."
  value       = aws_s3_bucket.artifacts.bucket
}

output "cache_bucket" {
  description = "S3 bucket used as CodeBuild cache."
  value       = aws_s3_bucket.cache.bucket
}

output "codepipeline_role_arn" {
  description = "Default CodePipeline service role ARN (null when not created)."
  value       = try(aws_iam_role.codepipeline[0].arn, null)
}

output "codestar_connection_arns" {
  description = "Map of CodeStar connection name to ARN."
  value       = { for k, v in aws_codestarconnections_connection.this : k => v.arn }
}

output "codebuild_project_arns" {
  description = "Map of CodeBuild project name to ARN."
  value       = { for k, v in aws_codebuild_project.this : k => v.arn }
}

output "lambda_function_arns" {
  description = "Map of Lambda function name to ARN."
  value       = { for k, v in aws_lambda_function.this : k => v.arn }
}

output "pipeline_arns" {
  description = "Map of pipeline name to ARN."
  value       = { for k, v in aws_codepipeline.this : k => v.arn }
}

output "eventbridge_role_arns" {
  description = "Map of pipeline name to its terrabits-* EventBridge role ARN."
  value       = { for k, v in aws_iam_role.eventbridge : k => v.arn }
}

output "eventbridge_rule_arns" {
  description = "Map of event key to EventBridge rule ARN."
  value       = { for k, v in aws_cloudwatch_event_rule.this : k => v.arn }
}
```

## Description

This Terraform program provisions a self-contained, hardened SFTP file-exchange stack on AWS:

**Storage layer (Amazon EFS)**
- `aws_efs_file_system` — always encrypted, `throughput_mode = "bursting"`, configurable `performance_mode` (default `generalPurpose`), and optional customer-managed KMS key via `efs_kms_key_arn` (falls back to the AWS-managed `aws/elasticfilesystem` key).
- `aws_efs_mount_target` — created only when both `vpc_id` and `subnet_ids` are provided (empty defaults ⇒ none created), each attached to the dedicated EFS security group.
- `aws_efs_access_point` — one per entry in `sftp_users` (root directory created with the user's POSIX UID/GID ownership and `0755` permissions) plus one per entry in `additional_access_points` for shared storage paths.

**Networking**
- Optional VPC-only security groups (`aws_security_group` + `aws_security_group_rule`) for the EFS NFS interface (2049 from the SFTP SG) and the SFTP endpoint (22 from `sftp_allowed_cidrs`, plus 2049 egress to EFS).
- Optional Elastic IPs (one per subnet) allocated only when `is_public = true` so a VPC endpoint can be reachable from the internet.

**AWS Transfer Family**
- `aws_transfer_server` with `domain = "EFS"`, `identity_provider_type = "SERVICE_MANAGED"`, `security_policy_name = "TransferSecurityPolicy-2023-05"`, `endpoint_type = "VPC"` (with `endpoint_details`) when a VPC/subnets are supplied, otherwise `"PUBLIC"`; logging role attached only when `logging_enabled = true`.
- `aws_transfer_user` + `aws_transfer_ssh_key` per entry in `sftp_users`, using the per-user EFS access point ARN as the home directory when `restricted = true`, for_each-safe SSH key fan-out.

**IAM**
- Auto-generated user role named `<sftp_server_name>-role` (created only if at least one user has no `role_arn`) granting EFS client mount/root/write + describe permissions scoped to the file system and access points; otherwise the caller-supplied `role_arn` is used.
- Conditional CloudWatch logging role + inline policy trusting `transfer.amazonaws.com`.

Observability and wiring are exposed through outputs (server ID/endpoint, EFS IDs, access point ARNs, generated role ARN).

```iac_template
###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which all resources are created."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name prefix used to tag/name the supporting resources."
  type        = string
  default     = "sftp-efs"
}

variable "sftp_server_name" {
  description = "Name of the AWS Transfer Family SFTP server. Also drives the generated IAM role name (<sftp_server_name>-role)."
  type        = string
  default     = "transfer-sftp"
}

variable "tags" {
  description = "Additional tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "vpc_id" {
  description = "VPC ID used for the EFS mount targets and the SFTP VPC endpoint. Empty means do not create VPC-based resources (no mount targets, PUBLIC endpoint)."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "Subnet IDs used for the EFS mount targets and the SFTP VPC endpoint. Empty means no mount targets are created."
  type        = list(string)
  default     = []
}

variable "is_public" {
  description = "When true (and a VPC endpoint is used) Elastic IPs are allocated so the VPC-hosted SFTP endpoint is reachable from the internet."
  type        = bool
  default     = false
}

variable "sftp_allowed_cidrs" {
  description = "CIDR blocks allowed to reach the SFTP endpoint on port 22 (only relevant for the VPC endpoint)."
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "efs_performance_mode" {
  description = "EFS performance mode: generalPurpose or maxIO."
  type        = string
  default     = "generalPurpose"

  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.efs_performance_mode)
    error_message = "efs_performance_mode must be either \"generalPurpose\" or \"maxIO\"."
  }
}

variable "efs_kms_key_arn" {
  description = "Optional customer-managed KMS key ARN used to encrypt the EFS file system. Empty string uses the AWS-managed key for Amazon EFS."
  type        = string
  default     = ""
}

variable "logging_enabled" {
  description = "When true, an IAM role/policy enabling CloudWatch logging is created and attached to the Transfer Family server."
  type        = bool
  default     = false
}

variable "sftp_users" {
  description = <<-EOT
    Map of SFTP users keyed by user name. Each user gets a dedicated EFS access point
    (created with the supplied POSIX ownership and 0755 permissions), one or more SSH
    public keys, and a Transfer Family user entry.
      - home_directory : path inside the EFS file system, e.g. "/myuser".
      - posix_uid/gid  : POSIX identity used for the access point + created directory.
      - public_keys    : list of OpenSSH formatted public keys.
      - restricted     : when true, the user's home directory is the EFS access point ARN
                         (confined to that directory). When false, the user's home
                         directory is the EFS file system root "/".
      - role_arn       : optional pre-existing IAM role ARN for the user. When omitted,
                         the automatically generated "<sftp_server_name>-role" is used.
  EOT
  type = map(object({
    home_directory = string
    posix_uid      = number
    posix_gid      = number
    public_keys    = optional(list(string), [])
    restricted     = optional(bool, true)
    role_arn       = optional(string, null)
    secondary_gids = optional(list(number), [])
    tags           = optional(map(string), {})
  }))
  default = {}
}

variable "additional_access_points" {
  description = <<-EOT
    Map of extra EFS access points keyed by a logical name, used for general storage paths.
      - path        : path on the EFS file system, e.g. "/shared".
      - posix_uid/gid : POSIX identity for the access point and created directory.
      - permissions : octal permissions for the created directory (default "0755").
  EOT
  type = map(object({
    path           = string
    posix_uid      = number
    posix_gid      = number
    permissions    = optional(string, "0755")
    secondary_gids = optional(list(number), [])
  }))
  default = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  # VPC-based resources (mount targets, security groups, VPC endpoint, EIPs)
  vpc_enabled        = var.vpc_id != "" && length(var.subnet_ids) > 0
  public_vpc_endpoint = local.vpc_enabled && var.is_public

  # Auto-generated IAM role is only needed when at least one user does not bring a role ARN
  create_user_role = anytrue([for u in values(var.sftp_users) : u.role_arn == null])

  # Safe reference: try() prevents an invalid-index error when the role is not created
  generated_user_role_arn = try(aws_iam_role.sftp_user[0].arn, null)

  # EFS resources the user role is allowed to use
  efs_resource_arns = concat(
    [aws_efs_file_system.this.arn],
    [for ap in aws_efs_access_point.users : ap.arn],
    [for ap in aws_efs_access_point.additional : ap.arn],
  )

  # Flatten per-user SSH public keys into a single map for aws_transfer_ssh_key
  user_ssh_keys = merge([
    for user_name, user in var.sftp_users : {
      for idx, pub_key in user.public_keys :
      "${user_name}-${idx}" => {
        user_name  = user_name
        public_key = pub_key
      }
    }
  ]...)

  common_tags = merge(var.tags, { ManagedBy = "terraform" })
}

###############################################################################
# Amazon EFS file system
###############################################################################

resource "aws_efs_file_system" "this" {
  creation_token   = var.name
  encrypted        = true
  kms_key_id       = var.efs_kms_key_arn != "" ? var.efs_kms_key_arn : null
  performance_mode = var.efs_performance_mode
  throughput_mode  = "bursting"

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  tags = merge(local.common_tags, { Name = var.name })
}

###############################################################################
# Security groups (only when a VPC + subnets are supplied)
###############################################################################

resource "aws_security_group" "efs" {
  count = local.vpc_enabled ? 1 : 0

  name_prefix = "${var.name}-efs-"
  description = "Mount target / NFS access for the EFS file system backing the SFTP server"
  vpc_id      = var.vpc_id

  tags = merge(local.common_tags, { Name = "${var.name}-efs-sg" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "sftp" {
  count = local.vpc_enabled ? 1 : 0

  name_prefix = "${var.name}-sftp-"
  description = "SFTP endpoint access for the AWS Transfer Family server"
  vpc_id      = var.vpc_id

  tags = merge(local.common_tags, { Name = "${var.name}-sftp-sg" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "efs_nfs_ingress" {
  count = local.vpc_enabled ? 1 : 0

  type                     = "ingress"
  description              = "NFS from the SFTP endpoint security group"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  security_group_id        = aws_security_group.efs[0].id
  source_security_group_id = aws_security_group.sftp[0].id
}

resource "aws_security_group_rule" "sftp_nfs_egress" {
  count = local.vpc_enabled ? 1 : 0

  type                     = "egress"
  description              = "NFS to the EFS mount targets"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  security_group_id        = aws_security_group.sftp[0].id
  source_security_group_id = aws_security_group.efs[0].id
}

resource "aws_security_group_rule" "sftp_ingress" {
  count = local.vpc_enabled ? 1 : 0

  type              = "ingress"
  description       = "SFTP access"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = var.sftp_allowed_cidrs
  security_group_id = aws_security_group.sftp[0].id
}

###############################################################################
# EFS mount targets (only when VPC + subnets are supplied)
###############################################################################

resource "aws_efs_mount_target" "this" {
  for_each = local.vpc_enabled ? { for idx, subnet_id in var.subnet_ids : "mt-${idx}" => subnet_id } : {}

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = each.value
  security_groups = [aws_security_group.efs[0].id]
}

###############################################################################
# Elastic IPs for a publicly reachable VPC endpoint
###############################################################################

resource "aws_eip" "sftp" {
  count = local.public_vpc_endpoint ? length(var.subnet_ids) : 0

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${var.name}-sftp-eip-${count.index}" })
}

###############################################################################
# EFS access points
###############################################################################

resource "aws_efs_access_point" "users" {
  for_each = var.sftp_users

  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid            = each.value.posix_uid
    gid            = each.value.posix_gid
    secondary_gids = length(each.value.secondary_gids) > 0 ? each.value.secondary_gids : null
  }

  root_directory {
    path = each.value.home_directory

    creation_info {
      owner_uid   = each.value.posix_uid
      owner_gid   = each.value.posix_gid
      permissions = "0755"
    }
  }

  tags = merge(local.common_tags, { Name = "${var.name}-ap-${each.key}" })
}

resource "aws_efs_access_point" "additional" {
  for_each = var.additional_access_points

  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid            = each.value.posix_uid
    gid            = each.value.posix_gid
    secondary_gids = length(each.value.secondary_gids) > 0 ? each.value.secondary_gids : null
  }

  root_directory {
    path = each.value.path

    creation_info {
      owner_uid   = each.value.posix_uid
      owner_gid   = each.value.posix_gid
      permissions = each.value.permissions
    }
  }

  tags = merge(local.common_tags, { Name = "${var.name}-ap-${each.key}" })
}

###############################################################################
# IAM - SFTP user role (auto-generated when no role ARN is supplied)
###############################################################################

resource "aws_iam_role" "sftp_user" {
  count = local.create_user_role ? 1 : 0

  name = "${var.sftp_server_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "TransferAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.sftp_server_name}-role" })
}

resource "aws_iam_role_policy" "sftp_user" {
  count = local.create_user_role ? 1 : 0

  name = "${var.sftp_server_name}-efs-policy"
  role = aws_iam_role.sftp_user[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EFSClientAccess"
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess",
          "elasticfilesystem:DescribeMountTargets",
          "elasticfilesystem:DescribeFileSystems",
          "elasticfilesystem:DescribeAccessPoints"
        ]
        Resource = local.efs_resource_arns
      }
    ]
  })
}

###############################################################################
# IAM - CloudWatch logging role (created only when logging_enabled = true)
###############################################################################

resource "aws_iam_role" "logging" {
  count = var.logging_enabled ? 1 : 0

  name = "${var.sftp_server_name}-logging"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "TransferLoggingAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.sftp_server_name}-logging" })
}

resource "aws_iam_role_policy" "logging" {
  count = var.logging_enabled ? 1 : 0

  name = "${var.sftp_server_name}-logging-policy"
  role = aws_iam_role.logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# AWS Transfer Family SFTP server
###############################################################################

resource "aws_transfer_server" "this" {
  domain                 = "EFS"
  protocols              = ["SFTP"]
  identity_provider_type = "SERVICE_MANAGED"
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  endpoint_type          = local.vpc_enabled ? "VPC" : "PUBLIC"

  logging_role = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  dynamic "endpoint_details" {
    for_each = local.vpc_enabled ? [1] : []

    content {
      vpc_id                 = var.vpc_id
      subnet_ids             = var.subnet_ids
      security_group_ids     = [aws_security_group.sftp[0].id]
      address_allocation_ids = local.public_vpc_endpoint ? aws_eip.sftp[*].id : null
    }
  }

  tags = merge(local.common_tags, { Name = var.sftp_server_name })

  depends_on = [aws_efs_mount_target.this]
}

###############################################################################
# Transfer Family users and their SSH keys
###############################################################################

resource "aws_transfer_user" "this" {
  for_each = var.sftp_users

  server_id           = aws_transfer_server.this.id
  user_name           = each.key
  role                = coalesce(each.value.role_arn, local.generated_user_role_arn)
  home_directory_type = "PATH"
  home_directory      = each.value.restricted ? aws_efs_access_point.users[each.key].arn : "/"

  tags = merge(
    local.common_tags,
    { Name = "${var.name}-user-${each.key}" },
    each.value.tags,
  )
}

resource "aws_transfer_ssh_key" "this" {
  for_each = local.user_ssh_keys

  server_id      = aws_transfer_server.this.id
  user_name      = each.value.user_name
  ssh_public_key = each.value.public_key
}

###############################################################################
# Outputs
###############################################################################

output "sftp_server_id" {
  description = "ID of the AWS Transfer Family SFTP server."
  value       = aws_transfer_server.this.id
}

output "sftp_server_endpoint" {
  description = "Endpoint (or VPC endpoint ID) of the SFTP server."
  value       = aws_transfer_server.this.endpoint
}

output "sftp_server_arn" {
  description = "ARN of the AWS Transfer Family SFTP server."
  value       = aws_transfer_server.this.arn
}

output "efs_file_system_id" {
  description = "ID of the EFS file system backing the SFTP server."
  value       = aws_efs_file_system.this.id
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system backing the SFTP server."
  value       = aws_efs_file_system.this.arn
}

output "efs_mount_target_ids" {
  description = "IDs of the created EFS mount targets (empty when no VPC/subnets were supplied)."
  value       = [for mt in aws_efs_mount_target.this : mt.id]
}

output "user_access_point_arns" {
  description = "Map of SFTP user name to its dedicated EFS access point ARN."
  value       = { for k, ap in aws_efs_access_point.users : k => ap.arn }
}

output "additional_access_point_arns" {
  description = "Map of additional access point name to its EFS access point ARN."
  value       = { for k, ap in aws_efs_access_point.additional : k => ap.arn }
}

output "sftp_user_iam_role_arn" {
  description = "ARN of the automatically generated SFTP user IAM role (null when every user supplied its own role ARN)."
  value       = local.generated_user_role_arn
}

output "sftp_user_names" {
  description = "Names of the provisioned SFTP users."
  value       = [for k, u in aws_transfer_user.this : u.user_name]
}

output "transfer_logging_role_arn" {
  description = "ARN of the CloudWatch logging role attached to the server (null when logging is disabled)."
  value       = var.logging_enabled ? aws_iam_role.logging[0].arn : null
}
```

###############################################################################
# Terraform & provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Input variables
###############################################################################

variable "region" {
  description = "AWS region in which the bucket and supporting resources are created."
  type        = string
  default     = "us-east-1"
}

# --------------------------------------------------------------------------
# Creation toggles - both default to true
# --------------------------------------------------------------------------

variable "create_bucket" {
  description = "Toggle #1 that controls creation of the S3 bucket."
  type        = bool
  default     = true
}

variable "create_kms_key" {
  description = "Toggle #2 that controls creation of the customer managed KMS key used for default SSE-KMS encryption."
  type        = bool
  default     = true
}

# --------------------------------------------------------------------------
# Optional bucket inputs (empty / disabled by default)
# --------------------------------------------------------------------------

variable "bucket" {
  description = "Explicit, globally unique bucket name. Leave empty to have AWS generate one."
  type        = string
  default     = ""
}

variable "bucket_prefix" {
  description = "Prefix used to generate the bucket name when `bucket` is empty."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Whether all objects (including locked ones) must be deleted so the bucket can be destroyed."
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Object Lock default retention, e.g. { default_retention = { mode = \"GOVERNANCE\", days = 30 } }."
  type        = any
  default     = {}
}

variable "tags" {
  description = "Tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

variable "acl" {
  description = "Canned ACL applied to the bucket (e.g. private, public-read)."
  type        = string
  default     = null
}

variable "grants" {
  description = "Explicit ACL grants, e.g. [{ id = \"...\", type = \"CanonicalUser\", permission = \"FULL_CONTROL\" }]."
  type        = list(any)
  default     = []
}

variable "website" {
  description = "Static website hosting configuration: index_document, error_document, redirect_all_requests_to, routing_rules."
  type        = any
  default     = {}
}

variable "cors_rules" {
  description = "List of CORS rules: { id, allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds }."
  type        = list(any)
  default     = []
}

variable "versioning" {
  description = "Versioning configuration: { enabled = bool, mfa_delete = bool }."
  type        = any
  default     = {}
}

variable "logging" {
  description = "Access logging configuration: { target_bucket, target_prefix, target_grants }."
  type        = any
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration status (\"Enabled\" or \"Suspended\"). Empty string disables the resource."
  type        = string
  default     = ""

  validation {
    condition     = contains(["", "Enabled", "Suspended"], var.acceleration_status)
    error_message = "acceleration_status must be one of \"\", \"Enabled\" or \"Suspended\"."
  }
}

variable "request_payer" {
  description = "Requester-pays configuration (\"BucketOwner\" or \"Requester\"). Empty string disables the resource."
  type        = string
  default     = ""

  validation {
    condition     = contains(["", "BucketOwner", "Requester"], var.request_payer)
    error_message = "request_payer must be one of \"\", \"BucketOwner\" or \"Requester\"."
  }
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules with id, status, filter, expiration, transitions, noncurrent_version_* and abort_incomplete_multipart_upload_days."
  type        = list(any)
  default     = []
}

variable "replication_configuration" {
  description = "Cross-region replication configuration: { role = optional arn, rules = [...] }. A role is created when none is supplied."
  type        = any
  default     = {}
}

variable "intelligent_tiering" {
  description = "List of intelligent tiering configurations: { name, filter, tierings = [{ days, access_tier }] }."
  type        = list(any)
  default     = []
}

variable "control_object_ownership" {
  description = "Whether to manage S3 object ownership controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting applied when control_object_ownership is enabled."
  type        = string
  default     = "ObjectWriter"

  validation {
    condition     = contains(["ObjectWriter", "BucketOwnerPreferred", "BucketOwnerEnforced"], var.object_ownership)
    error_message = "object_ownership must be one of ObjectWriter, BucketOwnerPreferred or BucketOwnerEnforced."
  }
}

variable "encryption" {
  description = "Caller-supplied encryption configuration ({ sse_algorithm, kms_key_id, bucket_key_enabled }) that replaces the default SSE-KMS configuration."
  type        = any
  default     = {}
}

# --------------------------------------------------------------------------
# Optional bucket policy toggles (disabled by default)
# --------------------------------------------------------------------------

variable "attach_elb_log_delivery_policy" {
  description = "Attach a policy statement allowing classic ELB access log delivery."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Attach a policy statement allowing ALB/NLB access log delivery."
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Attach a policy statement denying requests that do not use SSL/TLS."
  type        = bool
  default     = false
}

variable "attach_require_latest_tls_policy" {
  description = "Attach a policy statement denying requests using TLS versions older than 1.2."
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Merge the caller-supplied JSON policy defined in `policy`."
  type        = bool
  default     = false
}

variable "policy" {
  description = "User-supplied bucket policy JSON, merged into the combined bucket policy when attach_policy is true."
  type        = string
  default     = ""
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_elb_service_account" "this" {
  count = (var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy) ? 1 : 0
}

data "aws_canonical_user_id" "current" {
  count = length(var.grants) > 0 ? 1 : 0
}

###############################################################################
# Locals
###############################################################################

locals {
  create_bucket  = var.create_bucket
  create_kms_key = var.create_bucket && var.create_kms_key

  tags = var.tags

  bucket_display_name = try(aws_s3_bucket.this[0].bucket, var.bucket != "" ? var.bucket : "s3-bucket")

  # ---- Encryption (caller-supplied config overrides the defaults) ----------
  supplied_sse_algorithm = try(var.encryption.sse_algorithm, null)
  supplied_kms_key_id    = try(var.encryption.kms_key_id, null)

  sse_algorithm = local.supplied_sse_algorithm != null ? local.supplied_sse_algorithm : "aws:kms"

  kms_key_id = local.sse_algorithm == "aws:kms" ? (
    local.supplied_kms_key_id != null ? local.supplied_kms_key_id : try(aws_kms_key.this[0].arn, null)
  ) : null

  bucket_key_enabled = try(var.encryption.bucket_key_enabled, null) != null ? var.encryption.bucket_key_enabled : true

  # ---- Bucket policy -------------------------------------------------------
  attach_bucket_policy = local.create_bucket && (
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_deny_insecure_transport_policy ||
    var.attach_require_latest_tls_policy ||
    var.attach_policy
  )

  create_acl_with_grants = local.create_bucket && length(var.grants) > 0 && var.acl == null

  # ---- Replication ---------------------------------------------------------
  replication_enabled     = local.create_bucket && length(var.replication_configuration) > 0
  create_replication_role = local.replication_enabled && try(var.replication_configuration.role, "") == ""
  replication_role_arn    = local.create_replication_role ? try(aws_iam_role.replication[0].arn, null) : try(var.replication_configuration.role, null)

  replication_destination_bucket = local.replication_enabled ? try(var.replication_configuration.rules[0].destination.bucket, "*") : "*"
}

###############################################################################
# S3 bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  count = local.create_bucket ? 1 : 0

  bucket              = var.bucket != "" ? var.bucket : null
  bucket_prefix       = var.bucket == "" ? (var.bucket_prefix != "" ? var.bucket_prefix : "s3-bucket-") : null
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.tags
}

###############################################################################
# Default customer managed KMS key (rotation enabled, 7 day deletion window)
###############################################################################

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "SSE-KMS key for S3 bucket ${local.bucket_display_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/${local.bucket_display_name}-s3"
  target_key_id = aws_kms_key.this[0].key_id
}

###############################################################################
# Default server side encryption (SSE-KMS)
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.kms_key_id
      sse_algorithm     = local.sse_algorithm
    }

    bucket_key_enabled = local.bucket_key_enabled
  }
}

###############################################################################
# Bucket policy documents
###############################################################################

data "aws_iam_policy_document" "elb_log_delivery" {
  count = local.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0

  statement {
    sid    = "AllowELBLogDelivery"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [data.aws_elb_service_account.this[0].arn]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]
  }
}

data "aws_iam_policy_document" "lb_log_delivery" {
  count = local.create_bucket && var.attach_lb_log_delivery_policy ? 1 : 0

  statement {
    sid    = "AllowLbLogDelivery"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [data.aws_elb_service_account.this[0].arn]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this[0].arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]
  }
}

data "aws_iam_policy_document" "deny_insecure_transport" {
  count = local.create_bucket && var.attach_deny_insecure_transport_policy ? 1 : 0

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

data "aws_iam_policy_document" "deny_old_tls" {
  count = local.create_bucket && var.attach_require_latest_tls_policy ? 1 : 0

  statement {
    sid    = "DenyOldTLSVersions"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }
}

data "aws_iam_policy_document" "combined" {
  count = local.attach_bucket_policy ? 1 : 0

  source_policy_documents = compact([
    var.attach_elb_log_delivery_policy ? data.aws_iam_policy_document.elb_log_delivery[0].json : "",
    var.attach_lb_log_delivery_policy ? data.aws_iam_policy_document.lb_log_delivery[0].json : "",
    var.attach_deny_insecure_transport_policy ? data.aws_iam_policy_document.deny_insecure_transport[0].json : "",
    var.attach_require_latest_tls_policy ? data.aws_iam_policy_document.deny_old_tls[0].json : "",
    var.attach_policy ? var.policy : "",
  ])
}

resource "aws_s3_bucket_policy" "this" {
  count = local.attach_bucket_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

###############################################################################
# Public access block - applied only after the bucket policy
###############################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_bucket_policy.this]
}

###############################################################################
# Object ownership controls - applied only after the bucket policy
###############################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [
    aws_s3_bucket_policy.this,
    aws_s3_bucket_public_access_block.this,
  ]
}

###############################################################################
# ACL (canned ACL or explicit grants)
###############################################################################

resource "aws_s3_bucket_acl" "this" {
  count = local.create_bucket && (var.acl != null || length(var.grants) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  dynamic "access_control_policy" {
    for_each = local.create_acl_with_grants ? [1] : []

    content {
      owner {
        id           = data.aws_canonical_user_id.current[0].id
        display_name = data.aws_canonical_user_id.current[0].display_name
      }

      dynamic "grant" {
        for_each = var.grants

        content {
          permission = grant.value.permission

          grantee {
            id   = try(grant.value.id, null)
            type = try(grant.value.type, "CanonicalUser")
            uri  = try(grant.value.uri, null)
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && length(var.website) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [1] : []
    content {
      suffix = var.website.index_document
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [1] : []
    content {
      key = var.website.error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [1] : []
    content {
      host_name = var.website.redirect_all_requests_to
      protocol  = try(var.website.redirect_all_requests_to_protocol, null)
    }
  }

  routing_rules = try(var.website.routing_rules, null)
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Versioning
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket && length(var.versioning) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = try(var.versioning.enabled, false) ? "Enabled" : "Suspended"
    mfa_delete = try(var.versioning.mfa_delete, false) ? "Enabled" : "Disabled"
  }
}

###############################################################################
# Access logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && length(var.logging) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging.target_bucket
  target_prefix = try(var.logging.target_prefix, null)

  dynamic "target_grant" {
    for_each = try(var.logging.target_grants, [])

    content {
      permission = target_grant.value.permission

      grantee {
        id   = try(target_grant.value.id, null)
        type = try(target_grant.value.type, "CanonicalUser")
        uri  = try(target_grant.value.uri, null)
      }
    }
  }
}

###############################################################################
# Transfer acceleration
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.create_bucket && var.acceleration_status != "" ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

###############################################################################
# Requester pays
###############################################################################

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.create_bucket && var.request_payer != "" ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

###############################################################################
# Lifecycle rules
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = try(rule.value.id, "rule-${rule.key}")
      status = try(rule.value.status, "Enabled")

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []

        content {
          prefix                   = try(filter.value.prefix, null)
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []

        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])

        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = try(transition.value.storage_class, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days           = try(noncurrent_version_expiration.value.noncurrent_days, null)
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])

        content {
          noncurrent_days = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class   = try(noncurrent_version_transition.value.storage_class, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [1] : []

        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }
    }
  }
}

###############################################################################
# Cross region replication (+ IAM role when none is supplied)
###############################################################################

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0

  name = substr("${local.bucket_display_name}-replication", 0, 64)

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "s3.amazonaws.com" }
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_policy" "replication" {
  count = local.create_replication_role ? 1 : 0

  name = substr("${local.bucket_display_name}-replication", 0, 128)

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Resource = [aws_s3_bucket.this[0].arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectLegalHold",
          "s3:GetObjectRetention",
        ]
        Resource = ["${aws_s3_bucket.this[0].arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
        ]
        Resource = ["arn:${data.aws_partition.current.partition}:s3:::${local.replication_destination_bucket}/*"]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_replication_role ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = try(var.replication_configuration.rules, [])

    content {
      id       = try(rule.value.id, "rule-${rule.key}")
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []

        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication_status, null) != null ? [rule.value.delete_marker_replication_status] : []

        content {
          status = delete_marker_replication.value
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account, null)

        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation_owner, null) != null ? [rule.value.destination.access_control_translation_owner] : []

          content {
            owner = access_control_translation.value
          }
        }

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.replica_kms_key_id, null) != null ? [rule.value.destination.replica_kms_key_id] : []

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "metrics" {
          for_each = try(rule.value.destination.metrics_status, null) != null ? [rule.value.destination.metrics_status] : []

          content {
            status = metrics.value
          }
        }

        dynamic "replication_time" {
          for_each = try(rule.value.destination.replication_time_status, null) != null ? [rule.value.destination.replication_time_status] : []

          content {
            status = replication_time.value

            time {
              minutes = try(rule.value.destination.replication_time_minutes, 15)
            }
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Intelligent tiering
###############################################################################

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = local.create_bucket ? {
    for idx, cfg in var.intelligent_tiering :
    try(cfg.name, "tiering-${idx}") => cfg
  } : {}

  bucket = aws_s3_bucket.this[0].id
  name   = each.key

  dynamic "filter" {
    for_each = try(each.value.filter, null) != null ? [each.value.filter] : []

    content {
      prefix = try(filter.value.prefix, null)

      dynamic "tag" {
        for_each = try(filter.value.tags, {})
        content {
          key   = tag.key
          value = tag.value
        }
      }
    }
  }

  dynamic "tiering" {
    for_each = try(each.value.tierings, [])

    content {
      days        = tiering.value.days
      access_tier = tiering.value.access_tier
    }
  }
}

###############################################################################
# Object lock default retention
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && length(var.object_lock_configuration) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.default_retention.mode
      days  = try(var.object_lock_configuration.default_retention.days, null)
      years = try(var.object_lock_configuration.default_retention.years, null)
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "s3_bucket_id" {
  description = "Name (id) of the S3 bucket."
  value       = try(aws_s3_bucket.this[0].id, null)
}

output "s3_bucket_arn" {
  description = "ARN of the S3 bucket."
  value       = try(aws_s3_bucket.this[0].arn, null)
}

output "s3_bucket_domain_name" {
  description = "Domain name of the S3 bucket."
  value       = try(aws_s3_bucket.this[0].bucket_domain_name, null)
}

output "s3_bucket_regional_domain_name" {
  description = "Region specific domain name of the S3 bucket."
  value       = try(aws_s3_bucket.this[0].bucket_regional_domain_name, null)
}

output "s3_bucket_hosted_zone_id" {
  description = "Route53 hosted zone id of the S3 bucket."
  value       = try(aws_s3_bucket.this[0].hosted_zone_id, null)
}

output "s3_bucket_website_endpoint" {
  description = "Website endpoint of the bucket, when static website hosting is enabled."
  value       = try(aws_s3_bucket_website_configuration.this[0].website_endpoint, null)
}

output "s3_bucket_kms_key_arn" {
  description = "ARN of the customer managed KMS key created for default encryption."
  value       = try(aws_kms_key.this[0].arn, null)
}

output "s3_bucket_kms_key_id" {
  description = "ID of the customer managed KMS key created for default encryption."
  value       = try(aws_kms_key.this[0].key_id, null)
}

output "s3_bucket_kms_alias_arn" {
  description = "ARN of the KMS alias pointing at the bucket encryption key."
  value       = try(aws_kms_alias.this[0].arn, null)
}

output "s3_bucket_policy_json" {
  description = "The combined bucket policy JSON that was attached (if any)."
  value       = try(aws_s3_bucket_policy.this[0].policy, null)
}

output "s3_bucket_replication_role_arn" {
  description = "ARN of the IAM role used for cross region replication."
  value       = local.replication_role_arn
}

terraform {
  required_version = ">= 0.12"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "target_stack" {
  description = "Target stack name"
  type        = string
  default     = "benchmark"
}

variable "stack_githash" {
  description = "Stack git hash"
  type        = string
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  description = "Long stack git hash"
  type        = string
  default     = "benchmark0000000000000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  description = "S3 bucket for stack artifacts"
  type        = string
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  description = "S3 object key for dataset"
  type        = string
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  description = "S3 object key for destigmatized dataset"
  type        = string
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  description = "S3 object key for genomic dataset"
  type        = string
  default     = "genomic_dataset.csv"
}

locals {
  tiers = {
    wildfly = {
      prefix                 = "wildfly-deployment-s3"
      base_artifact_prefix   = "wildfly/artifacts"
      base_config_prefix     = "wildfly/config"
      base_ssl_prefix        = "wildfly/ssl"
      s3_datasets            = [var.dataset_s3_object_key, var.destigmatized_dataset_s3_object_key]
      common_security_prefix = "common/security"
    }
    httpd = {
      prefix                 = "httpd-deployment-s3"
      base_artifact_prefix   = "httpd/artifacts"
      base_config_prefix     = "httpd/config"
      base_ssl_prefix        = "httpd/ssl"
      s3_datasets            = [var.dataset_s3_object_key]
      common_security_prefix = "common/security"
    }
    auth-hpds = {
      prefix                 = "auth-hpds-deployment-s3"
      base_artifact_prefix   = "auth-hpds/artifacts"
      base_config_prefix     = "auth-hpds/config"
      base_ssl_prefix        = "auth-hpds/ssl"
      s3_datasets            = [var.genomic_dataset_s3_object_key, var.destigmatized_dataset_s3_object_key]
      common_security_prefix = "common/security"
    }
    open-hpds = {
      prefix                 = "open-hpds-deployment-s3"
      base_artifact_prefix   = "open-hpds/artifacts"
      base_config_prefix     = "open-hpds/config"
      base_ssl_prefix        = "open-hpds/ssl"
      s3_datasets            = [var.genomic_dataset_s3_object_key]
      common_security_prefix = "common/security"
    }
    dictionary = {
      prefix                 = "dictionary-deployment-s3"
      base_artifact_prefix   = "dictionary/artifacts"
      base_config_prefix     = "dictionary/config"
      base_ssl_prefix        = "dictionary/ssl"
      s3_datasets            = [var.dataset_s3_object_key]
      common_security_prefix = "common/security"
    }
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "this" {
  for_each = local.tiers
  name     = "${each.value.prefix}-${var.target_stack}-${var.stack_githash}"

  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name             = "${each.value.prefix}-${var.target_stack}-${var.stack_githash}"
    StackGithashLong = var.stack_githash_long
  }
}

resource "aws_iam_role_policy_attachment" "cloudwatch" {
  for_each   = local.tiers
  role       = aws_iam_role.this[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ssm" {
  for_each   = local.tiers
  role       = aws_iam_role.this[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy" "this" {
  for_each = local.tiers
  name     = "${each.value.prefix}-inline-policy"
  role     = aws_iam_role.this[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateTags"
        ]
        Resource = "arn:aws:ec2:*:*:instance/*"
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = concat(
          [
            "arn:aws:s3:::${var.stack_s3_bucket}/${each.value.base_artifact_prefix}/*",
            "arn:aws:s3:::${var.stack_s3_bucket}/${each.value.base_config_prefix}/*",
            "arn:aws:s3:::${var.stack_s3_bucket}/${each.value.base_ssl_prefix}/*",
            "arn:aws:s3:::${var.stack_s3_bucket}/${each.value.common_security_prefix}/*"
          ],
          [for ds in each.value.s3_datasets : "arn:aws:s3:::${var.stack_s3_bucket}/${ds}"]
        )
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = "arn:aws:s3:::${var.stack_s3_bucket}"
        Condition = {
          StringLike = {
            "s3:prefix" = [
              each.value.base_artifact_prefix,
              each.value.base_config_prefix,
              each.value.base_ssl_prefix,
              each.value.common_security_prefix
            ]
          }
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "this" {
  for_each = local.tiers
  name     = "${each.value.prefix}-${var.target_stack}-${var.stack_githash}"
  role     = aws_iam_role.this[each.key].name
}

output "instance_profile_names" {
  value = { for k, v in aws_iam_instance_profile.this : k => v.name }
}

output "role_arns" {
  value = { for k, v in aws_iam_role.this : k => v.arn }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Controls whether the module creates any resources."
  type        = bool
  default     = true
}

variable "create_new_security_group" {
  description = "When true, create a new security group. When false, manage rules on existing_security_group_id."
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "Existing security group ID to manage rules for when create_new_security_group is false."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID for the new security group. If null or empty, the default VPC is used."
  type        = string
  default     = null
}

variable "security_group_name" {
  description = "Name of the new security group. If null, AWS generates a name."
  type        = string
  default     = null
}

variable "security_group_description" {
  description = "Description for the new security group."
  type        = string
  default     = "Security group managed by Terraform"
}

variable "security_group_create_before_destroy" {
  description = "Whether to enable create_before_destroy for the new security group."
  type        = bool
  default     = true
}

variable "security_group_revoke_rules_on_delete" {
  description = "Whether to revoke all rules when deleting the new security group."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags to apply to created resources."
  type        = map(string)
  default     = {}
}

variable "ingress_rules_new" {
  description = "Ingress rules for the newly created security group."
  type = list(object({
    description                  = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = length([
      for r in var.ingress_rules_new : r
      if length([
        for v in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : v
        if v != null && v != ""
      ]) != 1
    ]) == 0
    error_message = "Each ingress rule for the new security group must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }
}

variable "egress_rules_new" {
  description = "Egress rules for the newly created security group. Defaults to allowing all outbound IPv4 traffic."
  type = list(object({
    description                  = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = [
    {
      description = "Allow all outbound IPv4 traffic"
      ip_protocol = "-1"
      cidr_ipv4   = "0.0.0.0/0"
    }
  ]

  validation {
    condition = length([
      for r in var.egress_rules_new : r
      if length([
        for v in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : v
        if v != null && v != ""
      ]) != 1
    ]) == 0
    error_message = "Each egress rule for the new security group must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }
}

variable "ingress_rules_existing" {
  description = "Ingress rules for the existing security group."
  type = list(object({
    description                  = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = length([
      for r in var.ingress_rules_existing : r
      if length([
        for v in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : v
        if v != null && v != ""
      ]) != 1
    ]) == 0
    error_message = "Each ingress rule for the existing security group must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }
}

variable "egress_rules_existing" {
  description = "Egress rules for the existing security group."
  type = list(object({
    description                  = optional(string)
    ip_protocol                  = string
    from_port                    = optional(number)
    to_port                      = optional(number)
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = length([
      for r in var.egress_rules_existing : r
      if length([
        for v in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : v
        if v != null && v != ""
      ]) != 1
    ]) == 0
    error_message = "Each egress rule for the existing security group must specify exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }
}

variable "create_prefix_list" {
  description = "Whether to create a customer-managed EC2 prefix list."
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name of the customer-managed prefix list."
  type        = string
  default     = "terraform-managed-prefix-list"
}

variable "prefix_list_address_family" {
  description = "Address family for the customer-managed prefix list."
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the customer-managed prefix list."
  type        = number
  default     = 100
}

variable "prefix_list_entries" {
  description = "CIDR entries for the customer-managed prefix list."
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

variable "existing_prefix_list_ids" {
  description = "Existing prefix list IDs. If non-empty, no new prefix list is created."
  type        = list(string)
  default     = []
}

locals {
  create_new_security_group           = var.create && var.create_new_security_group
  manage_existing_security_group_rules = var.create && !var.create_new_security_group

  use_default_vpc = var.create && var.create_new_security_group && (var.vpc_id == null || var.vpc_id == "")
  vpc_id          = (var.vpc_id != null && var.vpc_id != "") ? var.vpc_id : try(data.aws_vpc.default[0].id, null)

  create_prefix_list = var.create && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0
  prefix_list_ids    = length(var.existing_prefix_list_ids) > 0 ? var.existing_prefix_list_ids : aws_ec2_managed_prefix_list.this[*].id

  ingress_rules_new_map      = { for idx, rule in var.ingress_rules_new : tostring(idx) => rule }
  egress_rules_new_map       = { for idx, rule in var.egress_rules_new : tostring(idx) => rule }
  ingress_rules_existing_map = { for idx, rule in var.ingress_rules_existing : tostring(idx) => rule }
  egress_rules_existing_map  = { for idx, rule in var.egress_rules_existing : tostring(idx) => rule }
}

data "aws_vpc" "default" {
  count   = local.use_default_vpc ? 1 : 0
  default = true
}

resource "aws_security_group" "this" {
  count = local.create_new_security_group ? 1 : 0

  name        = var.security_group_name
  description = var.security_group_description
  vpc_id      = local.vpc_id
  egress      = []

  revoke_rules_on_delete = var.security_group_revoke_rules_on_delete

  tags = merge(var.tags, {
    Name = coalesce(var.security_group_name, "terraform-security-group")
  })

  lifecycle {
    create_before_destroy = var.security_group_create_before_destroy
  }
}

resource "aws_vpc_security_group_ingress_rule" "new" {
  for_each = local.create_new_security_group ? local.ingress_rules_new_map : {}

  security_group_id = aws_security_group.this[0].id

  cidr_ipv4                    = each.value.cidr_ipv4 != "" ? each.value.cidr_ipv4 : null
  cidr_ipv6                    = each.value.cidr_ipv6 != "" ? each.value.cidr_ipv6 : null
  referenced_security_group_id = each.value.referenced_security_group_id != "" ? each.value.referenced_security_group_id : null
  prefix_list_id               = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  description                  = each.value.description
}

resource "aws_vpc_security_group_egress_rule" "new" {
  for_each = local.create_new_security_group ? local.egress_rules_new_map : {}

  security_group_id = aws_security_group.this[0].id

  cidr_ipv4                    = each.value.cidr_ipv4 != "" ? each.value.cidr_ipv4 : null
  cidr_ipv6                    = each.value.cidr_ipv6 != "" ? each.value.cidr_ipv6 : null
  referenced_security_group_id = each.value.referenced_security_group_id != "" ? each.value.referenced_security_group_id : null
  prefix_list_id               = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  description                  = each.value.description
}

resource "aws_vpc_security_group_ingress_rule" "existing" {
  for_each = local.manage_existing_security_group_rules ? local.ingress_rules_existing_map : {}

  security_group_id = var.existing_security_group_id

  cidr_ipv4                    = each.value.cidr_ipv4 != "" ? each.value.cidr_ipv4 : null
  cidr_ipv6                    = each.value.cidr_ipv6 != "" ? each.value.cidr_ipv6 : null
  referenced_security_group_id = each.value.referenced_security_group_id != "" ? each.value.referenced_security_group_id : null
  prefix_list_id               = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  description                  = each.value.description
}

resource "aws_vpc_security_group_egress_rule" "existing" {
  for_each = local.manage_existing_security_group_rules ? local.egress_rules_existing_map : {}

  security_group_id = var.existing_security_group_id

  cidr_ipv4                    = each.value.cidr_ipv4 != "" ? each.value.cidr_ipv4 : null
  cidr_ipv6                    = each.value.cidr_ipv6 != "" ? each.value.cidr_ipv6 : null
  referenced_security_group_id = each.value.referenced_security_group_id != "" ? each.value.referenced_security_group_id : null
  prefix_list_id               = each.value.prefix_list_id != "" ? each.value.prefix_list_id : null
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  description                  = each.value.description
}

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = var.tags
}

output "security_group_id" {
  description = "ID of the new security group, or the existing security group ID."
  value       = local.create_new_security_group ? aws_security_group.this[0].id : var.existing_security_group_id
}

output "security_group_arn" {
  description = "ARN of the new security group."
  value       = try(aws_security_group.this[0].arn, null)
}

output "created_prefix_list_id" {
  description = "ID of the created managed prefix list, if any."
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

output "prefix_list_ids" {
  description = "Prefix list IDs available for use in rules."
  value       = local.prefix_list_ids
}

output "ingress_rule_ids_new" {
  description = "IDs of ingress rules created for the new security group."
  value       = { for k, v in aws_vpc_security_group_ingress_rule.new : k => v.id }
}

output "egress_rule_ids_new" {
  description = "IDs of egress rules created for the new security group."
  value       = { for k, v in aws_vpc_security_group_egress_rule.new : k => v.id }
}

output "ingress_rule_ids_existing" {
  description = "IDs of ingress rules created for the existing security group."
  value       = { for k, v in aws_vpc_security_group_ingress_rule.existing : k => v.id }
}

output "egress_rule_ids_existing" {
  description = "IDs of egress rules created for the existing security group."
  value       = { for k, v in aws_vpc_security_group_egress_rule.existing : k => v.id }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region to deploy the CI/CD IAM resources into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name of the application / project used as the prefix for IAM resources."
  type        = string
  default     = "Cv-React-App"
}

variable "pipeline_artifact_bucket_name" {
  description = "Name of the S3 bucket holding CodePipeline artifacts."
  type        = string
  default     = "cv-react-app-codepipeline-artifacts"
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Project     = "Cv-React-App"
    Environment = "CICD"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# 1. EC2 CodeDeploy Role + Instance Profile
###############################################################################

data "aws_iam_policy_document" "ec2_codedeploy_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_codedeploy_role" {
  name               = "${var.project_name}_ec2_codedeploy_role"
  description        = "EC2 role used by CodeDeploy-managed instances for ${var.project_name}"
  assume_role_policy = data.aws_iam_policy_document.ec2_codedeploy_assume_role.json

  tags = merge(var.tags, {
    Name = "${var.project_name}_ec2_codedeploy_role"
  })
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_managed_ec2_role" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRoleForEC2"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_full_access" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_s3_full_access" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "ec2_codedeploy_profile" {
  name = "${var.project_name}_ec2_codedeploy_role"
  role = aws_iam_role.ec2_codedeploy_role.name

  tags = merge(var.tags, {
    Name = "${var.project_name}_ec2_codedeploy_role"
  })
}

###############################################################################
# 2. CodeDeploy Service Role
###############################################################################

data "aws_iam_policy_document" "codedeploy_service_assume_role" {
  statement {
    sid     = "AllowCodeDeployAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codedeploy_service_role" {
  name               = "${var.project_name}_codedeploy_service_role"
  description        = "Service role assumed by AWS CodeDeploy for ${var.project_name}"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_service_assume_role.json

  tags = merge(var.tags, {
    Name = "${var.project_name}_codedeploy_service_role"
  })
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_managed" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_s3_full_access" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

###############################################################################
# 3. EC2 CloudWatch Agent Role + Instance Profile
###############################################################################

data "aws_iam_policy_document" "cloudwatch_agent_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRoleForCloudWatchAgent"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudwatch_agent_role" {
  name               = "${var.project_name}_cloudwatch_agent_role"
  description        = "EC2 role allowing the CloudWatch agent to publish metrics and logs for ${var.project_name}"
  assume_role_policy = data.aws_iam_policy_document.cloudwatch_agent_assume_role.json

  tags = merge(var.tags, {
    Name = "${var.project_name}_cloudwatch_agent_role"
  })
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_server_policy" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_s3_full_access" {
  role       = aws_iam_role.cloudwatch_agent_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "cloudwatch_agent_profile" {
  name = "${var.project_name}_cloudwatch_agent_role"
  role = aws_iam_role.cloudwatch_agent_role.name

  tags = merge(var.tags, {
    Name = "${var.project_name}_cloudwatch_agent_role"
  })
}

###############################################################################
# 4. CodeBuild Role
###############################################################################

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    sid     = "AllowCodeBuildAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild_role" {
  name               = "CodeBuildRole"
  description        = "Service role assumed by AWS CodeBuild for ${var.project_name}"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json

  tags = merge(var.tags, {
    Name = "CodeBuildRole"
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_full_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

data "aws_iam_policy_document" "codebuild_inline" {
  statement {
    sid    = "CloudWatchLoggingPermissions"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodePipelineArtifactBucketAccessUsEast1"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketAcl",
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:DeleteObject"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::codepipeline-us-east-1-*",
      "arn:${data.aws_partition.current.partition}:s3:::codepipeline-us-east-1-*/*",
      "arn:${data.aws_partition.current.partition}:s3:::${var.pipeline_artifact_bucket_name}",
      "arn:${data.aws_partition.current.partition}:s3:::${var.pipeline_artifact_bucket_name}/*"
    ]
  }

  statement {
    sid    = "CodeBuildReportPermissions"
    effect = "Allow"
    actions = [
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:BatchPutTestCases",
      "codebuild:BatchPutCodeCoverages"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codebuild_inline" {
  name   = "${var.project_name}_CodeBuild_inline_policy"
  role   = aws_iam_role.codebuild_role.id
  policy = data.aws_iam_policy_document.codebuild_inline.json
}

###############################################################################
# 5. CodePipeline Role
###############################################################################

data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    sid     = "AllowServicePrincipalsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "codebuild.amazonaws.com",
        "codedeploy.amazonaws.com",
        "codecommit.amazonaws.com",
        "codestar-connections.amazonaws.com",
        "cloudformation.amazonaws.com",
        "ec2.amazonaws.com",
        "lambda.amazonaws.com",
        "s3.amazonaws.com",
        "sns.amazonaws.com",
        "events.amazonaws.com",
        "states.amazonaws.com"
      ]
    }
  }

  statement {
    sid     = "AllowAccountRootAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "codepipeline_role" {
  name               = "CodePipelineRole"
  description        = "Service role assumed by AWS CodePipeline for ${var.project_name}"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json

  tags = merge(var.tags, {
    Name = "CodePipelineRole"
  })
}

data "aws_iam_policy_document" "codepipeline_inline" {
  statement {
    sid    = "CodeStarConnectionsAllActions"
    effect = "Allow"
    actions = [
      "codestar-connections:UseConnection",
      "codestar-connections:GetConnection",
      "codestar-connections:GetConnectionToken",
      "codestar-connections:ListConnections",
      "codestar-connections:PassConnection",
      "codestar-connections:CreateConnection",
      "codestar-connections:DeleteConnection"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3FullAccess"
    effect = "Allow"
    actions = [
      "s3:AbortMultipartUpload",
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:DeleteBucketPolicy",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:GetBucketAcl",
      "s3:GetBucketLocation",
      "s3:GetBucketLogging",
      "s3:GetBucketNotification",
      "s3:GetBucketPolicy",
      "s3:GetBucketVersioning",
      "s3:GetObject",
      "s3:GetObjectAcl",
      "s3:GetObjectVersion",
      "s3:ListAllMyBuckets",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:ListBucketVersions",
      "s3:PutBucketAcl",
      "s3:PutBucketLogging",
      "s3:PutBucketNotification",
      "s3:PutBucketPolicy",
      "s3:PutBucketVersioning",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:PutObjectVersionAcl",
      "s3:RestoreObject"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeCommitFullAccess"
    effect = "Allow"
    actions = [
      "codecommit:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeDeployFullAccess"
    effect = "Allow"
    actions = [
      "codedeploy:CreateDeployment",
      "codedeploy:GetApplication",
      "codedeploy:GetApplicationRevision",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:GetDeploymentGroup",
      "codedeploy:ListApplications",
      "codedeploy:ListDeploymentConfigs",
      "codedeploy:ListDeploymentGroups",
      "codedeploy:RegisterApplicationRevision",
      "codedeploy:BatchGetApplications",
      "codedeploy:BatchGetDeploymentGroups",
      "codedeploy:BatchGetDeployments",
      "codedeploy:StopDeployment",
      "codedeploy:ContinueDeployment",
      "codedeploy:CreateDeploymentGroup",
      "codedeploy:CreateApplication",
      "codedeploy:DeleteApplication",
      "codedeploy:DeleteDeploymentGroup",
      "codedeploy:UpdateApplication",
      "codedeploy:UpdateDeploymentGroup"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaFullAccess"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction",
      "lambda:ListFunctions",
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:GetPolicy",
      "lambda:UpdateFunctionCode",
      "lambda:UpdateFunctionConfiguration",
      "lambda:CreateFunction",
      "lambda:DeleteFunction",
      "lambda:AddPermission",
      "lambda:RemovePermission",
      "lambda:PublishVersion",
      "lambda:CreateAlias",
      "lambda:UpdateAlias",
      "lambda:DeleteAlias"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeBuildFullAccess"
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:BatchGetBuildBatches",
      "codebuild:BatchGetProjects",
      "codebuild:StartBuild",
      "codebuild:StartBuildBatch",
      "codebuild:StopBuild",
      "codebuild:StopBuildBatch",
      "codebuild:ListBuilds",
      "codebuild:ListBuildsForProject",
      "codebuild:ListProjects",
      "codebuild:CreateProject",
      "codebuild:DeleteProject",
      "codebuild:UpdateProject",
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport",
      "codebuild:UpdateReport"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudFormationFullAccess"
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeStackResources",
      "cloudformation:DescribeStacks",
      "cloudformation:GetTemplate",
      "cloudformation:ListStackResources",
      "cloudformation:UpdateStack",
      "cloudformation:CreateChangeSet",
      "cloudformation:DeleteChangeSet",
      "cloudformation:DescribeChangeSet",
      "cloudformation:ExecuteChangeSet",
      "cloudformation:ValidateTemplate"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IAMPassRolePermissions"
    effect = "Allow"
    actions = [
      "iam:PassRole",
      "iam:GetRole",
      "iam:ListRoles",
      "iam:GetRolePolicy",
      "iam:ListRolePolicies",
      "iam:ListAttachedRolePolicies"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SupportingInfrastructureServices"
    effect = "Allow"
    actions = [
      "ec2:*",
      "autoscaling:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "logs:*",
      "sns:*",
      "events:*",
      "states:*",
      "ssm:GetParameters",
      "ssm:GetParameter",
      "ssm:DescribeParameters"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codepipeline_inline" {
  name   = "${var.project_name}_CodePipeline_inline_policy"
  role   = aws_iam_role.codepipeline_role.id
  policy = data.aws_iam_policy_document.codepipeline_inline.json
}

###############################################################################
# Outputs
###############################################################################

output "ec2_codedeploy_role_arn" {
  description = "ARN of the EC2 CodeDeploy service role."
  value       = aws_iam_role.ec2_codedeploy_role.arn
}

output "ec2_codedeploy_instance_profile_name" {
  description = "Name of the EC2 CodeDeploy instance profile."
  value       = aws_iam_instance_profile.ec2_codedeploy_profile.name
}

output "codedeploy_service_role_arn" {
  description = "ARN of the CodeDeploy service role."
  value       = aws_iam_role.codedeploy_service_role.arn
}

output "cloudwatch_agent_role_arn" {
  description = "ARN of the EC2 CloudWatch Agent role."
  value       = aws_iam_role.cloudwatch_agent_role.arn
}

output "cloudwatch_agent_instance_profile_name" {
  description = "Name of the EC2 CloudWatch Agent instance profile."
  value       = aws_iam_instance_profile.cloudwatch_agent_profile.name
}

output "codebuild_role_arn" {
  description = "ARN of the CodeBuild service role."
  value       = aws_iam_role.codebuild_role.arn
}

output "codepipeline_role_arn" {
  description = "ARN of the CodePipeline service role."
  value       = aws_iam_role.codepipeline_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the data layer is deployed."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Deployment environment name applied to every resource tag."
  type        = string
  default     = "dev"
}

variable "table_prefix" {
  description = "Prefix used when naming all DynamoDB tables."
  type        = string
  default     = "near"
}

variable "project" {
  description = "Project identifier applied to every resource tag."
  type        = string
  default     = "decentralized-wallet-file-management"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "Terraform"
  }

  # SSM parameters published for the services that need runtime table discovery.
  # Key = full parameter name, Value = parameter value.
  dynamodb_ssm_parameters = {
    # ---------------------------------------------------------------------
    # File service - invitations (near-files-invitations)
    # ---------------------------------------------------------------------
    "/file-service/dynamodb/invitations/arn"       = aws_dynamodb_table.files_invitations.arn
    "/file-service/dynamodb/invitations/tableName" = aws_dynamodb_table.files_invitations.name
    "/file-service/dynamodb/invitations/streamArn" = aws_dynamodb_table.files_invitations.stream_arn

    # ---------------------------------------------------------------------
    # File service - files (near-files)
    # ---------------------------------------------------------------------
    "/file-service/dynamodb/files/arn"       = aws_dynamodb_table.files.arn
    "/file-service/dynamodb/files/tableName" = aws_dynamodb_table.files.name
    "/file-service/dynamodb/files/streamArn" = aws_dynamodb_table.files.stream_arn

    # ---------------------------------------------------------------------
    # Hashes service (near-hashes)
    # ---------------------------------------------------------------------
    "/hashes-service/dynamodb/hashes/arn"       = aws_dynamodb_table.hashes.arn
    "/hashes-service/dynamodb/hashes/tableName" = aws_dynamodb_table.hashes.name
    "/hashes-service/dynamodb/hashes/streamArn" = aws_dynamodb_table.hashes.stream_arn

    # ---------------------------------------------------------------------
    # File service - storage (near-storage)
    # ---------------------------------------------------------------------
    "/file-service/dynamodb/storage/arn"       = aws_dynamodb_table.storage.arn
    "/file-service/dynamodb/storage/tableName" = aws_dynamodb_table.storage.name
    "/file-service/dynamodb/storage/streamArn" = aws_dynamodb_table.storage.stream_arn

    # ---------------------------------------------------------------------
    # Wallet service (near-wallets)
    # ---------------------------------------------------------------------
    "/wallet-service/dynamodb/wallets/arn"       = aws_dynamodb_table.wallets.arn
    "/wallet-service/dynamodb/wallets/tableName" = aws_dynamodb_table.wallets.name
    "/wallet-service/dynamodb/wallets/streamArn" = aws_dynamodb_table.wallets.stream_arn
  }
}

###############################################################################
# 1. near-app-actions-mapping
###############################################################################

resource "aws_dynamodb_table" "app_actions_mapping" {
  name         = "${var.table_prefix}-app-actions-mapping"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  tags = merge(local.common_tags, {
    Name = "${var.table_prefix}-app-actions-mapping"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# 2. near-app-actions-master
###############################################################################

resource "aws_dynamodb_table" "app_actions_master" {
  name         = "${var.table_prefix}-app-actions-master"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "actionId"

  attribute {
    name = "actionId"
    type = "S"
