###############################################################################
# Systems Manager parameters - DynamoDB table discovery
###############################################################################

resource "aws_ssm_parameter" "dynamodb" {
  for_each = local.dynamodb_ssm_parameters

  name  = each.key
  type  = "String"
  value = each.value

  tags = merge(local.common_tags, {
    Name = each.key
  })
}

###############################################################################
# Outputs
###############################################################################

output "dynamodb_table_names" {
  description = "Names of every DynamoDB table created by this configuration."
  value = {
    app_actions_mapping = aws_dynamodb_table.app_actions_mapping.name
    app_actions_master  = aws_dynamodb_table.app_actions_master.name
    app_categories      = aws_dynamodb_table.app_categories.name
    apps                = aws_dynamodb_table.apps.name
    connected_apps      = aws_dynamodb_table.connected_apps.name
    contacts            = aws_dynamodb_table.contacts.name
    fiat_tokens         = aws_dynamodb_table.fiat_tokens.name
    files_invitations   = aws_dynamodb_table.files_invitations.name
    files               = aws_dynamodb_table.files.name
    folders             = aws_dynamodb_table.folders.name
    hashes              = aws_dynamodb_table.hashes.name
    hidden              = aws_dynamodb_table.hidden.name
    nft_access_requests = aws_dynamodb_table.nft_access_requests.name
    nft_activities      = aws_dynamodb_table.nft_activities.name
    nft_categories      = aws_dynamodb_table.nft_categories.name
    nft_collections     = aws_dynamodb_table.nft_collections.name
    nft_offers          = aws_dynamodb_table.nft_offers.name
    nft_shares          = aws_dynamodb_table.nft_shares.name
    nfts                = aws_dynamodb_table.nfts.name
    otp                 = aws_dynamodb_table.otp.name
    shared_files        = aws_dynamodb_table.shared_files.name
    storage             = aws_dynamodb_table.storage.name
    transactions        = aws_dynamodb_table.transactions.name
    users               = aws_dynamodb_table.users.name
    wallets_blockchain  = aws_dynamodb_table.wallets_blockchain.name
    wallets_private     = aws_dynamodb_table.wallets_private.name
    wallets             = aws_dynamodb_table.wallets.name
  }
}

output "dynamodb_table_arns" {
  description = "ARNs of every DynamoDB table created by this configuration."
  value = {
    files_invitations = aws_dynamodb_table.files_invitations.arn
    files             = aws_dynamodb_table.files.arn
    hashes            = aws_dynamodb_table.hashes.arn
    storage           = aws_dynamodb_table.storage.arn
    wallets           = aws_dynamodb_table.wallets.arn
  }
}

output "dynamodb_stream_arns" {
  description = "Stream ARNs for the stream-enabled tables."
  value = {
    files_invitations = aws_dynamodb_table.files_invitations.stream_arn
    files             = aws_dynamodb_table.files.stream_arn
    hashes            = aws_dynamodb_table.hashes.stream_arn
    storage           = aws_dynamodb_table.storage.stream_arn
    wallets           = aws_dynamodb_table.wallets.stream_arn
  }
}

output "ssm_parameter_names" {
  description = "Fully qualified names of the SSM parameters published for service discovery."
  value       = sort(keys(aws_ssm_parameter.dynamodb))
}

# Chaos Engineering Environment on AWS Fault Injection Simulator

This Terraform template provisions a complete, self-contained chaos engineering sandbox:

- **Network**: A VPC with one public subnet (no auto-assign public IP), an internet gateway, a public route table, and its association.
- **Compute**: A minimal EC2 Auto Scaling Group launched from a launch template that uses the latest ECS-optimized Amazon Linux 2 AMI (resolved via SSM), enforces IMDSv2 (`http_tokens = required`), assigns a public IP at the ENI level, and tags instances and volumes with `ChaosTarget = true` so FIS can select them. SSH is allowed only from an admin CIDR using an accepted SSH public key (auto-generated if none is supplied).
- **IAM**: An EC2 instance role/profile with ECS + SSM managed policies, and a dedicated FIS role with permissions for the terminate, CPU stress (SSM), EBS I/O pause, API fault injection, network disruption, and log-delivery actions.
- **Logging**: A KMS CMK (with a key policy that permits AWS log delivery and the FIS role), an S3 bucket with all public access blocked, SSE-KMS default encryption, ownership controls, versioning, and a bucket policy that grants the AWS log-delivery services write/ACL-check access. A CloudWatch log group plus resource policy backs the FIS experiment logging.
- **FIS experiments**: Five experiment templates, all with `stop_condition = none` (no auto-stop) and log schema v2: API internal error on EC2 `DescribeImages`, EBS volume I/O pause, EC2 CPU stress, EC2 instance termination, and subnet network connectivity disruption.

```iac_template
###############################################################################
# Terraform & Provider configuration
###############################################################################
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables (all with defaults so the template is deployable as-is)
###############################################################################
variable "aws_region" {
  description = "AWS region to deploy the chaos environment into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Short name used to prefix and tag resources."
  type        = string
  default     = "chaos-fis"
}

variable "admin_cidr" {
  description = "CIDR block permitted to SSH into the chaos target instances."
  type        = string
  default     = "203.0.113.0/24"
}

variable "ssh_public_key" {
  description = "Accepted SSH public key for the instances. Leave empty to auto-generate one."
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the chaos VPC."
  type        = string
  default     = "10.42.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the single public subnet."
  type        = string
  default     = "10.42.1.0/24"
}

variable "instance_type" {
  description = "EC2 instance type for the Auto Scaling Group."
  type        = string
  default     = "t3.micro"
}

variable "asg_min_size" {
  description = "Minimum size of the Auto Scaling Group."
  type        = number
  default     = 1
}

variable "asg_desired_capacity" {
  description = "Desired capacity of the Auto Scaling Group."
  type        = number
  default     = 2
}

variable "asg_max_size" {
  description = "Maximum size of the Auto Scaling Group."
  type        = number
  default     = 4
}

variable "experiment_duration" {
  description = "ISO-8601 duration for FIS fault injections."
  type        = string
  default     = "PT5M"
}

variable "cpu_stress_percent" {
  description = "Percentage of CPU to stress during the CPU stress experiment."
  type        = string
  default     = "80"
}

variable "fis_log_prefix" {
  description = "S3 key prefix used for FIS experiment logs."
  type        = string
  default     = "fis-experiments"
}

variable "fis_log_retention_days" {
  description = "CloudWatch Logs retention for FIS experiment logs."
  type        = number
  default     = 14
}

###############################################################################
# Data sources
###############################################################################
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# Latest Amazon ECS-optimized Amazon Linux 2 AMI id, published by AWS.
data "aws_ssm_parameter" "ecs_ami" {
  name = "/aws/service/ecs/optimized-ami/amazon-linux-2/recommended/image_id"
}

###############################################################################
# Networking: VPC, public subnet, IGW, route table
###############################################################################
resource "aws_vpc" "chaos" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.chaos.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.project_name}-public-subnet"
    ChaosTarget = "true"
  }
}

resource "aws_internet_gateway" "chaos" {
  vpc_id = aws_vpc.chaos.id

  tags = {
    Name = "${var.project_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.chaos.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.chaos.id
  }

  tags = {
    Name = "${var.project_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group + SSH key pair
###############################################################################
resource "aws_security_group" "ec2" {
  name_prefix = "${var.project_name}-ec2-"
  description = "Allow SSH from the admin CIDR and all outbound traffic"
  vpc_id      = aws_vpc.chaos.id

  ingress {
    description = "SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-ec2-sg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "tls_private_key" "admin" {
  count = var.ssh_public_key == "" ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

locals {
  generated_public_key = try(tls_private_key.admin[0].public_key_openssh, "")
  accepted_public_key  = var.ssh_public_key != "" ? var.ssh_public_key : local.generated_public_key
}

resource "aws_key_pair" "admin" {
  key_name   = "${var.project_name}-admin-key"
  public_key = local.accepted_public_key

  tags = {
    Name = "${var.project_name}-admin-key"
  }
}

###############################################################################
# IAM: EC2 instance role / profile (ECS + SSM)
###############################################################################
resource "aws_iam_role" "ec2" {
  name = "${var.project_name}-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.project_name}-ec2-role"
  }
}

resource "aws_iam_role_policy_attachment" "ec2_ecs" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "${var.project_name}-ec2-profile"
  role = aws_iam_role.ec2.name
}

###############################################################################
# Launch template + Auto Scaling Group
###############################################################################
resource "aws_launch_template" "app" {
  name_prefix   = "${var.project_name}-lt-"
  image_id      = data.aws_ssm_parameter.ecs_ami.value
  instance_type = var.instance_type
  key_name      = aws_key_pair.admin.key_name

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2.name
  }

  # IMDSv2 required for every instance
  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "enabled"
  }

  # Public IP is assigned per-ENI (the subnet itself does not auto-assign one).
  network_interfaces {
    associate_public_ip_address = true
    delete_on_termination       = true
    security_groups             = [aws_security_group.ec2.id]
  }

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -e
    systemctl enable amazon-ssm-agent || true
    systemctl start amazon-ssm-agent || true
  EOT
  )

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name        = "${var.project_name}-target"
      ChaosTarget = "true"
    }
  }

  tag_specifications {
    resource_type = "volume"

    tags = {
      Name        = "${var.project_name}-target-volume"
      ChaosTarget = "true"
    }
  }

  tags = {
    Name = "${var.project_name}-launch-template"
  }
}

resource "aws_autoscaling_group" "app" {
  name                      = "${var.project_name}-asg"
  min_size                  = var.asg_min_size
  desired_capacity          = var.asg_desired_capacity
  max_size                  = var.asg_max_size
  vpc_zone_identifier       = [aws_subnet.public.id]
  health_check_type         = "EC2"
  health_check_grace_period = 120

  launch_template {
    id      = aws_launch_template.app.id
    version = "$Latest"
  }

  tag {
    key                 = "Name"
    value               = "${var.project_name}-target"
    propagate_at_launch = true
  }

  tag {
    key                 = "ChaosTarget"
    value               = "true"
    propagate_at_launch = true
  }

  depends_on = [
    aws_internet_gateway.chaos,
    aws_route_table_association.public,
  ]
}

###############################################################################
# KMS key for FIS experiment logs (log delivery service may use it)
###############################################################################
resource "aws_kms_key" "fis_logs" {
  description             = "Customer managed key for ${var.project_name} FIS experiment logs"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAWSLogDeliveryToUseKey"
        Effect = "Allow"
        Principal = {
          Service = [
            "delivery.logs.amazonaws.com",
            "logs.${var.aws_region}.amazonaws.com",
            "fis.amazonaws.com",
          ]
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowFISRoleToUseKey"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.fis.arn
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.project_name}-fis-logs-key"
  }
}

resource "aws_kms_alias" "fis_logs" {
  name          = "alias/${var.project_name}-fis-logs"
  target_key_id = aws_kms_key.fis_logs.key_id
}

###############################################################################
# S3 bucket for FIS experiment logs
###############################################################################
resource "aws_s3_bucket" "fis_logs" {
  bucket        = "${var.project_name}-fis-logs-${data.aws_caller_identity.current.account_id}-${var.aws_region}"
  force_destroy = true

  tags = {
    Name = "${var.project_name}-fis-logs"
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ACLs remain enabled so the log delivery service can hand over object ownership.
resource "aws_s3_bucket_ownership_controls" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_versioning" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.fis_logs.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "fis_logs_bucket" {
  statement {
    sid    = "AWSLogDeliveryWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.fis_logs.arn}/${var.fis_log_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:*"]
    }
  }

  statement {
    sid    = "AWSLogDeliveryAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.fis_logs.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:*"]
    }
  }

  statement {
    sid    = "AWSServerAccessLogDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.fis_logs.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  policy = data.aws_iam_policy_document.fis_logs_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.fis_logs]
}

###############################################################################
# CloudWatch log group for FIS experiment logs (schema version 2)
###############################################################################
resource "aws_cloudwatch_log_group" "fis" {
  name              = "/aws/fis/${var.project_name}"
  retention_in_days = var.fis_log_retention_days

  tags = {
    Name = "${var.project_name}-fis-logs"
  }
}

data "aws_iam_policy_document" "fis_log_group" {
  statement {
    sid    = "AllowFISAndLogDeliveryToWrite"
    effect = "Allow"

    principals {
      type = "Service"
      identifiers = [
        "fis.amazonaws.com",
        "delivery.logs.amazonaws.com",
      ]
    }

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.fis.arn}:*"]
  }
}

resource "aws_cloudwatch_log_resource_policy" "fis" {
  policy_name     = "${var.project_name}-fis-log-policy"
  policy_document = data.aws_iam_policy_document.fis_log_group.json

  depends_on = [aws_cloudwatch_log_group.fis]
}

###############################################################################
# IAM role that FIS assumes to run the experiments
###############################################################################
resource "aws_iam_role" "fis" {
  name = "${var.project_name}-fis-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFISAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${var.project_name}-fis-role"
  }
}

data "aws_iam_policy_document" "fis_permissions" {
  statement {
    sid    = "EC2FaultInjection"
    effect = "Allow"

    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeVolumes",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeNetworkAcls",
      "ec2:DescribeRouteTables",
      "ec2:DescribeTags",
      "ec2:TerminateInstances",
      "ec2:StopInstances",
      "ec2:PauseVolumeIO",
      "ec2:CreateNetworkAcl",
      "ec2:CreateNetworkAclEntry",
      "ec2:DeleteNetworkAcl",
      "ec2:DeleteNetworkAclEntry",
      "ec2:ReplaceNetworkAclAssociation",
      "ec2:CreateTags",
      "ec2:DeleteTags",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "SSMFaultInjection"
    effect = "Allow"

    actions = [
      "ssm:SendCommand",
      "ssm:CancelCommand",
      "ssm:ListCommands",
      "ssm:ListCommandInvocations",
      "ssm:GetCommandInvocation",
      "ssm:DescribeInstanceInformation",
      "ssm:GetDocument",
      "ssm:DescribeDocument",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "FISApiFaultInjection"
    effect = "Allow"

    actions = [
      "fis:InjectApiInternalError",
      "fis:InjectApiThrottleError",
      "fis:InjectApiUnavailableError",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsDelivery"
    effect = "Allow"

    actions = [
      "logs:CreateLogDelivery",
      "logs:DeleteLogDelivery",
      "logs:GetLogDelivery",
      "logs:UpdateLogDelivery",
      "logs:ListLogDeliveries",
      "logs:PutResourcePolicy",
      "logs:DescribeResourcePolicies",
      "logs:DescribeLogGroups",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "ExperimentLogBucket"
    effect = "Allow"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = [
      aws_s3_bucket.fis_logs.arn,
      "${aws_s3_bucket.fis_logs.arn}/*",
    ]
  }

  statement {
    sid    = "ExperimentLogEncryption"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey*",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.fis_logs.arn]
  }

  statement {
    sid    = "PassInstanceRoleToSSM"
    effect = "Allow"

    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ec2.arn]
  }
}

resource "aws_iam_policy" "fis_permissions" {
  name        = "${var.project_name}-fis-policy"
  description = "Permissions used by AWS FIS to inject faults into the chaos target environment"
  policy      = data.aws_iam_policy_document.fis_permissions.json
}

resource "aws_iam_role_policy_attachment" "fis_permissions" {
  role       = aws_iam_role.fis.name
  policy_arn = aws_iam_policy.fis_permissions.arn
}

###############################################################################
# FIS experiment templates (none configured to auto-stop)
###############################################################################

# 1) API-level internal error fault against the EC2 DescribeImages API.
resource "aws_fis_experiment_template" "api_internal_error" {
  description = "Inject an internal error on the EC2 DescribeImages API"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "inject-api-internal-error"
    action_id = "aws:fis:inject-api-internal-error"

    parameter {
      key   = "service"
      value = "ec2"
    }

    parameter {
      key   = "operation"
      value = "DescribeImages"
    }

    parameter {
      key   = "percentage"
      value = "100"
    }

    parameter {
      key   = "duration"
      value = var.experiment_duration
    }
  }

  log_configuration {
    log_schema_version = 2

    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = var.fis_log_prefix
    }
  }

  tags = {
    Name = "${var.project_name}-api-internal-error"
  }
}

# 2) EBS volume I/O pause against tagged volumes.
resource "aws_fis_experiment_template" "ebs_pause_io" {
  description = "Pause I/O on all EBS volumes tagged ChaosTarget=true"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "pause-volume-io"
    action_id = "aws:ebs:pause-volume-io"

    parameter {
      key   = "duration"
      value = var.experiment_duration
    }

    target {
      key   = "Volumes"
      value = "chaos-ebs-volumes"
    }
  }

  target {
    name           = "chaos-ebs-volumes"
    resource_type  = "aws:ebs:volume"
    selection_mode = "ALL"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  log_configuration {
    log_schema_version = 2

    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = var.fis_log_prefix
    }
  }

  tags = {
    Name = "${var.project_name}-ebs-pause-io"
  }
}

# 3) EC2 CPU stress against tagged instances.
resource "aws_fis_experiment_template" "ec2_cpu_stress" {
  description = "Stress CPU on all EC2 instances tagged ChaosTarget=true"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "cpu-stress"
    action_id = "aws:ec2:cpu-stress"

    parameter {
      key   = "duration"
      value = var.experiment_duration
    }

    parameter {
      key   = "percent"
      value = var.cpu_stress_percent
    }

    target {
      key   = "Instances"
      value = "chaos-ec2-instances"
    }
  }

  target {
    name           = "chaos-ec2-instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  log_configuration {
    log_schema_version = 2

    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = var.fis_log_prefix
    }
  }

  tags = {
    Name = "${var.project_name}-ec2-cpu-stress"
  }
}

# 4) EC2 instance termination against tagged instances.
resource "aws_fis_experiment_template" "ec2_terminate" {
  description = "Terminate one EC2 instance tagged ChaosTarget=true"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "terminate-instances"
    action_id = "aws:ec2:terminate-instances"

    target {
      key   = "Instances"
      value = "chaos-ec2-terminate"
    }
  }

  target {
    name           = "chaos-ec2-terminate"
    resource_type  = "aws:ec2:instance"
    selection_mode = "COUNT(1)"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  log_configuration {
    log_schema_version = 2

    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = var.fis_log_prefix
    }
  }

  tags = {
    Name = "${var.project_name}-ec2-terminate"
  }
}

# 5) Network connectivity disruption on the tagged public subnet.
resource "aws_fis_experiment_template" "network_disrupt" {
  description = "Disrupt network connectivity on the subnet tagged ChaosTarget=true"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  action {
    name      = "network-disrupt-connectivity"
    action_id = "aws:network:disrupt-connectivity"

    parameter {
      key   = "duration"
      value = var.experiment_duration
    }

    parameter {
      key   = "scope"
      value = "all"
    }

    target {
      key   = "Subnets"
      value = "chaos-subnets"
    }
  }

  target {
    name           = "chaos-subnets"
    resource_type  = "aws:ec2:subnet"
    selection_mode = "ALL"

    resource_tag {
      key   = "ChaosTarget"
      value = "true"
    }
  }

  log_configuration {
    log_schema_version = 2

    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }

    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = var.fis_log_prefix
    }
  }

  tags = {
    Name = "${var.project_name}-network-disrupt"
  }
}

###############################################################################
# Outputs
###############################################################################
output "vpc_id" {
  description = "ID of the chaos VPC."
  value       = aws_vpc.chaos.id
}

output "public_subnet_id" {
  description = "ID of the public subnet used as the network disruption target."
  value       = aws_subnet.public.id
}

output "autoscaling_group_name" {
  description = "Name of the chaos target Auto Scaling Group."
  value       = aws_autoscaling_group.app.name
}

output "fis_role_arn" {
  description = "ARN of the IAM role assumed by AWS FIS."
  value       = aws_iam_role.fis.arn
}

output "fis_experiment_template_ids" {
  description = "IDs of the provisioned FIS experiment templates."
  value = {
    api_internal_error = aws_fis_experiment_template.api_internal_error.id
    ebs_pause_io       = aws_fis_experiment_template.ebs_pause_io.id
    ec2_cpu_stress     = aws_fis_experiment_template.ec2_cpu_stress.id
    ec2_terminate      = aws_fis_experiment_template.ec2_terminate.id
    network_disrupt    = aws_fis_experiment_template.network_disrupt.id
  }
}

output "fis_log_bucket" {
  description = "S3 bucket receiving FIS experiment logs."
  value       = aws_s3_bucket.fis_logs.id
}

output "fis_log_kms_key_arn" {
  description = "ARN of the KMS CMK used for FIS experiment logs."
  value       = aws_kms_key.fis_logs.arn
}

output "generated_ssh_private_key_pem" {
  description = "Auto-generated SSH private key (only set when ssh_public_key was left empty)."
  value       = local.generated_public_key == "" ? null : try(tls_private_key.admin[0].private_key_pem, null)
  sensitive   = true
}
```

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

variable "create_vpc" {
  description = "Controls if VPC should be created"
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "my-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "IPAM pool ID for the VPC"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Netmask length for the VPC when using IPAM"
  type        = number
  default     = null
}

variable "secondary_ipv4_cidr_blocks" {
  description = "List of secondary IPv4 CIDR blocks for the VPC"
  type        = list(string)
  default     = []
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "assign_ipv6_cidr_block" {
  description = "Assign IPv6 CIDR block to the VPC"
  type        = bool
  default     = false
}

variable "ipv6_cidr_block" {
  description = "IPv6 CIDR block for the VPC"
  type        = string
  default     = null
}

variable "create_igw" {
  description = "Create Internet Gateway"
  type        = bool
  default     = true
}

variable "public_subnets" {
  description = "Map of public subnets"
  type = map(object({
    cidr_block                      = string
    availability_zone               = string
    ipv6_cidr_block                 = optional(string)
    assign_ipv6_address_on_creation = optional(bool, false)
    map_public_ip_on_launch         = optional(bool, true)
    tags                            = optional(map(string), {})
  }))
  default = {}
}

variable "private_subnets" {
  description = "Map of private subnets"
  type = map(object({
    cidr_block                      = string
    availability_zone               = string
    ipv6_cidr_block                 = optional(string)
    assign_ipv6_address_on_creation = optional(bool, false)
    tags                            = optional(map(string), {})
  }))
  default = {}
}

variable "public_route_tables" {
  description = "Map of public route tables"
  type = map(object({
    subnets = list(string)
    tags    = optional(map(string), {})
  }))
  default = {}
}

variable "private_route_tables" {
  description = "Map of private route tables"
  type = map(object({
    subnets                 = list(string)
    nat_gateway_key         = optional(string)
    egress_only_gateway_key = optional(string)
    tags                    = optional(map(string), {})
  }))
  default = {}
}

variable "nat_gateways" {
  description = "Map of NAT Gateways"
  type = map(object({
    subnet_key = string
    tags       = optional(map(string), {})
  }))
  default = {}
}

variable "egress_only_internet_gateways" {
  description = "Map of egress-only internet gateways"
  type = map(object({
    tags = optional(map(string), {})
  }))
  default = {}
}

variable "network_acls" {
  description = "Map of network ACLs"
  type = map(object({
    subnet_keys = list(string)
    ingress = list(object({
      from_port       = number
      to_port         = number
      protocol        = string
      rule_no         = number
      action          = string
      cidr_block      = optional(string, "0.0.0.0/0")
      ipv6_cidr_block = optional(string, null)
    }))
    egress = list(object({
      from_port       = number
      to_port         = number
      protocol        = string
      rule_no         = number
      action          = string
      cidr_block      = optional(string, "0.0.0.0/0")
      ipv6_cidr_block = optional(string, null)
    }))
    tags = optional(map(string), {})
  }))
  default = {}
}

variable "dhcp_options" {
  description = "DHCP options configuration"
  type = object({
    domain_name          = optional(string)
    domain_name_servers  = optional(list(string))
    ntp_servers          = optional(list(string))
    netbios_name_servers = optional(list(string))
    netbios_node_type    = optional(string)
    tags                 = optional(map(string), {})
  })
  default = null
}

variable "flow_logs" {
  description = "Map of flow log configurations"
  type = map(object({
    log_destination_type     = string
    log_destination          = optional(string)
    iam_role_arn             = optional(string)
    traffic_type             = string
    max_aggregation_interval = optional(number, 600)
    destination_options = optional(object({
      file_format                = optional(string, "plain-text")
      hive_compatible_partitions = optional(bool, false)
      per_hour_partition         = optional(bool, false)
    }), {})
    tags = optional(map(string), {})
  }))
  default = {}
}

variable "manage_default_security_group" {
  description = "Manage the default security group"
  type        = bool
  default     = false
}

variable "manage_default_network_acl" {
  description = "Manage the default network ACL"
  type        = bool
  default     = false
}

variable "manage_default_route_table" {
  description = "Manage the default route table"
  type        = bool
  default     = false
}

locals {
  create_flow_log_cloudwatch_log_group = anytrue([for k, v in var.flow_logs : v.log_destination_type == "cloud-watch-logs" && v.log_destination == null])
  create_flow_log_cloudwatch_role      = anytrue([for k, v in var.flow_logs : v.log_destination_type == "cloud-watch-logs" && v.iam_role_arn == null])

  public_subnet_route_table_associations = merge([
    for rt_key, rt in var.public_route_tables : {
      for subnet_key in rt.subnets : "${rt_key}-${subnet_key}" => {
        subnet_key      = subnet_key
        route_table_key = rt_key
      }
    }
  ]...)

  private_subnet_route_table_associations = merge([
    for rt_key, rt in var.private_route_tables : {
      for subnet_key in rt.subnets : "${rt_key}-${subnet_key}" => {
        subnet_key      = subnet_key
        route_table_key = rt_key
      }
    }
  ]...)

  private_route_tables_with_nat = {
    for k, v in var.private_route_tables : k => v if v.nat_gateway_key != null
  }

  private_route_tables_with_eigw = {
    for k, v in var.private_route_tables : k => v if v.egress_only_gateway_key != null
  }

  network_acl_ingress_rules = merge([
    for acl_key, acl in var.network_acls : {
      for idx, rule in acl.ingress : "${acl_key}-${idx}" => {
        acl_key = acl_key
        rule    = rule
      }
    }
  ]...)

  network_acl_egress_rules = merge([
    for acl_key, acl in var.network_acls : {
      for idx, rule in acl.egress : "${acl_key}-${idx}" => {
        acl_key = acl_key
        rule    = rule
      }
    }
  ]...)

  network_acl_associations = merge([
    for acl_key, acl in var.network_acls : {
      for subnet_key in acl.subnet_keys : "${acl_key}-${subnet_key}" => {
        acl_key    = acl_key
        subnet_key = subnet_key
      }
    }
  ]...)

  all_subnets = merge(
    { for k, v in var.public_subnets : k => { type = "public", id = aws_subnet.public[k].id } },
    { for k, v in var.private_subnets : k => { type = "private", id = aws_subnet.private[k].id } }
  )
}

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block             = var.ipv4_ipam_pool_id != null ? null : var.vpc_cidr
  ipv4_ipam_pool_id      = var.ipv4_ipam_pool_id
  ipv4_netmask_length    = var.ipv4_netmask_length
  enable_dns_hostnames   = var.enable_dns_hostnames
  enable_dns_support     = var.enable_dns_support
  assign_ipv6_cidr_block = var.assign_ipv6_cidr_block
  ipv6_cidr_block        = var.ipv6_cidr_block

  tags = merge(
    { Name = var.vpc_name },
    var.tags
  )
}

resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  for_each = var.create_vpc ? toset(var.secondary_ipv4_cidr_blocks) : []

  vpc_id     = aws_vpc.this[0].id
  cidr_block = each.value
}

resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    { Name = "${var.vpc_name}-igw" },
    var.tags
  )
}

resource "aws_egress_only_internet_gateway" "this" {
  for_each = var.create_vpc ? var.egress_only_internet_gateways : {}

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    { Name = "${var.vpc_name}-eigw-${each.key}" },
    each.value.tags,
    var.tags
  )
}

resource "aws_subnet" "public" {
  for_each = var.create_vpc ? var.public_subnets : {}

  vpc_id                          = aws_vpc.this[0].id
  cidr_block                      = each.value.cidr_block
  availability_zone               = each.value.availability_zone
  ipv6_cidr_block                 = each.value.ipv6_cidr_block
  assign_ipv6_address_on_creation = each.value.assign_ipv6_address_on_creation
  map_public_ip_on_launch         = each.value.map_public_ip_on_launch

  tags = merge(
    { Name = "${var.vpc_name}-public-${each.key}" },
    each.value.tags,
    var.tags
  )
}

resource "aws_subnet" "private" {
  for_each = var.create_vpc ? var.private_subnets : {}

  vpc_id                          = aws_vpc.this[0].id
  cidr_block                      = each.value.cidr_block
  availability_zone               = each.value.availability_zone
  ipv6_cidr_block                 = each.value.ipv6_cidr_block
  assign_ipv6_address_on_creation = each.value.assign_ipv6_address_on_creation

  tags = merge(
    { Name = "${var.vpc_name}-private-${each.key}" },
    each.value.tags,
    var.tags
  )
}

resource "aws_route_table" "public" {
  for_each = var.create_vpc ? var.public_route_tables : {}

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    { Name = "${var.vpc_name}-public-rt-${each.key}" },
    each.value.tags,
    var.tags
  )
}

resource "aws_route" "public_internet_gateway" {
  for_each = var.create_vpc && var.create_igw ? var.public_route_tables : {}

  route_table_id         = aws_route_table.public[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route" "public_internet_gateway_ipv6" {
  for_each = var.create_vpc && var.create_igw && var.assign_ipv6_cidr_block ? var.public_route_tables : {}

  route_table_id              = aws_route_table.public[each.key].id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this[0].id
}

resource "aws_route_table" "private" {
  for_each = var.create_vpc ? var.private_route_tables : {}

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    { Name = "${var.vpc_name}-private-rt-${each.key}" },
    each.value.tags,
    var.tags
  )
}

resource "aws_route" "private_nat_gateway" {
  for_each = var.create_vpc ? local.private_route_tables_with_nat : {}

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.value.nat_gateway_key].id
}

resource "aws_route" "private_egress_only_gateway" {
  for_each = var.create_vpc ? local.private_route_tables_with_eigw : {}

  route_table_id              = aws_route_table.private[each.key].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.this[each.value.egress_only_gateway_key].id
}

resource "aws_route_table_association" "public" {
  for_each = var.create_vpc ? local.public_subnet_route_table_associations : {}

  subnet_id      = aws_subnet.public[each.value.subnet_key].id
  route_table_id = aws_route_table.public[each.value.route_table_key].id
}

resource "aws_route_table_association" "private" {
  for_each = var.create_vpc ? local.private_subnet_route_table_associations : {}

  subnet_id      = aws_subnet.private[each.value.subnet_key].id
  route_table_id = aws_route_table.private[each.value.route_table_key].id
}

resource "aws_eip" "nat" {
  for_each = var.create_vpc ? var.nat_gateways : {}

  domain = "vpc"

  tags = merge(
    { Name = "${var.vpc_name}-nat-eip-${each.key}" },
    each.value.tags,
    var.tags
  )
}

resource "aws_nat_gateway" "this" {
  for_each = var.create_vpc ? var.nat_gateways : {}

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.value.subnet_key].id

  tags = merge(
    { Name = "${var.vpc_name}-nat-${each.key}" },
    each.value.tags,
    var.tags
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_network_acl" "this" {
  for_each = var.create_vpc ? var.network_acls : {}

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    { Name = "${var.vpc_name}-nacl-${each.key}" },
    each.value.tags,
    var.tags
  )
}

resource "aws_network_acl_rule" "ingress" {
  for_each = var.create_vpc ? local.network_acl_ingress_rules : {}

  network_acl_id  = aws_network_acl.this[each.value.acl_key].id
  rule_number     = each.value.rule.rule_no
  protocol        = each.value.rule.protocol
  action          = each.value.rule.action
  from_port       = each.value.rule.from_port
  to_port         = each.value.rule.to_port
  cidr_block      = each.value.rule.cidr_block
  ipv6_cidr_block = each.value.rule.ipv6_cidr_block
}

resource "aws_network_acl_rule" "egress" {
  for_each = var.create_vpc ? local.network_acl_egress_rules : {}

  network_acl_id  = aws_network_acl.this[each.value.acl_key].id
  rule_number     = each.value.rule.rule_no
  protocol        = each.value.rule.protocol
  action          = each.value.rule.action
  from_port       = each.value.rule.from_port
  to_port         = each.value.rule.to_port
  cidr_block      = each.value.rule.cidr_block
  ipv6_cidr_block = each.value.rule.ipv6_cidr_block
}

resource "aws_network_acl_association" "this" {
  for_each = var.create_vpc ? local.network_acl_associations : {}

  network_acl_id = aws_network_acl.this[each.value.acl_key].id
  subnet_id      = local.all_subnets[each.value.subnet_key].id
}

resource "aws_dhcp_options" "this" {
  count = var.create_vpc && var.dhcp_options != null ? 1 : 0

  domain_name          = var.dhcp_options.domain_name
  domain_name_servers  = var.dhcp_options.domain_name_servers
  ntp_servers          = var.dhcp_options.ntp_servers
  netbios_name_servers = var.dhcp_options.netbios_name_servers
  netbios_node_type    = var.dhcp_options.netbios_node_type

  tags = merge(
    { Name = "${var.vpc_name}-dhcp-options" },
    var.dhcp_options.tags,
    var.tags
  )
}

resource "aws_vpc_dhcp_options_association" "this" {
  count = var.create_vpc && var.dhcp_options != null ? 1 : 0

  vpc_id          = aws_vpc.this[0].id
  dhcp_options_id = aws_dhcp_options.this[0].id
}

resource "aws_cloudwatch_log_group" "flow_log" {
  count = local.create_flow_log_cloudwatch_log_group ? 1 : 0

  name              = "/aws/vpc/flow-logs/${var.vpc_name}"
  retention_in_days = 30

  tags = merge(
    { Name = "${var.vpc_name}-flow-log" },
    var.tags
  )
}

resource "aws_iam_role" "flow_log_cloudwatch" {
  count = local.create_flow_log_cloudwatch_role ? 1 : 0

  name = "${var.vpc_name}-flow-log-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "vpc-flow-logs.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "flow_log_cloudwatch" {
  count = local.create_flow_log_cloudwatch_role ? 1 : 0

  name = "${var.vpc_name}-flow-log-policy"
  role = aws_iam_role.flow_log_cloudwatch[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogGroups",
        "logs:DescribeLogStreams"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_flow_log" "this" {
  for_each = var.create_vpc ? var.flow_logs : {}

  log_destination      = each.value.log_destination != null ? each.value.log_destination : (each.value.log_destination_type == "cloud-watch-logs" ? (local.create_flow_log_cloudwatch_log_group ? aws_cloudwatch_log_group.flow_log[0].arn : null) : null)
  log_destination_type = each.value.log_destination_type
  iam_role_arn         = each.value.iam_role_arn != null ? each.value.iam_role_arn : (each.value.log_destination_type == "cloud-watch-logs" ? (local.create_flow_log_cloudwatch_role ? aws_iam_role.flow_log_cloudwatch[0].arn : null) : null)
  traffic_type         = each.value.traffic_type
  vpc_id               = aws_vpc.this[0].id
  max_aggregation_interval = each.value.max_aggregation_interval

  dynamic "destination_options" {
    for_each = each.value.log_destination_type == "s3" ? [1] : []
    content {
      file_format                = each.value.destination_options.file_format
      hive_compatible_partitions = each.value.destination_options.hive_compatible_partitions
      per_hour_partition         = each.value.destination_options.per_hour_partition
    }
  }

  tags = merge(
    { Name = "${var.vpc_name}-flow-log-${each.key}" },
    each.value.tags,
    var.tags
  )
}

resource "aws_default_security_group" "this" {
  count = var.create_vpc && var.manage_default_security_group ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    { Name = "${var.vpc_name}-default-sg" },
    var.tags
  )
}

resource "aws_default_network_acl" "this" {
  count = var.create_vpc && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this[0].default_network_acl_id

  tags = merge(
    { Name = "${var.vpc_name}-default-nacl" },
    var.tags
  )

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol        = "-1"
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol        = "-1"
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }
}

resource "aws_default_route_table" "this" {
  count = var.create_vpc && var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this[0].default_route_table_id

  tags = merge(
    { Name = "${var.vpc_name}-default-rt" },
    var.tags
  )
}

###############################################################################
# AWS Transfer Family SFTP server - complete, deployable configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.62.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the Transfer Family server is deployed."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Server identifier. If empty, a two-word hyphenated random pet name is generated."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Endpoint type of the Transfer Family server: PUBLIC, VPC or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of: PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "protocols" {
  description = "Protocols enabled on the server (SFTP, FTPS, FTP, AS2)."
  type        = list(string)
  default     = ["SFTP"]
}

variable "domain" {
  description = "Storage backend for the server: S3 or EFS."
  type        = string
  default     = "S3"

  validation {
    condition     = contains(["S3", "EFS"], var.domain)
    error_message = "domain must be either S3 or EFS."
  }
}

variable "security_policy_name" {
  description = "Security policy applied to the server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "certificate_arn" {
  description = "ACM certificate ARN used when FTPS is enabled."
  type        = string
  default     = null
}

variable "pre_authentication_login_banner" {
  description = "Custom banner displayed before authentication."
  type        = string
  default     = null
}

variable "post_authentication_login_banner" {
  description = "Custom banner displayed after authentication."
  type        = string
  default     = null
}

variable "host_key" {
  description = "RSA private key (PEM) to use as the server host key."
  type        = string
  default     = null
  sensitive   = true
}

variable "logging_role_arn" {
  description = "IAM role ARN used for CloudWatch logging. When null a role with AWSTransferLoggingAccess is created."
  type        = string
  default     = null
}

variable "structured_log_destinations" {
  description = "List of CloudWatch log group ARNs used for structured logging."
  type        = list(string)
  default     = []
}

variable "endpoint_details" {
  description = "VPC endpoint details used when endpoint_type is VPC or VPC_ENDPOINT."
  type = object({
    vpc_id                 = optional(string)
    subnet_ids             = optional(list(string), [])
    security_group_ids     = optional(list(string), [])
    address_allocation_ids = optional(list(string), [])
    vpc_endpoint_id        = optional(string)
  })
  default = {}
}

variable "protocol_details" {
  description = "Advanced protocol configuration for the server."
  type = object({
    as2_transports              = optional(list(string), [])
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = {}
}

variable "api_gateway" {
  description = "API Gateway custom identity provider configuration."
  type = object({
    enabled             = optional(bool, false)
    url                 = optional(string)
    api_gateway_arn     = optional(string)
    execution_role_arn  = optional(string)
    invocation_role_arn = optional(string)
  })
  default = {}
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID used to create the CNAME record. No record is created when null."
  type        = string
  default     = null
}

variable "dns_subdomain" {
  description = "Sub-domain label used for the CNAME record."
  type        = string
  default     = "sftp"
}

variable "dns_ttl" {
  description = "TTL of the CNAME record in seconds."
  type        = number
  default     = 300
}

variable "users" {
  description = "Map of SFTP users to provision, keyed by user name."
  type = map(object({
    s3_bucket      = string
    home_directory = optional(string, "")
    tags           = optional(map(string), {})
  }))
  default = {}
}

variable "user_public_keys" {
  description = "Secondary map of user name to a list of SSH public keys to associate with that user."
  type        = map(list(string))
  default     = {}
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Naming
###############################################################################

resource "random_pet" "this" {
  count     = var.name == "" ? 1 : 0
  length    = 2
  separator = "-"
}

locals {
  server_name = var.name != "" ? var.name : random_pet.this[0].id

  common_tags = merge(
    var.tags,
    {
      "ManagedBy" = "Terraform"
      "Name"      = local.server_name
    }
  )
}

###############################################################################
# Logging IAM role (created unless an explicit ARN is provided)
###############################################################################

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    sid     = "AllowTransferServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

locals {
  create_logging_role = var.logging_role_arn == null
  logging_role_arn    = local.create_logging_role ? aws_iam_role.transfer_logging[0].arn : var.logging_role_arn
}

resource "aws_iam_role" "transfer_logging" {
  count              = local.create_logging_role ? 1 : 0
  name               = substr(replace("${local.server_name}-transfer-logging", " ", "-"), 0, 64)
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count      = local.create_logging_role ? 1 : 0
  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

###############################################################################
# API Gateway identity provider IAM role
###############################################################################

locals {
  create_api_gateway_role = (
    var.api_gateway.enabled &&
    (var.api_gateway.execution_role_arn == null || var.api_gateway.invocation_role_arn == null)
  )

  api_gateway_role_arn = local.create_api_gateway_role ? aws_iam_role.api_gateway[0].arn : null

  api_gateway_execution_role = (
    var.api_gateway.execution_role_arn != null
    ? var.api_gateway.execution_role_arn
    : local.api_gateway_role_arn
  )

  api_gateway_invocation_role = (
    var.api_gateway.invocation_role_arn != null
    ? var.api_gateway.invocation_role_arn
    : local.api_gateway_role_arn
  )
}

data "aws_iam_policy_document" "api_gateway" {
  count = local.create_api_gateway_role ? 1 : 0

  statement {
    sid       = "AllowApiGatewayInvoke"
    effect    = "Allow"
    actions   = ["execute-api:Invoke"]
    resources = var.api_gateway.api_gateway_arn != null ? ["${var.api_gateway.api_gateway_arn}/*"] : ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogging"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]
    resources = [
      "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*",
    ]
  }
}

resource "aws_iam_role" "api_gateway" {
  count              = local.create_api_gateway_role ? 1 : 0
  name               = substr(replace("${local.server_name}-transfer-apigw", " ", "-"), 0, 64)
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy" "api_gateway" {
  count  = local.create_api_gateway_role ? 1 : 0
  name   = "transfer-api-gateway-access"
  role   = aws_iam_role.api_gateway[0].id
  policy = data.aws_iam_policy_document.api_gateway[0].json
}

###############################################################################
# Networking helpers for VPC hosted endpoints
###############################################################################

locals {
  is_vpc                  = var.endpoint_type == "VPC"
  is_vpc_endpoint         = var.endpoint_type == "VPC_ENDPOINT"
  create_endpoint_details = local.is_vpc || local.is_vpc_endpoint

  auto_security_group = local.is_vpc && length(var.endpoint_details.security_group_ids) == 0

  auto_eips = (
    local.is_vpc &&
    length(var.endpoint_details.address_allocation_ids) == 0 &&
    length(var.endpoint_details.subnet_ids) > 0
  )

  security_group_ids = (
    local.auto_security_group
    ? aws_security_group.transfer[*].id
    : var.endpoint_details.security_group_ids
  )

  address_allocation_ids = (
    local.auto_eips
    ? aws_eip.transfer[*].id
    : var.endpoint_details.address_allocation_ids
  )
}

resource "aws_security_group" "transfer" {
  count       = local.auto_security_group ? 1 : 0
  name        = substr(replace("${local.server_name}-transfer-sg", " ", "-"), 0, 64)
  description = "Security group for the AWS Transfer Family endpoint"
  vpc_id      = var.endpoint_details.vpc_id

  ingress {
    description = "SFTP / FTPS / FTP access"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.server_name}-transfer-sg" })
}

resource "aws_eip" "transfer" {
  count  = local.auto_eips ? length(var.endpoint_details.subnet_ids) : 0
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.server_name}-transfer-eip-${count.index + 1}"
  })
}

###############################################################################
# Protocol details
###############################################################################

locals {
  create_protocol_details = (
    length(var.protocol_details.as2_transports) > 0 ||
    var.protocol_details.passive_ip != null ||
    var.protocol_details.set_stat_option != null ||
    var.protocol_details.tls_session_resumption_mode != null
  )
}

###############################################################################
# Transfer Family server
###############################################################################

resource "aws_transfer_server" "this" {
  identity_provider_type = var.api_gateway.enabled ? "API_GATEWAY" : "SERVICE_MANAGED"
  endpoint_type          = var.endpoint_type
  protocols              = var.protocols
  domain                 = var.domain
  security_policy_name   = var.security_policy_name

  certificate = var.certificate_arn
  host_key    = var.host_key

  logging_role                = local.logging_role_arn
  structured_log_destinations = length(var.structured_log_destinations) > 0 ? var.structured_log_destinations : null

  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner

  # API Gateway custom identity provider wiring
  url             = var.api_gateway.enabled ? var.api_gateway.url : null
  execution_role  = var.api_gateway.enabled ? local.api_gateway_execution_role : null
  invocation_role = var.api_gateway.enabled ? local.api_gateway_invocation_role : null

  dynamic "endpoint_details" {
    for_each = local.create_endpoint_details ? [1] : []
    content {
      vpc_endpoint_id        = local.is_vpc_endpoint ? var.endpoint_details.vpc_endpoint_id : null
      vpc_id                 = local.is_vpc ? var.endpoint_details.vpc_id : null
      subnet_ids             = local.is_vpc ? var.endpoint_details.subnet_ids : null
      security_group_ids     = local.is_vpc ? local.security_group_ids : null
      address_allocation_ids = local.is_vpc ? local.address_allocation_ids : null
    }
  }

  dynamic "protocol_details" {
    for_each = local.create_protocol_details ? [1] : []
    content {
      as2_transports = (
        length(var.protocol_details.as2_transports) > 0
        ? var.protocol_details.as2_transports
        : null
      )
      passive_ip                  = var.protocol_details.passive_ip
      set_stat_option             = var.protocol_details.set_stat_option
      tls_session_resumption_mode = var.protocol_details.tls_session_resumption_mode
    }
  }

  tags = merge(local.common_tags, { Name = local.server_name })
}

###############################################################################
# Route 53 CNAME mapping
###############################################################################

data "aws_route53_zone" "this" {
  count   = var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
}

resource "aws_route53_record" "this" {
  count   = var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
  name    = "${var.dns_subdomain}.${trimsuffix(data.aws_route53_zone.this[0].name, ".")}"
  type    = "CNAME"
  ttl     = var.dns_ttl
  records = [aws_transfer_server.this.endpoint]
}

###############################################################################
# SFTP users, roles, policies and SSH keys
###############################################################################

locals {
  user_prefix = {
    for k, v in var.users : k => trim(trimprefix(v.home_directory, "/"), "/")
  }
}

data "aws_iam_policy_document" "user" {
  for_each = var.users

  statement {
    sid       = "AllowListBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = ["arn:aws:s3:::${each.value.s3_bucket}"]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values = (
        local.user_prefix[each.key] == ""
        ? ["*"]
        : ["${local.user_prefix[each.key]}/*", local.user_prefix[each.key]]
      )
    }
  }

  statement {
    sid    = "AllowObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectAcl",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:DeleteObject",
    ]
    resources = [
      local.user_prefix[each.key] == ""
      ? "arn:aws:s3:::${each.value.s3_bucket}/*"
      : "arn:aws:s3:::${each.value.s3_bucket}/${local.user_prefix[each.key]}/*"
    ]
  }
}

resource "aws_iam_role" "user" {
  for_each           = var.users
  name               = substr(replace("${local.server_name}-${each.key}", " ", "-"), 0, 64)
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = merge(local.common_tags, each.value.tags)
}

resource "aws_iam_role_policy" "user" {
  for_each = var.users
  name     = "transfer-user-s3-access"
  role     = aws_iam_role.user[each.key].id
  policy   = data.aws_iam_policy_document.user[each.key].json
}

resource "aws_transfer_user" "this" {
  for_each            = var.users
  server_id           = aws_transfer_server.this.id
  user_name           = each.key
  role                = aws_iam_role.user[each.key].arn
  home_directory_type = "PATH"
  home_directory = (
    local.user_prefix[each.key] == ""
    ? "/${each.value.s3_bucket}"
    : "/${each.value.s3_bucket}/${local.user_prefix[each.key]}"
  )

  dynamic "ssh_public_key" {
    for_each = lookup(var.user_public_keys, each.key, [])
    content {
      ssh_public_key_body = ssh_public_key.value
    }
  }

  tags = merge(local.common_tags, each.value.tags, { Name = "${local.server_name}-${each.key}" })
}

###############################################################################
# Outputs
###############################################################################

output "server_name" {
  description = "Resolved name of the Transfer Family server."
  value       = local.server_name
}

output "server_id" {
  description = "Server ID of the Transfer Family server."
  value       = aws_transfer_server.this.id
}

output "server_arn" {
  description = "ARN of the Transfer Family server."
  value       = aws_transfer_server.this.arn
}

output "server_endpoint" {
  description = "Endpoint of the Transfer Family server."
  value       = aws_transfer_server.this.endpoint
}

output "logging_role_arn" {
  description = "ARN of the IAM role used for Transfer Family logging."
  value       = local.logging_role_arn
}

output "api_gateway_role_arn" {
  description = "ARN of the API Gateway authorization role, if created."
  value       = local.api_gateway_role_arn
}

output "dns_record_fqdn" {
  description = "FQDN of the created Route 53 CNAME record, if any."
  value       = try(aws_route53_record.this[0].fqdn, null)
}

output "user_roles" {
  description = "Map of user name to the ARN of its IAM role."
  value       = { for k, r in aws_iam_role.user : k => r.arn }
}

output "user_home_directories" {
  description = "Map of user name to the S3 home directory path."
  value       = { for k, u in aws_transfer_user.this : k => u.home_directory }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "md-k8s"
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = "1.30"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "192.168.0.0/16"
}

###############################################################################
# Data Sources & Locals
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  public_subnet_cidrs  = ["192.168.0.0/19", "192.168.32.0/19", "192.168.64.0/19"]
  private_subnet_cidrs = ["192.168.96.0/19", "192.168.128.0/19", "192.168.160.0/19"]

  cluster_tags = {
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-igw"
  })
}

###############################################################################
# Public Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = length(local.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.cluster_tags, {
    Name                     = "${var.cluster_name}-public-${count.index + 1}"
    "kubernetes.io/role/elb" = "1"
  })
}

###############################################################################
# Private Subnets
###############################################################################

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.cluster_tags, {
    Name                              = "${var.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

###############################################################################
# Public Routing
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT Gateway (single, in the first public subnet)
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Private Routing (shared route table)
###############################################################################

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Database Subnet Group (over the private subnets)
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "${var.cluster_name}-private-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-private-subnet-group"
  })
}

###############################################################################
# KMS Key for EKS secrets envelope encryption
###############################################################################

data "aws_iam_policy_document" "eks_kms" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEKSClusterRoleUseOfKey"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.eks_cluster.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "eks" {
  description             = "KMS key for ${var.cluster_name} EKS secrets encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.eks_kms.json

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-eks-kms"
  })
}

resource "aws_kms_alias" "eks" {
  name          = "alias/${var.cluster_name}-eks"
  target_key_id = aws_kms_key.eks.key_id
}

###############################################################################
# EKS Cluster IAM Role
###############################################################################

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "${var.cluster_name}-cluster-role"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-cluster-role"
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy" "eks_cluster_ec2_describe" {
  name = "${var.cluster_name}-ec2-describe"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DescribeEC2Networking"
        Effect = "Allow"
        Action = [
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeInstances",
          "ec2:DescribeRouteTables",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeNatGateways",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeAddresses"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "eks_cluster_cloudwatch" {
  name = "${var.cluster_name}-cloudwatch-metrics"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishCloudWatchMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name = "${var.cluster_name}-kms-access"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "UseKMSKeyForSecretsEncryption"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Security Groups
###############################################################################

resource "aws_security_group" "control_plane" {
  name        = "${var.cluster_name}-control-plane-sg"
  description = "EKS control plane security group for ${var.cluster_name}"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-control-plane-sg"
  })
}

resource "aws_security_group" "node" {
  name        = "${var.cluster_name}-node-sg"
  description = "Shared node security group for ${var.cluster_name}"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.cluster_tags, {
    Name = "${var.cluster_name}-node-sg"
  })
}

# --- Control plane egress limited to the VPC CIDR ---
resource "aws_security_group_rule" "control_plane_egress_vpc" {
  type              = "egress"
  description       = "Allow control plane outbound traffic within the VPC only"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.control_plane.id
}

# --- Node egress limited to the VPC CIDR ---
resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  description       = "Allow node outbound traffic within the VPC only"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.vpc_cidr]
  security_group_id = aws_security_group.node.id
}

# --- Control plane self ingress ---
resource "aws_security_group_rule" "control_plane_ingress_self" {
  type              = "ingress"
  description       = "Allow control plane self-referencing traffic"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.control_plane.id
}

# --- Node self ingress (traffic between nodes) ---
resource "aws_security_group_rule" "node_ingress_self" {
  type              = "ingress"
  description       = "Allow traffic between nodes in the shared node security group"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.node.id
}

# --- Control plane accepts node traffic on 443 ---
resource "aws_security_group_rule" "control_plane_ingress_from_node" {
  type                     = "ingress"
  description              = "Allow nodes to communicate with the control plane API"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
  security_group_id        = aws_security_group.control_plane.id
}

# --- Node accepts traffic from the cluster / control plane security group ---
resource "aws_security_group_rule" "node_ingress_from_control_plane" {
  type                     = "ingress"
  description              = "Allow traffic from the cluster control plane security group"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.control_plane.id
  security_group_id        = aws_security_group.node.id
}

###############################################################################
# EKS Cluster (control plane only)
###############################################################################

resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn
  version  = var.cluster_version

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    security_group_ids      = [aws_security_group.control_plane.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  tags = merge(local.cluster_tags, {
    Name = var.cluster_name
  })

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_ec2_describe,
    aws_iam_role_policy.eks_cluster_cloudwatch,
    aws_iam_role_policy.eks_cluster_kms,
    aws_kms_key.eks,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "cluster_name" {
  description = "EKS cluster name"
  value       = aws_eks_cluster.main.name
}

output "cluster_arn" {
  description = "EKS cluster ARN"
  value       = aws_eks_cluster.main.arn
}

output "cluster_endpoint" {
  description = "EKS cluster API endpoint (private)"
  value       = aws_eks_cluster.main.endpoint
}

output "cluster_security_group_id" {
  description = "Control plane security group ID"
  value       = aws_security_group.control_plane.id
}

output "node_security_group_id" {
  description = "Shared node security group ID"
  value       = aws_security_group.node.id
}

output "kms_key_arn" {
  description = "KMS key ARN used for EKS secrets encryption"
  value       = aws_kms_key.eks.arn
}

output "private_subnet_ids" {
  description = "Private subnet IDs"
  value       = aws_subnet.private[*].id
}

output "public_subnet_ids" {
  description = "Public subnet IDs"
  value       = aws_subnet.public[*].id
}

###############################################################################
# Terraform & provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 6.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_canonical_user_id" "current" {}

###############################################################################
# Label module - consistent naming and tagging
###############################################################################

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  stage       = var.stage
  name        = var.name
  attributes  = var.attributes
  delimiter   = var.delimiter
  tags        = var.tags
  context     = var.context

  # S3 bucket names must be 3-63 characters
  id_length_limit = 63
  enabled         = true
}

###############################################################################
# Locals
###############################################################################

locals {
  bucket_name = module.this.id

  # ------------------------- Encryption -------------------------
  create_kms_key    = var.kms_enabled && var.kms_key_id == null
  generated_kms_arn = one(aws_kms_key.this[*].arn)

  sse_algorithm      = var.kms_enabled ? "aws:kms" : "AES256"
  kms_key_arn        = var.kms_enabled ? coalesce(var.kms_key_id, local.generated_kms_arn) : null
  kms_master_key_id  = local.sse_algorithm == "aws:kms" ? local.kms_key_arn : null
  bucket_key_enabled = local.sse_algorithm == "aws:kms" ? var.bucket_key_enabled : false

  # ------------------------- Versioning -------------------------
  # Object Lock requires versioning to be enabled.
  versioning_enabled = var.versioning_enabled || var.object_lock_enabled

  # ------------------------- ACL / ownership --------------------
  acl_enabled = var.acl != null || length(var.grants) > 0

  object_ownership = (
    var.object_ownership != null
    ? var.object_ownership
    : (local.acl_enabled ? "BucketOwnerPreferred" : "BucketOwnerEnforced")
  )
}

###############################################################################
# KMS key (only created when KMS is enabled and no key id was supplied)
###############################################################################

data "aws_iam_policy_document" "kms" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = length(var.kms_key_user_arns) > 0 ? [1] : []
    content {
      sid    = "AllowKeyUsage"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = var.kms_key_user_arns
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:Encrypt",
        "kms:GenerateDataKey*",
        "kms:ReEncrypt*",
      ]

      resources = ["*"]
    }
  }
}

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer managed key used for server-side encryption of the ${local.bucket_name} S3 bucket"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = module.this.tags
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

###############################################################################
# S3 bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = module.this.tags
}

# Always block all public access.
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = local.object_ownership
  }

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = local.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.kms_master_key_id
    }

    bucket_key_enabled = local.bucket_key_enabled
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = local.acl_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = length(var.grants) > 0 ? null : var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []

    content {
      dynamic "grant" {
        for_each = var.grants

        content {
          permission = grant.value.permission

          grantee {
            type = grant.value.type
            id   = grant.value.id
            uri  = grant.value.uri
          }
        }
      }

      owner {
        id = data.aws_canonical_user_id.current.id
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Lifecycle configuration
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = (rule.value.prefix != null || rule.value.tags != null) ? [1] : []

        content {
          prefix = rule.value.prefix
          tags   = rule.value.tags
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null ? [1] : []

        content {
          days = rule.value.expiration_days
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []

        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Server access logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_enabled ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix
}

###############################################################################
# Static website hosting
###############################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = var.website_index_document
  }

  error_document {
    key = var.website_error_document
  }

  routing_rules = var.website_routing_rules != null ? jsonencode(var.website_routing_rules) : null
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

###############################################################################
# Transfer acceleration
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

###############################################################################
# Requester pays
###############################################################################

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = var.requester_pays ? 1 : 0

  bucket = aws_s3_bucket.this.id
  payer  = "Requester"
}

###############################################################################
# Object lock
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = (
      var.object_lock_default_retention_days != null
      || var.object_lock_default_retention_years != null
    ) ? [1] : []

    content {
      default_retention {
        mode  = var.object_lock_default_retention_mode
        days  = var.object_lock_default_retention_days
        years = var.object_lock_default_retention_years
      }
    }
  }
}

###############################################################################
# Bucket policy (built from an IAM policy document)
###############################################################################

data "aws_iam_policy_document" "bucket" {
  count = length(var.bucket_policy_statements) > 0 ? 1 : 0

  dynamic "statement" {
    for_each = var.bucket_policy_statements

    content {
      sid    = statement.value.sid
      effect = statement.value.effect

      actions     = length(statement.value.actions) > 0 ? statement.value.actions : null
      not_actions = length(statement.value.not_actions) > 0 ? statement.value.not_actions : null
      resources   = length(statement.value.resources) > 0 ? statement.value.resources : [aws_s3_bucket.this.arn]

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = statement.value.not_principals

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = length(var.bucket_policy_statements) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Input variables
###############################################################################

variable "region" {
  description = "AWS region in which the S3 bucket and supporting resources are created."
  type        = string
  default     = "us-east-1"
}

# ------------------------------- Label inputs -------------------------------

variable "namespace" {
  description = "Namespace (organization/division) used by the label module when building the bucket name and tags."
  type        = string
  default     = "example"
}

variable "environment" {
  description = "Environment name used by the label module (e.g. ue1, usw2, prod)."
  type        = string
  default     = null
}

variable "stage" {
  description = "Stage used by the label module (e.g. dev, staging, prod)."
  type        = string
  default     = null
}

variable "name" {
  description = "Base name used by the label module when building the bucket name and tags."
  type        = string
  default     = "s3"
}

variable "attributes" {
  description = "Additional attributes used by the label module when building the bucket name and tags."
  type        = list(string)
  default     = ["data"]
}

variable "delimiter" {
  description = "Delimiter used by the label module between name components."
  type        = string
  default     = "-"
}

variable "tags" {
  description = "Additional tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "context" {
  description = "Single object for setting the entire label context at once (namespace, environment, stage, name, attributes, tags, ...). Individual non-null variables override values supplied here."
  type        = any
  default     = {}
}

# ------------------------------- Encryption ---------------------------------

variable "kms_enabled" {
  description = "When true the bucket is encrypted with a customer managed KMS key (either supplied or created here). When false, AES256 is used."
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "ARN (or ID) of an existing KMS key to use for bucket encryption. When null and kms_enabled is true, a new key with automatic rotation is created."
  type        = string
  default     = null
}

variable "kms_key_deletion_window_in_days" {
  description = "Number of days before the newly created KMS key is deleted after scheduled destruction."
  type        = number
  default     = 30
}

variable "kms_key_user_arns" {
  description = "Optional list of IAM principal ARNs granted encrypt/decrypt permissions on the KMS key created by this module."
  type        = list(string)
  default     = []
}

variable "bucket_key_enabled" {
  description = "Whether to enable S3 Bucket Keys for KMS encrypted objects (only used when KMS is enabled)."
  type        = bool
  default     = true
}

# ------------------------------- Bucket basics ------------------------------

variable "force_destroy" {
  description = "Whether to delete all objects from the bucket so the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "versioning_enabled" {
  description = "Whether to enable versioning on the bucket. Versioning is always enabled when object lock is enabled."
  type        = bool
  default     = true
}

variable "mfa_delete" {
  description = "MFA delete status of the bucket: \"Enabled\" or \"Disabled\". Requires MFA credentials and versioning enabled; leave null to manage out of band."
  type        = string
  default     = null
}

# ------------------------------- ACLs ---------------------------------------

variable "acl" {
  description = "Canned ACL applied to the bucket (e.g. private, log-delivery-write, bucket-owner-full-control). Ignored when grants are supplied."
  type        = string
  default     = null

  validation {
    condition = (
      var.acl == null || contains([
        "private",
        "public-read",
        "public-read-write",
        "authenticated-read",
        "aws-exec-read",
        "bucket-owner-read",
        "bucket-owner-full-control",
        "log-delivery-write",
      ], var.acl)
    )
    error_message = "The acl value must be a valid canned ACL."
  }
}

variable "grants" {
  description = "Fine grained ACL grants applied through an access control policy. Each grant needs a grantee type plus either an id or a uri, and a permission."
  type = list(object({
    type       = string
    id         = optional(string, null)
    uri        = optional(string, null)
    permission = string
  }))
  default = []
}

variable "object_ownership" {
  description = "Object ownership setting: BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter. Defaults to BucketOwnerPreferred when ACLs are used, otherwise BucketOwnerEnforced."
  type        = string
  default     = null

  validation {
    condition = (
      var.object_ownership == null || contains([
        "BucketOwnerEnforced",
        "BucketOwnerPreferred",
        "ObjectWriter",
      ], var.object_ownership)
    )
    error_message = "The object_ownership value must be BucketOwnerEnforced, BucketOwnerPreferred or ObjectWriter."
  }
}

# ------------------------------- Lifecycle ----------------------------------

variable "lifecycle_rules" {
  description = "List of lifecycle rules. Each rule may define transitions (STANDARD_IA, GLACIER, DEEP_ARCHIVE, ...), expiration and noncurrent version handling."
  type = list(object({
    id      = string
    enabled = optional(bool, true)
    prefix  = optional(string, null)
    tags    = optional(map(string), null)
    transitions = optional(list(object({
      days          = optional(number, null)
      date          = optional(string, null)
      storage_class = string
    })), [])
    expiration_days                    = optional(number, null)
    noncurrent_version_expiration_days = optional(number, null)
    noncurrent_version_transitions = optional(list(object({
      days          = optional(number, null)
      storage_class = string
    })), [])
  }))
  default = []
}

# ------------------------------- Logging ------------------------------------

variable "logging_enabled" {
  description = "Whether to enable server access logging for the bucket to a separate target bucket."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Name of the bucket that receives the access logs. Required when logging_enabled is true."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix applied to the log objects in the target bucket."
  type        = string
  default     = null
}

# ------------------------------- Website ------------------------------------

variable "website_enabled" {
  description = "Whether to enable static website hosting on the bucket."
  type        = bool
  default     = false
}

variable "website_index_document" {
  description = "Suffix of the index document served by the website endpoint."
  type        = string
  default     = "index.html"
}

variable "website_error_document" {
  description = "Key of the error document served by the website endpoint."
  type        = string
  default     = "error.html"
}

variable "website_routing_rules" {
  description = "Routing rules for the website configuration, supplied as a Terraform list/object structure that is JSON encoded (see aws_s3_bucket_website_configuration)."
  type        = any
  default     = null
}

# ------------------------------- CORS ---------------------------------------

variable "cors_rules" {
  description = "List of CORS rules applied to the bucket."
  type = list(object({
    id              = optional(string, null)
    allowed_headers = optional(list(string), null)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string), null)
    max_age_seconds = optional(number, null)
  }))
  default = []
}

# ------------------------------- Accelerate / Requester pays ----------------

variable "acceleration_status" {
  description = "Transfer acceleration status of the bucket: \"Enabled\", \"Suspended\" or null to leave unmanaged."
  type        = string
  default     = null

  validation {
    condition     = var.acceleration_status == null || contains(["Enabled", "Suspended"], var.acceleration_status)
    error_message = "The acceleration_status value must be Enabled or Suspended."
  }
}

variable "requester_pays" {
  description = "When true, the requester of the objects pays for the requests and data transfer."
  type        = bool
  default     = false
}

# ------------------------------- Object lock --------------------------------

variable "object_lock_enabled" {
  description = "Whether to enable S3 Object Lock on the bucket. Versioning is automatically enabled when this is true."
  type        = bool
  default     = false
}

variable "object_lock_default_retention_mode" {
  description = "Default retention mode for object lock: GOVERNANCE or COMPLIANCE."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_default_retention_mode)
    error_message = "The object_lock_default_retention_mode value must be GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_default_retention_days" {
  description = "Default retention period in days for object lock. Mutually exclusive with the years value."
  type        = number
  default     = null
}

variable "object_lock_default_retention_years" {
  description = "Default retention period in years for object lock. Mutually exclusive with the days value."
  type        = number
  default     = null
}

# ------------------------------- Bucket policy ------------------------------

variable "bucket_policy_statements" {
  description = "List of IAM policy statements used to build the bucket policy. Resources default to the bucket ARN when none are supplied."
  type = list(object({
    sid         = optional(string, null)
    effect      = optional(string, "Allow")
    actions     = optional(list(string), [])
    not_actions = optional(list(string), [])
    resources   = optional(list(string), [])
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    not_principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = []
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "ID (name) of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_name" {
  description = "Name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket
}

output "bucket_domain_name" {
  description = "Global domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "Region specific domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_hosted_zone_id" {
  description = "Route 53 hosted zone id of the S3 bucket."
  value       = aws_s3_bucket.this.hosted_zone_id
}

output "bucket_tags" {
  description = "Tags applied to the resources created by this module."
  value       = module.this.tags
}

output "bucket_kms_key_arn" {
  description = "ARN of the KMS key used for bucket encryption (null when AES256 is used)."
  value       = local.kms_key_arn
}

output "bucket_kms_key_id" {
  description = "ID of the KMS key created by this module (null when a key was supplied or KMS is disabled)."
  value       = one(aws_kms_key.this[*].key_id)
}

###############################################################################
# Benchmark VPC stack
#   - VPC (default 10.0.0.0/18)
#   - Public + private subnets across a configurable number of AZs
#   - Internet gateway, NAT gateway (EIP), route tables, network ACLs
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the VPC stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC. Used as the prefix for all created resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/18"
}

variable "availability_zone_count" {
  description = "Number of availability zones to spread subnets across. Use 0 (the default) to use every AZ available in the region."
  type        = number
  default     = 0

  validation {
    condition     = var.availability_zone_count >= 0
    error_message = "availability_zone_count must be 0 or greater (0 = all available AZs)."
  }
}

variable "create_public_subnets" {
  description = "Whether to create public subnets (and the required internet gateway, public route table and public NACL)."
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets (and the private route table and private NACL)."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Whether to create a NAT gateway (with an elastic IP) for private subnet egress. Requires both public and private subnets."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags applied to every resource created by this stack."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  # All usable AZs in the region, then the subset we actually use.
  available_azs = data.aws_availability_zones.available.names
  az_count      = var.availability_zone_count > 0 ? min(var.availability_zone_count, length(local.available_azs)) : length(local.available_azs)
  azs           = slice(local.available_azs, 0, local.az_count)

  # /18 -> newbits 6 -> /24 per subnet. 64 available /24s: public 0..31, private 32..63.
  subnet_newbits        = 6
  private_subnet_offset = 32

  # A NAT gateway is only useful/creatable when it has a public subnet to live in
  # and private subnets to serve.
  create_nat_gateway = var.enable_nat_gateway && var.create_public_subnets && var.create_private_subnets

  common_tags = merge(
    {
      ManagedBy = "Terraform"
      Stack     = "vpc"
    },
    var.tags
  )
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

###############################################################################
# Internet gateway (public subnets only)
###############################################################################

resource "aws_internet_gateway" "this" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = var.create_public_subnets ? local.az_count : 0

  vpc_id                  = aws_vpc.this.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.subnet_newbits, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.subnet_newbits, count.index + local.private_subnet_offset)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

###############################################################################
# NAT gateway (elastic IP + gateway in the first public subnet)
###############################################################################

resource "aws_eip" "nat" {
  count = local.create_nat_gateway ? 1 : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  count = local.create_nat_gateway ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })

  # The NAT gateway needs an internet-attached VPC and a public subnet that can
  # actually reach the internet gateway.
  depends_on = [
    aws_internet_gateway.this,
    aws_route.public_internet,
  ]
}

###############################################################################
# Route tables and routes
###############################################################################

resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  count = var.create_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = var.create_public_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_nat" {
  count = local.create_nat_gateway ? 1 : 0

  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[0].id
}

resource "aws_route_table_association" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

###############################################################################
# Network ACLs
###############################################################################

resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.public[*].id

  # Intra-VPC traffic
  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  # Inbound HTTP
  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  # Inbound HTTPS
  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  # Ephemeral return traffic
  ingress {
    rule_no    = 130
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  # Outbound everything
  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-nacl"
    Tier = "public"
  })
}

resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.private[*].id

  # Intra-VPC traffic
  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  # Ephemeral return traffic (e.g. responses from NAT gateway / internet)
  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  # DNS responses from outside the VPC (in case of non-VPC resolvers)
  ingress {
    rule_no    = 120
    protocol   = "udp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  # Outbound everything
  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-nacl"
    Tier = "private"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.this.id
}

output "vpc_arn" {
  description = "ARN of the created VPC."
  value       = aws_vpc.this.arn
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.this.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the stack."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway (null when public subnets are disabled)."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway (null when it is not created)."
  value       = try(aws_nat_gateway.this[0].id, null)
}

output "nat_gateway_public_ip" {
  description = "Public elastic IP of the NAT gateway (null when it is not created)."
  value       = try(aws_eip.nat[0].public_ip, null)
}

output "public_route_table_id" {
  description = "ID of the public route table (null when public subnets are disabled)."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_id" {
  description = "ID of the private route table (null when private subnets are disabled)."
  value       = try(aws_route_table.private[0].id, null)
}

output "public_network_acl_id" {
  description = "ID of the public network ACL (null when public subnets are disabled)."
  value       = try(aws_network_acl.public[0].id, null)
}

output "private_network_acl_id" {
  description = "ID of the private network ACL (null when private subnets are disabled)."
  value       = try(aws_network_acl.private[0].id, null)
}

# Terraform Description

This Terraform configuration deploys a dual-stack (IPv4/IPv6) three-tier AWS network environment. It contains:

**Networking**
- A VPC named `main-vpc` with IPv4 CIDR `10.16.0.0/16`, default tenancy, DNS hostnames/support enabled, and an Amazon-provided IPv6 CIDR block controlled by the `is_ipv6_enabled` flag (default `true`).
- The `hashicorp/subnets/cidr` module (v1.0.0) is used twice to dynamically calculate subnet CIDRs: one module for IPv4 (`new_bits = 4`, producing `/20` subnets) and one for IPv6 (`new_bits = 8`, producing `/64` subnets). Both modules iterate over the `sn_details` variable (12 subnets across 3 AZs spanning web/app/db/reserved tiers).
- Twelve `aws_subnet` resources created via `for_each` from `sn_details`, each in its target AZ and with the calculated IPv4/IPv6 CIDRs.
- An Internet Gateway, tagged `main-igw-vpc-<vpc-id>`, attached to the VPC.
- A public route table tagged `public-rt-web` with routes for `0.0.0.0/0` and `::/0` to the IGW, associated only with public subnets.

**Security**
- `web_sg`: ingress 443 from `0.0.0.0/0`, ingress 22 from the VPC IPv4 CIDR, egress 443 to `app_sg`.
- `app_sg`: ingress 443 from `web_sg` (via `aws_security_group_rule`), egress 443 to `db_sg`.
- `db_sg`: ingress 443 from `app_sg` (via `aws_security_group_rule`).

Cross-reference rules are declared as standalone `aws_security_group_rule` resources to avoid Terraform dependency cycles between the three security groups.

```iac_template
terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which to deploy the stack"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the main VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "is_ipv6_enabled" {
  description = "Enable Amazon-provided IPv6 CIDR assignment on the VPC"
  type        = bool
  default     = true
}

variable "subnet_bits_ipv4" {
  description = "Number of additional bits used when carving IPv4 subnets"
  type        = number
  default     = 4
}

variable "subnet_bits_ipv6" {
  description = "Number of additional bits used when carving IPv6 subnets"
  type        = number
  default     = 8
}

variable "sn_details" {
  description = "Subnet definitions: name, availability zone and public/private indicator"
  type = list(object({
    name      = string
    az        = string
    is_public = bool
  }))
  default = [
    { name = "web-1a",      az = "us-east-1a", is_public = true },
    { name = "web-1b",      az = "us-east-1b", is_public = true },
    { name = "web-1c",      az = "us-east-1c", is_public = true },
    { name = "app-1a",      az = "us-east-1a", is_public = false },
    { name = "app-1b",      az = "us-east-1b", is_public = false },
    { name = "app-1c",      az = "us-east-1c", is_public = false },
    { name = "db-1a",       az = "us-east-1a", is_public = false },
    { name = "db-1b",       az = "us-east-1b", is_public = false },
    { name = "db-1c",       az = "us-east-1c", is_public = false },
    { name = "reserved-1a", az = "us-east-1a", is_public = false },
    { name = "reserved-1b", az = "us-east-1b", is_public = false },
    { name = "reserved-1c", az = "us-east-1c", is_public = false },
  ]
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled

  tags = {
    Name = "main-vpc"
  }
}

###############################################################################
# Subnet CIDR calculation (hashicorp/subnets/cidr)
###############################################################################

module "subnets_ipv4" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = var.vpc_cidr
  networks = [
    for s in var.sn_details : {
      name     = s.name
      new_bits = var.subnet_bits_ipv4
    }
  ]
}

module "subnets_ipv6" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"
  count   = var.is_ipv6_enabled ? 1 : 0

  base_cidr_block = aws_vpc.main.ipv6_cidr_block
  networks = [
    for s in var.sn_details : {
      name     = s.name
      new_bits = var.subnet_bits_ipv6
    }
  ]
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "main" {
  for_each = { for s in var.sn_details : s.name => s }

  vpc_id            = aws_vpc.main.id
  availability_zone = each.value.az

  cidr_block = module.subnets_ipv4.network_cidr_blocks[each.key]

  ipv6_cidr_block = var.is_ipv6_enabled ? module.subnets_ipv6[0].network_cidr_blocks[each.key] : null

  map_public_ip_on_launch = each.value.is_public

  tags = {
    Name        = each.key
    Tier        = split("-", each.key)[0]
    PublicTier  = each.value.is_public ? "true" : "false"
  }

  depends_on = [aws_vpc.main]
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

###############################################################################
# Public Route Table + Routes + Associations
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = { for s in var.sn_details : s.name => s if s.is_public }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security Groups
###############################################################################

# Web tier security group
resource "aws_security_group" "web" {
  name        = "web_sg"
  description = "Web tier security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TLS from internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description     = "TLS to app tier"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  tags = {
    Name = "web_sg"
  }
}

# App tier security group
resource "aws_security_group" "app" {
  name        = "app_sg"
  description = "App tier security group"
  vpc_id      = aws_vpc.main.id

  egress {
    description     = "TLS to db tier"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.db.id]
  }

  tags = {
    Name = "app_sg"
  }
}

# DB tier security group
resource "aws_security_group" "db" {
  name        = "db_sg"
  description = "DB tier security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

# App tier ingress from Web tier (avoids SG dependency cycle)
resource "aws_security_group_rule" "app_ingress_from_web" {
  type                     = "ingress"
  description              = "TLS from web tier"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.app.id
  source_security_group_id = aws_security_group.web.id
}

# DB tier ingress from App tier (avoids SG dependency cycle)
resource "aws_security_group_rule" "db_ingress_from_app" {
  type                     = "ingress"
  description              = "TLS from app tier"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.db.id
  source_security_group_id = aws_security_group.app.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the main VPC"
  value       = aws_vpc.main.id
}

output "vpc_ipv6_cidr_block" {
  description = "Amazon-provided IPv6 CIDR block of the VPC"
  value       = aws_vpc.main.ipv6_cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = aws_route_table.public.id
}

output "subnet_ipv4_cidrs" {
  description = "Map of subnet name to calculated IPv4 CIDR"
  value       = module.subnets_ipv4.network_cidr_blocks
}

output "subnet_ipv6_cidrs" {
  description = "Map of subnet name to calculated IPv6 CIDR"
  value       = var.is_ipv6_enabled ? module.subnets_ipv6[0].network_cidr_blocks : {}
}
```

## Terraform Configuration Description

This template provisions a complete, VPC-aware **CloudWatch Synthetics canary monitoring stack** with alerting:

**Artifact storage** – An S3 bucket (`benchmark-canary-bucket-tf5x`) with `force_destroy`, configurable versioning (default: disabled), full public-access blocking, default CORS rules, and server-side encryption using either the custom KMS key (default) or AES256.

**Encryption** – A customer-managed KMS key (`alias/benchmark-canary-key`) gated by an `kms_key_enabled` toggle (default `true`), with a 10-day deletion window, automatic key rotation, and a key policy granting `kms:*` to the account root and `Decrypt/GenerateDataKey/DescribeKey` to the CloudWatch service principal.

**Notifications** – An SNS topic (`benchmark-canary-topic`) encrypted with the KMS key, an email subscription (default `nobody@example.com`), and a topic policy that lets CloudWatch alarms publish while retaining owner administration rights.

**Execution role** – An IAM role whose name is prefixed with a `random_pet` two-word name, trusted by `lambda.amazonaws.com`, with an inline policy granting S3 object read/write + bucket listing, `cloudwatch:PutMetricData`, CloudWatch Logs creation/writes, EC2 ENI lifecycle management (create/describe/delete/eni IP assignment), and KMS usage for the encrypted bucket.

**Canaries** – A `for_each` over `var.canary_configs` deploys `aws_synthetics_canary` resources in the supplied subnets/security groups (120s timeout, 960 MB, tracing on, configurable schedule, inline zip *or* S3 artifact source), writing artifacts to the bucket.

**Alarms** – Every canary gets a failure alarm (Sum of `Failed` ≥ 1 in 60s → SNS) and, when `enable_success_alarm = true`, a success-percent alarm (`SuccessPercent` < 90 → SNS alarm + OK actions).

All variables carry defaults, IAM roles and policies are fully declared, and the AWS provider is pinned to a valid region (`us-east-1` by default).

```iac_template
###############################################################################
# CloudWatch Synthetics Canary Monitoring (VPC) with SNS failure notification
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the canary monitoring stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket used to store CloudWatch Synthetics canary artifacts."
  type        = string
  default     = "benchmark-canary-bucket-tf5x"
}

variable "bucket_versioning_enabled" {
  description = "Enable versioning on the canary artifacts bucket."
  type        = bool
  default     = false
}

variable "kms_key_enabled" {
  description = "Create and use a customer managed KMS key for the artifact bucket and the alarm topic."
  type        = bool
  default     = true
}

variable "kms_deletion_window_in_days" {
  description = "Number of days before the KMS key is permanently deleted."
  type        = number
  default     = 10
}

variable "kms_alias_name" {
  description = "Alias of the KMS key used for canary artifacts and alerts."
  type        = string
  default     = "alias/benchmark-canary-key"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic that receives canary alarm notifications."
  type        = string
  default     = "benchmark-canary-topic"
}

variable "alarm_email" {
  description = "Email address subscribed to the canary notification topic."
  type        = string
  default     = "nobody@example.com"
}

variable "enable_success_alarm" {
  description = "Create the optional canary success percentage alarm."
  type        = bool
  default     = false
}

variable "success_alarm_threshold" {
  description = "Success percentage below which the optional success alarm is triggered."
  type        = number
  default     = 90
}

variable "canary_timeout_in_seconds" {
  description = "Execution timeout (seconds) for each canary run."
  type        = number
  default     = 120
}

variable "canary_configs" {
  description = <<-EOT
    Map of VPC canary configurations. The map key is used as the canary name when
    `name` is not supplied. Each entry accepts either an inline `zip_file` (path to
    a local zip archive) or an S3 artifact source (`s3_bucket` / `s3_key` /
    `s3_version`).

    Example:
    canary_configs = {
      "api-health" = {
        name                = "api-health-canary"
        schedule_expression = "rate(5 minutes)"
        zip_file            = "./canary/api-health.zip"
        subnet_ids          = ["subnet-0123456789abcdef0"]
        security_group_ids  = ["sg-0123456789abcdef0"]
      }
      "s3-sourced" = {
        name               = "s3-sourced-canary"
        s3_bucket          = "my-canary-artifacts"
        s3_key             = "canaries/s3-sourced.zip"
        subnet_ids         = ["subnet-0123456789abcdef0"]
        security_group_ids = ["sg-0123456789abcdef0"]
      }
    }
  EOT
  type = map(object({
    name                = optional(string)
    handler             = optional(string, "index.handler")
    runtime_version     = optional(string, "syn-nodejs-puppeteer-7.0")
    schedule_expression = optional(string, "rate(5 minutes)")
    zip_file            = optional(string)
    s3_bucket           = optional(string)
    s3_key              = optional(string)
    s3_version          = optional(string)
    subnet_ids          = list(string)
    security_group_ids  = list(string)
    start_canary        = optional(bool, true)
    memory_in_mb        = optional(number, 960)
    active_tracing      = optional(bool, true)
  }))
  default = {}
}

variable "tags" {
  description = "Tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    Project   = "benchmark-canary"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # Null when the KMS toggle is disabled so that dependent resources fall back
  # to unencrypted / AES256 behaviour.
  kms_key_arn = var.kms_key_enabled ? aws_kms_key.canary[0].arn : null

  canary_configs = var.canary_configs

  kms_key_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountRootAccess"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid    = "AllowCloudWatchToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Randomized two word pet name prefix for the Lambda execution role
###############################################################################

resource "random_pet" "canary" {
  length    = 2
  separator = "-"
}

###############################################################################
# KMS key + alias (optional toggle, enabled by default)
###############################################################################

resource "aws_kms_key" "canary" {
  count = var.kms_key_enabled ? 1 : 0

  description             = "CMK used to encrypt CloudWatch Synthetics canary artifacts and alarm notifications"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = local.kms_key_policy

  tags = merge(var.tags, { Name = "benchmark-canary-key" })
}

resource "aws_kms_alias" "canary" {
  count = var.kms_key_enabled ? 1 : 0

  name          = var.kms_alias_name
  target_key_id = aws_kms_key.canary[0].key_id
}

###############################################################################
# S3 bucket for canary artifacts
###############################################################################

resource "aws_s3_bucket" "canary" {
  bucket        = var.bucket_name
  force_destroy = true

  tags = merge(var.tags, { Name = var.bucket_name })
}

resource "aws_s3_bucket_versioning" "canary" {
  bucket = aws_s3_bucket.canary.id

  versioning_configuration {
    status = var.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_public_access_block" "canary" {
  bucket = aws_s3_bucket.canary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_cors_configuration" "canary" {
  bucket = aws_s3_bucket.canary.id

  cors_rule {
    id              = "default"
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "HEAD"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary" {
  bucket = aws_s3_bucket.canary.id

  rule {
    bucket_key_enabled = var.kms_key_enabled ? true : null

    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_enabled ? "aws:kms" : "AES256"
      kms_master_key_id = local.kms_key_arn
    }
  }
}

###############################################################################
# IAM execution role for the canaries (Lambda execution + VPC ENI management)
###############################################################################

resource "aws_iam_role" "canary" {
  name        = "${random_pet.canary.id}-lambda-execution-role"
  description = "Execution role for CloudWatch Synthetics canaries running inside a VPC"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSyntheticsLambdaAssumption"
        Effect    = "Allow"
        Principal = { Service = "lambda.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(var.tags, { Name = "${random_pet.canary.id}-lambda-execution-role" })
}

resource "aws_iam_role_policy" "canary" {
  name = "${random_pet.canary.id}-lambda-execution-policy"
  role = aws_iam_role.canary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3CanaryArtifactsReadWrite"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:DeleteObject",
          "s3:AbortMultipartUpload"
        ]
        Resource = [
          aws_s3_bucket.canary.arn,
          "${aws_s3_bucket.canary.arn}/*"
        ]
      },
      {
        Sid    = "S3BucketListing"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketVersions",
          "s3:GetBucketLocation",
          "s3:ListAllMyBuckets"
        ]
        Resource = [
          aws_s3_bucket.canary.arn,
          "*"
        ]
      },
      {
        Sid      = "CloudWatchMetricWrite"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogging"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:${local.partition}:logs:${var.aws_region}:${local.account_id}:log-group:/aws/lambda/cwsyn-*",
          "arn:${local.partition}:logs:${var.aws_region}:${local.account_id}:log-group:/aws/lambda/cwsyn-*:*"
        ]
      },
      {
        Sid    = "EC2NetworkInterfaceManagement"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      },
      {
        Sid    = "KMSAccessForEncryptedArtifacts"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = var.kms_key_enabled ? [aws_kms_key.canary[0].arn] : ["*"]
      }
    ]
  })
}

###############################################################################
# SNS topic, encrypted subscription and topic policy
###############################################################################

resource "aws_sns_topic" "canary" {
  name              = var.sns_topic_name
  kms_master_key_id = local.kms_key_arn

  tags = merge(var.tags, { Name = var.sns_topic_name })
}

resource "aws_sns_topic_subscription" "canary_email" {
  topic_arn = aws_sns_topic.canary.arn
  protocol  = "email"
  endpoint  = var.alarm_email
}

resource "aws_sns_topic_policy" "canary" {
  arn = aws_sns_topic.canary.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowOwnerAccountTopicManagement"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action = [
          "SNS:GetTopicAttributes",
          "SNS:SetTopicAttributes",
          "SNS:AddPermission",
          "SNS:RemovePermission",
          "SNS:DeleteTopic",
          "SNS:Subscribe",
          "SNS:ListSubscriptionsByTopic",
          "SNS:Publish"
        ]
        Resource = aws_sns_topic.canary.arn
      },
      {
        Sid       = "AllowCloudWatchAlarmsToPublish"
        Effect    = "Allow"
        Principal = { Service = "cloudwatch.amazonaws.com" }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.canary.arn
      }
    ]
  })
}

###############################################################################
# CloudWatch Synthetics canaries (one per entry in var.canary_configs)
###############################################################################

resource "aws_synthetics_canary" "this" {
  for_each = local.canary_configs

  name                 = coalesce(each.value.name, each.key)
  artifact_s3_location = "s3://${aws_s3_bucket.canary.id}/canary/${coalesce(each.value.name, each.key)}"
  execution_role_arn   = aws_iam_role.canary.arn
  handler              = each.value.handler
  runtime_version      = each.value.runtime_version
  start_canary         = each.value.start_canary

  success_retention_period = 2
  failure_retention_period = 2

  # Inline zip file (base64 encoded) when supplied, otherwise the S3 artifact source.
  zip_file   = try(filebase64(each.value.zip_file), null)
  s3_bucket  = each.value.zip_file == null ? each.value.s3_bucket : null
  s3_key     = each.value.zip_file == null ? each.value.s3_key : null
  s3_version = each.value.zip_file == null ? each.value.s3_version : null

  schedule {
    expression = each.value.schedule_expression
  }

  run_config {
    timeout_in_seconds = var.canary_timeout_in_seconds
    memory_in_mb       = each.value.memory_in_mb
    active_tracing     = each.value.active_tracing
  }

  vpc_config {
    subnet_ids         = each.value.subnet_ids
    security_group_ids = each.value.security_group_ids
  }

  tags = merge(var.tags, { Name = coalesce(each.value.name, each.key) })

  depends_on = [aws_iam_role_policy.canary]
}

###############################################################################
# Failure alarm for every canary: >= 1 failure in a 60 second period
###############################################################################

resource "aws_cloudwatch_metric_alarm" "canary_failure" {
  for_each = aws_synthetics_canary.this

  alarm_name          = "${each.value.name}-failed"
  alarm_description   = "CloudWatch Synthetics canary ${each.value.name} reported one or more failures."
  namespace           = "CloudWatchSynthetics"
  metric_name         = "Failed"
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  datapoints_to_alarm = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  threshold           = 1
  treat_missing_data  = "notBreaching"

  dimensions = {
    CanaryName = each.value.name
  }

  alarm_actions = [aws_sns_topic.canary.arn]
  ok_actions    = [aws_sns_topic.canary.arn]

  tags = merge(var.tags, { Name = "${each.value.name}-failed" })
}

###############################################################################
# Optional success percentage alarm (disabled by default)
###############################################################################

resource "aws_cloudwatch_metric_alarm" "canary_success" {
  for_each = { for k, canary in aws_synthetics_canary.this : k => canary if var.enable_success_alarm }

  alarm_name          = "${each.value.name}-success-percent"
  alarm_description   = "CloudWatch Synthetics canary ${each.value.name} success percentage dropped below ${var.success_alarm_threshold}%."
  namespace           = "CloudWatchSynthetics"
  metric_name         = "SuccessPercent"
  statistic           = "Average"
  period              = 60
  evaluation_periods  = 1
  datapoints_to_alarm = 1
  comparison_operator = "LessThanThreshold"
  threshold           = var.success_alarm_threshold
  treat_missing_data  = "notBreaching"

  dimensions = {
    CanaryName = each.value.name
  }

  alarm_actions = [aws_sns_topic.canary.arn]
  ok_actions    = [aws_sns_topic.canary.arn]

  tags = merge(var.tags, { Name = "${each.value.name}-success-percent" })
}

###############################################################################
# Outputs
###############################################################################

output "canary_execution_role_arn" {
  description = "ARN of the canary execution role."
  value       = aws_iam_role.canary.arn
}

output "canary_execution_role_name" {
  description = "Name of the canary execution role (pet name prefixed)."
  value       = aws_iam_role.canary.name
}

output "canary_pet_name_prefix" {
  description = "Randomized two word pet name used as the resource name prefix."
  value       = random_pet.canary.id
}

output "canary_artifacts_bucket" {
  description = "Name of the S3 bucket storing canary artifacts."
  value       = aws_s3_bucket.canary.id
}

output "canary_artifacts_bucket_arn" {
  description = "ARN of the S3 bucket storing canary artifacts."
  value       = aws_s3_bucket.canary.arn
}

output "canary_kms_key_arn" {
  description = "ARN of the KMS key used to encrypt artifacts and alerts (null when disabled)."
  value       = local.kms_key_arn
}

output "canary_kms_key_alias" {
  description = "Alias of the KMS key (null when the KMS toggle is disabled)."
  value       = var.kms_key_enabled ? aws_kms_alias.canary[0].name : null
}

output "canary_alarm_topic_arn" {
  description = "ARN of the SNS topic receiving canary alarm notifications."
  value       = aws_sns_topic.canary.arn
}

output "canary_names" {
  description = "Names of the deployed canaries."
  value       = { for k, canary in aws_synthetics_canary.this : k => canary.name }
}

output "canary_arns" {
  description = "ARNs of the deployed canaries."
  value       = { for k, canary in aws_synthetics_canary.this : k => canary.arn }
}

output "canary_failure_alarm_arns" {
  description = "ARNs of the per-canary failure alarms."
  value       = { for k, alarm in aws_cloudwatch_metric_alarm.canary_failure : k => alarm.arn }
}

output "canary_success_alarm_arns" {
  description = "ARNs of the optional per-canary success percentage alarms."
  value       = { for k, alarm in aws_cloudwatch_metric_alarm.canary_success : k => alarm.arn }
}
```

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all resources"
  type        = map(string)
  default     = {}
}

variable "name" {
  description = "Name prefix for all resources"
  type        = string
  default     = "vpc"
}

variable "create_vpc" {
  description = "Controls whether the VPC and associated resources are created"
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "availability_zones" {
  description = "List of availability zones to map subnets across"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24", "10.0.12.0/24"]
}

variable "intra_subnet_cidrs" {
  description = "List of CIDR blocks for isolated intra subnets"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24", "10.0.22.0/24"]
}

variable "public_subnet_names" {
  description = "Optional explicit names for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Optional explicit names for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Optional explicit names for intra subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix used in generated public subnet names"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix used in generated private subnet names"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix used in generated intra subnet names"
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Automatically assign public IPs to instances in public subnets"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls whether an Internet Gateway is created for public subnets"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Controls whether NAT gateways and Elastic IPs are created"
  type        = bool
  default     = false
}

locals {
  create_public_rt = var.create_vpc && length(var.public_subnet_cidrs) > 0
  igw_enabled      = var.create_vpc && var.create_igw && length(var.public_subnet_cidrs) > 0
  nat_enabled      = var.create_vpc && var.enable_nat_gateway && length(var.public_subnet_cidrs) > 0 && length(var.private_subnet_cidrs) > 0
  nat_count        = local.nat_enabled ? min(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs)) : 0
}

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = merge(var.tags, {
    Name = var.name
  })
}

resource "aws_internet_gateway" "this" {
  count = local.igw_enabled ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = "${var.name}-igw"
  })
}

resource "aws_subnet" "public" {
  count = var.create_vpc ? length(var.public_subnet_cidrs) : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  availability_zone       = element(var.availability_zones, count.index)
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(var.tags, {
    Name = length(var.public_subnet_names) > 0 ? element(var.public_subnet_names, count.index) : "${var.name}-${var.public_subnet_suffix}-${element(var.availability_zones, count.index)}"
  })
}

resource "aws_subnet" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(var.availability_zones, count.index)

  tags = merge(var.tags, {
    Name = length(var.private_subnet_names) > 0 ? element(var.private_subnet_names, count.index) : "${var.name}-${var.private_subnet_suffix}-${element(var.availability_zones, count.index)}"
  })
}

resource "aws_subnet" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = element(var.intra_subnet_cidrs, count.index)
  availability_zone = element(var.availability_zones, count.index)

  tags = merge(var.tags, {
    Name = length(var.intra_subnet_names) > 0 ? element(var.intra_subnet_names, count.index) : "${var.name}-${var.intra_subnet_suffix}-${element(var.availability_zones, count.index)}"
  })
}

resource "aws_route_table" "public" {
  count = local.create_public_rt ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = "${var.name}-${var.public_subnet_suffix}-rt"
  })
}

resource "aws_route" "public_internet" {
  count = local.igw_enabled ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = local.create_public_rt ? length(var.public_subnet_cidrs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = "${var.name}-${var.private_subnet_suffix}-rt-${element(var.availability_zones, count.index)}"
  })
}

resource "aws_route" "private_nat" {
  count = local.nat_enabled ? length(var.private_subnet_cidrs) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index % local.nat_count].id
}

resource "aws_route_table_association" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = "${var.name}-${var.intra_subnet_suffix}-rt-${element(var.availability_zones, count.index)}"
  })
}

resource "aws_route_table_association" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

resource "aws_eip" "nat" {
  count = local.nat_enabled ? local.nat_count : 0

  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${var.name}-nat-eip-${count.index + 1}"
  })
}

resource "aws_nat_gateway" "this" {
  count = local.nat_enabled ? local.nat_count : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = element(aws_subnet.public[*].id, count.index)

  tags = merge(var.tags, {
    Name = "${var.name}-nat-${count.index + 1}"
  })

  depends_on = [aws_internet_gateway.this]
}

output "vpc_id" {
  description = "ID of the created VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC"
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "internet_gateway_id" {
  description = "ID of the created Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "IDs of the intra subnets"
  value       = aws_subnet.intra[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "IDs of the private route tables"
  value       = aws_route_table.private[*].id
}

output "intra_route_table_ids" {
  description = "IDs of the intra route tables"
  value       = aws_route_table.intra[*].id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways"
  value       = aws_nat_gateway.this[*].id
}

output "nat_public_ips" {
  description = "Elastic IP addresses allocated for NAT gateways"
  value       = aws_eip.nat[*].public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type    = string
  default = "us-east-1"
}

variable "api_type" {
  type    = string
  default = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either 'http' or 'rest'."
  }
}

variable "api_name" {
  type    = string
  default = "benchmark-api"
}

variable "environment" {
  type    = string
  default = "dev"
}

variable "vpc_link_enabled" {
  type    = bool
  default = false
}

variable "domain_name" {
  type    = string
  default = ""
}

variable "hosted_zone_id" {
  type    = string
  default = ""
}

variable "route53_record_enabled" {
  type    = bool
  default = false
}

variable "acm_certificate_arn" {
  type    = string
  default = ""
}

variable "private_subnet_ids" {
  type    = list(string)
  default = []
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "alb_arn" {
  type    = string
  default = ""
}

variable "alb_listener_port" {
  type    = number
  default = 443
}

variable "http_routes" {
  type = list(object({
    route_key        = string
    integration_type = string
    integration_uri  = string
  }))

  default = [
    {
      route_key        = "GET /"
      integration_type = "MOCK"
      integration_uri  = ""
    }
  ]
}

variable "rest_routes" {
  type = list(object({
    path               = string
    method             = string
    request_parameters = map(string)
  }))

  default = []
}

variable "rest_api_ip_whitelist_enabled" {
  type    = bool
  default = false
}

variable "rest_api_ip_whitelist" {
  type    = list(string)
  default = ["0.0.0.0/0"]
}

variable "rest_api_key_enabled" {
  type    = bool
  default = false
}

variable "rest_lambda_authorizer_enabled" {
  type    = bool
  default = false
}

variable "rest_redeployment_trigger" {
  type    = string
  default = "1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_subnet" "first" {
  count = length(var.private_subnet_ids) > 0 ? 1 : 0
  id    = var.private_subnet_ids[0]
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "rest_api_policy" {
  count = var.api_type == "rest" && var.rest_api_ip_whitelist_enabled ? 1 : 0

  statement {
    effect = "Allow"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions   = ["execute-api:Invoke"]
    resources = ["execute-api:/*"]

    condition {
      test     = "IpAddress"
      variable = "aws:SourceIp"
      values   = var.rest_api_ip_whitelist
    }
  }
}

data "archive_file" "lambda_authorizer" {
  count       = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0
  type        = "zip"
  output_path = "${path.module}/authorizer.zip"

  source {
    content = <<EOF
exports.handler = async (event) => {
  return {
    principalId: 'user',
    policyDocument: {
      Version: '2012-10-17',
      Statement: [{
        Action: 'execute-api:Invoke',
        Effect: 'Allow',
        Resource: event.methodArn
      }]
    }
  };
};
EOF
    filename = "index.js"
  }
}

locals {
  create_vpc = var.vpc_link_enabled && length(var.private_subnet_ids) == 0

  private_subnet_ids = length(var.private_subnet_ids) > 0 ? var.private_subnet_ids : (local.create_vpc ? aws_subnet.private[*].id : [])

  vpc_id = local.create_vpc ? aws_vpc.this[0].id : (length(var.private_subnet_ids) > 0 ? data.aws_subnet.first[0].vpc_id : "")

  create_alb = var.api_type == "rest" && var.vpc_link_enabled && var.alb_arn == "" && length(local.private_subnet_ids) >= 2

  alb_arn = var.alb_arn != "" ? var.alb_arn : (local.create_alb ? aws_lb.alb[0].arn : "")

  create_rest_vpc_link = var.api_type == "rest" && var.vpc_link_enabled && length(local.private_subnet_ids) >= 2 && local.alb_arn != ""

  create_http_vpc_link = var.api_type == "http" && var.vpc_link_enabled && length(local.private_subnet_ids) >= 2

  create_acm = var.domain_name != "" && var.acm_certificate_arn == ""

  acm_certificate_arn = var.acm_certificate_arn != "" ? var.acm_certificate_arn : (local.create_acm ? (var.hosted_zone_id != "" ? aws_acm_certificate_validation.this[0].certificate_arn : aws_acm_certificate.this[0].arn) : "")

  rest_unique_paths = toset([for r in var.rest_routes : r.path])
}

resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.api_name}-vpc"
  }
}

resource "aws_subnet" "private" {
  count = local.create_vpc ? 2 : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.api_name}-private-${count.index}"
  }
}

resource "aws_route_table" "private" {
  count = local.create_vpc ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = {
    Name = "${var.api_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = local.create_vpc ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_security_group" "alb" {
  count = local.create_alb ? 1 : 0

  name   = "${var.api_name}-alb-sg"
  vpc_id = local.vpc_id

  ingress {
    from_port   = var.alb_listener_port
    to_port     = var.alb_listener_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "alb" {
  count = local.create_alb ? 1 : 0

  name               = "${var.api_name}-alb"
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb[0].id]
  subnets            = local.private_subnet_ids

  tags = {
    Name = "${var.api_name}-alb"
  }
}

resource "aws_lb" "nlb" {
  count = local.create_rest_vpc_link ? 1 : 0

  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  subnets            = local.private_subnet_ids

  tags = {
    Name = "${var.api_name}-nlb"
  }
}

resource "aws_lb_target_group" "nlb_tg" {
  count = local.create_rest_vpc_link ? 1 : 0

  name        = "${var.api_name}-nlb-tg"
  port        = var.alb_listener_port
  protocol    = "TCP"
  target_type = "alb"
  vpc_id      = local.vpc_id

  health_check_protocol = "HTTPS"
  health_check_port     = "traffic-port"
  health_check_path     = "/"
  health_check_matcher  = "200-399"

  tags = {
    Name = "${var.api_name}-nlb-tg"
  }
}

resource "aws_lb_target_group_attachment" "nlb_tg_attachment" {
  count = local.create_rest_vpc_link ? 1 : 0

  target_group_arn = aws_lb_target_group.nlb_tg[0].arn
  target_id        = local.alb_arn
  port             = var.alb_listener_port
}

resource "aws_lb_listener" "nlb_listener" {
  count = local.create_rest_vpc_link ? 1 : 0

  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.alb_listener_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_tg[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count = local.create_rest_vpc_link ? 1 : 0

  name        = "${var.api_name}-rest-vpc-link"
  target_arns = [aws_lb.nlb[0].arn]
}

resource "aws_apigatewayv2_vpc_link" "http" {
  count = local.create_http_vpc_link ? 1 : 0

  name       = "${var.api_name}-http-vpc-link"
  subnet_ids = local.private_subnet_ids
}

resource "aws_acm_certificate" "this" {
  count = local.create_acm ? 1 : 0

  domain_name       = var.domain_name
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "acm_validation" {
  for_each = local.create_acm && var.hosted_zone_id != "" ? { for dvo in aws_acm_certificate.this[0].domain_validation_options : dvo.domain_name => dvo } : {}

  zone_id         = var.hosted_zone_id
  name            = each.value.resource_record_name
  type            = each.value.resource_record_type
  records         = [each.value.resource_record_value]
  ttl             = 60
  allow_overwrite = true
}

resource "aws_acm_certificate_validation" "this" {
  count = local.create_acm && var.hosted_zone_id != "" ? 1 : 0

  certificate_arn         = aws_acm_certificate.this[0].arn
  validation_record_fqdns = [for record in aws_route53_record.acm_validation : record.fqdn]
}

resource "aws_apigatewayv2_api" "this" {
  count = var.api_type == "http" ? 1 : 0

  name          = var.api_name
  protocol_type = "HTTP"
}

resource "aws_apigatewayv2_stage" "this" {
  count = var.api_type == "http" ? 1 : 0

  api_id      = aws_apigatewayv2_api.this[0].id
  name        = "${var.environment}-stage"
  auto_deploy = true
}

resource "aws_apigatewayv2_integration" "http" {
  for_each = var.api_type == "http" ? { for r in var.http_routes : r.route_key => r } : {}

  api_id                 = aws_apigatewayv2_api.this[0].id
  integration_type       = each.value.integration_type
  integration_method     = "POST"
  integration_uri        = each.value.integration_type == "MOCK" ? null : each.value.integration_uri
  payload_format_version = "1.0"
}

resource "aws_apigatewayv2_route" "http" {
  for_each = var.api_type == "http" ? { for r in var.http_routes : r.route_key => r } : {}

  api_id    = aws_apigatewayv2_api.this[0].id
  route_key = each.value.route_key
  target    = "integrations/${aws_apigatewayv2_integration.http[each.key].id}"
}

resource "aws_apigatewayv2_domain_name" "http" {
  count = var.api_type == "http" && var.domain_name != "" ? 1 : 0

  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = local.acm_certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count = var.api_type == "http" && var.domain_name != "" ? 1 : 0

  api_id      = aws_apigatewayv2_api.this[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.this[0].name
}

resource "aws_route53_record" "http" {
  count = var.api_type == "http" && var.domain_name != "" && var.route53_record_enabled ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_api_gateway_rest_api" "this" {
  count = var.api_type == "rest" ? 1 : 0

  name = var.api_name

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  policy = var.rest_api_ip_whitelist_enabled ? data.aws_iam_policy_document.rest_api_policy[0].json : null
}

resource "aws_api_gateway_resource" "rest" {
  for_each = var.api_type == "rest" ? local.rest_unique_paths : toset([])

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  parent_id   = aws_api_gateway_rest_api.this[0].root_resource_id
  path_part   = each.value
}

resource "aws_api_gateway_method" "rest" {
  for_each = var.api_type == "rest" ? { for r in var.rest_routes : "${r.path}-${r.method}" => r } : {}

  rest_api_id   = aws_api_gateway_rest_api.this[0].id
  resource_id   = aws_api_gateway_resource.rest[each.value.path].id
  http_method   = each.value.method
  authorization = var.rest_lambda_authorizer_enabled ? "CUSTOM" : "NONE"
  authorizer_id = var.rest_lambda_authorizer_enabled ? aws_api_gateway_authorizer.rest[0].id : null

  request_parameters = each.value.request_parameters
}

resource "aws_api_gateway_integration" "rest" {
  for_each = var.api_type == "rest" ? { for r in var.rest_routes : "${r.path}-${r.method}" => r } : {}

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  resource_id = aws_api_gateway_resource.rest[each.value.path].id
  http_method = aws_api_gateway_method.rest[each.key].http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
}

resource "aws_api_gateway_method_response" "rest" {
  for_each = var.api_type == "rest" ? { for r in var.rest_routes : "${r.path}-${r.method}" => r } : {}

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  resource_id = aws_api_gateway_resource.rest[each.value.path].id
  http_method = aws_api_gateway_method.rest[each.key].http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "rest" {
  for_each = var.api_type == "rest" ? { for r in var.rest_routes : "${r.path}-${r.method}" => r } : {}

  rest_api_id = aws_api_gateway_rest_api.this[0].id
  resource_id = aws_api_gateway_resource.rest[each.value.path].id
  http_method = aws_api_gateway_method.rest[each.key].http_method
  status_code = aws_api_gateway_method_response.rest[each.key].status_code

  response_templates = {
    "application/json" = ""
  }
}

resource "aws_api_gateway_deployment" "rest" {
  count = var.api_type == "rest" ? 1 : 0

  depends_on = [
    aws_api_gateway_integration.rest,
    aws_api_gateway_method.rest
  ]

  rest_api_id = aws_api_gateway_rest_api.this[0].id

  triggers = {
    redeployment = sha1(jsonencode(concat([for k, v in aws_api_gateway_integration.rest : v.id], [var.rest_redeployment_trigger])))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count = var.api_type == "rest" ? 1 : 0

  depends_on = [aws_api_gateway_deployment.rest]

  stage_name    = "${var.environment}-stage"
  rest_api_id   = aws_api_gateway_rest_api.this[0].id
  deployment_id = aws_api_gateway_deployment.rest[0].id
}

resource "aws_api_gateway_usage_plan" "rest" {
  count = var.api_type == "rest" && var.rest_api_key_enabled ? 1 : 0

  name = "${var.api_name}-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.this[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  throttle_settings {
    burst_limit = 10
    rate_limit  = 100
  }
}

resource "aws_api_gateway_api_key" "rest" {
  count = var.api_type == "rest" && var.rest_api_key_enabled ? 1 : 0

  name        = "${var.api_name}-${var.environment}-key"
  description = "API key for ${var.api_name}"
  enabled     = true
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count = var.api_type == "rest" && var.rest_api_key_enabled ? 1 : 0

  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count = var.api_type == "rest" && var.rest_api_key_enabled ? 1 : 0

  name      = "/${var.api_name}/${var.environment}/api-key"
  type      = "SecureString"
  value     = aws_api_gateway_api_key.rest[0].value
  overwrite = true
}

resource "aws_iam_role" "lambda_authorizer" {
  count = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0

  name               = "${var.api_name}-authorizer-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

resource "aws_iam_role_policy_attachment" "lambda_authorizer" {
  count = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0

  role       = aws_iam_role.lambda_authorizer[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "authorizer" {
  count = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0

  function_name    = "${var.api_name}-authorizer"
  role             = aws_iam_role.lambda_authorizer[0].arn
  handler          = "index.handler"
  runtime          = "nodejs16.x"
  filename         = data.archive_file.lambda_authorizer[0].output_path
  source_code_hash = data.archive_file.lambda_authorizer[0].output_base64sha256
  timeout          = 10
}

resource "aws_iam_role" "api_gateway_invocation" {
  count = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0

  name               = "${var.api_name}-apigw-invocation-role"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json
}

resource "aws_iam_role_policy_attachment" "api_gateway_invocation" {
  count = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0

  role       = aws_iam_role.api_gateway_invocation[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_iam_role_policy" "api_gateway_invocation" {
  count = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0

  name = "${var.api_name}-apigw-invocation-policy"
  role = aws_iam_role.api_gateway_invocation[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:InvokeFunction"
        Resource = aws_lambda_function.authorizer[0].arn
      }
    ]
  })
}

resource "aws_lambda_permission" "apigw" {
  count = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0

  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[0].function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.this[0].execution_arn}/*/*"
}

resource "aws_api_gateway_authorizer" "rest" {
  count = var.api_type == "rest" && var.rest_lambda_authorizer_enabled ? 1 : 0

  name                   = "${var.api_name}-authorizer"
  rest_api_id            = aws_api_gateway_rest_api.this[0].id
  authorizer_uri         = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_credentials = aws_iam_role.api_gateway_invocation[0].arn
  identity_source        = "method.request.header.Authorization"
  type                   = "REQUEST"
}

resource "aws_api_gateway_domain_name" "rest" {
  count = var.api_type == "rest" && var.domain_name != "" ? 1 : 0

  domain_name              = var.domain_name
  regional_certificate_arn = local.acm_certificate_arn
  security_policy          = "TLS_1_2"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count = var.api_type == "rest" && var.domain_name != "" ? 1 : 0

  api_id      = aws_api_gateway_rest_api.this[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  domain_name = aws_api_gateway_domain_name.rest[0].domain_name
}

resource "aws_route53_record" "rest" {
  count = var.api_type == "rest" && var.domain_name != "" && var.route53_record_enabled ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# Terraform & providers
###############################################################################
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################
variable "region" {
  description = "AWS region in which the CloudTrail trail and supporting resources are deployed."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name used for the trail, log group, IAM role, KMS alias and (optionally) the log bucket."
  type        = string
  default     = "cloudtrail"
}

variable "s3_bucket_name" {
  description = "Explicit S3 bucket name for CloudTrail logs. When empty, a name is generated from the name, account ID, region and a random 8-character lowercase suffix."
  type        = string
  default     = ""
}

variable "s3_key_prefix" {
  description = "Optional S3 key prefix (folder) under which CloudTrail delivers log files."
  type        = string
  default     = ""
}

variable "s3_force_destroy" {
  description = "Whether to destroy all objects in the CloudTrail S3 bucket even if it is not empty."
  type        = bool
  default     = true
}

variable "s3_versioning_enabled" {
  description = "Enable versioning on the CloudTrail S3 bucket."
  type        = bool
  default     = false
}

variable "cloudwatch_log_retention_days" {
  description = "Retention period (in days) for the CloudTrail CloudWatch log group."
  type        = number
  default     = 90
}

variable "kms_deletion_window_in_days" {
  description = "Number of days before the CloudTrail KMS key is deleted after destruction."
  type        = number
  default     = 30
}

variable "kms_alias_prefix" {
  description = "Alias prefix used to build the KMS key alias (final alias is \"<prefix>/<name>\")."
  type        = string
  default     = "alias"
}

variable "kms_decrypt_role_arn" {
  description = "Optional IAM role ARN that is granted permission to decrypt CloudTrail log files with the KMS key."
  type        = string
  default     = ""
}

variable "enable_log_file_validation" {
  description = "Enable CloudTrail log file validation (digest files)."
  type        = bool
  default     = true
}

variable "include_global_service_events" {
  description = "Include global service events (e.g. IAM) in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail applies to all AWS regions."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enable logging for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an AWS Organizations trail (must be created in the management account)."
  type        = bool
  default     = false
}

variable "read_write_type" {
  description = "Type of events the event selector logs: All, ReadOnly or WriteOnly."
  type        = string
  default     = "All"
}

variable "include_management_events" {
  description = "Whether the event selector captures management events."
  type        = bool
  default     = true
}

variable "data_resources" {
  description = "Data resource selectors for the event selector, e.g. [{ type = \"AWS::S3::Object\", values = [\"arn:aws:s3:::bucket/\"] }]."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_types" {
  description = "CloudTrail insight types to enable (e.g. ApiCallRateInsight, ApiErrorRateInsight)."
  type        = list(string)
  default     = []
}

variable "create_sns_topic" {
  description = "Create a dedicated SNS topic for CloudTrail log delivery notifications (disabled by default)."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Existing SNS topic ARN to use for CloudTrail notifications when create_sns_topic is false."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources & locals
###############################################################################
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "random_string" "suffix" {
  length  = 8
  upper   = false
  numeric = false
  special = false
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = var.region

  bucket_name = var.s3_bucket_name != "" ? var.s3_bucket_name : "${var.name}-${local.account_id}-${local.region}-${random_string.suffix.result}"

  s3_key_prefix  = var.s3_key_prefix == "" ? "" : "${trim(var.s3_key_prefix, "/")}/"
  log_group_name = "/aws/cloudtrail/${var.name}"
  kms_alias_name = "${var.kms_alias_prefix}/${var.name}"

  sns_topic_arn  = var.create_sns_topic ? aws_sns_topic.this[0].arn : var.sns_topic_arn
  sns_topic_name = var.create_sns_topic ? aws_sns_topic.this[0].name : (var.sns_topic_arn != "" ? var.sns_topic_arn : null)
}

###############################################################################
# KMS key for CloudTrail log file encryption
###############################################################################
data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableIAMPoliciesForRootAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:Decrypt",
      "kms:ReEncrypt*",
    ]

    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.name}"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"]
    }
  }

  statement {
    sid    = "AllowS3BucketEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  dynamic "statement" {
    for_each = var.kms_decrypt_role_arn == "" ? [] : [var.kms_decrypt_role_arn]

    content {
      sid    = "AllowLogDecryptionRole"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:GenerateDataKey*",
      ]

      resources = ["*"]
    }
  }
}

resource "aws_kms_key" "this" {
  description             = "KMS key used to encrypt ${var.name} CloudTrail log files and related logs"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = merge(var.tags, { Name = "${var.name}-cloudtrail" })
}

resource "aws_kms_alias" "this" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.this.key_id
}

###############################################################################
# S3 bucket for CloudTrail log delivery
###############################################################################
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.s3_force_destroy

  tags = merge(var.tags, { Name = local.bucket_name })
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.s3_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.this.arn]

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this.arn}/${local.s3_key_prefix}AWSLogs/${local.account_id}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# CloudWatch log group for CloudTrail events
###############################################################################
resource "aws_cloudwatch_log_group" "this" {
  name              = local.log_group_name
  retention_in_days = var.cloudwatch_log_retention_days
  kms_key_id        = aws_kms_key.this.arn

  tags = merge(var.tags, { Name = local.log_group_name })
}

###############################################################################
# IAM role allowing CloudTrail to deliver events to CloudWatch Logs
###############################################################################
data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    sid     = "CloudTrailAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudwatch" {
  name               = "${var.name}-cloudtrail-cloudwatch-logs"
  description        = "Role assumed by CloudTrail to write events to CloudWatch Logs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "cloudwatch" {
  statement {
    sid    = "CloudTrailCreateLogStreamAndPutLogEvents"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.this.arn}:*"]
  }
}

resource "aws_iam_role_policy" "cloudwatch" {
  name   = "${var.name}-cloudtrail-cloudwatch-logs"
  role   = aws_iam_role.cloudwatch.id
  policy = data.aws_iam_policy_document.cloudwatch.json
}

###############################################################################
# Optional SNS topic for CloudTrail log delivery notifications
###############################################################################
resource "aws_sns_topic" "this" {
  count = var.create_sns_topic ? 1 : 0

  name = "${var.name}-cloudtrail-notifications"

  tags = var.tags
}

data "aws_iam_policy_document" "sns" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    sid    = "AllowCloudTrailPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.this[0].arn]

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create_sns_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.sns[0].json
}

###############################################################################
# CloudTrail trail
###############################################################################
resource "aws_cloudtrail" "this" {
  name           = var.name
  s3_bucket_name = aws_s3_bucket.this.id
  s3_key_prefix  = var.s3_key_prefix
  kms_key_id     = aws_kms_key.this.arn

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.this.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudwatch.arn

  enable_log_file_validation    = var.enable_log_file_validation
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail

  sns_topic_name = local.sns_topic_name

  event_selector {
    read_write_type           = var.read_write_type
    include_management_events = var.include_management_events

    dynamic "data_resource" {
      for_each = var.data_resources

      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_types

    content {
      insight_type = insight_selector.value
    }
  }

  tags = merge(var.tags, { Name = var.name })

  depends_on = [
    aws_s3_bucket_policy.this,
    aws_iam_role_policy.cloudwatch,
    aws_sns_topic_policy.this,
  ]
}

###############################################################################
# Outputs
###############################################################################
output "cloudtrail_id" {
  description = "Name of the CloudTrail trail."
  value       = aws_cloudtrail.this.id
}

output "cloudtrail_arn" {
  description = "ARN of the CloudTrail trail."
  value       = aws_cloudtrail.this.arn
}

output "cloudtrail_home_region" {
  description = "Region in which the trail was created."
  value       = aws_cloudtrail.this.home_region
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket storing CloudTrail logs."
  value       = aws_s3_bucket.this.id
}

output "s3_bucket_arn" {
  description = "ARN of the S3 bucket storing CloudTrail logs."
  value       = aws_s3_bucket.this.arn
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch log group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.this.name
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch log group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.this.arn
}

output "cloudtrail_cloudwatch_role_arn" {
  description = "ARN of the IAM role used by CloudTrail to write to CloudWatch Logs."
  value       = aws_iam_role.cloudwatch.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key used to encrypt CloudTrail logs."
  value       = aws_kms_key.this.arn
}

output "kms_key_id" {
  description = "ID of the KMS key used to encrypt CloudTrail logs."
  value       = aws_kms_key.this.key_id
}

output "kms_alias_name" {
  description = "Alias of the KMS key used to encrypt CloudTrail logs."
  value       = aws_kms_alias.this.name
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic used for CloudTrail notifications (created or supplied)."
  value       = local.sns_topic_arn
}

## Description

This Terraform configuration delivers **account-level, region-scoped EBS security hardening** for compliance testing. It consists of:

**Provider & Region Handling**
- An AWS provider whose `region` is driven by an optional `region` variable. When `var.region` is `null` (the default), the AWS provider falls back to its normal region resolution chain (`AWS_REGION` / `AWS_DEFAULT_REGION` environment variables, or the region configured in the active profile), so the module targets the "provider's current region" unless explicitly overridden.

**Variables (all with defaults)**
- `region` (default `null`) — optional explicit region override.
- `enable_ebs_security` (default `true`) — global master switch for all account-level EBS controls.
- `enable_ebs_encryption_by_default` (default `true`) — toggles default EBS encryption for the region.
- `enable_ebs_snapshot_block_public_access` (default `true`) — toggles the snapshot public-access block.
- `ebs_snapshot_block_public_access_state` (default `"block-all-sharing"`) — validated against the three AWS-supported values (`block-all-sharing`, `block-new-sharing`, `unblocked`).

**Resources**
- `aws_ebs_encryption_by_default` — enables encryption-by-default for newly created EBS volumes in the target region.
- `aws_ebs_snapshot_block_public_access` — blocks public sharing of EBS snapshots at the account/region level, honoring the configurable state.

Both resources are gated by `count` expressions that combine the global flag with their individual control flag, so each control can be independently disabled or disabled globally. Conditional `count` is used (rather than `enabled = var...`) so nothing is created unless it should be.

**Outputs (compliance evidence)**
- The effective target region, plus the applied encryption and snapshot-block states, useful for automated compliance assertions.

No IAM roles are required: these are account-level EBS settings applied via the AWS EC2 API by the caller's credentials, not resources that assume service roles.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Provider
# When var.region is null the AWS provider falls back to its standard region
# resolution chain (AWS_REGION / AWS_DEFAULT_REGION env var or profile region),
# i.e. the provider's "current" region.
# ---------------------------------------------------------------------------
provider "aws" {
  region = var.region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "region" {
  description = "Optional target AWS region for the account-level EBS settings. If left null, the provider's current region is used (AWS_REGION / AWS_DEFAULT_REGION environment variable or profile region)."
  type        = string
  default     = null
}

variable "enable_ebs_security" {
  description = "Global master switch for all account-level EBS security controls managed by this module."
  type        = bool
  default     = true
}

variable "enable_ebs_encryption_by_default" {
  description = "Enable EBS encryption by default for newly created volumes in the target region."
  type        = bool
  default     = true
}

variable "enable_ebs_snapshot_block_public_access" {
  description = "Enable the account-level block public access setting for EBS snapshots."
  type        = bool
  default     = true
}

variable "ebs_snapshot_block_public_access_state" {
  description = "The state of the EBS snapshot public access block setting: 'block-all-sharing', 'block-new-sharing', or 'unblocked'."
  type        = string
  default     = "block-all-sharing"

  validation {
    condition = contains(
      ["block-all-sharing", "block-new-sharing", "unblocked"],
      var.ebs_snapshot_block_public_access_state
    )
    error_message = "ebs_snapshot_block_public_access_state must be one of: block-all-sharing, block-new-sharing, unblocked."
  }
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Account-level EBS security controls
# ---------------------------------------------------------------------------

# Default EBS encryption for the region
resource "aws_ebs_encryption_by_default" "this" {
  count   = var.enable_ebs_security && var.enable_ebs_encryption_by_default ? 1 : 0
  enabled = true
}

# Account-level block public access for EBS snapshots
resource "aws_ebs_snapshot_block_public_access" "this" {
  count = var.enable_ebs_security && var.enable_ebs_snapshot_block_public_access ? 1 : 0
  state = var.ebs_snapshot_block_public_access_state
}

# ---------------------------------------------------------------------------
# Outputs (compliance evidence)
# ---------------------------------------------------------------------------
output "account_id" {
  description = "AWS account ID in which the EBS security settings are applied."
  value       = data.aws_caller_identity.current.account_id
}

output "target_region" {
  description = "Effective AWS region targeted by this configuration."
  value       = data.aws_region.current.name
}

output "ebs_security_enabled" {
  description = "Whether the global EBS security master switch is enabled."
  value       = var.enable_ebs_security
}

output "ebs_encryption_by_default_enabled" {
  description = "Whether EBS encryption by default is enforced in the target region."
  value       = length(aws_ebs_encryption_by_default.this) > 0
}

output "ebs_snapshot_block_public_access_state" {
  description = "Effective state of the account-level EBS snapshot block public access setting (null when disabled)."
  value = length(aws_ebs_snapshot_block_public_access.this) > 0 ? (
    aws_ebs_snapshot_block_public_access.this[0].state
  ) : null
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "deployment_user_name" {
  description = "Name of the IAM deployment user."
  type        = string
  default     = "DeploymentUser"
}

variable "tags" {
  description = "Optional tags to apply to the IAM user and policies."
  type        = map(string)
  default     = {}
}

variable "s3_bucket_arns" {
  description = "List of S3 bucket ARNs to grant artifact access to. If empty, no S3 policy is created."
  type        = list(string)
  default     = []
}

variable "s3_object_subpaths" {
  description = "Sub-paths within each S3 bucket to grant object permissions on. Defaults to all objects."
  type        = list(string)
  default     = ["*"]
}

variable "lambda_function_arns" {
  description = "List of Lambda function ARNs to grant UpdateFunctionCode permission to. If empty, no Lambda policy is created."
  type        = list(string)
  default     = []
}

variable "create_access_key" {
  description = "Whether to create an access key for the deployment user."
  type        = bool
  default     = false
}

locals {
  normalized_s3_bucket_arns = [
    for arn in var.s3_bucket_arns : trimsuffix(arn, "/")
  ]

  normalized_s3_object_subpaths = [
    for path in var.s3_object_subpaths :
    trimprefix(path, "/") == "" ? "*" : trimprefix(path, "/")
  ]

  s3_object_resource_arns = flatten([
    for bucket_arn in local.normalized_s3_bucket_arns : [
      for subpath in local.normalized_s3_object_subpaths :
      "${bucket_arn}/${subpath}"
    ]
  ])
}

resource "aws_iam_user" "deployment" {
  name = var.deployment_user_name
  path = "/"
  tags = var.tags
}

resource "aws_iam_policy" "s3" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0

  name        = "${var.deployment_user_name}-s3-policy"
  description = "S3 artifact access policy for ${var.deployment_user_name}"
  tags        = var.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketList"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = local.normalized_s3_bucket_arns
      },
      {
        Sid    = "S3ObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:GetObjectAcl",
          "s3:PutObjectAcl"
        ]
        Resource = local.s3_object_resource_arns
      }
    ]
  })
}

resource "aws_iam_policy" "lambda" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0

  name        = "${var.deployment_user_name}-lambda-policy"
  description = "Lambda update policy for ${var.deployment_user_name}"
  tags        = var.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LambdaUpdateFunctionCode"
        Effect = "Allow"
        Action = [
          "lambda:UpdateFunctionCode"
        ]
        Resource = var.lambda_function_arns
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "s3" {
  count = length(aws_iam_policy.s3) > 0 ? 1 : 0

  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.s3[0].arn
}

resource "aws_iam_user_policy_attachment" "lambda" {
  count = length(aws_iam_policy.lambda) > 0 ? 1 : 0

  user       = aws_iam_user.deployment.name
  policy_arn = aws_iam_policy.lambda[0].arn
}

resource "aws_iam_access_key" "deployment" {
  count = var.create_access_key ? 1 : 0

  user = aws_iam_user.deployment.name
}

output "deployment_user_name" {
  description = "The name of the IAM deployment user."
  value       = aws_iam_user.deployment.name
}

output "deployment_user_arn" {
  description = "The ARN of the IAM deployment user."
  value       = aws_iam_user.deployment.arn
}

output "s3_policy_arn" {
  description = "The ARN of the S3 policy, if created."
  value       = try(aws_iam_policy.s3[0].arn, null)
}

output "lambda_policy_arn" {
  description = "The ARN of the Lambda policy, if created."
  value       = try(aws_iam_policy.lambda[0].arn, null)
}

output "access_key_id" {
  description = "The access key ID, if an access key was created."
  value       = try(aws_iam_access_key.deployment[0].id, null)
}

output "secret_access_key" {
  description = "The secret access key, if an access key was created."
  value       = try(aws_iam_access_key.deployment[0].secret, null)
  sensitive   = true
}

###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# CloudFront-scoped resources (ACM certificates and WAFv2 web ACLs with
# scope = CLOUDFRONT) must be created in us-east-1, regardless of the
# region the origin bucket lives in.
provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "Region used for the S3 origin bucket and general resources."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Prefix used for resource naming and tagging."
  type        = string
  default     = "webapp-template"
}

variable "bucket_name" {
  description = "Explicit S3 bucket name. Falls back to domain_name, then to an auto-generated name."
  type        = string
  default     = ""
}

variable "domain_name" {
  description = "Apex custom domain served by the CloudFront distribution. Empty string disables the custom-domain / ACM / Route 53 path."
  type        = string
  default     = ""
}

variable "hosted_zone_id" {
  description = "Route 53 public hosted zone ID used for certificate validation and alias records. Required when domain_name is set."
  type        = string
  default     = ""
}

variable "enable_www" {
  description = "Create the www.<domain_name> alias plus a wildcard certificate SAN."
  type        = bool
  default     = false
}

variable "enable_versioning" {
  description = "Enable S3 object versioning on the site bucket."
  type        = bool
  default     = false
}

variable "price_class" {
  description = "CloudFront price class."
  type        = string
  default     = "PriceClass_100"
}

variable "minimum_tls_version" {
  description = "Minimum TLS protocol version for the CloudFront distribution (SNI-only)."
  type        = string
  default     = "TLSv1.2_2021"
}

variable "force_destroy_bucket" {
  description = "Allow Terraform to destroy the bucket even when it contains objects."
  type        = bool
  default     = false
}

###############################################################################
# Data Sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

###############################################################################
# Random Suffixes
###############################################################################

# 8-byte (16 character) hexadecimal identifier used when the bucket name has
# to be generated automatically.
resource "random_id" "bucket_suffix" {
  byte_length = 8
}

# Short suffix so that globally/account scoped names (WAF, OAC) stay unique.
resource "random_id" "name_suffix" {
  byte_length = 4
}

###############################################################################
# Locals
###############################################################################

locals {
  has_domain  = var.domain_name != ""
  name_prefix = "${var.project_name}-${random_id.name_suffix.hex}"

  # bucket_name -> var.bucket_name -> var.domain_name -> "webapp-template-<8 byte hex>"
  bucket_name        = coalesce(var.bucket_name, var.domain_name, "${var.project_name}-${random_id.bucket_suffix.hex}")
  origin_id          = "s3-${local.bucket_name}"
  origin_domain_name = "${local.bucket_name}.s3.${var.aws_region}.amazonaws.com"

  aliases = local.has_domain ? (
    var.enable_www ? [var.domain_name, "www.${var.domain_name}"] : [var.domain_name]
  ) : []

  certificate_sans = local.has_domain && var.enable_www ? ["www.${var.domain_name}", "*.${var.domain_name}"] : null

  # Domains that need a DNS validation record. ACM reuses the apex record for
  # the wildcard, but listing every requested name keeps this idempotent
  # (allow_overwrite) and correct in all cases.
  validation_domains = local.has_domain ? (
    var.enable_www ? [var.domain_name, "www.${var.domain_name}", "*.${var.domain_name}"] : [var.domain_name]
  ) : []

  domain_validation_options = local.has_domain ? {
    for dvo in aws_acm_certificate.this[0].domain_validation_options : dvo.domain_name => dvo
  } : {}

  # Static (plan-time known) keys so that for_each is always resolvable;
  # only the map *values* come from the apply-time ACM response.
  validation_records = {
    for domain in local.validation_domains : domain => local.domain_validation_options[domain]
  }

  tags = {
    Project   = var.project_name
    ManagedBy = "Terraform"
  }
}

###############################################################################
# S3 Origin Bucket (private, SSE-KMS)
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy_bucket

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

###############################################################################
# Customer Managed KMS Key for the Origin Bucket
###############################################################################

resource "aws_kms_key" "this" {
  description             = "SSE-KMS key for the ${local.bucket_name} static site origin"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudFrontServicePrincipalDecrypt"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.this.arn
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# CloudFront Origin Access Control
###############################################################################

resource "aws_cloudfront_origin_access_control" "this" {
  name                              = "${local.name_prefix}-oac"
  description                       = "OAC for ${local.bucket_name}"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

###############################################################################
# WAFv2 (CloudFront scope, must live in us-east-1)
###############################################################################

resource "aws_wafv2_web_acl" "this" {
  provider = aws.us_east_1

  name  = "${local.name_prefix}-waf"
  scope = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${local.name_prefix}-waf"
    sampled_requests_enabled   = true
  }

  tags = local.tags
}

###############################################################################
# CloudFront Distribution
###############################################################################

resource "aws_cloudfront_distribution" "this" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "${var.project_name} static site"
  default_root_object = "index.html"
  price_class         = var.price_class
  aliases             = local.aliases
  web_acl_id          = aws_wafv2_web_acl.this.arn

  origin {
    domain_name              = local.origin_domain_name
    origin_id                = local.origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.this.id
  }

  default_cache_behavior {
    target_origin_id       = local.origin_id
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
  }

  # index.html must never be cached by the default (optimized) policy.
  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = local.origin_id
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_disabled.id
  }

  custom_error_response {
    error_code            = 403
    response_code         = 404
    response_page_path    = "/index.html"
    error_caching_min_ttl = 10
  }

  custom_error_response {
    error_code            = 404
    response_code         = 404
    response_page_path    = "/index.html"
    error_caching_min_ttl = 10
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = local.has_domain ? null : true
    acm_certificate_arn            = local.has_domain ? aws_acm_certificate_validation.this[0].certificate_arn : null
    ssl_support_method             = local.has_domain ? "sni-only" : null
    minimum_protocol_version       = local.has_domain ? var.minimum_tls_version : null
  }

  tags = local.tags
}

###############################################################################
# S3 Bucket Policy - only this CloudFront distribution may read objects
###############################################################################

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontServicePrincipalGetObject"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.this.arn
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# ACM Certificate (us-east-1) + DNS Validation
###############################################################################

resource "aws_acm_certificate" "this" {
  count    = local.has_domain ? 1 : 0
  provider = aws.us_east_1

  domain_name               = var.domain_name
  validation_method         = "DNS"
  subject_alternative_names = local.certificate_sans

  tags = local.tags

  lifecycle {
    create_before_destroy = true

    precondition {
      condition     = var.hosted_zone_id != ""
      error_message = "var.hosted_zone_id must be a non-empty Route 53 hosted zone ID when var.domain_name is configured."
    }
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = local.validation_records

  zone_id         = var.hosted_zone_id
  name            = each.value.resource_record_name
  type            = each.value.resource_record_type
  records         = [each.value.resource_record_value]
  ttl             = 60
  allow_overwrite = true
}

resource "aws_acm_certificate_validation" "this" {
  count    = local.has_domain ? 1 : 0
  provider = aws.us_east_1

  certificate_arn         = aws_acm_certificate.this[0].arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

###############################################################################
# Route 53 Alias Records for the Distribution
###############################################################################

resource "aws_route53_record" "alias" {
  for_each = toset(local.aliases)

  zone_id = var.hosted_zone_id
  name    = each.value
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.this.domain_name
    zone_id                = aws_cloudfront_distribution.this.hosted_zone_id
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the VPC and all supporting resources are created."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC. Subnet CIDRs are built by appending tier suffixes to the first two octets of this block."
  type        = string
  default     = "10.20.0.0/16"
}

variable "availability_zones" {
  description = "Comma separated list of availability zone names used to spread the subnet tiers."
  type        = string
  default     = "us-east-1a,us-east-1b,us-east-1c"
}

variable "multi_az_nat_gateway" {
  description = "Set to 1 to deploy one NAT gateway (and Elastic IP) per availability zone."
  type        = number
  default     = 1

  validation {
    condition     = contains([0, 1], var.multi_az_nat_gateway)
    error_message = "multi_az_nat_gateway must be either 0 or 1."
  }
}

variable "single_nat_gateway" {
  description = "Set to 1 to deploy a single shared NAT gateway (only used when multi_az_nat_gateway is 0)."
  type        = number
  default     = 0

  validation {
    condition     = contains([0, 1], var.single_nat_gateway)
    error_message = "single_nat_gateway must be either 0 or 1."
  }
}

variable "enable_s3_vpc_endpoint" {
  description = "When true, an S3 Gateway VPC endpoint is created and associated with every private route table."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Default global tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    "Author"     = "Fairwinds"
    "Managed By" = "Terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  az_list  = split(",", var.availability_zones)
  az_count = length(local.az_list)

  # "10.20.0.0/16" -> "10.20" so the documented subnet suffixes can be appended.
  cidr_prefix = join(".", slice(split(".", var.vpc_cidr), 0, 2))

  subnet_tiers = {
    admin = {
      suffixes = [".0.0/21", ".8.0/21", ".16.0/21"]
      public   = false
    }
    public = {
      suffixes = [".32.0/21", ".40.0/21", ".48.0/21"]
      public   = true
    }
    private_production = {
      suffixes = [".64.0/21", ".72.0/21", ".80.0/21"]
      public   = false
    }
    private_working = {
      suffixes = [".96.0/21", ".104.0/21", ".112.0/21"]
      public   = false
    }
  }

  # Flattened map of every subnet: key = "<tier>_az<N>".
  subnets = merge([
    for tier, cfg in local.subnet_tiers : {
      for idx, suffix in cfg.suffixes :
      "${tier}_az${idx + 1}" => {
        tier              = tier
        az_index          = idx
        availability_zone = local.az_list[idx % local.az_count]
        cidr_block        = "${local.cidr_prefix}${suffix}"
        is_public         = cfg.public
      }
    }
  ]...)

  # Which AZ indexes receive a NAT gateway.
  nat_az_indices = var.multi_az_nat_gateway == 1 ? range(local.az_count) : (var.single_nat_gateway == 1 ? [0] : [])

  nat_az_keys = { for i in local.nat_az_indices : tostring(i) => i }

  # Private route table index -> NAT gateway index (shared NAT falls back to az1).
  nat_routes = length(local.nat_az_indices) > 0 ? {
    for i in range(local.az_count) : tostring(i) => tostring(var.multi_az_nat_gateway == 1 ? i : 0)
  } : {}
}

###############################################################################
# VPC, Internet Gateway and Subnets
###############################################################################

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "vpc"
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "vpc"
  }
}

resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id                  = aws_vpc.this.id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = each.value.is_public

  tags = {
    Name = each.key
    Tier = each.value.tier
  }
}

###############################################################################
# Public routing (shared route table -> Internet Gateway)
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "public"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  for_each = { for k, s in local.subnets : k => s if s.is_public }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Private routing (one route table per AZ -> NAT gateway)
###############################################################################

resource "aws_route_table" "private" {
  for_each = { for idx, az in local.az_list : tostring(idx) => az }

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "private_az${tonumber(each.key) + 1}"
  }
}

resource "aws_route_table_association" "private" {
  for_each = { for k, s in local.subnets : k => s if !s.is_public }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[tostring(each.value.az_index)].id
}

###############################################################################
# NAT gateways + Elastic IPs (per AZ by default)
###############################################################################

resource "aws_eip" "nat" {
  for_each = local.nat_az_keys

  domain = "vpc"

  tags = {
    Name = "eip-nat-az${tonumber(each.key) + 1}"
  }
}

resource "aws_nat_gateway" "this" {
  for_each = local.nat_az_keys

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.this["public_az${tonumber(each.key) + 1}"].id

  tags = {
    Name = "nat-az${tonumber(each.key) + 1}"
  }

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route" "private_nat" {
  for_each = local.nat_routes

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[each.value].id
}

###############################################################################
# Optional S3 Gateway VPC Endpoint
###############################################################################

resource "aws_vpc_endpoint" "s3" {
  count = var.enable_s3_vpc_endpoint ? 1 : 0

  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [for rt in aws_route_table.private : rt.id]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "FullAccess"
        Effect    = "Allow"
        Principal = "*"
        Action    = "*"
        Resource  = "*"
      }
    ]
  })

  tags = {
    Name = "s3-gateway-endpoint"
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.this.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.this.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway attached to the VPC."
  value       = aws_internet_gateway.this.id
}

output "subnet_ids" {
  description = "Map of subnet name to subnet ID for all tiers and AZs."
  value       = { for k, s in aws_subnet.this : k => s.id }
}

output "public_subnet_ids" {
  description = "IDs of all public subnets."
  value       = [for k, s in aws_subnet.this : s.id if local.subnets[k].is_public]
}

output "private_route_table_ids" {
  description = "Map of AZ index to the dedicated private route table ID."
  value       = { for k, rt in aws_route_table.private : k => rt.id }
}

output "nat_gateway_ids" {
  description = "Map of AZ index to the NAT gateway ID."
  value       = { for k, ngw in aws_nat_gateway.this : k => ngw.id }
}

output "nat_gateway_public_ips" {
  description = "Map of AZ index to the NAT gateway public Elastic IP."
  value       = { for k, eip in aws_eip.nat : k => eip.public_ip }
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 Gateway VPC endpoint, or null when disabled."
  value       = try(aws_vpc_endpoint.s3[0].id, null)
}

###############################################################################
# Providers
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "tls_certificate" "github_actions" {
  url = "https://token.actions.githubusercontent.com"
}

###############################################################################
# Locals
###############################################################################

locals {
  # Two availability zones for the public and private subnets.
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  certificate_domain = "${var.project_name}.internal"

  # Connection string consumed by the application container.
  database_url = "postgresql://${var.db_username}:${var.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${var.db_name}"

  tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC and networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${var.project_name}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${var.project_name}-igw" })
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${var.project_name}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${var.project_name}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${var.project_name}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# No route to the internet: outbound traffic from private subnets stays in the VPC.
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${var.project_name}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "alb" {
  name        = "${var.project_name}-alb-sg"
  description = "Ingress to the internal load balancer from inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "HTTP from within the VPC (redirected to HTTPS)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound traffic only within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${var.project_name}-alb-sg" })
}

resource "aws_security_group" "app" {
  name        = "${var.project_name}-app-sg"
  description = "Application containers: reached only by the load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "All ports from the load balancer only"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound traffic only within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${var.project_name}-app-sg" })
}

resource "aws_security_group" "db" {
  name        = "${var.project_name}-db-sg"
  description = "PostgreSQL reachable only from the application containers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from the application containers"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  egress {
    description = "Outbound traffic only within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${var.project_name}-db-sg" })
}

###############################################################################
# Self signed certificate imported into ACM
###############################################################################

resource "tls_private_key" "app" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "app" {
  private_key_pem = tls_private_key.app.private_key_pem

  subject {
    common_name  = local.certificate_domain
    organization = "${var.project_name} internal"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "app" {
  domain_name      = local.certificate_domain
  private_key      = tls_private_key.app.private_key_pem
  certificate_body = tls_self_signed_cert.app.cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.tags, { Name = "${var.project_name}-cert" })
}

###############################################################################
# Internal application load balancer
###############################################################################

resource "aws_lb" "app" {
  name                       = substr("${var.project_name}-alb", 0, 32)
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = merge(local.tags, { Name = "${var.project_name}-alb" })
}

resource "aws_lb_target_group" "app" {
  name                 = substr("${var.project_name}-tg", 0, 32)
  port                 = var.container_port
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "ip"
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = var.health_check_path
    port                = "traffic-port"
    protocol            = "HTTP"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 3
    timeout             = 5
    interval            = 30
  }

  tags = merge(local.tags, { Name = "${var.project_name}-tg" })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.app.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.app.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }

  tags = merge(local.tags, { Name = "${var.project_name}-https-listener" })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.app.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.tags, { Name = "${var.project_name}-http-listener" })
}

###############################################################################
# ECS cluster, log group and IAM roles
###############################################################################

resource "aws_ecs_cluster" "main" {
  name = "${var.project_name}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = merge(local.tags, { Name = "${var.project_name}-cluster" })
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = ["FARGATE", "FARGATE_SPOT"]
}

resource "aws_cloudwatch_log_group" "app" {
  name              = "/ecs/${var.project_name}"
  retention_in_days = var.log_retention_days

  tags = merge(local.tags, { Name = "${var.project_name}-logs" })
}

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_execution" {
  name               = "${var.project_name}-ecs-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = merge(local.tags, { Name = "${var.project_name}-ecs-execution-role" })
}

resource "aws_iam_role_policy_attachment" "ecs_execution" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "ecs_task" {
  name               = "${var.project_name}-ecs-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = merge(local.tags, { Name = "${var.project_name}-ecs-task-role" })
}

###############################################################################
# ECS task definition and service
###############################################################################

resource "aws_ecs_task_definition" "app" {
  family                   = "${var.project_name}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = var.task_cpu
  memory                   = var.task_memory
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "app"
      image     = var.app_image
      essential = true

      portMappings = [
        {
          containerPort = var.container_port
          hostPort      = var.container_port
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "APP_PORT"
          value = tostring(var.container_port)
        },
        {
          name  = "DB_HOST"
          value = aws_db_instance.main.address
        },
        {
          name  = "DB_PORT"
          value = tostring(aws_db_instance.main.port)
        },
        {
          name  = "DB_NAME"
          value = var.db_name
        },
        {
          name  = "DB_USER"
          value = var.db_username
        },
        {
          name  = "DB_PASSWORD"
          value = var.db_password
        },
        {
          name  = "DATABASE_URL"
          value = local.database_url
        },
        {
          name  = "POSTGRES_CONNECTION_STRING"
          value = local.database_url
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.app.name
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "app"
        }
      }
    }
  ])

  tags = merge(local.tags, { Name = "${var.project_name}-task" })
}

resource "aws_ecs_service" "app" {
  name                              = "${var.project_name}-service"
  cluster                           = aws_ecs_cluster.main.id
  task_definition                   = aws_ecs_task_definition.app.arn
  desired_count                     = var.desired_count
  health_check_grace_period_seconds = 60

  # ~20% on-demand Fargate / ~80% Fargate Spot.
  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = var.on_demand_weight
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = var.spot_weight
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.app.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.app.arn
    container_name   = "app"
    container_port   = var.container_port
  }

  lifecycle {
    ignore_changes = [desired_count]
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http,
  ]

  tags = merge(local.tags, { Name = "${var.project_name}-service" })
}

###############################################################################
# Application Auto Scaling (CPU and memory target tracking, 2-4 tasks)
###############################################################################

resource "aws_appautoscaling_target" "ecs" {
  max_capacity       = var.max_capacity
  min_capacity       = var.min_capacity
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

resource "aws_appautoscaling_policy" "cpu" {
  name               = "${var.project_name}-cpu-target-tracking"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value       = var.cpu_target_value
    scale_in_cooldown  = 300
    scale_out_cooldown = 60
    disable_scale_in   = false

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
  }
}

resource "aws_appautoscaling_policy" "memory" {
  name               = "${var.project_name}-memory-target-tracking"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    target_value       = var.memory_target_value
    scale_in_cooldown  = 300
    scale_out_cooldown = 60
    disable_scale_in   = false

    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
  }
}

###############################################################################
# RDS PostgreSQL (private subnets, single AZ, encrypted)
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.tags, { Name = "${var.project_name}-db-subnet-group" })
}

resource "aws_db_instance" "main" {
  identifier             = "${var.project_name}-db"
  engine                 = "postgres"
  engine_version         = var.db_engine_version
  instance_class         = var.db_instance_class
  allocated_storage      = var.db_allocated_storage
  storage_type           = "gp3"
  storage_encrypted      = true
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  multi_az               = false
  publicly_accessible    = false
  skip_final_snapshot    = true
  deletion_protection    = false
  apply_immediately      = true
  backup_retention_period = 7

  tags = merge(local.tags, { Name = "${var.project_name}-db" })
}

###############################################################################
# Container registry
###############################################################################

resource "aws_ecr_repository" "app" {
  name                 = "${var.project_name}/app"
  image_tag_mutability = "IMMUTABLE"
  force_delete         = true

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = merge(local.tags, { Name = "${var.project_name}-app" })
}

resource "aws_ecr_lifecycle_policy" "app" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

###############################################################################
# GitHub Actions OIDC provider and CI/CD role
###############################################################################

resource "aws_iam_openid_connect_provider" "github_actions" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [data.tls_certificate.github_actions.certificates[0].sha1_fingerprint]

  tags = merge(local.tags, { Name = "${var.project_name}-github-actions" })
}

data "aws_iam_policy_document" "github_actions_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github_actions.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_org}/*:*"]
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name               = "${var.project_name}-github-actions-role"
  assume_role_policy = data.aws_iam_policy_document.github_actions_assume_role.json

  tags = merge(local.tags, { Name = "${var.project_name}-github-actions-role" })
}

data "aws_iam_policy_document" "github_actions" {
  statement {
    sid       = "EcrAuthorizationToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid    = "EcrPushAndPull"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer",
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "ecr:DescribeRepositories",
      "ecr:DescribeImages",
      "ecr:ListImages",
      "ecr:BatchDeleteImage",
    ]
    resources = [aws_ecr_repository.app.arn]
  }

  statement {
    sid    = "RegisterAndCleanUpTaskDefinitions"
    effect = "Allow"
    actions = [
      "ecs:RegisterTaskDefinition",
      "ecs:DescribeTaskDefinition",
      "ecs:ListTaskDefinitions",
      "ecs:ListTaskDefinitionFamilies",
      "ecs:DeregisterTaskDefinition",
      "ecs:DeleteTaskDefinitions",
      "ecs:TagResource",
      "ecs:ListTagsForResource",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "UpdateService"
    effect = "Allow"
    actions = [
      "ecs:UpdateService",
      "ecs:DescribeServices",
      "ecs:DescribeClusters",
      "ecs:ListClusters",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "PassEcsTaskRoles"
    effect = "Allow"
    actions = [
      "iam:PassRole",
    ]
    resources = [
      aws_iam_role.ecs_execution.arn,
      aws_iam_role.ecs_task.arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "github_actions" {
  name        = "${var.project_name}-github-actions-policy"
  description = "Permissions used by GitHub Actions to build, push and deploy the application"
  policy      = data.aws_iam_policy_document.github_actions.json

  tags = merge(local.tags, { Name = "${var.project_name}-github-actions-policy" })
}

resource "aws_iam_role_policy_attachment" "github_actions" {
  role       = aws_iam_role.github_actions.name
  policy_arn = aws_iam_policy.github_actions.arn
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region to deploy the platform into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to every resource created by this stack."
  type        = string
  default     = "web-backend"
}

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "prod"
}

variable "vpc_cidr" {
  description = "CIDR block for the new VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the two public subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the two private subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.12.0/24"]
}

variable "container_port" {
  description = "Port the application container listens on and the ALB forwards to."
  type        = number
  default     = 80
}

variable "health_check_path" {
  description = "Path used by the target group health check."
  type        = string
  default     = "/"
}

variable "app_image" {
  description = "Container image for the application (placeholder until CI/CD takes over)."
  type        = string
  default     = "nginx:latest"
}

variable "task_cpu" {
  description = "CPU units for the Fargate task definition."
  type        = number
  default     = 512
}

variable "task_memory" {
  description = "Memory (MiB) for the Fargate task definition."
  type        = number
  default     = 1024
}

variable "desired_count" {
  description = "Initial number of running tasks (autoscaling takes over afterwards)."
  type        = number
  default     = 2
}

variable "min_capacity" {
  description = "Minimum number of tasks kept by application auto scaling."
  type        = number
  default     = 2
}

variable "max_capacity" {
  description = "Maximum number of tasks allowed by application auto scaling."
  type        = number
  default     = 4
}

variable "cpu_target_value" {
  description = "Target average CPU utilization (percent) for target tracking scaling."
  type        = number
  default     = 70
}

variable "memory_target_value" {
  description = "Target average memory utilization (percent) for target tracking scaling."
  type        = number
  default     = 80
}

variable "on_demand_weight" {
  description = "Weight of on-demand Fargate capacity in the capacity provider strategy."
  type        = number
  default     = 1
}

variable "spot_weight" {
  description = "Weight of Fargate Spot capacity in the capacity provider strategy."
  type        = number
  default     = 4
}

variable "db_name" {
  description = "Name of the PostgreSQL database created for the application."
  type        = string
  default     = "mydb"
}

variable "db_username" {
  description = "Master username for the PostgreSQL instance."
  type        = string
  default     = "postgres"
}

variable "db_password" {
  description = "Master password for the PostgreSQL instance (bootstrap only)."
  type        = string
  default     = "postgres"
  sensitive   = true
}

variable "db_instance_class" {
  description = "Instance class for the PostgreSQL instance."
  type        = string
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage (GiB) for the PostgreSQL instance."
  type        = number
  default     = 20
}

variable "db_engine_version" {
  description = "PostgreSQL major engine version for the RDS instance."
  type        = string
  default     = "15"
}

variable "log_retention_days" {
  description = "Retention of the application CloudWatch log group."
  type        = number
  default     = 30
}

variable "github_org" {
  description = "GitHub organization or account allowed to assume the CI/CD role."
  type        = string
  default     = "my-github-org"
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "alb_dns_name" {
  description = "DNS name of the internal application load balancer."
  value       = aws_lb.app.dns_name
}

output "ecr_repository_url" {
  description = "URL of the application container registry."
  value       = aws_ecr_repository.app.repository_url
}

output "ecs_cluster_name" {
  description = "Name of the ECS cluster."
  value       = aws_ecs_cluster.main.name
}

output "ecs_service_name" {
  description = "Name of the ECS service."
  value       = aws_ecs_service.app.name
}

output "rds_endpoint" {
  description = "Connection endpoint of the PostgreSQL instance."
  value       = aws_db_instance.main.endpoint
  sensitive   = true
}

output "github_actions_role_arn" {
  description = "ARN of the role assumed by GitHub Actions via OIDC."
  value       = aws_iam_role.github_actions.arn
}

## Description

This Terraform configuration provisions a self-contained security and identity foundation for a HashiStack (Consul / Nomad / Vault) cluster on AWS. It consists of:

**Inputs** — `cluster_tag` (default `"default"`) used to namespace every resource; `enable_key_rotation` (default `false`) controlling the KMS annual rotation setting; and `machine_roles`, a `map(set(string))` binding role names (e.g. `consul-server`, `nomad-client`) to the sets of policy identifiers they should receive.

**Encryption** — An `aws_kms_key` for Vault unsealing with description `resinstack:vault:seal:{cluster_tag}`, annual (365-day) rotation gated on `enable_key_rotation`, and the `resinstack:cluster` tag.

**Secrets** — Seven `aws_secretsmanager_secret` entries named `resinstack-{name}-{cluster_tag}` for `consul-agent-token`, `consul-gossip-key`, `nomad-client-consul-token`, `nomad-gossip-key`, `nomad-server-consul-token`, `nomad-vault-token`, and `vault-consul-token`, each tagged with the cluster.

**IAM policies** — A Vault KMS policy (`kms:Encrypt`, `kms:Decrypt`, `kms:DescribeKey` scoped to the seal key ARN), a `ResinStackReadTags` policy (`ec2:DescribeInstances`), and four Secrets Manager read policies scoped to the exact secret ARNs required by clients, Nomad servers, Consul servers, and Vault servers.

**Machine roles** — A dynamic `for_each` over `machine_roles` creates EC2-assumable IAM roles with a 43,200-second (12-hour) maximum session duration plus matching instance profiles, both named `resinstack-{role}-{cluster_tag}`. Policy attachments are generated dynamically: only identifiers present in a role's set (`read-tags`, `vault-kms`, `nomad-keys`, `consul-keys`, `vault-keys`, `client-keys`) are attached.

**Outputs** — The Vault KMS key ID, a map of Secrets Manager secret names, and maps of generated machine role names and instance profile names.

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the HashiStack security foundation is deployed."
  type        = string
  default     = "us-east-1"
}

variable "cluster_tag" {
  description = "Identifier used to namespace and tag all HashiStack resources."
  type        = string
  default     = "default"
}

variable "enable_key_rotation" {
  description = "Enable annual (365 day) automatic rotation of the Vault seal KMS key."
  type        = bool
  default     = false
}

variable "machine_roles" {
  description = <<-EOT
    Map of machine role name to the set of policy identifiers that role requires.
    Supported identifiers: "read-tags", "vault-kms", "nomad-keys",
    "consul-keys", "vault-keys", "client-keys".
  EOT
  type        = map(set(string))
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  # Logical secret names used by the HashiStack control plane.
  secret_names = [
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token",
  ]

  # Map of logical name -> fully qualified Secrets Manager secret name.
  secret_full_names = {
    for name in local.secret_names :
    name => "resinstack-${name}-${var.cluster_tag}"
  }

  # Which secrets each Secrets Manager policy identifier grants access to.
  secret_policy_sets = {
    "client-keys" = [
      "consul-agent-token",
      "consul-gossip-key",
      "nomad-client-consul-token",
    ]
    "nomad-keys" = [
      "consul-agent-token",
      "consul-gossip-key",
      "nomad-gossip-key",
      "nomad-server-consul-token",
      "nomad-vault-token",
    ]
    "consul-keys" = [
      "consul-gossip-key",
    ]
    "vault-keys" = [
      "consul-gossip-key",
      "vault-consul-token",
    ]
  }

  # Flattened list of (role, policy identifier) pairs for policy attachment.
  machine_role_policy_pairs = flatten([
    for role_name, policies in var.machine_roles : [
      for policy_id in policies : {
        role_name = role_name
        policy_id = policy_id
      }
    ]
  ])

  # Lookup table of policy identifier -> ARN.
  policy_arns = {
    "read-tags"   = aws_iam_policy.read_tags.arn
    "vault-kms"   = aws_iam_policy.vault_kms.arn
    "nomad-keys"  = aws_iam_policy.secrets["nomad-keys"].arn
    "consul-keys" = aws_iam_policy.secrets["consul-keys"].arn
    "vault-keys"  = aws_iam_policy.secrets["vault-keys"].arn
    "client-keys" = aws_iam_policy.secrets["client-keys"].arn
  }
}

###############################################################################
# KMS key used for Vault unsealing
###############################################################################

resource "aws_kms_key" "vault_seal" {
  description             = "resinstack:vault:seal:${var.cluster_tag}"
  deletion_window_in_days = 7
  enable_key_rotation     = var.enable_key_rotation
  rotation_period_in_days = var.enable_key_rotation ? 365 : null

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_kms_alias" "vault_seal" {
  name          = "alias/resinstack-vault-seal-${var.cluster_tag}"
  target_key_id = aws_kms_key.vault_seal.key_id
}

###############################################################################
# Secrets Manager secrets for HashiStack tokens and keys
###############################################################################

resource "aws_secretsmanager_secret" "hashistack" {
  for_each = local.secret_full_names

  name                    = each.value
  description             = "HashiStack ${each.key} for cluster ${var.cluster_tag}"
  recovery_window_in_days = 0

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

###############################################################################
# IAM policy: unseal Vault via KMS
###############################################################################

resource "aws_iam_policy" "vault_kms" {
  name        = "resinstack-vault-kms-${var.cluster_tag}"
  description = "Permit encrypting/decrypting/describing the Vault seal KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:DescribeKey",
        ]
        Resource = aws_kms_key.vault_seal.arn
      }
    ]
  })

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

###############################################################################
# IAM policy: describe EC2 instances and read their tags
###############################################################################

resource "aws_iam_policy" "read_tags" {
  name        = "ResinStackReadTags"
  description = "Permit describing EC2 instances so cluster members can be discovered"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2:DescribeInstances"]
        Resource = "*"
      }
    ]
  })

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

###############################################################################
# IAM policies: read secrets from Secrets Manager
###############################################################################

resource "aws_iam_policy" "secrets" {
  for_each = local.secret_policy_sets

  name        = "resinstack-${each.key}-${var.cluster_tag}"
  description = "Permit reading the ${each.key} secrets for cluster ${var.cluster_tag}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
        ]
        Resource = [
          for secret_name in each.value :
          aws_secretsmanager_secret.hashistack[secret_name].arn
        ]
      }
    ]
  })

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

###############################################################################
# EC2 assume role policy document
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

###############################################################################
# Machine roles and instance profiles
###############################################################################

resource "aws_iam_role" "machine" {
  for_each = var.machine_roles

  name                 = "resinstack-${each.key}-${var.cluster_tag}"
  description          = "ResinStack machine role '${each.key}' for cluster ${var.cluster_tag}"
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 43200

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

resource "aws_iam_role_policy_attachment" "machine" {
  for_each = {
    for pair in local.machine_role_policy_pairs :
    "${pair.role_name}:${pair.policy_id}" => pair
    if contains(keys(local.policy_arns), pair.policy_id)
  }

  role       = aws_iam_role.machine[each.value.role_name].name
  policy_arn = local.policy_arns[each.value.policy_id]
}

resource "aws_iam_instance_profile" "machine" {
  for_each = var.machine_roles

  name = "resinstack-${each.key}-${var.cluster_tag}"
  role = aws_iam_role.machine[each.key].name

  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

###############################################################################
# Outputs
###############################################################################

output "vault_kms_key_id" {
  description = "Key ID of the KMS key used for Vault unsealing."
  value       = aws_kms_key.vault_seal.key_id
}

output "vault_kms_key_arn" {
  description = "ARN of the KMS key used for Vault unsealing."
  value       = aws_kms_key.vault_seal.arn
}

output "secret_names" {
  description = "Map of logical secret name to the Secrets Manager secret name."
  value       = { for name, secret in aws_secretsmanager_secret.hashistack : name => secret.name }
}

output "secret_arns" {
  description = "Map of logical secret name to the Secrets Manager secret ARN."
  value       = { for name, secret in aws_secretsmanager_secret.hashistack : name => secret.arn }
}

output "machine_role_names" {
  description = "Map of machine role name to the generated IAM role name."
  value       = { for role_name, role in aws_iam_role.machine : role_name => role.name }
}

output "machine_role_arns" {
  description = "Map of machine role name to the generated IAM role ARN."
  value       = { for role_name, role in aws_iam_role.machine : role_name => role.arn }
}

output "machine_instance_profile_names" {
  description = "Map of machine role name to the generated instance profile name."
  value       = { for role_name, profile in aws_iam_instance_profile.machine : role_name => profile.name }
}
```

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the networking stack."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment / project prefix applied to all resource names and tags."
  type        = string
  default     = "elluis_codes_limited_network"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "64.0.0.0/16"
}

variable "availability_zones" {
  description = "Map of availability zone name to the 8-bit subnet offset used for the public subnet in that AZ."
  type        = map(number)
  default = {
    "us-east-1a" = 11
    "us-east-1b" = 22
    "us-east-1c" = 33
  }
}

variable "private_subnet_offset" {
  description = "Value added to each AZ offset to derive the private subnet range, keeping public and private ranges distinct."
  type        = number
  default     = 100
}

###############################################################################
# Locals
###############################################################################

locals {
  # Public subnets: cidrsubnet(vpc_cidr, 8, az_offset)  -> e.g. 64.0.11.0/24
  public_subnet_cidrs = {
    for az, offset in var.availability_zones :
    az => cidrsubnet(var.vpc_cidr, 8, offset)
  }

  # Private subnets: shifted offsets ensure no overlap with public ranges
  private_subnet_cidrs = {
    for az, offset in var.availability_zones :
    az => cidrsubnet(var.vpc_cidr, 8, offset + var.private_subnet_offset)
  }

  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Project     = "blog-web-application"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true
  enable_classiclink   = false

  tags = merge(local.common_tags, {
    Name = var.environment
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  for_each = var.availability_zones

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[each.key]
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-${each.key}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  for_each = var.availability_zones

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[each.key]
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-${each.key}"
    Tier = "private"
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-igw"
  })
}

###############################################################################
# Public routing (per AZ)
###############################################################################

resource "aws_route_table" "public" {
  for_each = var.availability_zones

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-rt-${each.key}"
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  for_each = var.availability_zones

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[each.key].id

  lifecycle {
    ignore_changes = [route_table_id]
  }
}

###############################################################################
# NAT gateways (one per AZ) with Elastic IPs
###############################################################################

resource "aws_eip" "nat" {
  for_each = var.availability_zones

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-eip-${each.key}"
  })
}

resource "aws_nat_gateway" "main" {
  for_each = var.availability_zones

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-${each.key}"
  })

  depends_on = [aws_internet_gateway.main]

  lifecycle {
    ignore_changes = [subnet_id]
  }
}

###############################################################################
# Private routing (per AZ, egress through the NAT gateway in the same AZ)
###############################################################################

resource "aws_route_table" "private" {
  for_each = var.availability_zones

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[each.key].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-rt-${each.key}"
    Tier = "private"
  })
}

resource "aws_route_table_association" "private" {
  for_each = var.availability_zones

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id

  lifecycle {
    ignore_changes = [route_table_id]
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "public_subnet_ids" {
  description = "Map of availability zone to public subnet ID."
  value       = { for az, subnet in aws_subnet.public : az => subnet.id }
}

output "private_subnet_ids" {
  description = "Map of availability zone to private subnet ID."
  value       = { for az, subnet in aws_subnet.private : az => subnet.id }
}

output "public_route_table_ids" {
  description = "Map of availability zone to public route table ID."
  value       = { for az, rt in aws_route_table.public : az => rt.id }
}

output "private_route_table_ids" {
  description = "Map of availability zone to private route table ID."
  value       = { for az, rt in aws_route_table.private : az => rt.id }
}

output "nat_gateway_ids" {
  description = "Map of availability zone to NAT Gateway ID."
  value       = { for az, nat in aws_nat_gateway.main : az => nat.id }
}

output "nat_elastic_ip_addresses" {
  description = "Map of availability zone to the public Elastic IP address of the NAT Gateway."
  value       = { for az, eip in aws_eip.nat : az => eip.public_ip }
}

###############################################################################
# Terraform and provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the EFS file system and its supporting resources are created."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name used for the EFS file system and for tagging supporting resources."
  type        = string
  default     = "efs-shared-storage"
}

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

variable "creation_token" {
  description = "Unique, idempotency token for the EFS file system."
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "EFS performance mode (generalPurpose or maxIO)."
  type        = string
  default     = "generalPurpose"

  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "performance_mode must be either generalPurpose or maxIO."
  }
}

variable "throughput_mode" {
  description = "EFS throughput mode (bursting, provisioned or elastic)."
  type        = string
  default     = "bursting"

  validation {
    condition     = contains(["bursting", "provisioned", "elastic"], var.throughput_mode)
    error_message = "throughput_mode must be one of bursting, provisioned or elastic."
  }
}

variable "provisioned_throughput_in_mibps" {
  description = "Provisioned throughput in MiB/s; only used when throughput_mode is \"provisioned\"."
  type        = number
  default     = null

  validation {
    condition     = var.provisioned_throughput_in_mibps == null || (var.provisioned_throughput_in_mibps >= 1 && var.provisioned_throughput_in_mibps <= 1024)
    error_message = "provisioned_throughput_in_mibps must be between 1 and 1024 when supplied."
  }
}

variable "encrypted" {
  description = "Whether the EFS file system is encrypted at rest with the dedicated KMS key."
  type        = bool
  default     = true
}

variable "transition_to_ia" {
  description = "Lifecycle policy rule that moves files to the Infrequent Access storage class."
  type        = string
  default     = "AFTER_30_DAYS"

  validation {
    condition = contains([
      "AFTER_7_DAYS",
      "AFTER_14_DAYS",
      "AFTER_30_DAYS",
      "AFTER_60_DAYS",
      "AFTER_90_DAYS",
      "AFTER_180_DAYS",
      "AFTER_270_DAYS",
      "AFTER_365_DAYS",
    ], var.transition_to_ia)
    error_message = "transition_to_ia must be a valid EFS lifecycle policy value."
  }
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (in days) before the dedicated KMS key is destroyed."
  type        = number
  default     = 7

  validation {
    condition     = var.kms_deletion_window_in_days >= 7 && var.kms_deletion_window_in_days <= 30
    error_message = "kms_deletion_window_in_days must be between 7 and 30."
  }
}

variable "subnet_ids" {
  description = "Subnet IDs that host the EFS mount targets. Leave empty to have a VPC and subnets created."
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "Security group IDs attached to the EFS mount targets. Leave empty to have one created."
  type        = list(string)
  default     = []
}

variable "vpc_id" {
  description = "VPC ID used when a security group has to be created while subnet_ids are supplied."
  type        = string
  default     = ""
}

variable "vpc_cidr_block" {
  description = "CIDR block of the VPC created when subnet_ids is empty."
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zone_count" {
  description = "Number of subnets (and therefore mount targets) created when subnet_ids is empty."
  type        = number
  default     = 2

  validation {
    condition     = var.availability_zone_count >= 1 && var.availability_zone_count <= 10
    error_message = "availability_zone_count must be between 1 and 10."
  }
}

variable "nfs_allowed_cidr_blocks" {
  description = "CIDR blocks allowed to reach the mount targets over NFS (TCP/2049) when the security group is created."
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

###############################################################################
# Locals
###############################################################################

locals {
  # Create the network only when no subnets are supplied by the caller.
  create_network = length(var.subnet_ids) == 0

  # Create a security group only when none are supplied by the caller.
  create_sg = length(var.security_group_ids) == 0

  # Subnets that will host the mount targets.
  subnet_ids = local.create_network ? aws_subnet.this[*].id : var.subnet_ids

  # Security groups attached to the mount targets.
  security_group_ids = local.create_sg ? aws_security_group.this[*].id : var.security_group_ids

  # VPC used for the security group: created VPC, explicit vpc_id, or the VPC
  # of the supplied subnets.
  vpc_id = local.create_network ? one(aws_vpc.this[*].id) : (
    var.vpc_id != "" ? var.vpc_id : one([for s in data.aws_subnet.provided : s.vpc_id])
  )

  # Plan-time known number of mount targets (works with newly created subnets).
  mount_target_count = local.create_network ? var.availability_zone_count : length(var.subnet_ids)

  common_tags = merge(
    {
      Name        = var.name
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.tags
  )
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# Resolve the VPC of any caller-supplied subnet so a security group can be
# created in the correct VPC when none is provided.
data "aws_subnet" "provided" {
  for_each = toset(var.subnet_ids)
  id       = each.value
}

###############################################################################
# KMS key dedicated to EFS encryption
###############################################################################

data "aws_iam_policy_document" "efs_key" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEfsToUseTheKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["elasticfilesystem.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "efs" {
  description             = "Dedicated KMS key used to encrypt the ${var.name} EFS file system"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.efs_key.json

  tags = merge(local.common_tags, { Name = "${var.name}-kms" })
}

resource "aws_kms_alias" "efs" {
  name          = "alias/${var.name}-efs"
  target_key_id = aws_kms_key.efs.key_id
}

###############################################################################
# Fallback network (only created when no subnet_ids are supplied)
###############################################################################

resource "aws_vpc" "this" {
  count = local.create_network ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${var.name}-vpc" })
}

resource "aws_subnet" "this" {
  count = local.create_network ? var.availability_zone_count : 0

  vpc_id            = aws_vpc.this[0].id
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  cidr_block        = cidrsubnet(var.vpc_cidr_block, 8, count.index)

  tags = merge(local.common_tags, { Name = "${var.name}-subnet-${count.index}" })
}

###############################################################################
# Security group for the mount targets (only created when none are supplied)
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_sg ? 1 : 0

  name        = "${var.name}-efs-mount-targets"
  description = "NFS access to the EFS mount targets managed by Terraform"
  vpc_id      = local.vpc_id

  ingress {
    description = "NFS from allowed networks"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = var.nfs_allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${var.name}-efs-mount-targets" })
}

###############################################################################
# Encrypted EFS file system
###############################################################################

resource "aws_efs_file_system" "this" {
  creation_token = var.creation_token
  encrypted      = var.encrypted
  kms_key_id     = var.encrypted ? aws_kms_key.efs.arn : null

  performance_mode                = var.performance_mode
  throughput_mode                 = var.throughput_mode
  provisioned_throughput_in_mibps = var.throughput_mode == "provisioned" ? var.provisioned_throughput_in_mibps : null

  lifecycle_policy {
    transition_to_ia = var.transition_to_ia
  }

  tags = merge(local.common_tags, { Name = var.name })
}

###############################################################################
# Mount targets, one per supplied (or created) subnet
###############################################################################

resource "aws_efs_mount_target" "this" {
  count = local.mount_target_count

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = local.subnet_ids[count.index]
  security_groups = local.security_group_ids
}

###############################################################################
# Outputs
###############################################################################

output "efs_file_system_id" {
  description = "ID of the EFS file system."
  value       = aws_efs_file_system.this.id
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system."
  value       = aws_efs_file_system.this.arn
}

output "efs_dns_name" {
  description = "DNS name that clients use to mount the EFS file system."
  value       = aws_efs_file_system.this.dns_name
}

output "kms_key_arn" {
  description = "ARN of the dedicated KMS key used for EFS encryption."
  value       = aws_kms_key.efs.arn
}

output "kms_key_id" {
  description = "ID of the dedicated KMS key used for EFS encryption."
  value       = aws_kms_key.efs.key_id
}

output "kms_key_alias" {
  description = "Alias of the dedicated KMS key used for EFS encryption."
  value       = aws_kms_alias.efs.name
}

output "mount_target_ids" {
  description = "IDs of the provisioned EFS mount targets."
  value       = aws_efs_mount_target.this[*].id
}

output "mount_target_subnet_ids" {
  description = "Subnet IDs hosting the EFS mount targets."
  value       = local.subnet_ids
}

output "mount_target_security_group_ids" {
  description = "Security group IDs attached to the EFS mount targets."
  value       = local.security_group_ids
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the cert-manager IAM credential stack"
  type        = string
  default     = "us-east-1"
}

variable "iam_user_name" {
  description = "Name of the IAM user used by cert-manager"
  type        = string
  default     = "cert-manager"
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID that cert-manager may manage; use * to allow all hosted zones"
  type        = string
  default     = "*"
}

variable "ssm_access_key_parameter_name" {
  description = "SSM Parameter Store name for the IAM access key ID"
  type        = string
  default     = "/cert-manager/access-key"
}

variable "ssm_secret_key_parameter_name" {
  description = "SSM Parameter Store name for the IAM secret access key"
  type        = string
  default     = "/cert-manager/secret-key"
}

data "aws_iam_policy_document" "cert_manager_route53" {
  statement {
    sid    = "GetChange"
    effect = "Allow"

    actions = [
      "route53:GetChange"
    ]

    resources = [
      "arn:aws:route53:::change/*"
    ]
  }

  statement {
    sid    = "ManageRecordSetsInHostedZone"
    effect = "Allow"

    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:ListResourceRecordSets"
    ]

    resources = [
      "arn:aws:route53:::hostedzone/${var.hosted_zone_id}"
    ]
  }

  statement {
    sid    = "ListHostedZonesByName"
    effect = "Allow"

    actions = [
      "route53:ListHostedZonesByName"
    ]

    resources = [
      "*"
    ]
  }
}

resource "aws_iam_user" "cert_manager" {
  name = var.iam_user_name

  tags = {
    Name        = var.iam_user_name
    Application = "cert-manager"
  }
}

resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name
}

resource "aws_ssm_parameter" "access_key" {
  name        = var.ssm_access_key_parameter_name
  description = "cert-manager IAM access key ID"
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.id
  overwrite   = true

  tags = {
    Name        = var.ssm_access_key_parameter_name
    Application = "cert-manager"
  }
}

resource "aws_ssm_parameter" "secret_key" {
  name        = var.ssm_secret_key_parameter_name
  description = "cert-manager IAM secret access key"
  type        = "SecureString"
  value       = aws_iam_access_key.cert_manager.secret
  overwrite   = true

  tags = {
    Name        = var.ssm_secret_key_parameter_name
    Application = "cert-manager"
  }
}

output "cert_manager_iam_user_name" {
  description = "Name of the cert-manager IAM user"
  value       = aws_iam_user.cert_manager.name
}

output "cert_manager_access_key_ssm_parameter" {
  description = "SSM parameter name containing the cert-manager access key ID"
  value       = aws_ssm_parameter.access_key.name
}

output "cert_manager_secret_key_ssm_parameter" {
  description = "SSM parameter name containing the cert-manager secret access key"
  value       = aws_ssm_parameter.secret_key.name
}

output "cert_manager_route53_policy_document_json" {
  description = "IAM policy document JSON for cert-manager Route 53 permissions (defined, not attached)"
  value       = data.aws_iam_policy_document.cert_manager_route53.json
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

################################################################################
# Providers
################################################################################

provider "aws" {
  region = var.region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

################################################################################
# Data Sources & Locals
################################################################################

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Create supporting KMS + S3 infrastructure when any feature that needs it is on.
  create_supporting_infra = var.enable_ip_sets || var.enable_threat_intel_sets || var.enable_s3_publishing

  primary_bucket_name = "${var.bucket_prefix}-${local.account_id}-${var.region}"
  logs_bucket_name    = "${var.bucket_prefix}-logs-${local.account_id}-${var.region}"
  replica_bucket_name = "${var.bucket_prefix}-replica-${local.account_id}-${var.replica_region}"
}

################################################################################
# Variables
################################################################################

variable "region" {
  description = "Primary AWS region for the GuardDuty detector."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Region for the replica S3 bucket and replica KMS key."
  type        = string
  default     = "us-west-2"
}

variable "bucket_prefix" {
  description = "Prefix used to name the GuardDuty S3 buckets."
  type        = string
  default     = "guardduty-findings"
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "enable_detector" {
  description = "Enable the primary GuardDuty detector."
  type        = bool
  default     = true
}

variable "finding_publishing_frequency" {
  description = "GuardDuty findings publishing frequency."
  type        = string
  default     = "FIFTEEN_MINUTES"
}

variable "enable_s3_protection" {
  description = "Enable GuardDuty S3 data event protection."
  type        = bool
  default     = false
}

variable "enable_kubernetes_protection" {
  description = "Enable GuardDuty Kubernetes (EKS) audit log protection."
  type        = bool
  default     = false
}

variable "enable_malware_protection" {
  description = "Enable GuardDuty EBS malware protection."
  type        = bool
  default     = false
}

variable "snapshot_retention" {
  description = "Toggle EBS snapshot preservation (RETENTION_WITH_FINDING when true, NO_RETENTION when false)."
  type        = bool
  default     = false
}

variable "enable_ip_sets" {
  description = "Enable creation of GuardDuty IP sets."
  type        = bool
  default     = false
}

variable "ip_sets" {
  description = "List of GuardDuty IP set definitions."
  type = list(object({
    name     = string
    format   = string
    location = string
    activate = bool
  }))
  default = []
}

variable "enable_threat_intel_sets" {
  description = "Enable creation of GuardDuty threat intelligence sets."
  type        = bool
  default     = false
}

variable "threat_intel_sets" {
  description = "List of GuardDuty threat intelligence set definitions."
  type = list(object({
    name     = string
    format   = string
    location = string
    activate = bool
  }))
  default = []
}

variable "enable_s3_publishing" {
  description = "Enable GuardDuty findings export to S3."
  type        = bool
  default     = false
}

variable "filters" {
  description = "List of GuardDuty finding filters."
  type = list(object({
    name     = string
    action   = string
    rank     = number
    criteria = list(object({
      field        = string
      equals       = optional(list(string))
      not_equals   = optional(list(string))
      greater_than = optional(number)
      less_than    = optional(number)
    }))
  }))
  default = []
}

################################################################################
# GuardDuty Detector
################################################################################

resource "aws_guardduty_detector" "this" {
  enable                       = var.enable_detector
  finding_publishing_frequency = var.finding_publishing_frequency

  tags = var.tags
}

resource "aws_guardduty_detector_feature" "s3_logs" {
  count       = var.enable_s3_protection ? 1 : 0
  detector_id = aws_guardduty_detector.this.id
  name        = "S3_DATA_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "kubernetes" {
  count       = var.enable_kubernetes_protection ? 1 : 0
  detector_id = aws_guardduty_detector.this.id
  name        = "EKS_AUDIT_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "malware" {
  count       = var.enable_malware_protection ? 1 : 0
  detector_id = aws_guardduty_detector.this.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = "ENABLED"
}

################################################################################
# EBS Snapshot Preservation (local-exec)
################################################################################

resource "null_resource" "ebs_snapshot_preservation" {
  triggers = {
    detector_id        = aws_guardduty_detector.this.id
    snapshot_retention = tostring(var.snapshot_retention)
    region             = var.region
  }

  provisioner "local-exec" {
    command = "aws guardduty update-detector --region ${var.region} --detector-id ${aws_guardduty_detector.this.id} --features '[{\"Name\":\"EBS_MALWARE_PROTECTION\",\"Status\":\"ENABLED\",\"AdditionalConfiguration\":[{\"Name\":\"EBS_SNAPSHOT_PRESERVATION\",\"Status\":\"${var.snapshot_retention ? "ENABLED" : "DISABLED"}\"}]}]'"
  }
}

################################################################################
# KMS - Multi-Region Primary & Replica Keys
################################################################################

data "aws_iam_policy_document" "kms" {
  count = local.create_supporting_infra ? 1 : 0

  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowGuardDutyToEncryptAndDecrypt"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:ReEncrypt*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowAccountPrincipalsForReplication"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "this" {
  count = local.create_supporting_infra ? 1 : 0

  description             = "GuardDuty findings, IP set and threat intel set encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  multi_region            = true
  policy                  = data.aws_iam_policy_document.kms[0].json

  tags = var.tags
}

resource "aws_kms_alias" "this" {
  count = local.create_supporting_infra ? 1 : 0

  name          = "alias/guardduty-findings"
  target_key_id = aws_kms_key.this[0].key_id
}

resource "aws_kms_replica_key" "replica" {
  count = local.create_supporting_infra ? 1 : 0

  provider = aws.replica

  description             = "GuardDuty replica encryption key in ${var.replica_region}"
  deletion_window_in_days = 7
  primary_key_arn         = aws_kms_key.this[0].arn

  tags = var.tags
}

################################################################################
# S3 - Access Log Bucket
################################################################################

resource "aws_s3_bucket" "logs" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = local.logs_bucket_name

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

################################################################################
# S3 - Primary Findings Bucket
################################################################################

resource "aws_s3_bucket" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = local.primary_bucket_name

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this[0].arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  bucket        = aws_s3_bucket.primary[0].id
  target_bucket = aws_s3_bucket.logs[0].id
  target_prefix = "log/"
}

################################################################################
# S3 - Replica Bucket (Replica Region)
################################################################################

resource "aws_s3_bucket" "replica" {
  count = local.create_supporting_infra ? 1 : 0

  provider = aws.replica

  bucket = local.replica_bucket_name

  tags = var.tags
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count = local.create_supporting_infra ? 1 : 0

  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "replica" {
  count = local.create_supporting_infra ? 1 : 0

  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count = local.create_supporting_infra ? 1 : 0

  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_replica_key.replica[0].arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

################################################################################
# IAM - Cross-Region Replication Role & Policy
################################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  count = local.create_supporting_infra ? 1 : 0

  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "replication" {
  count = local.create_supporting_infra ? 1 : 0

  name               = "${var.bucket_prefix}-s3-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json

  tags = var.tags
}

data "aws_iam_policy_document" "replication" {
  count = local.create_supporting_infra ? 1 : 0

  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [aws_s3_bucket.primary[0].arn]
  }

  statement {
    sid    = "SourceObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectVersion",
    ]

    resources = ["${aws_s3_bucket.primary[0].arn}/*"]
  }

  statement {
    sid    = "DestinationBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:List*",
    ]

    resources = ["${aws_s3_bucket.replica[0].arn}/*"]
  }

  statement {
    sid    = "KmsPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:ReEncrypt*",
    ]

    resources = [
      aws_kms_key.this[0].arn,
      aws_kms_replica_key.replica[0].arn,
    ]
  }
}

resource "aws_iam_policy" "replication" {
  count = local.create_supporting_infra ? 1 : 0

  name   = "${var.bucket_prefix}-s3-replication"
  policy = data.aws_iam_policy_document.replication[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_supporting_infra ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

################################################################################
# S3 - Cross-Region Replication with 15-Minute RTC
################################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "guardduty-findings-replication"
    status = "Enabled"

    filter {
      prefix = ""
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_replica_key.replica[0].arn
      }

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica,
  ]
}

################################################################################
# GuardDuty S3 Publishing Destination + Bucket Policy
################################################################################

data "aws_iam_policy_document" "guardduty_publishing_bucket" {
  count = var.enable_s3_publishing ? 1 : 0

  statement {
    sid    = "AllowGuardDutyPutObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.primary[0].arn}/AWSLogs/${local.account_id}/GuardDuty/*",
    ]
  }

  statement {
    sid    = "AllowGuardDutyGetBucketLocation"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    actions = ["s3:GetBucketLocation"]

    resources = [aws_s3_bucket.primary[0].arn]
  }
}

resource "aws_s3_bucket_policy" "guardduty_publishing" {
  count = var.enable_s3_publishing ? 1 : 0

  bucket = aws_s3_bucket.primary[0].id
  policy = data.aws_iam_policy_document.guardduty_publishing_bucket[0].json

  depends_on = [
    aws_s3_bucket_public_access_block.primary,
  ]
}

resource "aws_guardduty_publishing_destination" "this" {
  count = var.enable_s3_publishing ? 1 : 0

  detector_id     = aws_guardduty_detector.this.id
  destination_arn = aws_s3_bucket.primary[0].arn
  kms_key_arn     = aws_kms_key.this[0].arn

  depends_on = [
    aws_guardduty_detector_feature.s3_logs,
    aws_s3_bucket_policy.guardduty_publishing,
  ]
}

################################################################################
# GuardDuty Filters
################################################################################

resource "aws_guardduty_filter" "this" {
  for_each = { for f in var.filters : f.name => f }

  detector_id = aws_guardduty_detector.this.id
  name        = each.value.name
  action      = each.value.action
  rank        = each.value.rank

  finding_criteria {
    dynamic "criterion" {
      for_each = each.value.criteria

      content {
        field        = criterion.value.field
        equals       = try(criterion.value.equals, null)
        not_equals   = try(criterion.value.not_equals, null)
        greater_than = try(criterion.value.greater_than, null)
        less_than    = try(criterion.value.less_than, null)
      }
    }
  }

  tags = var.tags
}

################################################################################
# GuardDuty IP Sets
################################################################################

resource "aws_guardduty_ipset" "this" {
  for_each = var.enable_ip_sets ? { for s in var.ip_sets : s.name => s } : {}

  detector_id = aws_guardduty_detector.this.id
  name        = each.value.name
  format      = each.value.format
  location    = each.value.location
  activate    = each.value.activate
}

################################################################################
# GuardDuty Threat Intel Sets
################################################################################

resource "aws_guardduty_threatintelset" "this" {
  for_each = var.enable_threat_intel_sets ? { for s in var.threat_intel_sets : s.name => s } : {}

  detector_id = aws_guardduty_detector.this.id
  name        = each.value.name
  format      = each.value.format
  location    = each.value.location
  activate    = each.value.activate
}

## Overview

This template provisions the complete IAM foundation required to launch an Amazon EMR cluster:

- **EMR service role** (`<prefix>-emr-service-role`): trusted by `elasticmapreduce.amazonaws.com`, attached to the AWS managed `AmazonElasticMapReduceRole` policy plus a tightly scoped inline `iam:PassRole` policy that only allows passing the cluster's EC2 role and the autoscaling role to EMR.
- **EMR EC2 instance profile role** (`<prefix>-emr-ec2-role`): trusted by `ec2.amazonaws.com`, with the managed `AmazonElasticMapReduceforEC2Role`, `CloudWatchAgentServerPolicy` (CloudWatch agent metrics/logs), and `AmazonSSMManagedInstanceCore` (SSM Session Manager / patching) policies attached.
- **EMR autoscaling role** (`<prefix>-emr-autoscaling-role`): trusted by `elasticmapreduce.amazonaws.com`, with an inline policy granting the `application-autoscaling:*` and required `cloudwatch:*` actions used by EMR managed scaling.
- **EC2 instance profile** (`<prefix>-emr-ec2-instance-profile`): wrapping the EC2 role so it can be supplied to the EC2 fleet / EMR cluster.

All names derive from `var.name_prefix` (default `imputation-example`) and every taggable resource is tagged from `var.tags` merged with a `Name` tag. Outputs expose ARN, name, and unique ID for each role, plus ID/ARN/name for the instance profile.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the IAM resources (IAM is global, but the provider requires a region)."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to every IAM role, policy, and instance profile created by this template."
  type        = string
  default     = "imputation-example"

  validation {
    condition     = can(regex("^[a-zA-Z0-9+=,.@_-]{1,48}$", var.name_prefix))
    error_message = "name_prefix must be 1-48 characters and contain only alphanumeric characters or +=,.@_-."
  }
}

variable "tags" {
  description = "Map of tags applied to all taggable resources for consistent tagging."
  type        = map(string)
  default = {
    Project     = "imputation-example"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(
    var.tags,
    {
      ManagedBy = "Terraform"
    }
  )
}

###############################################################################
# EMR Service Role
###############################################################################

resource "aws_iam_role" "emr_service" {
  name        = "${var.name_prefix}-emr-service-role"
  description = "Service role assumed by Amazon EMR to provision and manage cluster resources."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEMRServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticmapreduce.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-emr-service-role" })
}

resource "aws_iam_role_policy_attachment" "emr_service_managed" {
  role       = aws_iam_role.emr_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceRole"
}

resource "aws_iam_role_policy" "emr_service_passrole" {
  name = "${var.name_prefix}-emr-service-passrole"
  role = aws_iam_role.emr_service.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEMRToPassClusterRoles"
        Effect = "Allow"
        Action = ["iam:PassRole"]
        Resource = [
          aws_iam_role.emr_ec2.arn,
          aws_iam_role.emr_autoscaling.arn
        ]
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "elasticmapreduce.amazonaws.com"
          }
        }
      }
    ]
  })
}

###############################################################################
# EMR EC2 Instance Profile Role (CloudWatch + SSM + EMR for EC2)
###############################################################################

resource "aws_iam_role" "emr_ec2" {
  name        = "${var.name_prefix}-emr-ec2-role"
  description = "Role assumed by EMR cluster EC2 instances; grants CloudWatch agent and SSM access."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-emr-ec2-role" })
}

resource "aws_iam_role_policy_attachment" "emr_ec2_for_ec2_role" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticMapReduceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_cloudwatch" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_ssm" {
  role       = aws_iam_role.emr_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

###############################################################################
# EMR Autoscaling Role
###############################################################################

resource "aws_iam_role" "emr_autoscaling" {
  name        = "${var.name_prefix}-emr-autoscaling-role"
  description = "Role assumed by Amazon EMR managed scaling to create and manage scaling policies."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEMRServiceToAssumeAutoscalingRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticmapreduce.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-emr-autoscaling-role" })
}

resource "aws_iam_role_policy" "emr_autoscaling" {
  name = "${var.name_prefix}-emr-autoscaling-policy"
  role = aws_iam_role.emr_autoscaling.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowManagedScalingPolicies"
        Effect = "Allow"
        Action = [
          "application-autoscaling:DeleteScalingPolicy",
          "application-autoscaling:DeregisterScalableTarget",
          "application-autoscaling:DescribeScalableTargets",
          "application-autoscaling:DescribeScalingActivities",
          "application-autoscaling:DescribeScalingPolicies",
          "application-autoscaling:PutScalingPolicy",
          "application-autoscaling:RegisterScalableTarget"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowScalingAlarms"
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricAlarm",
          "cloudwatch:DeleteAlarms",
          "cloudwatch:DescribeAlarms"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowScalingTagging"
        Effect = "Allow"
        Action = [
          "application-autoscaling:ListTagsForResource",
          "application-autoscaling:TagResource",
          "application-autoscaling:UntagResource"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowReadMetricsForScaling"
        Effect = "Allow"
        Action = [
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# EC2 Instance Profile for EMR Cluster Nodes
###############################################################################

resource "aws_iam_instance_profile" "emr_ec2" {
  name        = "${var.name_prefix}-emr-ec2-instance-profile"
  description = "Instance profile attached to EMR cluster EC2 instances."

  role = aws_iam_role.emr_ec2.name

  tags = merge(local.common_tags, { Name = "${var.name_prefix}-emr-ec2-instance-profile" })
}

###############################################################################
# Outputs - EMR Service Role
###############################################################################

output "emr_service_role_arn" {
  description = "ARN of the EMR service role."
  value       = aws_iam_role.emr_service.arn
}

output "emr_service_role_name" {
  description = "Name of the EMR service role."
  value       = aws_iam_role.emr_service.name
}

output "emr_service_role_unique_id" {
  description = "Unique ID of the EMR service role."
  value       = aws_iam_role.emr_service.unique_id
}

###############################################################################
# Outputs - EMR EC2 Instance Profile Role
###############################################################################

output "emr_ec2_role_arn" {
  description = "ARN of the EMR EC2 (instance profile) role."
  value       = aws_iam_role.emr_ec2.arn
}

output "emr_ec2_role_name" {
  description = "Name of the EMR EC2 (instance profile) role."
  value       = aws_iam_role.emr_ec2.name
}

output "emr_ec2_role_unique_id" {
  description = "Unique ID of the EMR EC2 (instance profile) role."
  value       = aws_iam_role.emr_ec2.unique_id
}

###############################################################################
# Outputs - EMR Autoscaling Role
###############################################################################

output "emr_autoscaling_role_arn" {
  description = "ARN of the EMR autoscaling role."
  value       = aws_iam_role.emr_autoscaling.arn
}

output "emr_autoscaling_role_name" {
  description = "Name of the EMR autoscaling role."
  value       = aws_iam_role.emr_autoscaling.name
}

output "emr_autoscaling_role_unique_id" {
  description = "Unique ID of the EMR autoscaling role."
  value       = aws_iam_role.emr_autoscaling.unique_id
}

###############################################################################
# Outputs - EC2 Instance Profile
###############################################################################

output "emr_ec2_instance_profile_id" {
  description = "ID of the EC2 instance profile for the EMR cluster."
  value       = aws_iam_instance_profile.emr_ec2.id
}

output "emr_ec2_instance_profile_arn" {
  description = "ARN of the EC2 instance profile for the EMR cluster."
  value       = aws_iam_instance_profile.emr_ec2.arn
}

output "emr_ec2_instance_profile_name" {
  description = "Name of the EC2 instance profile for the EMR cluster."
  value       = aws_iam_instance_profile.emr_ec2.name
}
```

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region in which to deploy the IAM resources."
  type        = string
  default     = "us-east-1"
}

variable "iam_user_name" {
  description = "Name of the dedicated IAM user used for API integration testing and monitoring."
  type        = string
  default     = "postman-user"
}

variable "iam_user_path" {
  description = "IAM path for the user. Defaults to root path."
  type        = string
  default     = "/"
}

variable "cognito_user_pool_arn" {
  description = "Optional ARN of a Cognito user pool. If supplied, an additional policy granting cognito-idp:AdminInitiateAuth scoped to this pool is created and attached."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags applied to all taggable resources created by this stack."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Purpose   = "api-integration-testing"
  }
}

# ---------------------------------------------------------------------------
# IAM user + programmatic access credentials
# ---------------------------------------------------------------------------

resource "aws_iam_user" "postman_user" {
  name = var.iam_user_name
  path = var.iam_user_path
  tags = var.tags
}

resource "aws_iam_access_key" "postman_user" {
  user   = aws_iam_user.postman_user.name
  status = "Active"
}

# ---------------------------------------------------------------------------
# Read-only API Gateway + CloudWatch metrics policy (always attached)
# ---------------------------------------------------------------------------

resource "aws_iam_policy" "api_monitoring_readonly" {
  name        = "${var.iam_user_name}-api-monitoring-readonly"
  path        = "/"
  description = "Read-only access to API Gateway configuration and CloudWatch metrics for integration testing and monitoring."
  tags        = var.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ApiGatewayReadOnly"
        Effect   = "Allow"
        Action   = ["apigateway:GET"]
        Resource = "*"
      },
      {
        Sid      = "CloudWatchMetricsReadOnly"
        Effect   = "Allow"
        Action   = [
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "api_monitoring_readonly" {
  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.api_monitoring_readonly.arn
}

# ---------------------------------------------------------------------------
# Conditional Cognito policy (only when a user pool ARN is supplied)
# ---------------------------------------------------------------------------

resource "aws_iam_policy" "cognito_admin_initiate_auth" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  name        = "${var.iam_user_name}-cognito-admin-initiate-auth"
  path        = "/"
  description = "Allows cognito-idp:AdminInitiateAuth against a specific Cognito user pool for API integration testing."
  tags        = var.tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CognitoAdminInitiateAuth"
        Effect   = "Allow"
        Action   = ["cognito-idp:AdminInitiateAuth"]
        Resource = var.cognito_user_pool_arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "cognito_admin_initiate_auth" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  user       = aws_iam_user.postman_user.name
  policy_arn = aws_iam_policy.cognito_admin_initiate_auth[0].arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "iam_user_name" {
  description = "Name of the created IAM user."
  value       = aws_iam_user.postman_user.name
}

output "iam_user_arn" {
  description = "ARN of the created IAM user."
  value       = aws_iam_user.postman_user.arn
}

output "access_key_id" {
  description = "Access key ID for the IAM user (use in API integration tests)."
  value       = aws_iam_access_key.postman_user.id
}

output "secret_access_key" {
  description = "Secret access key for the IAM user. Sensitive: stored in state, retrieve once at creation."
  value       = aws_iam_access_key.postman_user.secret
  sensitive   = true
}

output "api_monitoring_policy_arn" {
  description = "ARN of the always-attached API Gateway / CloudWatch read-only policy."
  value       = aws_iam_policy.api_monitoring_readonly.arn
}

output "cognito_policy_arn" {
  description = "ARN of the conditional Cognito policy, or null when no user pool ARN was supplied."
  value       = try(aws_iam_policy.cognito_admin_initiate_auth[0].arn, null)
}

##############################################################################
# Provider & Terraform configuration
##############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

##############################################################################
# Variables
##############################################################################

variable "aws_region" {
  description = "AWS region in which the EKS-related IAM resources are created."
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster. Used as the suffix for IAM role, policy, and instance profile names."
  type        = string
  default     = "legion"
}

##############################################################################
# Common tags
##############################################################################

locals {
  common_tags = {
    "eks-cluster" = var.cluster_name
    ManagedBy     = "terraform"
  }
}

##############################################################################
# EKS Control Plane (Master) IAM Role
##############################################################################

data "aws_iam_policy_document" "eks_master_assume_role" {
  statement {
    sid     = "EKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_master" {
  name               = "tf-${var.cluster_name}"
  description        = "IAM role for the EKS control plane of cluster ${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_master_assume_role.json

  tags = merge(local.common_tags, {
    Name = "tf-${var.cluster_name}"
    Role = "eks-control-plane"
  })
}

resource "aws_iam_role_policy_attachment" "eks_master_cluster_policy" {
  role       = aws_iam_role.eks_master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_master_service_policy" {
  role       = aws_iam_role.eks_master.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

##############################################################################
# EKS Worker Node IAM Role & Instance Profile
##############################################################################

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    sid     = "EKSNodeAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "tf-${var.cluster_name}-node"
  description        = "IAM role for EKS worker nodes of cluster ${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json

  tags = merge(local.common_tags, {
    Name = "tf-${var.cluster_name}-node"
    Role = "eks-worker-node"
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_worker_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr_readonly" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.eks_node.name

  tags = merge(local.common_tags, {
    Name = "tf-${var.cluster_name}-node"
  })
}

##############################################################################
# Cluster Autoscaler IAM Policy (attached to node role)
##############################################################################

data "aws_iam_policy_document" "eks_worker_autoscaling" {
  # Global read-only / describe permissions required by the Cluster Autoscaler.
  statement {
    sid    = "AllowAutoscalingDescribeGlobal"
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchTemplateVersions",
      "ec2:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  # Capacity mutation actions, strictly limited to ASGs that are tagged as
  # belonging to this cluster and having the autoscaler enabled.
  statement {
    sid    = "AllowAutoscalingScalingActionsOnTaggedResources"
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "eks_worker_autoscaling" {
  name        = "eks-worker-autoscaling-${var.cluster_name}"
  description = "Permissions required by the Kubernetes Cluster Autoscaler for EKS cluster ${var.cluster_name}"
  policy      = data.aws_iam_policy_document.eks_worker_autoscaling.json

  tags = merge(local.common_tags, {
    Name = "eks-worker-autoscaling-${var.cluster_name}"
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.eks_worker_autoscaling.arn
}

##############################################################################
# Outputs
##############################################################################

output "eks_master_role_arn" {
  description = "ARN of the EKS control plane IAM role."
  value       = aws_iam_role.eks_master.arn
}

output "eks_master_role_name" {
  description = "Name of the EKS control plane IAM role."
  value       = aws_iam_role.eks_master.name
}

output "eks_node_role_arn" {
  description = "ARN of the EKS worker node IAM role."
  value       = aws_iam_role.eks_node.arn
}

output "eks_node_role_name" {
  description = "Name of the EKS worker node IAM role."
  value       = aws_iam_role.eks_node.name
}

output "eks_node_instance_profile_name" {
  description = "Name of the EC2 instance profile for the EKS worker nodes."
  value       = aws_iam_instance_profile.eks_node.name
}

output "eks_node_instance_profile_arn" {
  description = "ARN of the EC2 instance profile for the EKS worker nodes."
  value       = aws_iam_instance_profile.eks_node.arn
}

output "eks_worker_autoscaling_policy_arn" {
  description = "ARN of the Cluster Autoscaler IAM policy attached to the node role."
  value       = aws_iam_policy.eks_worker_autoscaling.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ------------------------------------------------------------
# Variables
# ------------------------------------------------------------

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.69.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "172.69.2.0/24"
}

variable "availability_zone" {
  description = "Availability zone for the subnets"
  type        = string
  default     = "us-east-1a"
}

variable "webserver_ingress_rules" {
  description = "List of ingress rules for the web server security group"
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    {
      from_port   = 80
      to_port     = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    }
  ]
}

variable "database_ingress_port" {
  description = "Port for database ingress"
  type        = number
  default     = 3306
}

# ------------------------------------------------------------
# VPC
# ------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "vpc_name"
  }
}

# ------------------------------------------------------------
# Subnets
# ------------------------------------------------------------

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = var.availability_zone
  map_public_ip_on_launch = true

  tags = {
    Name = "public_subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = var.availability_zone

  tags = {
    Name = "private_subnet"
  }
}

# ------------------------------------------------------------
# Internet Gateway
# ------------------------------------------------------------

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw_tag"
  }
}

# ------------------------------------------------------------
# Route Table and Association
# ------------------------------------------------------------

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rtb_tag"
  }
}

resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public_rt.id
}

# ------------------------------------------------------------
# Security Groups
# ------------------------------------------------------------

resource "aws_security_group" "webserver" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Web server security group"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.webserver_ingress_rules
    content {
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "web-server_security_group"
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Database security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = var.database_ingress_port
    to_port     = var.database_ingress_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "database_security_group"
  }
}

## Description

This template provisions the IAM foundation required by the AWS Cloud Controller Manager (CCM) plus container registry access for a Kubernetes cluster running on EC2 (control plane and worker nodes).

What it creates:

- **Configurable tagging** – A `tags` variable (`map(string)`, default `{}`) applied to every taggable resource.
- **Region/provider** – AWS provider pinned to a configurable region (default `us-east-1`).
- **Control plane role** – `aws_ccm_k8s_controlplane` IAM role with an EC2 `sts:AssumeRole` trust policy, an EC2 instance profile of the same name, and an attached customer-managed policy `aws_ccm_k8s_controlplane` granting:
  - EC2 networking actions (security groups, subnets, VPCs, routes, tags, etc.)
  - `autoscaling:Describe*` plus capacity adjustment actions
  - `elasticloadbalancing:*` for ELB/NLB lifecycle management by the CCM
  - `kms:DescribeKey`
  - `iam:CreateServiceLinkedRole`, constrained via condition to ELB and Auto Scaling service-linked roles
- **Worker role** – `aws_ccm_k8s_worker` IAM role with an EC2 `sts:AssumeRole` trust policy, an EC2 instance profile of the same name, and an attached customer-managed policy `aws_ccm_k8s_worker` granting:
  - `ec2:DescribeInstances`, `ec2:DescribeRegions` (and a few supporting describes)
  - Read-only ECR access (`GetAuthorizationToken`, `BatchCheckLayerAvailability`, `GetDownloadUrlForLayer`, `BatchGetImage`, repository/image metadata reads) so nodes can pull container images
- **Outputs** – Role ARNs and instance profile names for downstream cluster modules.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Provider configuration
###############################################################################

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region where IAM resources will be created (IAM is global, region is required for the provider)."
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "A map of tags to apply to all taggable resources created by this module."
  type        = map(string)
  default     = {}
}

variable "controlplane_role_name" {
  description = "Name of the IAM role and instance profile used by the Kubernetes control plane nodes for the AWS Cloud Controller Manager."
  type        = string
  default     = "aws_ccm_k8s_controlplane"
}

variable "worker_role_name" {
  description = "Name of the IAM role and instance profile used by the Kubernetes worker nodes for the AWS Cloud Controller Manager and ECR access."
  type        = string
  default     = "aws_ccm_k8s_worker"
}

###############################################################################
# Trust policies (EC2 assume role)
###############################################################################

data "aws_iam_policy_document" "controlplane_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "worker_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

###############################################################################
# Control plane (aws_ccm_k8s_controlplane) permission policy document
###############################################################################

data "aws_iam_policy_document" "controlplane" {
  # EC2 networking permissions used by the CCM to reconcile security groups,
  # subnets, routes and related network constructs.
  statement {
    sid    = "EC2Networking"
    effect = "Allow"

    resources = ["*"]

    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeSecurityGroups",
      "ec2:CreateSecurityGroup",
      "ec2:DeleteSecurityGroup",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:RevokeSecurityGroupEgress",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeRouteTables",
      "ec2:DescribeInternetGateways",
      "ec2:DescribeNatGateways",
      "ec2:DescribeLaunchTemplates",
      "ec2:DescribeLaunchTemplateVersions",
      "ec2:CreateTags",
      "ec2:DeleteTags",
      "ec2:DescribeTags",
      "ec2:ModifyNetworkInterfaceAttribute",
    ]
  }

  # Auto Scaling group description / capacity reconciliation.
  statement {
    sid    = "AutoScalingGroupAccess"
    effect = "Allow"

    resources = ["*"]

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
    ]
  }

  # Elastic Load Balancing management (classic ELB, ALB and NLB).
  statement {
    sid    = "ElasticLoadBalancingManagement"
    effect = "Allow"

    resources = ["*"]

    actions = [
      "elasticloadbalancing:*",
    ]
  }

  # KMS key description for encrypted ELB / EBS resources.
  statement {
    sid    = "KMSDescribeKey"
    effect = "Allow"

    resources = ["*"]

    actions = [
      "kms:DescribeKey",
      "kms:ListKeys",
      "kms:ListAliases",
    ]
  }

  # Allow the CCM to create the ELB and Auto Scaling service-linked roles it
  # requires on first use, scoped via condition to those AWS services only.
  statement {
    sid       = "CreateServiceLinkedRole"
    effect    = "Allow"
    resources = ["arn:aws:iam::*:role/aws-service-role/*"]

    actions = [
      "iam:CreateServiceLinkedRole",
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:AWSServiceName"

      values = [
        "elasticloadbalancing.amazonaws.com",
        "autoscaling.amazonaws.com",
      ]
    }
  }
}

###############################################################################
# Worker (aws_ccm_k8s_worker) permission policy document
###############################################################################

data "aws_iam_policy_document" "worker" {
  # Instance / region description used by the CCM to map nodes to instances.
  statement {
    sid    = "EC2Describe"
    effect = "Allow"

    resources = ["*"]

    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRegions",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeTags",
      "ec2:DescribeNetworkInterfaces",
    ]
  }

  # ECR token retrieval (must target "*" per AWS requirements).
  statement {
    sid    = "ECRGetAuthorizationToken"
    effect = "Allow"

    resources = ["*"]

    actions = [
      "ecr:GetAuthorizationToken",
    ]
  }

  # Read-only ECR repository/image access for pulling container images.
  statement {
    sid    = "ECRReadOnly"
    effect = "Allow"

    resources = ["*"]

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:DescribeRepositories",
      "ecr:DescribeImages",
      "ecr:ListImages",
      "ecr:ListTagsForResource",
    ]
  }
}

###############################################################################
# IAM role + instance profile: control plane
###############################################################################

resource "aws_iam_role" "controlplane" {
  name                 = var.controlplane_role_name
  assume_role_policy   = data.aws_iam_policy_document.controlplane_assume_role.json
  description          = "IAM role assumed by Kubernetes control plane nodes for the AWS Cloud Controller Manager."
  max_session_duration = 3600

  tags = var.tags
}

resource "aws_iam_instance_profile" "controlplane" {
  name = var.controlplane_role_name
  role = aws_iam_role.controlplane.name

  tags = var.tags
}

resource "aws_iam_policy" "controlplane" {
  name        = var.controlplane_role_name
  description = "Permissions for the AWS Cloud Controller Manager running on Kubernetes control plane nodes."
  policy      = data.aws_iam_policy_document.controlplane.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "controlplane" {
  role       = aws_iam_role.controlplane.name
  policy_arn = aws_iam_policy.controlplane.arn
}

###############################################################################
# IAM role + instance profile: worker
###############################################################################

resource "aws_iam_role" "worker" {
  name                 = var.worker_role_name
  assume_role_policy   = data.aws_iam_policy_document.worker_assume_role.json
  description          = "IAM role assumed by Kubernetes worker nodes for the AWS Cloud Controller Manager and ECR image pulls."
  max_session_duration = 3600

  tags = var.tags
}

resource "aws_iam_instance_profile" "worker" {
  name = var.worker_role_name
  role = aws_iam_role.worker.name

  tags = var.tags
}

resource "aws_iam_policy" "worker" {
  name        = var.worker_role_name
  description = "Permissions for Kubernetes worker nodes to describe EC2 instances/regions and pull container images from ECR."
  policy      = data.aws_iam_policy_document.worker.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "worker" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.worker.arn
}

###############################################################################
# Outputs
###############################################################################

output "controlplane_role_arn" {
  description = "ARN of the control plane IAM role."
  value       = aws_iam_role.controlplane.arn
}

output "controlplane_role_name" {
  description = "Name of the control plane IAM role."
  value       = aws_iam_role.controlplane.name
}

output "controlplane_instance_profile_name" {
  description = "Name of the control plane EC2 instance profile."
  value       = aws_iam_instance_profile.controlplane.name
}

output "controlplane_instance_profile_arn" {
  description = "ARN of the control plane EC2 instance profile."
  value       = aws_iam_instance_profile.controlplane.arn
}

output "controlplane_policy_arn" {
  description = "ARN of the control plane IAM policy."
  value       = aws_iam_policy.controlplane.arn
}

output "worker_role_arn" {
  description = "ARN of the worker IAM role."
  value       = aws_iam_role.worker.arn
}

output "worker_role_name" {
  description = "Name of the worker IAM role."
  value       = aws_iam_role.worker.name
}

output "worker_instance_profile_name" {
  description = "Name of the worker EC2 instance profile."
  value       = aws_iam_instance_profile.worker.name
}

output "worker_instance_profile_arn" {
  description = "ARN of the worker EC2 instance profile."
  value       = aws_iam_instance_profile.worker.arn
}

output "worker_policy_arn" {
  description = "ARN of the worker IAM policy."
  value       = aws_iam_policy.worker.arn
}
```

##############################################################################
# Terraform & Provider Configuration
##############################################################################

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.default_tags
  }
}

##############################################################################
# Variables
##############################################################################

variable "aws_region" {
  description = "AWS region in which the IAM resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Prefix applied to all IAM resource names."
  type        = string
  default     = "awscademo-"
}

variable "contact" {
  description = "Contact / owning team tag value."
  type        = string
  default     = "cloud-team@example.com"
}

variable "deployment_method" {
  description = "Tag value describing how the resources were deployed."
  type        = string
  default     = "Terraform"
}

variable "deployment_date" {
  description = "Tag value describing when the resources were deployed."
  type        = string
  default     = "2024-01-01"
}

variable "ttl" {
  description = "Tag value describing the time-to-live of the resources."
  type        = string
  default     = "infinite"
}

##############################################################################
# Data Sources
##############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

##############################################################################
# Locals
##############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # Role name is truncated to a 31 character prefix so that it stays valid
  # even when used with a path.
  admin_role_name = substr("${var.name}admin", 0, 31)

  default_tags = {
    Contact          = var.contact
    DeploymentMethod = var.deployment_method
    DeploymentDate   = var.deployment_date
    TTL              = var.ttl
  }
}

##############################################################################
# IAM Groups
##############################################################################

# Demo users - self service credentials management
resource "aws_iam_group" "demo_users" {
  name = "${var.name}demo-users"
}

# Read only users - AWS managed ReadOnlyAccess
resource "aws_iam_group" "read_only_users" {
  name = "${var.name}read-only-users"
}

# MFA superadmin users - can assume the MFA protected admin role
resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.name}mfa-superadmin"
}

##############################################################################
# Self-Management Policy (attached to the demo users group)
##############################################################################

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowUsersToChangeTheirOwnPassword"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/&{aws:username}",
    ]
  }

  statement {
    sid    = "AllowUsersToListTheirOwnAccountInformation"
    effect = "Allow"

    actions = [
      "iam:GetUser",
      "iam:ListAccountAliases",
      "iam:ListUsers",
      "iam:ListGroups",
      "iam:ListPolicies",
      "iam:GetAccountPasswordPolicy",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowUsersToManageTheirOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/&{aws:username}",
    ]
  }

  statement {
    sid    = "AllowUsersToUploadTheirOwnSSHPublicKeys"
    effect = "Allow"

    actions = [
      "iam:UploadSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:UpdateSSHPublicKey",
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/&{aws:username}",
    ]
  }

  statement {
    sid    = "AllowUsersToManageTheirOwnVirtualMFADevices"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/&{aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/&{aws:username}",
    ]
  }

  # Deactivation of a user's own virtual MFA device is only permitted when the
  # caller has already authenticated with MFA.
  statement {
    sid    = "AllowUsersToDeactivateTheirOwnMFADeviceOnlyWhenMFAIsPresent"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/&{aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:user/&{aws:username}",
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${var.name}self-management"
  description = "Allows group members to manage their own password, access keys, SSH public keys and virtual MFA devices."
  policy      = data.aws_iam_policy_document.self_management.json
}

resource "aws_iam_group_policy_attachment" "demo_users_self_management" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.self_management.arn
}

##############################################################################
# Read Only Policy Attachment
##############################################################################

resource "aws_iam_group_policy_attachment" "read_only_users_read_only_access" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/ReadOnlyAccess"
}

##############################################################################
# Administrative Role (assumable by account root, 12 hour max session)
##############################################################################

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountRootToAssumeAdminRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name                 = local.admin_role_name
  description          = "Administrative role that can only be assumed by the account root user and whose permissions require MFA."
  max_session_duration = 43200 # 12 hours
  assume_role_policy   = data.aws_iam_policy_document.admin_assume_role.json
}

##############################################################################
# Administrator Policy (full admin, MFA required)
##############################################################################

data "aws_iam_policy_document" "admin" {
  statement {
    sid       = "AllowAllActionsWhenMFAIsPresent"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin" {
  name        = "${var.name}admin-policy"
  description = "Grants full administrator permissions but only when the caller has authenticated with MFA."
  policy      = data.aws_iam_policy_document.admin.json
}

resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin.arn
}

##############################################################################
# MFA Superadmin Group Policy (assume the admin role when MFA is present)
##############################################################################

data "aws_iam_policy_document" "mfa_superadmin_assume_admin_role" {
  statement {
    sid     = "AllowGroupMembersToAssumeAdminRoleWhenMFAIsPresent"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    resources = [
      aws_iam_role.admin.arn,
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "mfa_superadmin_assume_admin_role" {
  name   = "${var.name}mfa-superadmin-assume-admin-role"
  group  = aws_iam_group.mfa_superadmin.name
  policy = data.aws_iam_policy_document.mfa_superadmin_assume_admin_role.json
}

##############################################################################
# Outputs
##############################################################################

output "demo_users_group_name" {
  description = "Name of the self-service demo users group."
  value       = aws_iam_group.demo_users.name
}

output "read_only_users_group_name" {
  description = "Name of the read-only users group."
  value       = aws_iam_group.read_only_users.name
}

output "mfa_superadmin_group_name" {
  description = "Name of the MFA superadmin group."
  value       = aws_iam_group.mfa_superadmin.name
}

output "self_management_policy_arn" {
  description = "ARN of the custom self-management policy."
  value       = aws_iam_policy.self_management.arn
}

output "admin_role_arn" {
  description = "ARN of the administrative IAM role."
  value       = aws_iam_role.admin.arn
}

output "admin_role_name" {
  description = "Name of the administrative IAM role."
  value       = aws_iam_role.admin.name
}

output "admin_policy_arn" {
  description = "ARN of the MFA-conditioned administrator policy."
  value       = aws_iam_policy.admin.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

# IAM Groups
resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# Inline Policies for Groups
resource "aws_iam_group_policy" "admin_policy" {
  name  = "admin_policy"
  group = aws_iam_group.admin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy" "admin_terraform_cloud_policy" {
  name  = "admin_terraform_cloud_policy"
  group = aws_iam_group.admin_terraform_cloud.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_group_policy" "github_policy" {
  name  = "github_policy"
  group = aws_iam_group.github.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "acm:*",
          "cloudfront:*",
          "iam:*",
          "lambda:*",
          "route53:*",
          "s3:*",
          "sqs:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Customer Managed Policy for Serverless
resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  description = "Policy for serverless workloads"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "acm:*",
          "cloudfront:*",
          "iam:*",
          "lambda:*",
          "logs:*",
          "route53:*",
          "s3:*",
          "sqs:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach Managed Policy to Serverless Group
resource "aws_iam_group_policy_attachment" "serverless_group" {
  group      = aws_iam_group.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

# IAM Users
resource "aws_iam_user" "admin" {
  name = "admin"
  path = "/"
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
  path = "/"
}

resource "aws_iam_access_key" "admin_macbook_pro_key" {
  user = aws_iam_user.admin_macbook_pro.name
}

resource "aws_iam_user" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/"
}

resource "aws_iam_access_key" "admin_terraform_cloud_key" {
  user = aws_iam_user.admin_terraform_cloud.name
}

resource "aws_iam_user" "github" {
  name = "github"
  path = "/"
}

resource "aws_iam_user" "serverless" {
  name = "serverless"
  path = "/"
}

# Group Memberships
resource "aws_iam_group_membership" "admin_membership" {
  name  = "admin_membership"
  group = aws_iam_group.admin.name
  users = [
    aws_iam_user.admin.name,
    aws_iam_user.admin_macbook_pro.name
  ]
}

resource "aws_iam_group_membership" "admin_terraform_cloud_membership" {
  name  = "admin_terraform_cloud_membership"
  group = aws_iam_group.admin_terraform_cloud.name
  users = [aws_iam_user.admin_terraform_cloud.name]
}

resource "aws_iam_group_membership" "github_membership" {
  name  = "github_membership"
  group = aws_iam_group.github.name
  users = [aws_iam_user.github.name]
}

resource "aws_iam_group_membership" "serverless_membership" {
  name  = "serverless_membership"
  group = aws_iam_group.serverless.name
  users = [aws_iam_user.serverless.name]
}

# IAM Role for Serverless
resource "aws_iam_role" "serverless" {
  name = "serverless"
  path = "/serverless/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "lambda.amazonaws.com",
            "edgelambda.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "serverless_role" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

# Outputs
output "admin_macbook_pro_access_key_id" {
  value     = aws_iam_access_key.admin_macbook_pro_key.id
  sensitive = true
}

output "admin_macbook_pro_secret_access_key" {
  value     = aws_iam_access_key.admin_macbook_pro_key.secret
  sensitive = true
}

output "admin_terraform_cloud_access_key_id" {
  value     = aws_iam_access_key.admin_terraform_cloud_key.id
  sensitive = true
}

output "admin_terraform_cloud_secret_access_key" {
  value     = aws_iam_access_key.admin_terraform_cloud_key.secret
  sensitive = true
}

output "serverless_role_arn" {
  value = aws_iam_role.serverless.arn
}

# IAM MFA Access Management Framework

**Description of the Terraform program:**

This configuration provisions a secure, MFA-enforced IAM access management framework:

1. **Naming/tagging (CloudPosse `label` module):** Five `cloudposse/label/null` modules are declared, each fed the same `namespace`, `environment`, `name`, `tags`, and `attributes` variables, producing consistent, predictable identifiers for the admin group, the non-admin group, the admin role, and the two customer-managed policies.
2. **Groups:** `aws_iam_group.admin` and `aws_iam_group.non_admin` are created from those labels.
3. **Self-management policy:** A single customer-managed policy (`aws_iam_policy_document.self_management`) is attached to **both** groups. It allows users to change their own password/login profile, manage their own access keys, create/enable/resync/delete their own virtual MFA device, and list account-level MFA devices (`iam:ListVirtualMFADevices`) and the account password policy (`iam:GetAccountPasswordPolicy`). The `iam:DeactivateMFADevice` statement carries a `Bool aws:MultiFactorAuthPresent = true` condition, so deactivation is only permitted while the caller is actively MFA-authenticated. IAM policy variables are escaped with `$${aws:username}` so the rendered JSON contains the literal `${aws:username}` variable.
4. **Admin-only assume-role policy:** An additional managed policy grants `sts:AssumeRole` on the dedicated admin role, conditioned on `aws:MultiFactorAuthPresent = true`.
5. **Admin role:** `aws_iam_role.admin` has a trust policy whose principal is the account root ARN and whose condition also requires MFA. It is attached to the AWS-managed `AdministratorAccess` policy.
6. **Memberships:** `aws_iam_group_membership` resources are created only when the corresponding `admin_users` / `non_admin_users` lists are non-empty (`count = length(...) > 0 ? 1 : 0`), and manage the full membership of each group.

All variables have defaults; the provider is pinned to a valid region.

```iac_template
##############################################################################
# Terraform & Provider configuration
##############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

##############################################################################
# Data sources / locals
##############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # "$${...}" renders to a literal "${...}" so IAM policy variables survive
  # Terraform interpolation and land intact in the rendered policy JSON.
  own_user_arn     = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
  own_mfa_arn      = "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"
  admin_policy_arn = "arn:${local.partition}:iam::aws:policy/AdministratorAccess"
}

##############################################################################
# Variables
##############################################################################

variable "region" {
  type        = string
  description = "AWS region in which the provider operates."
  default     = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "CloudPosse label namespace (organization / project abbreviation)."
  default     = "acme"
}

variable "environment" {
  type        = string
  description = "CloudPosse label environment (e.g. prod, staging, dev)."
  default     = "prod"
}

variable "name" {
  type        = string
  description = "CloudPosse label name (base name of the IAM framework)."
  default     = "iam"
}

variable "attributes" {
  type        = list(string)
  description = "Additional CloudPosse label attributes appended to generated names."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags applied to all taggable resources."
  default     = {}
}

variable "admin_users" {
  type        = list(string)
  description = "List of IAM user names that should be members of the admin group."
  default     = []
}

variable "non_admin_users" {
  type        = list(string)
  description = "List of IAM user names that should be members of the non-admin group."
  default     = []
}

##############################################################################
# CloudPosse label modules (namespace, environment, name, tags, attributes)
##############################################################################

module "admin_group_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["admin", "group"])
  tags        = var.tags
}

module "non_admin_group_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["non-admin", "group"])
  tags        = var.tags
}

module "admin_role_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["admin", "role"])
  tags        = var.tags
}

module "self_management_policy_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["self", "management", "policy"])
  tags        = var.tags
}

module "assume_admin_role_policy_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["assume", "admin", "role", "policy"])
  tags        = var.tags
}

##############################################################################
# Self-management policy document (attached to BOTH groups)
#
# Allows members to manage their own password / login profile, their own
# access keys and their own virtual MFA devices, plus list account level
# MFA devices and the account password policy.
#
# Deactivating a virtual MFA device REQUIRES an active MFA session.
##############################################################################

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowListingAccountLevelMfaDevicesAndPasswordPolicy"
    effect = "Allow"

    actions = [
      "iam:ListVirtualMFADevices",
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccountAliases",
      "iam:GetAccountSummary",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowIndividualUserToManageTheirOwnPassword"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
      "iam:CreateLoginProfile",
      "iam:DeleteLoginProfile",
      "iam:GetLoginProfile",
      "iam:UpdateLoginProfile",
      "iam:GetUser",
      "iam:ListGroupsForUser",
      "iam:ListUserPolicies",
      "iam:ListAttachedUserPolicies",
      "iam:ListMFADevices",
      "iam:ListSigningCertificates",
      "iam:ListSSHPublicKeys",
      "iam:ListServiceSpecificCredentials",
    ]

    resources = [local.own_user_arn]
  }

  statement {
    sid    = "AllowIndividualUserToManageTheirOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]

    resources = [local.own_user_arn]
  }

  statement {
    sid    = "AllowIndividualUserToManageTheirOwnVirtualMfaDevices"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]

    resources = [
      local.own_mfa_arn,
      local.own_user_arn,
    ]
  }

  statement {
    sid    = "AllowIndividualUserToDeactivateTheirOwnVirtualMfaDeviceOnlyWhenMfaIsPresent"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
    ]

    resources = [
      local.own_mfa_arn,
      local.own_user_arn,
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

##############################################################################
# Admin-only policy document: assume the dedicated admin role (MFA required)
##############################################################################

data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    sid    = "AllowAssumingTheAdminRoleOnlyWithMFA"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
    ]

    resources = [
      aws_iam_role.admin.arn,
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

##############################################################################
# Trust policy for the admin role: account root principal + MFA required
##############################################################################

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid    = "AllowAccountRootToAssumeAdminRoleOnlyWithMFA"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

##############################################################################
# IAM groups
##############################################################################

resource "aws_iam_group" "admin" {
  name = module.admin_group_label.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_group_label.id
  path = "/"
}

##############################################################################
# Customer managed policies
##############################################################################

resource "aws_iam_policy" "self_management" {
  name        = module.self_management_policy_label.id
  description = "Allows IAM users to self-manage their own passwords, access keys and virtual MFA devices; MFA is required to deactivate their virtual MFA device."
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = module.self_management_policy_label.tags
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = module.assume_admin_role_policy_label.id
  description = "Allows members of the admin group to assume the dedicated admin role, and only when MFA is present."
  policy      = data.aws_iam_policy_document.assume_admin_role.json
  tags        = module.assume_admin_role_policy_label.tags
}

##############################################################################
# Policy attachments
##############################################################################

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "admin_assume_admin_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

##############################################################################
# Dedicated admin role (MFA-protected trust policy) + AdministratorAccess
##############################################################################

resource "aws_iam_role" "admin" {
  name                 = module.admin_role_label.id
  description          = "Privileged administrator role assumable only with MFA by members of the admin group."
  assume_role_policy   = data.aws_iam_policy_document.admin_role_trust.json
  max_session_duration = 3600
  tags                 = module.admin_role_label.tags
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = local.admin_policy_arn
}

##############################################################################
# Conditionally managed group memberships
##############################################################################

resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_users) > 0 ? 1 : 0

  name  = "${module.admin_group_label.id}-membership"
  users = var.admin_users
  group = aws_iam_group.admin.name
}

resource "aws_iam_group_membership" "non_admin" {
  count = length(var.non_admin_users) > 0 ? 1 : 0

  name  = "${module.non_admin_group_label.id}-membership"
  users = var.non_admin_users
  group = aws_iam_group.non_admin.name
}

##############################################################################
# Outputs
##############################################################################

output "admin_group_name" {
  description = "Name of the administrator IAM group."
  value       = aws_iam_group.admin.name
}

output "non_admin_group_name" {
  description = "Name of the non-administrator IAM group."
  value       = aws_iam_group.non_admin.name
}

output "admin_role_name" {
  description = "Name of the MFA-protected administrator role."
  value       = aws_iam_role.admin.name
}

output "admin_role_arn" {
  description = "ARN of the MFA-protected administrator role."
  value       = aws_iam_role.admin.arn
}

output "self_management_policy_arn" {
  description = "ARN of the shared self-management policy."
  value       = aws_iam_policy.self_management.arn
}

output "assume_admin_role_policy_arn" {
  description = "ARN of the admin-only assume-role policy."
  value       = aws_iam_policy.assume_admin_role.arn
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the network stack."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name of the project, used as a prefix for resource names/tags."
  type        = string
  default     = "devtest"
}

variable "environment" {
  description = "Environment name (dev, test, etc.)."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC (a /16 for this dev/test stack)."
  type        = string
  default     = "10.0.0.0/16"
}

variable "availability_zone_count" {
  description = "Number of availability zones to spread the subnets across."
  type        = number
  default     = 2
}

variable "subnet_newbits" {
  description = "Number of bits to add to the VPC CIDR when carving subnets (/16 + 8 = /24)."
  type        = number
  default     = 8
}

###############################################################################
# Data sources / locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, var.availability_zone_count)

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC and Internet Gateway
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-igw"
  })
}

###############################################################################
# Subnets
#   Index layout per AZ (i = AZ index):
#     public      -> i
#     private-app -> availability_zone_count + i
#     private-data-> (2 * availability_zone_count) + i
###############################################################################

resource "aws_subnet" "public" {
  count = var.availability_zone_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, var.subnet_newbits, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private_app" {
  count = var.availability_zone_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, var.subnet_newbits, var.availability_zone_count + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-private-app-${local.azs[count.index]}"
    Tier = "private-app"
  })
}

resource "aws_subnet" "private_data" {
  count = var.availability_zone_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, var.subnet_newbits, (2 * var.availability_zone_count) + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-private-data-${local.azs[count.index]}"
    Tier = "private-data"
  })
}

###############################################################################
# Route tables and associations
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = var.availability_zone_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table intentionally has NO routes defined.
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-private-rt"
  })
}

resource "aws_route_table_association" "private_app" {
  count = var.availability_zone_count

  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_data" {
  count = var.availability_zone_count

  subnet_id      = aws_subnet.private_data[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "public" {
  name        = "${var.project_name}-${var.environment}-public-sg"
  description = "Public tier SG: VPC-internal traffic, SSH from VPC, HTTP from anywhere."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic from within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "Allow SSH from within the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "Allow HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-public-sg"
    Tier = "public"
  })
}

resource "aws_security_group" "private" {
  name        = "${var.project_name}-${var.environment}-private-sg"
  description = "Private tier SG: VPC-internal traffic in and out only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic from within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound traffic only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-${var.environment}-private-sg"
    Tier = "private"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the stack."
  value       = local.azs
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_app_subnet_ids" {
  description = "IDs of the private application subnets."
  value       = aws_subnet.private_app[*].id
}

output "private_data_subnet_ids" {
  description = "IDs of the private data subnets."
  value       = aws_subnet.private_data[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table (default route to the internet gateway)."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table (no explicit routes)."
  value       = aws_route_table.private.id
}

output "public_security_group_id" {
  description = "ID of the public tier security group."
  value       = aws_security_group.public.id
}

output "private_security_group_id" {
  description = "ID of the private tier security group."
  value       = aws_security_group.private.id
}

## Description

This Terraform configuration provisions a CI/CD IAM security stack on AWS (default region `us-east-1`), built around a naming convention of the `prod-ci-` prefix plus an optional, configurable `name_suffix` (defaults to an empty string, so names are exactly `prod-ci-...` out of the box).

Resources defined:

1. **Provider / version constraints** — `hashicorp/aws` provider (>= 5.0) configured with a `aws_region` variable defaulting to `us-east-1`.
2. **`aws_iam_role` (`prod-ci-role<name_suffix>`)** — the CI/CD role, with a trust policy generated by `aws_iam_policy_document` that allows a **wildcard principal** (`Principal: {"AWS": "*"}`) to perform `sts:AssumeRole`. A comment flags the security implication of a wildcard trust policy.
3. **`aws_iam_policy` (`prod-ci-assume-role<name_suffix>`)** — a customer-managed policy whose document grants only `sts:AssumeRole` scoped to the ARN of the role created above (no `Resource: "*"` for the action).
4. **`aws_iam_group` (`prod-ci-group<name_suffix>`)** — the CI/CD group.
5. **`aws_iam_group_policy_attachment`** — binds the assume-role policy to the group.
6. **`aws_iam_user` (`prod-ci-user<name_suffix>`)** — the CI/CD user.
7. **`aws_iam_user_group_membership`** — binds the user into the group.

Variables are all supplied with defaults (`aws_region`, `name_suffix`, `tags`), and outputs expose the role ARN, policy ARN, group name, and user name for downstream consumption. No undeclared resources or variables are referenced.

```iac_template
###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the IAM security stack is managed."
  type        = string
  default     = "us-east-1"
}

variable "name_suffix" {
  description = "Suffix appended to every resource name. All names use the 'prod-ci-' prefix."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Additional tags applied to all taggable resources in the stack."
  type        = map(string)
  default     = {}
}

###############################################################################
# Local naming convention: "prod-ci-" + resource purpose + name_suffix
###############################################################################

locals {
  name_prefix = "prod-ci-"

  common_tags = merge(
    {
      ManagedBy = "Terraform"
      Stack     = "prod-ci-cicd-iam"
    },
    var.tags
  )
}

###############################################################################
# IAM Role — CI/CD role with wildcard principal assume-role trust policy
#
# SECURITY NOTE: The trust policy below uses a wildcard principal ("*"), which
# means any AWS principal that is granted sts:AssumeRole on this role can assume
# it. This is intentional per the business requirement, but it should be paired
# with tightly scoped assume-role permissions (see the attached policy below)
# and/or an external ID / source-account condition in hardened environments.
###############################################################################

data "aws_iam_policy_document" "ci_role_assume_role" {
  statement {
    sid    = "AllowWildcardPrincipalAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }
}

resource "aws_iam_role" "ci_role" {
  name               = "${local.name_prefix}role${var.name_suffix}"
  description        = "CI/CD role assuming wildcard principals with an assume-role policy attached to the CI/CD group."
  assume_role_policy = data.aws_iam_policy_document.ci_role_assume_role.json

  tags = local.common_tags
}

###############################################################################
# IAM Policy — grants permission to assume the CI/CD role created above
###############################################################################

data "aws_iam_policy_document" "assume_ci_role" {
  statement {
    sid    = "AllowAssumeCiRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    resources = [aws_iam_role.ci_role.arn]
  }
}

resource "aws_iam_policy" "assume_ci_role" {
  name        = "${local.name_prefix}assume-role${var.name_suffix}"
  description = "Allows assuming the CI/CD role ${aws_iam_role.ci_role.name}."
  policy      = data.aws_iam_policy_document.assume_ci_role.json

  tags = local.common_tags
}

###############################################################################
# IAM Group — CI/CD group with the assume-role policy attached
###############################################################################

resource "aws_iam_group" "ci_group" {
  name = "${local.name_prefix}group${var.name_suffix}"
  path = "/ci/"
}

resource "aws_iam_group_policy_attachment" "ci_group_assume_role" {
  group      = aws_iam_group.ci_group.name
  policy_arn = aws_iam_policy.assume_ci_role.arn
}

###############################################################################
# IAM User — CI/CD user
###############################################################################

resource "aws_iam_user" "ci_user" {
  name = "${local.name_prefix}user${var.name_suffix}"
  path = "/ci/"

  tags = local.common_tags
}

###############################################################################
# Group Membership — bind the CI/CD user to the CI/CD group
###############################################################################

resource "aws_iam_user_group_membership" "ci_user_membership" {
  user = aws_iam_user.ci_user.name

  groups = [aws_iam_group.ci_group.name]
}

###############################################################################
# Outputs
###############################################################################

output "ci_role_name" {
  description = "Name of the CI/CD IAM role."
  value       = aws_iam_role.ci_role.name
}

output "ci_role_arn" {
  description = "ARN of the CI/CD IAM role."
  value       = aws_iam_role.ci_role.arn
}

output "assume_ci_role_policy_arn" {
  description = "ARN of the policy that grants permission to assume the CI/CD role."
  value       = aws_iam_policy.assume_ci_role.arn
}

output "ci_group_name" {
  description = "Name of the CI/CD IAM group."
  value       = aws_iam_group.ci_group.name
}

output "ci_user_name" {
  description = "Name of the CI/CD IAM user."
  value       = aws_iam_user.ci_user.name
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

variable "aws_region" {
  description = "AWS region in which to create the AWS Config configuration aggregator."
  type        = string
  default     = "us-east-1"
}

variable "aggregator_name" {
  description = "Name of the AWS Config configuration aggregator."
  type        = string
  default     = "default"
}

variable "tags" {
  description = "Default tags applied to all resources in this stack."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Stack     = "aws-config-aggregator"
  }
}

data "aws_caller_identity" "current" {}

resource "aws_config_configuration_aggregator" "default" {
  name = var.aggregator_name

  account_aggregation_source {
    account_ids = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }

  tags = var.tags
}

output "aggregator_arn" {
  description = "ARN of the AWS Config configuration aggregator."
  value       = aws_config_configuration_aggregator.default.arn
}

output "aggregator_name" {
  description = "Name of the AWS Config configuration aggregator."
  value       = aws_config_configuration_aggregator.default.name
}

###############################################################################
# Terraform and provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Input variables (all with defaults so the stack is deployable as-is)
###############################################################################

variable "aws_region" {
  description = "AWS region in which the networking stack is created."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name used to tag/name the VPC and all dependent resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

variable "ssh_inbound" {
  description = "CIDR ranges allowed to reach the public tier over SSH (TCP/22)."
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

###############################################################################
# Data sources and locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required", "opted-in"]
  }
}

locals {
  azs      = data.aws_availability_zones.available.names
  az_count = length(local.azs)

  # Two subnets (one public + one private) per availability zone.
  subnet_count = local.az_count * 2

  # Number of extra network bits required to carve the VPC CIDR evenly.
  newbits = ceil(log(local.subnet_count, 2))

  # Netnum offsets: public subnets occupy 0..n-1, private n..2n-1.
  public_netnum_offset  = 0
  private_netnum_offset = local.az_count
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.tags,
    {
      Name     = var.vpc_name
      vpc_name = var.vpc_name
    }
  )
}

###############################################################################
# Default Network ACL and default Security Group (adopted and tagged)
###############################################################################

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.this.default_network_acl_id

  # Preserve the AWS default "allow everything" semantics.
  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(var.tags, { Name = "${var.vpc_name}-Default" })

  lifecycle {
    ignore_changes = [subnet_ids]
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.this.id

  # Preserve the AWS default rules: all traffic from self, all traffic out.
  ingress {
    description = "Allow all traffic from members of this security group"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, { Name = "${var.vpc_name}-Default" })
}

###############################################################################
# Subnets - dynamically calculated and evenly split across all available AZs
###############################################################################

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id                  = aws_vpc.this.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.public_netnum_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-${local.azs[count.index]}"
      Tier = "public"
    }
  )
}

resource "aws_subnet" "private" {
  count = local.az_count

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.newbits, local.private_netnum_offset + count.index)
  availability_zone = local.azs[count.index]

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-${local.azs[count.index]}"
      Tier = "private"
    }
  )
}

###############################################################################
# Internet Gateway, Elastic IP and NAT Gateway (NAT lives in first public subnet)
###############################################################################

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(var.tags, { Name = "${var.vpc_name}-igw" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(var.tags, { Name = "${var.vpc_name}-nat-eip" })
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(var.tags, { Name = "${var.vpc_name}-nat" })

  depends_on = [aws_internet_gateway.this]
}

###############################################################################
# Route tables and associations
###############################################################################

# Public routing: everything goes to the Internet Gateway.
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(var.tags, { Name = "${var.vpc_name}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private routing: outbound traffic goes through the NAT Gateway.
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = merge(var.tags, { Name = "${var.vpc_name}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count = local.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# The private route table also serves as the VPC main route table.
resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.this.id
  route_table_id = aws_route_table.private.id

  depends_on = [aws_route_table_association.private]
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "public" {
  name        = "${var.vpc_name}-public-sg"
  description = "Public tier: HTTP/HTTPS from the internet and SSH from approved CIDRs"
  vpc_id      = aws_vpc.this.id

  tags = merge(var.tags, { Name = "${var.vpc_name}-public-sg" })

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  dynamic "ingress" {
    for_each = var.ssh_inbound
    content {
      description = "SSH from ${ingress.value}"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  egress {
    description = "HTTP to the VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "HTTPS to the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }
}

resource "aws_security_group" "private" {
  name        = "${var.vpc_name}-private-sg"
  description = "Private tier: HTTP/HTTPS only from the public subnets"
  vpc_id      = aws_vpc.this.id

  tags = merge(var.tags, { Name = "${var.vpc_name}-private-sg" })

  dynamic "ingress" {
    for_each = aws_subnet.public
    content {
      description = "HTTP from public subnet ${ingress.value.cidr_block}"
      from_port   = 80
      to_port     = 80
      protocol    = "tcp"
      cidr_blocks = [ingress.value.cidr_block]
    }
  }

  dynamic "ingress" {
    for_each = aws_subnet.public
    content {
      description = "HTTPS from public subnet ${ingress.value.cidr_block}"
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = [ingress.value.cidr_block]
    }
  }

  egress {
    description = "HTTPS to the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }
}

###############################################################################
# Network ACLs
###############################################################################

resource "aws_network_acl" "public" {
  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.public[*].id

  tags = merge(var.tags, { Name = "${var.vpc_name}-public-nacl" })

  # SSH - one rule per approved CIDR, numbering starts at 100.
  dynamic "ingress" {
    for_each = var.ssh_inbound
    content {
      rule_no    = 100 + tonumber(ingress.key)
      protocol   = "tcp"
      action     = "allow"
      cidr_block = ingress.value
      from_port  = 22
      to_port    = 22
    }
  }

  ingress {
    rule_no    = 200
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 210
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 220
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  egress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  egress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.private[*].id

  tags = merge(var.tags, { Name = "${var.vpc_name}-private-nacl" })

  # HTTP from each public subnet.
  dynamic "ingress" {
    for_each = aws_subnet.public
    content {
      rule_no    = 100 + tonumber(ingress.key)
      protocol   = "tcp"
      action     = "allow"
      cidr_block = ingress.value.cidr_block
      from_port  = 80
      to_port    = 80
    }
  }

  # HTTPS from each public subnet.
  dynamic "ingress" {
    for_each = aws_subnet.public
    content {
      rule_no    = 200 + tonumber(ingress.key)
      protocol   = "tcp"
      action     = "allow"
      cidr_block = ingress.value.cidr_block
      from_port  = 443
      to_port    = 443
    }
  }

  # Ephemeral return traffic from everywhere.
  ingress {
    rule_no    = 300
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  # HTTPS outbound to everywhere.
  egress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  # Ephemeral return traffic to the private subnets (local traffic).
  dynamic "egress" {
    for_each = aws_subnet.private
    content {
      rule_no    = 110 + tonumber(egress.key)
      protocol   = "tcp"
      action     = "allow"
      cidr_block = egress.value.cidr_block
      from_port  = 1024
      to_port    = 65535
    }
  }

  # Ephemeral traffic to the public subnets.
  dynamic "egress" {
    for_each = aws_subnet.public
    content {
      rule_no    = 200 + tonumber(egress.key)
      protocol   = "tcp"
      action     = "allow"
      cidr_block = egress.value.cidr_block
      from_port  = 1024
      to_port    = 65535
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "Identifier of the VPC."
  value       = aws_vpc.this.id
}

output "vpc_cidr" {
  description = "CIDR block of the VPC."
  value       = aws_vpc.this.cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the stack."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "Identifiers of the public subnets."
  value       = aws_subnet.public[*].id
}

output "public_subnet_cidrs" {
  description = "CIDR blocks of the public subnets."
  value       = aws_subnet.public[*].cidr_block
}

output "private_subnet_ids" {
  description = "Identifiers of the private subnets."
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidrs" {
  description = "CIDR blocks of the private subnets."
  value       = aws_subnet.private[*].cidr_block
}

output "internet_gateway_id" {
  description = "Identifier of the Internet Gateway."
  value       = aws_internet_gateway.this.id
}

output "nat_gateway_id" {
  description = "Identifier of the NAT Gateway."
  value       = aws_nat_gateway.this.id
}

output "nat_gateway_public_ip" {
  description = "Elastic IP address attached to the NAT Gateway."
  value       = aws_eip.nat.public_ip
}

output "public_route_table_id" {
  description = "Identifier of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "Identifier of the private (main) route table."
  value       = aws_route_table.private.id
}

output "public_security_group_id" {
  description = "Identifier of the public security group."
  value       = aws_security_group.public.id
}

output "private_security_group_id" {
  description = "Identifier of the private security group."
  value       = aws_security_group.private.id
}

output "public_network_acl_id" {
  description = "Identifier of the public Network ACL."
  value       = aws_network_acl.public.id
}

output "private_network_acl_id" {
  description = "Identifier of the private Network ACL."
  value       = aws_network_acl.private.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Trust policy: allow the EC2 service to assume the role (required for
# EC2 Image Builder build/test instances).
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "image_builder_assume_role" {
  statement {
    sid     = "EC2ImageBuilderAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM Role used by EC2 Image Builder automation
# ---------------------------------------------------------------------------
resource "aws_iam_role" "image_builder" {
  name_prefix        = "imagebuilder_"
  path               = "/"
  description        = "IAM role for EC2 Image Builder automation"
  assume_role_policy = data.aws_iam_policy_document.image_builder_assume_role.json

  tags = {
    Name = "imagebuilder_role"
  }
}

# ---------------------------------------------------------------------------
# Attach the AWS managed full-access policy for EC2 Image Builder
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "image_builder_full_access" {
  role       = aws_iam_role.image_builder.name
  policy_arn = "arn:aws:iam::aws:policy/EC2ImageBuilderFullAccess"
}

# ---------------------------------------------------------------------------
# Instance profile so the role can be attached to EC2 instances
# ---------------------------------------------------------------------------
resource "aws_iam_instance_profile" "image_builder" {
  name_prefix = "imagebuilder_"
  path        = "/"
  role        = aws_iam_role.image_builder.name

  tags = {
    Name = "imagebuilder_instance_profile"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "image_builder_role_name" {
  description = "Name of the IAM role created for EC2 Image Builder automation."
  value       = aws_iam_role.image_builder.name
}

output "image_builder_role_arn" {
  description = "ARN of the IAM role created for EC2 Image Builder automation."
  value       = aws_iam_role.image_builder.arn
}

output "image_builder_instance_profile_name" {
  description = "Name of the IAM instance profile created for EC2 Image Builder automation."
  value       = aws_iam_instance_profile.image_builder.name
}

output "image_builder_instance_profile_arn" {
  description = "ARN of the IAM instance profile created for EC2 Image Builder automation."
  value       = aws_iam_instance_profile.image_builder.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "region" {
  description = "AWS region in which to deploy the Tamr instance role and instance profile."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for Tamr data platform EC2 instances."
  type        = string
  default     = "tamr-instance-role"
}

variable "instance_profile_name" {
  description = "Name of the IAM instance profile associated with the Tamr instance role."
  type        = string
  default     = "tamr-instance-profile"
}

variable "permissions_boundary_arn" {
  description = "Optional ARN of a managed policy to use as the permissions boundary for the role. Leave null to omit a boundary."
  type        = string
  default     = null
}

variable "policy_arns" {
  description = "Optional list of managed policy ARNs to attach to the Tamr instance role (e.g. S3, CloudWatch, KMS access policies)."
  type        = list(string)
  default     = []
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role, between 3600 and 43200."
  type        = number
  default     = 3600

  validation {
    condition     = var.max_session_duration >= 3600 && var.max_session_duration <= 43200
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }
}

variable "tags" {
  description = "Map of tags to apply to the IAM role and instance profile."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM role and instance profile
# ---------------------------------------------------------------------------

resource "aws_iam_role" "tamr_instance_role" {
  name                 = var.role_name
  description          = "IAM role assumed by EC2 instances running the Tamr data platform."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  permissions_boundary = var.permissions_boundary_arn
  max_session_duration = var.max_session_duration

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "tamr_instance_role_attachments" {
  count = length(var.policy_arns)

  role       = aws_iam_role.tamr_instance_role.name
  policy_arn = var.policy_arns[count.index]
}

resource "aws_iam_instance_profile" "tamr_instance_profile" {
  name = var.instance_profile_name
  role = aws_iam_role.tamr_instance_role.name

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "role_name" {
  description = "Name of the IAM role created for the Tamr instance."
  value       = aws_iam_role.tamr_instance_role.name
}

output "role_arn" {
  description = "ARN of the IAM role created for the Tamr instance."
  value       = aws_iam_role.tamr_instance_role.arn
}

output "instance_profile_name" {
  description = "Name of the IAM instance profile created for the Tamr instance."
  value       = aws_iam_instance_profile.tamr_instance_profile.name
}

output "instance_profile_arn" {
  description = "ARN of the IAM instance profile created for the Tamr instance."
  value       = aws_iam_instance_profile.tamr_instance_profile.arn
}

output "permissions_boundary_arn" {
  description = "ARN of the permissions boundary applied to the role, if any."
  value       = var.permissions_boundary_arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the RDS Custom for SQL Server resources will be used."
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "Tags to apply to the IAM resources."
  type        = map(string)
  default = {
    Project = "Amazon-RDS-Custom-SQLServer"
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_custom_sqlserver_instance_role" {
  name               = "AWSRDSCustomSQLServerInstanceRole"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "rds_custom_sqlserver_instance_role_policy_attachment" {
  role       = aws_iam_role.rds_custom_sqlserver_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSCustomInstanceProfileRolePolicy"
}

resource "aws_iam_instance_profile" "rds_custom_sqlserver_instance_profile" {
