}

output "rds_custom_sqlserver_instance_profile_arn" {
  description = "ARN of the RDS Custom for SQL Server instance profile."
  value       = aws_iam_instance_profile.rds_custom_sqlserver_instance_profile.arn
}

## Description

This Terraform program provisions the AWS identity plumbing needed for an EC2-based Packer builder host that must pull software installation artifacts from an S3 bucket owned by **another** AWS account.

What it creates:

1. **Provider / inputs** – A single AWS provider pinned to a region supplied by variable (default `us-east-1`), plus variables for the environment name, a base resource name prefix, the target account ID, the target role name, session duration, optional extra managed policy ARNs, and tags. All variables have defaults, and the target account ID and target role name are validated so the resulting ARN is well-formed.
2. **IAM role (`aws_iam_role.packer_builder`)** – An EC2-trust role (service principal `ec2.amazonaws.com`) whose name is derived from the environment-specific prefix (`<environment>-<name_prefix>`), with a configurable max session duration.
3. **IAM instance profile (`aws_iam_instance_profile.packer_builder`)** – Attaches the role to the profile so it can be associated with the Packer builder EC2 instance / launch template.
4. **Cross-account assume-role policy (`aws_iam_policy.cross_account_assume_role`)** – Grants `sts:AssumeRole`, `sts:TagSession`, and `sts:SetSourceIdentity` (the tag/source-identity actions are what allow Packer to stamp the builder identity onto the assumed session) on the exact ARN `arn:<partition>:iam::<target_account_id>:role/<target_role_name>`. This is what lets the builder obtain temporary S3 read credentials in the remote account.
5. **Policy attachment** – Binds the cross-account policy to the role.
6. **Optional extra policy attachments** – A `for_each` over `additional_role_policy_arns` (empty by default) so baseline policies such as SSM Session Manager or CloudWatch Agent can be layered on without editing the module.
7. **Outputs** – Role name/ARN, instance profile name/ARN, and the resolved cross-account role ARN, for consumption by Packer templates or downstream Terraform stacks.

```hcl
###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the Packer builder IAM resources are created."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name used as the leading part of the resource name prefix (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9]{2,12}$", var.environment))
    error_message = "environment must be 2-12 lowercase alphanumeric characters."
  }
}

variable "name_prefix" {
  description = "Base name prefix for the Packer builder IAM role and instance profile. Final name is '<environment>-<name_prefix>'."
  type        = string
  default     = "packer-builder"

  validation {
    condition     = can(regex("^[a-zA-Z0-9+=,.@_-]{1,40}$", var.name_prefix))
    error_message = "name_prefix contains characters not allowed in IAM resource names."
  }
}

variable "target_account_id" {
  description = "AWS account ID that owns the S3 bucket holding the software installation files."
  type        = string
  default     = "123456789012"

  validation {
    condition     = can(regex("^[0-9]{12}$", var.target_account_id))
    error_message = "target_account_id must be a 12-digit AWS account ID."
  }
}

variable "target_role_name" {
  description = "Name of the IAM role in the target account that grants read access to the software installation files."
  type        = string
  default     = "software-artifacts-s3-reader"

  validation {
    condition     = can(regex("^[a-zA-Z0-9+=,.@_-]{1,64}$", var.target_role_name))
    error_message = "target_role_name contains characters not allowed in IAM role names."
  }
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the Packer builder role. Must be between 3600 and 43200."
  type        = number
  default     = 3600

  validation {
    condition     = var.max_session_duration >= 3600 && var.max_session_duration <= 43200
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }
}

variable "additional_role_policy_arns" {
  description = "Optional list of additional managed policy ARNs to attach to the Packer builder role (e.g. SSM Session Manager, CloudWatch agent)."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to all created resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "${var.environment}-${var.name_prefix}"

  target_role_arn = "arn:${data.aws_partition.current.partition}:iam::${var.target_account_id}:role/${var.target_role_name}"

  common_tags = merge(
    {
      Environment = var.environment
      Component   = "packer-builder"
      ManagedBy   = "Terraform"
    },
    var.tags
  )
}

###############################################################################
# IAM role for the Packer builder EC2 instance
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2InstancesToAssumeBuilderRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "packer_builder" {
  name                 = "${local.name_prefix}-role"
  description          = "Role assumed by the EC2 instance running HashiCorp Packer builds for the ${var.environment} environment."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = var.max_session_duration
  tags                 = local.common_tags
}

###############################################################################
# Instance profile attached to the Packer builder EC2 instance
###############################################################################

resource "aws_iam_instance_profile" "packer_builder" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.packer_builder.name
  tags = local.common_tags
}

###############################################################################
# Policy allowing the builder to assume the cross-account S3 reader role
###############################################################################

data "aws_iam_policy_document" "cross_account_assume_role" {
  statement {
    sid    = "AssumeCrossAccountSoftwareArtifactRole"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
      "sts:TagSession",
      "sts:SetSourceIdentity",
    ]

    resources = [local.target_role_arn]
  }
}

resource "aws_iam_policy" "cross_account_assume_role" {
  name        = "${local.name_prefix}-cross-account-assume-role"
  description = "Allows the Packer builder in ${var.environment} (account ${data.aws_caller_identity.current.account_id}) to assume ${local.target_role_arn} to read software installation files from S3."
  policy      = data.aws_iam_policy_document.cross_account_assume_role.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cross_account_assume_role" {
  role       = aws_iam_role.packer_builder.name
  policy_arn = aws_iam_policy.cross_account_assume_role.arn
}

###############################################################################
# Optional additional managed policies
###############################################################################

resource "aws_iam_role_policy_attachment" "additional" {
  for_each = toset(var.additional_role_policy_arns)

  role       = aws_iam_role.packer_builder.name
  policy_arn = each.value
}

###############################################################################
# Outputs
###############################################################################

output "builder_role_name" {
  description = "Name of the IAM role used by the Packer builder EC2 instance."
  value       = aws_iam_role.packer_builder.name
}

output "builder_role_arn" {
  description = "ARN of the IAM role used by the Packer builder EC2 instance."
  value       = aws_iam_role.packer_builder.arn
}

output "builder_instance_profile_name" {
  description = "Name of the instance profile to attach to the Packer builder EC2 instance."
  value       = aws_iam_instance_profile.packer_builder.name
}

output "builder_instance_profile_arn" {
  description = "ARN of the instance profile to attach to the Packer builder EC2 instance."
  value       = aws_iam_instance_profile.packer_builder.arn
}

output "cross_account_target_role_arn" {
  description = "ARN of the role in the target account that the builder is permitted to assume."
  value       = local.target_role_arn
}

output "name_prefix" {
  description = "Resolved environment-specific resource name prefix."
  value       = local.name_prefix
}
```

# Terraform Template for a 3-Tier AWS Network

This Terraform configuration provisions a self-contained 3-tier network in AWS on **us-east-1** (configurable). It creates:

- A **VPC** (`10.16.0.0/16`) named `three-tier-vpc`
- Three tier subnets in the same availability zone:
  - **Presentation subnet** `10.16.0.0/24` — `presentation-subnet`
  - **Application subnet** `10.16.1.0/24` — `application-subnet`
  - **Data subnet** `10.16.2.0/24` — `data-subnet`
- An **Internet Gateway** attached to the VPC
- A **dedicated route table** associated *only* with the presentation subnet, routing `0.0.0.0/0` to the IGW (so the app and data tiers remain isolated with no internet route)

No IAM roles are required since this is purely a networking stack with no compute or service principal access.

```iac_template
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy the 3-tier network into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag applied to the VPC."
  type        = string
  default     = "three-tier-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.16.0.0/16"
}

# ---------------------------------------------------------------------------
# Provider
# ---------------------------------------------------------------------------
provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# ---------------------------------------------------------------------------
# Presentation tier subnet (public)
# ---------------------------------------------------------------------------
resource "aws_subnet" "presentation" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.16.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "presentation-subnet"
    Tier = "presentation"
  }
}

# ---------------------------------------------------------------------------
# Application tier subnet (private / isolated)
# ---------------------------------------------------------------------------
resource "aws_subnet" "application" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "application-subnet"
    Tier = "application"
  }
}

# ---------------------------------------------------------------------------
# Data tier subnet (private / isolated)
# ---------------------------------------------------------------------------
resource "aws_subnet" "data" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "data-subnet"
    Tier = "data"
  }
}

# ---------------------------------------------------------------------------
# Dedicated route table for the presentation subnet only
# ---------------------------------------------------------------------------
resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.vpc_name}-presentation-rt"
  }
}

resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway attached to the VPC."
  value       = aws_internet_gateway.igw.id
}

output "presentation_subnet_id" {
  description = "ID of the presentation (public) subnet."
  value       = aws_subnet.presentation.id
}

output "application_subnet_id" {
  description = "ID of the application (isolated) subnet."
  value       = aws_subnet.application.id
}

output "data_subnet_id" {
  description = "ID of the data (isolated) subnet."
  value       = aws_subnet.data.id
}

output "presentation_route_table_id" {
  description = "ID of the route table associated with the presentation subnet."
  value       = aws_route_table.presentation.id
}
```

###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region used for the provider and for scoped resource ARNs."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name used for tagging and naming."
  type        = string
  default     = "test"
}

variable "project_name" {
  description = "Short project name used as a prefix for generated resources."
  type        = string
  default     = "sc-governance"
}

variable "test_role_name" {
  description = "Name of the Service Catalog assumable launch-constraint role."
  type        = string
  default     = "test_role"
}

variable "group_name" {
  description = "Name of the IAM group that holds the Service Catalog end users."
  type        = string
  default     = "sc-test-group"
}

variable "console_user_name" {
  description = "Name of the console-enabled IAM user added to the group."
  type        = string
  default     = "sc-console-user"
}

variable "product_bucket_prefix" {
  description = "Bucket name prefix that the launch-constraint role is allowed to manage."
  type        = string
  default     = "sc-governance-product"
}

variable "allowed_instance_types" {
  description = "EC2 instance types the launch-constraint role is allowed to launch."
  type        = list(string)
  default     = ["t3.micro", "t3.small", "t3.medium"]
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "Terraform"
    Purpose     = "ServiceCatalog-IAM-Governance"
  }

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  # Constructed (not resource-referenced) so the role trust policy does not
  # create a dependency cycle with the IAM user/group membership resources.
  console_user_arn = "arn:${local.partition}:iam::${local.account_id}:user/${var.console_user_name}"

  ec2_arn_prefix = "arn:${local.partition}:ec2:${local.region}:${local.account_id}"
  s3_arn_prefix  = "arn:${local.partition}:s3:::"
}

###############################################################################
# Account password policy (IAM governance baseline)
###############################################################################

resource "aws_iam_account_password_policy" "governance" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 5
  hard_expiry                    = false
}

###############################################################################
# Service Catalog launch-constraint role: test_role
###############################################################################

data "aws_iam_policy_document" "test_role_assume" {
  # 1) Service Catalog itself assumes the role to provision products.
  statement {
    sid     = "AllowServiceCatalogToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["servicecatalog.amazonaws.com"]
    }
  }

  # 2) The dedicated console test user may assume the role for manual testing.
  statement {
    sid     = "AllowConsoleTestUserToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "StringLike"
      variable = "aws:PrincipalArn"
      values   = [local.console_user_arn]
    }
  }
}

resource "aws_iam_role" "test_role" {
  name                 = var.test_role_name
  description          = "Service Catalog launch-constraint role assumed by servicecatalog.amazonaws.com"
  assume_role_policy   = data.aws_iam_policy_document.test_role_assume.json
  max_session_duration = 3600

  tags = merge(local.common_tags, {
    Name = var.test_role_name
  })
}

# ---------------------------------------------------------------------------
# Scoped launch-constraint policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "launch_constraint" {
  # Discovery / describe only permissions (no mutating actions).
  statement {
    sid    = "ReadOnlyDiscoveryForProductLaunches"
    effect = "Allow"
    actions = [
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeImages",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeInstances",
      "ec2:DescribeKeyPairs",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeTags",
      "ec2:DescribeVolumes",
      "ec2:DescribeVpcs",
      "s3:GetBucketLocation",
      "s3:ListAllMyBuckets",
    ]
    resources = ["*"]
  }

  # S3 actions scoped to the product bucket naming prefix only.
  statement {
    sid    = "ScopedS3ProductBuckets"
    effect = "Allow"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:GetBucketTagging",
      "s3:GetBucketVersioning",
      "s3:GetObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:PutBucketTagging",
      "s3:PutBucketVersioning",
      "s3:PutObject",
    ]
    resources = [
      "${local.s3_arn_prefix}${var.product_bucket_prefix}-*",
      "${local.s3_arn_prefix}${var.product_bucket_prefix}-*/*",
    ]
  }

  # Launch permissions limited by resource type, region/account and instance type.
  statement {
    sid     = "ScopedRunInstances"
    effect  = "Allow"
    actions = ["ec2:RunInstances"]

    resources = [
      "${local.ec2_arn_prefix}:instance/*",
      "${local.ec2_arn_prefix}:volume/*",
      "${local.ec2_arn_prefix}:network-interface/*",
      "${local.ec2_arn_prefix}:security-group/*",
      "${local.ec2_arn_prefix}:subnet/*",
      "${local.ec2_arn_prefix}:key-pair/*",
      "arn:${local.partition}:ec2:${local.region}::image/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "ec2:InstanceType"
      values   = var.allowed_instance_types
    }
  }

  # Lifecycle management limited to instance ARNs in this account/region.
  statement {
    sid     = "ScopedInstanceLifecycle"
    effect  = "Allow"
    actions = [
      "ec2:StartInstances",
      "ec2:StopInstances",
      "ec2:TerminateInstances",
    ]
    resources = ["${local.ec2_arn_prefix}:instance/*"]
  }

  # Tagging of the resources the launch constraint creates.
  statement {
    sid     = "ScopedResourceTagging"
    effect  = "Allow"
    actions = ["ec2:CreateTags", "ec2:DeleteTags"]
    resources = [
      "${local.ec2_arn_prefix}:instance/*",
      "${local.ec2_arn_prefix}:volume/*",
      "${local.ec2_arn_prefix}:security-group/*",
      "${local.ec2_arn_prefix}:subnet/*",
    ]
  }
}

resource "aws_iam_policy" "launch_constraint" {
  name        = "${var.project_name}-launch-constraint"
  description = "Scoped provisioning permissions for the Service Catalog launch-constraint role ${var.test_role_name}"
  policy      = data.aws_iam_policy_document.launch_constraint.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "launch_constraint" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

###############################################################################
# IAM group for Service Catalog end users
###############################################################################

resource "aws_iam_group" "test_group" {
  name = var.group_name
  path = "/service-catalog/"
}

data "aws_iam_policy_document" "service_catalog_end_user" {
  # Service Catalog end-user (read + provision/update/terminate) access.
  statement {
    sid    = "ServiceCatalogEndUserAccess"
    effect = "Allow"
    actions = [
      "servicecatalog:Describe*",
      "servicecatalog:List*",
      "servicecatalog:ScanProvisionedProducts",
      "servicecatalog:SearchProducts",
      "servicecatalog:ProvisionProduct",
      "servicecatalog:UpdateProvisionedProduct",
      "servicecatalog:TerminateProvisionedProduct",
      "servicecatalog:ExecuteProvisionedProductServiceAction",
    ]
    resources = ["*"]
  }

  # Role assumption strictly scoped to the launch-constraint role.
  statement {
    sid       = "AssumeLaunchConstraintRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.test_role.arn]
  }

  # Console self-service password management.
  statement {
    sid    = "ConsoleSelfServicePasswordManagement"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetAccountPasswordPolicy",
      "iam:GetUser",
      "iam:ListAccessKeys",
      "iam:ListMFADevices",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "service_catalog_end_user" {
  name        = "${var.project_name}-service-catalog-end-user"
  description = "Service Catalog end-user permissions for members of ${var.group_name}"
  policy      = data.aws_iam_policy_document.service_catalog_end_user.json

  tags = local.common_tags
}

resource "aws_iam_group_policy_attachment" "service_catalog_end_user" {
  group      = aws_iam_group.test_group.name
  policy_arn = aws_iam_policy.service_catalog_end_user.arn
}

###############################################################################
# Console-enabled user and group membership
###############################################################################

resource "aws_iam_user" "console_user" {
  name          = var.console_user_name
  path          = "/service-catalog/"
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = var.console_user_name
  })
}

resource "aws_iam_user_group_membership" "console_user" {
  user   = aws_iam_user.console_user.name
  groups = [aws_iam_group.test_group.name]
}

resource "random_password" "console_user" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_iam_user_login_profile" "console_user" {
  user                    = aws_iam_user.console_user.name
  password                = random_password.console_user.result
  password_reset_required = true

  depends_on = [aws_iam_account_password_policy.governance]
}

###############################################################################
# Outputs
###############################################################################

output "test_role_name" {
  description = "Name of the Service Catalog launch-constraint role."
  value       = aws_iam_role.test_role.name
}

output "test_role_arn" {
  description = "ARN of the Service Catalog launch-constraint role."
  value       = aws_iam_role.test_role.arn
}

output "test_role_trust_policy" {
  description = "Effective trust policy of the launch-constraint role."
  value       = data.aws_iam_policy_document.test_role_assume.json
}

output "launch_constraint_policy_arn" {
  description = "ARN of the scoped launch-constraint policy attached to test_role."
  value       = aws_iam_policy.launch_constraint.arn
}

output "group_name" {
  description = "Name of the IAM group for Service Catalog end users."
  value       = aws_iam_group.test_group.name
}

output "group_policy_arn" {
  description = "ARN of the Service Catalog end-user policy attached to the group."
  value       = aws_iam_policy.service_catalog_end_user.arn
}

output "console_user_name" {
  description = "Name of the console-enabled IAM user."
  value       = aws_iam_user.console_user.name
}

output "console_user_arn" {
  description = "ARN of the console-enabled IAM user."
  value       = aws_iam_user.console_user.arn
}

output "console_login_url" {
  description = "Console sign-in URL for the created IAM user."
  value       = "https://${local.account_id}.signin.aws.amazon.com/console"
}

output "console_user_initial_password" {
  description = "Initial console password (must be changed on first login)."
  value       = random_password.console_user.result
  sensitive   = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
  default_tags {
    tags = {
      Datadog                 = "true"
      DatadogAgentlessScanner = "true"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_count = min(3, length(data.aws_availability_zones.available.names))
  azs      = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  # Public subnets: /20 blocks starting at netnum 0
  public_subnets = [for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, i)]
  # Private subnets: /20 blocks offset by 4 to avoid overlap
  private_subnets = [for i in range(local.az_count) : cidrsubnet(var.vpc_cidr, 4, i + 4)]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
  }
}

resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.vpc_name}-nat"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = {
    Name = "${var.vpc_name}-s3-endpoint"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name_prefix = "${var.vpc_name}-vpc-endpoints-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.vpc_name}-vpc-endpoints-sg"
  }
}

resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.region}.lambda"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-lambda-endpoint"
  }
}

resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.region}.ebs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-ebs-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  for_each = var.enable_ssm_endpoints ? toset(["ec2messages", "ssmmessages", "ssm"]) : toset([])

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.region}.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-${each.key}-endpoint"
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DatatogAgentlessScanner"
}

variable "enable_ssm_endpoints" {
  description = "Enable SSM interface VPC endpoints"
  type        = bool
  default     = false
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "enabled" {
  description = "Master toggle for all resources in this module."
  type        = bool
  default     = true
}

variable "name" {
  description = "Base name used by the label module for resource naming."
  type        = string
  default     = "app"
}

variable "tags" {
  description = "Additional tags to apply through the label module."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
  }
}

variable "create_security_group" {
  description = "When true, create a new security group. When false, attach rules to an existing security group."
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID for the new security group. If empty and create_security_group is true, a fallback VPC is created."
  type        = string
  default     = ""
}

variable "existing_security_group_id" {
  description = "Existing security group ID used when create_security_group is false."
  type        = string
  default     = ""
}

variable "create_prefix_list" {
  description = "When true, create a managed prefix list if no pre-existing prefix list IDs are supplied."
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "Pre-existing prefix list IDs. If non-empty, managed prefix list creation is skipped."
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family for the managed prefix list."
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the managed prefix list."
  type        = number
  default     = 5

  validation {
    condition     = var.prefix_list_max_entries <= 5
    error_message = "A maximum of 5 prefix list entries is supported."
  }
}

variable "prefix_list_entries" {
  description = "Entries for the managed prefix list."
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []

  validation {
    condition     = length(var.prefix_list_entries) <= var.prefix_list_max_entries
    error_message = "The number of prefix list entries must not exceed prefix_list_max_entries."
  }
}

variable "ingress_cidr_rules" {
  description = "Ingress rules based on CIDR blocks."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = optional(string)
  }))
  default = []
}

variable "egress_cidr_rules" {
  description = "Egress rules based on CIDR blocks."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = optional(string)
  }))
  default = []
}

variable "ingress_self_rules" {
  description = "Ingress self-referencing rules."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string)
  }))
  default = []
}

variable "egress_self_rules" {
  description = "Egress self-referencing rules."
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string)
  }))
  default = []
}

variable "ingress_source_security_group_rules" {
  description = "Ingress rules that reference source security group IDs."
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    source_security_group_id = string
    description              = optional(string)
  }))
  default = []
}

variable "egress_source_security_group_rules" {
  description = "Egress rules that reference source security group IDs."
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    source_security_group_id = string
    description              = optional(string)
  }))
  default = []
}

variable "ingress_prefix_list_rules" {
  description = "Ingress rules based on prefix lists. If prefix_list_ids is omitted, the managed prefix list created by this module is used."
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = optional(list(string))
    description     = optional(string)
  }))
  default = []
}

variable "egress_prefix_list_rules" {
  description = "Egress rules based on prefix lists. If prefix_list_ids is omitted, the managed prefix list created by this module is used."
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = optional(list(string))
    description     = optional(string)
  }))
  default = []
}

module "labels_vpc" {
  source     = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  name       = var.name
  attributes = ["vpc"]
  tags       = var.tags
  enabled    = var.enabled
  delimiter  = "-"
}

module "labels_sg" {
  source     = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  name       = var.name
  attributes = ["sg"]
  tags       = var.tags
  enabled    = var.enabled
  delimiter  = "-"
}

module "labels_prefix" {
  source     = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  name       = var.name
  attributes = ["prefix-list"]
  tags       = var.tags
  enabled    = var.enabled
  delimiter  = "-"
}

locals {
  create_new_security_group = var.enabled && var.create_security_group
  create_fallback_vpc       = local.create_new_security_group && var.vpc_id == ""
  create_managed_prefix_list = var.enabled && var.create_prefix_list && length(var.prefix_list_ids) == 0
  rules_enabled             = var.enabled && (var.create_security_group || var.existing_security_group_id != "")

  vpc_id = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.fallback[0].id, "")

  effective_security_group_id = var.create_security_group ? try(aws_security_group.this[0].id, "") : var.existing_security_group_id

  default_prefix_list_id = try(aws_ec2_managed_prefix_list.this[0].id, "")
}

resource "aws_vpc" "fallback" {
  count      = local.create_fallback_vpc ? 1 : 0
  cidr_block = "10.0.0.0/16"

  tags = module.labels_vpc.tags
}

resource "aws_security_group" "this" {
  count       = local.create_new_security_group ? 1 : 0
  name        = module.labels_sg.id
  description = "Security group managed by Terraform"
  vpc_id      = local.vpc_id

  tags = module.labels_sg.tags
}

resource "aws_ec2_managed_prefix_list" "this" {
  count          = local.create_managed_prefix_list ? 1 : 0
  name           = module.labels_prefix.id
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entries" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entries.value.cidr
      description = try(entries.value.description, null)
    }
  }

  tags = module.labels_prefix.tags
}

resource "aws_security_group_rule" "ingress_cidr" {
  for_each = local.rules_enabled ? {
    for idx, rule in var.ingress_cidr_rules :
    "ingress-cidr-${idx}" => rule
    if length(rule.cidr_blocks) > 0
  } : {}

  type              = "ingress"
  security_group_id = local.effective_security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = each.value.cidr_blocks
  description       = try(each.value.description, null)
}

resource "aws_security_group_rule" "egress_cidr" {
  for_each = local.rules_enabled ? {
    for idx, rule in var.egress_cidr_rules :
    "egress-cidr-${idx}" => rule
    if length(rule.cidr_blocks) > 0
  } : {}

  type              = "egress"
  security_group_id = local.effective_security_group_id
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = each.value.cidr_blocks
  description       = try(each.value.description, null)
}

resource "aws_security_group_rule" "ingress_self" {
  for_each = local.rules_enabled ? {
    for idx, rule in var.ingress_self_rules :
    "ingress-self-${idx}" => rule
  } : {}

  type              = "ingress"
  security_group_id = local.effective_security_group_id
  self              = true
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
}

resource "aws_security_group_rule" "egress_self" {
  for_each = local.rules_enabled ? {
    for idx, rule in var.egress_self_rules :
    "egress-self-${idx}" => rule
  } : {}

  type              = "egress"
  security_group_id = local.effective_security_group_id
  self              = true
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
}

resource "aws_security_group_rule" "ingress_source_sg" {
  for_each = local.rules_enabled ? {
    for idx, rule in var.ingress_source_security_group_rules :
    "ingress-source-sg-${idx}" => rule
    if length(rule.source_security_group_id) > 0
  } : {}

  type                     = "ingress"
  security_group_id        = local.effective_security_group_id
  source_security_group_id = each.value.source_security_group_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = try(each.value.description, null)
}

resource "aws_security_group_rule" "egress_source_sg" {
  for_each = local.rules_enabled ? {
    for idx, rule in var.egress_source_security_group_rules :
    "egress-source-sg-${idx}" => rule
    if length(rule.source_security_group_id) > 0
  } : {}

  type                     = "egress"
  security_group_id        = local.effective_security_group_id
  source_security_group_id = each.value.source_security_group_id
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  description              = try(each.value.description, null)
}

resource "aws_security_group_rule" "ingress_prefix_list" {
  for_each = local.rules_enabled ? {
    for idx, rule in var.ingress_prefix_list_rules :
    "ingress-prefix-list-${idx}" => rule
    if try(length(rule.prefix_list_ids), 0) > 0 || local.create_managed_prefix_list
  } : {}

  type              = "ingress"
  security_group_id = local.effective_security_group_id
  prefix_list_ids   = try(length(each.value.prefix_list_ids), 0) > 0 ? each.value.prefix_list_ids : [local.default_prefix_list_id]
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
}

resource "aws_security_group_rule" "egress_prefix_list" {
  for_each = local.rules_enabled ? {
    for idx, rule in var.egress_prefix_list_rules :
    "egress-prefix-list-${idx}" => rule
    if try(length(rule.prefix_list_ids), 0) > 0 || local.create_managed_prefix_list
  } : {}

  type              = "egress"
  security_group_id = local.effective_security_group_id
  prefix_list_ids   = try(length(each.value.prefix_list_ids), 0) > 0 ? each.value.prefix_list_ids : [local.default_prefix_list_id]
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  description       = try(each.value.description, null)
}

output "security_group_id" {
  description = "ID of the managed or existing security group."
  value       = local.effective_security_group_id
}

output "vpc_id" {
  description = "VPC ID used by the security group."
  value       = local.vpc_id
}

output "managed_prefix_list_id" {
  description = "ID of the managed prefix list, if created."
  value       = local.default_prefix_list_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

###############################################################################
# Provider configuration
###############################################################################
provider "aws" {
  region = var.aws_region
}

###############################################################################
# Input variables
###############################################################################
variable "aws_region" {
  description = "AWS region where the CloudForecast integration role is created."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the third-party (CloudForecast) IAM integration role."
  type        = string
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  description = "External ID that CloudForecast must present when assuming the role."
  type        = string
  default     = "benchmark-external-id"
}

variable "cloudforecast_principal_arn" {
  description = "Cross-account principal ARN allowed to assume the role."
  type        = string
  default     = "arn:aws:iam::656227328603:root"
}

variable "tags" {
  description = "Tags applied to the integration role."
  type        = map(string)
  default = {
    ManagedBy   = "Terraform"
    Integration = "CloudForecast"
    Purpose     = "ZeroWaste-CostOptimization"
  }
}

###############################################################################
# Assume-role trust policy (cross-account + external ID condition)
###############################################################################
data "aws_iam_policy_document" "cloudforecast_assume_role" {
  statement {
    sid     = "AllowCloudForecastCrossAccountAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [var.cloudforecast_principal_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.external_id]
    }
  }
}

###############################################################################
# IAM role
###############################################################################
resource "aws_iam_role" "cloudforecast" {
  name                 = var.role_name
  description          = "Read-only role for CloudForecast cost optimization and waste monitoring (Zero Waste)."
  max_session_duration = 43200
  assume_role_policy   = data.aws_iam_policy_document.cloudforecast_assume_role.json

  tags = var.tags
}

###############################################################################
# Inline policy 1: Common metrics and resource tags
###############################################################################
resource "aws_iam_role_policy" "common_metrics_and_resource_tags" {
  name = "CloudForecast-CommonMetricsAndResourceTags"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CommonMetricsAndResourceTags"
        Effect = "Allow"
        Action = [
          "cloudwatch:GetMetricStatistics",
          "tag:GetResources"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 2: AWS Organizations
###############################################################################
resource "aws_iam_role_policy" "organizations_list_accounts" {
  name = "CloudForecast-OrganizationsListAccounts"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "OrganizationsListAccounts"
        Effect   = "Allow"
        Action   = ["organizations:ListAccounts"]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 3: ALB / ELB load balancers and tags
###############################################################################
resource "aws_iam_role_policy" "elb_load_balancers_and_tags" {
  name = "CloudForecast-ELBLoadBalancersAndTags"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ELBLoadBalancersAndTags"
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeLoadBalancerAttributes",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetGroupAttributes",
          "elasticloadbalancing:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 4: EBS snapshots
###############################################################################
resource "aws_iam_role_policy" "ebs_snapshots" {
  name = "CloudForecast-EBSSnapshots"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EBSSnapshots"
        Effect = "Allow"
        Action = [
          "ec2:DescribeSnapshots",
          "ec2:DescribeSnapshotAttribute"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 5: EBS volumes
###############################################################################
resource "aws_iam_role_policy" "ebs_volumes" {
  name = "CloudForecast-EBSVolumes"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EBSVolumes"
        Effect = "Allow"
        Action = [
          "ec2:DescribeVolumes",
          "ec2:DescribeVolumeStatus",
          "ec2:DescribeVolumeAttribute"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 6: EC2 instances
###############################################################################
resource "aws_iam_role_policy" "ec2_instances" {
  name = "CloudForecast-EC2Instances"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2Instances"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 7: RDS instances
###############################################################################
resource "aws_iam_role_policy" "rds_instances" {
  name = "CloudForecast-RDSInstances"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RDSInstances"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances",
          "rds:ListTagsForResource"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 8: RDS snapshots
###############################################################################
resource "aws_iam_role_policy" "rds_snapshots" {
  name = "CloudForecast-RDSSnapshots"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RDSSnapshots"
        Effect = "Allow"
        Action = [
          "rds:DescribeDBSnapshots",
          "rds:DescribeDBSnapshotAttributes"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 9: S3 bucket metadata (list all buckets)
###############################################################################
resource "aws_iam_role_policy" "s3_list_all_my_buckets" {
  name = "CloudForecast-S3ListAllMyBuckets"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "S3ListAllMyBuckets"
        Effect   = "Allow"
        Action   = ["s3:ListAllMyBuckets"]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 10: S3 list bucket contents
###############################################################################
resource "aws_iam_role_policy" "s3_list_bucket" {
  name = "CloudForecast-S3ListBucket"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "S3ListBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 11: S3 bucket location
###############################################################################
resource "aws_iam_role_policy" "s3_get_bucket_location" {
  name = "CloudForecast-S3GetBucketLocation"
  role = aws_iam_role.cloudforecast.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "S3GetBucketLocation"
