        Action   = ["s3:GetLifecycleConfiguration"]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Inline policy 14: CloudWatch log group metadata
###############################################################################
resource "aws_iam_role_policy" "logs_describe_log_groups" {
  name = "CloudForecast-LogsDescribeLogGroups"
