}

output "cloudforecast_external_id" {
  description = "External ID required to assume the role."
  value       = var.external_id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment suffix for IAM user names"
  type        = string
  default     = "dev"
}

variable "create_db_dr_user" {
  description = "Whether to create the database disaster recovery IAM user"
  type        = bool
  default     = false
}

variable "create_data_exports_user" {
  description = "Whether to create the data exports IAM user"
  type        = bool
  default     = false
}

variable "create_packer_builder_user" {
  description = "Whether to create the Packer image builder IAM user"
  type        = bool
  default     = false
}

variable "s3_export_bucket_arn" {
  description = "ARN of the S3 bucket for data exports (required if create_data_exports_user is true)"
  type        = string
  default     = ""
}

variable "s3_monitoring_bucket_arn" {
  description = "ARN of the S3 bucket for Packer monitoring state (required if create_packer_builder_user is true)"
  type        = string
  default     = ""
}

variable "packer_server_role_name" {
  description = "Name of the dedicated server role that Packer will pass to EC2 instances"
  type        = string
  default     = "mattermost-bind-server"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Mandatory cost reporting user
resource "aws_iam_user" "cost_report" {
  name = "mattermost-cost-report-${var.environment}"
  path = "/"

  tags = {
    Environment = var.environment
    Purpose     = "cost-reporting"
  }
}

resource "aws_iam_user_policy" "cost_report" {
  name = "mattermost-cost-report-policy"
  user = aws_iam_user.cost_report.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ce:*"
        Resource = "*"
      }
    ]
  })
}

# Optional: Database disaster recovery user
resource "aws_iam_user" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-${var.environment}"
  path  = "/"

  tags = {
    Environment = var.environment
    Purpose     = "database-disaster-recovery"
  }
}

resource "aws_iam_user_policy" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-policy"
  user  = aws_iam_user.db_dr[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "RDSFullAccess"
        Effect   = "Allow"
        Action   = "rds:*"
        Resource = "*"
      },
      {
        Sid      = "KMSFullAccess"
        Effect   = "Allow"
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecretVersionIds",
          "secretsmanager:GetResourcePolicy"
        ]
        Resource = "arn:aws:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:rds-cluster-multitenant-*"
      }
    ]
  })
}

# Optional: Data exports user
resource "aws_iam_user" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${var.environment}"
  path  = "/"

  tags = {
    Environment = var.environment
    Purpose     = "data-exports"
  }
}

resource "aws_iam_user_policy" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-policy"
  user  = aws_iam_user.data_exports[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListExportBucket"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = var.s3_export_bucket_arn
      },
      {
        Sid    = "ReadWriteObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${var.s3_export_bucket_arn}/*"
      }
    ]
  })
}

# Optional: Packer image builder user
resource "aws_iam_user" "packer_builder" {
  count = var.create_packer_builder_user ? 1 : 0
  name  = "mattermost-packer-builder-${var.environment}"
  path  = "/"

  tags = {
    Environment = var.environment
    Purpose     = "packer-image-builder"
  }
}

data "aws_iam_policy_document" "packer_builder" {
  count = var.create_packer_builder_user ? 1 : 0

  statement {
    sid       = "EC2FullAccess"
    effect    = "Allow"
    actions   = ["ec2:*"]
    resources = ["*"]
  }

  statement {
    sid       = "AutoScalingFullAccess"
    effect    = "Allow"
    actions   = ["autoscaling:*"]
    resources = ["*"]
  }

  statement {
    sid       = "CloudWatchEventsFullAccess"
    effect    = "Allow"
    actions   = ["events:*"]
    resources = ["*"]
  }

  statement {
    sid    = "SSMParameterAccess"
    effect = "Allow"
    actions = [
      "ssm:DescribeParameters",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath",
      "ssm:ListTagsForResource"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IAMInspection"
    effect = "Allow"
    actions = [
      "iam:GetInstanceProfile",
      "iam:GetRole",
      "iam:GetRolePolicy",
      "iam:ListInstanceProfiles",
      "iam:ListInstanceProfilesForRole",
      "iam:ListRoles",
      "iam:ListRolePolicies",
      "iam:ListAttachedRolePolicies"
    ]
    resources = ["*"]
  }

  statement {
    sid       = "S3MonitoringStateBucketList"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [var.s3_monitoring_bucket_arn]
  }

  statement {
    sid    = "S3MonitoringStateBucketObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = ["${var.s3_monitoring_bucket_arn}/*"]
  }

  statement {
    sid    = "LambdaConfigAccess"
    effect = "Allow"
    actions = [
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:UpdateFunctionConfiguration",
      "lambda:GetPolicy",
      "lambda:AddPermission",
      "lambda:RemovePermission"
    ]
    resources = [
      "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:bind-server-network-attachment"
    ]
  }

  statement {
    sid       = "PassRoleToDedicatedServerRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [
      "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${var.packer_server_role_name}"
    ]
  }
}

resource "aws_iam_policy" "packer_builder" {
  count       = var.create_packer_builder_user ? 1 : 0
  name        = "mattermost-packer-builder-policy-${var.environment}"
  description = "Policy for Packer image builder user"
  policy      = data.aws_iam_policy_document.packer_builder[0].json
}

resource "aws_iam_user_policy_attachment" "packer_builder" {
  count      = var.create_packer_builder_user ? 1 : 0
  user       = aws_iam_user.packer_builder[0].name
  policy_arn = aws_iam_policy.packer_builder[0].arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "output_bucket_name" {
  description = "Name of the S3 bucket for HealthOmics output"
  type        = string
  default     = "tf-benchmark-omics-output-bucket"
}

variable "service_user_name" {
  description = "Name of the IAM user for programmatic access"
  type        = string
  default     = "workbench-health-omics"
}

variable "iam_role_name" {
  description = "Name of the IAM role for HealthOmics"
  type        = string
  default     = "HealthOmicsRole"
}

variable "service_policy_name" {
  description = "Name of the IAM policy for the HealthOmics service role"
  type        = string
  default     = "HealthOmicsServicePolicy"
}

variable "user_policy_name" {
  description = "Name of the IAM policy for the HealthOmics user"
  type        = string
  default     = "HealthOmicsUserPolicy"
}

variable "ecr_repository_names" {
  description = "List of ECR repository names to create"
  type        = list(string)
  default     = ["healthomics-test-repo"]
}

variable "external_account_ids" {
  description = "List of external AWS account IDs to grant cross-account ECR access"
  type        = list(string)
  default     = []
}

variable "additional_s3_bucket_arns" {
  description = "List of additional S3 bucket ARNs for read-only access"
  type        = list(string)
  default     = []
}

# -----------------------------------------------------------------------------
# Data sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# KMS key for output bucket encryption
# -----------------------------------------------------------------------------
resource "aws_kms_key" "omics_output" {
  description             = "KMS key for HealthOmics output bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

# -----------------------------------------------------------------------------
# S3 output bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "omics_output" {
  bucket        = var.output_bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "omics_output" {
  bucket                  = aws_s3_bucket.omics_output.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "omics_output" {
  bucket = aws_s3_bucket.omics_output.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.omics_output.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# -----------------------------------------------------------------------------
# ECR repositories
# -----------------------------------------------------------------------------
resource "aws_ecr_repository" "omics" {
  for_each = toset(var.ecr_repository_names)
  name     = each.value

  image_tag_mutability = "MUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

data "aws_iam_policy_document" "ecr_repo_policy" {
  statement {
    sid    = "AllowHealthOmicsPull"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
    actions = [
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability"
    ]
  }

  dynamic "statement" {
    for_each = length(var.external_account_ids) > 0 ? [1] : []
    content {
      sid    = "AllowCrossAccountPull"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = formatlist("arn:aws:iam::%s:root", var.external_account_ids)
      }
      actions = [
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchGetImage",
        "ecr:BatchCheckLayerAvailability"
      ]
    }
  }
}

resource "aws_ecr_repository_policy" "omics" {
  for_each   = aws_ecr_repository.omics
  repository = each.value.name
  policy     = data.aws_iam_policy_document.ecr_repo_policy.json
}

# -----------------------------------------------------------------------------
# IAM role for HealthOmics
# -----------------------------------------------------------------------------
resource "aws_iam_role" "health_omics" {
  name               = var.iam_role_name
  assume_role_policy = data.aws_iam_policy_document.health_omics_assume_role.json
}

data "aws_iam_policy_document" "health_omics_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# -----------------------------------------------------------------------------
# IAM policy for HealthOmics service (attached to role)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "health_omics_service" {
  statement {
    sid       = "FullOmicsAccess"
    effect    = "Allow"
    actions   = ["omics:*"]
    resources = ["*"]
  }

  statement {
    sid    = "S3OutputAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.omics_output.arn,
      "${aws_s3_bucket.omics_output.arn}/*"
    ]
  }

  statement {
    sid       = "ECRGetAuthToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  dynamic "statement" {
    for_each = length(aws_ecr_repository.omics) > 0 ? [1] : []
    content {
      sid    = "ECRPullAccess"
      effect = "Allow"
      actions = [
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchGetImage",
        "ecr:BatchCheckLayerAvailability"
      ]
      resources = [for repo in aws_ecr_repository.omics : repo.arn]
    }
  }

  statement {
    sid    = "KMSAccess"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.omics_output.arn]
  }
}

resource "aws_iam_policy" "health_omics_service" {
  name   = var.service_policy_name
  policy = data.aws_iam_policy_document.health_omics_service.json
}

resource "aws_iam_role_policy_attachment" "health_omics_service" {
  role       = aws_iam_role.health_omics.name
  policy_arn = aws_iam_policy.health_omics_service.arn
}

# -----------------------------------------------------------------------------
# IAM user for programmatic access
# -----------------------------------------------------------------------------
resource "aws_iam_user" "health_omics" {
  name = var.service_user_name
}

resource "aws_iam_access_key" "health_omics" {
  user = aws_iam_user.health_omics.name
}

# -----------------------------------------------------------------------------
# IAM policy for user
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "health_omics_user" {
  statement {
    sid       = "FullOmicsActions"
    effect    = "Allow"
    actions   = ["omics:*"]
    resources = ["*"]
  }

  statement {
    sid       = "PassRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.health_omics.arn]
  }

  statement {
    sid    = "S3ReadOnlyOutput"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.omics_output.arn,
      "${aws_s3_bucket.omics_output.arn}/*"
    ]
  }

  dynamic "statement" {
    for_each = length(var.additional_s3_bucket_arns) > 0 ? [1] : []
    content {
      sid    = "S3ReadOnlyAdditional"
      effect = "Allow"
      actions = [
        "s3:GetObject",
        "s3:ListBucket",
        "s3:GetBucketLocation"
      ]
      resources = flatten([
        for arn in var.additional_s3_bucket_arns : [
          arn,
          "${arn}/*"
        ]
      ])
    }
  }

  statement {
    sid    = "KMSAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.omics_output.arn]
  }
}

resource "aws_iam_policy" "health_omics_user" {
  name   = var.user_policy_name
  policy = data.aws_iam_policy_document.health_omics_user.json
}

resource "aws_iam_user_policy_attachment" "health_omics_user" {
  user       = aws_iam_user.health_omics.name
  policy_arn = aws_iam_policy.health_omics_user.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "aws_access_key_id" {
  value     = aws_iam_access_key.health_omics.id
  sensitive = true
}

output "aws_secret_access_key" {
  value     = aws_iam_access_key.health_omics.secret
  sensitive = true
}

output "health_omics_role_arn" {
  value = aws_iam_role.health_omics.arn
}

output "output_bucket_name" {
  value = aws_s3_bucket.omics_output.bucket
}

output "ecr_repository_urls" {
  value = { for name, repo in aws_ecr_repository.omics : name => repo.repository_url }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.default_tags
  }
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the cluster"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  description = "First two octets for the VPC CIDR block"
  type        = string
  default     = "10.0"
}

variable "default_tags" {
  description = "Default tags to apply to all resources"
  type        = map(string)
  default     = {}
}

locals {
  azs = ["${var.aws_region}a", "${var.aws_region}b", "${var.aws_region}c"]

  public_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.12.0/22",
    "${var.vpc_cidr_network_octets}.16.0/22",
    "${var.vpc_cidr_network_octets}.20.0/22"
  ]

  private_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.0.0/22",
    "${var.vpc_cidr_network_octets}.4.0/22",
    "${var.vpc_cidr_network_octets}.8.0/22"
  ]
}

resource "aws_vpc" "this" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.cluster_name}-ig"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.cluster_name}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.this.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.cluster_name}-private-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "${var.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "${var.cluster_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "this" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.cluster_name}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this[count.index].id
  }

  tags = {
    Name = "${var.cluster_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_ecs_cluster" "this" {
  name = "dit-paas-${var.cluster_name}-cluster"

  tags = {
    Name = "dit-paas-${var.cluster_name}-cluster"
  }
}

resource "aws_iam_role" "ecs_task_execution" {
  name = "dit-paas-${var.cluster_name}-ecs-task-execution"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "dit-paas-${var.cluster_name}-ecs-task-execution"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

###############################################################################
# Network stack: VPC + dynamic public/private subnets + VPC endpoints
# (S3 Gateway endpoint + private-DNS Interface endpoints for ECR, Logs, SSM, KMS)
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the network stack is deployed"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC; also used as the base name for derived resources"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary IPv4 CIDR block assigned to the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

variable "availability_zones" {
  description = "Availability zones across which public/private subnets are provisioned"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "tags" {
  description = "Additional tags applied to every resource created by this stack"
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  # Interface endpoints required by the containerized workloads
  interface_endpoints = {
    ecr_docker = "ecr.dkr"
    ecr_api    = "ecr.api"
    logs       = "logs"
    ssm        = "ssm"
    kms        = "kms"
  }

  common_tags = merge(var.tags, {
    ManagedBy = "Terraform"
    Component = "network"
  })
}

###############################################################################
# VPC - DNS enabled, no IPv6 CIDR, default security group denies all traffic
###############################################################################

module "vpc" {
  source  = "cloudposse/vpc/aws"
  version = "~> 2.0"

  name       = var.vpc_name
  cidr_block = var.vpc_cidr

  enable_dns_hostnames = true
  enable_dns_support   = true

  # Disable generated IPv6 CIDR blocks
  assign_generated_ipv6_cidr_block = false

  # Manage the default security group and strip all ingress/egress rules
  default_security_group_deny_all = true

  tags = local.common_tags
}

###############################################################################
# Public and private subnets spread across the requested AZs, NAT enabled
###############################################################################

module "subnets" {
  source  = "cloudposse/dynamic-subnets/aws"
  version = "~> 2.0"

  name               = var.vpc_name
  vpc_id             = module.vpc.vpc_id
  igw_id             = [module.vpc.igw_id]
  cidr_block         = module.vpc.vpc_cidr_block
  availability_zones = var.availability_zones

  # NAT gateways provide outbound routing for the private subnets
  nat_gateway_enabled  = true
  nat_instance_enabled = false

  tags = local.common_tags
}

###############################################################################
# VPC main ("default") route table lookup, used for the S3 gateway endpoint
###############################################################################

data "aws_route_table" "default" {
  vpc_id = module.vpc.vpc_id

  filter {
    name   = "association.main"
    values = ["true"]
  }
}

###############################################################################
# Security group dedicated to the interface endpoints: HTTPS (443) only,
# self-referencing ingress and egress
###############################################################################

resource "aws_security_group" "vpc_endpoint" {
  name        = "vpc_endpoint_sg"
  description = "Controls access to the VPC interface endpoints - HTTPS (443) self-referencing only"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "Allow HTTPS from resources associated with this security group"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow HTTPS back to resources associated with this security group"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  tags = merge(local.common_tags, {
    Name = "vpc_endpoint_sg"
  })
}

###############################################################################
# S3 Gateway VPC endpoint (public, private and default route tables)
###############################################################################

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = module.vpc.vpc_id
  service_name      = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = concat(
    module.subnets.public_route_table_ids,
    module.subnets.private_route_table_ids,
    [data.aws_route_table.default.id]
  )

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccessFromVPC"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource  = "*"
        Condition = {
          StringEquals = {
            "aws:SourceVpc" = module.vpc.vpc_id
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-s3-gateway-endpoint"
  })
}

###############################################################################
# Interface VPC endpoints (private DNS enabled) in the private subnets:
# ECR Docker, ECR API, CloudWatch Logs, SSM and KMS
###############################################################################

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoints

  vpc_id              = module.vpc.vpc_id
  service_name        = "com.amazonaws.${var.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = module.subnets.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-${replace(each.value, ".", "-")}-endpoint"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC"
  value       = module.vpc.vpc_id
}

output "vpc_cidr_block" {
  description = "Primary IPv4 CIDR block of the VPC"
  value       = module.vpc.vpc_cidr_block
}

output "availability_zones" {
  description = "Availability zones used for subnet provisioning"
  value       = var.availability_zones
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = module.subnets.public_subnet_ids
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = module.subnets.private_subnet_ids
}

output "public_route_table_ids" {
  description = "IDs of the public route tables"
  value       = module.subnets.public_route_table_ids
}

output "private_route_table_ids" {
  description = "IDs of the private route tables"
  value       = module.subnets.private_route_table_ids
}

output "default_route_table_id" {
  description = "ID of the VPC main (default) route table"
  value       = data.aws_route_table.default.id
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways created for private subnet egress"
  value       = module.subnets.nat_gateway_ids
}

output "vpc_endpoint_security_group_id" {
  description = "ID of the vpc_endpoint_sg security group used by the interface endpoints"
  value       = aws_security_group.vpc_endpoint.id
}

output "s3_gateway_endpoint_id" {
  description = "ID of the S3 Gateway VPC endpoint"
  value       = aws_vpc_endpoint.s3.id
}

output "interface_endpoint_ids" {
  description = "Map of interface endpoint keys to their endpoint IDs"
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.id }
}

output "interface_endpoint_dns_entries" {
  description = "Map of interface endpoint keys to their private DNS entries"
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.dns_entry }
}

Here is a self-contained Terraform template that deploys a VPC with VPC Flow Logs, flexible VPC endpoints, and conditional SSM instance role support.
```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Tenancy of instances in the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "flow_logs_retention_days" {
  description = "Retention period for VPC flow logs in CloudWatch"
  type        = number
  default     = 180
}

variable "aws_endpoint_services" {
  description = "List of standard AWS services for interface endpoints"
  type        = list(string)
  default     = ["logs"]
}

variable "custom_endpoint_services" {
  description = "List of custom endpoint services"
  type = list(object({
    key          = string
    service_name = string
    port         = number
  }))
  default = []
}

variable "source_security_group_ids" {
  description = "List of source security group IDs for endpoint access"
  type        = list(string)
  default     = []
}

variable "route_table_ids" {
  description = "Optional list of route table IDs for gateway endpoints. If empty, a new route table will be created and used."
  type        = list(string)
  default     = []
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  # Determine which route tables to use for gateway endpoints
  gateway_route_table_ids = length(var.route_table_ids) > 0 ? var.route_table_ids : [aws_route_table.main.id]

  # Flatten custom endpoint service rules (port + source SG combination)
  custom_endpoint_rules = flatten([
    for svc in var.custom_endpoint_services : [
      for sg in var.source_security_group_ids : {
        key   = "${svc.key}-${sg}"
        port  = svc.port
        sg_id = sg
      }
    ]
  ])

  # Conditional creation of SSM role & instance profile
  create_ssm_role = contains(var.aws_endpoint_services, "ssm")
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = var.vpc_name
  }
}

# Default security group management
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  # Allow all outbound traffic (default behaviour)
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "default-${var.vpc_name}"
  }
}

# Subnet for interface endpoints
resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${var.vpc_name}-subnet"
  }
}

# Route table (used for gateway endpoints if none provided)
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-route-table"
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

# ------------------------------------------------------------------------------
# VPC Flow Logs
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = var.flow_logs_retention_days

  tags = {
    Name = "/aws/vpc-flow-logs/${var.vpc_name}"
  }
}

resource "aws_iam_role" "flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "vpc_flow_logs_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc_flow_logs_policy_${var.vpc_name}"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_logs.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  vpc_id               = aws_vpc.main.id
  traffic_type         = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.flow_logs.arn
  iam_role_arn         = aws_iam_role.flow_logs.arn

  tags = {
    Name = "vpc-flow-log-${var.vpc_name}"
  }
}

# ------------------------------------------------------------------------------
# Security Groups for VPC Endpoints
# ------------------------------------------------------------------------------

# Standard AWS interface endpoints security group
resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security group for standard AWS interface endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc-endpoints-${var.vpc_name}"
  }
}

resource "aws_security_group_rule" "vpc_endpoints_ingress" {
  for_each = toset(var.source_security_group_ids)

  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = each.value
  description              = "HTTPS from ${each.value}"
}

resource "aws_security_group_rule" "vpc_endpoints_egress" {
  for_each = toset(var.source_security_group_ids)

  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = each.value
  description              = "HTTPS to ${each.value}"
}

# Custom endpoint services security group
resource "aws_security_group" "custom_endpoints" {
  name        = "custom-endpoints-${var.vpc_name}"
  description = "Security group for custom VPC endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "custom-endpoints-${var.vpc_name}"
  }
}

resource "aws_security_group_rule" "custom_endpoints_ingress" {
  for_each = { for r in local.custom_endpoint_rules : r.key => r }

  type                     = "ingress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  security_group_id        = aws_security_group.custom_endpoints.id
  source_security_group_id = each.value.sg_id
  description              = "Custom port ${each.value.port} from ${each.value.sg_id}"
}

resource "aws_security_group_rule" "custom_endpoints_egress" {
  for_each = { for r in local.custom_endpoint_rules : r.key => r }

  type                     = "egress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  security_group_id        = aws_security_group.custom_endpoints.id
  source_security_group_id = each.value.sg_id
  description              = "Custom port ${each.value.port} to ${each.value.sg_id}"
}

# ------------------------------------------------------------------------------
# VPC Endpoints
# ------------------------------------------------------------------------------

# Gateway endpoints for dynamodb and s3
resource "aws_vpc_endpoint" "gateway" {
  for_each = toset(["dynamodb", "s3"])

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.${each.value}"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = local.gateway_route_table_ids

  tags = {
    Name = "${each.value}-gateway-endpoint"
  }
}

# Interface endpoints for standard AWS services (default: logs)
resource "aws_vpc_endpoint" "interface" {
  for_each = toset(var.aws_endpoint_services)

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${each.value}-interface-endpoint"
  }
}

# Interface endpoints for custom services (non-private DNS)
resource "aws_vpc_endpoint" "custom" {
  for_each = { for svc in var.custom_endpoint_services : svc.key => svc }

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.custom_endpoints.id]
  private_dns_enabled = false

  tags = {
    Name = "${each.value.key}-custom-endpoint"
  }
}

# ------------------------------------------------------------------------------
# Conditional SSM IAM Role and Instance Profile
# ------------------------------------------------------------------------------

resource "aws_iam_role" "ssm" {
  count = local.create_ssm_role ? 1 : 0

  name = "ssm_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "ssm_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy_attachment" "ssm" {
  count = local.create_ssm_role ? 1 : 0

  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.create_ssm_role ? 1 : 0

  name = "ssm_${var.vpc_name}"
  role = aws_iam_role.ssm[0].name
}
```
### VPC, Flow Logs, and Endpoint Architecture

The template provisions a VPC with configurable name, CIDR, and DNS hostnames, then adds VPC Flow Logs to CloudWatch with a dedicated IAM role. It creates two security groups for endpoint traffic and three types of VPC endpoints.

- **Core VPC and logging** – The VPC defaults to `benchmark-vpc` and `10.0.0.0/16`, enabling DNS hostnames. Flow logs capture all traffic and store them in `/aws/vpc-flow-logs/{vpc_name}` with 180-day retention. A dedicated IAM role and policy permit log stream creation and event delivery.

- **Security group management** – The default security group allows all outbound traffic. A standard endpoint security group allows HTTPS (port 443) ingress and egress from specified source security group IDs. A custom endpoint security group creates rules for each combination of custom service port and source security group ID.

- **Endpoint creation** – Gateway endpoints for `dynamodb` and `s3` attach to provided route tables (or one created automatically). Interface endpoints for standard AWS services (default `["logs"]`) enable private DNS. Custom interface endpoints use non-private DNS and are defined by key, service name, and port.

- **Conditional SSM support** – If `ssm` appears in the endpoint services list, an IAM role and instance profile named `ssm_{vpc_name}` are created with EC2 trust and the `AmazonSSMManagedInstanceCore` policy attached.
---

**Optimization Tip:** You can customize the VPC name, CIDR, endpoint service lists, and source security group IDs by editing the variable defaults. The `custom_endpoint_services` variable accepts objects with `key`, `service_name`, and `port` fields to define non-AWS endpoints.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Context / data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = var.aws_region

  # Default EBS KMS key: external ARN when provided, otherwise the compute CMK
  ebs_default_kms_key_arn = var.ebs_default_kms_key_arn != "" ? var.ebs_default_kms_key_arn : aws_kms_key.compute.arn

  common_tags = merge(
    var.tags,
    {
      Project   = var.project_name
      ManagedBy = "terraform"
      Layer     = "security-baseline"
    }
  )
}

###############################################################################
# KMS key policies
###############################################################################

# ---------------------------- COMPUTE ---------------------------------------
data "aws_iam_policy_document" "compute_kms" {
  statement {
    sid    = "AllowAccountRootFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEC2ServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowAutoScalingServiceRoleUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["autoscaling.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RetireGrant",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

# -------------------------- OBSERVABILITY -----------------------------------
data "aws_iam_policy_document" "observability_kms" {
  statement {
    sid    = "AllowAccountRootFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # CloudWatch Logs (conditioned on the log group encryption context)
  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # CloudTrail
  statement {
    sid    = "AllowCloudTrailUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
    ]

    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/*"]
    }
  }

  # CloudWatch Alarms
  statement {
    sid    = "AllowCloudWatchAlarmsUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # SNS
  statement {
    sid    = "AllowSNSUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # SQS
  statement {
    sid    = "AllowSQSUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # EventBridge
  statement {
    sid    = "AllowEventBridgeUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

# ----------------------------- STORAGE --------------------------------------
data "aws_iam_policy_document" "storage_kms" {
  statement {
    sid    = "AllowAccountRootFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  # S3 service usage
  statement {
    sid    = "AllowS3ServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # AWS Config encrypted snapshot / configuration item delivery
  statement {
    sid    = "AllowConfigEncryptedSnapshotDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  # CloudTrail log file encryption
  statement {
    sid    = "AllowCloudTrailLogEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
    ]

    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/*"]
    }
  }
}

###############################################################################
# KMS customer managed keys
###############################################################################

resource "aws_kms_key" "compute" {
  description             = "${var.project_name} compute layer customer managed key"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.compute_kms.json

  tags = merge(local.common_tags, { Layer = "compute" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.key_id
}

resource "aws_kms_key" "observability" {
  description             = "${var.project_name} observability layer customer managed key"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.observability_kms.json

  tags = merge(local.common_tags, { Layer = "observability" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.key_id
}

resource "aws_kms_key" "storage" {
  description             = "${var.project_name} storage layer customer managed key"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_rotation_period_days
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.storage_kms.json

  tags = merge(local.common_tags, { Layer = "storage" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.key_id
}

###############################################################################
# Account-level EBS encryption defaults
###############################################################################

resource "aws_ebs_encryption_by_default" "this" {
  enabled = true
}

resource "aws_ebs_default_kms_key" "this" {
  key_arn = local.ebs_default_kms_key_arn

  depends_on = [
    aws_kms_key.compute,
    aws_kms_alias.compute,
  ]
}

###############################################################################
# Account-level public access restrictions / hardening
###############################################################################

resource "aws_ec2_image_block_public_access" "this" {
  state = "block-new-sharing"
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  state = "block-all-sharing"
}

# IMDSv2 enforcement for all newly launched instances (account default)
resource "aws_ec2_instance_metadata_defaults" "this" {
  count = var.enforce_imdsv2_default ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.imds_hop_limit
  instance_metadata_tags      = "disabled"
}

# Disable account-level EC2 Serial Console access
resource "aws_ec2_serial_console_access" "this" {
  count = var.disable_serial_console ? 1 : 0

  enabled = false
}

# Restrict publicly accessible security groups in EMR
resource "aws_emr_block_public_access_configuration" "this" {
  count = var.enforce_emr_block_public_access ? 1 : 0

  block_public_security_group_rules = true
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the security baseline is deployed."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Project name used as the prefix for all KMS key aliases (alias/<project_name>-<layer>)."
  type        = string
  default     = "security-baseline"
}

variable "kms_rotation_period_days" {
  description = "Number of days between automatic rotations of each customer managed KMS key."
  type        = number
  default     = 90

  validation {
    condition     = var.kms_rotation_period_days >= 90 && var.kms_rotation_period_days <= 2560
    error_message = "kms_rotation_period_days must be between 90 and 2560 days."
  }
}

variable "ebs_default_kms_key_arn" {
  description = "Optional external KMS key ARN to use as the account default EBS encryption key. When empty, the internal compute KMS key is used."
  type        = string
  default     = ""
}

variable "enforce_imdsv2_default" {
  description = "When true, account-level EC2 instance metadata defaults require IMDSv2 (HTTP tokens required)."
  type        = bool
  default     = true
}

variable "imds_hop_limit" {
  description = "HTTP PUT response hop limit applied to the account-level EC2 instance metadata defaults."
  type        = number
  default     = 1

  validation {
    condition     = var.imds_hop_limit >= 1 && var.imds_hop_limit <= 64
    error_message = "imds_hop_limit must be between 1 and 64."
  }
}

variable "disable_serial_console" {
  description = "When true, account-level EC2 Serial Console access is disabled."
  type        = bool
  default     = true
}

variable "enforce_emr_block_public_access" {
  description = "When true, EMR block public access is configured to reject public security group rules."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags applied to all supported resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Outputs
###############################################################################

output "compute_kms_key_arn" {
  description = "ARN of the compute layer customer managed KMS key."
  value       = aws_kms_key.compute.arn
}

output "observability_kms_key_arn" {
  description = "ARN of the observability layer customer managed KMS key."
  value       = aws_kms_key.observability.arn
}

output "storage_kms_key_arn" {
  description = "ARN of the storage layer customer managed KMS key."
  value       = aws_kms_key.storage.arn
}

output "kms_key_aliases" {
  description = "Aliases created for each layer customer managed KMS key."
  value = {
    compute       = aws_kms_alias.compute.name
    observability = aws_kms_alias.observability.name
    storage       = aws_kms_alias.storage.name
  }
}

output "ebs_default_kms_key_arn" {
  description = "KMS key ARN currently configured as the account-level EBS default."
  value       = local.ebs_default_kms_key_arn
}

output "ec2_image_block_public_access_state" {
  description = "Account-level EC2 image block public access state."
  value       = aws_ec2_image_block_public_access.this.state
}

output "ebs_snapshot_block_public_access_state" {
  description = "Account-level EBS snapshot block public access state."
  value       = aws_ebs_snapshot_block_public_access.this.state
}

output "imdsv2_default_enforced" {
  description = "Whether account-level IMDSv2 enforcement (required HTTP tokens) is active."
  value       = var.enforce_imdsv2_default
}

output "serial_console_disabled" {
  description = "Whether account-level EC2 Serial Console access is disabled."
  value       = var.disable_serial_console
}

output "emr_block_public_access_enforced" {
  description = "Whether EMR block public access is enforced."
  value       = var.enforce_emr_block_public_access
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

############################################
# Variables
############################################

variable "region" {
  description = "AWS region to deploy the benchmark infrastructure into."
  type        = string
  default     = "us-east-1"
}

variable "cluster_prefix" {
  description = "Prefix used for naming all resources (restricted to 5-8 characters)."
  type        = string
  default     = "bench"

  validation {
    condition     = length(var.cluster_prefix) >= 5 && length(var.cluster_prefix) <= 8
    error_message = "The cluster_prefix value must be between 5 and 8 characters long."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "172.16.0.0/16"
}

variable "availability_zones" {
  description = "List of availability zones used to place subnets."
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "public_subnets" {
  description = "User-defined public subnet objects. az_index indexes into var.availability_zones."
  type = list(object({
    name     = string
    az_index = number
  }))
  default = [
    { name = "public-a", az_index = 0 },
    { name = "public-b", az_index = 1 },
  ]
}

variable "private_subnets" {
  description = "User-defined private subnet objects. az_index indexes into var.availability_zones."
  type = list(object({
    name     = string
    az_index = number
  }))
  default = [
    { name = "private-a", az_index = 0 },
    { name = "private-b", az_index = 1 },
  ]
}

variable "ssh_key_name" {
  description = "Name of the deployment SSH key pair."
  type        = string
  default     = "benchmark-keypair"
}

variable "ssh_public_key" {
  description = "Valid SSH public key string used for the deployment key pair."
  type        = string
  default     = "ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABAQDd0F3k4mQ8tI9ZrXqHc9VtLbY2uK7pWsN0rJxE1aF3mQvHnY8sT6cR4dP2gZkL5oUw9bC1eXjN7vB3mS8qA0hGzD2yIzY1uPnW5kMoR6tE9sV4cB7dJ2fH8aQ3lN0rXxZ1vY6wS8qA3tF5bG2nM4oP7kL9cV1xZ6yU0tE benchmark@example"
}

variable "ingress_cidr_rules" {
  description = "Dynamic ingress rules granting access from specific CIDR blocks."
  type = list(object({
    description = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_block  = string
  }))
  default = [
    {
      description = "SSH access"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "inventory_nodes" {
  description = "List of inventory compute nodes to provision."
  type = list(object({
    name             = string
    instance_type    = string
    subnet_index     = number
    root_volume_size = number
    assign_eip       = bool
    secondary_volumes = list(object({
      device_name = string
      size        = number
      mount_point = string
    }))
  }))
  default = [
    {
      name             = "node-1"
      instance_type    = "t3.micro"
      subnet_index     = 0
      root_volume_size = 20
      assign_eip       = true
      secondary_volumes = [
        { device_name = "/dev/sdf", size = 10, mount_point = "/data" }
      ]
    },
    {
      name             = "node-2"
      instance_type    = "t3.micro"
      subnet_index     = 2
      root_volume_size = 20
      assign_eip       = false
      secondary_volumes = [
        { device_name = "/dev/sdg", size = 10, mount_point = "/var/lib/data" }
      ]
    }
  ]
}

############################################
# Locals
############################################

locals {
  # Combined list of subnet IDs (public first, then private) used for index positioning.
  all_subnet_ids = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)

  # Flattened list of secondary volume definitions across all nodes.
  secondary_volumes = flatten([
    for n in var.inventory_nodes : [
      for v in n.secondary_volumes : {
        key         = "${n.name}-${v.device_name}"
        node        = n.name
        device_name = v.device_name
        size        = v.size
        mount_point = v.mount_point
      }
    ]
  ])
}

############################################
# Networking
############################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_prefix}-igw"
  }
}

resource "aws_key_pair" "deploy" {
  key_name   = var.ssh_key_name
  public_key = var.ssh_public_key

  tags = {
    Name = "${var.cluster_prefix}-${var.ssh_key_name}"
  }
}

############################################
# Subnets (dynamic CIDR allocation)
############################################

resource "aws_subnet" "public" {
  count = length(var.public_subnets)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = var.availability_zones[var.public_subnets[count.index].az_index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.cluster_prefix}-${var.public_subnets[count.index].name}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 128)
  availability_zone = var.availability_zones[var.private_subnets[count.index].az_index]

  tags = {
    Name = "${var.cluster_prefix}-${var.private_subnets[count.index].name}"
    Tier = "private"
  }
}

############################################
# Public routing
############################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.cluster_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnets)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

############################################
# Private routing (NAT Gateways + Elastic IPs + private route tables)
############################################

resource "aws_eip" "nat" {
  count  = length(var.private_subnets)
  domain = "vpc"

  tags = {
    Name = "${var.cluster_prefix}-nat-eip-${count.index}"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  count = length(var.private_subnets)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index % length(var.public_subnets)].id

  tags = {
    Name = "${var.cluster_prefix}-nat-${count.index}"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  count = length(var.private_subnets)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = "${var.cluster_prefix}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

############################################
# Security Group
############################################

resource "aws_security_group" "default" {
  name        = "${var.cluster_prefix}-default-sg"
  description = "Default security group for ${var.cluster_prefix} cluster"
  vpc_id      = aws_vpc.main.id

  # Full self-referencing intra-group ingress.
  ingress {
    description = "Allow all intra-group traffic (self reference)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  # Custom dynamic ingress CIDR rules.
  dynamic "ingress" {
    for_each = var.ingress_cidr_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = [ingress.value.cidr_block]
    }
  }

  # Outbound traffic restricted to the VPC CIDR only.
  egress {
    description = "Outbound traffic within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.cluster_prefix}-default-sg"
  }
}

############################################
# AMI lookup
############################################

data "aws_ami" "node" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

############################################
# Inventory compute nodes
############################################

resource "aws_instance" "node" {
  for_each = { for n in var.inventory_nodes : n.name => n }

  ami                    = data.aws_ami.node.id
  instance_type          = each.value.instance_type
  subnet_id              = local.all_subnet_ids[each.value.subnet_index]
  vpc_security_group_ids = [aws_security_group.default.id]
  key_name               = aws_key_pair.deploy.key_name
  ebs_optimized          = true

  root_block_device {
    volume_size = each.value.root_volume_size
    volume_type = "gp3"
  }

  tags = {
    Name = "${var.cluster_prefix}-${each.value.name}"
    Node = each.value.name
  }
}

############################################
# Optional Elastic IPs for nodes
############################################

resource "aws_eip" "node" {
  for_each = { for n in var.inventory_nodes : n.name => n if n.assign_eip }
  domain   = "vpc"

  tags = {
    Name = "${var.cluster_prefix}-${each.value.name}-eip"
  }
}

resource "aws_eip_association" "node" {
  for_each = { for n in var.inventory_nodes : n.name => n if n.assign_eip }

  instance_id   = aws_instance.node[each.key].id
  allocation_id = aws_eip.node[each.key].id
}

############################################
# Secondary EBS volumes + attachments
############################################

resource "aws_ebs_volume" "secondary" {
  for_each = { for v in local.secondary_volumes : v.key => v }

  availability_zone = aws_instance.node[each.value.node].availability_zone
  size              = each.value.size
  type              = "gp3"

  tags = {
    Name        = "${var.cluster_prefix}-${each.value.node}-vol"
    DeviceName  = each.value.device_name
    MountPoint  = each.value.mount_point
  }
}

resource "aws_volume_attachment" "secondary" {
  for_each = { for v in local.secondary_volumes : v.key => v }

  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.secondary[each.key].id
  instance_id = aws_instance.node[each.value.node].id
}

############################################
# Outputs
############################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ids" {
  description = "IDs of the provisioned NAT gateways."
  value       = aws_nat_gateway.nat[*].id
}

output "node_instance_ids" {
  description = "Instance IDs of the inventory nodes."
  value       = { for k, v in aws_instance.node : k => v.id }
}

output "node_public_ips" {
  description = "Elastic IPs assigned to nodes (where enabled)."
  value       = { for k, v in aws_eip.node : k => v.public_ip }
}

output "default_security_group_id" {
  description = "ID of the default security group."
  value       = aws_security_group.default.id
}

terraform {
  required_version = ">= 1.2"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "List of subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]
}

variable "enable_private_subnets" {
  description = "Toggle private subnets on or off"
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Enable NAT Gateway egress strategy"
  type        = bool
  default     = true
}

variable "enable_nat_instance" {
  description = "Enable NAT Instance egress strategy"
  type        = bool
  default     = false
}

variable "enable_egress_only_igw" {
  description = "Enable Egress-Only Internet Gateway egress strategy"
  type        = bool
  default     = false
}

variable "nat_instance_type" {
  description = "Instance type for NAT instances"
  type        = string
  default     = "m1.small"
}

variable "nat_instance_ami_id" {
  description = "Optional AMI ID for NAT instances. If empty, a recent Amazon Linux NAT AMI is used."
  type        = string
  default     = ""
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

data "aws_ami" "nat" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  azs = sort(data.aws_availability_zones.available.names)

  public_subnet_count  = var.enable_private_subnets ? 2 : 4
  private_subnet_count = var.enable_private_subnets ? 2 : 0

  public_subnet_cidrs  = var.enable_private_subnets ? slice(var.subnet_cidrs, 0, 2) : var.subnet_cidrs
  private_subnet_cidrs = var.enable_private_subnets ? slice(var.subnet_cidrs, 2, 4) : []

  public_azs  = slice(local.azs, 0, local.public_subnet_count)
  private_azs = var.enable_private_subnets ? slice(local.azs, 0, 2) : []

  private_route_table_ids = var.enable_private_subnets ? (
    var.enable_nat_gateway ? aws_route_table.private_nat_gateway[*].id :
    var.enable_nat_instance ? aws_route_table.private_nat_instance[*].id :
    var.enable_egress_only_igw ? aws_route_table.private_eigw[*].id :
    []
  ) : []
}

resource "aws_vpc" "this" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = var.enable_private_subnets && var.enable_egress_only_igw

  tags = {
    Name = var.vpc_name
  }

  lifecycle {
    precondition {
      condition     = length([for e in [var.enable_nat_gateway, var.enable_nat_instance, var.enable_egress_only_igw] : e if e]) <= 1
      error_message = "At most one private egress strategy can be enabled: enable_nat_gateway, enable_nat_instance, or enable_egress_only_igw."
    }
  }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.this.id

  ingress {
    self      = true
    from_port = 0
    to_port   = 0
    protocol  = "-1"
  }

  egress {
    self      = true
    from_port = 0
    to_port   = 0
    protocol  = "-1"
  }

  tags = {
    Name = "${var.vpc_name}-default-sg"
  }
}

resource "aws_security_group" "tls" {
  name        = "${var.vpc_name}-tls"
  description = "Allow inbound TLS on port 443"
  vpc_id      = aws_vpc.this.id

  ingress {
    description      = "TLS from anywhere"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  egress {
    description      = "Allow all outbound"
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  tags = {
    Name = "${var.vpc_name}-tls"
  }
}

resource "aws_subnet" "public" {
  count                   = local.public_subnet_count
  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.public_azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.vpc_name}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = local.private_subnet_count
  vpc_id            = aws_vpc.this.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.private_azs[count.index]
  ipv6_cidr_block   = var.enable_private_subnets && var.enable_egress_only_igw ? cidrsubnet(aws_vpc.this.ipv6_cidr_block, 8, count.index) : null

  tags = {
    Name = "${var.vpc_name}-private-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.public_subnet_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = var.enable_private_subnets && var.enable_nat_gateway ? local.public_subnet_count : 0
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "this" {
  count         = var.enable_private_subnets && var.enable_nat_gateway ? local.public_subnet_count : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.vpc_name}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private_nat_gateway" {
  count  = var.enable_private_subnets && var.enable_nat_gateway ? local.private_subnet_count : 0
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this[count.index].id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt-natgw-${count.index + 1}"
  }
}

resource "aws_security_group" "nat_instance" {
  count       = var.enable_private_subnets && var.enable_nat_instance ? 1 : 0
  name        = "${var.vpc_name}-nat-instance"
  description = "Security group for NAT instances"
  vpc_id      = aws_vpc.this.id

  ingress {
    description = "Allow all traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.vpc_name}-nat-instance-sg"
  }
}

resource "aws_instance" "nat" {
  count                       = var.enable_private_subnets && var.enable_nat_instance ? local.public_subnet_count : 0
  ami                         = var.nat_instance_ami_id != "" ? var.nat_instance_ami_id : data.aws_ami.nat.id
  instance_type               = var.nat_instance_type
  subnet_id                   = aws_subnet.public[count.index].id
  vpc_security_group_ids      = [aws_security_group.nat_instance[0].id]
  source_dest_check           = false
  associate_public_ip_address = true

  tags = {
    Name = "${var.vpc_name}-nat-instance-${count.index + 1}"
  }
}

resource "aws_route_table" "private_nat_instance" {
  count  = var.enable_private_subnets && var.enable_nat_instance ? local.private_subnet_count : 0
  vpc_id = aws_vpc.this.id

  route {
    cidr_block           = "0.0.0.0/0"
    network_interface_id = aws_instance.nat[count.index].primary_network_interface_id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt-natinst-${count.index + 1}"
  }
}

resource "aws_egress_only_internet_gateway" "this" {
  count  = var.enable_private_subnets && var.enable_egress_only_igw ? 1 : 0
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-eigw"
  }
}

resource "aws_route_table" "private_eigw" {
  count  = var.enable_private_subnets && var.enable_egress_only_igw ? local.private_subnet_count : 0
  vpc_id = aws_vpc.this.id

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.this[0].id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt-eigw-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = var.enable_private_subnets && (var.enable_nat_gateway || var.enable_nat_instance || var.enable_egress_only_igw) ? local.private_subnet_count : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = local.private_route_table_ids[count.index]
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "default_security_group_id" {
  value = aws_default_security_group.default.id
}

output "tls_security_group_id" {
  value = aws_security_group.tls.id
}

###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Primary region (source buckets)
provider "aws" {
  region = var.primary_region
}

# Secondary region (replica / disaster-recovery buckets)
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment / workload name used as a prefix for every resource created by this template."
  type        = string
  default     = "benchmark"
}

variable "primary_region" {
  description = "AWS region in which the primary Terraform state bucket and the access-logs bucket are created."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "AWS region in which the replicated (disaster recovery) buckets are created."
  type        = string
  default     = "us-west-2"
}

variable "glacier_transition_days" {
  description = "Number of days after object creation before access-log objects transition to the GLACIER storage class."
  type        = number
  default     = 7
}

variable "log_expiration_days" {
  description = "Number of days, counted AFTER the Glacier transition, before access-log objects expire (default 30 => expire at day 37)."
  type        = number
  default     = 30
}

variable "force_destroy" {
  description = "Allow the buckets (and therefore every object version they contain) to be deleted when the stack is destroyed."
  type        = bool
  default     = true
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # Total object lifetime = Glacier transition + retention after transition.
  log_expiration_days = var.glacier_transition_days + var.log_expiration_days

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Component   = "multi-region-tfstate"
  }
}

###############################################################################
# KMS keys
###############################################################################

# Customer managed key used for server-side encryption of the primary state bucket.
resource "aws_kms_key" "state" {
  description             = "${var.environment} Terraform state bucket SSE-KMS key (${var.primary_region})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.tags
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.environment}-tfstate"
  target_key_id = aws_kms_key.state.key_id
}

# Dedicated customer managed key for the replica state bucket (own key + automatic rotation).
resource "aws_kms_key" "replica_state" {
  provider                = aws.replica
  description             = "${var.environment} replica Terraform state bucket SSE-KMS key (${var.replica_region})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.tags
}

resource "aws_kms_alias" "replica_state" {
  provider      = aws.replica
  name          = "alias/${var.environment}-tfstate-replica"
  target_key_id = aws_kms_key.replica_state.key_id
}

###############################################################################
# Buckets
###############################################################################

# Primary Terraform state bucket
resource "aws_s3_bucket" "state" {
  bucket_prefix = "${var.environment}-tfstate-"
  force_destroy = var.force_destroy

  tags = merge(local.tags, {
    Name = "${var.environment}-tfstate"
    Role = "terraform-state"
  })
}

# Primary access-logs bucket (target of the state bucket's server access logging)
resource "aws_s3_bucket" "logs" {
  bucket_prefix = "${var.environment}-tfstate-logs-"
  force_destroy = var.force_destroy

  tags = merge(local.tags, {
    Name = "${var.environment}-tfstate-logs"
    Role = "access-logs"
  })
}

# Replica Terraform state bucket (secondary region)
resource "aws_s3_bucket" "replica_state" {
  provider      = aws.replica
  bucket_prefix = "${var.environment}-tfstate-replica-"
  force_destroy = var.force_destroy

  tags = merge(local.tags, {
    Name = "${var.environment}-tfstate-replica"
    Role = "terraform-state-replica"
  })
}

# Replica access-logs bucket (secondary region)
resource "aws_s3_bucket" "replica_logs" {
  provider      = aws.replica
  bucket_prefix = "${var.environment}-tfstate-logs-replica-"
  force_destroy = var.force_destroy

  tags = merge(local.tags, {
    Name = "${var.environment}-tfstate-logs-replica"
    Role = "access-logs-replica"
  })
}

###############################################################################
# Versioning (required on both source and destination buckets for replication)
###############################################################################

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Public access blocks (all four buckets)
###############################################################################

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Object ownership + ACLs for the log-delivery buckets
###############################################################################

# ACLs must be re-enabled (ObjectWriter) so the log-delivery-write canned ACL can be applied.
resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    object_ownership = "ObjectWriter"
  }

  depends_on = [aws_s3_bucket_public_access_block.logs]
}

resource "aws_s3_bucket_acl" "logs" {
  bucket = aws_s3_bucket.logs.id
  acl    = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.logs]
}

resource "aws_s3_bucket_ownership_controls" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  rule {
    object_ownership = "ObjectWriter"
  }

  depends_on = [aws_s3_bucket_public_access_block.replica_logs]
}

resource "aws_s3_bucket_acl" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id
  acl      = "log-delivery-write"

  depends_on = [aws_s3_bucket_ownership_controls.replica_logs]
}

###############################################################################
# Server-side encryption
###############################################################################

# Primary state bucket: SSE-KMS with the primary customer managed key.
resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

# Replica state bucket: SSE-KMS with its own customer managed key.
resource "aws_s3_bucket_server_side_encryption_configuration" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

###############################################################################
# Server access logging for the state bucket
###############################################################################

resource "aws_s3_bucket_logging" "state" {
  bucket        = aws_s3_bucket.state.id
  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "access-logs/${aws_s3_bucket.state.id}/"

  depends_on = [
    aws_s3_bucket_acl.logs,
    aws_s3_bucket_policy.logs,
  ]
}

# Allows the S3 logging service principal to deliver access logs into the bucket.
resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogs"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.logs.arn}/access-logs/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.state.arn
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.logs]
}

###############################################################################
# Lifecycle rules for access-log objects (primary + replica)
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "${var.environment}-access-logs-glacier-then-expire"
    status = "Enabled"

    filter {}

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = local.log_expiration_days
    }
  }

  depends_on = [aws_s3_bucket_versioning.logs]
}

resource "aws_s3_bucket_lifecycle_configuration" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  rule {
    id     = "${var.environment}-access-logs-glacier-then-expire"
    status = "Enabled"

    filter {}

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = local.log_expiration_days
    }
  }

  depends_on = [aws_s3_bucket_versioning.replica_logs]
}

###############################################################################
# Bucket policies restricting the state buckets to the owning account
###############################################################################

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RestrictAllS3ActionsToOwningAccountWithBucketOwnerFullControl"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*",
        ]
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.state]
}

# The replica state bucket carries the same bucket policy.
resource "aws_s3_bucket_policy" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RestrictAllS3ActionsToOwningAccountWithBucketOwnerFullControl"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.replica_state.arn,
          "${aws_s3_bucket.replica_state.arn}/*",
        ]
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.replica_state]
}

###############################################################################
# IAM role & policy used by S3 replication
###############################################################################

resource "aws_iam_role" "replication" {
  name = "${var.environment}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_policy" "replication" {
  name        = "${var.environment}-s3-replication-policy"
  description = "Permissions for S3 cross-region replication of the Terraform state and access-log buckets."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketMetadataAccess"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetBucketLocation",
        ]
        Resource = [
          aws_s3_bucket.state.arn,
          aws_s3_bucket.logs.arn,
        ]
      },
      {
        Sid    = "SourceObjectReadAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectVersion",
          "s3:GetObjectLegalHold",
          "s3:GetObjectRetention",
        ]
        Resource = [
          "${aws_s3_bucket.state.arn}/*",
          "${aws_s3_bucket.logs.arn}/*",
        ]
      },
      {
        Sid    = "DestinationObjectWriteAccess"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = [
          "${aws_s3_bucket.replica_state.arn}/*",
          "${aws_s3_bucket.replica_logs.arn}/*",
        ]
      },
      {
        Sid    = "DecryptSourceObjects"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
        ]
        Resource = [aws_kms_key.state.arn]
      },
      {
        Sid    = "EncryptReplicaObjects"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = [aws_kms_key.replica_state.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# Cross-region replication - Terraform state bucket
###############################################################################

resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "${var.environment}-tfstate-crr"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_state.arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_state.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica_state,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Cross-region replication - access logs bucket
###############################################################################

resource "aws_s3_bucket_replication_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "${var.environment}-access-logs-crr"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica_logs.arn
      storage_class = "STANDARD"
      account       = local.account_id
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.logs,
    aws_s3_bucket_versioning.replica_logs,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "state_bucket_name" {
  description = "Name of the primary Terraform state bucket."
  value       = aws_s3_bucket.state.id
}

output "state_bucket_arn" {
  description = "ARN of the primary Terraform state bucket."
  value       = aws_s3_bucket.state.arn
}

output "logs_bucket_name" {
  description = "Name of the primary access-logs bucket."
  value       = aws_s3_bucket.logs.id
}

output "replica_state_bucket_name" {
  description = "Name of the replica Terraform state bucket."
  value       = aws_s3_bucket.replica_state.id
}

output "replica_logs_bucket_name" {
  description = "Name of the replica access-logs bucket."
  value       = aws_s3_bucket.replica_logs.id
}

output "state_kms_key_arn" {
  description = "ARN of the KMS key encrypting the primary state bucket."
  value       = aws_kms_key.state.arn
}

output "replica_state_kms_key_arn" {
  description = "ARN of the KMS key encrypting the replica state bucket."
  value       = aws_kms_key.replica_state.arn
}

output "replication_role_arn" {
  description = "ARN of the IAM role assumed by S3 for cross-region replication."
  value       = aws_iam_role.replication.arn
}

##############################################################################
# Terraform & Provider
##############################################################################

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

##############################################################################
# Variables
##############################################################################

variable "region" {
  description = "AWS region in which the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name of the VPC; used as the prefix for every child resource."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary CIDR block used when the module creates the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "map_public_ip_on_launch" {
  description = "Whether instances launched in the public subnets receive a public IP automatically."
  type        = bool
  default     = false
}

variable "public_subnets" {
  description = "Map of availability zone => CIDR block used for the public subnets."
  type        = map(string)
  default = {
    "us-east-1a" = "10.0.0.0/20"
    "us-east-1b" = "10.0.16.0/20"
  }
}

variable "private_subnets" {
  description = "Map of availability zone => CIDR block used for the private subnets."
  type        = map(string)
  default = {
    "us-east-1a" = "10.0.32.0/20"
    "us-east-1b" = "10.0.48.0/20"
  }
}

variable "database_subnets" {
  description = "Map of availability zone => CIDR block used for the database subnets."
  type        = map(string)
  default = {
    "us-east-1a" = "10.0.64.0/20"
    "us-east-1b" = "10.0.80.0/20"
  }
}

variable "existing_vpc_id" {
  description = "ID of an existing VPC to integrate with. When set, no VPC is created."
  type        = string
  default     = ""
}

variable "existing_public_subnet_ids" {
  description = "Map of availability zone => existing public subnet ID. When non-empty, no public subnets are created."
  type        = map(string)
  default     = {}
}

variable "existing_private_subnet_ids" {
  description = "Map of availability zone => existing private subnet ID. When non-empty, no private subnets are created."
  type        = map(string)
  default     = {}
}

variable "existing_database_subnet_ids" {
  description = "Map of availability zone => existing database subnet ID. When non-empty, no database subnets are created."
  type        = map(string)
  default     = {}
}

variable "existing_nat_id" {
  description = "ID of an existing NAT gateway. When set, no NAT gateway or Elastic IP is created."
  type        = string
  default     = ""
}

variable "existing_security_group_id" {
  description = "ID of an existing security group to attach to the interface endpoints. When set, no endpoint security group is created."
  type        = string
  default     = ""
}

variable "vpc_endpoint_services" {
  description = "AWS service short names for which interface VPC endpoints are created."
  type        = list(string)
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "s3",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling"
  ]
}

##############################################################################
# VPC (created or existing)
##############################################################################

resource "aws_vpc" "this" {
  count = var.existing_vpc_id == "" ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.name
  }
}

data "aws_vpc" "existing" {
  count = var.existing_vpc_id == "" ? 0 : 1

  id = var.existing_vpc_id
}

##############################################################################
# Internet Gateway (created or discovered)
##############################################################################

resource "aws_internet_gateway" "this" {
  count = var.existing_vpc_id == "" ? 1 : 0

  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-igw"
  }
}

# Only looked up when integrating with an existing VPC that already owns an IGW.
data "aws_internet_gateway" "existing" {
  count = var.existing_vpc_id == "" ? 0 : 1

  filter {
    name   = "attachment.vpc-id"
    values = [var.existing_vpc_id]
  }
}

##############################################################################
# Locals
##############################################################################

locals {
  create_vpc = var.existing_vpc_id == ""

  # VPC identity: use the created VPC when there is one, otherwise the supplied ID.
  vpc_id         = coalesce(one(aws_vpc.this[*].id), var.existing_vpc_id)
  vpc_cidr_block = coalesce(one(data.aws_vpc.existing[*].cidr_block), var.vpc_cidr)

  internet_gateway_id = coalesce(
    one(aws_internet_gateway.this[*].id),
    one(data.aws_internet_gateway.existing[*].id)
  )

  # Subnet inventory: pre-existing ID maps win over module-created subnets.
  public_subnet_ids = length(var.existing_public_subnet_ids) > 0 ? values(var.existing_public_subnet_ids) : aws_subnet.public[*].id
  private_subnet_ids = length(var.existing_private_subnet_ids) > 0 ? values(var.existing_private_subnet_ids) : aws_subnet.private[*].id
  database_subnet_ids = length(var.existing_database_subnet_ids) > 0 ? values(var.existing_database_subnet_ids) : aws_subnet.database[*].id

  # NAT gateway: supplied ID wins, otherwise the one created by the module.
  nat_gateway_id = coalesce(var.existing_nat_id, one(aws_nat_gateway.this[*].id))

  # Endpoint security group: supplied ID wins, otherwise the one created by the module.
  endpoint_security_group_id = coalesce(var.existing_security_group_id, one(aws_security_group.vpc_endpoints[*].id))

  database_subnet_group_name = lower(var.name)
}

##############################################################################
# Subnets
##############################################################################

resource "aws_subnet" "public" {
  for_each = length(var.existing_public_subnet_ids) == 0 ? var.public_subnets : {}

  vpc_id                  = local.vpc_id
  cidr_block              = each.value
  availability_zone       = each.key
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = {
    Name = "${var.name}-public-${each.key}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  for_each = length(var.existing_private_subnet_ids) == 0 ? var.private_subnets : {}

  vpc_id                  = local.vpc_id
  cidr_block              = each.value
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-private-${each.key}"
    Tier = "private"
  }
}

resource "aws_subnet" "database" {
  for_each = length(var.existing_database_subnet_ids) == 0 ? var.database_subnets : {}

  vpc_id                  = local.vpc_id
  cidr_block              = each.value
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-database-${each.key}"
    Tier = "database"
  }
}

##############################################################################
# RDS subnet group
##############################################################################

resource "aws_db_subnet_group" "this" {
  name       = local.database_subnet_group_name
  subnet_ids = local.database_subnet_ids

  tags = {
    Name = local.database_subnet_group_name
  }
}

##############################################################################
# NAT gateway (Elastic IP in the first public subnet)
##############################################################################

resource "aws_eip" "nat" {
  count = var.existing_nat_id == "" ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${var.name}-nat-eip"
  }
}

resource "aws_nat_gateway" "this" {
  count = var.existing_nat_id == "" ? 1 : 0

  allocation_id = one(aws_eip.nat[*].id)
  subnet_id     = local.public_subnet_ids[0]

  depends_on = [aws_internet_gateway.this]

  tags = {
    Name = "${var.name}-nat"
  }
}

##############################################################################
# Route tables and routes
##############################################################################

resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-public-rt"
  }
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = local.internet_gateway_id
}

resource "aws_route_table" "private" {
  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-private-rt"
  }
}

resource "aws_route" "private_nat_access" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = local.nat_gateway_id
}

resource "aws_route_table_association" "public" {
  count = length(local.public_subnet_ids)

  subnet_id      = local.public_subnet_ids[count.index]
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = length(local.private_subnet_ids)

  subnet_id      = local.private_subnet_ids[count.index]
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database" {
  count = length(local.database_subnet_ids)

  subnet_id      = local.database_subnet_ids[count.index]
  route_table_id = aws_route_table.private.id
}

##############################################################################
# Endpoint security group
##############################################################################

resource "aws_security_group" "vpc_endpoints" {
  count = var.existing_security_group_id == "" ? 1 : 0

  name        = "${var.name}-vpc-endpoints"
  description = "Allow HTTPS from the ${var.name} VPC to the interface VPC endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "HTTPS from inside the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr_block]
  }

  tags = {
    Name = "${var.name}-vpc-endpoints"
  }
}

##############################################################################
# Interface VPC endpoints
##############################################################################

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(var.vpc_endpoint_services)

  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.${var.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = [local.endpoint_security_group_id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-${replace(each.value, ".", "-")}-endpoint"
  }
}

##############################################################################
# Outputs
##############################################################################

output "vpc_id" {
  description = "ID of the VPC in use (created or existing)."
  value       = local.vpc_id
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC in use."
  value       = local.vpc_cidr_block
}

output "public_subnet_ids" {
  description = "IDs of the public subnets in use."
  value       = local.public_subnet_ids
}

output "private_subnet_ids" {
  description = "IDs of the private subnets in use."
  value       = local.private_subnet_ids
}

output "database_subnet_ids" {
  description = "IDs of the database subnets in use."
  value       = local.database_subnet_ids
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway used for public egress."
  value       = local.internet_gateway_id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway used for private egress."
  value       = local.nat_gateway_id
}

output "database_subnet_group_name" {
  description = "Name of the RDS database subnet group."
  value       = aws_db_subnet_group.this.name
}

output "vpc_endpoint_security_group_id" {
  description = "Security group backing the interface VPC endpoints."
  value       = local.endpoint_security_group_id
}

output "vpc_endpoint_ids" {
  description = "Map of service name => interface VPC endpoint ID."
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.id }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region to deploy the isolated SSM test environment into."
  type        = string
  default     = "us-east-1"
}

variable "app_shortcode" {
  description = "Short application code used as a prefix for IAM role and instance profile names."
  type        = string
  default     = "bmk"
}

variable "vpc_cidr" {
  description = "CIDR block for the isolated testing VPC."
  type        = string
  default     = "10.8.0.0/16"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the single private subnet."
  type        = string
  default     = "10.8.1.0/24"
}

variable "instance_type" {
  description = "Instance type for the SSM test instance."
  type        = string
  default     = "t3.small"
}

variable "root_volume_size" {
  description = "Size (GiB) of the encrypted root EBS volume."
  type        = number
  default     = 20
}

###############################################################################
# Data sources
###############################################################################

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

###############################################################################
# Networking - isolated VPC and single private subnet
###############################################################################

resource "aws_vpc" "test" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.app_shortcode}-ssm-test-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.test.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.app_shortcode}-ssm-test-private-subnet"
  }
}

###############################################################################
# Security Groups
###############################################################################

# Security group attached to all interface VPC endpoints.
# Inbound 443 from the VPC CIDR only, and no egress rules.
resource "aws_security_group" "endpoints" {
  name_prefix = "${var.app_shortcode}-ssm-test-endpoints-"
  description = "Allow HTTPS from the VPC CIDR to the SSM interface VPC endpoints"
  vpc_id      = aws_vpc.test.id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # No egress blocks are declared, so Terraform removes the default
  # allow-all egress rule and the group has no egress rules.

  tags = {
    Name = "${var.app_shortcode}-ssm-test-endpoint-sg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

# Security group attached to the test EC2 instance.
# Egress 443 to the VPC CIDR (endpoints) only, and no ingress rules.
resource "aws_security_group" "instance" {
  name_prefix = "${var.app_shortcode}-ssm-test-instance-"
  description = "Allow HTTPS egress to VPC endpoints only, no inbound access"
  vpc_id      = aws_vpc.test.id

  # No ingress blocks are declared, so the group has no ingress rules.

  egress {
    description = "HTTPS to interface VPC endpoints within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.app_shortcode}-ssm-test-instance-sg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Interface VPC Endpoints (private DNS enabled, auto accepted)
###############################################################################

locals {
  ssm_endpoints = {
    ssm         = "ssm"
    ec2messages = "ec2messages"
    ssmmessages = "ssmmessages"
    logs        = "logs"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = local.ssm_endpoints

  vpc_id              = aws_vpc.test.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true
  auto_accept         = true

  tags = {
    Name = "${var.app_shortcode}-ssm-test-${each.key}-endpoint"
  }
}

###############################################################################
# IAM Role / Instance Profile for the test instance
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "instance" {
  name_prefix        = "${var.app_shortcode}-ssm-test-"
  description        = "SSM Session Manager test instance role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name = "${var.app_shortcode}-ssm-test-role"
  }
}

# Required for Session Manager, SSM agent, SSM messages and EC2 messages.
resource "aws_iam_role_policy_attachment" "ssm_core" {
  role       = aws_iam_role.instance.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy_document" "instance_permissions" {
  statement {
    sid    = "CloudWatchLogsAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMSDataKeyGeneration"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "instance_inline" {
  name_prefix = "${var.app_shortcode}-ssm-test-"
  role        = aws_iam_role.instance.id
  policy      = data.aws_iam_policy_document.instance_permissions.json
}

resource "aws_iam_instance_profile" "instance" {
  name_prefix = "${var.app_shortcode}-ssm-test-"
  role        = aws_iam_role.instance.name

  tags = {
    Name = "${var.app_shortcode}-ssm-test-profile"
  }
}

###############################################################################
# Test EC2 instance (no internet access; talks to VPC endpoints only)
###############################################################################

resource "aws_instance" "test" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  iam_instance_profile        = aws_iam_instance_profile.instance.name
  associate_public_ip_address = false
  source_dest_check           = false

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required" # IMDSv2 required
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = var.root_volume_size
    encrypted             = true
    delete_on_termination = true
  }

  tags = {
    Name = "${var.app_shortcode}-ssm-test-instance"
  }

  depends_on = [aws_vpc_endpoint.interface]
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the isolated testing VPC."
  value       = aws_vpc.test.id
}

output "private_subnet_id" {
  description = "ID of the private subnet hosting the instance and endpoints."
  value       = aws_subnet.private.id
}

output "availability_zone" {
  description = "Availability zone used for the private subnet."
  value       = aws_subnet.private.availability_zone
}

output "vpc_endpoint_ids" {
  description = "Map of interface VPC endpoint IDs."
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.id }
}

output "instance_id" {
  description = "ID of the SSM test instance."
  value       = aws_instance.test.id
}

output "instance_private_ip" {
  description = "Private IP address of the SSM test instance."
  value       = aws_instance.test.private_ip
}

output "instance_role_name" {
  description = "Name of the IAM role attached to the test instance."
  value       = aws_iam_role.instance.name
}

output "instance_profile_name" {
  description = "Name of the IAM instance profile attached to the test instance."
  value       = aws_iam_instance_profile.instance.name
}

###############################################################################
# Terraform / Provider configuration
###############################################################################
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "Terraform"
    }
  }
}

###############################################################################
# Variables (all with defaults so the stack is deployable as-is)
###############################################################################
variable "aws_region" {
  description = "AWS region to deploy into."
  type        = string
  default     = "us-east-1"
}

variable "project" {
  description = "Project / name prefix applied to resources."
  type        = string
  default     = "crowdnews"
}

variable "environment" {
  description = "Environment name."
  type        = string
  default     = "dev"
}

variable "az_count" {
  description = "Number of Availability Zones to span."
  type        = number
  default     = 3
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the three public subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.0.0/20", "10.0.16.0/20", "10.0.32.0/20"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the three private subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.128.0/20", "10.0.144.0/20", "10.0.160.0/20"]
}

variable "namespace_name" {
  description = "Private Cloud Map DNS namespace name."
  type        = string
  default     = "private-fargate-crowdnews.hands-on.cloud.local"
}

variable "service_name" {
  description = "Cloud Map service name for the NGINX task."
  type        = string
  default     = "nginx"
}

variable "container_port" {
  description = "Port the NGINX container listens on."
  type        = number
  default     = 80
}

variable "image_tag" {
  description = "Tag used for the NGINX image inside the ECR repository."
  type        = string
  default     = "latest"
}

variable "container_image" {
  description = "Full container image URI. When empty, the NGINX image from the created ECR repository is used."
  type        = string
  default     = ""
}

variable "push_nginx_image" {
  description = "When true, a local-exec provisioner pulls the public NGINX image and pushes it to the created ECR repository (requires docker + aws CLI on the apply host)."
  type        = bool
  default     = true
}

variable "jumphost_private_ip" {
  description = "Static private IP for the jumphost ENI (must be inside the first public subnet)."
  type        = string
  default     = "10.0.0.10"
}

variable "jumphost_instance_type" {
  description = "Instance type for the SSM-managed jumphost."
  type        = string
  default     = "t3.micro"
}

variable "log_retention_days" {
  description = "Retention for the ECS CloudWatch log group."
  type        = number
  default     = 7
}

###############################################################################
# Data sources
###############################################################################
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

###############################################################################
# Locals
###############################################################################
locals {
  name_prefix = "${var.project}-${var.environment}"

  ecr_registry    = split("/", aws_ecr_repository.nginx.repository_url)[0]
  container_image = var.container_image != "" ? var.container_image : "${aws_ecr_repository.nginx.repository_url}:${var.image_tag}"

  interface_endpoints = {
    ecr_dkr        = "ecr.dkr"
    ecr_api        = "ecr.api"
    logs           = "logs"
    secretsmanager = "secretsmanager"
    ssm            = "ssm"
    kms            = "kms"
  }
}

###############################################################################
# VPC + subnets + gateways
###############################################################################
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = var.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_prefix}-public-${data.aws_availability_zones.available.names[count.index]}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  count = var.az_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-${data.aws_availability_zones.available.names[count.index]}"
    Tier = "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_eip" "nat" {
  count  = var.az_count
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "nat" {
  count = var.az_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

# ---------------------------------------------------------------------------
# Public routing
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = var.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Private routing (one NAT gateway per AZ)
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = var.az_count

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = var.az_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# VPC endpoints (keep AWS API traffic off the public internet)
###############################################################################
resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpce-sg"
  description = "Allow HTTPS from within the VPC to the interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound to VPC resources"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${local.name_prefix}-vpce-sg"
  }
}

# Gateway endpoint for S3 -> attached to the private route tables
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${local.name_prefix}-s3-gw-endpoint"
  }
}

# Interface endpoints for ECR (docker + api), CloudWatch Logs, Secrets Manager, SSM and KMS
resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${local.name_prefix}-${each.key}-endpoint"
  }
}

###############################################################################
# Cloud Map private DNS namespace
###############################################################################
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = var.namespace_name
  description = "Private DNS namespace for internal service discovery"
  vpc         = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-namespace"
  }
}

###############################################################################
# ECR repository / CloudWatch logs / ECS cluster
###############################################################################
resource "aws_ecr_repository" "nginx" {
  name                 = "${var.project}/nginx"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = {
    Name = "${local.name_prefix}-nginx-ecr"
  }
}

resource "aws_cloudwatch_log_group" "nginx" {
  name              = "/ecs/${var.project}-nginx"
  retention_in_days = var.log_retention_days

  tags = {
    Name = "${local.name_prefix}-nginx-logs"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${local.name_prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = {
    Name = "${local.name_prefix}-cluster"
  }
}

###############################################################################
# IAM - ECS task execution role (ECR pulls, logs, parameter access, KMS)
###############################################################################
resource "aws_iam_role" "ecs_execution" {
  name = "${local.name_prefix}-ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-ecs-execution-role"
  }
}

resource "aws_iam_role_policy" "ecs_execution" {
  name = "${local.name_prefix}-ecs-execution-policy"
  role = aws_iam_role.ecs_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ECRAuthorization"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECRPull"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = aws_ecr_repository.nginx.arn
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.nginx.arn}:*"
      },
      {
        Sid    = "ParameterAndSecretAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath",
          "secretsmanager:GetSecretValue"
        ]
        Resource = "*"
      },
      {
        Sid    = "KMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# IAM - ECS task role (service discovery, logs, parameters)
###############################################################################
resource "aws_iam_role" "ecs_task" {
  name = "${local.name_prefix}-ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-ecs-task-role"
  }
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "${local.name_prefix}-ecs-task-policy"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ServiceDiscovery"
        Effect = "Allow"
        Action = [
          "servicediscovery:RegisterInstance",
          "servicediscovery:DeregisterInstance",
          "servicediscovery:GetOperation",
          "servicediscovery:GetNamespace",
          "servicediscovery:GetService",
          "servicediscovery:DiscoverInstances",
          "servicediscovery:ListInstances"
        ]
        Resource = "*"
      },
      {
        Sid    = "ParameterAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = "*"
      },
      {
        Sid    = "Logging"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.nginx.arn}:*"
      }
    ]
  })
}

###############################################################################
# Security group for the NGINX tasks
###############################################################################
resource "aws_security_group" "ecs_tasks" {
  name        = "${local.name_prefix}-nginx-task-sg"
  description = "Allow NGINX traffic from inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NGINX from the VPC CIDR"
    from_port   = var.container_port
    to_port     = var.container_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound (ECR/Logs/SSM via endpoints or NAT)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-nginx-task-sg"
  }
}

###############################################################################
# ECS task definition (Fargate, 512 CPU / 1024 memory, awsvpc, port 80)
###############################################################################
resource "aws_ecs_task_definition" "nginx" {
  family                   = "${local.name_prefix}-nginx"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = local.container_image
      essential = true

      portMappings = [
        {
          name          = "nginx-http"
          containerPort = var.container_port
          hostPort      = var.container_port
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.main.id
        },
        {
          name  = "SERVICE_DISCOVERY_DNS_NAME"
          value = "${var.service_name}.${var.namespace_name}"
        },
        {
          name  = "AWS_REGION"
          value = var.aws_region
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.nginx.name
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "nginx"
        }
      }
    }
  ])

  tags = {
    Name = "${local.name_prefix}-nginx-task"
  }
}

###############################################################################
# Cloud Map service for NGINX (MULTIVALUE A + SRV, TTL 10)
###############################################################################
resource "aws_service_discovery_service" "nginx" {
  name = var.service_name
  type = "DNS_HTTP"

  namespace_id = aws_service_discovery_private_dns_namespace.main.id

  dns_config {
    namespace_id   = aws_service_discovery_private_dns_namespace.main.id
    routing_policy = "MULTIVALUE"

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }
  }

  health_check_custom_config {
    failure_threshold = 1
  }

  tags = {
    Name = "${local.name_prefix}-nginx-sd-service"
  }
}

###############################################################################
# Optional: build/push the NGINX image into the immutable ECR repository
###############################################################################
resource "null_resource" "push_nginx_image" {
  count = var.push_nginx_image ? 1 : 0

  triggers = {
    repository_url = aws_ecr_repository.nginx.repository_url
    image          = local.container_image
    registry       = local.ecr_registry
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = <<-EOT
      set -euo pipefail
      aws ecr get-login-password --region ${var.aws_region} \
        | docker login --username AWS --password-stdin ${local.ecr_registry}
      docker pull nginx:latest
      docker tag nginx:latest ${local.container_image}
      docker push ${local.container_image}
    EOT
  }

  depends_on = [aws_ecr_repository.nginx]
}

###############################################################################
# ECS Fargate service (private subnets, 1 task, registered in Cloud Map)
###############################################################################
resource "aws_ecs_service" "nginx" {
  name            = "${local.name_prefix}-nginx"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"
  platform_version = "LATEST"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.nginx.arn
    container_name = "nginx"
    container_port = var.container_port
  }

  depends_on = [
    aws_iam_role_policy.ecs_execution,
    aws_iam_role_policy.ecs_task,
    aws_service_discovery_service.nginx,
    null_resource.push_nginx_image,
  ]

  tags = {
    Name = "${local.name_prefix}-nginx-service"
  }
}

###############################################################################
# SSM-managed jumphost (t3.micro, Amazon Linux 2, static ENI in public subnet 1)
###############################################################################
resource "aws_security_group" "jumphost" {
  name        = "${local.name_prefix}-jumphost-sg"
  description = "Allow all inbound traffic from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All protocols from the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-jumphost-sg"
  }
}

resource "aws_iam_role" "jumphost" {
  name = "${local.name_prefix}-jumphost-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-jumphost-role"
  }
}

resource "aws_iam_role_policy_attachment" "jumphost_ssm" {
  role       = aws_iam_role.jumphost.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "${local.name_prefix}-jumphost-profile"
  role = aws_iam_role.jumphost.name
}

resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = [var.jumphost_private_ip]
  security_groups = [aws_security_group.jumphost.id]
  description     = "Static primary ENI for the SSM-managed jumphost"

  tags = {
    Name = "${local.name_prefix}-jumphost-eni"
  }
}

resource "aws_instance" "jumphost" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = var.jumphost_instance_type
  iam_instance_profile = aws_iam_instance_profile.jumphost.name

  network_interface {
    network_interface_id = aws_network_interface.jumphost.id
    device_index         = 0
  }

  tags = {
    Name = "${local.name_prefix}-jumphost"
    Role = "ssm-jumphost"
  }

  depends_on = [aws_iam_role_policy_attachment.jumphost_ssm]
}

###############################################################################
# Outputs
###############################################################################
output "vpc_id" {
  description = "VPC ID."
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "Private subnet IDs hosting the Fargate service."
  value       = aws_subnet.private[*].id
}

output "public_subnet_ids" {
  description = "Public subnet IDs."
  value       = aws_subnet.public[*].id
}

output "ecr_repository_url" {
  description = "ECR repository URL holding the NGINX image."
  value       = aws_ecr_repository.nginx.repository_url
}

output "ecs_cluster_name" {
  description = "ECS cluster name."
  value       = aws_ecs_cluster.main.name
}

output "ecs_service_name" {
  description = "ECS Fargate service name."
  value       = aws_ecs_service.nginx.name
}

output "cloud_map_namespace" {
  description = "Cloud Map private DNS namespace."
  value       = aws_service_discovery_private_dns_namespace.main.name
}

output "nginx_service_discovery_dns_name" {
  description = "Private service discovery DNS name of the NGINX service."
  value       = "${aws_service_discovery_service.nginx.name}.${aws_service_discovery_private_dns_namespace.main.name}"
}

output "jumphost_instance_id" {
  description = "SSM-managed jumphost instance ID (connect with: aws ssm start-session --target <id>)."
  value       = aws_instance.jumphost.id
}

output "jumphost_private_ip" {
  description = "Static private IP of the jumphost."
  value       = var.jumphost_private_ip
}

output "curl_command" {
  description = "Exact curl command (run from the SSM-managed jumphost) to reach NGINX via private service discovery."
  value       = "curl -v http://${aws_service_discovery_service.nginx.name}.${aws_service_discovery_private_dns_namespace.main.name}:${var.container_port}"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

########################################
# Variables
########################################

variable "project" {
  description = "Project name used in the naming convention."
  type        = string
  default     = "benchmark"
}

variable "app" {
  description = "Application name used in the naming convention."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment name used in the naming convention."
  type        = string
  default     = "dev"
}

variable "availability_zone" {
  description = "Availability zone used for the subnet and naming convention."
  type        = string
  default     = "us-east-1a"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t3.micro"
}

variable "root_volume_size" {
  description = "Size of the encrypted root volume in GB."
  type        = number
  default     = 20
}

variable "create_ssh_key" {
  description = "Whether to create and attach an SSH key pair to the EC2 instance."
  type        = bool
  default     = false
}

variable "ssh_public_key" {
  description = "The public key (OpenSSH format) to register when create_ssh_key is true."
  type        = string
  default     = ""
}

variable "create_eip" {
  description = "Whether to allocate and associate a static Elastic IP with the ENI."
  type        = bool
  default     = false
}

variable "attach_ssm_managed_policy" {
  description = "Whether to attach the AmazonSSMManagedInstanceCore AWS managed policy to the role."
  type        = bool
  default     = true
}

variable "allow_ssh_cidr" {
  description = "CIDR allowed to reach the instance over SSH when create_ssh_key is true."
  type        = string
  default     = "0.0.0.0/0"
}

variable "custom_routes" {
  description = "Optional map of extra routes to add to the public route table. Key = destination CIDR, value.gateway_id = target gateway."
  type = map(object({
    gateway_id = string
  }))
  default = {}
}

########################################
# Data sources
########################################

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

########################################
# Locals
########################################

locals {
  name_prefix = "${var.project}-${var.app}-${var.environment}-${var.availability_zone}"

  common_tags = {
    Project     = var.project
    Application = var.app
    Environment = var.environment
    AZ          = var.availability_zone
    ManagedBy   = "Terraform"
  }
}

########################################
# Networking
########################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = var.availability_zone
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rtb-public"
  })
}

resource "aws_route" "default_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "custom" {
  for_each = var.custom_routes

  route_table_id         = aws_route_table.public.id
  destination_cidr_block = each.key
  gateway_id             = each.value.gateway_id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

########################################
# Security group
########################################

resource "aws_security_group" "main" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for ${local.name_prefix}"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_security_group_rule" "ssh_ingress" {
  count             = var.create_ssh_key ? 1 : 0
  type              = "ingress"
  description       = "Optional SSH ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [var.allow_ssh_cidr]
  security_group_id = aws_security_group.main.id
}

########################################
# SSH key pair (optional)
########################################

resource "aws_key_pair" "main" {
  count      = var.create_ssh_key ? 1 : 0
  key_name   = "${local.name_prefix}-key"
  public_key = var.ssh_public_key

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-key"
  })
}

########################################
# IAM
########################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEc2AndSsmToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [
        "ec2.amazonaws.com",
        "ssm.amazonaws.com",
      ]
    }
  }
}

resource "aws_iam_role" "main" {
  name               = "${local.name_prefix}-role"
  description        = "Role for ${local.name_prefix} allowing EC2 and SSM to assume it."
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-role"
  })
}

data "aws_iam_policy_document" "ssm_session_manager" {
  statement {
    sid    = "SsmSessionManagerChannels"
    effect = "Allow"

    actions = [
      "ssmmessages:CreateControlChannel",
      "ssmmessages:CreateDataChannel",
      "ssmmessages:OpenControlChannel",
      "ssmmessages:OpenDataChannel",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-session-manager"
  description = "Dedicated SSM Session Manager control and data channel policy for ${local.name_prefix}."
  policy      = data.aws_iam_policy_document.ssm_session_manager.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-session-manager"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.main.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

resource "aws_iam_role_policy_attachment" "ssm_managed_core" {
  count      = var.attach_ssm_managed_policy ? 1 : 0
  role       = aws_iam_role.main.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "main" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.main.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-profile"
  })
}

########################################
# Network interface (no auto public IP)
########################################

resource "aws_network_interface" "main" {
  subnet_id       = aws_subnet.public.id
  security_groups = [aws_security_group.main.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eni"
  })
}

########################################
# Elastic IP (optional)
########################################

resource "aws_eip" "main" {
  count  = var.create_eip ? 1 : 0
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eip"
  })
}

resource "aws_eip_association" "main" {
  count                = var.create_eip ? 1 : 0
  allocation_id        = aws_eip.main[0].id
  network_interface_id = aws_network_interface.main.id
}

########################################
# EC2 instance
########################################

resource "aws_instance" "main" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = var.instance_type
  iam_instance_profile = aws_iam_instance_profile.main.name
  key_name             = var.create_ssh_key ? aws_key_pair.main[0].key_name : null

  network_interface {
    network_interface_id = aws_network_interface.main.id
    device_index         = 0
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  root_block_device {
    volume_size           = var.root_volume_size
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true

    tags = merge(local.common_tags, {
      Name = "${local.name_prefix}-root-volume"
    })
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2"
  })
}

########################################
# Outputs
########################################

output "ec2_instance_id" {
  description = "ID of the EC2 instance."
  value       = aws_instance.main.id
}

output "ec2_instance_arn" {
  description = "ARN of the EC2 instance."
  value       = aws_instance.main.arn
}

output "iam_role_arn" {
  description = "ARN of the IAM role attached to the instance profile."
  value       = aws_iam_role.main.arn
}

output "instance_profile_arn" {
  description = "ARN of the IAM instance profile."
  value       = aws_iam_instance_profile.main.arn
}

output "route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "network_interface_id" {
  description = "ID of the ENI attached to the instance."
  value       = aws_network_interface.main.id
}

output "elastic_ip" {
  description = "Public Elastic IP address when create_eip is true, otherwise null."
  value       = var.create_eip ? aws_eip.main[0].public_ip : null
}

# Terraform Plan: EKS Cluster "demo-eks" with CloudFormation‑Managed Node Group

I'll build a modular yet single‑file configuration that:

1. **Provider & Networking** – An AWS provider with a `default_tags` block that stamps `kubernetes.io/cluster/demo-eks=owned` on every resource. A 10.0.0.0/16 VPC (DNS + hostnames) with an IGW, one public subnet (hosts the NAT gateway + EIP), a public & private route table, and three private subnets – one per AZ – all egressing through the NAT gateway.
2. **Control Plane** – A customer‑managed KMS key for secrets encryption, an `eksClusterRole` carrying `AmazonEKSClusterPolicy` + `AmazonEKSVPCResourceController` plus an inline KMS policy, and a private‑only EKS cluster (`endpoint_public_access=false`) placed in the three private subnets.
3. **Worker Nodes** – A 4096‑bit RSA `tls_private_key`, written to `~/.ssh/eks-aws.pem` and registered as key pair `eks_kp`. A dedicated node security group with self‑ingress, VPC‑only egress, and bidirectional port 443 / 1025‑65535 rules tied to the cluster SG. IAM role `eks-demo-node` (WorkerNode, CNI, ECR‑ReadOnly, SSM core) attached to an instance profile.
4. **Launch Template & ASG** – A `t3.medium` launch template (30 GB gp2, IMDSv2 required w/ hop limit 2, SSM‑looked‑up EKS AMI, base64 user‑data running `bootstrap.sh` and `cfn-signal`). A 30‑second `time_sleep` lets the LT settle, then a CloudFormation stack `eks-cluster-stack` provisions the ASG (min 1 / desired 3 / max 4) across the private subnets with a rolling‑update policy (batch 1, min in service 3, 5‑min pause) and outputs the role ARN, node SG, and ASG ID.

```iac_template
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.11"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/1.28/amazon-linux-2/recommended/image_id"
}

# ---------------------------------------------------------------------------
# Networking: VPC, Subnets, IGW, NAT, Route Tables
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "demo-eks-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "demo-eks-igw"
  }
}

# Public subnet (hosts the NAT gateway)
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "demo-eks-public"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "demo-eks-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "demo-eks-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "demo-eks-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Three private subnets, one per AZ
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index + 1}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "demo-eks-private-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "demo-eks-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# KMS key for EKS secrets encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "eks" {
  description             = "KMS Key for demo-eks secret encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "demo-eks-kms"
  }
}

resource "aws_kms_alias" "eks" {
  name          = "alias/demo-eks"
  target_key_id = aws_kms_key.eks.key_id
}

# ---------------------------------------------------------------------------
# EKS Control Plane IAM Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = {
        Service = "eks.amazonaws.com"
      },
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "eks_kms" {
  name = "eks-kms-policy"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Action = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:CreateGrant",
        "kms:ListGrants",
        "kms:RevokeGrant"
      ],
      Resource = aws_kms_key.eks.arn
    }]
  })
}

# ---------------------------------------------------------------------------
# EKS Cluster (private-only API endpoint)
# ---------------------------------------------------------------------------
resource "aws_eks_cluster" "demo" {
  name     = "demo-eks"
  role_arn = aws_iam_role.eks_cluster.arn
  version  = "1.28"

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_kms
  ]
}

# ---------------------------------------------------------------------------
# SSH Key Pair for worker nodes
# ---------------------------------------------------------------------------
resource "tls_private_key" "node" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "private_key" {
  content         = tls_private_key.node.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.node.public_key_openssh
}

# ---------------------------------------------------------------------------
# Node Security Group
# ---------------------------------------------------------------------------
resource "aws_security_group" "node" {
  name        = "demo-eks-node-sg"
  description = "Security group for demo-eks worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "demo-eks-node-sg"
  }
}

# Unrestricted internal communication between nodes
resource "aws_security_group_rule" "node_ingress_self" {
  type              = "ingress"
  description       = "Allow nodes to communicate with each other"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.node.id
}

# Ingress: HTTPS from control plane SG
resource "aws_security_group_rule" "node_ingress_cluster_443" {
  type                     = "ingress"
  description              = "Allow control plane to reach kubelet/kube-proxy over 443"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
}

# Ingress: high ports from control plane SG
resource "aws_security_group_rule" "node_ingress_cluster_high" {
  type                     = "ingress"
  description              = "Allow control plane to reach node ports 1025-65535"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
}

# Egress: only within the VPC CIDR
resource "aws_security_group_rule" "node_egress_vpc" {
  type              = "egress"
  description       = "Allow outbound traffic within the VPC CIDR only"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.node.id
}

# Egress: HTTPS to control plane SG
resource "aws_security_group_rule" "node_egress_cluster_443" {
  type                     = "egress"
  description              = "Allow nodes to reach control plane over 443"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
}

# Egress: high ports to control plane SG
resource "aws_security_group_rule" "node_egress_cluster_high" {
  type                     = "egress"
  description              = "Allow nodes to reach control plane ports 1025-65535"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  security_group_id        = aws_security_group.node.id
}

# ---------------------------------------------------------------------------
# Node IAM Role / Instance Profile
# ---------------------------------------------------------------------------
resource "aws_iam_role" "node" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = {
        Service = "ec2.amazonaws.com"
      },
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "node" {
  name = "eks-demo-node"
  role = aws_iam_role.node.name
}

# ---------------------------------------------------------------------------
# Launch Template
# ---------------------------------------------------------------------------
resource "aws_launch_template" "node" {
  name_prefix   = "demo-eks-node-"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks.key_name

  iam_instance_profile {
    name = aws_iam_instance_profile.node.name
  }

  network_interfaces {
    security_groups = [aws_security_group.node.id]
  }

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -o xtrace
    /etc/eks/bootstrap.sh demo-eks
    /opt/aws/bin/cfn-signal --exit-code $? \
      --stack eks-cluster-stack \
      --resource NodeGroup \
      --region us-east-1
  EOT
  )

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name                             = "demo-eks-node"
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }

  tag_specifications {
    resource_type = "volume"

    tags = {
      Name = "demo-eks-node-volume"
    }
  }

  tags = {
    Name = "demo-eks-node-lt"
  }
}

# ---------------------------------------------------------------------------
# 30-second settling delay before creating the CloudFormation stack
# ---------------------------------------------------------------------------
resource "time_sleep" "wait_for_launch_template" {
  create_duration = "30s"

  depends_on = [aws_launch_template.node]
}

# ---------------------------------------------------------------------------
# CloudFormation stack that owns the Auto Scaling Group
# ---------------------------------------------------------------------------
resource "aws_cloudformation_stack" "eks_node_group" {
  name          = "eks-cluster-stack"
  on_failure    = "ROLLBACK"
  capabilities  = []

  parameters = {
    ClusterName           = aws_eks_cluster.demo.name
    LaunchTemplateId      = aws_launch_template.node.id
    LaunchTemplateVersion = aws_launch_template.node.latest_version
    Subnets               = join(",", aws_subnet.private[*].id)
    MinSize               = "1"
    DesiredCapacity       = "3"
    MaxSize               = "4"
    NodeInstanceRoleArn   = aws_iam_role.node.arn
    NodeSecurityGroupId   = aws_security_group.node.id
  }

  template_body = <<-CFT
    AWSTemplateFormatVersion: "2010-09-09"
    Description: EKS demo-eks worker node group managed by CloudFormation

    Parameters:
      ClusterName:
        Type: String
      LaunchTemplateId:
        Type: String
      LaunchTemplateVersion:
        Type: String
      Subnets:
        Type: CommaDelimitedList
      MinSize:
        Type: String
        Default: "1"
      DesiredCapacity:
        Type: String
        Default: "3"
      MaxSize:
        Type: String
        Default: "4"
      NodeInstanceRoleArn:
        Type: String
      NodeSecurityGroupId:
        Type: String

    Resources:
      NodeGroup:
        Type: AWS::AutoScaling::AutoScalingGroup
        Properties:
          AutoScalingGroupName: !Sub "$${ClusterName}-nodes"
          DesiredCapacity: !Ref DesiredCapacity
          MinSize: !Ref MinSize
          MaxSize: !Ref MaxSize
          LaunchTemplate:
            LaunchTemplateId: !Ref LaunchTemplateId
            Version: !Ref LaunchTemplateVersion
          VPCZoneIdentifier: !Ref Subnets
          Tags:
            - Key: Name
              Value: !Sub "$${ClusterName}-node"
              PropagateAtLaunch: true
            - Key: kubernetes.io/cluster/demo-eks
              Value: owned
              PropagateAtLaunch: true
        UpdatePolicy:
          AutoScalingRollingUpdate:
            MaxBatchSize: 1
            MinInstancesInService: 3
            PauseTime: PT5M
        CreationPolicy:
          ResourceSignal:
            Count: 3
            Timeout: PT15M

    Outputs:
      NodeInstanceRoleArn:
        Description: ARN of the worker node IAM role
        Value: !Ref NodeInstanceRoleArn
      NodeSecurityGroupId:
        Description: ID of the worker node security group
        Value: !Ref NodeSecurityGroupId
      AutoScalingGroupId:
        Description: ID of the newly created Auto Scaling Group
        Value: !Ref NodeGroup
  CFT

  depends_on = [time_sleep.wait_for_launch_template]
}

# ---------------------------------------------------------------------------
# Outputs (returned directly by the CloudFormation stack)
# ---------------------------------------------------------------------------
output "node_instance_role_arn" {
  description = "Worker node IAM role ARN (from CFN stack output)"
  value       = aws_cloudformation_stack.eks_node_group.outputs["NodeInstanceRoleArn"]
}

output "node_security_group_id" {
  description = "Worker node security group ID (from CFN stack output)"
  value       = aws_cloudformation_stack.eks_node_group.outputs["NodeSecurityGroupId"]
}

output "autoscaling_group_id" {
  description = "Auto Scaling Group ID (from CFN stack output)"
  value       = aws_cloudformation_stack.eks_node_group.outputs["AutoScalingGroupId"]
}

output "eks_cluster_endpoint" {
  description = "Private EKS API server endpoint"
  value       = aws_eks_cluster.demo.endpoint
}

output "eks_cluster_certificate_authority" {
  description = "EKS cluster certificate authority data"
  value       = aws_eks_cluster.demo.certificate_authority[0].data
  sensitive   = true
}
```

## Terraform Program Description

This configuration provisions a **secure, cross-region Terraform remote-state platform for multiple EKS stacks**, bootstrapped with local state (it creates the backend it will later consume).

**What gets created:**

1. **Primary state bucket (us-east-1)** – name derived from the AWS account ID (`tfstate-<account-id>-primary`), with versioning enabled, all four public-access blocks enabled, `BucketOwnerEnforced` ownership, default SSE-KMS encryption via a **new customer-managed KMS key** (7-day deletion window, automatic rotation), and a bucket policy that **denies every request made over a non-TLS transport** (`aws:SecureTransport = false`).
2. **Replica state bucket (us-west-2)** – identical hardening (versioning, public-access blocks, SSL-only deny policy, ownership controls) encrypted with its **own dedicated replica KMS key**.
3. **Cross-region replication** – a replication rule on the primary bucket (prefix `eks-stacks/`, delete-marker replication, SSE-KMS source selection criteria) targeting the replica bucket using the replica CMK, driven by a dedicated **IAM service role for `s3.amazonaws.com`** whose policy grants exactly: list/read on the source bucket, object version/ACL/tag reads, `kms:Decrypt` on the primary key (scoped `kms:ViaService = s3.<primary-region>`), `kms:Encrypt` on the replica key (scoped to `s3.<replica-region>`), and replicate/write on the destination.
4. **Per-stack state locking** – the supplied `eks_stacks` map (stack name ⇒ region) is partitioned per region and iterated with `for_each` to create one **PAY_PER_REQUEST DynamoDB table keyed by `LockID`** per stack, in that stack's region (providers aliased for `us-east-1`, `us-west-2`, `eu-west-1`).
5. **Per-stack IAM** – one dedicated IAM policy per stack (bucket list restricted to that stack's `s3:prefix`, read/write on that stack's object prefix, `dynamodb:*Item` on its own lock table ARN, and KMS encrypt/decrypt on the state CMK), plus a **per-stack IAM role** (assumable by the account root and any principals you declare in `trusted_principal_arns`) to which that policy is attached.
6. **Generated backends** – a `local_file` resource writes a ready-to-use `terraform { backend "s3" { … } }` file to `eks-stacks/<stack>/backend.tf` for each stack, referencing the primary bucket, KMS key, region and that stack's lock table. All taggable resources carry a standardized state-management tag set (`ManagedBy`, `Component`, `Purpose`, `DataClass` plus user tags).

**Key edges handled:** KMS key policies delegate to the account root so the replication role's IAM policy is authorized without creating a key↔role dependency cycle; replication config explicitly depends on both buckets' versioning and the role policy; the replication filter uses the state prefix to avoid empty-filter API rejections; and the stack map is validated against the regions that have provider aliases.

```hcl
###############################################################################
# Terraform Remote State Management platform for multiple EKS stacks
#
# Creates:
#   * Primary S3 state bucket (us-east-1) + CMK + SSL-only bucket policy
#   * Replica S3 state bucket (us-west-2) + CMK + SSL-only bucket policy
#   * S3 cross-region replication with a least-privilege IAM role
#   * Per-stack DynamoDB lock tables (LockID) in each stack's region
#   * Per-stack IAM policies (bucket prefix + lock table + KMS) and roles
#   * Generated local `eks-stacks/<stack>/backend.tf` files
#
# NOTE: this bootstrap configuration intentionally uses LOCAL state; you cannot
# use a backend that does not exist yet. After the first apply, you may migrate
# this configuration onto the bucket it just created.
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

###############################################################################
# Providers
###############################################################################

# Default provider == primary state region (us-east-1)
provider "aws" {
  region = var.primary_region
}

# Disaster-recovery / replica state region
provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# Additional region used for regional lock tables (and their stack policies)
provider "aws" {
  alias  = "tertiary"
  region = var.tertiary_region
}

###############################################################################
# Variables
###############################################################################

variable "primary_region" {
  description = "AWS region that hosts the primary Terraform state bucket."
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "AWS region that hosts the cross-region replica state bucket."
  type        = string
  default     = "us-west-2"
}

variable "tertiary_region" {
  description = "Third region made available for per-stack state-lock tables."
  type        = string
  default     = "eu-west-1"
}

variable "eks_stacks" {
  description = "Map of EKS stack name => region. A DynamoDB lock table, an IAM policy/role and a backend.tf file are generated for every entry."
  type        = map(string)
  default = {
    "eks-platform-dev"  = "us-east-1"
    "eks-platform-prod" = "us-east-1"
    "eks-data-dev"      = "us-west-2"
    "eks-data-prod"     = "eu-west-1"
  }

  validation {
    condition = alltrue([
      for region in values(var.eks_stacks) :
      contains(["us-east-1", "us-west-2", "eu-west-1"], region)
    ])
    error_message = "Every stack region must have a matching provider alias in this configuration (us-east-1, us-west-2 or eu-west-1). Declare a new provider alias before adding a new region."
  }
}

variable "state_prefix" {
  description = "Key prefix / namespace inside the state buckets that holds all EKS stack state (also the replication filter prefix)."
  type        = string
  default     = "eks-stacks"
}

variable "trusted_principal_arns" {
  description = "Additional IAM principals (e.g. CI/CD roles) allowed to assume the per-stack state access roles. The account root is always allowed."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Extra tags merged into the standardized state-management tag set."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # Bucket names are derived dynamically from the AWS account ID so that they
  # stay globally unique and reproducible.
  primary_bucket_name = "tfstate-${local.account_id}-primary"
  replica_bucket_name = "tfstate-${local.account_id}-replica"

  # Terraform requires provider configuration to be statically resolvable, so
  # the stack map is split per region and each slice is used with for_each
  # against the matching provider alias.
  stacks_primary  = { for name, region in var.eks_stacks : name => region if region == var.primary_region }
  stacks_replica  = { for name, region in var.eks_stacks : name => region if region == var.replica_region }
  stacks_tertiary = { for name, region in var.eks_stacks : name => region if region == var.tertiary_region }

  # Deterministic lock-table name for every stack.
  lock_table_name = { for name in keys(var.eks_stacks) : name => "${name}-tfstate-lock" }

  # Standardized state-management label set applied to every taggable resource.
  tags = merge(
    {
      ManagedBy = "Terraform"
      Component = "terraform-remote-state"
      Purpose   = "eks-state-management"
      DataClass = "state-and-lock"
    },
    var.tags,
  )
}

###############################################################################
# Primary KMS key (us-east-1) - encrypts all state objects by default
###############################################################################

data "aws_iam_policy_document" "primary_kms" {
  statement {
    sid       = "EnableAccountRootFullControl"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  # Allows any principal in the account that is already authorized through IAM
  # (the replication role, stack roles, ...) to use the key through S3.
  statement {
    sid    = "AllowStateCryptoViaS3"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.primary_region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "primary" {
  description             = "CMK for the primary Terraform remote state bucket (${local.primary_bucket_name})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.primary_kms.json

  tags = merge(local.tags, {
    Name  = "tfstate-primary-cmk"
    Role  = "primary"
    Stack = "shared"
  })
}

resource "aws_kms_alias" "primary" {
  name          = "alias/tfstate-primary-${local.account_id}"
  target_key_id = aws_kms_key.primary.key_id
}

###############################################################################
# Replica KMS key (us-west-2) - encrypts replicated state objects
###############################################################################

data "aws_iam_policy_document" "replica_kms" {
  statement {
    sid       = "EnableAccountRootFullControl"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowReplicaCryptoViaS3"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.replica_region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "replica" {
  provider = aws.replica

  description             = "CMK for the replica Terraform remote state bucket (${local.replica_bucket_name})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.replica_kms.json

  tags = merge(local.tags, {
    Name  = "tfstate-replica-cmk"
    Role  = "replica"
    Stack = "shared"
  })
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name          = "alias/tfstate-replica-${local.account_id}"
  target_key_id = aws_kms_key.replica.key_id
}

###############################################################################
# Primary state bucket (us-east-1)
###############################################################################

resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name

  tags = merge(local.tags, {
    Name  = local.primary_bucket_name
    Role  = "primary"
    Stack = "shared"
  })
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "primary_bucket" {
  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.primary_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.primary]
}

###############################################################################
# Replica state bucket (us-west-2)
###############################################################################

resource "aws_s3_bucket" "replica" {
  provider = aws.replica

  bucket = local.replica_bucket_name

  tags = merge(local.tags, {
    Name  = local.replica_bucket_name
    Role  = "replica"
    Stack = "shared"
  })
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "replica_bucket" {
  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id
  policy = data.aws_iam_policy_document.replica_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

###############################################################################
# Cross-region replication role + policy
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "tfstate-cross-region-replication-${local.account_id}"
  description        = "Role assumed by S3 to replicate Terraform state objects from ${local.primary_bucket_name} to ${local.replica_bucket_name}"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = merge(local.tags, {
    Name  = "tfstate-cross-region-replication"
    Role  = "replication"
    Stack = "shared"
  })
}

data "aws_iam_policy_document" "replication" {
  # --- Read the replication configuration and the source bucket -------------
  statement {
    sid    = "SourceBucketRead"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
    ]
    resources = [aws_s3_bucket.primary.arn]
  }

  # --- Read source object versions, ACLs and tags ---------------------------
  statement {
    sid    = "SourceObjectRead"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectVersion",
    ]
    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  # --- Write replicated versions into the destination bucket ----------------
  statement {
    sid    = "DestinationObjectWrite"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]
    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  # --- Decrypt source objects with the primary CMK --------------------------
  statement {
    sid    = "DecryptSourceObjects"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.primary.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.primary_region}.amazonaws.com"]
    }
  }

  # --- Encrypt replicated objects with the replica CMK ----------------------
  statement {
    sid    = "EncryptReplicatedObjects"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.replica.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.replica_region}.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "replication" {
  name   = "tfstate-cross-region-replication-policy"
  role   = aws_iam_role.replication.id
  policy = data.aws_iam_policy_document.replication.json
}

###############################################################################
# Replication configuration on the primary bucket
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy.replication,
  ]

  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.primary.id

  rule {
    id     = "replicate-eks-state"
    status = "Enabled"

    # The state prefix (must be non-empty; an empty filter is rejected by S3).
    filter {
      prefix = "${var.state_prefix}/"
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
  }
}

###############################################################################
# Per-stack DynamoDB state locking tables (PAY_PER_REQUEST, keyed by LockID)
###############################################################################

resource "aws_dynamodb_table" "state_lock_primary" {
  for_each = local.stacks_primary

  name         = local.lock_table_name[each.key]
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = merge(local.tags, {
    Name  = local.lock_table_name[each.key]
    Role  = "state-lock"
    Stack = each.key
  })
}

resource "aws_dynamodb_table" "state_lock_replica" {
  provider = aws.replica
  for_each = local.stacks_replica

  name         = local.lock_table_name[each.key]
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = merge(local.tags, {
    Name  = local.lock_table_name[each.key]
    Role  = "state-lock"
    Stack = each.key
  })
}

resource "aws_dynamodb_table" "state_lock_tertiary" {
  provider = aws.tertiary
  for_each = local.stacks_tertiary

  name         = local.lock_table_name[each.key]
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = merge(local.tags, {
    Name  = local.lock_table_name[each.key]
    Role  = "state-lock"
    Stack = each.key
  })
}

###############################################################################
# Per-stack IAM: assume-role policy document (shared) + policy + role
###############################################################################

data "aws_iam_policy_document" "stack_deployer_assume_role" {
  statement {
    sid     = "AllowAccountAndTrustedPrincipals"
    effect  = "Allow"
    actions = ["sts:AssumeRole", "sts:TagSession", "sts:SetSourceIdentity"]

    principals {
      type = "AWS"
      identifiers = concat(
        ["arn:${local.partition}:iam::${local.account_id}:root"],
        var.trusted_principal_arns,
      )
    }
  }
}

data "aws_iam_policy_document" "stack_state_access" {
  for_each = var.eks_stacks

  # List only this stack's own prefix inside the state bucket.
  statement {
    sid     = "ListOwnStatePrefix"
    effect  = "Allow"
    actions = ["s3:ListBucket", "s3:ListBucketVersions", "s3:GetBucketLocation"]
    resources = [
      aws_s3_bucket.primary.arn,
    ]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values = [
        "${var.state_prefix}/${each.key}/",
        "${var.state_prefix}/${each.key}/*",
      ]
    }
  }

  # Read/write objects only inside this stack's own prefix.
  statement {
    sid    = "ReadWriteOwnStateObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectTagging",
      "s3:PutObject",
      "s3:PutObjectTagging",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]
    resources = [
      "${aws_s3_bucket.primary.arn}/${var.state_prefix}/${each.key}/*",
    ]
  }

  # Lock/unlock using this stack's dedicated DynamoDB table (in its own region).
  statement {
    sid    = "UseOwnStateLockTable"
    effect = "Allow"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
      "dynamodb:UpdateItem",
      "dynamodb:ConditionCheckItem",
    ]
    resources = [
      "arn:${local.partition}:dynamodb:${each.value}:${local.account_id}:table/${local.lock_table_name[each.key]}",
    ]
  }

  # Crypto operations against the primary state CMK only.
  statement {
    sid    = "UseStateKmsKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:ReEncrypt*",
    ]
    resources = [
      aws_kms_key.primary.arn,
    ]
  }
}

resource "aws_iam_policy" "stack_state_access" {
  for_each = var.eks_stacks

  name        = "tfstate-${each.key}-access"
  description = "Least-privilege access to the ${each.key} Terraform remote state (bucket prefix, lock table, CMK)"
  policy      = data.aws_iam_policy_document.stack_state_access[each.key].json

  tags = merge(local.tags, {
    Name  = "tfstate-${each.key}-access"
    Role  = "stack-state-access"
    Stack = each.key
  })
}

resource "aws_iam_role" "stack_deployer" {
  for_each = var.eks_stacks

  name               = "tfstate-${each.key}-role"
  description        = "Role used by the ${each.key} pipeline to access its Terraform remote state"
  assume_role_policy = data.aws_iam_policy_document.stack_deployer_assume_role.json

  tags = merge(local.tags, {
    Name  = "tfstate-${each.key}-role"
    Role  = "stack-state-access"
    Stack = each.key
  })
}

resource "aws_iam_role_policy_attachment" "stack_state_access" {
  for_each = var.eks_stacks

  role       = aws_iam_role.stack_deployer[each.key].name
  policy_arn = aws_iam_policy.stack_state_access[each.key].arn
}

###############################################################################
# Generated backend configuration files: eks-stacks/<stack>/backend.tf
###############################################################################

resource "local_file" "stack_backend" {
  for_each = var.eks_stacks

  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    # ---------------------------------------------------------------------------
    # AUTO-GENERATED Terraform backend configuration - DO NOT EDIT BY HAND.
    # Regenerate by re-applying the remote-state bootstrap configuration.
    #
    # EKS stack : ${each.key}
    # Region    : ${each.value}
    # ---------------------------------------------------------------------------
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.primary.id}"
        key            = "${var.state_prefix}/${each.key}/terraform.tfstate"
        region         = "${var.primary_region}"
        encrypt        = true
        kms_key_id     = "${aws_kms_key.primary.arn}"
        dynamodb_table = "${local.lock_table_name[each.key]}"
      }
    }
  EOT

  file_permission      = "0644"
  directory_permission = "0755"
}

###############################################################################
# Outputs
###############################################################################

output "primary_state_bucket" {
  description = "Name of the primary (us-east-1) Terraform state bucket."
  value       = aws_s3_bucket.primary.id
}

output "replica_state_bucket" {
  description = "Name of the cross-region replica Terraform state bucket."
  value       = aws_s3_bucket.replica.id
}

output "primary_kms_key_arn" {
  description = "ARN of the CMK used for the primary state bucket."
  value       = aws_kms_key.primary.arn
}

output "replica_kms_key_arn" {
  description = "ARN of the CMK used for the replica state bucket."
  value       = aws_kms_key.replica.arn
}

output "replication_role_arn" {
  description = "ARN of the IAM role used by S3 cross-region replication."
  value       = aws_iam_role.replication.arn
}

output "state_lock_tables" {
  description = "Map of EKS stack name => DynamoDB state-lock table name."
  value       = local.lock_table_name
}

output "stack_deployer_role_arns" {
  description = "Map of EKS stack name => ARN of the per-stack state access role."
  value       = { for name, role in aws_iam_role.stack_deployer : name => role.arn }
}

output "stack_state_policy_arns" {
  description = "Map of EKS stack name => ARN of the per-stack state access policy."
  value       = { for name, policy in aws_iam_policy.stack_state_access : name => policy.arn }
}

output "generated_backend_files" {
  description = "Map of EKS stack name => path of the generated backend.tf file."
  value       = { for name, file in local_file.stack_backend : name => file.filename }
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to create the Cognito resources."
  type        = string
  default     = "us-east-1"
}

variable "user_pool_name" {
  description = "Name of the Cognito user pool."
  type        = string
  default     = "box_things"
}

variable "app_client_name" {
  description = "Name of the Cognito user pool app client."
  type        = string
  default     = "box_things_client"
}

variable "callback_urls" {
  description = "Sample callback URLs allowed for the app client."
  type        = list(string)
  default     = ["https://example.com/callback"]
}

variable "logout_urls" {
  description = "Sample logout URLs allowed for the app client."
  type        = list(string)
  default     = ["https://example.com/logout"]
}

resource "aws_cognito_user_pool" "box_things" {
  name = var.user_pool_name

  # Use email as an alias for sign-in and auto-verify the email on sign-up.
  alias_attributes         = ["email"]
  auto_verified_attributes = ["email"]

  # Email confirmation link flow.
  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
  }

  # Strong password policy (minimum 8 characters, mixed character classes).
  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_numbers   = true
    require_symbols   = true
    require_uppercase = true
  }

  # MFA turned off.
  mfa_configuration = "OFF"

  # Allow self sign-up (i.e., do not restrict to admin-created users only).
  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  tags = {
    Name = var.user_pool_name
  }
}

resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = var.app_client_name
  user_pool_id = aws_cognito_user_pool.box_things.id

  # Supported authentication flows.
  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  # Token validity settings: access and ID tokens valid for 60 minutes.
  access_token_validity = 60
  id_token_validity     = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  # Sample callback and logout URLs.
  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  # Hosted UI / identity providers.
  supported_identity_providers = ["COGNITO"]

  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]
  allowed_oauth_flows_user_pool_client = true
  generate_secret                      = false

  # Email is used as an alias, so it is not a separate writable username attribute.
  read_attributes  = ["email", "email_verified"]
  write_attributes = ["email"]
}

output "user_pool_id" {
  description = "The ID of the Cognito user pool."
  value       = aws_cognito_user_pool.box_things.id
}

output "user_pool_arn" {
  description = "The ARN of the Cognito user pool."
  value       = aws_cognito_user_pool.box_things.arn
}

output "app_client_id" {
  description = "The ID of the Cognito user pool app client."
  value       = aws_cognito_user_pool_client.box_things_client.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region to deploy the IAM resources into."
  type        = string
  default     = "us-east-1"
}

variable "users" {
  description = <<-EOT
    Map of IAM users to create. The map key is the IAM user name; the value
    contains the tags applied to the user. The tag "Owner" drives group
    membership: "Devel" -> Ersia_Devel_Group, anything else -> Ersia_Guest_Group.
  EOT
  type = map(object({
    tags = map(string)
  }))
  default = {
    dev1 = {
      tags = {
        Owner = "Devel"
      }
    }
    dev2 = {
      tags = {
        Owner = "Devel"
      }
    }
    guest = {
      tags = {
        Owner = "Guest"
      }
    }
  }
}

variable "devel_group_name" {
  description = "Name of the developer IAM group."
  type        = string
  default     = "Ersia_Devel_Group"
}

variable "guest_group_name" {
  description = "Name of the guest IAM group."
  type        = string
  default     = "Ersia_Guest_Group"
}

############################################
# AWS managed policies (resolved by name)
############################################

data "aws_iam_policy" "read_only_access" {
  name = "ReadOnlyAccess"
}

data "aws_iam_policy" "iam_read_only_access" {
  name = "IAMReadOnlyAccess"
}

############################################
# IAM Groups
############################################

resource "aws_iam_group" "devel" {
  name = var.devel_group_name
  path = "/"

  tags = {
    Name    = var.devel_group_name
    Purpose = "Developer read-only access"
  }
}

resource "aws_iam_group" "guest" {
  name = var.guest_group_name
  path = "/"

  tags = {
    Name    = var.guest_group_name
    Purpose = "Guest IAM read-only access"
  }
}

resource "aws_iam_group_policy_attachment" "devel_read_only" {
  group      = aws_iam_group.devel.name
  policy_arn = data.aws_iam_policy.read_only_access.arn
}

resource "aws_iam_group_policy_attachment" "guest_iam_read_only" {
  group      = aws_iam_group.guest.name
  policy_arn = data.aws_iam_policy.iam_read_only_access.arn
}

############################################
# IAM Users (from the configurable map)
############################################

resource "aws_iam_user" "users" {
  for_each = var.users

  name          = each.key
  path          = "/"
  force_destroy = true

  tags = merge(
    each.value.tags,
    {
      Name = each.key
    }
  )
}

############################################
# Group membership driven by the Owner tag
############################################

locals {
  user_group_assignment = {
    for name, user in var.users :
    name => (
      lower(lookup(user.tags, "Owner", "Guest")) == "devel"
      ? aws_iam_group.devel.name
      : aws_iam_group.guest.name
    )
  }
}

resource "aws_iam_user_group_membership" "membership" {
  for_each = local.user_group_assignment

  user = aws_iam_user.users[each.key].name

  groups = [each.value]
}

############################################
# Outputs
############################################

output "devel_group" {
  description = "Developer group details."
  value = {
    name = aws_iam_group.devel.name
    arn  = aws_iam_group.devel.arn
  }
}

output "guest_group" {
  description = "Guest group details."
  value = {
    name = aws_iam_group.guest.name
    arn  = aws_iam_group.guest.arn
  }
}

output "user_names" {
  description = "Names of the IAM users created from the users map."
  value       = sort([for u in aws_iam_user.users : u.name])
}

output "user_group_assignment" {
  description = "Resolved mapping of each IAM user to the group it was added to."
  value       = local.user_group_assignment
}

# Terraform Configuration Overview

The following configuration provisions a **serverless WebSocket → SQS ingestion pipeline** with no Lambda functions:

- **Naming** – A `random_pet` resource (2 words, e.g. `merry-otter`) is used for the API name, the SQS queue name, IAM role/policy names, and the access log group.
- **Encryption** – A customer-managed KMS key with `enable_key_rotation = true` (plus an alias) encrypts the SQS queue.
- **IAM** – An execution role assumable by `apigateway.amazonaws.com`, inline policy granting `sqs:SendMessage` on the queue and CloudWatch Logs write permissions.
- **API Gateway v2 WebSocket API** – `route_selection_expression = "$request.body.action"`:
  - `$connect` → **MOCK** integration returning `{"statusCode":200}`.
  - `$disconnect` → **AWS** `SQS-SendMessage` integration with a static literal body `'Client disconnected'` (single quotes = literal string in API Gateway mapping).
  - `$default` → **AWS** `SQS-SendMessage` integration with `MessageBody = $request.body`, plus a route response and integration response so the SendMessage result is returned to the client.
- **Stage** – `dev`, `auto_deploy = true`, access logging (JSON format) to `/aws/apigateway/<pet>-access-logs` with 1-day retention.
- **Outputs** – Full `wss://…/dev` endpoint URL, queue URL/ARN, KMS key ARN, and integration role ARN.

```iac_template
###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the WebSocket API, SQS queue and KMS key."
  type        = string
  default     = "us-east-1"
}

variable "stage_name" {
  description = "Name of the auto-deployed API Gateway stage."
  type        = string
  default     = "dev"
}

variable "access_log_retention_days" {
  description = "Retention (in days) for the API Gateway access log group."
  type        = number
  default     = 1
}

variable "environment" {
  description = "Environment tag value."
  type        = string
  default     = "dev"
}

###############################################################################
# Data sources / locals
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# Two-word pet name shared by the API and the queue
resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  name = random_pet.this.id

  tags = {
    Name        = random_pet.this.id
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# KMS customer managed key (automatic rotation) - encrypts the SQS queue
###############################################################################

resource "aws_kms_key" "sqs" {
  description             = "Customer managed key protecting the ${local.name} SQS queue"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountFullAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/${local.name}-sqs"
  target_key_id = aws_kms_key.sqs.key_id
}

###############################################################################
# SQS queue (server side encryption with the CMK above)
###############################################################################

resource "aws_sqs_queue" "this" {
  name                              = local.name
  kms_master_key_id                 = aws_kms_key.sqs.arn
  kms_data_key_reuse_period_seconds = 300
  message_retention_seconds         = 86400
  visibility_timeout_seconds        = 30

  tags = local.tags
}

###############################################################################
# IAM execution role assumable by API Gateway (SQS + CloudWatch Logs access)
###############################################################################

data "aws_iam_policy_document" "apigw_assume_role" {
  statement {
    sid     = "AllowApiGatewayToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "apigw_integration" {
  name               = "${local.name}-apigw-sqs-role"
  description        = "Execution role used by the ${local.name} WebSocket API to publish to SQS"
  assume_role_policy = data.aws_iam_policy_document.apigw_assume_role.json

  tags = local.tags
}

data "aws_iam_policy_document" "apigw_integration" {
  statement {
    sid    = "AllowSendMessageToQueue"
    effect = "Allow"

    actions = [
      "sqs:SendMessage",
      "sqs:GetQueueUrl",
      "sqs:GetQueueAttributes",
    ]

    resources = [aws_sqs_queue.this.arn]
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "apigw_integration" {
  name   = "${local.name}-apigw-sqs-policy"
  role   = aws_iam_role.apigw_integration.id
  policy = data.aws_iam_policy_document.apigw_integration.json
}

###############################################################################
# CloudWatch log group for access logs
###############################################################################

resource "aws_cloudwatch_log_group" "access_logs" {
  name              = "/aws/apigateway/${local.name}-access-logs"
  retention_in_days = var.access_log_retention_days

  tags = local.tags
}

###############################################################################
# WebSocket API
###############################################################################

resource "aws_apigatewayv2_api" "this" {
  name                       = local.name
  description                = "WebSocket API forwarding messages to SQS queue ${aws_sqs_queue.this.name}"
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"

  tags = local.tags
}

###############################################################################
# Integrations
###############################################################################

# $connect -> MOCK integration returning a 200 status code
resource "aws_apigatewayv2_integration" "connect_mock" {
  api_id           = aws_apigatewayv2_api.this.id
  integration_type = "MOCK"

  request_templates = {
    "$default" = jsonencode({ statusCode = 200 })
  }
}

# $default -> SQS SendMessage with the raw message body from the client
resource "aws_apigatewayv2_integration" "send_message" {
  api_id              = aws_apigatewayv2_api.this.id
  integration_type    = "AWS"
  integration_subtype = "SQS-SendMessage"
  credentials_arn     = aws_iam_role.apigw_integration.arn

  request_parameters = {
    "QueueUrl"    = aws_sqs_queue.this.id
    "MessageBody" = "$request.body"
  }
}

# $disconnect -> SQS SendMessage with a fixed literal message
resource "aws_apigatewayv2_integration" "disconnect_message" {
  api_id              = aws_apigatewayv2_api.this.id
  integration_type    = "AWS"
  integration_subtype = "SQS-SendMessage"
  credentials_arn     = aws_iam_role.apigw_integration.arn

  request_parameters = {
    "QueueUrl"    = aws_sqs_queue.this.id
    "MessageBody" = "'Client disconnected'"
  }
}

###############################################################################
# Routes
###############################################################################

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect_mock.id}"
}

resource "aws_apigatewayv2_route" "default" {
  api_id                              = aws_apigatewayv2_api.this.id
  route_key                           = "$default"
  route_response_selection_expression = "$default"
  target                              = "integrations/${aws_apigatewayv2_integration.send_message.id}"
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect_message.id}"
}

###############################################################################
# Route / integration responses (returns the SQS SendMessage response)
###############################################################################

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.this.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.this.id
  integration_id           = aws_apigatewayv2_integration.send_message.id
  integration_response_key = "$default"
}

###############################################################################
# Auto-deployed stage with access logging
###############################################################################

resource "aws_apigatewayv2_stage" "dev" {
  api_id        = aws_apigatewayv2_api.this.id
  name          = var.stage_name
  auto_deploy   = true
  description   = "Auto-deployed ${var.stage_name} stage for the ${local.name} WebSocket API"

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.access_logs.arn

    format = jsonencode({
      requestId        = "$context.requestId"
      connectionId     = "$context.connectionId"
      eventType        = "$context.eventType"
      routeKey         = "$context.routeKey"
      status           = "$context.status"
      sourceIp         = "$context.identity.sourceIp"
      requestTime      = "$context.requestTime"
      responseLength   = "$context.responseLength"
      integrationError = "$context.integrationErrorMessage"
    })
  }

  tags = local.tags
}

###############################################################################
# Outputs
###############################################################################

output "websocket_endpoint_url" {
  description = "Full WebSocket endpoint URL including the stage name."
  value       = "wss://${aws_apigatewayv2_api.this.id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_apigatewayv2_stage.dev.name}"
}

output "websocket_api_id" {
  description = "Identifier of the WebSocket API."
  value       = aws_apigatewayv2_api.this.id
}

output "stage_invoke_url" {
  description = "Invoke URL reported by the API Gateway stage (includes the stage name)."
  value       = aws_apigatewayv2_stage.dev.invoke_url
}

output "sqs_queue_url" {
  description = "URL of the SQS queue that receives the forwarded WebSocket messages."
  value       = aws_sqs_queue.this.id
}

output "sqs_queue_arn" {
  description = "ARN of the SQS queue."
  value       = aws_sqs_queue.this.arn
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key encrypting the queue."
  value       = aws_kms_key.sqs.arn
}

output "apigw_integration_role_arn" {
  description = "ARN of the IAM execution role assumed by API Gateway for SQS/CloudWatch integrations."
  value       = aws_iam_role.apigw_integration.arn
}

output "access_log_group_name" {
  description = "Name of the CloudWatch log group receiving API Gateway access logs."
  value       = aws_cloudwatch_log_group.access_logs.name
}
```

###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the test VPCs will be created."
  type        = string
  default     = "us-east-1"
}

# --- VPC 1: XXXX-vpc-test ----------------------------------------------------
variable "vpc_test_name" {
  description = "Name tag for the \"XXXX-vpc-test\" VPC."
  type        = string
  default     = "XXXX-vpc-test"
}

variable "vpc_test_cidr" {
  description = "CIDR block for the \"XXXX-vpc-test\" VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_test_enable_dns_support" {
  description = "Whether DNS resolution is supported in the \"XXXX-vpc-test\" VPC."
  type        = bool
  default     = true
}

variable "vpc_test_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the \"XXXX-vpc-test\" VPC."
  type        = bool
  default     = false
}

# --- VPC 2: Default ----------------------------------------------------------
variable "default_vpc_name" {
  description = "Name tag for the \"Default\" VPC."
  type        = string
  default     = "Default"
}

variable "default_vpc_cidr" {
  description = "CIDR block for the \"Default\" VPC."
  type        = string
  default     = "172.31.0.0/16"
}

variable "default_vpc_enable_dns_support" {
  description = "Whether DNS resolution is supported in the \"Default\" VPC."
  type        = bool
  default     = true
}

variable "default_vpc_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the \"Default\" VPC."
  type        = bool
  default     = true
}

# --- VPC 3: eksctl-eks-cluster-px-cluster/VPC --------------------------------
variable "eksctl_vpc_name" {
  description = "Name tag for the eksctl-managed VPC."
  type        = string
  default     = "eksctl-eks-cluster-px-cluster/VPC"
}

variable "eksctl_vpc_cidr" {
  description = "CIDR block for the eksctl-managed VPC."
  type        = string
  default     = "192.168.0.0/16"
}

variable "eksctl_vpc_enable_dns_support" {
  description = "Whether DNS resolution is supported in the eksctl-managed VPC."
  type        = bool
  default     = true
}

variable "eksctl_vpc_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the eksctl-managed VPC."
  type        = bool
  default     = true
}

variable "eksctl_cluster_name" {
  description = "EKS cluster name recorded by the eksctl tags."
  type        = string
  default     = "eks-cluster-px"
}

variable "eksctl_version" {
  description = "eksctl version recorded by the eksctl tags."
  type        = string
  default     = "0.94.0"
}

# --- VPC 4: untagged ---------------------------------------------------------
variable "untagged_vpc_cidr" {
  description = "CIDR block for the untagged VPC."
  type        = string
  default     = "10.0.0.0/24"
}

variable "untagged_vpc_enable_dns_support" {
  description = "Whether DNS resolution is supported in the untagged VPC."
  type        = bool
  default     = true
}

variable "untagged_vpc_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the untagged VPC."
  type        = bool
  default     = false
}

# --- VPC 5: empty Name tag ---------------------------------------------------
variable "empty_name_vpc_name" {
  description = "Value of the Name tag for the VPC that carries an empty Name tag."
  type        = string
  default     = ""
}

variable "empty_name_vpc_cidr" {
  description = "CIDR block for the VPC that carries an empty Name tag."
  type        = string
  default     = "10.0.0.0/16"
}

variable "empty_name_vpc_enable_dns_support" {
  description = "Whether DNS resolution is supported in the VPC that carries an empty Name tag."
  type        = bool
  default     = true
}

variable "empty_name_vpc_enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled in the VPC that carries an empty Name tag."
  type        = bool
  default     = false
}

###############################################################################
# VPC 1: XXXX-vpc-test  (default tenancy, DNS support enabled)
###############################################################################

resource "aws_vpc" "vpc_test" {
  cidr_block           = var.vpc_test_cidr
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc_test_enable_dns_support
  enable_dns_hostnames = var.vpc_test_enable_dns_hostnames

  tags = {
    Name = var.vpc_test_name
  }
}

###############################################################################
# VPC 2: Default  (DNS support + DNS hostnames enabled)
###############################################################################

resource "aws_vpc" "default_vpc" {
  cidr_block           = var.default_vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = var.default_vpc_enable_dns_support
  enable_dns_hostnames = var.default_vpc_enable_dns_hostnames

  tags = {
    Name = var.default_vpc_name
  }
}

###############################################################################
# VPC 3: eksctl-eks-cluster-px-cluster/VPC  (eksctl tags, DNS hostnames on)
###############################################################################

resource "aws_vpc" "eksctl_vpc" {
  cidr_block           = var.eksctl_vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = var.eksctl_vpc_enable_dns_support
  enable_dns_hostnames = var.eksctl_vpc_enable_dns_hostnames

  tags = {
    Name                          = var.eksctl_vpc_name
    "alpha.eksctl.io/cluster-name"    = var.eksctl_cluster_name
    "alpha.eksctl.io/eksctl-version"  = var.eksctl_version
  }
}

###############################################################################
# VPC 4: standalone, untagged VPC
###############################################################################

resource "aws_vpc" "untagged_vpc" {
  cidr_block           = var.untagged_vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = var.untagged_vpc_enable_dns_support
  enable_dns_hostnames = var.untagged_vpc_enable_dns_hostnames
}

###############################################################################
# VPC 5: standalone VPC with an empty Name tag
###############################################################################

resource "aws_vpc" "empty_name_vpc" {
  cidr_block           = var.empty_name_vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = var.empty_name_vpc_enable_dns_support
  enable_dns_hostnames = var.empty_name_vpc_enable_dns_hostnames

  tags = {
    Name = var.empty_name_vpc_name
  }
}

###############################################################################
# Outputs
###############################################################################

output "vpc_test_id" {
  description = "ID of the \"XXXX-vpc-test\" VPC."
  value       = aws_vpc.vpc_test.id
}

output "default_vpc_id" {
  description = "ID of the \"Default\" VPC."
  value       = aws_vpc.default_vpc.id
}

output "eksctl_vpc_id" {
  description = "ID of the eksctl-managed VPC."
  value       = aws_vpc.eksctl_vpc.id
}

output "untagged_vpc_id" {
  description = "ID of the untagged VPC."
  value       = aws_vpc.untagged_vpc.id
}

output "empty_name_vpc_id" {
  description = "ID of the VPC carrying an empty Name tag."
  value       = aws_vpc.empty_name_vpc.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region used by the provider."
  type        = string
  default     = "us-east-1"
}

variable "default_tags" {
  description = "Default tags applied globally by the AWS provider."
  type        = map(string)
  default     = {}
}

variable "tags" {
  description = "Optional tags for resources. Tags identical to provider default_tags are skipped here and inherited from the provider."
  type        = map(string)
  default     = {}
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.default_tags
  }
}

locals {
  resource_tags = {
    for k, v in var.tags : k => v
    if lookup(var.default_tags, k, null) != v
  }
}

data "aws_iam_policy_document" "ecs_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "events_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_role" {
  name = "ecs-role"

  assume_role_policy = data.aws_iam_policy_document.ecs_assume_role.json

  force_detach_policies = true
  path                  = "/"
  tags                  = local.resource_tags
}

resource "aws_iam_role" "ecs_tasks_role" {
  name = "ecs-tasks-role"

  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  force_detach_policies = true
  path                  = "/"
  tags                  = local.resource_tags
}

resource "aws_iam_role" "events_role" {
  name = "events-role"

  assume_role_policy = data.aws_iam_policy_document.events_assume_role.json

  force_detach_policies = true
  path                  = "/"
  tags                  = local.resource_tags
}

resource "aws_iam_role_policy_attachment" "ecs_service_managed" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_execution_managed" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

data "aws_iam_policy_document" "ecs_policy" {
  statement {
    sid    = "AllowRunTask"
    effect = "Allow"

    actions   = ["ecs:RunTask"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowPassTaskExecutionRole"
    effect = "Allow"

    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_tasks_role.arn]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  description = "Policy for EventBridge to run ECS tasks and pass only the ECS task execution role."
  path        = "/"

  policy = data.aws_iam_policy_document.ecs_policy.json

  tags = local.resource_tags
}

resource "aws_iam_role_policy_attachment" "events_custom_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_cloudwatch_logs" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

##############################################################################
# Terraform / Providers
##############################################################################
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

# Primary region (us-east-1) - default provider.
provider "aws" {
  region = "us-east-1"
}

# Multi-Region Access Points can only be created and managed from us-west-2,
# so the secondary bucket and the access point live in this aliased provider.
provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

##############################################################################
# Variables
##############################################################################
variable "primary_bucket_name" {
  description = "Base name of the primary S3 bucket. The AWS account ID is appended to make the name globally unique."
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Base name of the secondary (replica) S3 bucket. The AWS account ID is appended to make the name globally unique."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point."
  type        = string
  default     = "example-mrap"
}

##############################################################################
# Account / naming helpers
##############################################################################
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id    = data.aws_caller_identity.current.account_id
  partition     = data.aws_partition.current.partition
  primary_name  = "${var.primary_bucket_name}-${data.aws_caller_identity.current.account_id}"
  secondary_name = "${var.secondary_bucket_name}-${data.aws_caller_identity.current.account_id}"
}

##############################################################################
# KMS keys (one customer-managed key per bucket / region)
##############################################################################
resource "aws_kms_key" "primary" {
  description             = "SSE-KMS key for the primary S3 bucket (${local.primary_name})"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = local.primary_name
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/${local.primary_name}"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "secondary" {
  provider = aws.us_west_2

  description             = "SSE-KMS key for the secondary S3 bucket (${local.secondary_name})"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = local.secondary_name
  }
}

resource "aws_kms_alias" "secondary" {
  provider = aws.us_west_2

  name          = "alias/${local.secondary_name}"
  target_key_id = aws_kms_key.secondary.key_id
}

##############################################################################
# Primary bucket (us-east-1)
##############################################################################
resource "aws_s3_bucket" "primary" {
  bucket = local.primary_name

  tags = {
    Name = local.primary_name
    Role = "primary"
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  depends_on = [aws_s3_bucket_ownership_controls.primary]

  bucket = aws_s3_bucket.primary.id
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

##############################################################################
# Secondary bucket (us-west-2 - the MRAP control-plane region)
##############################################################################
resource "aws_s3_bucket" "secondary" {
  provider = aws.us_west_2

  bucket = local.secondary_name

  tags = {
    Name = local.secondary_name
    Role = "secondary"
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider = aws.us_west_2

  depends_on = [aws_s3_bucket_ownership_controls.secondary]

  bucket = aws_s3_bucket.secondary.id
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

##############################################################################
# IAM role assumed by Amazon S3 to replicate objects
##############################################################################
data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name_prefix        = "${var.primary_bucket_name}-replication-"
  description        = "Role assumed by Amazon S3 to replicate objects from ${local.primary_name} to ${local.secondary_name}"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
}

data "aws_iam_policy_document" "replication" {
  # Read - source bucket level
  statement {
    sid    = "ReadSourceBucketReplicationConfiguration"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  # Read - source object level
  statement {
    sid    = "ReadSourceObjects"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  # Replicate - destination object level
  statement {
    sid    = "ReplicateObjectsToDestination"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  # Decrypt source objects with the primary key
  statement {
    sid    = "DecryptSourceObjects"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  # Encrypt replica objects with the secondary key
  statement {
    sid    = "EncryptReplicaObjects"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_role_policy" "replication" {
  name   = "${var.primary_bucket_name}-s3-replication-policy"
  role   = aws_iam_role.replication.id
  policy = data.aws_iam_policy_document.replication.json
}

##############################################################################
# Cross-region replication (primary -> secondary)
##############################################################################
resource "aws_s3_bucket_replication_configuration" "primary_to_secondary" {
  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_iam_role_policy.replication,
  ]

  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-objects"
    status = "Enabled"

    # Empty filter = every object in the bucket.
    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    # Replicate objects that are encrypted with SSE-KMS.
    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }
}

##############################################################################
# Multi-Region Access Point (control plane: us-west-2)
##############################################################################
resource "aws_s3control_multi_region_access_point" "this" {
  provider = aws.us_west_2

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_s3_bucket_public_access_block.primary,
    aws_s3_bucket_public_access_block.secondary,
  ]

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

data "aws_iam_policy_document" "mrap" {
  statement {
    sid    = "AllowOwningAccountGetAndPutObjects"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = [
      "arn:${local.partition}:s3::${local.account_id}:accesspoint/${aws_s3control_multi_region_access_point.this.alias}/object/*",
    ]
  }
}

resource "aws_s3control_multi_region_access_point_policy" "this" {
  provider = aws.us_west_2

  account_id = local.account_id

  details {
    name   = var.mrap_name
    policy = data.aws_iam_policy_document.mrap.json
  }
}

##############################################################################
# Outputs
##############################################################################
output "primary_bucket_name" {
  description = "Name of the primary S3 bucket."
  value       = aws_s3_bucket.primary.id
}

output "secondary_bucket_name" {
  description = "Name of the secondary (replica) S3 bucket."
  value       = aws_s3_bucket.secondary.id
}

output "multi_region_access_point_alias" {
  description = "Alias of the Multi-Region Access Point (for example, mfzwi23gnjvgw.mrap)."
  value       = aws_s3control_multi_region_access_point.this.alias
}

output "multi_region_access_point_domain_name" {
  description = "Global domain name of the Multi-Region Access Point."
  value       = aws_s3control_multi_region_access_point.this.domain_name
}

# Terraform: AWS SSM Patch Manager (Weekly Scan + Install)

This template provisions a complete AWS Systems Manager Patch Manager workflow:

- **Cloud Posse null-label** module for consistent naming/tagging (`id`, `tags`, context propagation).
- **Versioned, encrypted, private S3 log bucket** with a bucket policy granting the owning account read/write (used for Run Command output under the `scanning/` prefix).
- **AMAZON_LINUX_2 patch baseline** with `HIGH` compliance, and an approval rule that auto-approves Critical/Important/Medium *Security, Bugfix, Recommended* patches after 7 days, with non-security updates enabled. Both patch groups (`TOSCAN`, `TOPATCH`) are registered against it.
- **Two maintenance windows** (scan: `cron(0 0 18 ? * WED *)`, install: `cron(0 0 21 ? * WED *)`), each 3 hours long with a 1-hour cutoff.
- **Instance targets** defaulting to `tag:Patch Group = TOSCAN` / `TOPATCH` (overridable).
- **Run Command tasks** using `AWS-RunPatchBaseline`, `max_concurrency = 20`, `max_errors = 50`, `Scan` (no reboot) and `Install` (RebootIfNeeded) operations, S3 output, optional SNS notification config, optional CloudWatch Logs output (log group created when enabled).
- **IAM service role** (`AmazonSSMMaintenanceWindowRole`) trusted by `ssm.amazonaws.com`, used by both tasks.

```hcl
###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.40.0, < 6.0.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Cloud Posse null-label (naming + tagging context)
###############################################################################

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace           = var.namespace
  tenant              = var.tenant
  environment         = var.environment
  stage               = var.stage
  name                = var.name
  delimiter           = var.delimiter
  attributes          = var.attributes
  tags                = var.tags
  label_order         = var.label_order
  regex_replace_chars = var.regex_replace_chars
  id_length_limit     = var.id_length_limit
  label_value_case    = var.label_value_case
  descriptor_formats  = var.descriptor_formats
  enabled             = var.enabled
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  create_s3_log_bucket        = var.enabled && var.create_s3_log_bucket
  create_cloudwatch_log_group = var.enabled && var.cloudwatch_output_enabled && var.create_cloudwatch_log_group

  s3_log_bucket_name        = lower(coalesce(var.s3_log_bucket_name, "${module.label.id}-logs-${local.account_id}"))
  s3_output_bucket          = local.create_s3_log_bucket ? aws_s3_bucket.logs[0].id : (var.s3_log_bucket_name != "" ? var.s3_log_bucket_name : null)
  cloudwatch_log_group_name = coalesce(var.cloudwatch_log_group_name, "/aws/ssm/${module.label.id}-patch")

  sns_notifications_enabled = var.enable_sns_notifications && var.sns_topic_arn != null
}

###############################################################################
# S3 log bucket for Run Command output (versioned, private, SSE-S3)
###############################################################################

resource "aws_s3_bucket" "logs" {
  count = local.create_s3_log_bucket ? 1 : 0

  bucket        = local.s3_log_bucket_name
  force_destroy = var.s3_log_bucket_force_destroy

  tags = merge(module.label.tags, { Name = local.s3_log_bucket_name })
}

resource "aws_s3_bucket_versioning" "logs" {
  count  = local.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  count  = local.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count  = local.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "logs" {
  count = local.create_s3_log_bucket ? 1 : 0

  statement {
    sid    = "AllowOwningAccountReadWrite"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:PutObject",
      "s3:PutObjectAcl",
    ]

    resources = [
      aws_s3_bucket.logs[0].arn,
      "${aws_s3_bucket.logs[0].arn}/*",
    ]
  }
}

resource "aws_s3_bucket_policy" "logs" {
  count  = local.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.logs[0].id
  policy = data.aws_iam_policy_document.logs[0].json

  depends_on = [aws_s3_bucket_public_access_block.logs]
}

###############################################################################
# IAM role used by the maintenance window tasks (Run Command)
###############################################################################

data "aws_iam_policy_document" "maintenance_window_assume_role" {
  count = var.enabled ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "maintenance_window" {
  count = var.enabled ? 1 : 0

  name               = "${module.label.id}-mw"
  description        = "Service role assumed by AWS Systems Manager maintenance windows created by ${module.label.id}"
  assume_role_policy = data.aws_iam_policy_document.maintenance_window_assume_role[0].json

  tags = merge(module.label.tags, { Name = "${module.label.id}-mw" })
}

resource "aws_iam_role_policy_attachment" "maintenance_window" {
  count = var.enabled ? 1 : 0

  role       = aws_iam_role.maintenance_window[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonSSMMaintenanceWindowRole"
}

###############################################################################
# Patch baseline (AMAZON_LINUX_2, HIGH compliance, auto-approval after 7 days)
###############################################################################

resource "aws_ssm_patch_baseline" "this" {
  count = var.enabled ? 1 : 0

  name                                 = "${module.label.id}-amazon-linux-2"
  description                          = "Amazon Linux 2 patch baseline managed by ${module.label.id}"
  operating_system                     = var.patch_baseline_operating_system
  approved_patches_compliance_level    = var.approved_patches_compliance_level
  approved_patches_enable_non_security = var.approved_patches_enable_non_security

  approval_rule {
    approve_after_days  = var.approve_after_days
    compliance_level    = var.approval_rule_compliance_level
    enable_non_security = var.approval_rule_enable_non_security

    patch_filter {
      key    = "CLASSIFICATION"
      values = var.patch_classifications
    }

    patch_filter {
      key    = "SEVERITY"
      values = var.patch_severities
    }
  }

  tags = merge(module.label.tags, { Name = "${module.label.id}-amazon-linux-2" })
}

resource "aws_ssm_patch_group" "scan" {
  count = var.enabled ? 1 : 0

  baseline_id = aws_ssm_patch_baseline.this[0].id
  patch_group = var.scan_patch_group
}

resource "aws_ssm_patch_group" "install" {
  count = var.enabled ? 1 : 0

  baseline_id = aws_ssm_patch_baseline.this[0].id
  patch_group = var.install_patch_group
}

###############################################################################
# Maintenance window: SCAN
###############################################################################

resource "aws_ssm_maintenance_window" "scan" {
  count = var.enabled ? 1 : 0

  name                       = "${module.label.id}-scan"
  description                = "Weekly maintenance window used to scan patch group ${var.scan_patch_group} for missing patches"
  schedule                   = var.scan_window_schedule
  duration                   = var.window_duration_hours
  cutoff                     = var.window_cutoff_hours
  allow_unassociated_targets = false

  tags = merge(module.label.tags, { Name = "${module.label.id}-scan" })
}

resource "aws_ssm_maintenance_window_target" "scan" {
  count = var.enabled ? 1 : 0

  window_id     = aws_ssm_maintenance_window.scan[0].id
  name          = "${module.label.id}-scan-targets"
  description   = "Instances to scan (key: ${var.scan_target_tag_key})"
  resource_type = "INSTANCE"

  targets {
    key    = var.scan_target_tag_key
    values = var.scan_target_tag_values
  }
}

resource "aws_ssm_maintenance_window_task" "scan" {
  count = var.enabled ? 1 : 0

  window_id        = aws_ssm_maintenance_window.scan[0].id
  name             = "${module.label.id}-scan"
  description      = "Runs AWS-RunPatchBaseline (Scan) against patch group ${var.scan_patch_group}"
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = var.task_priority
  service_role_arn = aws_iam_role.maintenance_window[0].arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  cutoff_behavior  = var.cutoff_behavior

  targets {
    key    = var.scan_target_tag_key
    values = var.scan_target_tag_values
  }

  task_invocation_parameters {
    run_command_parameters {
      comment              = "Weekly patch compliance scan"
      service_role_arn     = aws_iam_role.maintenance_window[0].arn
      output_s3_bucket     = local.s3_output_bucket
      output_s3_key_prefix = var.output_s3_key_prefix
      timeout_in_seconds   = var.command_timeout_seconds

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.scan_reboot_option]
      }

      dynamic "notification_config" {
        for_each = local.sns_notifications_enabled ? [1] : []

        content {
          notification_arn    = var.sns_topic_arn
          notification_events = var.notification_events
          notification_type   = var.notification_type
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.cloudwatch_output_enabled ? [1] : []

        content {
          cloudwatch_log_group_name = local.cloudwatch_log_group_name
          cloudwatch_output_enabled = true
        }
      }
    }
  }
}

###############################################################################
# Maintenance window: INSTALL
###############################################################################

resource "aws_ssm_maintenance_window" "install" {
  count = var.enabled ? 1 : 0

  name                       = "${module.label.id}-install"
  description                = "Weekly maintenance window used to install patches on patch group ${var.install_patch_group}"
  schedule                   = var.install_window_schedule
  duration                   = var.window_duration_hours
  cutoff                     = var.window_cutoff_hours
  allow_unassociated_targets = false

  tags = merge(module.label.tags, { Name = "${module.label.id}-install" })
}

resource "aws_ssm_maintenance_window_target" "install" {
  count = var.enabled ? 1 : 0

  window_id     = aws_ssm_maintenance_window.install[0].id
  name          = "${module.label.id}-install-targets"
  description   = "Instances to patch (key: ${var.install_target_tag_key})"
  resource_type = "INSTANCE"

  targets {
    key    = var.install_target_tag_key
    values = var.install_target_tag_values
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  count = var.enabled ? 1 : 0

  window_id        = aws_ssm_maintenance_window.install[0].id
  name             = "${module.label.id}-install"
  description      = "Runs AWS-RunPatchBaseline (Install) against patch group ${var.install_patch_group}"
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = var.task_priority
  service_role_arn = aws_iam_role.maintenance_window[0].arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  cutoff_behavior  = var.cutoff_behavior

  targets {
    key    = var.install_target_tag_key
    values = var.install_target_tag_values
  }

  task_invocation_parameters {
    run_command_parameters {
      comment              = "Weekly patch installation"
      service_role_arn     = aws_iam_role.maintenance_window[0].arn
      output_s3_bucket     = local.s3_output_bucket
      output_s3_key_prefix = var.output_s3_key_prefix
      timeout_in_seconds   = var.command_timeout_seconds

      parameter {
        name   = "Operation"
        values = ["Install"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.install_reboot_option]
      }

      dynamic "notification_config" {
        for_each = local.sns_notifications_enabled ? [1] : []

        content {
          notification_arn    = var.sns_topic_arn
          notification_events = var.notification_events
          notification_type   = var.notification_type
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.cloudwatch_output_enabled ? [1] : []

        content {
          cloudwatch_log_group_name = local.cloudwatch_log_group_name
          cloudwatch_output_enabled = true
        }
      }
    }
  }
}

###############################################################################
# Optional CloudWatch Logs group for command output
###############################################################################

resource "aws_cloudwatch_log_group" "patch" {
  count = local.create_cloudwatch_log_group ? 1 : 0

  name              = local.cloudwatch_log_group_name
  retention_in_days = var.cloudwatch_log_group_retention_in_days

  tags = merge(module.label.tags, { Name = local.cloudwatch_log_group_name })
}

###############################################################################
# Outputs
###############################################################################

output "label_id" {
  description = "Cloud Posse label ID used as the naming prefix."
  value       = module.label.id
}

output "tags" {
  description = "Tags applied to all resources created by this configuration."
  value       = module.label.tags
}

output "scan_maintenance_window_id" {
  description = "ID of the patch scan maintenance window."
  value       = try(aws_ssm_maintenance_window.scan[0].id, null)
}

output "install_maintenance_window_id" {
  description = "ID of the patch install maintenance window."
  value       = try(aws_ssm_maintenance_window.install[0].id, null)
}

output "patch_baseline_id" {
  description = "ID of the Amazon Linux 2 patch baseline."
  value       = try(aws_ssm_patch_baseline.this[0].id, null)
}

output "scan_patch_group" {
  description = "Patch group registered for the scan baseline."
  value       = try(aws_ssm_patch_group.scan[0].patch_group, null)
}

output "install_patch_group" {
  description = "Patch group registered for the install baseline."
  value       = try(aws_ssm_patch_group.install[0].patch_group, null)
}

output "maintenance_window_role_arn" {
  description = "ARN of the IAM service role used by the maintenance window tasks."
  value       = try(aws_iam_role.maintenance_window[0].arn, null)
}

output "s3_log_bucket_name" {
  description = "Name of the S3 bucket used for Run Command output."
  value       = try(aws_s3_bucket.logs[0].id, null)
}

output "s3_log_bucket_arn" {
  description = "ARN of the S3 bucket used for Run Command output."
  value       = try(aws_s3_bucket.logs[0].arn, null)
}

output "s3_output_bucket" {
  description = "S3 bucket actually used as the Run Command output location."
  value       = local.s3_output_bucket
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Logs group used for command output (when enabled)."
  value       = try(aws_cloudwatch_log_group.patch[0].name, local.cloudwatch_log_group_name)
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  type        = string
  description = "AWS region where the patch management resources are deployed."
  default     = "us-east-1"
}

# --- Cloud Posse null-label inputs ---

variable "namespace" {
  type        = string
  description = "Cloud Posse label namespace (e.g. company or org)."
  default     = null
}

variable "tenant" {
  type        = string
  description = "Cloud Posse label tenant (e.g. owning team)."
  default     = null
}

variable "environment" {
  type        = string
  description = "Cloud Posse label environment (e.g. ue2)."
  default     = null
}

variable "stage" {
  type        = string
  description = "Cloud Posse label stage (e.g. prod, nonprod)."
  default     = null
}

variable "name" {
  type        = string
  description = "Cloud Posse label name used as the base for all resource names."
  default     = "ssm-patch"
}

variable "delimiter" {
  type        = string
  description = "Delimiter between label parts."
  default     = "-"
}

variable "attributes" {
  type        = list(string)
  description = "Additional label attributes appended to the ID."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags applied to all resources."
  default     = {}
}

variable "label_order" {
  type        = list(string)
  description = "Order in which label components are joined into the ID."
  default     = ["namespace", "tenant", "environment", "stage", "name", "attributes"]
}

variable "regex_replace_chars" {
  type        = string
  description = "Regex of characters to replace in label values (null keeps the module default)."
  default     = null
}

variable "id_length_limit" {
  type        = number
  description = "Maximum length of the generated ID (null keeps the module default)."
  default     = null
}

variable "label_value_case" {
  type        = string
  description = "Case of the label values: lower, upper, title or none."
  default     = "lower"
}

variable "descriptor_formats" {
  type        = any
  description = "Cloud Posse descriptor formats for additional label outputs."
  default     = {}
}

variable "enabled" {
  type        = bool
  description = "Set to false to disable creation of all patch management resources."
  default     = true
}

# --- Scheduling ---

variable "scan_window_schedule" {
  type        = string
  description = "Cron expression for the patch scan maintenance window."
  default     = "cron(0 0 18 ? * WED *)"
}

variable "install_window_schedule" {
  type        = string
  description = "Cron expression for the patch install maintenance window."
  default     = "cron(0 0 21 ? * WED *)"
}

variable "window_duration_hours" {
  type        = number
  description = "Duration of each maintenance window in hours."
  default     = 3
}

variable "window_cutoff_hours" {
  type        = number
  description = "Hours before the end of the window when no new tasks are started."
  default     = 1
}

variable "cutoff_behavior" {
  type        = string
  description = "Task behavior when the cutoff is reached: CONTINUE_TASK or CANCEL_TASK."
  default     = "CONTINUE_TASK"
}

# --- Patch groups and targets ---

variable "scan_patch_group" {
  type        = string
  description = "Patch group registered against the patch baseline for scanning."
  default     = "TOSCAN"
}

variable "install_patch_group" {
  type        = string
  description = "Patch group registered against the patch baseline for installing."
  default     = "TOPATCH"
}

variable "scan_target_tag_key" {
  type        = string
  description = "Target key used to select instances for the scan window."
  default     = "tag:Patch Group"
}

variable "scan_target_tag_values" {
  type        = list(string)
  description = "Target values used to select instances for the scan window."
  default     = ["TOSCAN"]
}

variable "install_target_tag_key" {
  type        = string
  description = "Target key used to select instances for the install window."
  default     = "tag:Patch Group"
}

variable "install_target_tag_values" {
  type        = list(string)
  description = "Target values used to select instances for the install window."
  default     = ["TOPATCH"]
}

# --- Run Command task settings ---

variable "task_priority" {
  type        = number
  description = "Priority of the Run Command task within the maintenance window."
  default     = 1
}

variable "max_concurrency" {
  type        = string
  description = "Maximum number of instances targeted at once (number or percentage)."
  default     = "20"
}

variable "max_errors" {
  type        = string
  description = "Maximum number of errors tolerated before the task stops (number or percentage)."
  default     = "50"
}

variable "command_timeout_seconds" {
  type        = number
  description = "Timeout in seconds for the Run Command invocation."
  default     = 3600
}

variable "scan_reboot_option" {
  type        = string
  description = "Reboot option used by the scan task (NoReboot keeps scanning side effect free)."
  default     = "NoReboot"
}

variable "install_reboot_option" {
  type        = string
  description = "Reboot option used by the install task: RebootIfNeeded or NoReboot."
  default     = "RebootIfNeeded"
}

# --- Output logging ---

variable "output_s3_key_prefix" {
  type        = string
  description = "S3 key prefix used for Run Command output."
  default     = "scanning"
}

variable "create_s3_log_bucket" {
  type        = bool
  description = "Create a versioned, private S3 bucket for Run Command output."
  default     = true
}

variable "s3_log_bucket_name" {
  type        = string
  description = "Explicit S3 bucket name for logs. When empty, a name is generated from the label and account ID (also used as the output bucket when create_s3_log_bucket is false)."
  default     = ""
}

variable "s3_log_bucket_force_destroy" {
  type        = bool
  description = "Allow destruction of the log bucket even when it contains objects."
  default     = false
}

variable "enable_sns_notifications" {
  type        = bool
  description = "Enable SNS notifications for the Run Command tasks."
  default     = false
}

variable "sns_topic_arn" {
  type        = string
  description = "SNS topic ARN used for task notifications when enable_sns_notifications is true."
  default     = null
}

variable "notification_events" {
  type        = list(string)
  description = "SNS notification events (All, InProgress, Success, TimedOut, Cancelled, Failed)."
  default     = ["All"]
}

variable "notification_type" {
  type        = string
  description = "SNS notification type: Command or Invocation."
  default     = "Command"
}

variable "cloudwatch_output_enabled" {
  type        = bool
  description = "Send Run Command output to CloudWatch Logs."
  default     = false
}

variable "create_cloudwatch_log_group" {
  type        = bool
  description = "Create the CloudWatch Logs group used for command output when CloudWatch output is enabled."
  default     = true
}

variable "cloudwatch_log_group_name" {
  type        = string
  description = "CloudWatch Logs group name for command output. When empty, a name is generated from the label."
  default     = ""
}

variable "cloudwatch_log_group_retention_in_days" {
  type        = number
  description = "Retention period in days for the CloudWatch Logs group."
  default     = 30
}

# --- Patch baseline ---

variable "patch_baseline_operating_system" {
  type        = string
  description = "Operating system the patch baseline applies to."
  default     = "AMAZON_LINUX_2"
}

variable "approved_patches_compliance_level" {
  type        = string
  description = "Compliance level assigned to approved patches: CRITICAL, HIGH, MEDIUM, LOW, INFORMATIONAL or UNSPECIFIED."
  default     = "HIGH"
}

variable "approved_patches_enable_non_security" {
  type        = bool
  description = "Allow non-security patches that are explicitly approved to be installed."
  default     = true
}

variable "approve_after_days" {
  type        = number
  description = "Number of days to wait after a patch is released before auto-approving it."
  default     = 7
}

variable "approval_rule_compliance_level" {
  type        = string
  description = "Compliance level assigned to patches approved by the default rule."
  default     = "HIGH"
}

variable "approval_rule_enable_non_security" {
  type        = bool
  description = "Allow the default approval rule to auto-approve non-security patches."
  default     = true
}

variable "patch_classifications" {
  type        = list(string)
  description = "Patch classifications auto-approved by the default rule."
  default     = ["Security", "Bugfix", "Recommended"]
}

variable "patch_severities" {
  type        = list(string)
  description = "Patch severities auto-approved by the default rule."
  default     = ["Critical", "Important", "Medium"]
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region in which the monitoring stack (home region of the multi-region trail) is deployed."
  type        = string
  default     = "us-east-1"
}

variable "alarm_email_recipients" {
  description = "List of email addresses that receive alarm notifications from the management-updates SNS topic."
  type        = list(string)
  default     = ["security-alerts@example.com"]
}

variable "alarm_period_seconds" {
  description = "Period (in seconds) over which the metric is evaluated for each alarm."
  type        = number
  default     = 60
}

variable "alarm_evaluation_periods" {
  description = "Number of periods the threshold must be breached for each alarm to fire."
  type        = number
  default     = 1
}

variable "alarm_threshold" {
  description = "Threshold at which each alarm fires (metric is a Sum of matching CloudTrail events)."
  type        = number
  default     = 1
}

variable "log_retention_in_days" {
  description = "Retention for the CloudTrail CloudWatch Logs group."
  type        = number
  default     = 90
}

variable "tags" {
  description = "Tags applied to all taggable resources in this stack."
  type        = map(string)
  default = {
    Project   = "account-activity-monitoring"
    ManagedBy = "terraform"
  }
}

############################################
# Data sources & locals
############################################

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
  region      = var.aws_region
  trail_name  = "monitor_account_activities"
  bucket_name = "cloudtrail-monitor-management-event-logs-${data.aws_caller_identity.current.account_id}"
  log_group   = "cloudtrail_to_cloudwatch_logs"
  namespace   = "management_activities"

  trail_arn  = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${local.trail_name}"
  account_id_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  # CloudWatch Logs metric filters + matching alarms for sensitive management changes.
  management_activity_filters = {
    "security-group-changes" = {
      metric_name = "SecurityGroupChanges"
      description = "Security group ingress/egress rules or security groups were created, modified, or deleted."
      pattern = "{ ($.eventSource = \"ec2.amazonaws.com\") && (($.eventName = \"AuthorizeSecurityGroupIngress\") || ($.eventName = \"AuthorizeSecurityGroupEgress\") || ($.eventName = \"CreateSecurityGroup\") || ($.eventName = \"DeleteSecurityGroup\") || ($.eventName = \"RevokeSecurityGroupIngress\") || ($.eventName = \"RevokeSecurityGroupEgress\")) }"
    }
    "iam-user-creation-deletion" = {
      metric_name = "IAMUserCreationOrDeletion"
      description = "An IAM user was created or deleted."
      pattern = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreateUser\") || ($.eventName = \"DeleteUser\")) }"
    }
    "failed-console-logins" = {
      metric_name = "FailedConsoleLogins"
      description = "A failed AWS Management Console authentication attempt was recorded."
      pattern = "{ ($.eventName = \"ConsoleLogin\") && ($.errorMessage = \"Failed authentication\") }"
    }
    "iam-group-role-user-policy-changes" = {
      metric_name = "IAMGroupRoleUserPolicyChanges"
      description = "An inline policy was changed on an IAM group, role, or user."
      pattern = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"PutGroupPolicy\") || ($.eventName = \"PutRolePolicy\") || ($.eventName = \"PutUserPolicy\")) }"
    }
    "iam-policy-changes" = {
      metric_name = "IAMPolicyChanges"
      description = "A managed IAM policy was created, deleted, versioned, or attached/detached to a principal."
      pattern = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreatePolicy\") || ($.eventName = \"DeletePolicy\") || ($.eventName = \"CreatePolicyVersion\") || ($.eventName = \"DeletePolicyVersion\") || ($.eventName = \"SetDefaultPolicyVersion\") || ($.eventName = \"AttachGroupPolicy\") || ($.eventName = \"AttachRolePolicy\") || ($.eventName = \"AttachUserPolicy\") || ($.eventName = \"DetachGroupPolicy\") || ($.eventName = \"DetachRolePolicy\") || ($.eventName = \"DetachUserPolicy\"))) }"
    }
    "iam-user-added-to-group" = {
      metric_name = "IAMUserAddedToGroup"
      description = "An IAM user was added to an IAM group."
      pattern = "{ ($.eventSource = \"iam.amazonaws.com\") && ($.eventName = \"AddUserToGroup\") }"
    }
    "iam-role-creation-deletion" = {
      metric_name = "IAMRoleCreationOrDeletion"
      description = "An IAM role was created or deleted."
      pattern = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreateRole\") || ($.eventName = \"DeleteRole\"))) }"
    }
  }
}

############################################
# KMS key for CloudTrail encryption
############################################

data "aws_iam_policy_document" "cloudtrail_kms" {
  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_id_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["kms:GenerateDataKey*"]
    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }

  statement {
    sid    = "AllowCloudTrailToDescribeKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["kms:DescribeKey"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "Customer managed key used to encrypt CloudTrail trails and the CloudTrail log bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.cloudtrail_kms.json

  tags = { Name = "cloudtrail-monitor-account-activities" }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/cloudtrail-monitor-account-activities"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

############################################
# KMS key for the SNS alert topic
############################################

data "aws_iam_policy_document" "sns_kms" {
  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_id_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchAlarmsToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions   = ["kms:Decrypt", "kms:GenerateDataKey*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions   = ["kms:Decrypt", "kms:GenerateDataKey*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  description             = "Customer managed key used to encrypt the management-updates SNS topic."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms.json

  tags = { Name = "management-updates-sns" }
}

resource "aws_kms_alias" "sns" {
  name          = "alias/management-updates-sns"
  target_key_id = aws_kms_key.sns.key_id
}

############################################
# S3 bucket for CloudTrail log delivery
############################################

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = false

  tags = { Name = local.bucket_name }
}

resource "aws_s3_bucket_ownership_controls" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "cloudtrail_logs_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${local.account_id}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.cloudtrail_logs.arn,
      "${aws_s3_bucket.cloudtrail_logs.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_logs_bucket.json
}

############################################
# CloudWatch Logs group + IAM role for CloudTrail
############################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group
  retention_in_days = var.log_retention_in_days

  tags = { Name = local.log_group }
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    sid     = "AllowCloudTrailToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name                 = "cloudtrail-to-cloudwatch-logs-role"
  description          = "Role assumed by CloudTrail to deliver trail events to the CloudWatch Logs group."
  assume_role_policy   = data.aws_iam_policy_document.cloudtrail_assume_role.json
  max_session_duration = 3600

  tags = { Name = "cloudtrail-to-cloudwatch-logs-role" }
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch" {
  statement {
    sid    = "WriteCloudTrailEventsToCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "cloudtrail-to-cloudwatch-logs-policy"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_cloudwatch.json
}

############################################
# Multi-region CloudTrail trail
############################################

resource "aws_cloudtrail" "monitor_account_activities" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true

  kms_key_id                 = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cloudwatch.arn

  advanced_event_selector {
    name = "AllManagementEventsExceptKMSAndRDSData"

    field_selector {
      field  = "eventCategory"
      equals = ["Management"]
    }

    field_selector {
      field      = "eventSource"
      not_equals = ["kms.amazonaws.com", "rdsdata.amazonaws.com"]
    }
  }

  tags = { Name = local.trail_name }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_iam_role_policy.cloudtrail_cloudwatch,
  ]
}

############################################
# SNS topic for alarm notifications
############################################

resource "aws_sns_topic" "management_updates" {
  name              = "management-updates"
  kms_master_key_id = aws_kms_key.sns.id

  tags = { Name = "management-updates" }
}

data "aws_iam_policy_document" "management_updates_topic" {
  statement {
    sid    = "AllowCloudWatchAlarmsToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.management_updates.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "management_updates" {
  arn    = aws_sns_topic.management_updates.arn
  policy = data.aws_iam_policy_document.management_updates_topic.json
}

resource "aws_sns_topic_subscription" "management_updates_email" {
  for_each = toset(var.alarm_email_recipients)

  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.value
}

############################################
# Metric filters + alarms for sensitive management changes
############################################

resource "aws_cloudwatch_log_metric_filter" "management_activities" {
  for_each = local.management_activity_filters

  name           = each.key
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name
  pattern        = each.value.pattern

  metric_transformation {
    name          = each.value.metric_name
    namespace     = local.namespace
    value         = "1"
    default_value = "0"
    unit          = "Count"
  }
}

resource "aws_cloudwatch_metric_alarm" "management_activities" {
  for_each = local.management_activity_filters

  alarm_name          = "management-activities-${each.key}"
  alarm_description   = each.value.description
  namespace           = local.namespace
  metric_name         = each.value.metric_name
  statistic           = "Sum"
  period              = var.alarm_period_seconds
  evaluation_periods  = var.alarm_evaluation_periods
  threshold           = var.alarm_threshold
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "notBreaching"

  alarm_actions = [aws_sns_topic.management_updates.arn]

  tags = { Name = "management-activities-${each.key}" }

  depends_on = [aws_cloudwatch_log_metric_filter.management_activities]
}

############################################
# Outputs
############################################

output "cloudtrail_trail_arn" {
  description = "ARN of the multi-region CloudTrail trail."
  value       = aws_cloudtrail.monitor_account_activities.arn
}

output "cloudtrail_log_bucket" {
  description = "Name of the S3 bucket receiving CloudTrail log files."
  value       = aws_s3_bucket.cloudtrail_logs.id
}

output "cloudtrail_log_group_name" {
  description = "CloudWatch Logs group that receives CloudTrail events."
  value       = aws_cloudwatch_log_group.cloudtrail.name
}

output "cloudtrail_kms_key_arn" {
  description = "ARN of the KMS key encrypting the trail and its log bucket."
  value       = aws_kms_key.cloudtrail.arn
}

output "management_updates_topic_arn" {
  description = "ARN of the SNS topic that receives all management activity alarms."
  value       = aws_sns_topic.management_updates.arn
}

output "management_activity_alarm_names" {
  description = "Names of the CloudWatch alarms created for sensitive management changes."
  value       = [for alarm in aws_cloudwatch_metric_alarm.management_activities : alarm.alarm_name]
}

# Terraform Configuration: AWS Config ACM Certificate Expiration Check

## Description

This Terraform program provisions a complete, self-contained AWS Config setup that continuously evaluates whether ACM certificates in the account are close to expiring.

**AWS resources created:**

| Resource | Purpose |
|---|---|
| `aws_config_config_rule` (`ACM_CERTIFICATE_EXPIRATION_CHECK`) | The AWS-managed Config rule that flags ACM certificates nearing expiration. Enabled by default; the `daysToExpiration` threshold is configurable. |
| `aws_config_configuration_recorder` | Records resource configuration changes so the rule has data to evaluate. |
| `aws_config_delivery_channel` | Delivers configuration snapshots/history to S3. |
| `aws_config_configuration_recorder_status` | Turns the recorder on. |
| `aws_s3_bucket` + policy + public access block | Destination for Config snapshots, secured so only `config.amazonaws.com` may deliver. |
| `aws_iam_role` + attachment | Service role assumed by AWS Config (uses the AWS managed `AWS_ConfigRole` policy, which grants the required S3 and Config permissions). |

**Design notes:**
- The rule name is built from an optional `name_prefix` variable (defaults to `""`), so the naming is stable out of the box and customizable without editing the config.
- The `daysToExpiration` input parameter (default `14`) controls how close to expiry a certificate must be before it is reported as non-compliant.
- Explicit ordering via `depends_on` ensures the recorder is running before the rule is created and evaluated.
- All variables have defaults, so the stack deploys with no required inputs.

```hcl
###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the Config rule and supporting resources."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Optional prefix applied to the names of all resources created by this template."
  type        = string
  default     = ""
}

variable "days_to_expiration" {
  description = "Number of days before ACM certificate expiry at which the Config rule reports a resource as NON_COMPLIANT."
  type        = number
  default     = 14
}

variable "recording_frequency" {
  description = "Frequency with which AWS Config records configuration changes (Continuous or Daily)."
  type        = string
  default     = "Continuous"

  validation {
    condition     = contains(["Continuous", "Daily"], var.recording_frequency)
    error_message = "recording_frequency must be either \"Continuous\" or \"Daily\"."
  }
}

variable "tags" {
  description = "A map of tags to apply to resources that support tagging."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  config_rule_name = "${var.name_prefix}acm-certificate-expiration-check"
  bucket_name      = "${var.name_prefix}aws-config-delivery-${data.aws_caller_identity.current.account_id}-${var.aws_region}"
  config_role_name = "${var.name_prefix}aws-config-role"

  tags = merge(
    var.tags,
    {
      ManagedBy = "Terraform"
      Purpose   = "AWS Config ACM certificate expiration monitoring"
    }
  )
}

###############################################################################
# S3 Bucket for AWS Config Delivery
###############################################################################

resource "aws_s3_bucket" "config" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket = aws_s3_bucket.config.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "config_bucket" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl", "s3:ListBucket"]
    resources = [aws_s3_bucket.config.arn]
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/Config/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "config" {
  bucket = aws_s3_bucket.config.id
  policy = data.aws_iam_policy_document.config_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.config]
}

###############################################################################
# IAM Role for AWS Config
###############################################################################

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "config" {
  name               = local.config_role_name
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

###############################################################################
# AWS Config Recorder, Delivery Channel & Status
###############################################################################

resource "aws_config_configuration_recorder" "this" {
  name     = "${var.name_prefix}config-recorder"
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = false
  }
}

resource "aws_config_delivery_channel" "this" {
  name           = "${var.name_prefix}config-delivery-channel"
  s3_bucket_name = aws_s3_bucket.config.bucket
  s3_key_prefix  = "AWSLogs"

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [aws_s3_bucket_policy.config]
}

resource "aws_config_configuration_recorder_status" "this" {
  name       = aws_config_configuration_recorder.this.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.this]
}

###############################################################################
# AWS Config Managed Rule: ACM Certificate Expiration Check
###############################################################################

resource "aws_config_config_rule" "acm_certificate_expiration_check" {
  name        = local.config_rule_name
  description = "Checks whether ACM certificates in the account are close to their expiration date (${var.days_to_expiration} days)."

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = var.days_to_expiration
  })

  tags = local.tags

  depends_on = [aws_config_configuration_recorder_status.this]
}

###############################################################################
# Outputs
###############################################################################

output "config_rule_name" {
  description = "Name of the AWS Config managed rule monitoring ACM certificate expiration."
  value       = aws_config_config_rule.acm_certificate_expiration_check.name
}

output "config_rule_arn" {
  description = "ARN of the AWS Config managed rule."
  value       = aws_config_config_rule.acm_certificate_expiration_check.arn
}

output "config_recorder_name" {
  description = "Name of the AWS Config configuration recorder."
  value       = aws_config_configuration_recorder.this.name
}

output "config_delivery_bucket" {
  description = "Name of the S3 bucket used by AWS Config for snapshot delivery."
  value       = aws_s3_bucket.config.bucket
}

output "config_role_arn" {
  description = "ARN of the IAM role assumed by AWS Config."
  value       = aws_iam_role.config.arn
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = "fiap-hackathon"
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region where the Cognito user pool will be created."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "user_pool_name" {
  description = "Name of the Cognito user pool."
  type        = string
  default     = "fiap-hackathon-cognito-pool"
}

variable "app_client_name" {
  description = "Name of the Cognito user pool app client."
  type        = string
  default     = "cognito-pool-client"
}

############################################
# Cognito User Pool
############################################

resource "aws_cognito_user_pool" "fiap_hackathon_pool" {
  name = var.user_pool_name

  # Sign in with email address; email is also the username
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  # MFA disabled
  mfa_configuration = "OFF"

  # Required "name" attribute (plus Cognito defaults)
  schema {
    name                = "name"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  # Basic password policy: 8 character minimum, no complexity requirements
  password_policy {
    minimum_length    = 8
    require_lowercase = false
    require_numbers   = false
    require_symbols   = false
    require_uppercase = false
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  tags = {
    Name = var.user_pool_name
  }
}

############################################
# Cognito User Pool App Client
############################################

resource "aws_cognito_user_pool_client" "fiap_hackathon_client" {
  name         = var.app_client_name
  user_pool_id = aws_cognito_user_pool.fiap_hackathon_pool.id

  # Public client: no client secret
  generate_secret = false

  # Supported authentication flows
  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  # Token validity configuration
  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  # Do not let the provider manage client secrets / prevent user existence errors
  prevent_user_existence_errors = "ENABLED"
}

############################################
# Outputs
############################################

output "user_pool_id" {
  description = "ID of the created Cognito user pool."
  value       = aws_cognito_user_pool.fiap_hackathon_pool.id
}

output "user_pool_arn" {
  description = "ARN of the created Cognito user pool."
  value       = aws_cognito_user_pool.fiap_hackathon_pool.arn
}

output "user_pool_endpoint" {
  description = "Endpoint of the created Cognito user pool."
  value       = aws_cognito_user_pool.fiap_hackathon_pool.endpoint
}

output "app_client_id" {
  description = "ID of the created Cognito user pool app client."
  value       = aws_cognito_user_pool_client.fiap_hackathon_client.id
}

output "app_client_name" {
  description = "Name of the created Cognito user pool app client."
  value       = aws_cognito_user_pool_client.fiap_hackathon_client.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the IAM OIDC provider and role are created."
  type        = string
  default     = "us-east-1"
}

variable "azure_ad_tenant_id" {
  description = "Azure AD (Entra ID) tenant ID that issues the tokens used by the Sentinel function apps."
  type        = string
  default     = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
}

variable "azure_ad_client_id" {
  description = "Azure AD application (client) ID that appears as the token audience (aud) claim and must match the OIDC provider audience."
  type        = string
  default     = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
}

variable "azure_ad_thumbprint" {
  description = "Optional explicit SHA-1 thumbprint of the Azure AD issuer TLS certificate. When empty, the thumbprint is derived from the live certificate chain at the issuer URL."
  type        = string
  default     = ""
}

variable "role_name" {
  description = "Name of the IAM role assumed by Sentinel function apps via web identity."
  type        = string
  default     = "Sentinel-OIDC-Organizations-ReadOnly"
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role."
  type        = number
  default     = 3600
}

variable "tags" {
  description = "Additional tags to apply to all created resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  issuer_url = "https://sts.windows.net/${var.azure_ad_tenant_id}/"

  # Condition key used by STS for OIDC providers whose URL contains a path
  # (Azure AD issuers include the tenant ID in the path).
  audience_condition_key = "sts.windows.net/${var.azure_ad_tenant_id}/:aud"

  common_tags = merge(
    {
      ManagedBy = "Terraform"
      Purpose   = "Sentinel-OIDC-Organizations-ReadOnly"
    },
    var.tags
  )
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# Retrieve the live TLS certificate chain presented by the Azure AD issuer so
# that the SHA-1 thumbprint required by the IAM OIDC provider can be derived.
data "tls_certificate" "azure_ad" {
  url = local.issuer_url
}

###############################################################################
# Azure AD OpenID Connect identity provider
###############################################################################

resource "aws_iam_openid_connect_provider" "azure_ad" {
  url = local.issuer_url

  client_id_list = [var.azure_ad_client_id]

  thumbprint_list = var.azure_ad_thumbprint != "" ? [
    var.azure_ad_thumbprint
    ] : [
    data.tls_certificate.azure_ad.certificates[0].sha1_fingerprint
  ]

  tags = merge(
    local.common_tags,
    {
      Name     = "AzureAD-${var.azure_ad_tenant_id}"
      Provider = "sts.windows.net"
    }
  )
}

###############################################################################
# Trust policy for the Sentinel function app role
###############################################################################

data "aws_iam_policy_document" "sentinel_assume_role" {
  statement {
    sid    = "AllowAzureADWebIdentityFederation"
    effect = "Allow"

    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.azure_ad.arn]
    }

    condition {
      test     = "StringEquals"
      variable = local.audience_condition_key
      values   = [var.azure_ad_client_id]
    }
  }
}

###############################################################################
# Role assumed by Sentinel function apps
###############################################################################

resource "aws_iam_role" "sentinel_organizations_readonly" {
  name                 = var.role_name
  description          = "Read-only AWS Organizations access for Sentinel function apps authenticating via Azure AD web identity."
  assume_role_policy   = data.aws_iam_policy_document.sentinel_assume_role.json
  max_session_duration = var.max_session_duration

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "organizations_readonly" {
  role       = aws_iam_role.sentinel_organizations_readonly.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

###############################################################################
# Outputs
###############################################################################

output "oidc_provider_arn" {
  description = "ARN of the Azure AD IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.azure_ad.arn
}

output "oidc_provider_url" {
  description = "Issuer URL of the Azure AD IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.azure_ad.url
}

output "role_name" {
  description = "Name of the role assumed by Sentinel function apps."
  value       = aws_iam_role.sentinel_organizations_readonly.name
}

output "role_arn" {
  description = "ARN of the role assumed by Sentinel function apps."
  value       = aws_iam_role.sentinel_organizations_readonly.arn
}

output "audience_condition_key" {
  description = "STS condition key used for the token audience claim in the role trust policy."
  value       = local.audience_condition_key
}

variable "aws_region" {
  description = "AWS region for the provider"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

resource "aws_iam_role" "test_role" {
  name = "test-iam-wildcard-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "allow_specific" {
  name = "allow-specific-rds-cluster"
  role = aws_iam_role.test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "rds:AddRoleToDBCluster"
        Resource = "arn:aws:rds:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:cluster:foo_cluster"
      }
    ]
  })
}

resource "aws_iam_role_policy" "allow_wildcard" {
  name = "allow-wildcard-rds-clusters"
  role = aws_iam_role.test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "rds:Add*"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "deny_wildcard" {
  name = "deny-wildcard-rds-clusters"
  role = aws_iam_role.test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "rds:Add*"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

## Description of the Terraform Program

This Terraform configuration provisions two logically separate stacks in a single program, deployed to the **us-east-1** region (required because the CloudFront-scoped WAFv2 web ACL must live in us-east-1).

**1. Static frontend hosting stack**
- An **S3 bucket** named `s3-frontend-nft-maker-v2-<account-id>`, with:
  - All public access blocked (4 block-public-acls flags).
  - SSE-KMS encryption using a **dedicated customer-managed KMS key** with automatic rotation enabled.
  - Static website hosting configured with `index.html` as both the index and error document.
  - A CORS rule allowing `GET`, `PUT`, `POST`, `DELETE` from any origin.
- A **CloudFront Origin Access Identity (OAI)** that is granted `s3:GetObject` and `s3:ListBucket` via the bucket policy.
- A **CloudFront distribution** that:
  - Uses the S3 bucket (regional domain) as its origin via the OAI.
  - Redirects viewers to HTTPS (`redirect-to-https`).
  - Enables IPv6.
  - Uses `index.html` as the default root object.
  - Adds ordered cache behaviors for `/content/immutable/*` (1-year TTL) and `/content/*` (1-day TTL), both with compression enabled.
  - Uses **PriceClass_200** and the default CloudFront certificate.
  - Attaches the WAFv2 web ACL via `web_acl_id`.
- A **WAFv2 web ACL** with `CLOUDFRONT` scope, default **Allow**, and the AWS-managed **Common Rule Set** (`AWSManagedRulesCommonRuleSet`).

**2. Terraform remote state backend**
- An **S3 bucket** named `near-frontend-<environment>-terraform-state-<account-id>`, versioned, all public access blocked, encrypted with its **own dedicated customer-managed KMS key** (rotation enabled).
- A **DynamoDB table** named `near-frontend-terraform-state` with a string `LockID` hash key and provisioned capacity of 5 RCU / 5 WCU for state locking.

**Inputs:** `aws_region` (default `us-east-1`) and `environment` (default `dev`). The AWS account ID is obtained via the `aws_caller_identity` data source, so all names are account-scoped. A commented backend block is included so the generated state resources can be wired into a backend after the initial apply.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # Bootstrap note: this bucket/table are created by the configuration below.
  # After the first apply, uncomment and run `terraform init -migrate-state`
  # to move state into the S3 + DynamoDB backend.
  #
  # backend "s3" {
  #   bucket         = "near-frontend-dev-terraform-state-<ACCOUNT_ID>"
  #   key            = "frontend/terraform.tfstate"
  #   region         = "us-east-1"
  #   dynamodb_table = "near-frontend-terraform-state"
  #   encrypt        = true
  # }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = "nft-maker-v2"
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy into. Must be us-east-1 for CLOUDFRONT-scoped WAFv2."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name used in resource naming."
  type        = string
  default     = "dev"
}

# ---------------------------------------------------------------------------
# Account context
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

locals {
  account_id       = data.aws_caller_identity.current.account_id
  frontend_bucket  = "s3-frontend-nft-maker-v2-${local.account_id}"
  state_bucket     = "near-frontend-${var.environment}-terraform-state-${local.account_id}"
  lock_table_name  = "near-frontend-terraform-state"
}

# ===========================================================================
# PART 1 - STATIC FRONTEND HOSTING STACK
# ===========================================================================

# --- Dedicated KMS key for the frontend bucket -----------------------------
resource "aws_kms_key" "frontend" {
  description             = "CMK for ${local.frontend_bucket} (SSE-KMS)"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "nft-maker-v2-frontend-key"
  }
}

resource "aws_kms_alias" "frontend" {
  name          = "alias/nft-maker-v2-frontend"
  target_key_id = aws_kms_key.frontend.key_id
}

# --- Frontend S3 bucket ----------------------------------------------------
resource "aws_s3_bucket" "frontend" {
  bucket = local.frontend_bucket

  tags = {
    Name = local.frontend_bucket
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.frontend.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    allowed_headers = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

# --- CloudFront Origin Access Identity -------------------------------------
resource "aws_cloudfront_origin_access_identity" "frontend" {
  comment = "OAI for ${local.frontend_bucket}"
}

# --- Bucket policy granting the OAI read + list access ---------------------
data "aws_iam_policy_document" "frontend_bucket" {
  statement {
    sid     = "AllowCloudFrontOAIReadList"
    effect  = "Allow"
    actions = ["s3:GetObject", "s3:ListBucket"]

    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.frontend.iam_arn]
    }

    resources = [
      aws_s3_bucket.frontend.arn,
      "${aws_s3_bucket.frontend.arn}/*",
    ]
  }
}

resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id
  policy = data.aws_iam_policy_document.frontend_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.frontend]
}

# --- WAFv2 web ACL (CLOUDFRONT scope, must be in us-east-1) ----------------
resource "aws_wafv2_web_acl" "frontend" {
  name        = "near-frontend-nft-maker-v2-web-acl"
  description = "WAF for the nft-maker-v2 CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "near-frontend-nft-maker-v2-web-acl"
    sampled_requests_enabled   = true
  }

  tags = {
    Name = "near-frontend-nft-maker-v2-web-acl"
  }
}

# --- CloudFront distribution ----------------------------------------------
resource "aws_cloudfront_distribution" "frontend" {
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  price_class         = "PriceClass_200"
  web_acl_id          = aws_wafv2_web_acl.frontend.arn
  comment             = "nft-maker-v2 static frontend"

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.frontend.bucket}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.frontend.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    target_origin_id       = "S3-${aws_s3_bucket.frontend.bucket}"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true

    forwarded_values {
      query_string = false
      headers      = ["Origin"]

      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400
  }

  # Long-lived cache for immutable content
  ordered_cache_behavior {
    path_pattern           = "/content/immutable/*"
    target_origin_id       = "S3-${aws_s3_bucket.frontend.bucket}"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true

    forwarded_values {
      query_string = false
      headers      = ["Origin"]

      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  # Long-lived cache for other content
  ordered_cache_behavior {
    path_pattern           = "/content/*"
    target_origin_id       = "S3-${aws_s3_bucket.frontend.bucket}"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]
    compress               = true

    forwarded_values {
      query_string = false
      headers      = ["Origin"]

      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name = "nft-maker-v2-frontend-distribution"
  }
}

# ===========================================================================
# PART 2 - TERRAFORM REMOTE STATE BACKEND
# ===========================================================================

# --- Dedicated KMS key for the state bucket --------------------------------
resource "aws_kms_key" "state" {
  description             = "CMK for ${local.state_bucket} (SSE-KMS)"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "near-frontend-terraform-state-key"
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/near-frontend-terraform-state"
  target_key_id = aws_kms_key.state.key_id
}

# --- State S3 bucket -------------------------------------------------------
resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket

  tags = {
    Name = local.state_bucket
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
    bucket_key_enabled = true
  }
}

# --- DynamoDB state-lock table ---------------------------------------------
resource "aws_dynamodb_table" "state_lock" {
  name           = local.lock_table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = {
    Name = local.lock_table_name
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "frontend_bucket_name" {
  description = "Name of the static frontend S3 bucket."
  value       = aws_s3_bucket.frontend.bucket
}

output "cloudfront_distribution_id" {
  description = "ID of the CloudFront distribution."
  value       = aws_cloudfront_distribution.frontend.id
}

output "cloudfront_domain_name" {
  description = "Public domain name of the CloudFront distribution."
  value       = aws_cloudfront_distribution.frontend.domain_name
}

output "terraform_state_bucket_name" {
  description = "Name of the S3 bucket used for Terraform remote state."
  value       = aws_s3_bucket.state.bucket
}

output "terraform_state_lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  value       = aws_dynamodb_table.state_lock.name
}
```

##############################################################################
# Terraform & Provider configuration
##############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

##############################################################################
# Variables
##############################################################################

variable "region" {
  description = "AWS region to deploy the dual-stack VPC network foundation into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name used to name and tag all network resources."
  type        = string
  default     = "stackx-network"
}

variable "cluster_name" {
  description = "Name of the EKS cluster that consumes this network (used for discovery tags)."
  type        = string
  default     = "stackx"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "enable_database_subnets" {
  description = "Enable the optional database subnet tier (private, per-AZ route tables, RDS subnet group)."
  type        = bool
  default     = false
}

variable "enable_cache_subnets" {
  description = "Enable the optional cache subnet tier (private, per-AZ route tables, ElastiCache subnet group)."
  type        = bool
  default     = false
}

variable "enable_internal_subnets" {
  description = "Enable the optional internal subnet tier (fully isolated, no internet routes)."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags applied to every resource."
  type        = map(string)
  default     = {}
}

##############################################################################
# Data sources
##############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

data "aws_region" "current" {}

##############################################################################
# Locals
##############################################################################

locals {
  private_subnets  = ["10.1.0.0/18", "10.1.64.0/18", "10.1.128.0/18"]
  public_subnets   = ["10.1.192.0/22", "10.1.196.0/22", "10.1.200.0/22"]
  database_subnets = ["10.1.204.0/24", "10.1.205.0/24", "10.1.206.0/24"]
  cache_subnets    = ["10.1.207.0/24", "10.1.208.0/24", "10.1.209.0/24"]
  internal_subnets = ["10.1.210.0/24", "10.1.211.0/24", "10.1.212.0/24"]
}

locals {
  azs  = slice(data.aws_availability_zones.available.names, 0, 3)
  tags = var.tags
}

##############################################################################
# VPC (dual-stack) + gateways
##############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = merge(local.tags, {
    Name = var.name
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.name}-igw"
  })
}

resource "aws_egress_only_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.name}-eigw"
  })
}

##############################################################################
# Private subnets (large, dual-stack)
##############################################################################

resource "aws_subnet" "private" {
  count = length(local.private_subnets)

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.private_subnets[count.index]
  availability_zone               = local.azs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index)
  assign_ipv6_address_on_creation = true

  tags = merge(local.tags, {
    Name                                        = "${var.name}-private-${local.azs[count.index]}"
    "kubernetes.io/role/internal-elb"           = "1"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "karpenter.sh/discovery"                    = var.cluster_name
  })
}

##############################################################################
# Public subnets (small, dual-stack, no auto-assigned public IPs)
##############################################################################

resource "aws_subnet" "public" {
  count = length(local.public_subnets)

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.public_subnets[count.index]
  availability_zone               = local.azs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 8)
  assign_ipv6_address_on_creation = true
  map_public_ip_on_launch         = false

  tags = merge(local.tags, {
    Name                                        = "${var.name}-public-${local.azs[count.index]}"
    "kubernetes.io/role/elb"                    = "1"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  })
}

##############################################################################
# NAT gateways (one per AZ) with Elastic IPs
##############################################################################

resource "aws_eip" "nat" {
  count = length(local.private_subnets)

  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${var.name}-nat-${local.azs[count.index]}"
  })
}

resource "aws_nat_gateway" "main" {
  count = length(local.private_subnets)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.tags, {
    Name = "${var.name}-nat-${local.azs[count.index]}"
  })

  depends_on = [aws_internet_gateway.main]
}

##############################################################################
# Public route table (shared) - default routes to the Internet Gateway
##############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.name}-public"
  })
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length(local.public_subnets)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

##############################################################################
# Private route tables (one per AZ) - NAT gateway (IPv4) + egress-only IGW (IPv6)
##############################################################################

resource "aws_route_table" "private" {
  count = length(local.private_subnets)

  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.name}-private-${local.azs[count.index]}"
  })
}

resource "aws_route" "private_ipv4_nat" {
  count = length(local.private_subnets)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route" "private_ipv6_eigw" {
  count = length(local.private_subnets)

  route_table_id              = aws_route_table.private[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count = length(local.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

##############################################################################
# Optional database tier (disabled by default)
##############################################################################

resource "aws_subnet" "database" {
  count = var.enable_database_subnets ? length(local.database_subnets) : 0

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.database_subnets[count.index]
  availability_zone               = local.azs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 16)
  assign_ipv6_address_on_creation = true

  tags = merge(local.tags, {
    Name                                        = "${var.name}-database-${local.azs[count.index]}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  })
}

resource "aws_route_table" "database" {
  count = var.enable_database_subnets ? length(local.database_subnets) : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.name}-database-${local.azs[count.index]}"
  })
}

resource "aws_route" "database_ipv4_nat" {
  count = var.enable_database_subnets ? length(local.database_subnets) : 0

  route_table_id         = aws_route_table.database[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route" "database_ipv6_eigw" {
  count = var.enable_database_subnets ? length(local.database_subnets) : 0

  route_table_id              = aws_route_table.database[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main.id
}

resource "aws_route_table_association" "database" {
  count = var.enable_database_subnets ? length(local.database_subnets) : 0

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[count.index].id
}

resource "aws_db_subnet_group" "database" {
  count = var.enable_database_subnets ? 1 : 0

  name       = "${var.name}-database"
  subnet_ids = aws_subnet.database[*].id

  tags = merge(local.tags, {
    Name = "${var.name}-database"
  })
}

##############################################################################
# Optional cache tier (disabled by default)
##############################################################################

resource "aws_subnet" "cache" {
  count = var.enable_cache_subnets ? length(local.cache_subnets) : 0

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.cache_subnets[count.index]
  availability_zone               = local.azs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 24)
  assign_ipv6_address_on_creation = true

  tags = merge(local.tags, {
    Name                                        = "${var.name}-cache-${local.azs[count.index]}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  })
}

resource "aws_route_table" "cache" {
  count = var.enable_cache_subnets ? length(local.cache_subnets) : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.name}-cache-${local.azs[count.index]}"
  })
}

resource "aws_route" "cache_ipv4_nat" {
  count = var.enable_cache_subnets ? length(local.cache_subnets) : 0

  route_table_id         = aws_route_table.cache[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route" "cache_ipv6_eigw" {
  count = var.enable_cache_subnets ? length(local.cache_subnets) : 0

  route_table_id              = aws_route_table.cache[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main.id
}

resource "aws_route_table_association" "cache" {
  count = var.enable_cache_subnets ? length(local.cache_subnets) : 0

  subnet_id      = aws_subnet.cache[count.index].id
  route_table_id = aws_route_table.cache[count.index].id
}

resource "aws_elasticache_subnet_group" "cache" {
  count = var.enable_cache_subnets ? 1 : 0

  name       = "${var.name}-cache"
  subnet_ids = aws_subnet.cache[*].id

  tags = merge(local.tags, {
    Name = "${var.name}-cache"
  })
}

##############################################################################
# Optional internal tier (fully isolated - no internet routes)
##############################################################################

resource "aws_subnet" "internal" {
  count = var.enable_internal_subnets ? length(local.internal_subnets) : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.internal_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.tags, {
    Name                                        = "${var.name}-internal-${local.azs[count.index]}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  })
}

resource "aws_route_table" "internal" {
  count = var.enable_internal_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${var.name}-internal"
  })
}

resource "aws_route_table_association" "internal" {
  count = var.enable_internal_subnets ? length(local.internal_subnets) : 0

  subnet_id      = aws_subnet.internal[count.index].id
  route_table_id = aws_route_table.internal[0].id
}

##############################################################################
# S3 Gateway VPC endpoint (associated with private + optional tier route tables)
##############################################################################

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = concat(
    aws_route_table.private[*].id,
    aws_route_table.database[*].id,
    aws_route_table.cache[*].id,
    aws_route_table.internal[*].id
  )

  tags = merge(local.tags, {
    Name = "${var.name}-s3-endpoint"
  })
}

##############################################################################
# Outputs
##############################################################################

output "vpc_id" {
  description = "ID of the dual-stack VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "IPv4 CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "Amazon-provided IPv6 CIDR block of the VPC."
  value       = aws_vpc.main.ipv6_cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the network."
  value       = local.azs
}

output "private_subnet_ids" {
  description = "IDs of the private (EKS node) subnets."
  value       = aws_subnet.private[*].id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_route_table_ids" {
  description = "IDs of the per-AZ private route tables."
  value       = aws_route_table.private[*].id
}

output "public_route_table_id" {
  description = "ID of the shared public route table."
  value       = aws_route_table.public.id
}

output "nat_gateway_ids" {
  description = "IDs of the per-AZ NAT gateways."
  value       = aws_nat_gateway.main[*].id
}

output "database_subnet_ids" {
  description = "IDs of the optional database subnets (empty when disabled)."
  value       = aws_subnet.database[*].id
}

output "cache_subnet_ids" {
  description = "IDs of the optional cache subnets (empty when disabled)."
  value       = aws_subnet.cache[*].id
}

output "internal_subnet_ids" {
  description = "IDs of the optional internal subnets (empty when disabled)."
  value       = aws_subnet.internal[*].id
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint."
  value       = aws_vpc_endpoint.s3.id
}

# Terraform Configuration for the Weather-Data Lake Pipeline

This template provisions the following on AWS:

- **6 S3 buckets** (`benchmark-glue-artefacts-<ACCOUNT>`, `benchmark-datalake-{staging,bronze,silver,gold,logs}-<ACCOUNT>`) with public access blocked, SSE-KMS default encryption using a shared rotating CMK, and versioning enabled on the artefacts, bronze, silver and gold buckets. The `glueClima` folder scripts are uploaded into the artefacts bucket.
- **KMS CMK + alias** (`alias/benchmark-datalake`) with yearly rotation.
- An **Athena database** `silver` backed by the silver bucket and encrypted with the same CMK.
- An **IAM role for Glue** with Glue, CloudWatch, CloudWatch Logs, Secrets Manager permissions, plus object read/write/delete/list limited to the six buckets and KMS usage of the CMK.
- **Two Glue 4.0 Python jobs**: `glue-job-extrai-dados` (runs `extraiDados.py`) and `glue-job-transforma-dados` (runs `transformaDados.py`, with extra py-files `lib.zip` and the Iceberg data-lake format) — both 20×G.1X workers, 0 retries, max 2 concurrent runs, 2880-min timeout and the logs bucket for `--TempDir`.
- A **Step Functions state machine** running the extraction job synchronously (city `Sao Paulo`, staging bucket, placeholder API key), then the transform job (staging/bronze/silver buckets, placeholder translation key), via a role allowed to start/monitor only those two jobs.
- An **EventBridge hourly rule** triggering the state machine through a dedicated role.

```iac_template
###############################################################################
# Provider & Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Input variables
###############################################################################

variable "aws_region" {
  description = "AWS region to deploy the weather data-lake pipeline into."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Deployment environment tag."
  type        = string
  default     = "prod"
}

variable "city" {
  description = "City passed to the extraction Glue job."
  type        = string
  default     = "Sao Paulo"
}

variable "weather_api_key" {
  description = "Placeholder API key for the weather provider (extraction job)."
  type        = string
  default     = "PLACEHOLDER_WEATHER_API_KEY"
  sensitive   = true
}

variable "translation_api_key" {
  description = "Placeholder API key for the translation service (transform job)."
  type        = string
  default     = "PLACEHOLDER_TRANSLATION_API_KEY"
  sensitive   = true
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  bucket_config = {
    artefacts = { prefix = "benchmark-glue-artefacts",   versioned = true }
    staging   = { prefix = "benchmark-datalake-staging", versioned = false }
    bronze    = { prefix = "benchmark-datalake-bronze",  versioned = true }
    silver    = { prefix = "benchmark-datalake-silver",  versioned = true }
    gold      = { prefix = "benchmark-datalake-gold",    versioned = true }
    logs      = { prefix = "benchmark-datalake-logs",    versioned = false }
  }

  common_tags = {
    Project     = "benchmark-weather-datalake"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# KMS CMK (shared, rotating) + alias
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAwsServicesToUseKey"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = [
        "glue.amazonaws.com",
        "s3.amazonaws.com",
        "athena.amazonaws.com",
        "logs.${var.aws_region}.amazonaws.com",
        "cloudwatch.amazonaws.com",
      ]
    }
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "datalake" {
  description             = "Shared CMK for the benchmark weather data lake"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "datalake" {
  name          = "alias/benchmark-datalake"
  target_key_id = aws_kms_key.datalake.key_id
}

###############################################################################
# Six S3 buckets (prefix + account id)
###############################################################################

resource "aws_s3_bucket" "datalake" {
  for_each = local.bucket_config
  bucket   = "${each.value.prefix}-${local.account_id}"
  tags     = merge(local.common_tags, { Name = "${each.value.prefix}-${local.account_id}" })
}

resource "aws_s3_bucket_public_access_block" "datalake" {
  for_each                = local.bucket_config
  bucket                  = aws_s3_bucket.datalake[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "datalake" {
  for_each = local.bucket_config
  bucket   = aws_s3_bucket.datalake[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "datalake" {
  for_each = { for k, v in local.bucket_config : k => v if v.versioned }
  bucket   = aws_s3_bucket.datalake[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Upload Glue scripts (local glueClima folder) into the artefacts bucket
###############################################################################

resource "aws_s3_object" "glue_scripts" {
  for_each   = fileset("${path.module}/glueClima", "**")
  bucket     = aws_s3_bucket.datalake["artefacts"].id
  key        = "scripts/${each.value}"
  source     = "${path.module}/glueClima/${each.value}"
  etag       = filemd5("${path.module}/glueClima/${each.value}")
  kms_key_id = aws_kms_key.datalake.arn
  tags       = local.common_tags
}

###############################################################################
# Athena database backed by the silver bucket and encrypted with the CMK
###############################################################################

resource "aws_athena_database" "silver" {
  name   = "silver"
  bucket = aws_s3_bucket.datalake["silver"].id

  encryption_configuration {
    encryption_option = "SSE_KMS"
    kms_key           = aws_kms_key.datalake.arn
  }
}

###############################################################################
# IAM role for AWS Glue
###############################################################################

data "aws_iam_policy_document" "glue_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "glue" {
  name               = "benchmark-glue-role"
  assume_role_policy = data.aws_iam_policy_document.glue_assume.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "glue_policy" {
  statement {
    sid       = "GlueServiceAccess"
    effect    = "Allow"
    actions   = ["glue:*"]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:GetLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "CloudWatchMetricsAccess"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }

  statement {
    sid    = "SecretsManagerAccess"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
      "secretsmanager:ListSecrets",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "DataLakeS3Access"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:GetBucketLocation",
    ]
    resources = concat(
      [for b in values(aws_s3_bucket.datalake) : b.arn],
      [for b in values(aws_s3_bucket.datalake) : "${b.arn}/*"]
    )
  }

  statement {
    sid    = "DataLakeKmsAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.datalake.arn]
  }
}

resource "aws_iam_role_policy" "glue" {
  name   = "benchmark-glue-policy"
  role   = aws_iam_role.glue.id
  policy = data.aws_iam_policy_document.glue_policy.json
}

resource "aws_iam_role_policy_attachment" "glue_service_role" {
  role       = aws_iam_role.glue.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSGlueServiceRole"
}

###############################################################################
# Glue jobs
###############################################################################

resource "aws_glue_job" "extrai_dados" {
  name              = "glue-job-extrai-dados"
  role_arn          = aws_iam_role.glue.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.datalake["artefacts"].id}/scripts/extraiDados.py"
    python_version  = "3"
  }

  default_arguments = {
    "--job-language"                     = "python"
    "--TempDir"                          = "s3://${aws_s3_bucket.datalake["logs"].id}/tmp/"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-metrics"                   = "true"
  }

  tags = local.common_tags

  depends_on = [aws_s3_object.glue_scripts]
}

resource "aws_glue_job" "transforma_dados" {
  name              = "glue-job-transforma-dados"
  role_arn          = aws_iam_role.glue.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.datalake["artefacts"].id}/scripts/transformaDados.py"
    python_version  = "3"
  }

  default_arguments = {
    "--job-language"                     = "python"
    "--TempDir"                          = "s3://${aws_s3_bucket.datalake["logs"].id}/tmp/"
    "--datalake-formats"                 = "iceberg"
    "--extra-py-files"                   = "s3://${aws_s3_bucket.datalake["artefacts"].id}/scripts/lib.zip"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-metrics"                   = "true"
  }

  tags = local.common_tags

  depends_on = [aws_s3_object.glue_scripts]
}

###############################################################################
# Step Functions state machine
###############################################################################

data "aws_iam_policy_document" "sfn_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sfn" {
  name               = "benchmark-sfn-role"
  assume_role_policy = data.aws_iam_policy_document.sfn_assume.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "sfn_policy" {
  statement {
    sid    = "StartAndMonitorGlueJobs"
    effect = "Allow"
    actions = [
      "glue:StartJobRun",
      "glue:GetJobRun",
      "glue:GetJobRuns",
      "glue:BatchStopJobRun",
    ]
    resources = [
      aws_glue_job.extrai_dados.arn,
      aws_glue_job.transforma_dados.arn,
    ]
  }
}

resource "aws_iam_role_policy" "sfn" {
  name   = "benchmark-sfn-policy"
  role   = aws_iam_role.sfn.id
  policy = data.aws_iam_policy_document.sfn_policy.json
}

resource "aws_sfn_state_machine" "weather" {
  name     = "benchmark-weather-pipeline"
  role_arn = aws_iam_role.sfn.arn
  tags     = local.common_tags

  definition = jsonencode({
    Comment = "Weather data-lake extraction + transformation pipeline"
    StartAt = "ExtractData"
    States = {
      ExtractData = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--CITY"           = var.city
            "--STAGING_BUCKET" = "s3://${aws_s3_bucket.datalake["staging"].id}"
            "--API_KEY"        = var.weather_api_key
          }
        }
        Next = "TransformData"
      }
      TransformData = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--STAGING_BUCKET"  = "s3://${aws_s3_bucket.datalake["staging"].id}"
            "--BRONZE_BUCKET"   = "s3://${aws_s3_bucket.datalake["bronze"].id}"
            "--SILVER_BUCKET"   = "s3://${aws_s3_bucket.datalake["silver"].id}"
            "--TRANSLATION_KEY" = var.translation_api_key
          }
        }
        End = true
      }
    }
  })
}

###############################################################################
# EventBridge hourly trigger
###############################################################################

data "aws_iam_policy_document" "events_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "events" {
  name               = "benchmark-events-role"
  assume_role_policy = data.aws_iam_policy_document.events_assume.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "events_policy" {
  statement {
    sid       = "StartWeatherStateMachine"
    effect    = "Allow"
    actions   = ["states:StartExecution"]
    resources = [aws_sfn_state_machine.weather.arn]
  }
}

resource "aws_iam_role_policy" "events" {
  name   = "benchmark-events-policy"
  role   = aws_iam_role.events.id
  policy = data.aws_iam_policy_document.events_policy.json
}

resource "aws_cloudwatch_event_rule" "hourly" {
  name                = "benchmark-weather-hourly"
  description         = "Triggers the weather data-lake pipeline every hour"
  schedule_expression = "rate(1 hour)"
  tags                = local.common_tags
}

resource "aws_cloudwatch_event_target" "sfn" {
  rule     = aws_cloudwatch_event_rule.hourly.name
  arn      = aws_sfn_state_machine.weather.arn
  role_arn = aws_iam_role.events.arn
}

###############################################################################
# Outputs
###############################################################################

output "bucket_names" {
  description = "Names of the six data-lake buckets."
  value       = { for k, b in aws_s3_bucket.datalake : k => b.bucket }
}

output "kms_key_alias" {
  description = "Alias of the shared rotating CMK."
  value       = aws_kms_alias.datalake.name
}

output "glue_job_names" {
  description = "Names of the Glue jobs."
  value = {
    extract = aws_glue_job.extrai_dados.name
    transform = aws_glue_job.transforma_dados.name
  }
}

output "state_machine_arn" {
  description = "ARN of the weather pipeline state machine."
  value       = aws_sfn_state_machine.weather.arn
}
```

###############################################################################
# Terraform: CI/CD pipeline for a static website served through CloudFront
# - Target S3 bucket (private, SSE-KMS with CMK, versioned)
# - Artifact S3 bucket (private, SSE-KMS, TLS-only, versioned)
# - CloudFront distribution with Origin Access Control
# - CodeBuild project (small Linux container, 5-minute timeout)
# - CodePipeline (GitHub source, build stage) + GitHub HMAC webhook
# - GitHub OAuth token & webhook secret stored as SecureString SSM parameters
# - Optional SNS notifications and artifact-bucket access logging (off by default)
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  tags = {
    Project   = var.name_prefix
    ManagedBy = "Terraform"
  }
}

###############################################################################
# Variables (all with defaults so the template is deployable as-is)
###############################################################################

variable "region" {
  description = "AWS region for all resources."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used for naming resources."
  type        = string
  default     = "benchmark-cicd"
}

variable "target_bucket_prefix" {
  description = "Prefix for the static-site target S3 bucket name."
  type        = string
  default     = "benchmark-cicd-target"
}

variable "github_repo_owner" {
  description = "GitHub repository owner/organization."
  type        = string
  default     = "my-org"
}

variable "github_repo_name" {
  description = "GitHub repository name."
  type        = string
  default     = "my-static-site"
}

variable "github_branch" {
  description = "GitHub branch to build from."
  type        = string
  default     = "master"
}

variable "github_oauth_token" {
  description = "GitHub OAuth token (placeholder by default; stored as SecureString SSM parameter)."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_GITHUB_OAUTH_TOKEN"
}

variable "github_webhook_secret" {
  description = "GitHub webhook HMAC secret (placeholder by default; stored as SecureString SSM parameter)."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_GITHUB_WEBHOOK_SECRET"
}

variable "codestar_connection_arn" {
  description = "Optional CodeStar (CodeConnections) connection ARN. When supplied, it is used instead of GitHub OAuth."
  type        = string
  default     = ""
}

variable "invalidate_cloudfront" {
  description = "Whether the build stage should invalidate the CloudFront distribution."
  type        = bool
  default     = true
}

variable "build_timeout" {
  description = "CodeBuild project build timeout in minutes."
  type        = number
  default     = 5
}

variable "codebuild_image" {
  description = "CodeBuild build container image."
  type        = string
  default     = "aws/codebuild/standard:7.0"
}

variable "enable_notifications" {
  description = "Enable CodePipeline SNS notifications (off by default)."
  type        = bool
  default     = false
}

variable "enable_artifact_bucket_logging" {
  description = "Enable S3 server access logging for the artifact bucket (off by default)."
  type        = bool
  default     = false
}

###############################################################################
# KMS customer managed key (rotation enabled)
###############################################################################

resource "aws_kms_key" "this" {
  description             = "CMK for ${var.name_prefix} CI/CD buckets and artifacts"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json

  tags = local.tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/${var.name_prefix}"
  target_key_id = aws_kms_key.this.key_id
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudFrontServiceDecrypt"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudfront_distribution.this.arn]
    }
  }
}

###############################################################################
# Target S3 bucket (static site files)
###############################################################################

resource "aws_s3_bucket" "target" {
  bucket        = "${var.target_bucket_prefix}-${local.account_id}"
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "target" {
  bucket = aws_s3_bucket.target.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "target" {
  bucket = aws_s3_bucket.target.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "target" {
  bucket = aws_s3_bucket.target.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target" {
  bucket = aws_s3_bucket.target.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# Bucket policy allowing only the CloudFront distribution (via OAC) to read objects
data "aws_iam_policy_document" "target_bucket" {
  statement {
    sid    = "AllowCloudFrontOACRead"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.target.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.this.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "target" {
  bucket = aws_s3_bucket.target.id
  policy = data.aws_iam_policy_document.target_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.target]
}

###############################################################################
# Artifact S3 bucket (CodePipeline artifacts)
###############################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket        = "${var.name_prefix}-artifacts-${local.account_id}"
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# Deny any request that is not made over TLS
data "aws_iam_policy_document" "artifacts_bucket" {
  statement {
    sid    = "DenyNonTLSAccess"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  policy = data.aws_iam_policy_document.artifacts_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.artifacts]
}

###############################################################################
# Optional: artifact-bucket access logging (off by default)
###############################################################################

resource "aws_s3_bucket" "artifacts_logs" {
  count         = var.enable_artifact_bucket_logging ? 1 : 0
  bucket        = "${var.name_prefix}-artifacts-logs-${local.account_id}"
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "artifacts_logs" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifacts_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "artifacts_logs" {
  count = var.enable_artifact_bucket_logging ? 1 : 0

  statement {
    sid    = "S3LogDeliveryWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.artifacts_logs[0].arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "artifacts_logs" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifacts_logs[0].id
  policy = data.aws_iam_policy_document.artifacts_logs[0].json

  depends_on = [aws_s3_bucket_public_access_block.artifacts_logs]
}

resource "aws_s3_bucket_logging" "artifacts" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifacts.id

  target_bucket = aws_s3_bucket.artifacts_logs[0].id
  target_prefix = "artifact-access-logs/"
}

###############################################################################
# CloudFront distribution (OAC -> private S3 bucket)
###############################################################################

resource "aws_cloudfront_origin_access_control" "this" {
  name                              = "${var.name_prefix}-oac"
  description                       = "OAC for ${var.name_prefix} target bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "this" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "${var.name_prefix} static site"
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.target.bucket_regional_domain_name
    origin_id                = "s3-${aws_s3_bucket.target.id}"
    origin_access_control_id = aws_cloudfront_origin_access_control.this.id
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "s3-${aws_s3_bucket.target.id}"
    viewer_protocol_policy = "redirect-to-https"
    compress               = true

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = local.tags
}

###############################################################################
# GitHub credentials stored as SecureString SSM parameters
###############################################################################

resource "aws_ssm_parameter" "github_oauth_token" {
  name        = "/${var.name_prefix}/github/oauth-token"
  description = "GitHub OAuth token used by CodePipeline"
  type        = "SecureString"
  value       = var.github_oauth_token

  tags = local.tags
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name        = "/${var.name_prefix}/github/webhook-secret"
  description = "GitHub webhook HMAC secret used by CodePipeline webhook"
  type        = "SecureString"
  value       = var.github_webhook_secret

  tags = local.tags
}

data "aws_ssm_parameter" "github_oauth_token" {
  name            = aws_ssm_parameter.github_oauth_token.name
  with_decryption = true
}

data "aws_ssm_parameter" "github_webhook_secret" {
  name            = aws_ssm_parameter.github_webhook_secret.name
  with_decryption = true
}

###############################################################################
# CodeBuild service role
###############################################################################

data "aws_iam_policy_document" "codebuild_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild" {
  name               = "${var.name_prefix}-codebuild-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume.json

  tags = local.tags
}

data "aws_iam_policy_document" "codebuild" {
  statement {
    sid    = "CodeBuildLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${local.partition}:logs:${var.region}:${local.account_id}:log-group:/aws/codebuild/*",
    ]
  }

  statement {
    sid    = "SourceAndArtifactBuckets"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.target.arn,
      "${aws_s3_bucket.target.arn}/*",
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "KmsUse"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.this.arn]
  }

  statement {
    sid    = "CloudFrontInvalidations"
    effect = "Allow"

    actions = [
      "cloudfront:CreateInvalidation",
      "cloudfront:GetInvalidation",
      "cloudfront:GetDistribution",
    ]

    resources = [aws_cloudfront_distribution.this.arn]
  }

  statement {
    sid    = "SsmParameters"
    effect = "Allow"

    actions = [
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:GetParametersByPath",
    ]

    resources = [
      "arn:${local.partition}:ssm:${var.region}:${local.account_id}:parameter/${var.name_prefix}/*",
    ]
  }
}

resource "aws_iam_role_policy" "codebuild" {
  name   = "${var.name_prefix}-codebuild-policy"
  role   = aws_iam_role.codebuild.id
  policy = data.aws_iam_policy_document.codebuild.json
}

###############################################################################
# CodeBuild project
###############################################################################

locals {
  buildspec = <<-EOT
    version: 0.2
    phases:
      build:
        commands:
          - echo "Building static site..."
          - echo "Target bucket: $TARGET_BUCKET"
          - echo "CloudFront distribution: $CLOUDFRONT_DISTRIBUTION_ID"
          - aws s3 sync . "s3://$TARGET_BUCKET" --delete --exclude ".git/*"
      post_build:
        commands:
          - |
            if [ "$INVALIDATE_CLOUDFRONT" = "true" ]; then
              echo "Invalidating CloudFront distribution $CLOUDFRONT_DISTRIBUTION_ID"
              aws cloudfront create-invalidation --distribution-id "$CLOUDFRONT_DISTRIBUTION_ID" --paths "/*"
            else
              echo "CloudFront invalidation disabled."
            fi
  EOT
}

resource "aws_codebuild_project" "this" {
  name          = "${var.name_prefix}-build"
  description   = "Build and deploy ${var.name_prefix} static site"
  service_role  = aws_iam_role.codebuild.arn
  build_timeout = var.build_timeout

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = var.codebuild_image
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target.bucket
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.this.id
    }

    environment_variable {
      name  = "INVALIDATE_CLOUDFRONT"
      value = tostring(var.invalidate_cloudfront)
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = local.buildspec
  }

  tags = local.tags
}

###############################################################################
# CodePipeline role
###############################################################################

data "aws_iam_policy_document" "codepipeline_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codepipeline" {
  name               = "${var.name_prefix}-codepipeline-role"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume.json

  tags = local.tags
}

data "aws_iam_policy_document" "codepipeline" {
  statement {
    sid    = "ArtifactBucket"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "KmsUse"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.this.arn]
  }

  statement {
    sid    = "StartBuild"
    effect = "Allow"

    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild",
    ]

    resources = [aws_codebuild_project.this.arn]
  }

  dynamic "statement" {
    for_each = var.codestar_connection_arn == "" ? [] : [1]

    content {
      sid    = "UseCodeStarConnection"
      effect = "Allow"

      actions   = ["codestar-connections:UseConnection"]
      resources = [var.codestar_connection_arn]
    }
  }
}

resource "aws_iam_role_policy" "codepipeline" {
  name   = "${var.name_prefix}-codepipeline-policy"
  role   = aws_iam_role.codepipeline.id
  policy = data.aws_iam_policy_document.codepipeline.json
}

###############################################################################
# CodePipeline (GitHub source -> CodeBuild)
###############################################################################

resource "aws_codepipeline" "this" {
  name          = "${var.name_prefix}-pipeline"
  role_arn      = aws_iam_role.codepipeline.arn
  pipeline_type = "V1"

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.this.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = var.codestar_connection_arn == "" ? "ThirdParty" : "AWS"
      provider         = var.codestar_connection_arn == "" ? "GitHub" : "CodeStarSourceConnection"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = var.codestar_connection_arn == "" ? {
        Owner                = var.github_repo_owner
        Repo                 = var.github_repo_name
        Branch               = var.github_branch
        OAuthToken           = data.aws_ssm_parameter.github_oauth_token.value
        PollForSourceChanges = "false"
        } : {
        ConnectionArn    = var.codestar_connection_arn
        FullRepositoryId = "${var.github_repo_owner}/${var.github_repo_name}"
        BranchName       = var.github_branch
      }
    }
  }

  stage {
    name = "Build"

    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      version          = "1"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]

      configuration = {
        ProjectName = aws_codebuild_project.this.name
      }
    }
  }

  tags = local.tags
}

###############################################################################
# GitHub webhook (HMAC auth, only pushes to the configured branch)
###############################################################################

resource "aws_codepipeline_webhook" "this" {
  count = var.codestar_connection_arn == "" ? 1 : 0

  name            = "${var.name_prefix}-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.this.name

  authentication_configuration {
    secret_token = data.aws_ssm_parameter.github_webhook_secret.value
  }

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.github_branch}"
  }

  tags = local.tags
}

###############################################################################
# Optional: pipeline notifications to SNS (off by default)
###############################################################################

resource "aws_sns_topic" "notifications" {
  count = var.enable_notifications ? 1 : 0
  name  = "${var.name_prefix}-notifications"

  tags = local.tags
}

data "aws_iam_policy_document" "notifications" {
  count = var.enable_notifications ? 1 : 0

  statement {
    sid    = "AllowCodeStarNotificationsPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["codestar-notifications.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.notifications[0].arn]
  }
}

resource "aws_sns_topic_policy" "notifications" {
  count = var.enable_notifications ? 1 : 0

  arn    = aws_sns_topic.notifications[0].arn
  policy = data.aws_iam_policy_document.notifications[0].json
}

resource "aws_codestarnotifications_notification_rule" "this" {
  count = var.enable_notifications ? 1 : 0

  name        = "${var.name_prefix}-notifications"
  detail_type = "FULL"

  event_type_ids = [
    "codepipeline-pipeline-pipeline-execution-started",
    "codepipeline-pipeline-pipeline-execution-succeeded",
    "codepipeline-pipeline-pipeline-execution-failed",
  ]

  resource = aws_codepipeline.this.arn

  target {
    address = aws_sns_topic.notifications[0].arn
  }

  tags = local.tags
}

###############################################################################
# Outputs
###############################################################################

output "target_bucket_name" {
  description = "Name of the static-site target S3 bucket."
  value       = aws_s3_bucket.target.bucket
}

output "artifact_bucket_name" {
  description = "Name of the CodePipeline artifact S3 bucket."
  value       = aws_s3_bucket.artifacts.bucket
}

output "cloudfront_distribution_id" {
  description = "ID of the CloudFront distribution serving the static site."
  value       = aws_cloudfront_distribution.this.id
}

output "cloudfront_domain_name" {
  description = "Domain name of the CloudFront distribution."
  value       = aws_cloudfront_distribution.this.domain_name
}

output "codebuild_project_name" {
  description = "Name of the CodeBuild project."
  value       = aws_codebuild_project.this.name
}

output "codepipeline_name" {
  description = "Name of the CodePipeline."
  value       = aws_codepipeline.this.name
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key."
  value       = aws_kms_key.this.arn
}

###############################################################################
# General-purpose AWS VPC module
#
# Defaults provision a single VPC named "main" (10.0.0.0/16) and nothing else.
# Subnets / gateways / route tables / subnet groups are only created when
# subnet definitions are supplied via the `subnets` variable.
#
# Example usage with subnets:
#
#   module "vpc" {
#     source = "./modules/vpc"
#
#     name     = "main"
#     az_count = 3
#
#     subnets = [
#       {
#         name    = "public"
#         class   = "public"
#         netnums = [0, 1, 2]
#       },
#       {
#         name                     = "private"
#         class                    = "private"
#         netnums                  = [10, 11, 12]
#         db_subnet_group          = true
#         elasticache_subnet_group = true
#       },
#       {
#         name    = "intra"
#         class   = "intra"
#         netnums = [20, 21, 22]
#       },
#     ]
#   }
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the VPC is created."
  type        = string
  default     = "us-east-1"
}

variable "enabled" {
  description = "Module-level toggle. When false, no resources are created at all."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the VPC, also used as the prefix for every child resource."
  type        = string
  default     = "main"
}

variable "cidr_block" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Tenancy of instances launched into the VPC: default, dedicated or host."
  type        = string
  default     = "default"

  validation {
    condition     = contains(["default", "dedicated", "host"], var.instance_tenancy)
    error_message = "instance_tenancy must be one of: default, dedicated, host."
  }
}

variable "enable_dns_support" {
  description = "Whether DNS resolution is supported inside the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Whether instances launched into the VPC receive public DNS hostnames."
  type        = bool
  default     = false
}

variable "enable_ipv6" {
  description = "Whether to associate an Amazon-provided IPv6 CIDR block with the VPC. Disabled by default."
  type        = bool
  default     = false
}

variable "azs" {
  description = "Explicit list of availability zones to use. When empty, the first `az_count` AZs of the region are used."
  type        = list(string)
  default     = []
}

variable "az_count" {
  description = "Number of availability zones used when a subnet definition does not specify its own CIDR/netnum list."
  type        = number
  default     = 3
}

variable "single_nat_gateway" {
  description = "When true a single NAT gateway is shared by all private subnets; when false one NAT gateway per availability zone is created."
  type        = bool
  default     = true
}

variable "subnets" {
  description = <<-EOT
    Optional list of subnet definitions. Subnets are grouped by `name` and `class`
    (public, private or intra) and one subnet is allocated per availability zone.

    Each definition supports:
      name                     - (required) logical group name, used for resource naming
      class                    - (required) one of: public, private, intra
      cidrs                    - (optional) explicit list of CIDRs, one per AZ
      netnums                  - (optional) list of cidrsubnet() netnums, one per AZ
      newbits                  - (optional) bits added to the VPC prefix (default 8)
      map_public_ip_on_launch  - (optional) auto-assign public IPs (public subnets only, default true)
      db_subnet_group          - (optional) register these subnets in an RDS subnet group (default false)
      elasticache_subnet_group - (optional) register these subnets in an ElastiCache subnet group (default false)
      tags                     - (optional) extra tags for these subnets

    Subnet groups created for a definition are named "<name>-<definition name>-db" and
    "<name>-<definition name>-elasticache".
  EOT

  type = list(object({
    name                     = string
    class                    = string
    cidrs                    = optional(list(string), [])
    netnums                  = optional(list(number), [])
    newbits                  = optional(number, 8)
    map_public_ip_on_launch  = optional(bool, true)
    db_subnet_group          = optional(bool, false)
    elasticache_subnet_group = optional(bool, false)
    tags                     = optional(map(string), {})
  }))

  default = []

  validation {
    condition     = alltrue([for s in var.subnets : contains(["public", "private", "intra"], s.class)])
    error_message = "Each subnet definition 'class' must be one of: public, private, intra."
  }
}

variable "tags" {
  description = "Tags applied to every resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  azs = length(var.azs) > 0 ? var.azs : slice(
    data.aws_availability_zones.available.names,
    0,
    min(var.az_count, length(data.aws_availability_zones.available.names))
  )

  # No subnet definitions at all when the module is disabled.
  subnet_defs = var.enabled ? var.subnets : []

  # Flatten each definition into one entry per availability zone.
  subnets_flat = flatten([
    for s in local.subnet_defs : [
      for idx in range(min(
        length(s.cidrs) > 0 ? length(s.cidrs) : (length(s.netnums) > 0 ? length(s.netnums) : length(local.azs)),
        length(local.azs)
        )) : {
        key                      = "${s.name}-${idx}"
        name                     = s.name
        class                    = s.class
        az                       = local.azs[idx]
        index                    = idx
        cidr                     = length(s.cidrs) > idx ? s.cidrs[idx] : cidrsubnet(var.cidr_block, s.newbits, length(s.netnums) > idx ? s.netnums[idx] : idx)
        map_public_ip_on_launch  = s.class == "public" ? s.map_public_ip_on_launch : false
        db_subnet_group          = s.db_subnet_group
        elasticache_subnet_group = s.elasticache_subnet_group
        tags                     = s.tags
      }
    ]
  ])

  public_subnets  = [for s in local.subnets_flat : s if s.class == "public"]
  private_subnets = [for s in local.subnets_flat : s if s.class == "private"]
  intra_subnets   = [for s in local.subnets_flat : s if s.class == "intra"]

  public_subnet_azs  = toset([for s in local.public_subnets : s.az])
  private_subnet_azs = toset([for s in local.private_subnets : s.az])

  # Key of the (first) public subnet in each availability zone.
  public_subnet_key_by_az = {
    for az in local.public_subnet_azs :
    az => [for s in local.public_subnets : s.key if s.az == az][0]
  }

  # NAT gateways can only be created when both public and private subnets exist.
  nat_azs = (
    var.enabled
    && length(local.public_subnets) > 0
    && length(local.private_subnets) > 0
    ) ? (
    var.single_nat_gateway
    ? [local.public_subnets[0].az]
    : sort(tolist(setintersection(local.private_subnet_azs, local.public_subnet_azs)))
  ) : []

  nat_enabled = length(local.nat_azs) > 0

  private_rt_index_by_az = { for i, az in local.nat_azs : az => i }

  db_subnet_group_names = toset([for s in local.subnet_defs : s.name if s.db_subnet_group])
  ec_subnet_group_names = toset([for s in local.subnet_defs : s.name if s.elasticache_subnet_group])
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  count = var.enabled ? 1 : 0

  cidr_block                       = var.cidr_block
  instance_tenancy                 = var.instance_tenancy
  enable_dns_support               = var.enable_dns_support
  enable_dns_hostnames             = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = var.enable_ipv6

  tags = merge(var.tags, { Name = var.name })
}

###############################################################################
# Internet gateway (public subnets only)
###############################################################################

resource "aws_internet_gateway" "this" {
  count = length(local.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.name}-igw" })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "this" {
  for_each = { for s in local.subnets_flat : s.key => s }

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = each.value.map_public_ip_on_launch

  tags = merge(
    var.tags,
    { Name = "${var.name}-${each.value.name}-${each.value.az}" },
    each.value.tags
  )
}

###############################################################################
# Public routing
###############################################################################

resource "aws_route_table" "public" {
  count = length(local.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.name}-public" })
}

resource "aws_route" "public_internet" {
  count = length(local.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = { for s in local.public_subnets : s.key => s }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Intra routing (isolated - no outbound routes)
###############################################################################

resource "aws_route_table" "intra" {
  count = length(local.intra_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, { Name = "${var.name}-intra" })
}

resource "aws_route_table_association" "intra" {
  for_each = { for s in local.intra_subnets : s.key => s }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.intra[0].id
}

###############################################################################
# NAT gateways (single shared by default, otherwise one per availability zone)
###############################################################################

resource "aws_eip" "nat" {
  count = length(local.nat_azs)

  domain = "vpc"

  tags = merge(var.tags, { Name = "${var.name}-nat-${count.index}" })
}

resource "aws_nat_gateway" "this" {
  count = length(local.nat_azs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.this[local.public_subnet_key_by_az[local.nat_azs[count.index]]].id

  tags = merge(var.tags, { Name = "${var.name}-nat-${count.index}" })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  count = length(local.nat_azs)

  vpc_id = aws_vpc.this[0].id

  tags = merge(var.tags, {
    Name = var.single_nat_gateway ? "${var.name}-private" : "${var.name}-private-${local.nat_azs[count.index]}"
  })
}

resource "aws_route" "private_nat" {
  count = length(local.nat_azs)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

resource "aws_route_table_association" "private" {
  for_each = local.nat_enabled ? { for s in local.private_subnets : s.key => s } : {}

  subnet_id = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[
    try(local.private_rt_index_by_az[each.value.az], 0)
  ].id
}

###############################################################################
# Database / ElastiCache subnet groups (one per qualifying subnet definition)
###############################################################################

resource "aws_db_subnet_group" "this" {
  for_each = local.db_subnet_group_names

  name       = "${var.name}-${each.value}-db"
  subnet_ids = [for s in local.subnets_flat : aws_subnet.this[s.key].id if s.name == each.value]

  tags = merge(var.tags, { Name = "${var.name}-${each.value}-db" })
}

resource "aws_elasticache_subnet_group" "this" {
  for_each = local.ec_subnet_group_names

  name       = "${var.name}-${each.value}-elasticache"
  subnet_ids = [for s in local.subnets_flat : aws_subnet.this[s.key].id if s.name == each.value]

  tags = merge(var.tags, { Name = "${var.name}-${each.value}-elasticache" })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the VPC (null when the module is disabled)."
  value       = one(aws_vpc.this[*].id)
}

output "vpc_arn" {
  description = "ARN of the VPC (null when the module is disabled)."
  value       = one(aws_vpc.this[*].arn)
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC."
  value       = one(aws_vpc.this[*].cidr_block)
}

output "availability_zones" {
  description = "Availability zones used by the module."
  value       = local.azs
}

output "internet_gateway_id" {
  description = "ID of the internet gateway (null when no public subnets are defined)."
  value       = one(aws_internet_gateway.this[*].id)
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways."
  value       = [for n in aws_nat_gateway.this : n.id]
}

output "nat_gateway_public_ips" {
  description = "Elastic IP addresses associated with the NAT gateways."
  value       = [for e in aws_eip.nat : e.public_ip]
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = [for s in local.public_subnets : aws_subnet.this[s.key].id]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = [for s in local.private_subnets : aws_subnet.this[s.key].id]
}

output "intra_subnet_ids" {
  description = "IDs of the intra subnets."
  value       = [for s in local.intra_subnets : aws_subnet.this[s.key].id]
}

output "subnet_ids_by_key" {
  description = "Map of every created subnet, keyed by <name>-<az index>."
  value       = { for s in local.subnets_flat : s.key => aws_subnet.this[s.key].id }
}

output "public_route_table_id" {
  description = "ID of the public route table (null when no public subnets are defined)."
  value       = one(aws_route_table.public[*].id)
}

output "private_route_table_ids" {
  description = "IDs of the private route tables."
  value       = [for rt in aws_route_table.private : rt.id]
}

output "intra_route_table_id" {
  description = "ID of the intra route table (null when no intra subnets are defined)."
  value       = one(aws_route_table.intra[*].id)
}

output "database_subnet_group_names" {
  description = "Names of the created RDS database subnet groups."
  value       = [for g in aws_db_subnet_group.this : g.name]
}

output "elasticache_subnet_group_names" {
  description = "Names of the created ElastiCache subnet groups."
  value       = [for g in aws_elasticache_subnet_group.this : g.name]
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region in which to create the resources."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role that EC2 instances will assume for SSM."
  type        = string
  default     = "ec2-ssm-association"
}

variable "instance_profile_name" {
  description = "Name of the IAM instance profile attached to EC2 instances."
  type        = string
  default     = "ec2-s3-ssm-association"
}

# ---------------------------------------------------------------------------
# Trust policy: allow EC2 to assume the role
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ec2_ssm_association" {
  name                 = var.role_name
  description          = "IAM role that EC2 instances assume for AWS Systems Manager management."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name = var.role_name
  }
}

# ---------------------------------------------------------------------------
# Attach the AWS-managed AmazonSSMManagedInstanceCore policy
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_ssm_association.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# ---------------------------------------------------------------------------
# IAM Instance Profile
# ---------------------------------------------------------------------------
resource "aws_iam_instance_profile" "ec2_s3_ssm_association" {
  name = var.instance_profile_name
  role = aws_iam_role.ec2_ssm_association.name

  tags = {
    Name = var.instance_profile_name
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "role_name" {
  description = "Name of the created IAM role."
  value       = aws_iam_role.ec2_ssm_association.name
}

output "role_arn" {
  description = "ARN of the created IAM role."
  value       = aws_iam_role.ec2_ssm_association.arn
}

output "instance_profile_name" {
  description = "Name of the created IAM instance profile."
  value       = aws_iam_instance_profile.ec2_s3_ssm_association.name
}

output "instance_profile_arn" {
  description = "ARN of the created IAM instance profile."
  value       = aws_iam_instance_profile.ec2_s3_ssm_association.arn
}

## Description of the Terraform program

This Terraform configuration provisions a fully encrypted, customer-managed dead-letter queue pipeline for an aggregation Lambda:

1. **Provider & context** — AWS provider pinned by region variable (default `us-east-1`), plus `aws_caller_identity` and `aws_region` data sources for building ARNs in policies.

2. **KMS customer-managed key** — A new symmetric CMK (`aggregation-lambda-dlq-key`) with `enable_key_rotation = true`, a 30-day deletion window, and an alias (`alias/aggregation-lambda-dlq`). Its key policy grants:
   - the account root full key administration,
   - the SQS service principal `kms:GenerateDataKey`/`kms:Decrypt`/`kms:DescribeKey`, scoped by `aws:SourceArn` to the DLQ ARN (built as a static string to avoid a resource cycle) and `aws:SourceAccount`,
   - the aggregation Lambda execution role the same cryptographic permissions.

3. **SQS dead-letter queue** — `aggregation-lambda-dead-letter-queue`, a standard queue with `message_retention_seconds = 1209600` (14 days), server-side encryption using the new CMK (`kms_master_key_id`), a 300-second data-key reuse period, and long polling. CloudWatch metrics are intentionally omitted so the queue access policy stays unrestricted for the Lambda.

4. **IAM** — An execution role `aggregation-lambda-dlq-role` assumable by `lambda.amazonaws.com`, attached to the AWS managed `AWSLambdaBasicExecutionRole` policy for CloudWatch Logs, plus an inline policy granting `sqs:SendMessage`/`GetQueueAttributes` on this queue and the KMS data-key/decrypt actions on the CMK.

5. **Outputs** — Queue name, ARN, URL, KMS key ARN and alias, and the IAM role ARN for wiring into the aggregation Lambda's environment and dead-letter config.

All variables carry defaults, every referenced resource is declared, and no external dependencies are required.

```iac_template
###############################################################################
# Providers & context
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region where the dead-letter queue and KMS key are created."
  type        = string
  default     = "us-east-1"
}

variable "dlq_name" {
  description = "Name of the SQS dead-letter queue."
  type        = string
  default     = "aggregation-lambda-dead-letter-queue"
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds (14 days = 1209600)."
  type        = number
  default     = 1209600
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for the dead-letter queue in seconds."
  type        = number
  default     = 60
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period before the KMS key is deleted."
  type        = number
  default     = 30
}

variable "tags" {
  description = "Tags applied to all supported resources."
  type        = map(string)
  default = {
    Project     = "aggregation-lambda"
    Environment = "prod"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# KMS customer-managed key (rotation enabled)
###############################################################################

resource "aws_kms_key" "dlq" {
  description             = "Customer-managed key encrypting the ${var.dlq_name} SQS dead-letter queue"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  is_enabled              = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountFullAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowSQSEncryption"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:aws:sqs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:${var.dlq_name}"
          }
        }
      },
      {
        Sid    = "AllowAggregationLambdaRoleUse"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.aggregation_lambda_dlq.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(var.tags, { Name = "${var.dlq_name}-kms-key" })
}

resource "aws_kms_alias" "dlq" {
  name          = "alias/aggregation-lambda-dlq"
  target_key_id = aws_kms_key.dlq.key_id
}

###############################################################################
# SQS dead-letter queue
###############################################################################

resource "aws_sqs_queue" "dlq" {
  name                       = var.dlq_name
  message_retention_seconds  = var.message_retention_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds
  receive_wait_time_seconds  = 20
  sqs_managed_sse_enabled    = false
  kms_master_key_id          = aws_kms_key.dlq.arn
  kms_data_key_reuse_period_seconds = 300

  tags = merge(var.tags, { Name = var.dlq_name })
}

###############################################################################
# IAM: execution role for the aggregation Lambda (producer into the DLQ)
###############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "aggregation_lambda_dlq" {
  name               = "aggregation-lambda-dlq-role"
  description        = "Execution role granting the aggregation Lambda access to the encrypted dead-letter queue"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = merge(var.tags, { Name = "aggregation-lambda-dlq-role" })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.aggregation_lambda_dlq.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "aws_iam_policy_document" "dlq_access" {
  statement {
    sid    = "AllowSendToDeadLetterQueue"
    effect = "Allow"
    actions = [
      "sqs:SendMessage",
      "sqs:SendMessageBatch",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl"
    ]
    resources = [aws_sqs_queue.dlq.arn]
  }

  statement {
    sid    = "AllowUseOfDeadLetterQueueKmsKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.dlq.arn]
  }
}

resource "aws_iam_role_policy" "dlq_access" {
  name   = "aggregation-lambda-dlq-access"
  role   = aws_iam_role.aggregation_lambda_dlq.id
  policy = data.aws_iam_policy_document.dlq_access.json
}

###############################################################################
# Outputs
###############################################################################

output "dead_letter_queue_name" {
  description = "Name of the SQS dead-letter queue."
  value       = aws_sqs_queue.dlq.name
}

output "dead_letter_queue_arn" {
  description = "ARN of the SQS dead-letter queue (use as Lambda dead_letter_config target_arn)."
  value       = aws_sqs_queue.dlq.arn
}

output "dead_letter_queue_url" {
  description = "URL of the SQS dead-letter queue."
  value       = aws_sqs_queue.dlq.url
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used to encrypt the dead-letter queue."
  value       = aws_kms_key.dlq.arn
}

output "kms_key_alias" {
  description = "Alias of the customer-managed KMS key."
  value       = aws_kms_alias.dlq.name
}

output "aggregation_lambda_role_arn" {
  description = "ARN of the IAM role the aggregation Lambda can assume to send failures to the DLQ."
  value       = aws_iam_role.aggregation_lambda_dlq.arn
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

#############################################
# Variables (all with defaults)
#############################################

variable "aws_region" {
  description = "AWS region in which to create the SQS queue."
  type        = string
  default     = "us-east-1"
}

variable "queue_name_prefix" {
  description = "Prefix used to auto-generate a unique queue name."
  type        = string
  default     = "standard-queue-"
}

variable "environment" {
  description = "Environment tag applied to the queue."
  type        = string
  default     = "dev"
}

#############################################
# Provider
#############################################

provider "aws" {
  region = var.aws_region
}

#############################################
# Standard (non-FIFO) SQS Queue
#############################################

resource "aws_sqs_queue" "standard_queue" {
  # Auto-generated name: provider appends a unique suffix to this prefix.
  name_prefix = var.queue_name_prefix

  # Standard queue (not FIFO)
  fifo_queue = false

  # Requested behavior
  visibility_timeout_seconds = 30
  message_retention_seconds  = 345600
  max_message_size           = 262144
  delay_seconds              = 0
  receive_wait_time_seconds  = 0

  tags = {
    Name        = "standard-queue"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

#############################################
# Outputs
#############################################

output "queue_id" {
  description = "The URL/ID of the created SQS queue."
  value       = aws_sqs_queue.standard_queue.id
}

output "queue_url" {
  description = "The URL of the created SQS queue."
  value       = aws_sqs_queue.standard_queue.url
}

output "queue_arn" {
  description = "The ARN of the created SQS queue."
  value       = aws_sqs_queue.standard_queue.arn
}

output "queue_name" {
  description = "The auto-generated name of the created SQS queue."
  value       = aws_sqs_queue.standard_queue.name
}

output "queue_attributes" {
  description = "Effective configuration of the created queue."
  value = {
    fifo_queue                 = aws_sqs_queue.standard_queue.fifo_queue
    visibility_timeout_seconds = aws_sqs_queue.standard_queue.visibility_timeout_seconds
    message_retention_seconds  = aws_sqs_queue.standard_queue.message_retention_seconds
    max_message_size           = aws_sqs_queue.standard_queue.max_message_size
    delay_seconds              = aws_sqs_queue.standard_queue.delay_seconds
    receive_wait_time_seconds  = aws_sqs_queue.standard_queue.receive_wait_time_seconds
  }
}

## Description of the Terraform Program

This configuration manages the **account-level Amazon SNS SMS messaging preferences** for a single AWS region.

**What it deploys:**

1. **Provider & backend setup** – The `hashicorp/aws` provider (~> 5.0) is pinned and configured with a `region` supplied by `var.aws_region` (default `us-east-1`). SNS SMS preferences are account‑ and region‑scoped, so no VPC/networking is required.

2. **`aws_sns_sms_preferences` resource** – The single resource that calls the SNS `SetSMSAttributes` API:
   - `default_sms_type` → **`Transactional`** (drives higher deliverability, no promotional throttling).
   - `delivery_status_success_sampling_rate` → **`0`** (no success events are sampled/logged, so no CloudWatch spend from delivery‑status logging).
   - `default_sender_id`, `monthly_spend_limit`, `delivery_status_iam_role_arn`, and `usage_report_s3_bucket` are driven by **variables whose defaults are `null`**, so by default they are *unset* and the provider omits them from the API call entirely (it uses `GetOk`, so unset values are never sent). Operators can optionally override any of them later without editing the module.

3. **Variables** – Every input has a default value supplied, so the module is deployable with zero required inputs.
   - `aws_region` (default `us-east-1`)
   - `default_sms_type` (default `Transactional`, validated to be `Transactional` or `Promotional`)
   - `delivery_status_success_sampling_rate` (default `"0"`)
   - `default_sender_id` (default `null` – unset)
   - `monthly_spend_limit` (default `null` – unset)
   - `delivery_status_iam_role_arn` (default `null` – unset)
   - `usage_report_s3_bucket` (default `null` – unset)

4. **IAM** – No IAM role is created, because the delivery‑status IAM role ARN is intentionally left unset by default (no delivery‑status logging is enabled at a sampling rate of 0). If an operator later enables delivery‑status logging, they pass the ARN of an existing role that trusts `sns.amazonaws.com`, rather than having this module create an unused principal.

5. **Outputs** – All six configured preference values are exported (`default_sms_type`, `delivery_status_success_sampling_rate`, `default_sender_id`, `monthly_spend_limit`, `delivery_status_iam_role_arn`, `usage_report_s3_bucket`) plus the effective region, so the applied account state can be inspected or consumed by other stacks.

**Note:** `aws_sns_sms_preferences` is an account/region singleton. `terraform destroy` will delete these preferences, reverting the account to AWS defaults.

```iac_template
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region whose account-level SNS SMS preferences are managed."
  type        = string
  default     = "us-east-1"
}

variable "default_sms_type" {
  description = "Default SMS message type used for messages sent via SNS. Either 'Promotional' or 'Transactional'."
  type        = string
  default     = "Transactional"

  validation {
    condition     = contains(["Promotional", "Transactional"], var.default_sms_type)
    error_message = "default_sms_type must be either 'Promotional' or 'Transactional'."
  }
}

variable "delivery_status_success_sampling_rate" {
  description = "Percentage of successful SMS deliveries to log to CloudWatch. Must be between 0 and 100."
  type        = string
  default     = "0"

  validation {
    condition     = can(tonumber(var.delivery_status_success_sampling_rate)) && tonumber(var.delivery_status_success_sampling_rate) >= 0 && tonumber(var.delivery_status_success_sampling_rate) <= 100
    error_message = "delivery_status_success_sampling_rate must be a number between 0 and 100."
  }
}

variable "default_sender_id" {
  description = "Default sender ID for SMS messages. Leave null to keep it unset (required for US destinations, unsupported elsewhere)."
  type        = string
  default     = null
}

variable "monthly_spend_limit" {
  description = "Maximum amount (USD) the account may spend on SMS per calendar month. Leave null to keep the AWS default unset by this configuration."
  type        = number
  default     = null
}

variable "delivery_status_iam_role_arn" {
  description = "ARN of the IAM role that SNS assumes to write SMS delivery-status logs. Leave null when delivery-status logging is not enabled."
  type        = string
  default     = null
}

variable "usage_report_s3_bucket" {
  description = "S3 bucket that receives SNS SMS usage reports. Leave null to keep usage reporting disabled."
  type        = string
  default     = null
}

###############################################################################
# Account-level SNS SMS preferences
###############################################################################

resource "aws_sns_sms_preferences" "this" {
  default_sms_type                      = var.default_sms_type
  delivery_status_success_sampling_rate = var.delivery_status_success_sampling_rate

  # Optional attributes: left unset (null) by default so the provider omits
  # them from the SNS SetSMSAttributes call entirely.
  default_sender_id            = var.default_sender_id
  monthly_spend_limit          = var.monthly_spend_limit
  delivery_status_iam_role_arn = var.delivery_status_iam_role_arn
  usage_report_s3_bucket       = var.usage_report_s3_bucket
}

###############################################################################
# Outputs
###############################################################################

output "aws_region" {
  description = "Region in which the SNS SMS preferences are configured."
  value       = var.aws_region
}

output "default_sms_type" {
  description = "Configured default SMS message type."
  value       = aws_sns_sms_preferences.this.default_sms_type
}

output "delivery_status_success_sampling_rate" {
  description = "Configured success sampling rate for SMS delivery-status logging."
  value       = aws_sns_sms_preferences.this.delivery_status_success_sampling_rate
}

output "default_sender_id" {
  description = "Configured default sender ID (null when unset)."
  value       = aws_sns_sms_preferences.this.default_sender_id
}

output "monthly_spend_limit" {
  description = "Configured monthly SMS spend limit in USD (null when unset)."
  value       = aws_sns_sms_preferences.this.monthly_spend_limit
}

output "delivery_status_iam_role_arn" {
  description = "IAM role ARN used for SMS delivery-status logging (null when unset)."
  value       = aws_sns_sms_preferences.this.delivery_status_iam_role_arn
}

output "usage_report_s3_bucket" {
  description = "S3 bucket receiving SNS SMS usage reports (null when unset)."
  value       = aws_sns_sms_preferences.this.usage_report_s3_bucket
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to configure the provider."
  type        = string
  default     = "us-east-1"
}

variable "eks_role_name" {
  description = "Name of the IAM service role that Amazon EKS will assume."
  type        = string
  default     = "eks-cluster-sadcloud-example"
}

# Trust policy that allows the Amazon EKS service to assume the role.
data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    sid     = "EKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

# The IAM service role that Amazon EKS assumes.
resource "aws_iam_role" "eks_cluster" {
  name               = var.eks_role_name
  description        = "IAM service role assumed by the Amazon EKS service for cluster creation and management."
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json

  tags = {
    Name = var.eks_role_name
  }
}

# Attach the AWS-managed AmazonEKSClusterPolicy.
resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

# Attach the AWS-managed AmazonEKSServicePolicy.
resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

output "eks_cluster_role_arn" {
  description = "ARN of the IAM service role for the EKS cluster."
  value       = aws_iam_role.eks_cluster.arn
}

output "eks_cluster_role_name" {
  description = "Name of the IAM service role for the EKS cluster."
  value       = aws_iam_role.eks_cluster.name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      ManagedBy = "Terraform"
      Purpose   = "CloudWatchLogsDemo"
    }
  }
}

provider "random" {}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region in which to create the resources."
  type        = string
  default     = "us-east-1"
}

variable "log_group_prefix" {
  description = "Prefix used for the CloudWatch log group name."
  type        = string
  default     = "logs"
}

variable "retention_in_days" {
  description = "Number of days to retain log events in the log group."
  type        = number
  default     = 7

  validation {
    condition     = contains([1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653], var.retention_in_days)
    error_message = "retention_in_days must be one of the values supported by CloudWatch Logs."
  }
}

############################################
# Random pet-name suffix
############################################

resource "random_pet" "log_suffix" {
  length    = 2
  separator = "-"
}

############################################
# CloudWatch Log Group
############################################

resource "aws_cloudwatch_log_group" "app_logs" {
  name              = "${var.log_group_prefix}-${random_pet.log_suffix.id}"
  retention_in_days = var.retention_in_days
}

############################################
# IAM Policy limited to the created log group
############################################

data "aws_iam_policy_document" "log_write_policy" {
  statement {
    sid    = "AllowLogStreamWriteOnSpecificLogGroup"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.app_logs.arn,
      "${aws_cloudwatch_log_group.app_logs.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "log_write_policy" {
  name        = "${var.log_group_prefix}-${random_pet.log_suffix.id}-write-policy"
  description = "Allows creating log streams, describing log streams, and putting log events only on the ${aws_cloudwatch_log_group.app_logs.name} log group."
  policy      = data.aws_iam_policy_document.log_write_policy.json
}

############################################
# Outputs
############################################

output "log_group_name" {
  description = "Name of the generated CloudWatch log group."
  value       = aws_cloudwatch_log_group.app_logs.name
}

output "log_group_arn" {
  description = "ARN of the generated CloudWatch log group."
  value       = aws_cloudwatch_log_group.app_logs.arn
}

output "iam_policy_arn" {
  description = "ARN of the IAM policy granting write access to the log group."
  value       = aws_iam_policy.log_write_policy.arn
}

## Description

This Terraform configuration provisions the following:

**CloudWatch log group**
- `aws_cloudwatch_log_group.ssm_automation_script` — creates the log group `/aws/ssm/automation/executeScript` (name configurable via variable) with a retention of **14 days** and tags.

**Systems Manager service settings (account/region level)**
- `aws_ssm_service_setting.automation_script_log_enabled` — sets the service setting `.../servicesetting/ssm/automation/customer-script-log` to `Enabled`, so SSM Automation (customer script) output is written to CloudWatch Logs.
- `aws_ssm_service_setting.automation_script_log_group` — sets `.../servicesetting/ssm/automation/customer-script-log-group` to the name of the log group created above, so the automation output lands in that specific group (the group name is prefixed with `/aws/ssm`, which is the required format).
- `aws_ssm_service_setting.document_public_sharing_permission` — sets `.../servicesetting/ssm/documents/console/public-sharing-permission` to `Disable`, blocking public sharing of Systems Manager documents in the account/region.

**IAM**
- `aws_iam_role.ssm_automation_logging` — an automation role assumable by `ssm.amazonaws.com`.
- `aws_iam_role_policy.ssm_automation_logging` — least-privilege inline policy allowing only log-stream creation and log event writes into the created log group.

**Single control flag**
- `enable_ssm_automation_logging` (bool, **default `true`**) gates every resource through `count`, so the whole feature set can be turned off with one variable.

Region is supplied through the AWS provider (`var.aws_region`, default `us-east-1`); partition/account/region are read via data sources so the service-setting ARNs are always valid. Outputs expose the log group name/ARN and the IAM role ARN.

```iac_template
###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the log group and SSM service settings are configured."
  type        = string
  default     = "us-east-1"
}

variable "enable_ssm_automation_logging" {
  description = "Single flag that controls whether SSM Automation script output is logged to CloudWatch and whether public sharing of SSM documents is disabled. Defaults to on."
  type        = bool
  default     = true
}

variable "log_group_name" {
  description = "Name of the CloudWatch log group used for SSM Automation script output. Must start with /aws/ssm."
  type        = string
  default     = "/aws/ssm/automation/executeScript"
}

variable "log_retention_in_days" {
  description = "Retention period (in days) for the SSM automation script log group."
  type        = number
  default     = 14

  validation {
    condition     = contains([0, 1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653], var.log_retention_in_days)
    error_message = "log_retention_in_days must be one of the retention values supported by CloudWatch Logs."
  }
}

variable "tags" {
  description = "Additional tags applied to taggable resources created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  # All resources are gated by a single flag.
  create = var.enable_ssm_automation_logging

  # Base ARN used by SSM account-level service settings.
  ssm_service_setting_arn_prefix = "arn:${data.aws_partition.current.partition}:ssm:${var.aws_region}:${data.aws_caller_identity.current.account_id}:servicesetting"

  common_tags = merge(
    var.tags,
    {
      ManagedBy = "Terraform"
    }
  )
}

###############################################################################
# CloudWatch log group for SSM Automation script output
###############################################################################

resource "aws_cloudwatch_log_group" "ssm_automation_script" {
  count = local.create ? 1 : 0

  name              = var.log_group_name
  retention_in_days = var.log_retention_in_days

  tags = merge(
    local.common_tags,
    {
      Name = var.log_group_name
    }
  )
}

###############################################################################
# SSM service settings: enable automation logging, point it at the log group,
# and disable public sharing of SSM documents.
###############################################################################

# Enable CloudWatch Logs output for SSM Automation customer script execution.
resource "aws_ssm_service_setting" "automation_script_log_enabled" {
  count = local.create ? 1 : 0

  setting_id    = "${local.ssm_service_setting_arn_prefix}/ssm/automation/customer-script-log"
  setting_value = "Enabled"

  depends_on = [aws_cloudwatch_log_group.ssm_automation_script]
}

# Direct the automation script output to the log group created above.
resource "aws_ssm_service_setting" "automation_script_log_group" {
  count = local.create ? 1 : 0

  setting_id    = "${local.ssm_service_setting_arn_prefix}/ssm/automation/customer-script-log-group"
  setting_value = aws_cloudwatch_log_group.ssm_automation_script[0].name

  depends_on = [aws_cloudwatch_log_group.ssm_automation_script]
}

# Disable public (anonymous) sharing of Systems Manager documents in this account/region.
resource "aws_ssm_service_setting" "document_public_sharing_permission" {
  count = local.create ? 1 : 0

  setting_id    = "${local.ssm_service_setting_arn_prefix}/ssm/documents/console/public-sharing-permission"
  setting_value = "Disable"
}

###############################################################################
# IAM role used by SSM Automation to write script output to CloudWatch Logs
###############################################################################

data "aws_iam_policy_document" "ssm_automation_assume_role" {
  statement {
    sid     = "AllowSsmAutomationAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm_automation_logging" {
  count = local.create ? 1 : 0

  name                 = "ssm-automation-cloudwatch-logging-role"
  description          = "Role assumed by SSM Automation executions to write script output to CloudWatch Logs."
  assume_role_policy   = data.aws_iam_policy_document.ssm_automation_assume_role.json
  max_session_duration = 3600

  tags = merge(
    local.common_tags,
    {
      Name = "ssm-automation-cloudwatch-logging-role"
    }
  )
}

data "aws_iam_policy_document" "ssm_automation_logging" {
  count = local.create ? 1 : 0

  statement {
    sid    = "AllowAutomationScriptLogWrites"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.ssm_automation_script[0].arn,
      "${aws_cloudwatch_log_group.ssm_automation_script[0].arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "ssm_automation_logging" {
  count = local.create ? 1 : 0

  name   = "ssm-automation-cloudwatch-logging-policy"
  role   = aws_iam_role.ssm_automation_logging[0].id
  policy = data.aws_iam_policy_document.ssm_automation_logging[0].json
}

###############################################################################
# Outputs
###############################################################################

output "ssm_automation_log_group_name" {
  description = "Name of the CloudWatch log group that receives SSM Automation script output."
  value       = local.create ? aws_cloudwatch_log_group.ssm_automation_script[0].name : null
}

output "ssm_automation_log_group_arn" {
  description = "ARN of the CloudWatch log group that receives SSM Automation script output."
  value       = local.create ? aws_cloudwatch_log_group.ssm_automation_script[0].arn : null
}

output "ssm_automation_logging_role_arn" {
  description = "ARN of the IAM role that SSM Automation executions can assume to write logs."
  value       = local.create ? aws_iam_role.ssm_automation_logging[0].arn : null
}

output "ssm_service_settings_configured" {
  description = "SSM service settings managed by this configuration."
  value = local.create ? {
    automation_script_log          = aws_ssm_service_setting.automation_script_log_enabled[0].setting_id
    automation_script_log_group    = aws_ssm_service_setting.automation_script_log_group[0].setting_id
    document_public_sharing        = aws_ssm_service_setting.document_public_sharing_permission[0].setting_id
    automation_script_log_enabled  = true
    document_public_sharing_allowed = false
  } : null
}
```

###############################################################################
# Provider / Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the DynamoDB backup IAM roles and policies are created."
  type        = string
  default     = "us-east-1"
}

variable "project" {
  description = "Project name used for tagging the created IAM resources."
  type        = string
  default     = "dynamodb-backup-automation"
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "prod"
}

###############################################################################
# Data sources / locals
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  dynamodb_table_arn  = "arn:${local.partition}:dynamodb:${var.aws_region}:${local.account_id}:table/*"
  dynamodb_backup_arn = "arn:${local.partition}:dynamodb:${var.aws_region}:${local.account_id}:table/*/backup/*"

  lambda_log_group_arn       = "arn:${local.partition}:logs:${var.aws_region}:${local.account_id}:log-group:/aws/lambda/*"
  lambda_log_group_stream_arn = "arn:${local.partition}:logs:${var.aws_region}:${local.account_id}:log-group:/aws/lambda/*:*"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Assume-role policy documents (trust policies)
###############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

###############################################################################
# Customer managed policy: lambda_logging (shared by both roles)
###############################################################################

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    sid    = "CloudWatchLogsWriteAccess"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      local.lambda_log_group_arn,
      local.lambda_log_group_stream_arn,
    ]
  }
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Shared CloudWatch Logs write permissions for the DynamoDB backup Lambda functions."
  policy      = data.aws_iam_policy_document.lambda_logging.json

  tags = local.common_tags
}

###############################################################################
# Policy: create_ddb_backup_policy (create DynamoDB backups)
###############################################################################

data "aws_iam_policy_document" "create_ddb_backup" {
  statement {
    sid    = "ListDynamoDbTables"
    effect = "Allow"

    actions = [
      "dynamodb:ListTables",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DescribeTablesAndCreateBackup"
    effect = "Allow"

    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:CreateBackup",
    ]

    resources = [
      local.dynamodb_table_arn,
      local.dynamodb_backup_arn,
    ]
  }
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Allows the backup Lambda function to enumerate DynamoDB tables and create on-demand backups."
  policy      = data.aws_iam_policy_document.create_ddb_backup.json

  tags = local.common_tags
}

###############################################################################
# Policy: remove_ddb_backup_policy (list + delete DynamoDB backups)
###############################################################################

data "aws_iam_policy_document" "remove_ddb_backup" {
  statement {
    sid    = "ListDynamoDbBackups"
    effect = "Allow"

    actions = [
      "dynamodb:ListBackups",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DescribeAndDeleteBackups"
    effect = "Allow"

    actions = [
      "dynamodb:DescribeBackup",
      "dynamodb:DeleteBackup",
    ]

    resources = [
      local.dynamodb_backup_arn,
    ]
  }
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Allows the cleanup Lambda function to list, inspect and delete DynamoDB on-demand backups."
  policy      = data.aws_iam_policy_document.remove_ddb_backup.json

  tags = local.common_tags
}

###############################################################################
# IAM role: create_ddb_backup_role
###############################################################################

resource "aws_iam_role" "create_ddb_backup_role" {
  name                 = "create_ddb_backup_role"
  description          = "Execution role for the Lambda function that creates DynamoDB on-demand backups."
  assume_role_policy   = data.aws_iam_policy_document.lambda_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_dynamodb" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

###############################################################################
# IAM role: remove_ddb_backup_role
###############################################################################

resource "aws_iam_role" "remove_ddb_backup_role" {
  name                 = "remove_ddb_backup_role"
  description          = "Execution role for the Lambda function that lists and deletes stale DynamoDB backups."
  assume_role_policy   = data.aws_iam_policy_document.lambda_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_dynamodb" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

###############################################################################
# Outputs
###############################################################################

output "create_ddb_backup_role" {
  description = "Name and ARN of the IAM role used by the DynamoDB backup-creation Lambda function."
  value = {
    name = aws_iam_role.create_ddb_backup_role.name
    arn  = aws_iam_role.create_ddb_backup_role.arn
  }
}

output "remove_ddb_backup_role" {
  description = "Name and ARN of the IAM role used by the DynamoDB backup-removal Lambda function."
  value = {
    name = aws_iam_role.remove_ddb_backup_role.name
    arn  = aws_iam_role.remove_ddb_backup_role.arn
  }
}

output "lambda_logging_policy_arn" {
  description = "ARN of the customer-managed CloudWatch Logs policy shared by both Lambda execution roles."
  value       = aws_iam_policy.lambda_logging.arn
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_group" "admin" {
  name = "admin"
}

resource "aws_iam_group" "admin_read_only" {
  name = "admin_read_only"
}

resource "aws_iam_group" "developer_group" {
  name = "developer_group"
}

resource "aws_iam_group_policy_attachment" "admin_administrator_access" {
  group      = aws_iam_group.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "admin_read_only_readonly" {
  group      = aws_iam_group.admin_read_only.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_s3_full_access" {
  group      = aws_iam_group.developer_group.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer_group.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_membership" "admin_team" {
  name  = "admin_team"
  group = aws_iam_group.admin.name
  users = []
}

resource "aws_iam_group_membership" "read_only_admin_team" {
  name  = "read_only_admin_team"
  group = aws_iam_group.admin_read_only.name
  users = []
}

resource "aws_iam_group_membership" "developers" {
  name  = "developers"
  group = aws_iam_group.developer_group.name
  users = []
}

output "admin_group_arn" {
  value = aws_iam_group.admin.arn
}

output "admin_read_only_group_arn" {
  value = aws_iam_group.admin_read_only.arn
}

output "developer_group_arn" {
  value = aws_iam_group.developer_group.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to create the IAM OIDC provider and roles."
  type        = string
  default     = "us-east-1"
}

variable "oidc_provider_url" {
  description = "OIDC issuer URL for GitHub Actions. Stored without a trailing slash, exactly as AWS expects."
  type        = string
  default     = "https://token.actions.githubusercontent.com"

  validation {
    condition     = !endswith(var.oidc_provider_url, "/")
    error_message = "The OIDC provider URL must not end with a trailing slash."
  }
}

variable "oidc_audience" {
  description = "Audience(s) allowed in the client_id_list of the OIDC provider."
  type        = list(string)
  default     = ["sts.amazonaws.com"]
}

variable "github_published_thumbprints" {
  description = "GitHub's two published (stable) root CA thumbprints, used in addition to the CA fingerprints fetched live from the issuer's TLS certificate."
  type        = list(string)
  default = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "github_federated_roles" {
  description = <<-EOT
    Optional map of GitHub-federated IAM roles to create. Empty by default (no roles are created).

    Key   -> IAM role name.
    Value -> object({
      description          = optional(string)                 # Role description
      subject_claims       = list(string)                     # Required, e.g. ["repo:org/repo:ref:refs/heads/main"]
      policy_arns          = optional(list(string), [])       # Managed policy ARNs to attach
      inline_policies      = optional(map(string), {})        # name => JSON policy document
      max_session_duration = optional(number, 3600)           # 3600..43200 seconds
      tags                 = optional(map(string), {})        # Extra tags for this role
    })
  EOT
  type = map(object({
    description          = optional(string, "")
    subject_claims       = list(string)
    policy_arns          = optional(list(string), [])
    inline_policies      = optional(map(string), {})
    max_session_duration = optional(number, 3600)
    tags                 = optional(map(string), {})
  }))
  default = {}

  validation {
    condition = alltrue([
      for cfg in values(var.github_federated_roles) : length(cfg.subject_claims) > 0
    ])
    error_message = "Each GitHub federated role must define at least one subject claim (token.actions.githubusercontent.com:sub)."
  }

  validation {
    condition = alltrue([
      for cfg in values(var.github_federated_roles) :
      cfg.max_session_duration >= 3600 && cfg.max_session_duration <= 43200
    ])
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }
}

###############################################################################
# Discover the issuer's current CA thumbprints from its TLS certificate chain
###############################################################################

data "tls_certificate" "github_oidc" {
  url = var.oidc_provider_url
}

locals {
  # Fingerprints of every certificate in the chain that is a Certificate Authority.
  issuer_ca_thumbprints = [
    for cert in data.tls_certificate.github_oidc.certificates :
    cert.sha1_fingerprint if cert.is_ca
  ]

  # Union of the live CA fingerprints and GitHub's published thumbprints.
  oidc_thumbprint_list = distinct(concat(
    local.issuer_ca_thumbprints,
    var.github_published_thumbprints,
  ))
}

###############################################################################
# IAM OpenID Connect identity provider for GitHub Actions
###############################################################################

resource "aws_iam_openid_connect_provider" "github" {
  url             = var.oidc_provider_url
  client_id_list  = var.oidc_audience
  thumbprint_list = local.oidc_thumbprint_list

  tags = merge(var.tags, {
    Name    = "github-actions-oidc"
    Service = "github-actions"
  })
}

###############################################################################
# Optional GitHub-federated IAM roles (none created by default)
###############################################################################

data "aws_iam_policy_document" "github_assume_role" {
  for_each = var.github_federated_roles

  statement {
    sid     = "AllowGitHubActionsWebIdentity"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = var.oidc_audience
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = each.value.subject_claims
    }
  }
}

resource "aws_iam_role" "github" {
  for_each = var.github_federated_roles

  name                 = each.key
  description          = each.value.description
  assume_role_policy   = data.aws_iam_policy_document.github_assume_role[each.key].json
  max_session_duration = each.value.max_session_duration

  tags = merge(var.tags, each.value.tags, {
    Name    = each.key
    Service = "github-actions"
  })
}

locals {
  # Flatten the optional managed-policy attachments into a stable-keyed map.
  github_managed_attachments = {
    for pair in flatten([
      for role_name, cfg in var.github_federated_roles : [
        for arn in cfg.policy_arns : {
          key    = "${role_name}::${arn}"
          role   = role_name
          policy = arn
        }
      ]
    ]) : pair.key => pair
  }

  # Flatten the optional inline policies into a stable-keyed map.
  github_inline_policies = {
    for pair in flatten([
      for role_name, cfg in var.github_federated_roles : [
        for policy_name, policy_json in cfg.inline_policies : {
          key    = "${role_name}::${policy_name}"
          role   = role_name
          name   = policy_name
          policy = policy_json
        }
      ]
    ]) : pair.key => pair
  }
}

resource "aws_iam_role_policy_attachment" "github" {
  for_each = local.github_managed_attachments

  role       = aws_iam_role.github[each.value.role].name
  policy_arn = each.value.policy
}

resource "aws_iam_role_policy" "github" {
  for_each = local.github_inline_policies

  name   = each.value.name
  role   = aws_iam_role.github[each.value.role].id
  policy = each.value.policy
}

###############################################################################
# Outputs
###############################################################################

output "oidc_provider_arn" {
  description = "ARN of the GitHub Actions IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

output "oidc_provider_url" {
  description = "Issuer URL of the GitHub Actions IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.url
}

output "oidc_thumbprint_list" {
  description = "Resolved thumbprint list on the OIDC provider (live CA fingerprints + GitHub's published thumbprints)."
  value       = aws_iam_openid_connect_provider.github.thumbprint_list
}

output "issuer_ca_thumbprints" {
  description = "CA SHA-1 fingerprints discovered from the issuer's TLS certificate chain."
  value       = local.issuer_ca_thumbprints
}

output "github_role_arns" {
  description = "Map of created GitHub-federated role name => ARN. Empty when no roles are requested."
  value       = { for name, role in aws_iam_role.github : name => role.arn }
}

output "github_role_names" {
  description = "Names of the created GitHub-federated roles. Empty when no roles are requested."
  value       = sort(keys(aws_iam_role.github))
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "projectvpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "projectvpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.projectvpc.id

  tags = {
    Name = "projectvpc-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.projectvpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "projectvpc-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.projectvpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "projectvpc-private-subnet"
  }
}

resource "aws_eip" "nat_eip" {
  domain = "vpc"

  tags = {
    Name = "projectvpc-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat_eip.id
  subnet_id     = aws_subnet.public.id

  depends_on = [
    aws_internet_gateway.igw,
    aws_route_table_association.public
  ]

  tags = {
    Name = "projectvpc-nat-gateway"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "projectvpc-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "projectvpc-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.projectvpc.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway"
  value       = aws_nat_gateway.nat.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_cidrs  = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]
  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24", "10.0.13.0/24"]
}

resource "aws_vpc" "demo_vpc" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "demo-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.demo_vpc.id
  cidr_block              = element(local.public_subnet_cidrs, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index + 1]
  map_public_ip_on_launch = true

  tags = {
    Name = "demo-vpc-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.demo_vpc.id
  cidr_block        = element(local.private_subnet_cidrs, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = {
    Name = "demo-vpc-private-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "demo_igw" {
  vpc_id = aws_vpc.demo_vpc.id

  tags = {
    Name = "demo-vpc-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.demo_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.demo_igw.id
  }

  tags = {
    Name = "demo-vpc-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "demo-vpc-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "demo-vpc-nat-gw"
  }

  depends_on = [aws_internet_gateway.demo_igw]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.demo_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "demo-vpc-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

############################################
# Variables
############################################

variable "aws_region" {
  description = "AWS region in which to create the VPCs and peering connection"
  type        = string
  default     = "us-east-1"
}

variable "dev_vpc_cidr" {
  description = "CIDR block for the dev VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "test_vpc_cidr" {
  description = "CIDR block for the test VPC"
  type        = string
  default     = "172.24.0.0/16"
}

variable "subnet_new_bits" {
  description = "Number of additional network bits used to carve /24 subnets out of the /16 VPC CIDRs"
  type        = number
  default     = 8
}

variable "public_subnet_offsets" {
  description = "Subnet offsets used to build the two public /24 subnets in each VPC"
  type        = list(number)
  default     = [101, 102]
}

variable "private_subnet_offsets" {
  description = "Subnet offsets used to build the two private /24 subnets in each VPC"
  type        = list(number)
  default     = [1, 2]
}

variable "az_count" {
  description = "Number of availability zones to span in each VPC (first two available AZs)"
  type        = number
  default     = 2
}

############################################
# Data & Locals
############################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  common_tags = {
    ManagedBy = "terraform"
  }
}

############################################
# VPCs
############################################

resource "aws_vpc" "dev" {
  cidr_block           = var.dev_vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "dev"
  })
}

resource "aws_vpc" "test" {
  cidr_block           = var.test_vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "test"
  })
}

############################################
# Internet Gateways
############################################

resource "aws_internet_gateway" "dev" {
  vpc_id = aws_vpc.dev.id

  tags = merge(local.common_tags, {
    Name = "dev-igw"
  })
}

resource "aws_internet_gateway" "test" {
  vpc_id = aws_vpc.test.id

  tags = merge(local.common_tags, {
    Name = "test-igw"
  })
}

############################################
# Dev Subnets
############################################

resource "aws_subnet" "dev_public" {
  count = length(var.public_subnet_offsets)

  vpc_id                  = aws_vpc.dev.id
  cidr_block              = cidrsubnet(aws_vpc.dev.cidr_block, var.subnet_new_bits, var.public_subnet_offsets[count.index])
  availability_zone       = local.azs[count.index % length(local.azs)]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "dev-public-${var.public_subnet_offsets[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "dev_private" {
  count = length(var.private_subnet_offsets)

  vpc_id            = aws_vpc.dev.id
  cidr_block        = cidrsubnet(aws_vpc.dev.cidr_block, var.subnet_new_bits, var.private_subnet_offsets[count.index])
  availability_zone = local.azs[count.index % length(local.azs)]

  tags = merge(local.common_tags, {
    Name = "dev-private-${var.private_subnet_offsets[count.index]}"
    Tier = "private"
  })
}

############################################
# Test Subnets
############################################

resource "aws_subnet" "test_public" {
  count = length(var.public_subnet_offsets)

  vpc_id                  = aws_vpc.test.id
  cidr_block              = cidrsubnet(aws_vpc.test.cidr_block, var.subnet_new_bits, var.public_subnet_offsets[count.index])
  availability_zone       = local.azs[count.index % length(local.azs)]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "test-public-${var.public_subnet_offsets[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "test_private" {
  count = length(var.private_subnet_offsets)

  vpc_id            = aws_vpc.test.id
  cidr_block        = cidrsubnet(aws_vpc.test.cidr_block, var.subnet_new_bits, var.private_subnet_offsets[count.index])
  availability_zone = local.azs[count.index % length(local.azs)]

  tags = merge(local.common_tags, {
    Name = "test-private-${var.private_subnet_offsets[count.index]}"
    Tier = "private"
  })
}

############################################
# Dev Route Tables and Routes
############################################

resource "aws_route_table" "dev_public" {
  vpc_id = aws_vpc.dev.id

  tags = merge(local.common_tags, {
    Name = "dev-public-rt"
  })
}

resource "aws_route_table" "dev_private" {
  vpc_id = aws_vpc.dev.id

  tags = merge(local.common_tags, {
    Name = "dev-private-rt"
  })
}

resource "aws_route" "dev_public_internet" {
  route_table_id         = aws_route_table.dev_public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.dev.id
}

resource "aws_route" "dev_public_peer" {
  route_table_id            = aws_route_table.dev_public.id
  destination_cidr_block    = aws_vpc.test.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "dev_private_peer" {
  route_table_id            = aws_route_table.dev_private.id
  destination_cidr_block    = aws_vpc.test.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route_table_association" "dev_public" {
  count = length(aws_subnet.dev_public)

  subnet_id      = aws_subnet.dev_public[count.index].id
  route_table_id = aws_route_table.dev_public.id
}

resource "aws_route_table_association" "dev_private" {
  count = length(aws_subnet.dev_private)

  subnet_id      = aws_subnet.dev_private[count.index].id
  route_table_id = aws_route_table.dev_private.id
}

############################################
# Test Route Tables and Routes
############################################

resource "aws_route_table" "test_public" {
  vpc_id = aws_vpc.test.id

  tags = merge(local.common_tags, {
    Name = "test-public-rt"
  })
}

resource "aws_route_table" "test_private" {
  vpc_id = aws_vpc.test.id

  tags = merge(local.common_tags, {
    Name = "test-private-rt"
  })
}

resource "aws_route" "test_public_internet" {
  route_table_id         = aws_route_table.test_public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.test.id
}

resource "aws_route" "test_public_peer" {
  route_table_id            = aws_route_table.test_public.id
  destination_cidr_block    = aws_vpc.dev.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "test_private_peer" {
  route_table_id            = aws_route_table.test_private.id
  destination_cidr_block    = aws_vpc.dev.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route_table_association" "test_public" {
  count = length(aws_subnet.test_public)

  subnet_id      = aws_subnet.test_public[count.index].id
  route_table_id = aws_route_table.test_public.id
}

resource "aws_route_table_association" "test_private" {
  count = length(aws_subnet.test_private)

  subnet_id      = aws_subnet.test_private[count.index].id
  route_table_id = aws_route_table.test_private.id
}

############################################
# VPC Peering Connection (auto-accepted)
############################################

resource "aws_vpc_peering_connection" "dev_test" {
  vpc_id      = aws_vpc.dev.id
  peer_vpc_id = aws_vpc.test.id
  auto_accept = true

  requester {
    allow_remote_vpc_dns_resolution = true
  }

  accepter {
    allow_remote_vpc_dns_resolution = true
  }

  tags = merge(local.common_tags, {
    Name = "dev-test-vpc-peer"
  })
}

############################################
# Outputs
############################################

output "dev_vpc_id" {
  description = "ID of the dev VPC"
  value       = aws_vpc.dev.id
}

output "test_vpc_id" {
  description = "ID of the test VPC"
  value       = aws_vpc.test.id
}

output "dev_public_subnet_ids" {
  description = "IDs of the dev public subnets"
  value       = aws_subnet.dev_public[*].id
}

output "dev_private_subnet_ids" {
  description = "IDs of the dev private subnets"
  value       = aws_subnet.dev_private[*].id
}

output "test_public_subnet_ids" {
  description = "IDs of the test public subnets"
  value       = aws_subnet.test_public[*].id
}

output "test_private_subnet_ids" {
  description = "IDs of the test private subnets"
  value       = aws_subnet.test_private[*].id
}

output "vpc_peering_connection_id" {
  description = "ID of the auto-accepted dev-test VPC peering connection"
  value       = aws_vpc_peering_connection.dev_test.id
}

output "vpc_peering_connection_status" {
  description = "Acceptance status of the dev-test VPC peering connection"
  value       = aws_vpc_peering_connection.dev_test.accept_status
}

output "availability_zones_used" {
  description = "Availability zones spanned by the VPC subnets"
  value       = local.azs
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Trust policy: allow EC2 service to assume the test roles
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

###############################################################################
# IAM roles
###############################################################################

resource "aws_iam_role" "test_role" {
  name               = "test-role"
  description        = "Test role assumable by EC2"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name        = "test-role"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role" "test_role2" {
  name               = "test-role2"
  description        = "Second test role assumable by EC2"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name        = "test-role2"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Customer managed policies: EC2 describe-only
###############################################################################

data "aws_iam_policy_document" "ec2_describe_only" {
  statement {
    sid       = "AllowEc2DescribeOnly"
    effect    = "Allow"
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "test_policy" {
  name        = "test-policy"
  description = "Test policy allowing only EC2 describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe_only.json

  tags = {
    Name        = "test-policy"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_policy" "test_policy2" {
  name        = "test-policy2"
  description = "Test policy 2 allowing only EC2 describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe_only.json

  tags = {
    Name        = "test-policy2"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_policy" "test_policy3" {
  name        = "test-policy3"
  description = "Test policy 3 allowing only EC2 describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe_only.json

  tags = {
    Name        = "test-policy3"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Individual attachments: test-policy and test-policy2 to each role
###############################################################################

resource "aws_iam_role_policy_attachment" "test_role_test_policy" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy.arn
}

resource "aws_iam_role_policy_attachment" "test_role_test_policy2" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

resource "aws_iam_role_policy_attachment" "test_role2_test_policy" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy.arn
}

resource "aws_iam_role_policy_attachment" "test_role2_test_policy2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

###############################################################################
# Single named policy attachment: test-policy3 -> both roles
###############################################################################

resource "aws_iam_policy_attachment" "test_attachment5" {
  name       = "test-attachment5"
  policy_arn = aws_iam_policy.test_policy3.arn
  roles      = [aws_iam_role.test_role.name, aws_iam_role.test_role2.name]
}

###############################################################################
# Outputs
###############################################################################

output "role_names" {
  description = "Names of the created IAM roles"
  value = [
    aws_iam_role.test_role.name,
    aws_iam_role.test_role2.name
  ]
}

output "role_arns" {
  description = "ARNs of the created IAM roles"
  value = [
    aws_iam_role.test_role.arn,
    aws_iam_role.test_role2.arn
  ]
}

output "policy_arns" {
  description = "ARNs of the created customer managed policies"
  value = {
    test_policy  = aws_iam_policy.test_policy.arn
    test_policy2 = aws_iam_policy.test_policy2.arn
    test_policy3 = aws_iam_policy.test_policy3.arn
  }
}

output "test_attachment5_id" {
  description = "ID of the single named policy attachment for test-policy3"
  value       = aws_iam_policy_attachment.test_attachment5.id
}

## Description of the Terraform configuration

This configuration creates everything GitHub Actions needs in order to assume an AWS IAM role without long‑lived credentials, using OIDC web‑identity federation:

* **Provider / backend** – Standard AWS provider pinned to `~> 5.0`, with a configurable region (default `us-east-1`) and a minimum Terraform version of `1.3.0` (needed for `try()`/`one()` semantics used in the module).
* **OIDC identity provider** – A toggle (`create_github_oidc_provider`, default `false`) either **looks up** the existing `token.actions.githubusercontent.com` provider in the current account via the `aws_iam_openid_connect_provider` data source, or **creates** it with the standard GitHub thumbprints and `sts.amazonaws.com` client id when the account does not have one yet.
* **Trust policy** – An `aws_iam_policy_document` containing a federated principal referencing the GitHub OIDC provider, with:
  * `StringEquals` on `token.actions.githubusercontent.com:aud` = `sts.amazonaws.com`
  * `StringEquals` on `token.actions.githubusercontent.com:iss` = `https://token.actions.githubusercontent.com`
  * a dynamically generated `StringLike` condition on `token.actions.githubusercontent.com:sub` whose values come from `var.repository_patterns` (e.g. `repo:my-org/my-repo:*`). The list is **empty by default**, in which case the subject condition is omitted from the policy (a warning about this is documented on the variable).
* **IAM role** – `aws_iam_role` named via `var.role_name`, path fixed to `/`, configurable `max_session_duration`, optional permissions boundary, `force_detach_policies = true` (policies are detached on destroy) and tags.
* **Managed policies** – `aws_iam_role_policy_attachment` instances driven by `var.managed_policy_arns`, which is an **empty list by default**, so no managed policy is attached unless requested.
* **Outputs** – the role ARN, name, path, and unique ID, plus the resolved OIDC provider ARN.

All variables have default values, so the configuration applies without any `.tfvars` file (assuming the GitHub OIDC provider already exists in the target account; set `create_github_oidc_provider = true` for a brand‑new account).

```iac_template
###############################################################################
# Terraform and AWS provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Locals
###############################################################################

locals {
  # The role must live in the root path.
  role_path = "/"

  github_oidc_host     = "token.actions.githubusercontent.com"
  github_oidc_url      = "https://token.actions.githubusercontent.com"
  github_oidc_issuer   = "https://token.actions.githubusercontent.com"
  github_oidc_audience = "sts.amazonaws.com"
}

###############################################################################
# GitHub OIDC identity provider (existing, or created when requested)
###############################################################################

# Created only when the account does not already have the GitHub OIDC provider.
resource "aws_iam_openid_connect_provider" "github" {
  count = var.create_github_oidc_provider ? 1 : 0

  url             = local.github_oidc_url
  client_id_list  = [local.github_oidc_audience]
  thumbprint_list = var.github_oidc_thumbprints

  tags = var.tags
}

# Used when the provider already exists in the current account.
data "aws_iam_openid_connect_provider" "github" {
  count = var.create_github_oidc_provider ? 0 : 1

  url = local.github_oidc_url
}

locals {
  # Resolves to the ARN of whichever of the two objects above is active.
  github_oidc_provider_arn = try(
    aws_iam_openid_connect_provider.github[0].arn,
    data.aws_iam_openid_connect_provider.github[0].arn,
  )
}

###############################################################################
# Assume-role (trust) policy
###############################################################################

data "aws_iam_policy_document" "github_actions_assume_role" {
  statement {
    sid     = "AllowGitHubActionsOIDCWebIdentity"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity", "sts:TagSession"]

    principals {
      type        = "Federated"
      identifiers = [local.github_oidc_provider_arn]
    }

    # Audience condition: the token must have been issued for STS.
    condition {
      test     = "StringEquals"
      variable = "${local.github_oidc_host}:aud"
      values   = [local.github_oidc_audience]
    }

    # Issuer condition: the token must come from GitHub's OIDC issuer.
    condition {
      test     = "StringEquals"
      variable = "${local.github_oidc_host}:iss"
      values   = [local.github_oidc_issuer]
    }

    # Subject condition: only added when repository patterns are supplied.
    dynamic "condition" {
      for_each = length(var.repository_patterns) > 0 ? [1] : []

      content {
        test     = "StringLike"
        variable = "${local.github_oidc_host}:sub"
        values   = var.repository_patterns
      }
    }
  }
}

###############################################################################
# GitHub Actions IAM role
###############################################################################

resource "aws_iam_role" "github_actions" {
  name                  = var.role_name
  description           = var.role_description
  path                  = local.role_path
  max_session_duration  = var.max_session_duration
  assume_role_policy    = data.aws_iam_policy_document.github_actions_assume_role.json
  force_detach_policies = true
  permissions_boundary  = var.permissions_boundary

  tags = var.tags
}

###############################################################################
# Optional managed policy attachments (none by default)
###############################################################################

resource "aws_iam_role_policy_attachment" "managed" {
  count = length(var.managed_policy_arns)

  role       = aws_iam_role.github_actions.name
  policy_arn = var.managed_policy_arns[count.index]
}

###############################################################################
# Outputs
###############################################################################

output "role_arn" {
  description = "ARN of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.arn
}

output "role_name" {
  description = "Name of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.name
}

output "role_path" {
  description = "Path of the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.path
}

output "role_unique_id" {
  description = "Stable and unique string identifying the GitHub Actions IAM role."
  value       = aws_iam_role.github_actions.unique_id
}

output "github_oidc_provider_arn" {
  description = "ARN of the GitHub OIDC identity provider trusted by the role."
  value       = local.github_oidc_provider_arn
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the AWS provider operates (IAM is global, but a region is required)."
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role that GitHub Actions will assume."
  type        = string
  default     = "github-actions-oidc-role"
}

variable "role_description" {
  description = "Description of the IAM role that GitHub Actions will assume."
  type        = string
  default     = "IAM role assumed by GitHub Actions through OpenID Connect web identity federation"
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role, between 3600 and 43200."
  type        = number
  default     = 3600
}

variable "permissions_boundary" {
  description = "Optional ARN of a permissions boundary policy to attach to the role."
  type        = string
  default     = null
}

variable "managed_policy_arns" {
  description = "List of managed policy ARNs to attach to the role. Empty by default, so no managed policies are attached."
  type        = list(string)
  default     = []
}

variable "repository_patterns" {
  description = <<-EOT
    List of GitHub repository subject patterns allowed to assume the role, matched against the
    'token.actions.githubusercontent.com:sub' claim with StringLike (for example
    "repo:my-org/my-repo:*" or "repo:my-org/*:*"). Empty by default, in which case no subject
    condition is emitted and any GitHub repository issuing a token from the trusted issuer and
    audience can assume the role. Populate this list in production environments.
  EOT
  type        = list(string)
  default     = []
}

variable "create_github_oidc_provider" {
  description = "When true, creates the GitHub OIDC identity provider in the current account. When false (default), the existing provider is looked up instead."
  type        = bool
  default     = false
}

variable "github_oidc_thumbprints" {
  description = "Thumbprints used when creating the GitHub OIDC identity provider."
  type        = list(string)
  default = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]
}

variable "tags" {
  description = "Map of tags applied to the created resources."
  type        = map(string)
  default     = {}
}
```

## Terraform Program Description

This template provisions a **customer-managed IAM policy** named `managed-force-mfa-policy` rooted at the `/` path. It is designed to be attached to IAM users who must be nudged into using MFA, and it contains the following logic:

1. **`AllowViewAccountInfo`** – Read-only access to account-level context (`GetAccountPasswordPolicy`, `GetAccountSummary`, `ListVirtualMFADevices`) so users can understand password rules and see their own MFA inventory.
2. **`AllowManageOwnPasswords`** – Lets the caller change their own password and read their own user record (`arn:aws:iam::*:user/${aws:username}`).
3. **`AllowManageOwnVirtualMFADevice`** – Lets the caller create/delete their own virtual MFA device (`arn:aws:iam::*:mfa/${aws:username}`) — necessary to bootstrap MFA.
4. **`AllowManageOwnUserMFA`** – Enables MFA, lists MFA devices, and resyncs the device token without an MFA condition (you can't require MFA to *enable* MFA).
5. **`AllowDeactivateOwnMFAOnlyWithMFA`** – Permits `DeactivateMFADevice` **only** when `aws:MultiFactorAuthPresent` is `true`, preventing MFA removal from a non-MFA session.
6. **`AllowSelfInspectionOnlyWithMFA`** – Grants broader self-inspection (access keys, signing certs, SSH keys, service-specific credentials, tags, groups, attached policies, etc.) **only** when MFA is present.

Because the provider/region and policy name/path are parameterized with sensible defaults, the configuration deploys out-of-the-box. No IAM role is required for this deliverable (only a standalone managed policy is requested), so none is created; the policy ARN is exposed as an output for attachment elsewhere.

```iac_template
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

############################################
# Provider
############################################
provider "aws" {
  region = var.aws_region
}

############################################
# Variables (with defaults so it deploys as-is)
############################################
variable "aws_region" {
  description = "AWS region in which the provider will operate."
  type        = string
  default     = "us-east-1"
}

variable "policy_name" {
  description = "Name of the customer-managed IAM policy."
  type        = string
  default     = "managed-force-mfa-policy"
}

variable "policy_path" {
  description = "IAM path under which the policy is created."
  type        = string
  default     = "/"
}

variable "tags" {
  description = "Tags applied to created resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Purpose   = "ForceMFA"
  }
}

############################################
# Customer-managed IAM policy: managed-force-mfa-policy
############################################
resource "aws_iam_policy" "managed_force_mfa" {
  name        = var.policy_name
  path        = var.policy_path
  description = "Allows IAM users to view basic account information and manage their own password and virtual MFA device; MFA deactivation and broader self-inspection are allowed only when signed in with MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # 1. Basic account information (no MFA required)
      {
        Sid    = "AllowViewAccountInfo"
        Effect = "Allow"
        Action = [
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary",
          "iam:ListVirtualMFADevices"
        ]
        Resource = "*"
      },

      # 2. Manage own password (no MFA required)
      {
        Sid    = "AllowManageOwnPasswords"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },

      # 3. Manage own virtual MFA device (needed to bootstrapping MFA)
      {
        Sid    = "AllowManageOwnVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "arn:aws:iam::*:mfa/$${aws:username}"
      },

      # 4. Enable / list / resync own MFA device (no MFA required, otherwise can't enable MFA)
      {
        Sid    = "AllowManageOwnUserMFA"
        Effect = "Allow"
        Action = [
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },

      # 5. Deactivate own MFA device — ONLY when signed in with MFA
      {
        Sid      = "AllowDeactivateOwnMFAOnlyWithMFA"
        Effect   = "Allow"
        Action   = "iam:DeactivateMFADevice"
        Resource = "arn:aws:iam::*:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },

      # 6. Broader self-inspection — ONLY when signed in with MFA
      {
        Sid    = "AllowSelfInspectionOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "iam:ListAccessKeys",
          "iam:GetAccessKeyLastUsed",
          "iam:ListSigningCertificates",
          "iam:ListSSHPublicKeys",
          "iam:GetSSHPublicKey",
          "iam:ListServiceSpecificCredentials",
          "iam:ListUserTags",
          "iam:GetUserPolicy",
          "iam:ListUserPolicies",
          "iam:ListGroupsForUser",
          "iam:ListAttachedUserPolicies"
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })

  tags = var.tags
}

############################################
# Outputs
############################################
output "managed_force_mfa_policy_arn" {
  description = "ARN of the created customer-managed IAM policy."
  value       = aws_iam_policy.managed_force_mfa.arn
}

output "managed_force_mfa_policy_name" {
  description = "Name of the created customer-managed IAM policy."
  value       = aws_iam_policy.managed_force_mfa.name
}
```

## Description of the Terraform program

This Terraform configuration provisions a small, team-based AWS IAM access structure using the `aws` provider (region `us-east-1`) and the `random` provider.

**What gets created:**

1. **Three IAM groups** — `BillingGroup`, `AdminGroup`, and `SuportGroup`.
2. **Three IAM users** — `Billing`, `Admin`, and `Suport`, each placed into its matching group via `aws_iam_user_group_membership`.
3. **Console login profiles** — one `aws_iam_user_login_profile` per user, whose password comes from a `random_password` resource constrained to exactly 8 characters and guaranteed to contain at least one uppercase, lowercase, numeric, and special character.
4. **Policies:**
   - `BillingPolicy` (customer-managed `aws_iam_policy`) granting read-only visibility into billing, usage, AWS Budgets, Cost Explorer / cost reports (CUR), and the Pricing API; attached to `BillingGroup`.
   - `AdministratorAccess` (AWS-managed) attached to `AdminGroup`.
   - `SuportPolicy` (customer-managed `aws_iam_policy`) granting read-only `Describe*`, `Get*`, and `List*` actions for EC2, S3, CloudWatch, and RDS; attached to `SuportGroup`.
5. **Sensitive outputs** — each username is exposed alongside its generated console password (marked `sensitive = true`).

All values are self-contained: no input variables are required, the region is hard-coded, and every resource referenced is declared in the template.

```iac_template
###############################################################################
# Provider / Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Generated passwords (8 characters, with mixed complexity)
###############################################################################

resource "random_password" "billing_password" {
  length           = 8
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "random_password" "admin_password" {
  length           = 8
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "random_password" "suport_password" {
  length           = 8
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

###############################################################################
# IAM Groups
###############################################################################

resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport_group" {
  name = "SuportGroup"
}

###############################################################################
# IAM Users
###############################################################################

resource "aws_iam_user" "billing_user" {
  name          = "Billing"
  force_destroy = true
  tags = {
    Team = "Billing"
  }
}

resource "aws_iam_user" "admin_user" {
  name          = "Admin"
  force_destroy = true
  tags = {
    Team = "Admin"
  }
}

resource "aws_iam_user" "suport_user" {
  name          = "Suport"
  force_destroy = true
  tags = {
    Team = "Suport"
  }
}

###############################################################################
# Group memberships
###############################################################################

resource "aws_iam_user_group_membership" "billing_membership" {
  user   = aws_iam_user.billing_user.name
  groups = [aws_iam_group.billing_group.name]
}

resource "aws_iam_user_group_membership" "admin_membership" {
  user   = aws_iam_user.admin_user.name
  groups = [aws_iam_group.admin_group.name]
}

resource "aws_iam_user_group_membership" "suport_membership" {
  user   = aws_iam_user.suport_user.name
  groups = [aws_iam_group.suport_group.name]
}

###############################################################################
# Console login profiles
###############################################################################

resource "aws_iam_user_login_profile" "billing_login" {
  user                    = aws_iam_user.billing_user.name
  password                = random_password.billing_password.result
  password_reset_required = false
}

resource "aws_iam_user_login_profile" "admin_login" {
  user                    = aws_iam_user.admin_user.name
  password                = random_password.admin_password.result
  password_reset_required = false
}

resource "aws_iam_user_login_profile" "suport_login" {
  user                    = aws_iam_user.suport_user.name
  password                = random_password.suport_password.result
  password_reset_required = false
}

###############################################################################
# Billing policy (read-only billing / usage / budgets / cost reports / pricing)
###############################################################################

data "aws_iam_policy_document" "billing_policy_document" {
  statement {
    sid    = "BillingPortalReadOnly"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "aws-portal:ViewAccount",
      "aws-portal:ViewPaymentMethods",
      "aws-portal:ViewCredits",
      "aws-portal:ViewDedicatedUsage",
      "aws-portal:ViewRIUsage",
      "aws-portal:ViewRateBasedUsage",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "BudgetsReadOnly"
    effect = "Allow"
    actions = [
      "budgets:ViewBudget",
      "budgets:DescribeBudget",
      "budgets:DescribeBudgets",
      "budgets:DescribeBudgetPerformanceHistory",
      "budgets:DescribeNotificationsForBudget",
      "budgets:DescribeSubscribersForNotification",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CostReportReadOnly"
    effect = "Allow"
    actions = [
      "cur:DescribeReportDefinitions",
      "cur:GetUsageReport",
      "cur:GetClassicReport",
      "cur:GetClassicReportPreferences",
      "ce:GetCostAndUsage",
      "ce:GetCostForecast",
      "ce:GetDimensionValues",
      "ce:GetReservationUtilization",
      "ce:GetSavingsPlansUtilization",
      "ce:GetUsageForecast",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "PricingReadOnly"
    effect = "Allow"
    actions = [
      "pricing:DescribeServices",
      "pricing:GetAttributeValues",
      "pricing:GetProducts",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  description = "Read-only access to billing, usage, budgets, cost reports, and pricing."
  policy      = data.aws_iam_policy_document.billing_policy_document.json
}

resource "aws_iam_group_policy_attachment" "billing_policy_attachment" {
  group      = aws_iam_group.billing_group.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

###############################################################################
# Admin policy (AWS managed AdministratorAccess)
###############################################################################

resource "aws_iam_group_policy_attachment" "admin_managed_policy_attachment" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

###############################################################################
# Support policy (read-only EC2, S3, CloudWatch, RDS)
###############################################################################

data "aws_iam_policy_document" "suport_policy_document" {
  statement {
    sid    = "EC2ReadOnly"
    effect = "Allow"
    actions = [
      "ec2:Describe*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ReadOnly"
    effect = "Allow"
    actions = [
      "s3:Get*",
      "s3:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "RDSReadOnly"
    effect = "Allow"
    actions = [
      "rds:Describe*",
      "rds:List*",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "suport_policy" {
  name        = "SuportPolicy"
  description = "Read-only describe/get/list access to EC2, S3, CloudWatch, and RDS."
  policy      = data.aws_iam_policy_document.suport_policy_document.json
}

resource "aws_iam_group_policy_attachment" "suport_policy_attachment" {
  group      = aws_iam_group.suport_group.name
  policy_arn = aws_iam_policy.suport_policy.arn
}

###############################################################################
# Outputs (username + generated console password)
###############################################################################

output "billing_username" {
  description = "Console username for the Billing user."
  value       = aws_iam_user.billing_user.name
}

output "billing_password" {
  description = "Generated console password for the Billing user."
  value       = random_password.billing_password.result
  sensitive   = true
}

output "admin_username" {
  description = "Console username for the Admin user."
  value       = aws_iam_user.admin_user.name
}

output "admin_password" {
  description = "Generated console password for the Admin user."
  value       = random_password.admin_password.result
  sensitive   = true
}

output "suport_username" {
  description = "Console username for the Suport user."
  value       = aws_iam_user.suport_user.name
}

output "suport_password" {
  description = "Generated console password for the Suport user."
  value       = random_password.suport_password.result
  sensitive   = true
}
```

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region in which to create the EFS file system"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used for naming and tagging resources"
  type        = string
  default     = "efs-shared-storage-test"
}

# Terraform-generated creation token for idempotent EFS creation
resource "random_id" "efs_creation_token" {
  byte_length = 8
  prefix      = var.name_prefix

  keepers = {
    name_prefix = var.name_prefix
  }
}

# Encrypted EFS file system with general purpose performance and bursting throughput
resource "aws_efs_file_system" "this" {
  creation_token   = random_id.efs_creation_token.hex
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  # No lifecycle_policy block: lifecycle transitions are intentionally omitted
  # No file_system_policy: file system policies are intentionally omitted

  tags = {
    Name        = var.name_prefix
    Environment = "test"
    ManagedBy   = "Terraform"
  }
}

# Backup policy enabling automatic backups for the EFS file system
resource "aws_efs_backup_policy" "this" {
  file_system_id = aws_efs_file_system.this.id

  backup_policy {
    status = "ENABLED"
  }
}

output "efs_file_system_id" {
  description = "ID of the EFS file system"
  value       = aws_efs_file_system.this.id
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system"
  value       = aws_efs_file_system.this.arn
}

output "efs_file_system_dns_name" {
  description = "DNS name of the EFS file system"
  value       = aws_efs_file_system.this.dns_name
}

## Description

This Terraform configuration provisions the foundational storage and IAM layer for an AWS NLP pipeline (Glue + Comprehend + Lambda + Step Functions).

**Remote state backend infrastructure**
- A KMS customer-managed key with automatic rotation enabled and a 7-day deletion window, plus an alias for convenience.
- An S3 bucket named `my-terraform-state-bucket-<current-account-id>` (account ID resolved at apply time via `aws_caller_identity`), with versioning enabled, a full public-access block, and default SSE-KMS encryption using the new CMK (bucket keys enabled).
- A DynamoDB table `terraform-locks` with on-demand billing and a string hash key `LockID` for state locking.

**Service roles (least-privilege, per service)**
- `glue-service-role` — trusted by `glue.amazonaws.com`, attached to the AWS managed `AWSGlueServiceRole` policy, plus an inline policy granting read/write object access to `nlp-pipeline-bucket`.
- `comprehend-service-role` — trusted by `comprehend.amazonaws.com`, with the same inline S3 object read/write policy on `nlp-pipeline-bucket`.
- `lambda-execution-role` — trusted by `lambda.amazonaws.com`, attached to `AWSLambdaBasicExecutionRole`, plus an inline policy granting S3 object read/write on `nlp-pipeline-bucket`, write access to the `NLPResults` DynamoDB table, and `states:StartExecution` on the `YourStateMachineName` state machine.
- `step-functions-service-role` — trusted by `states.amazonaws.com`, with an inline policy allowing `lambda:InvokeFunction` on any function in the account/region and `glue:StartJobRun` on any Glue job in the account/region.

All ARNs are constructed from the region and account ID (so no undeclared resources are referenced), all variables carry defaults, and the provider is pinned to `us-east-1`. A commented-out `backend "s3"` block is included for the bootstrap-then-migrate workflow, since the state bucket itself must exist before it can be used as a backend.

```iac_template
###############################################################################
# Terraform & provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # ---------------------------------------------------------------------------
  # Remote state backend.
  #
  # NOTE: This block is intentionally commented out. The bucket and lock table
  # it references are created BY this configuration, so the backend cannot be
  # enabled until after the first `terraform apply`. Once applied, uncomment
  # the block (replacing <ACCOUNT_ID> with the real account ID) and run
  # `terraform init -migrate-state`.
  # ---------------------------------------------------------------------------
  # backend "s3" {
  #   bucket         = "my-terraform-state-bucket-<ACCOUNT_ID>"
  #   key            = "global/nlp-pipeline/terraform.tfstate"
  #   region         = "us-east-1"
  #   dynamodb_table = "terraform-locks"
  #   encrypt        = true
  # }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which all resources are created."
  type        = string
  default     = "us-east-1"
}

variable "state_bucket_prefix" {
  description = "Prefix for the Terraform remote state bucket name (account ID is appended)."
  type        = string
  default     = "my-terraform-state-bucket-"
}

variable "terraform_lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  type        = string
  default     = "terraform-locks"
}

variable "nlp_bucket_name" {
  description = "Name of the S3 bucket holding NLP pipeline data."
  type        = string
  default     = "nlp-pipeline-bucket"
}

variable "nlp_results_table_name" {
  description = "Name of the DynamoDB table storing NLP results."
  type        = string
  default     = "NLPResults"
}

variable "state_machine_name" {
  description = "Name of the Step Functions state machine orchestrating the NLP pipeline."
  type        = string
  default     = "YourStateMachineName"
}

variable "project_tag" {
  description = "Value for the Project tag applied to all resources."
  type        = string
  default     = "nlp-data-pipeline"
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  common_tags = {
    Project   = var.project_tag
    ManagedBy = "Terraform"
  }

  # Constructed ARNs (the referenced buckets/tables/state machines are managed
  # outside this foundational stack, so no data sources are needed).
  nlp_bucket_arn             = "arn:aws:s3:::${var.nlp_bucket_name}"
  nlp_bucket_objects_arn     = "arn:aws:s3:::${var.nlp_bucket_name}/*"
  nlp_results_table_arn      = "arn:aws:dynamodb:${var.aws_region}:${local.account_id}:table/${var.nlp_results_table_name}"
  state_machine_arn          = "arn:aws:states:${var.aws_region}:${local.account_id}:stateMachine:${var.state_machine_name}"
  lambda_function_arn_pattern = "arn:aws:lambda:${var.aws_region}:${local.account_id}:function:*"
  glue_job_arn_pattern       = "arn:aws:glue:${var.aws_region}:${local.account_id}:job/*"
}

###############################################################################
# KMS key for Terraform remote state encryption
###############################################################################

resource "aws_kms_key" "terraform_state" {
  description             = "Customer managed key used to encrypt Terraform remote state"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  is_enabled              = true

  tags = {
    Name = "terraform-state-kms-key"
  }
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.terraform_state.key_id
}

###############################################################################
# S3 bucket for Terraform remote state
###############################################################################

resource "aws_s3_bucket" "terraform_state" {
  bucket = "${var.state_bucket_prefix}${local.account_id}"

  tags = {
    Name = "terraform-state-bucket"
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# DynamoDB table for Terraform state locking
###############################################################################

resource "aws_dynamodb_table" "terraform_locks" {
  name         = var.terraform_lock_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = {
    Name = "terraform-state-locks"
  }
}

###############################################################################
# Glue service role
###############################################################################

data "aws_iam_policy_document" "glue_assume_role" {
  statement {
    sid     = "GlueAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "glue_service_role" {
  name        = "glue-service-role"
  description = "Service role assumed by AWS Glue jobs in the NLP data pipeline"

  assume_role_policy = data.aws_iam_policy_document.glue_assume_role.json
}

resource "aws_iam_role_policy_attachment" "glue_service_role_managed" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSGlueServiceRole"
}

data "aws_iam_policy_document" "glue_nlp_bucket_access" {
  statement {
    sid    = "NLPBucketObjectReadWrite"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      local.nlp_bucket_arn,
      local.nlp_bucket_objects_arn,
    ]
  }
}

resource "aws_iam_role_policy" "glue_nlp_bucket_access" {
  name   = "glue-nlp-bucket-access"
  role   = aws_iam_role.glue_service_role.id
  policy = data.aws_iam_policy_document.glue_nlp_bucket_access.json
}

###############################################################################
# Comprehend service role
###############################################################################

data "aws_iam_policy_document" "comprehend_assume_role" {
  statement {
    sid     = "ComprehendAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["comprehend.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "comprehend_service_role" {
  name        = "comprehend-service-role"
  description = "Service role assumed by Amazon Comprehend for NLP processing"

  assume_role_policy = data.aws_iam_policy_document.comprehend_assume_role.json
}

data "aws_iam_policy_document" "comprehend_nlp_bucket_access" {
  statement {
    sid    = "NLPBucketObjectReadWrite"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      local.nlp_bucket_arn,
      local.nlp_bucket_objects_arn,
    ]
  }
}

resource "aws_iam_role_policy" "comprehend_nlp_bucket_access" {
  name   = "comprehend-nlp-bucket-access"
  role   = aws_iam_role.comprehend_service_role.id
  policy = data.aws_iam_policy_document.comprehend_nlp_bucket_access.json
}

###############################################################################
# Lambda execution role
###############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "LambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name        = "lambda-execution-role"
  description = "Execution role for NLP pipeline Lambda functions"

  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "aws_iam_policy_document" "lambda_pipeline_access" {
  statement {
    sid    = "NLPBucketObjectReadWrite"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      local.nlp_bucket_arn,
      local.nlp_bucket_objects_arn,
    ]
  }

  statement {
    sid    = "NLPResultsTableWrite"
    effect = "Allow"

    actions = [
      "dynamodb:PutItem",
      "dynamodb:UpdateItem",
      "dynamodb:DeleteItem",
      "dynamodb:BatchWriteItem",
    ]

    resources = [local.nlp_results_table_arn]
  }

  statement {
    sid    = "StartStateMachineExecution"
    effect = "Allow"

    actions   = ["states:StartExecution"]
    resources = [local.state_machine_arn]
  }
}

resource "aws_iam_role_policy" "lambda_pipeline_access" {
  name   = "lambda-pipeline-access"
  role   = aws_iam_role.lambda_execution_role.id
  policy = data.aws_iam_policy_document.lambda_pipeline_access.json
}

###############################################################################
# Step Functions service role
###############################################################################

data "aws_iam_policy_document" "step_functions_assume_role" {
  statement {
    sid     = "StepFunctionsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "step_functions_service_role" {
  name        = "step-functions-service-role"
  description = "Service role assumed by the NLP pipeline Step Functions state machine"

  assume_role_policy = data.aws_iam_policy_document.step_functions_assume_role.json
}

data "aws_iam_policy_document" "step_functions_pipeline_access" {
  statement {
    sid       = "InvokeAnyLambdaFunction"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = [local.lambda_function_arn_pattern]
  }

  statement {
    sid       = "StartAnyGlueJobRun"
    effect    = "Allow"
    actions   = ["glue:StartJobRun"]
    resources = [local.glue_job_arn_pattern]
  }
}

resource "aws_iam_role_policy" "step_functions_pipeline_access" {
  name   = "step-functions-pipeline-access"
  role   = aws_iam_role.step_functions_service_role.id
  policy = data.aws_iam_policy_document.step_functions_pipeline_access.json
}

###############################################################################
# Outputs
###############################################################################

output "terraform_state_bucket_name" {
  description = "Name of the S3 bucket used for Terraform remote state."
  value       = aws_s3_bucket.terraform_state.id
}

output "terraform_state_bucket_arn" {
  description = "ARN of the S3 bucket used for Terraform remote state."
  value       = aws_s3_bucket.terraform_state.arn
}

output "terraform_state_kms_key_arn" {
  description = "ARN of the KMS CMK used to encrypt Terraform remote state."
  value       = aws_kms_key.terraform_state.arn
}

output "terraform_lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  value       = aws_dynamodb_table.terraform_locks.name
}

output "glue_service_role_arn" {
  description = "ARN of the Glue service role."
  value       = aws_iam_role.glue_service_role.arn
}

output "comprehend_service_role_arn" {
  description = "ARN of the Amazon Comprehend service role."
  value       = aws_iam_role.comprehend_service_role.arn
}

output "lambda_execution_role_arn" {
  description = "ARN of the Lambda execution role."
  value       = aws_iam_role.lambda_execution_role.arn
}

output "step_functions_service_role_arn" {
  description = "ARN of the Step Functions service role."
  value       = aws_iam_role.step_functions_service_role.arn
}
```

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

provider "local" {}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the ZenML stack will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "zenml_version" {
  description = "ZenML version the generated stack YAML file targets."
  type        = string
  default     = "0.12.0"
}

variable "stack_file_name" {
  description = "File name of the locally generated ZenML stack YAML."
  type        = string
  default     = "zenml-stack.yaml"
}

variable "stack_name" {
  description = "Name of the ZenML stack described by the generated YAML file."
  type        = string
  default     = "demo-stack"
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  tags = {
    managedBy   = "terraform"
    application = "demo"
  }

  artifact_bucket_name = "demo-artifact-store-${local.account_id}"
  artifact_bucket_path = "s3://${local.artifact_bucket_name}"
  ecr_registry_uri     = "${local.account_id}.dkr.ecr.${var.aws_region}.amazonaws.com"
}

###############################################################################
# KMS key for S3 (and ECR) encryption
###############################################################################

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "artifact_store" {
  description             = "Customer-managed KMS key for encrypting the ZenML artifact store"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = local.tags
}

resource "aws_kms_alias" "artifact_store" {
  name          = "alias/demo-artifact-store"
  target_key_id = aws_kms_key.artifact_store.key_id
}

###############################################################################
# S3 artifact store bucket
###############################################################################

resource "aws_s3_bucket" "artifact_store" {
  bucket        = local.artifact_bucket_name
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_ownership_controls" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "artifact_store" {
  depends_on = [aws_s3_bucket_ownership_controls.artifact_store]

  bucket = aws_s3_bucket.artifact_store.id
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifact_store.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# ECR repository for ZenML container images
###############################################################################

resource "aws_ecr_repository" "zenml_kubernetes" {
  name                 = "zenml-kubernetes"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.artifact_store.arn
  }

  tags = local.tags
}

###############################################################################
# Locally generated ZenML stack definition
###############################################################################

resource "local_file" "zenml_stack" {
  filename        = "${path.module}/${var.stack_file_name}"
  file_permission = "0644"

  content = <<-EOT
    # ZenML stack definition (generated by Terraform).
    # ZenML version: ${var.zenml_version}
    # Import with: zenml stack import ${var.stack_name} -f ${var.stack_file_name}
    zenml_version: "${var.zenml_version}"
    stack_name: "${var.stack_name}"

    artifact_store:
      name: "demo-artifact-store"
      flavor: "s3"
      path: "${local.artifact_bucket_path}"
      settings:
        encryption_key: "${aws_kms_key.artifact_store.arn}"

    container_registry:
      name: "zenml-kubernetes"
      flavor: "aws"
      uri: "${local.ecr_registry_uri}"

    secrets_manager:
      name: "aws-secrets-manager"
      flavor: "aws"
      settings:
        region_name: "${var.aws_region}"
  EOT
}

###############################################################################
# Outputs
###############################################################################

output "artifact_bucket_name" {
  description = "Name of the S3 artifact store bucket."
  value       = aws_s3_bucket.artifact_store.id
}

output "artifact_bucket_path" {
  description = "S3 URI used as the ZenML artifact store path."
  value       = local.artifact_bucket_path
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for artifact store encryption."
  value       = aws_kms_key.artifact_store.arn
}

output "ecr_registry_uri" {
  description = "ECR registry URI for the current account and region."
  value       = local.ecr_registry_uri
}

output "ecr_repository_url" {
  description = "Full URL of the ZenML container registry repository."
  value       = aws_ecr_repository.zenml_kubernetes.repository_url
}

output "zenml_stack_file" {
  description = "Path of the locally generated ZenML stack YAML file."
  value       = local_file.zenml_stack.filename
}

This Terraform program creates the ECS task execution IAM role and a Secrets Manager secret, following the specified naming and policy requirements. It uses a `random_id` resource to generate a unique suffix for both the role name (`nim-ecs_task_execution-<suffix>`) and the secret name (`nim-reposecret-<suffix>`). The role is trusted by `ecs-tasks.amazonaws.com`, has the AWS-managed `AmazonECSTaskExecutionRolePolicy` attached, and receives an inline policy named `ECSTaskAccessSecretsPolicy` that allows `secretsmanager:GetSecretValue` only for the created secret. The secret stores a JSON object with username `AWS` and an empty password by default (password is marked sensitive and can be overridden via variable). Provider configuration and all required variables with defaults are included.

```iac_template
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix to use for naming the ECS task execution role and the Secrets Manager secret."
  type        = string
  default     = "nim"
}

variable "secret_username" {
  description = "Username for the container-registry credentials stored in Secrets Manager."
  type        = string
  default     = "AWS"
}

variable "secret_password" {
  description = "Password for the container-registry credentials stored in Secrets Manager. Empty by default."
  type        = string
  default     = ""
  sensitive   = true
}

# Generate a unique suffix to append to resource names for uniqueness.
resource "random_id" "suffix" {
  byte_length = 4
}

# IAM role for ECS task execution, trusted by ECS tasks service.
resource "aws_iam_role" "ecs_task_execution" {
  name = "${var.name_prefix}-ecs_task_execution-${random_id.suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the AWS-managed ECS task execution policy.
resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# Secrets Manager secret to store container-registry credentials.
resource "aws_secretsmanager_secret" "reposecret" {
  name = "${var.name_prefix}-reposecret-${random_id.suffix.hex}"
}

# Secret value: JSON with username and empty password by default.
resource "aws_secretsmanager_secret_version" "reposecret" {
  secret_id = aws_secretsmanager_secret.reposecret.id

  secret_string = jsonencode({
    username = var.secret_username
    password = var.secret_password
  })
}

# Inline policy allowing the ECS task execution role to read only the above secret's value.
resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name = "ECSTaskAccessSecretsPolicy"
  role = aws_iam_role.ecs_task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = [aws_secretsmanager_secret.reposecret.arn]
      }
    ]
  })
}
```

###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

###############################################################################
# Input Variables
###############################################################################

variable "region" {
  description = "AWS region used by the provider. AWS Organizations is a global service; any valid region works."
  type        = string
  default     = "us-east-1"
}

variable "organizational_units" {
  description = <<-EOT
    Optional list of slash-delimited organizational unit paths to create beneath
    the organization root, e.g. ["Sandbox", "Workloads/Prod", "Workloads/NonProd/Dev"].
    Up to five levels deep. Ancestor OUs are created automatically. Defaults to an
    empty list so that no organizational units are created.
  EOT
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for p in var.organizational_units :
      length([for s in split("/", p) : trimspace(s) if trimspace(s) != ""]) >= 1 &&
      length([for s in split("/", p) : trimspace(s) if trimspace(s) != ""]) <= 5
    ])
    error_message = "Each organizational unit path must contain between 1 and 5 non-empty, slash-delimited segments."
  }
}

###############################################################################
# Locals - normalize paths and derive per-level prefixes
###############################################################################

locals {
  # Trim whitespace and collapse any empty segments (e.g. "A//B" -> "A/B").
  ou_paths = [
    for p in var.organizational_units :
    join("/", [for s in split("/", p) : trimspace(s) if trimspace(s) != ""])
  ]

  # Each normalized path split into its segments.
  ou_segments = [for p in local.ou_paths : split("/", p)]

  # Distinct OU names at level 1 (root children).
  level1_names = distinct([for s in local.ou_segments : s[0]])

  # Distinct full paths (prefixes) at each deeper level. Deeper paths imply
  # their ancestors, so "A/B/C" yields A, A/B and A/B/C.
  level2_paths = distinct([for s in local.ou_segments : join("/", slice(s, 0, 2)) if length(s) >= 2])
  level3_paths = distinct([for s in local.ou_segments : join("/", slice(s, 0, 3)) if length(s) >= 3])
  level4_paths = distinct([for s in local.ou_segments : join("/", slice(s, 0, 4)) if length(s) >= 4])
  level5_paths = distinct([for s in local.ou_segments : join("/", slice(s, 0, 5)) if length(s) >= 5])
}

###############################################################################
# AWS Organization (all features enabled, policy types enabled on the root)
###############################################################################

resource "aws_organizations_organization" "this" {
  feature_set = "ALL"

  # Enables the policy types on the organization root.
  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY",
  ]
}

###############################################################################
# Level 1 Organizational Units (direct children of the root)
###############################################################################

resource "aws_organizations_organizational_unit" "level1" {
  for_each = toset(local.level1_names)

  name      = each.value
  parent_id = aws_organizations_organization.this.roots[0].id
}

###############################################################################
# Level 2 Organizational Units
###############################################################################

resource "aws_organizations_organizational_unit" "level2" {
  for_each = toset(local.level2_paths)

  name      = element(split("/", each.value), 1)
  parent_id = aws_organizations_organizational_unit.level1[element(split("/", each.value), 0)].id
}

###############################################################################
# Level 3 Organizational Units
###############################################################################

resource "aws_organizations_organizational_unit" "level3" {
  for_each = toset(local.level3_paths)

  name      = element(split("/", each.value), 2)
  parent_id = aws_organizations_organizational_unit.level2[join("/", slice(split("/", each.value), 0, 2))].id
}

###############################################################################
# Level 4 Organizational Units
###############################################################################

resource "aws_organizations_organizational_unit" "level4" {
  for_each = toset(local.level4_paths)

  name      = element(split("/", each.value), 3)
  parent_id = aws_organizations_organizational_unit.level3[join("/", slice(split("/", each.value), 0, 3))].id
}

###############################################################################
# Level 5 Organizational Units
###############################################################################

resource "aws_organizations_organizational_unit" "level5" {
  for_each = toset(local.level5_paths)

  name      = element(split("/", each.value), 4)
  parent_id = aws_organizations_organizational_unit.level4[join("/", slice(split("/", each.value), 0, 4))].id
}

###############################################################################
# Outputs
###############################################################################

output "organization_id" {
  description = "The identifier of the AWS Organization."
  value       = aws_organizations_organization.this.id
}

output "organization_arn" {
  description = "The ARN of the AWS Organization."
  value       = aws_organizations_organization.this.arn
}

output "organization_root_id" {
  description = "The ID of the organization root."
  value       = aws_organizations_organization.this.roots[0].id
}

output "organization_enabled_policy_types" {
  description = "Policy types enabled on the organization root."
  value       = aws_organizations_organization.this.enabled_policy_types
}

output "organizational_unit_ids" {
  description = "Map of slash-delimited OU path to organizational unit ID."
  value = merge(
    { for k, v in aws_organizations_organizational_unit.level1 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level2 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level3 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level4 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level5 : k => v.id },
  )
}

output "organizational_unit_arns" {
  description = "Map of slash-delimited OU path to organizational unit ARN."
  value = merge(
    { for k, v in aws_organizations_organizational_unit.level1 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level2 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level3 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level4 : k => v.arn },
    { for k, v in aws_organizations_organizational_unit.level5 : k => v.arn },
  )
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "swe_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name          = "swe-vpc"
    ResourceGroup = "default"
  }
}

# ---------------------------------------------------------------------------
# Adopt / manage the VPC's default Network ACL
# ---------------------------------------------------------------------------
resource "aws_default_network_acl" "swe_vpc_default_acl" {
  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  tags = {
    Name          = "swe-vpc-default_acl"
    ResourceGroup = "default"
  }

  # Allow ALL traffic from the VPC's own CIDR
  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "10.0.0.0/16"
    from_port  = 0
    to_port    = 0
  }

  # Explicitly DENY inbound SSH (22) from anywhere
  ingress {
    protocol   = "tcp"
    rule_no    = 200
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  # Explicitly DENY inbound RDP (3389) from anywhere
  ingress {
    protocol   = "tcp"
    rule_no    = 210
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 3389
    to_port    = 3389
  }

  # Allow ALL traffic to the VPC's own CIDR
  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "10.0.0.0/16"
    from_port  = 0
    to_port    = 0
  }
}

# ---------------------------------------------------------------------------
# Adopt / manage the VPC's default Security Group (no rules of its own)
# ---------------------------------------------------------------------------
resource "aws_default_security_group" "swe_vpc_default_sg" {
  vpc_id = aws_vpc.swe_vpc.id

  # No ingress/egress blocks -> Terraform manages the group with no rules of its own

  tags = {
    Name          = "swe-vpc-default_sg"
    ResourceGroup = "default"
  }
}

# ---------------------------------------------------------------------------
# Separate inbound rules on the default Security Group
# ---------------------------------------------------------------------------

# Allow ICMP echo (ping) from anywhere
resource "aws_security_group_rule" "default_sg_icmp_ingress" {
  type              = "ingress"
  from_port         = 8
  to_port           = 0
  protocol          = "icmp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  description       = "Allow ICMP echo (ping) from anywhere"
}

# Allow HTTP (port 80) from anywhere
resource "aws_security_group_rule" "default_sg_http_ingress" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  description       = "Allow HTTP (port 80) from anywhere"
}

