terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  stage       = var.stage
  name        = var.name
  delimiter   = var.delimiter
  attributes  = var.attributes
  tags        = var.tags
  label_order = var.label_order
  enabled     = var.enabled
  context     = var.context
}

locals {
  create_sns_topic            = var.create_sns_topic
  create_event_rule           = var.create_event_rule
  create_event_rule_effective = var.create_event_rule && (var.create_sns_topic || var.sns_topic_arn != "")
  create_sns_topic_policy     = var.create_sns_topic && local.create_event_rule_effective
  notification_topic_arn      = var.create_sns_topic ? try(aws_sns_topic.this[0].arn, "") : var.sns_topic_arn
}

resource "aws_guardduty_detector" "this" {
  enable = true

  datasources {
    s3_logs {
      enable = false
    }
  }

  tags = module.this.tags
}

resource "aws_sns_topic" "this" {
  count = local.create_sns_topic ? 1 : 0

  name              = "${module.this.id}-findings"
  kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
  tags              = module.this.tags
}

resource "aws_sns_topic_policy" "this" {
  count = local.create_sns_topic_policy ? 1 : 0

  arn = aws_sns_topic.this[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEventBridgeToPublishGuardDutyFindings"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.this[0].arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_cloudwatch_event_rule.this[0].arn
          }
        }
      }
    ]
  })
}

resource "aws_cloudwatch_event_rule" "this" {
  count = local.create_event_rule_effective ? 1 : 0

  name        = "${module.this.id}-findings"
  description = "Capture GuardDuty findings and send them to SNS"

  event_pattern = jsonencode({
    source        = ["aws.guardduty"]
    "detail-type" = ["GuardDuty Finding"]
  })

  tags = module.this.tags
}

resource "aws_cloudwatch_event_target" "this" {
  count = local.create_event_rule_effective ? 1 : 0

  rule      = aws_cloudwatch_event_rule.this[0].name
  target_id = "sns"
  arn       = local.notification_topic_arn
}

variable "region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region to deploy the GuardDuty detector and optional notifications into."
}

variable "namespace" {
  type        = string
  default     = ""
  description = "Cloud Posse namespace label."
}

variable "environment" {
  type        = string
  default     = ""
  description = "Cloud Posse environment label."
}

variable "stage" {
  type        = string
  default     = ""
  description = "Cloud Posse stage label."
}

variable "name" {
  type        = string
  default     = "guardduty"
  description = "Cloud Posse name label."
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter used by the Cloud Posse label module."
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Cloud Posse additional attributes."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags to apply to resources."
}

variable "label_order" {
  type        = list(string)
  default     = ["namespace", "environment", "stage", "name", "attributes"]
  description = "Cloud Posse label order."
}

variable "enabled" {
  type        = bool
  default     = true
  description = "Whether to enable the Cloud Posse label module."
}

variable "context" {
  type        = any
  default     = {}
  description = "Cloud Posse context for the label module."
}

variable "create_sns_topic" {
  type        = bool
  default     = false
  description = "Whether to create an SNS topic for GuardDuty finding notifications."
}

variable "create_event_rule" {
  type        = bool
  default     = false
  description = "Whether to create an EventBridge rule for GuardDuty findings."
}

variable "sns_topic_arn" {
  type        = string
  default     = ""
  description = "Existing SNS topic ARN to use for GuardDuty finding notifications when create_sns_topic is false."
}

variable "kms_master_key_id" {
  type        = string
  default     = ""
  description = "Optional KMS master key ID for SNS topic encryption."
}

## Description

This Terraform configuration provisions a complete AWS Backup stack with randomly-suffixed, convention-following resource names.

**What it builds:**

1. **Name prefix generation** — A `random_string` resource produces a 6-character lowercase alphanumeric suffix, combined with the base `sudo-backup-` to form a unique prefix (e.g. `sudo-backup-x7k2qn`) used consistently across every resource name.

2. **Customer-managed KMS key** — `aws_kms_key` with `enable_key_rotation = true`, a descriptive alias, and a key policy that grants account-root administration plus explicit use permissions for the backup role (Decrypt, DescribeKey, GenerateDataKey, ReEncryptFrom/To, CreateGrant, ListGrants).

3. **Backup vault** — `aws_backup_vault` named `<prefix>-backup-vault`, encrypted with the customer-managed key via `kms_key_arn`.

4. **Backup plan** — `aws_backup_plan` named `<prefix>-backup-plan` containing a single rule named `<prefix>-backup-rule` that targets the vault on `cron(0 12 * * ? *)` (noon UTC) and tags recovery points with a `Name` tag. Conditional `dynamic` blocks for lifecycle and copy actions are driven by variables whose defaults (`null`) mean "no lifecycle transition/expiration and no cross-vault copy" out of the box, while remaining configurable.

5. **IAM role** — `aws_iam_role` named `<prefix>-backup-role`, assumable by `backup.amazonaws.com`. It has the AWS-managed `AWSBackupServiceRolePolicyForBackup` attached, plus a small inline policy scoped to the created KMS key so encrypted backup/restore operations succeed.

6. **Backup selection** — `aws_backup_selection` named `<prefix>-backup-selection` that uses the backup role and selects every resource carrying the tag `backup = true` (`STRINGEQUALS`), with `resources = ["*"]`.

Outputs expose the vault name/ARN, plan ID, role ARN, and key ARN for downstream use.

```hcl
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------
# Variables (all have defaults so the stack is deployable as-is)
# ---------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region in which to deploy the backup stack."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Base prefix for all resource names; a random 6-character suffix is appended."
  type        = string
  default     = "sudo-backup-"
}

variable "backup_lifecycle_cold_storage_after" {
  description = "Days after creation to move recovery points to cold storage. Null means disabled."
  type        = number
  default     = null
}

variable "backup_lifecycle_delete_after" {
  description = "Days after creation to expire recovery points. Null means no expiration."
  type        = number
  default     = null
}

variable "backup_copy_destination_vault_arn" {
  description = "ARN of a secondary vault for cross-vault copy. Null disables copy actions."
  type        = string
  default     = null
}

variable "backup_copy_delete_after" {
  description = "Days after creation to expire copied recovery points. Null means no expiration."
  type        = number
  default     = null
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Randomized name prefix: sudo-backup-<6 lowercase alphanumeric chars>
# ---------------------------------------------------------------------------

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  prefix = "${var.name_prefix}${random_string.suffix.result}"
}

# ---------------------------------------------------------------------------
# Customer-managed KMS key (rotation enabled) + alias
# ---------------------------------------------------------------------------

resource "aws_kms_key" "backup" {
  description             = "Customer-managed key encrypting ${local.prefix}-backup-vault"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid    = "AllowBackupRoleUseOfKey"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.backup.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:CreateGrant",
          "kms:ListGrants"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.prefix}-backup-key"
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${local.prefix}-backup"
  target_key_id = aws_kms_key.backup.key_id
}

# ---------------------------------------------------------------------------
# IAM role that AWS Backup assumes
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowBackupServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "${local.prefix}-backup-role"
  description        = "Role assumed by AWS Backup for ${local.prefix}-backup-plan"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name = "${local.prefix}-backup-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup_service" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy" "backup_kms" {
  name = "${local.prefix}-backup-kms-policy"
  role = aws_iam_role.backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowUseOfBackupKmsKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:CreateGrant",
          "kms:ListGrants"
        ]
        Resource = aws_kms_key.backup.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Backup vault encrypted with the customer-managed key
# ---------------------------------------------------------------------------

resource "aws_backup_vault" "main" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name = "${local.prefix}-backup-vault"
  }
}

# ---------------------------------------------------------------------------
# Backup plan with a single daily rule targeting the vault
# ---------------------------------------------------------------------------

resource "aws_backup_plan" "main" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 12 * * ? *)"

    recovery_point_tags = {
      Name = "${local.prefix}-backup-recovery-point"
    }

    # Lifecycle is created only when a transition or expiration value is supplied.
    # Defaults are null, so no transition and no expiration are configured.
    dynamic "lifecycle" {
      for_each = (
        var.backup_lifecycle_cold_storage_after != null ||
        var.backup_lifecycle_delete_after != null
      ) ? [1] : []

      content {
        cold_storage_after = var.backup_lifecycle_cold_storage_after
        delete_after       = var.backup_lifecycle_delete_after
      }
    }

    # Cross-vault copy is created only when a destination vault ARN is supplied.
    # Default is null, so no copy action is configured.
    dynamic "copy_action" {
      for_each = var.backup_copy_destination_vault_arn != null ? [1] : []

      content {
        destination_vault_arn = var.backup_copy_destination_vault_arn

        dynamic "lifecycle" {
          for_each = var.backup_copy_delete_after != null ? [1] : []
          content {
            delete_after = var.backup_copy_delete_after
          }
        }
      }
    }
  }

  tags = {
    Name = "${local.prefix}-backup-plan"
  }
}

# ---------------------------------------------------------------------------
# Backup selection: resources tagged backup = true, using the backup role
# ---------------------------------------------------------------------------

resource "aws_backup_selection" "tagged" {
  name         = "${local.prefix}-backup-selection"
  plan_id      = aws_backup_plan.main.id
  iam_role_arn = aws_iam_role.backup.arn

  resources = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "name_prefix" {
  description = "Generated resource name prefix (sudo-backup-<random>)."
  value       = local.prefix
}

output "backup_vault_name" {
  description = "Name of the encrypted backup vault."
  value       = aws_backup_vault.main.name
}

output "backup_vault_arn" {
  description = "ARN of the encrypted backup vault."
  value       = aws_backup_vault.main.arn
}

output "backup_plan_id" {
  description = "ID of the backup plan."
  value       = aws_backup_plan.main.id
}

output "backup_plan_arn" {
  description = "ARN of the backup plan."
  value       = aws_backup_plan.main.arn
}

output "backup_role_arn" {
  description = "ARN of the IAM role assumed by AWS Backup."
  value       = aws_iam_role.backup.arn
}

output "backup_selection_id" {
  description = "ID of the tag-based backup selection."
  value       = aws_backup_selection.tagged.id
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key with rotation enabled."
  value       = aws_kms_key.backup.arn
}

output "kms_key_alias" {
  description = "Alias of the customer-managed KMS key."
  value       = aws_kms_alias.backup.name
}
```

provider "aws" {
  region = "us-east-1"
}

resource "aws_cognito_user_pool" "coop_tweets" {
  name = "coop-tweets"

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_lowercase = false
    require_numbers   = true
    require_symbols   = true
    require_uppercase = true
  }
}

resource "aws_cognito_user_pool_domain" "coop_tweets" {
  domain       = "coop-tweets-domain"
  user_pool_id = aws_cognito_user_pool.coop_tweets.id
}

resource "aws_cognito_identity_pool" "coop_tweets" {
  identity_pool_name               = "coop tweets"
  allow_unauthenticated_identities = false
}

data "aws_iam_policy_document" "auth_assume_role" {
  statement {
    effect = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.coop_tweets.id]
    }
    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

data "aws_iam_policy_document" "unauth_assume_role" {
  statement {
    effect = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.coop_tweets.id]
    }
    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

resource "aws_iam_role" "coop_tweets_cognito_auth_role" {
  name               = "coop-tweets_cognito_auth_role"
  assume_role_policy = data.aws_iam_policy_document.auth_assume_role.json
}

resource "aws_iam_role" "coop_tweets_cognito_unauth_role" {
  name               = "coop-tweets_cognito_unauth_role"
  assume_role_policy = data.aws_iam_policy_document.unauth_assume_role.json
}

data "aws_iam_policy_document" "cognito_kibana_auth_policy" {
  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
      "cognito-identity:*"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "cognito_kibana_unauth_policy" {
  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
      "cognito-identity:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cognito_kibana_auth_coop_tweets" {
  name        = "cognito_kibana_auth_coop-tweets"
  description = "Policy for authenticated Cognito users for coop-tweets"
  policy      = data.aws_iam_policy_document.cognito_kibana_auth_policy.json
}

resource "aws_iam_policy" "cognito_kibana_unauth_coop_tweets" {
  name        = "cognito_kibana_unauth_coop-tweets"
  description = "Policy for unauthenticated Cognito users for coop-tweets"
  policy      = data.aws_iam_policy_document.cognito_kibana_unauth_policy.json
}

resource "aws_iam_role_policy_attachment" "auth_attach" {
  role       = aws_iam_role.coop_tweets_cognito_auth_role.name
  policy_arn = aws_iam_policy.cognito_kibana_auth_coop_tweets.arn
}

resource "aws_iam_role_policy_attachment" "unauth_attach" {
  role       = aws_iam_role.coop_tweets_cognito_unauth_role.name
  policy_arn = aws_iam_policy.cognito_kibana_unauth_coop_tweets.arn
}

resource "aws_cognito_identity_pool_roles_attachment" "coop_tweets" {
  identity_pool_id = aws_cognito_identity_pool.coop_tweets.id

  roles = {
    "authenticated"   = aws_iam_role.coop_tweets_cognito_auth_role.arn
    "unauthenticated" = aws_iam_role.coop_tweets_cognito_unauth_role.arn
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created"
  type        = string
  default     = "us-east-1"
}

variable "enable_findings_export" {
  description = "Whether to export GuardDuty findings to an S3 bucket"
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "guardduty_kms" {
  statement {
    sid    = "AccountFullAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "GuardDutyGenerateDataKeys"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    actions   = ["kms:GenerateDataKey*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "guardduty" {
  description             = "Customer managed KMS key for GuardDuty findings encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.guardduty_kms.json
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.key_id
}

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
}

resource "aws_cloudwatch_event_rule" "guardduty_finding_events" {
  name        = "guardduty-finding-events"
  description = "Match GuardDuty Finding events"

  event_pattern = jsonencode({
    source        = ["aws.guardduty"]
    "detail-type" = ["GuardDuty Finding"]
  })
}

resource "aws_s3_bucket" "guardduty_findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = "guardduty-findings-export-${data.aws_caller_identity.current.account_id}-${var.aws_region}"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings_export[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.guardduty.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings_export[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "guardduty_s3_export" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "AllowGuardDutyGetBucketLocation"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    actions   = ["s3:GetBucketLocation"]
    resources = [aws_s3_bucket.guardduty_findings_export[0].arn]
  }

  statement {
    sid    = "AllowGuardDutyPutObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.guardduty_findings_export[0].arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "guardduty_findings_export" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings_export[0].id
  policy = data.aws_iam_policy_document.guardduty_s3_export[0].json

  depends_on = [
    aws_s3_bucket_public_access_block.guardduty_findings_export
  ]
}

resource "aws_guardduty_publishing_destination" "guardduty_findings_export" {
  count           = var.enable_findings_export ? 1 : 0
  detector_id     = aws_guardduty_detector.this.id
  destination_arn = aws_s3_bucket.guardduty_findings_export[0].arn
  kms_key_arn     = aws_kms_key.guardduty.arn

  depends_on = [
    aws_s3_bucket_policy.guardduty_findings_export,
    aws_s3_bucket_server_side_encryption_configuration.guardduty_findings_export,
    aws_kms_alias.guardduty
  ]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "this" {
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "this" {
  depends_on = [aws_s3_bucket_ownership_controls.this]

  bucket = aws_s3_bucket.this.id
  acl    = "private"
}

###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables (all have defaults so the template deploys as-is)
###############################################################################

variable "aws_region" {
  description = "Region used by the AWS provider (billing data is global)."
  type        = string
  default     = "us-east-1"
}

variable "role_max_session_duration" {
  description = "Maximum session duration (seconds) for the billing roles (3600 - 43200)."
  type        = number
  default     = 3600
}

variable "billing_full_access_group_users" {
  description = "IAM user names to place in the billing-full-access group. Empty by default so no memberships are created."
  type        = list(string)
  default     = []
}

variable "billing_view_access_group_users" {
  description = "IAM user names to place in the billing-view-access group. Empty by default so no memberships are created."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Tags applied to the created IAM resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Context data
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Trust policy: current account principals only, MFA required
###############################################################################

data "aws_iam_policy_document" "billing_role_assume_role" {
  statement {
    sid    = "AllowCurrentAccountPrincipalsWithMFA"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

###############################################################################
# Customer-managed policies
###############################################################################

data "aws_iam_policy_document" "billing_full_access" {
  statement {
    sid    = "FullBillingUsagePaymentAndBudgetManagement"
    effect = "Allow"

    actions = [
      "aws-portal:*",
      "account:*",
      "budgets:*",
      "ce:*",
      "consolidatedbilling:*",
      "cur:*",
      "freetier:*",
      "invoicing:*",
      "pricing:*",
      "purchase-orders:*",
      "savingsplans:*",
      "tax:*",
      "organizations:Describe*",
      "organizations:List*",
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "billing_view_access" {
  statement {
    sid    = "ReadOnlyBillingUsageAccountPaymentMethodsAndBudgets"
    effect = "Allow"

    actions = [
      "aws-portal:View*",
      "account:Get*",
      "account:List*",
      "budgets:View*",
      "budgets:Describe*",
      "budgets:List*",
      "ce:Get*",
      "ce:Describe*",
      "ce:List*",
      "consolidatedbilling:Get*",
      "consolidatedbilling:Describe*",
      "consolidatedbilling:List*",
      "cur:Get*",
      "cur:Describe*",
      "cur:List*",
      "freetier:Get*",
      "freetier:Describe*",
      "freetier:List*",
      "invoicing:Get*",
      "invoicing:List*",
      "pricing:Get*",
      "pricing:Describe*",
      "pricing:List*",
      "purchase-orders:Get*",
      "purchase-orders:Describe*",
      "purchase-orders:List*",
      "savingsplans:Describe*",
      "savingsplans:List*",
      "tax:Get*",
      "tax:Describe*",
      "tax:List*",
      "organizations:Describe*",
      "organizations:List*",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  description = "Full management access to billing, usage, payment methods and budgets."
  policy      = data.aws_iam_policy_document.billing_full_access.json
  tags        = var.tags
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  description = "Read-only access to billing, usage, account, payment methods and budgets."
  policy      = data.aws_iam_policy_document.billing_view_access.json
  tags        = var.tags
}

###############################################################################
# Roles (assumable by current-account principals with MFA only)
###############################################################################

resource "aws_iam_role" "billing_full_access" {
  name                 = "billing-full-access"
  description          = "Full billing console access role. MFA required to assume."
  max_session_duration = var.role_max_session_duration
  assume_role_policy   = data.aws_iam_policy_document.billing_role_assume_role.json
  tags                 = var.tags
}

resource "aws_iam_role" "billing_view_access" {
  name                 = "billing-view-access"
  description          = "Read-only billing console access role. MFA required to assume."
  max_session_duration = var.role_max_session_duration
  assume_role_policy   = data.aws_iam_policy_document.billing_role_assume_role.json
  tags                 = var.tags
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

###############################################################################
# Groups (at path "/") + inline assume-role policies
###############################################################################

resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    sid       = "AssumeBillingFullAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_full_access.arn]
  }
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    sid       = "AssumeBillingViewAccessRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_view_access.arn]
  }
}

resource "aws_iam_group_policy" "billing_full_access_assume_role" {
  name   = "billing-full-access-assume-role"
  group  = aws_iam_group.billing_full_access.id
  policy = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

resource "aws_iam_group_policy" "billing_view_access_assume_role" {
  name   = "billing-view-access-assume-role"
  group  = aws_iam_group.billing_view_access.id
  policy = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

###############################################################################
# Optional group memberships (empty by default => no memberships created)
###############################################################################

resource "aws_iam_group_membership" "billing_full_access" {
  count = length(var.billing_full_access_group_users) > 0 ? 1 : 0

  name  = "billing-full-access-membership"
  group = aws_iam_group.billing_full_access.name
  users = var.billing_full_access_group_users
}

resource "aws_iam_group_membership" "billing_view_access" {
  count = length(var.billing_view_access_group_users) > 0 ? 1 : 0

  name  = "billing-view-access-membership"
  group = aws_iam_group.billing_view_access.name
  users = var.billing_view_access_group_users
}

###############################################################################
# Outputs
###############################################################################

output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access role."
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access role."
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access group."
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access group."
  value       = aws_iam_group.billing_view_access.arn
}

###############################################################################
# Terraform / provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the Cognito resources are created."
  type        = string
  default     = "us-east-1"
}

variable "base_name" {
  description = "Base name for every resource; a random pet name is appended to it."
  type        = string
  default     = "cognito"
}

variable "pet_name_length" {
  description = "Number of pet words appended to the base name."
  type        = number
  default     = 2
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Project   = "cognito-identity"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Helper lookups: current partition, region and account
###############################################################################

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Random naming / secrets
###############################################################################

resource "random_pet" "this" {
  prefix = var.base_name
  length = var.pet_name_length
}

resource "random_string" "sms_external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = true
  special = false
}

###############################################################################
# Locals
###############################################################################

locals {
  # e.g. "cognito-quiet-otter"
  base_name = random_pet.this.id

  # e.g. "cognito_quiet_otter" (hyphens replaced with underscores)
  pool_name = replace(local.base_name, "-", "_")

  # Resolved by the helper lookups above
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
  account_id = data.aws_caller_identity.current.account_id

  identity_pool_id  = aws_cognito_identity_pool.this.id
  identity_pool_arn = "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${local.identity_pool_id}"
  cognito_sync_arn  = "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${local.identity_pool_id}"
}

###############################################################################
# IAM role assumed by Cognito User Pools to send SMS through SNS
###############################################################################

data "aws_iam_policy_document" "sms_assume_role" {
  statement {
    sid     = "AllowCognitoUserPoolsToAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cognito-idp.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.sms_external_id.result]
    }
  }
}

resource "aws_iam_role" "sms" {
  name               = "${local.base_name}-sms-role"
  description        = "Role assumed by Amazon Cognito to publish SMS messages via Amazon SNS"
  assume_role_policy = data.aws_iam_policy_document.sms_assume_role.json
}

data "aws_iam_policy_document" "sms_publish" {
  statement {
    sid       = "PublishSmsViaSns"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "sms_publish" {
  name   = "${local.base_name}-sms-publish-policy"
  role   = aws_iam_role.sms.id
  policy = data.aws_iam_policy_document.sms_publish.json
}

###############################################################################
# Cognito user pool
###############################################################################

resource "aws_cognito_user_pool" "this" {
  name = local.pool_name

  mfa_configuration        = "OFF"
  auto_verified_attributes = ["email"]

  # --- required, immutable custom attributes -------------------------------
  schema {
    name                     = "email"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = false
    required                 = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  # --- optional, immutable custom attribute --------------------------------
  schema {
    name                     = "phone_number"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = false
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  # --- mutable custom attributes -------------------------------------------
  schema {
    name                     = "profile_user_id"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "profile_email"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "first_name"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "last_name"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "gender"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "age"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "persona"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  # --- SMS delivery through the SNS publishing role ------------------------
  sms_configuration {
    sns_caller_arn = aws_iam_role.sms.arn
    external_id    = random_string.sms_external_id.result
  }
}

###############################################################################
# Cognito user pool app client (no client secret)
###############################################################################

resource "aws_cognito_user_pool_client" "this" {
  name         = "${local.base_name}-client"
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  supported_identity_providers = ["COGNITO"]
}

###############################################################################
# Cognito identity pool (federated identities)
###############################################################################

resource "aws_cognito_identity_pool" "this" {
  identity_pool_name               = local.base_name
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.this.id
    provider_name           = aws_cognito_user_pool.this.endpoint
    server_side_token_check = false
  }
}

###############################################################################
# Trust policies - each role trusts only this identity pool
###############################################################################

data "aws_iam_policy_document" "signed_users_assume_role" {
  statement {
    sid     = "AllowAuthenticatedCognitoIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.this.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

data "aws_iam_policy_document" "anonymous_users_assume_role" {
  statement {
    sid     = "AllowUnauthenticatedCognitoIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.this.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

###############################################################################
# Permission policies scoped to this identity pool
###############################################################################

data "aws_iam_policy_document" "signed_users" {
  statement {
    sid    = "CognitoIdentity"
    effect = "Allow"

    actions = [
      "cognito-identity:GetId",
      "cognito-identity:GetOpenIdToken",
      "cognito-identity:GetOpenIdTokenForDeveloperIdentity",
      "cognito-identity:GetCredentialsForIdentity",
      "cognito-identity:ListIdentities",
      "cognito-identity:DescribeIdentity",
      "cognito-identity:LookupDeveloperIdentity",
      "cognito-identity:MergeDeveloperIdentities",
      "cognito-identity:UnlinkIdentity",
    ]

    resources = [
      local.identity_pool_arn,
      "${local.identity_pool_arn}/*",
    ]
  }

  statement {
    sid     = "CognitoSync"
    effect  = "Allow"
    actions = ["cognito-sync:*"]

    resources = [
      local.cognito_sync_arn,
      "${local.cognito_sync_arn}/identity/*",
      "${local.cognito_sync_arn}/dataset/*",
    ]
  }
}

data "aws_iam_policy_document" "anonymous_users" {
  statement {
    sid    = "CognitoIdentity"
    effect = "Allow"

    actions = [
      "cognito-identity:GetId",
      "cognito-identity:GetOpenIdToken",
      "cognito-identity:GetCredentialsForIdentity",
    ]

    resources = [
      local.identity_pool_arn,
      "${local.identity_pool_arn}/*",
    ]
  }
}

###############################################################################
# IAM roles for the identity pool
###############################################################################

resource "aws_iam_role" "signed_users" {
  name               = "${local.base_name}-signed-users-role"
  description        = "Role for authenticated (signed-in) identities of the ${local.base_name} identity pool"
  assume_role_policy = data.aws_iam_policy_document.signed_users_assume_role.json
}

resource "aws_iam_role_policy" "signed_users" {
  name   = "${local.base_name}-signed-users-policy"
  role   = aws_iam_role.signed_users.id
  policy = data.aws_iam_policy_document.signed_users.json
}

resource "aws_iam_role" "anonymous_users" {
  name               = "${local.base_name}-anonymous-users-role"
  description        = "Role for unauthenticated (anonymous) identities of the ${local.base_name} identity pool"
  assume_role_policy = data.aws_iam_policy_document.anonymous_users_assume_role.json
}

resource "aws_iam_role_policy" "anonymous_users" {
  name   = "${local.base_name}-anonymous-users-policy"
  role   = aws_iam_role.anonymous_users.id
  policy = data.aws_iam_policy_document.anonymous_users.json
}

###############################################################################
# Attach the roles to the identity pool
###############################################################################

resource "aws_cognito_identity_pool_roles_attachment" "this" {
  identity_pool_id = aws_cognito_identity_pool.this.id

  roles = {
    "authenticated"   = aws_iam_role.signed_users.arn
    "unauthenticated" = aws_iam_role.anonymous_users.arn
  }
}

###############################################################################
# Outputs
###############################################################################

output "user_pool_id" {
  description = "ID of the Cognito user pool."
  value       = aws_cognito_user_pool.this.id
}

output "user_pool_arn" {
  description = "ARN of the Cognito user pool."
  value       = aws_cognito_user_pool.this.arn
}

output "user_pool_endpoint" {
  description = "Endpoint (provider name) of the Cognito user pool."
  value       = aws_cognito_user_pool.this.endpoint
}

output "user_pool_client_id" {
  description = "ID of the Cognito user pool app client."
  value       = aws_cognito_user_pool_client.this.id
}

output "identity_pool_id" {
  description = "ID of the Cognito identity pool."
  value       = aws_cognito_identity_pool.this.id
}

output "signed_users_role_arn" {
  description = "ARN of the authenticated (signed-users) IAM role."
  value       = aws_iam_role.signed_users.arn
}

output "anonymous_users_role_arn" {
  description = "ARN of the unauthenticated (anonymous-users) IAM role."
  value       = aws_iam_role.anonymous_users.arn
}

output "sms_role_arn" {
  description = "ARN of the IAM role Cognito assumes to publish SMS messages via SNS."
  value       = aws_iam_role.sms.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.30.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the Batch environment will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the new VPC."
  type        = string
  default     = "192.168.0.0/16"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet."
  type        = string
  default     = "192.168.0.0/24"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "192.168.10.0/24"
}

variable "results_bucket_prefix" {
  description = "Prefix of the S3 results bucket name (account ID is appended)."
  type        = string
  default     = "benchmark-batch-results"
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  name_suffix = "${terraform.workspace}-batch"

  azs = data.aws_availability_zones.available.names

  # Second availability zone of the region
  az = local.azs[1]

  account_id = data.aws_caller_identity.current.account_id

  results_bucket_name = "${var.results_bucket_prefix}-${local.account_id}"

  common_tags = {
    Name        = local.name_suffix
    Workspace   = terraform.workspace
    ManagedBy   = "Terraform"
    Application = "aws-batch-pipeline"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "batch" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.name_suffix
  })
}

###############################################################################
# Subnets (both in the second AZ of the region)
###############################################################################

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.batch.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_suffix}-public"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.batch.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_suffix}-private"
    Tier = "private"
  })
}

###############################################################################
# Internet gateway, Elastic IP and NAT gateway
###############################################################################

resource "aws_internet_gateway" "batch" {
  vpc_id = aws_vpc.batch.id

  tags = merge(local.common_tags, {
    Name = local.name_suffix
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_suffix}-nat-eip"
  })
}

resource "aws_nat_gateway" "batch" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  depends_on = [aws_internet_gateway.batch]

  tags = merge(local.common_tags, {
    Name = local.name_suffix
  })
}

###############################################################################
# Route tables and associations
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.batch.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.batch.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_suffix}-public"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.batch.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.batch.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_suffix}-private"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security group for the Batch compute environment
# (single egress rule: HTTPS to the VPC CIDR)
###############################################################################

resource "aws_security_group" "batch" {
  name        = local.name_suffix
  description = "Security group for the ${terraform.workspace} AWS Batch compute environment"
  vpc_id      = aws_vpc.batch.id

  egress {
    description = "HTTPS to the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.batch.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = local.name_suffix
  })
}

###############################################################################
# KMS key for the S3 results bucket (customer managed, rotation enabled)
###############################################################################

resource "aws_kms_key" "batch" {
  description             = "KMS CMK for the ${local.results_bucket_name} bucket used by ${terraform.workspace} AWS Batch"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = local.name_suffix
  })
}

resource "aws_kms_alias" "batch" {
  name          = "alias/${local.name_suffix}"
  target_key_id = aws_kms_key.batch.key_id
}

###############################################################################
# S3 results bucket
###############################################################################

resource "aws_s3_bucket" "results" {
  bucket = local.results_bucket_name

  tags = merge(local.common_tags, {
    Name = local.results_bucket_name
  })
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.batch.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# IAM: AWS Batch service role
###############################################################################

resource "aws_iam_role" "batch_service" {
  name        = "${local.name_suffix}-service-role"
  description = "Service role assumed by AWS Batch for the ${terraform.workspace} environment"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BatchServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_suffix}-service-role"
  })
}

resource "aws_iam_role_policy_attachment" "batch_service" {
  role       = aws_iam_role.batch_service.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBatchServiceRole"
}

###############################################################################
# IAM: ECS instance role, custom S3 policy, instance profile
###############################################################################

resource "aws_iam_role" "ecs_instance" {
  name        = "${local.name_suffix}-ecs-instance-role"
  description = "Instance role for EC2 hosts in the ${terraform.workspace} AWS Batch compute environment"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_suffix}-ecs-instance-role"
  })
}

resource "aws_iam_role_policy_attachment" "ecs_instance_ecs" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_policy" "ecs_s3_policy" {
  name        = "ecs_s3_policy"
  description = "Allows Batch ECS instances to read S3 generally, read/write/delete the results bucket and use its KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ListAndReadGeneral"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListAllMyBuckets",
          "s3:GetBucketLocation",
          "s3:GetObject"
        ]
        Resource = "*"
      },
      {
        Sid    = "ResultsBucketReadWriteDelete"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:AbortMultipartUpload"
        ]
        Resource = [
          aws_s3_bucket.results.arn,
          "${aws_s3_bucket.results.arn}/*"
        ]
      },
      {
        Sid    = "ResultsBucketKmsUsage"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [
          aws_kms_key.batch.arn
        ]
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "ecs_s3_policy"
  })
}

resource "aws_iam_role_policy_attachment" "ecs_instance_s3" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = aws_iam_policy.ecs_s3_policy.arn
}

resource "aws_iam_instance_profile" "ecs_instance" {
  name = "${local.name_suffix}-ecs-instance-profile"
  role = aws_iam_role.ecs_instance.name

  tags = merge(local.common_tags, {
    Name = "${local.name_suffix}-ecs-instance-profile"
  })
}

###############################################################################
# AWS Batch compute environment (managed, EC2, private subnet)
###############################################################################

resource "aws_batch_compute_environment" "batch" {
  name         = local.name_suffix
  type         = "MANAGED"
  state        = "ENABLED"
  service_role = aws_iam_role.batch_service.arn

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    min_vcpus           = 0
    max_vcpus           = 4
    desired_vcpus       = 0
    instance_type       = ["optimal"]
    image_type          = "ECS_AL2023"

    subnets            = [aws_subnet.private.id]
    security_group_ids = [aws_security_group.batch.id]
    instance_role      = aws_iam_instance_profile.ecs_instance.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.batch_service,
    aws_iam_role_policy_attachment.ecs_instance_ecs,
    aws_iam_role_policy_attachment.ecs_instance_s3,
    aws_internet_gateway.batch,
    aws_nat_gateway.batch,
    aws_route_table_association.private
  ]

  tags = merge(local.common_tags, {
    Name = local.name_suffix
  })
}

###############################################################################
# AWS Batch job queue
###############################################################################

resource "aws_batch_job_queue" "batch" {
  name     = "${terraform.workspace}-queue"
  state    = "ENABLED"
  priority = 1

  compute_environments = [aws_batch_compute_environment.batch.arn]

  tags = merge(local.common_tags, {
    Name = "${terraform.workspace}-queue"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.batch.id
}

output "private_subnet_id" {
  description = "ID of the private subnet used by the Batch compute environment."
  value       = aws_subnet.private.id
}

output "batch_compute_environment_name" {
  description = "Name of the managed Batch compute environment."
  value       = aws_batch_compute_environment.batch.name
}

output "batch_job_queue_name" {
  description = "Name of the Batch job queue."
  value       = aws_batch_job_queue.batch.name
}

output "results_bucket_name" {
  description = "Name of the S3 results bucket."
  value       = aws_s3_bucket.results.id
}

output "results_bucket_kms_key_arn" {
  description = "ARN of the customer managed KMS key used for the results bucket."
  value       = aws_kms_key.batch.arn
}

##############################################################################
# Terraform & AWS provider configuration
##############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

##############################################################################
# Input variables (all have defaults so the configuration is deployable as-is)
##############################################################################

variable "aws_region" {
  description = "AWS region where the backup bucket and IAM resources are created."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name_prefix" {
  description = "Prefix of the backup bucket name. The current AWS account ID is appended."
  type        = string
  default     = "endpoint-backup"
}

variable "iam_user_name" {
  description = "Name of the IAM user that is granted access to the backup bucket."
  type        = string
  default     = "endpoint-backup"
}

variable "iam_policy_name" {
  description = "Name of the customer managed policy granting bucket read/write access."
  type        = string
  default     = "endpoint-backup-bucket-read-write-access"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Purpose   = "endpoint-backups"
  }
}

##############################################################################
# Data sources & locals
##############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
  bucket_name = "${var.bucket_name_prefix}-${local.account_id}"
  bucket_arn  = "arn:${local.partition}:s3:::${local.bucket_name}"

  # AWS managed KMS key used by S3 (SSE-KMS / bucket keys)
  s3_kms_key_arn = "arn:${local.partition}:kms:${var.aws_region}:${local.account_id}:alias/aws/s3"
}

##############################################################################
# S3 bucket: endpoint-backup-<account id>
##############################################################################

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  # Object Lock must be explicitly disabled (default, stated explicitly).
  object_lock_enabled = false

  tags = merge(var.tags, {
    Name = local.bucket_name
  })
}

# Block every form of public access.
resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Disable ACLs; the bucket owner owns every object written to the bucket.
resource "aws_s3_bucket_ownership_controls" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Transfer acceleration suspended.
resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

# Versioning enabled so version-level permissions are meaningful and
# backups cannot be silently overwritten.
resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Default server-side encryption with S3 managed keys (AES256).
resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

##############################################################################
# Bucket policy: deny insecure transport and long COMPLIANCE retention
##############################################################################

data "aws_iam_policy_document" "endpoint_backup_bucket_policy" {
  # 1) Deny any request that does not use TLS (plain HTTP).
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      local.bucket_arn,
      "${local.bucket_arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  # 2) Deny any request negotiated with a TLS version older than 1.2.
  statement {
    sid    = "DenyOutdatedTLS"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      local.bucket_arn,
      "${local.bucket_arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  # 3) Deny uploads / retention changes that would lock objects in
  #    COMPLIANCE mode for more than 90 days.
  statement {
    sid    = "DenyComplianceRetentionOver90Days"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
      "s3:PutObjectLegalHold",
    ]

    resources = ["${local.bucket_arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.endpoint_backup]
}

##############################################################################
# IAM user (no access keys are created)
##############################################################################

resource "aws_iam_user" "endpoint_backup" {
  name = var.iam_user_name
  path = "/"

  tags = merge(var.tags, {
    Name = var.iam_user_name
  })
}

##############################################################################
# Customer managed policy: list / read / write / delete / version /
# retention / restore on the bucket, plus decrypt & data-key access on the
# AWS managed S3 KMS key.
##############################################################################

data "aws_iam_policy_document" "endpoint_backup_bucket_access" {
  # -------- List / bucket level metadata --------
  statement {
    sid    = "ListBucket"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:ListBucketMultipartUploads",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:GetBucketObjectLockConfiguration",
    ]

    resources = [local.bucket_arn]
  }

  # -------- Read objects --------
  statement {
    sid    = "ReadObjects"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectAttributes",
      "s3:GetObjectVersionAttributes",
      "s3:GetObjectTagging",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:ListMultipartUploadParts",
    ]

    resources = ["${local.bucket_arn}/*"]
  }

  # -------- Write objects --------
  statement {
    sid    = "WriteObjects"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:PutObjectTagging",
      "s3:PutObjectVersionTagging",
      "s3:AbortMultipartUpload",
    ]

    resources = ["${local.bucket_arn}/*"]
  }

  # -------- Delete objects and versions --------
  statement {
    sid    = "DeleteObjects"
    effect = "Allow"

    actions = [
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:DeleteObjectTagging",
      "s3:DeleteObjectVersionTagging",
    ]

    resources = ["${local.bucket_arn}/*"]
  }

  # -------- Retention / legal hold --------
  statement {
    sid    = "ObjectRetention"
    effect = "Allow"

    actions = [
      "s3:PutObjectRetention",
      "s3:PutObjectLegalHold",
    ]

    resources = ["${local.bucket_arn}/*"]
  }

  # -------- Restore archived objects --------
  statement {
    sid    = "RestoreObjects"
    effect = "Allow"

    actions = [
      "s3:RestoreObject",
    ]

    resources = ["${local.bucket_arn}/*"]
  }

  # -------- Use the AWS managed S3 KMS key --------
  statement {
    sid    = "UseAwsManagedS3KmsKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [local.s3_kms_key_arn]
  }
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write" {
  name        = var.iam_policy_name
  description = "List, read, write, delete, version, retention and restore access to the ${local.bucket_name} bucket."
  policy      = data.aws_iam_policy_document.endpoint_backup_bucket_access.json

  tags = merge(var.tags, {
    Name = var.iam_policy_name
  })
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write.arn
}

##############################################################################
# Outputs
##############################################################################

output "bucket_name" {
  description = "Name of the created backup bucket."
  value       = aws_s3_bucket.endpoint_backup.id
}

output "bucket_arn" {
  description = "ARN of the created backup bucket."
  value       = aws_s3_bucket.endpoint_backup.arn
}

output "iam_user_name" {
  description = "Name of the IAM user granted bucket access."
  value       = aws_iam_user.endpoint_backup.name
}

output "iam_policy_arn" {
  description = "ARN of the customer managed bucket access policy."
  value       = aws_iam_policy.endpoint_backup_bucket_read_write.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which to deploy the shared-services Cognito resources."
  type        = string
  default     = "us-west-2"
}

variable "project_name" {
  description = "Project / application name used for tagging."
  type        = string
  default     = "unity-shared-services"
}

# ---- App client callback / logout URLs --------------------------------------

variable "unity_uds_distribution_callback_urls" {
  description = "Callback URLs for the unity-uds-distribution app client."
  type        = list(string)
  default     = ["https://api.unity-shared-services.example.com/uds/oauth2/callback"]
}

variable "unity_uds_distribution_logout_urls" {
  description = "Logout URLs for the unity-uds-distribution app client."
  type        = list(string)
  default     = ["https://api.unity-shared-services.example.com/uds/logout"]
}

variable "localhost_jupyterhub_callback_urls" {
  description = "Callback URLs for the localhost JupyterHub app client."
  type        = list(string)
  default     = ["http://localhost:8000/hub/oauth_callback"]
}

variable "localhost_jupyterhub_logout_urls" {
  description = "Logout URLs for the localhost JupyterHub app client."
  type        = list(string)
  default     = ["http://localhost:8000/logout"]
}

variable "unity_app_to_app_callback_urls" {
  description = "Callback URLs for the unity app-to-app client."
  type        = list(string)
  default     = ["https://api.unity-shared-services.example.com/app-to-app/oauth2/callback"]
}

variable "unity_app_to_app_logout_urls" {
  description = "Logout URLs for the unity app-to-app client."
  type        = list(string)
  default     = ["https://api.unity-shared-services.example.com/app-to-app/logout"]
}

variable "uads_jupyter_development_callback_urls" {
  description = "Callback URLs for the UADS Jupyter development client."
  type        = list(string)
  default     = ["http://localhost:8888/oauth2/callback"]
}

variable "uads_jupyter_development_logout_urls" {
  description = "Logout URLs for the UADS Jupyter development client."
  type        = list(string)
  default     = ["http://localhost:8888/logout"]
}

variable "hysds_ui_callback_urls" {
  description = "Callback URLs for the HySDS UI client."
  type        = list(string)
  default     = ["https://hysds-ui.unity-shared-services.example.com/oauth2/callback"]
}

variable "hysds_ui_logout_urls" {
  description = "Logout URLs for the HySDS UI client."
  type        = list(string)
  default     = ["https://hysds-ui.unity-shared-services.example.com/logout"]
}

variable "localhost_hysds_ui_callback_urls" {
  description = "Callback URLs for the localhost HySDS UI client."
  type        = list(string)
  default     = ["http://localhost:3000/oauth2/callback"]
}

variable "localhost_hysds_ui_logout_urls" {
  description = "Logout URLs for the localhost HySDS UI client."
  type        = list(string)
  default     = ["http://localhost:3000/logout"]
}

###############################################################################
# Cognito User Pool
###############################################################################

resource "aws_cognito_user_pool" "shared_services" {
  name = "unity-shared-services-user-pool"

  # Only administrators may create users.
  admin_create_user_config {
    allow_admin_create_user_only = true

    # Deliver the generated username and temporary password in the invite.
    invite_message_template {
      email_subject = "Your Unity Shared Services account has been created"
      email_message = "Hello,\n\nYour Unity Shared Services username is {username} and your temporary password is {####}. Please sign in and change your password.\n\nThank you,\nUnity Shared Services Team"
      sms_message   = "Unity account: username {username}, temporary password {####}"
    }
  }

  # Account recovery must use a verified email address.
  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  # Email is the auto-verified attribute used for recovery.
  auto_verified_attributes = ["email"]

  username_configuration {
    case_sensitive = false
  }

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 0
      max_length = 2048
    }
  }

  tags = {
    Name    = "unity-shared-services-user-pool"
    Project = var.project_name
  }
}

###############################################################################
# Hosted UI Domain
###############################################################################

resource "aws_cognito_user_pool_domain" "shared_services" {
  domain       = "unity-shared-services-test"
  user_pool_id = aws_cognito_user_pool.shared_services.id
}

###############################################################################
# Publish the user pool ID to SSM
###############################################################################

resource "aws_ssm_parameter" "user_pool_id" {
  name  = "/unity/cs/security/shared-services-cognito-user-pool/user-pool-id"
  type  = "String"
  value = aws_cognito_user_pool.shared_services.id

  tags = {
    Name    = "shared-services-cognito-user-pool-id"
    Project = var.project_name
  }
}

###############################################################################
# App Clients
###############################################################################

locals {
  app_clients = {
    "unity-uds-distribution-user-pool-client" = {
      name                = "unity-uds-distribution-user-pool-client"
      generate_secret     = true
      callback_urls       = var.unity_uds_distribution_callback_urls
      logout_urls         = var.unity_uds_distribution_logout_urls
      explicit_auth_flows = ["ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH"]
    }
    "localhost-jupyterhub-user-pool-client" = {
      name                = "localhost-jupyterhub-user-pool-client"
      generate_secret     = true
      callback_urls       = var.localhost_jupyterhub_callback_urls
      logout_urls         = var.localhost_jupyterhub_logout_urls
      explicit_auth_flows = ["ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH"]
    }
    "unity-app-to-app-client-user-pool-client" = {
      name                = "unity-app-to-app-client-user-pool-client"
      generate_secret     = true
      callback_urls       = var.unity_app_to_app_callback_urls
      logout_urls         = var.unity_app_to_app_logout_urls
      explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH"]
    }
    "uads-jupyter-development-client-user-pool-client" = {
      name                = "uads-jupyter-development-client-user-pool-client"
      generate_secret     = true
      callback_urls       = var.uads_jupyter_development_callback_urls
      logout_urls         = var.uads_jupyter_development_logout_urls
      explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH"]
    }
    "hysds-ui-client-user-pool-client" = {
      name                = "hysds-ui-client-user-pool-client"
      generate_secret     = false
      callback_urls       = var.hysds_ui_callback_urls
      logout_urls         = var.hysds_ui_logout_urls
      explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH"]
    }
    "localhost-hysds-ui-client-user-pool-client" = {
      name                = "localhost-hysds-ui-client-user-pool-client"
      generate_secret     = false
      callback_urls       = var.localhost_hysds_ui_callback_urls
      logout_urls         = var.localhost_hysds_ui_logout_urls
      explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH"]
    }
  }
}

resource "aws_cognito_user_pool_client" "clients" {
  for_each = local.app_clients

  name         = each.value.name
  user_pool_id = aws_cognito_user_pool.shared_services.id

  generate_secret = each.value.generate_secret

  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  allowed_oauth_flows_user_pool_client = true
  supported_identity_providers         = ["COGNITO"]

  callback_urls = each.value.callback_urls
  logout_urls   = each.value.logout_urls

  explicit_auth_flows = each.value.explicit_auth_flows

  depends_on = [aws_cognito_user_pool_domain.shared_services]
}

###############################################################################
# User Groups
###############################################################################

resource "aws_cognito_user_group" "unity_admin" {
  name         = "Unity_Admin"
  user_pool_id = aws_cognito_user_pool.shared_services.id
  description  = "Unity shared-services administrators"
}

resource "aws_cognito_user_group" "unity_viewer" {
  name         = "Unity_Viewer"
  user_pool_id = aws_cognito_user_pool.shared_services.id
  description  = "Unity shared-services read-only viewers"
}

###############################################################################
# Outputs
###############################################################################

output "user_pool_id" {
  description = "ID of the shared-services Cognito user pool."
  value       = aws_cognito_user_pool.shared_services.id
}

output "user_pool_arn" {
  description = "ARN of the shared-services Cognito user pool."
  value       = aws_cognito_user_pool.shared_services.arn
}

output "user_pool_domain" {
  description = "Hosted UI domain of the shared-services Cognito user pool."
  value       = aws_cognito_user_pool_domain.shared_services.domain
}

output "user_pool_id_ssm_parameter_name" {
  description = "SSM parameter name holding the user pool ID."
  value       = aws_ssm_parameter.user_pool_id.name
}

output "app_client_ids" {
  description = "Map of app client names to their IDs."
  value       = { for k, v in aws_cognito_user_pool_client.clients : k => v.id }
}

###############################################################################
# Terraform / Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the VPC will be created."
  type        = string
  default     = "us-east-1"
}

variable "app_name" {
  description = "Application name used for naming and tagging resources."
  type        = string
  default     = "terraform"
}

variable "environment" {
  description = "Environment name used for naming and tagging resources."
  type        = string
  default     = "testing"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets (one per availability zone)."
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC (disabled by default)."
  type        = bool
  default     = false
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "enable_ipv6" {
  description = "Enable IPv6 on the VPC/subnets and create egress-only IPv6 routing (disabled by default)."
  type        = bool
  default     = false
}

variable "enable_transit_gateway_attachment" {
  description = "Create a transit gateway and attach the VPC to it (disabled by default)."
  type        = bool
  default     = false
}

variable "transit_gateway_asn" {
  description = "Amazon side ASN for the optional transit gateway."
  type        = number
  default     = 64512
}

###############################################################################
# Data sources & locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  # e.g. "terraform-testing"
  name_prefix = "${var.app_name}-${var.environment}"

  # First three standard availability zones in the region
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  common_tags = {
    Application = var.app_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  assign_generated_ipv6_cidr_block = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = "vpc-${local.name_prefix}"
  })
}

###############################################################################
# Subnets (one public + one private per AZ)
###############################################################################

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  ipv6_cidr_block                 = var.enable_ipv6 ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 1) : null
  assign_ipv6_address_on_creation = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${local.azs[count.index]}"
    Tier = "public"
    Type = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  ipv6_cidr_block                 = var.enable_ipv6 ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 11) : null
  assign_ipv6_address_on_creation = var.enable_ipv6

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${local.azs[count.index]}"
    Tier = "private"
    Type = "private"
  })
}

###############################################################################
# Internet gateway (public egress) + optional egress-only IGW (IPv6)
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_egress_only_internet_gateway" "main" {
  count = var.enable_ipv6 ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eigw"
  })
}

###############################################################################
# Public routing
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_internet" {
  count = var.enable_ipv6 ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT gateway (Elastic IP + single NAT in the first public subnet)
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Private routing (shared route table through the NAT gateway)
###############################################################################

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route" "private_ipv6_egress" {
  count = var.enable_ipv6 ? 1 : 0

  route_table_id              = aws_route_table.private.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = one(aws_egress_only_internet_gateway.main[*].id)
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# DB subnet group (private subnets only)
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "db-subnet-${local.name_prefix}"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "db-subnet-${local.name_prefix}"
  })
}

###############################################################################
# Optional transit gateway attachment (disabled by default)
###############################################################################

resource "aws_ec2_transit_gateway" "main" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  description                     = "Transit gateway for ${local.name_prefix}"
  amazon_side_asn                 = var.transit_gateway_asn
  auto_accept_shared_attachments  = "disable"
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"
  dns_support                     = "enable"
  vpn_ecmp_support                = "enable"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tgw"
  })
}

resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  subnet_ids         = aws_subnet.private[*].id
  transit_gateway_id = one(aws_ec2_transit_gateway.main[*].id)
  vpc_id             = aws_vpc.main.id

  dns_support                                     = "enable"
  transit_gateway_default_route_table_association = true
  transit_gateway_default_route_table_propagation = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tgw-attachment"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc" {
  description = "Details of the created VPC."
  value = {
    id                   = aws_vpc.main.id
    arn                  = aws_vpc.main.arn
    cidr_block           = aws_vpc.main.cidr_block
    ipv6_cidr_block      = aws_vpc.main.ipv6_cidr_block
    enable_dns_hostnames = aws_vpc.main.enable_dns_hostnames
    enable_dns_support   = aws_vpc.main.enable_dns_support
    availability_zones   = local.azs
    name                 = "vpc-${local.name_prefix}"
  }
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "availability_zones" {
  description = "Availability zones used by the subnets."
  value       = local.azs
}

output "subnets" {
  description = "Details of the public and private subnets."

  value = {
    public = {
      for idx, subnet in aws_subnet.public : subnet.availability_zone => {
        id                = subnet.id
        name              = subnet.tags["Name"]
        cidr_block        = subnet.cidr_block
        ipv6_cidr_block   = subnet.ipv6_cidr_block
        availability_zone = subnet.availability_zone
        route_table_id    = aws_route_table.public.id
        type              = "public"
      }
    }
    private = {
      for idx, subnet in aws_subnet.private : subnet.availability_zone => {
        id                = subnet.id
        name              = subnet.tags["Name"]
        cidr_block        = subnet.cidr_block
        ipv6_cidr_block   = subnet.ipv6_cidr_block
        availability_zone = subnet.availability_zone
        route_table_id    = aws_route_table.private.id
        type              = "private"
      }
    }
  }
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "default_security_group" {
  description = "Default security group of the VPC."
  value = {
    id   = aws_vpc.main.default_security_group_id
    name = "default"
    vpc  = aws_vpc.main.id
  }
}

output "default_security_group_id" {
  description = "ID of the VPC default security group."
  value       = aws_vpc.main.default_security_group_id
}

output "nat_gateway" {
  description = "Details of the NAT gateway and its Elastic IP."
  value = {
    id                   = aws_nat_gateway.main.id
    name                 = aws_nat_gateway.main.tags["Name"]
    subnet_id            = aws_nat_gateway.main.subnet_id
    private_ip           = aws_nat_gateway.main.private_ip
    public_ip            = aws_eip.nat.public_ip
    network_interface_id = aws_nat_gateway.main.network_interface_id
    allocation_id        = aws_eip.nat.id
  }
}

output "route_tables" {
  description = "IDs of the public and private route tables."
  value = {
    public  = aws_route_table.public.id
    private = aws_route_table.private.id
  }
}

output "internet_gateways" {
  description = "Internet gateway IDs (IPv6 egress-only gateway is null when IPv6 is disabled)."
  value = {
    internet_gateway    = aws_internet_gateway.main.id
    egress_only_gateway = one(aws_egress_only_internet_gateway.main[*].id)
  }
}

output "db_subnet_group_name" {
  description = "Name of the DB subnet group spanning the private subnets."
  value       = aws_db_subnet_group.main.name
}

output "transit_gateway_attachment" {
  description = "Transit gateway attachment details (null when the attachment is disabled)."
  value = var.enable_transit_gateway_attachment ? {
    id                 = one(aws_ec2_transit_gateway_vpc_attachment.main[*].id)
    transit_gateway_id = one(aws_ec2_transit_gateway.main[*].id)
    vpc_id             = aws_vpc.main.id
  } : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region where the CodeCommit repositories will be created."
  type        = string
  default     = "us-east-1"
}

variable "repository_names" {
  description = "Names of the CodeCommit repositories used by the Argo CD GitOps bridge."
  type        = list(string)
  default     = ["gitops-apps", "gitops-platform", "gitops-addons"]
}

variable "gitops_user_name" {
  description = "IAM user name that authenticates to CodeCommit over SSH."
  type        = string
  default     = "gitops-bridge-gitops"
}

variable "gitops_policy_name" {
  description = "Name of the customer-managed IAM policy granting Git pull/push to the GitOps repositories."
  type        = string
  default     = "gitops-bridge-gitops"
}

variable "secret_name_prefix" {
  description = "Prefix for the Secrets Manager secret that stores the generated SSH private key."
  type        = string
  default     = "codecommit-key-"
}

variable "private_key_filename" {
  description = "Filename (inside the SSH directory) where the generated private key is written."
  type        = string
  default     = "gitops_ssh.pem"
}

variable "ssh_directory" {
  description = "Directory where the SSH private key and SSH config are written."
  type        = string
  default     = "~/.ssh"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "argocd-gitops-bridge"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# CodeCommit repositories
###############################################################################

resource "aws_codecommit_repository" "gitops" {
  for_each = toset(var.repository_names)

  repository_name = each.value
  description     = "Argo CD GitOps bridge repository: ${each.value}"

  tags = merge(var.tags, {
    Name = each.value
  })
}

###############################################################################
# 4096-bit RSA key pair for SSH authentication to CodeCommit
###############################################################################

resource "tls_private_key" "gitops" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

###############################################################################
# IAM user + SSH public key
###############################################################################

resource "aws_iam_user" "gitops" {
  name = var.gitops_user_name
  path = "/"

  tags = merge(var.tags, {
    Name = var.gitops_user_name
  })
}

resource "aws_iam_user_ssh_key" "gitops" {
  username   = aws_iam_user.gitops.name
  encoding   = "SSH"
  public_key = trimspace(tls_private_key.gitops.public_key_openssh)

  depends_on = [aws_iam_user.gitops]
}

###############################################################################
# Customer-managed IAM policy: Git pull/push on the three GitOps repositories only
###############################################################################

resource "aws_iam_policy" "gitops" {
  name        = var.gitops_policy_name
  description = "Allows Git pull and push access to the GitOps bridge CodeCommit repositories."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeCommitGitPullPushScopedToGitOpsRepos"
        Effect = "Allow"
        Action = [
          "codecommit:GitPull",
          "codecommit:GitPush"
        ]
        Resource = [for repo in aws_codecommit_repository.gitops : repo.arn]
      }
    ]
  })

  tags = merge(var.tags, {
    Name = var.gitops_policy_name
  })
}

resource "aws_iam_user_policy_attachment" "gitops" {
  user       = aws_iam_user.gitops.name
  policy_arn = aws_iam_policy.gitops.arn
}

###############################################################################
# Secrets Manager secret holding the generated private key
###############################################################################

resource "random_string" "secret_suffix" {
  length  = 5
  upper   = false
  lower   = true
  numeric = true
  special = false
}

resource "aws_secretsmanager_secret" "gitops_private_key" {
  name                    = "${var.secret_name_prefix}${random_string.secret_suffix.result}"
  description             = "SSH private key used by the Argo CD GitOps bridge to access CodeCommit."
  recovery_window_in_days = 0

  tags = merge(var.tags, {
    Name = "${var.secret_name_prefix}${random_string.secret_suffix.result}"
  })
}

resource "aws_secretsmanager_secret_version" "gitops_private_key" {
  secret_id     = aws_secretsmanager_secret.gitops_private_key.id
  secret_string = tls_private_key.gitops.private_key_pem
}

###############################################################################
# Local SSH artifacts: directory, private key file, SSH config entry
###############################################################################

resource "null_resource" "ssh_directory" {
  triggers = {
    ssh_directory = pathexpand(var.ssh_directory)
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = "mkdir -p '${pathexpand(var.ssh_directory)}' && chmod 700 '${pathexpand(var.ssh_directory)}'"
  }
}

resource "local_sensitive_file" "private_key" {
  content         = tls_private_key.gitops.private_key_pem
  filename        = "${pathexpand(var.ssh_directory)}/${var.private_key_filename}"
  file_permission = "0600"

  depends_on = [null_resource.ssh_directory]
}

resource "local_file" "ssh_config" {
  content = <<-EOT
    # Managed by Terraform (argocd-gitops-bridge). Do not edit manually.
    Host git-codecommit.*.amazonaws.com
      User ${aws_iam_user_ssh_key.gitops.ssh_public_key_id}
      IdentityFile ${pathexpand(var.ssh_directory)}/${var.private_key_filename}
      StrictHostKeyChecking no

  EOT

  filename        = "${pathexpand(var.ssh_directory)}/config"
  file_permission = "0600"

  depends_on = [
    null_resource.ssh_directory,
    aws_iam_user_ssh_key.gitops
  ]
}

###############################################################################
# Outputs
###############################################################################

output "repository_names" {
  description = "Names of the created CodeCommit repositories."
  value       = sort([for repo in aws_codecommit_repository.gitops : repo.repository_name])
}

output "repository_ssh_clone_urls" {
  description = "SSH clone URLs for each GitOps bridge repository."
  value = {
    for name, repo in aws_codecommit_repository.gitops : name => repo.clone_url_ssh
  }
}

output "gitops_user_name" {
  description = "IAM user used for SSH access to CodeCommit."
  value       = aws_iam_user.gitops.name
}

output "gitops_user_arn" {
  description = "ARN of the GitOps bridge IAM user."
  value       = aws_iam_user.gitops.arn
}

output "gitops_ssh_public_key_id" {
  description = "SSH public key ID; this is the SSH username for CodeCommit Git endpoints."
  value       = aws_iam_user_ssh_key.gitops.ssh_public_key_id
}

output "gitops_ssh_username" {
  description = "Username to use in the SSH config for git-codecommit.*.amazonaws.com."
  value       = aws_iam_user_ssh_key.gitops.ssh_public_key_id
}

output "gitops_policy_arn" {
  description = "ARN of the customer-managed IAM policy granting Git pull/push."
  value       = aws_iam_policy.gitops.arn
}

output "private_key_secret_name" {
  description = "Name of the Secrets Manager secret containing the generated SSH private key."
  value       = aws_secretsmanager_secret.gitops_private_key.name
}

output "private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the generated SSH private key."
  value       = aws_secretsmanager_secret.gitops_private_key.arn
}

output "local_private_key_path" {
  description = "Local path of the generated SSH private key."
  value       = local_sensitive_file.private_key.filename
}

output "local_ssh_config_path" {
  description = "Local path of the generated SSH config entry."
  value       = local_file.ssh_config.filename
}

output "account_id" {
  description = "AWS account ID in which the resources were created."
  value       = data.aws_caller_identity.current.account_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "region" {
  description = "AWS region in which to create the instance and its network."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC that the module creates."
  type        = string
  default     = "10.70.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the single subnet that the module creates."
  type        = string
  default     = "10.70.0.0/24"
}

variable "availability_zone" {
  description = "Availability zone for the subnet. Defaults to the first available AZ in the region."
  type        = string
  default     = null
}

variable "instance_name" {
  description = "Name tag / identifier for the EC2 instance."
  type        = string
  default     = "benchmark-instance"
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t2.micro"
}

variable "key_name" {
  description = "Name of the SSH key pair that the module creates."
  type        = string
  default     = "benchmark-d8bc612be4e0-key"
}

variable "public_key" {
  description = "SSH public key material used to create the key pair. When empty, a 2048-bit RSA key pair is generated."
  type        = string
  default     = ""
}

variable "root_volume_size" {
  description = "Size of the encrypted root EBS volume in GiB."
  type        = number
  default     = 10
}

variable "root_volume_type" {
  description = "Type of the root EBS volume."
  type        = string
  default     = "gp2"
}

variable "root_volume_encrypted" {
  description = "Whether the root EBS volume is encrypted."
  type        = bool
  default     = true
}

variable "associate_public_ip_address" {
  description = "Whether to associate a public IP address with the instance."
  type        = bool
  default     = true
}

variable "detailed_monitoring" {
  description = "Enable detailed (1-minute) CloudWatch monitoring for the instance."
  type        = bool
  default     = true
}

variable "iam_policy_arns" {
  description = "Optional list of managed IAM policy ARNs to attach to the instance role."
  type        = list(string)
  default     = []
}

variable "additional_ebs_volumes" {
  description = "Optional extra EBS volumes to create and attach to the instance."
  type = list(object({
    device_name = string
    size        = number
    type        = optional(string, "gp3")
    encrypted   = optional(bool, true)
    iops        = optional(number)
    throughput  = optional(number)
    delete_on_termination = optional(bool, true)
  }))
  default = []
}

variable "additional_network_interfaces" {
  description = "Optional extra network interfaces to attach to the instance (each may receive its own Elastic IP)."
  type = list(object({
    subnet_id          = optional(string)
    private_ip         = optional(string)
    security_group_ids = optional(list(string))
    allocate_eip       = optional(bool, false)
  }))
  default = []
}

variable "status_check_alarm_enabled" {
  description = "Create the CloudWatch StatusCheckFailed_Instance alarm that reboots the instance."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Additional tags applied to every resource created by the module."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  common_tags = merge(
    {
      Name      = var.instance_name
      ManagedBy = "terraform"
    },
    var.tags
  )

  additional_ebs_volumes_map = {
    for idx, volume in var.additional_ebs_volumes : tostring(idx) => volume
  }

  additional_network_interfaces_map = {
    for idx, eni in var.additional_network_interfaces : tostring(idx) => eni
  }

  additional_network_interfaces_with_eip = {
    for idx, eni in var.additional_network_interfaces : tostring(idx) => eni if eni.allocate_eip
  }

  public_key = var.public_key != "" ? var.public_key : tls_private_key.generated[0].public_key_openssh
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${var.instance_name}-vpc" })
}

resource "aws_subnet" "this" {
  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.subnet_cidr
  availability_zone       = coalesce(var.availability_zone, data.aws_availability_zones.available.names[0])
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${var.instance_name}-subnet" })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.common_tags, { Name = "${var.instance_name}-igw" })
}

resource "aws_route_table" "this" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = merge(local.common_tags, { Name = "${var.instance_name}-public-rt" })
}

resource "aws_route_table_association" "this" {
  subnet_id      = aws_subnet.this.id
  route_table_id = aws_route_table.this.id
}

# ---------------------------------------------------------------------------
# AMI and SSH key pair
# ---------------------------------------------------------------------------

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"] # Canonical

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "tls_private_key" "generated" {
  count     = var.public_key == "" ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "this" {
  key_name   = var.key_name
  public_key = local.public_key

  tags = merge(local.common_tags, { Name = var.key_name })
}

# ---------------------------------------------------------------------------
# Security group: egress to the VPC CIDR only, no ingress
# ---------------------------------------------------------------------------

resource "aws_security_group" "this" {
  name        = "${var.instance_name}-sg"
  description = "Egress to the VPC CIDR only; no ingress rules by default"
  vpc_id      = aws_vpc.this.id

  egress {
    description = "Allow all traffic to the VPC CIDR block only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = "${var.instance_name}-sg" })
}

# ---------------------------------------------------------------------------
# IAM role and instance profile
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "this" {
  name               = "${var.instance_name}-role"
  description        = "Role assumed by the ${var.instance_name} EC2 instance"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, { Name = "${var.instance_name}-role" })
}

resource "aws_iam_instance_profile" "this" {
  name = "${var.instance_name}-instance-profile"
  role = aws_iam_role.this.name

  tags = merge(local.common_tags, { Name = "${var.instance_name}-instance-profile" })
}

resource "aws_iam_role_policy_attachment" "this" {
  for_each = toset(var.iam_policy_arns)

  role       = aws_iam_role.this.name
  policy_arn = each.value
}

# ---------------------------------------------------------------------------
# EC2 instance
# ---------------------------------------------------------------------------

resource "aws_instance" "this" {
  ami                         = data.aws_ami.ubuntu.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.this.id
  key_name                    = aws_key_pair.this.key_name
  vpc_security_group_ids      = [aws_security_group.this.id]
  iam_instance_profile        = aws_iam_instance_profile.this.name
  associate_public_ip_address = var.associate_public_ip_address
  monitoring                  = var.detailed_monitoring

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = var.root_volume_size
    volume_type           = var.root_volume_type
    encrypted             = var.root_volume_encrypted
    delete_on_termination = true
  }

  tags = merge(local.common_tags, { Name = var.instance_name })
}

# ---------------------------------------------------------------------------
# Elastic IP for the primary interface
# ---------------------------------------------------------------------------

resource "aws_eip" "this" {
  domain   = "vpc"
  instance = aws_instance.this.id

  tags = merge(local.common_tags, { Name = "${var.instance_name}-eip" })

  depends_on = [aws_internet_gateway.this]
}

# ---------------------------------------------------------------------------
# Optional additional EBS volumes
# ---------------------------------------------------------------------------

resource "aws_ebs_volume" "additional" {
  for_each = local.additional_ebs_volumes_map

  availability_zone = aws_instance.this.availability_zone
  size              = each.value.size
  type              = each.value.type
  encrypted         = each.value.encrypted
  iops              = each.value.iops
  throughput        = each.value.throughput

  tags = merge(local.common_tags, { Name = "${var.instance_name}-vol-${each.key}" })
}

resource "aws_volume_attachment" "additional" {
  for_each = aws_ebs_volume.additional

  device_name = local.additional_ebs_volumes_map[each.key].device_name
  volume_id   = each.value.id
  instance_id = aws_instance.this.id
}

# ---------------------------------------------------------------------------
# Optional additional network interfaces (+ optional Elastic IPs)
# ---------------------------------------------------------------------------

resource "aws_network_interface" "additional" {
  for_each = local.additional_network_interfaces_map

  subnet_id       = coalesce(each.value.subnet_id, aws_subnet.this.id)
  private_ips     = each.value.private_ip == null ? null : [each.value.private_ip]
  security_groups = coalesce(each.value.security_group_ids, [aws_security_group.this.id])

  tags = merge(local.common_tags, { Name = "${var.instance_name}-eni-${each.key}" })
}

resource "aws_network_interface_attachment" "additional" {
  for_each = aws_network_interface.additional

  instance_id          = aws_instance.this.id
  network_interface_id = each.value.id
  device_index         = tonumber(each.key) + 1
}

resource "aws_eip" "additional" {
  for_each = local.additional_network_interfaces_with_eip

  domain            = "vpc"
  network_interface = aws_network_interface.additional[each.key].id

  tags = merge(local.common_tags, { Name = "${var.instance_name}-eip-${each.key}" })

  depends_on = [aws_network_interface_attachment.additional]
}

# ---------------------------------------------------------------------------
# CloudWatch alarm: reboot the instance on failed instance status checks
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "status_check_failed_instance" {
  count = var.status_check_alarm_enabled ? 1 : 0

  alarm_name          = "${var.instance_name}-StatusCheckFailed-Instance"
  alarm_description   = "Reboots ${var.instance_name} when the EC2 instance status check fails for 5 consecutive minutes."
  namespace           = "AWS/EC2"
  metric_name         = "StatusCheckFailed_Instance"
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 5
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "missing"

  dimensions = {
    InstanceId = aws_instance.this.id
  }

  alarm_actions = ["arn:aws:automate:${var.region}:ec2:reboot"]

  tags = merge(local.common_tags, { Name = "${var.instance_name}-StatusCheckFailed-Instance" })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC created by the module."
  value       = aws_vpc.this.id
}

output "subnet_id" {
  description = "ID of the subnet created by the module."
  value       = aws_subnet.this.id
}

output "availability_zone" {
  description = "Availability zone used by the subnet and instance."
  value       = aws_subnet.this.availability_zone
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.this.id
}

output "route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.this.id
}

output "instance_id" {
  description = "ID of the EC2 instance."
  value       = aws_instance.this.id
}

output "instance_name" {
  description = "Name tag of the EC2 instance."
  value       = var.instance_name
}

output "instance_private_ip" {
  description = "Private IP address of the EC2 instance."
  value       = aws_instance.this.private_ip
}

output "instance_public_ip" {
  description = "Public IP address associated with the EC2 instance."
  value       = aws_instance.this.public_ip
}

output "elastic_ip" {
  description = "Elastic IP address attached to the instance's primary interface."
  value       = aws_eip.this.public_ip
}

output "elastic_ip_allocation_id" {
  description = "Allocation ID of the Elastic IP attached to the primary interface."
  value       = aws_eip.this.id
}

output "ami_id" {
  description = "ID of the Ubuntu 22.04 AMI used to launch the instance."
  value       = data.aws_ami.ubuntu.id
}

output "key_pair_name" {
  description = "Name of the SSH key pair created by the module."
  value       = aws_key_pair.this.key_name
}

output "generated_private_key_pem" {
  description = "PEM encoded private key, only populated when no public key was supplied."
  value       = var.public_key == "" ? tls_private_key.generated[0].private_key_pem : null
  sensitive   = true
}

output "security_group_id" {
  description = "ID of the instance security group."
  value       = aws_security_group.this.id
}

output "iam_role_arn" {
  description = "ARN of the IAM role assumed by the instance."
  value       = aws_iam_role.this.arn
}

output "iam_role_name" {
  description = "Name of the IAM role assumed by the instance."
  value       = aws_iam_role.this.name
}

output "iam_instance_profile_name" {
  description = "Name of the IAM instance profile attached to the instance."
  value       = aws_iam_instance_profile.this.name
}

output "root_volume_id" {
  description = "ID of the encrypted root EBS volume."
  value       = aws_instance.this.root_block_device[0].volume_id
}

output "additional_ebs_volume_ids" {
  description = "Map of additional EBS volume IDs keyed by their index in the input list."
  value       = { for key, volume in aws_ebs_volume.additional : key => volume.id }
}

output "additional_network_interface_ids" {
  description = "Map of additional network interface IDs keyed by their index in the input list."
  value       = { for key, eni in aws_network_interface.additional : key => eni.id }
}

output "additional_elastic_ip_addresses" {
  description = "Map of Elastic IP addresses attached to the additional network interfaces."
  value       = { for key, eip in aws_eip.additional : key => eip.public_ip }
}

output "cloudwatch_alarm_name" {
  description = "Name of the StatusCheckFailed_Instance alarm, if created."
  value       = var.status_check_alarm_enabled ? aws_cloudwatch_metric_alarm.status_check_failed_instance[0].alarm_name : null
}

###############################################################################
# Terraform configuration and providers
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Primary source region (first source region)
# ---------------------------------------------------------------------------
provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Secondary source region (second source region)
# ---------------------------------------------------------------------------
provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

# ---------------------------------------------------------------------------
# First replica region
# ---------------------------------------------------------------------------
provider "aws" {
  alias  = "replica1"
  region = "eu-west-1"
}

# ---------------------------------------------------------------------------
# Second replica region
# ---------------------------------------------------------------------------
provider "aws" {
  alias  = "replica2"
  region = "ap-southeast-1"
}

data "aws_caller_identity" "current" {}

###############################################################################
# Global locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id

  tags = {
    Env = "dev"
  }

  # Base names for the source buckets of each source region
  source1_bases = ["log1a.veerum", "log1b.veerum"]
  source2_bases = ["log2a.veerum", "log2b.veerum"]

  # Every replica region holds one replica for every source bucket
  all_bases = concat(local.source1_bases, local.source2_bases)
}

###############################################################################
# IAM role assumed by Amazon S3 for replication
###############################################################################

resource "aws_iam_role" "replication" {
  name        = "s3-cross-region-replication-role"
  description = "Role assumed by Amazon S3 to replicate Env=dev log buckets across regions"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

###############################################################################
# Bucket ARN collections used by the replication policy
###############################################################################

locals {
  source_bucket_arns = concat(
    [for b in aws_s3_bucket.source1 : b.arn],
    [for b in aws_s3_bucket.source2 : b.arn]
  )

  replica_bucket_arns = concat(
    [for b in aws_s3_bucket.replica1 : b.arn],
    [for b in aws_s3_bucket.replica2 : b.arn]
  )

  source_object_arns  = [for arn in local.source_bucket_arns : "${arn}/*"]
  replica_object_arns = [for arn in local.replica_bucket_arns : "${arn}/*"]
}

###############################################################################
# Customer managed IAM policy for the replication role
###############################################################################

resource "aws_iam_policy" "replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Allows S3 replication to read the source log buckets and write to the replica buckets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketReadPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetBucketVersioning",
          "s3:ListBucket",
          "s3:GetReplicationConfiguration"
        ]
        Resource = local.source_bucket_arns
      },
      {
        Sid    = "SourceObjectReadPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersion",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = local.source_object_arns
      },
      {
        Sid    = "ReplicaBucketWritePermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner",
          "s3:GetBucketVersioning"
        ]
        Resource = concat(local.replica_bucket_arns, local.replica_object_arns)
      },
      {
        Sid    = "DecryptSourceKeys"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey"
        ]
        Resource = [
          aws_kms_key.source1.arn,
          aws_kms_key.source2.arn
        ]
      },
      {
        Sid    = "EncryptReplicaKeys"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.replica1.arn,
          aws_kms_key.replica2.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# KMS key policies (shared shape, principal is the replication role)
###############################################################################

locals {
  kms_key_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootAccountPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowS3ReplicationRole"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.replication.arn }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Customer managed KMS keys (one per region)
###############################################################################

# Source key for us-east-1 -> alias/sourcekey1
resource "aws_kms_key" "source1" {
  description             = "SSE-KMS key for source log buckets in us-east-1"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = local.kms_key_policy
  tags                    = local.tags
}

resource "aws_kms_alias" "source1" {
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

# Source key for us-west-2 -> alias/sourcekey2
resource "aws_kms_key" "source2" {
  provider                = aws.source2
  description             = "SSE-KMS key for source log buckets in us-west-2"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = local.kms_key_policy
  tags                    = local.tags
}

resource "aws_kms_alias" "source2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.key_id
}

# Replica key for eu-west-1 -> alias/replicakey1
resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "SSE-KMS key for replica log buckets in eu-west-1"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = local.kms_key_policy
  tags                    = local.tags
}

resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.key_id
}

# Replica key for ap-southeast-1 -> alias/replicakey2
resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "SSE-KMS key for replica log buckets in ap-southeast-1"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = local.kms_key_policy
  tags                    = local.tags
}

resource "aws_kms_alias" "replica2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica2.key_id
}

###############################################################################
# Source buckets - region 1 (us-east-1): log1a.veerum-<acct>, log1b.veerum-<acct>
###############################################################################

resource "aws_s3_bucket" "source1" {
  for_each = toset(local.source1_bases)

  bucket = "${each.value}-${local.account_id}"
  tags   = local.tags
}

resource "aws_s3_bucket_versioning" "source1" {
  for_each = toset(local.source1_bases)

  bucket = aws_s3_bucket.source1[each.value].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "source1" {
  for_each = toset(local.source1_bases)

  bucket = aws_s3_bucket.source1[each.value].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "source1" {
  for_each = toset(local.source1_bases)

  bucket = aws_s3_bucket.source1[each.value].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source1" {
  for_each = toset(local.source1_bases)

  bucket = aws_s3_bucket.source1[each.value].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source1.arn
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# Source buckets - region 2 (us-west-2): log2a.veerum-<acct>, log2b.veerum-<acct>
###############################################################################

resource "aws_s3_bucket" "source2" {
  provider = aws.source2
  for_each = toset(local.source2_bases)

  bucket = "${each.value}-${local.account_id}"
  tags   = local.tags
}

resource "aws_s3_bucket_versioning" "source2" {
  provider = aws.source2
  for_each = toset(local.source2_bases)

  bucket = aws_s3_bucket.source2[each.value].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "source2" {
  provider = aws.source2
  for_each = toset(local.source2_bases)

  bucket = aws_s3_bucket.source2[each.value].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "source2" {
  provider = aws.source2
  for_each = toset(local.source2_bases)

  bucket = aws_s3_bucket.source2[each.value].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source2" {
  provider = aws.source2
  for_each = toset(local.source2_bases)

  bucket = aws_s3_bucket.source2[each.value].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.source2.arn
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# Replica buckets - replica region 1 (eu-west-1)  ->  <base>-replica1-<acct>
###############################################################################

resource "aws_s3_bucket" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_bases)

  bucket = "${each.value}-replica1-${local.account_id}"
  tags   = local.tags
}

resource "aws_s3_bucket_versioning" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_bases)

  bucket = aws_s3_bucket.replica1[each.value].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_bases)

  bucket = aws_s3_bucket.replica1[each.value].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_bases)

  bucket = aws_s3_bucket.replica1[each.value].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1" {
  provider = aws.replica1
  for_each = toset(local.all_bases)

  bucket = aws_s3_bucket.replica1[each.value].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica1.arn
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# Replica buckets - replica region 2 (ap-southeast-1) -> <base>-replica2-<acct>
###############################################################################

resource "aws_s3_bucket" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_bases)

  bucket = "${each.value}-replica2-${local.account_id}"
  tags   = local.tags
}

resource "aws_s3_bucket_versioning" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_bases)

  bucket = aws_s3_bucket.replica2[each.value].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_bases)

  bucket = aws_s3_bucket.replica2[each.value].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_bases)

  bucket = aws_s3_bucket.replica2[each.value].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica2" {
  provider = aws.replica2
  for_each = toset(local.all_bases)

  bucket = aws_s3_bucket.replica2[each.value].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica2.arn
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# Replication rules for the us-east-1 source buckets
# (two enabled rules each: one to eu-west-1, one to ap-southeast-1)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "source1" {
  for_each = toset(local.source1_bases)

  bucket = aws_s3_bucket.source1[each.value].id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-replica1"
    status = "Enabled"

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1[each.value].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id     = "replicate-to-replica2"
    status = "Enabled"

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2[each.value].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source1,
    aws_s3_bucket_versioning.source2,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
  ]
}

###############################################################################
# Replication rules for the us-west-2 source buckets
# (two enabled rules each: one to eu-west-1, one to ap-southeast-1)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "source2" {
  provider = aws.source2
  for_each = toset(local.source2_bases)

  bucket = aws_s3_bucket.source2[each.value].id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-replica1"
    status = "Enabled"

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1[each.value].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }
  }

  rule {
    id     = "replicate-to-replica2"
    status = "Enabled"

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2[each.value].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source1,
    aws_s3_bucket_versioning.source2,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
  ]
}

###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.1"
    }
  }
}

provider "aws" {
  region = var.region
}

# Secondary provider used only when cross-region replication is enabled.
provider "aws" {
  alias  = "replica"
  region = var.replication_region
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "Primary AWS region where the GuardDuty detector is created."
  type        = string
  default     = "us-east-1"
}

variable "replication_region" {
  description = "Destination region used only when findings export is enabled."
  type        = string
  default     = "us-west-2"
}

variable "repository_url" {
  description = "Repository URL used to tag the GuardDuty detector."
  type        = string
  default     = "https://github.com/example/terraform-aws-guardduty"
}

variable "name_prefix" {
  description = "Prefix used to name optional resources."
  type        = string
  default     = "guardduty"
}

variable "finding_publishing_frequency" {
  description = "Frequency with which GuardDuty publishes findings."
  type        = string
  default     = "FIFTEEN_MINUTES"
}

variable "tags" {
  description = "Additional tags applied to all created resources."
  type        = map(string)
  default     = {}
}

# --- Optional feature toggles (all disabled by default) ----------------------

variable "enable_findings_filters" {
  description = "Whether to create GuardDuty findings filters."
  type        = bool
  default     = false
}

variable "findings_filter_name" {
  description = "Name for the GuardDuty findings filter."
  type        = string
  default     = "guardduty-archive-low-severity"
}

variable "enable_trusted_ip_sets" {
  description = "Whether to create a GuardDuty trusted IP set."
  type        = bool
  default     = false
}

variable "trusted_ip_set_location" {
  description = "S3 URI of the trusted IP list (required when trusted IP sets are enabled)."
  type        = string
  default     = "https://example-bucket.s3.amazonaws.com/trusted-ips.txt"
}

variable "enable_threat_intel_sets" {
  description = "Whether to create a GuardDuty threat intelligence set."
  type        = bool
  default     = false
}

variable "threat_intel_set_location" {
  description = "S3 URI of the threat intelligence list (required when threat intel sets are enabled)."
  type        = string
  default     = "https://example-bucket.s3.amazonaws.com/threat-intel.txt"
}

variable "enable_s3_malware_protection_plan" {
  description = "Whether to create an S3 malware protection plan."
  type        = bool
  default     = false
}

variable "malware_protection_bucket_name" {
  description = "Name of the S3 bucket protected by the malware protection plan."
  type        = string
  default     = "example-malware-protected-bucket"
}

variable "enable_findings_export" {
  description = "Whether to create the S3/KMS resources that export GuardDuty findings."
  type        = bool
  default     = false
}

###############################################################################
# Locals
###############################################################################

locals {
  tags = merge(
    var.tags,
    {
      Repository = var.repository_url
    }
  )
}

###############################################################################
# GuardDuty detector (always created)
###############################################################################

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  # S3 data events
  features {
    name   = "S3_DATA_EVENTS"
    status = "ENABLED"
  }

  # RDS login events
  features {
    name   = "RDS_LOGIN_EVENTS"
    status = "ENABLED"
  }

  # Lambda network logs
  features {
    name   = "LAMBDA_NETWORK_LOGS"
    status = "ENABLED"
  }

  # EKS audit logs
  features {
    name   = "EKS_AUDIT_LOGS"
    status = "ENABLED"
  }

  # EBS malware protection
  features {
    name   = "EBS_MALWARE_PROTECTION"
    status = "ENABLED"
  }

  # Runtime monitoring: feature ON, automatic agent management OFF for each
  # supported runtime (EKS, ECS Fargate, EC2).
  features {
    name   = "RUNTIME_MONITORING"
    status = "ENABLED"

    additional_configuration {
      name   = "EKS_ADDON_MANAGEMENT"
      status = "DISABLED"
    }

    additional_configuration {
      name   = "ECS_FARGATE_AGENT_MANAGEMENT"
      status = "DISABLED"
    }

    additional_configuration {
      name   = "EC2_AGENT_MANAGEMENT"
      status = "DISABLED"
    }
  }

  tags = local.tags
}

###############################################################################
# Post-create AWS CLI step: do not retain EBS snapshots from malware scans
###############################################################################

resource "null_resource" "malware_scan_settings" {
  triggers = {
    detector_id = aws_guardduty_detector.this.id
    region      = var.region
  }

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --detector-id ${aws_guardduty_detector.this.id} --ebs-snapshot-preservation NO_RETENTION --region ${var.region}"
  }

  depends_on = [aws_guardduty_detector.this]
}

###############################################################################
# Optional: Findings filters (disabled by default)
###############################################################################

resource "aws_guardduty_filter" "this" {
  count = var.enable_findings_filters ? 1 : 0

  detector_id = aws_guardduty_detector.this.id
  name        = var.findings_filter_name
  action      = "ARCHIVE"
  rank        = 1
  description = "Archive low severity findings"

  finding_criteria {
    criterion {
      field     = "severity"
      less_than = "4"
    }
  }

  tags = local.tags
}

###############################################################################
# Optional: Trusted IP set (disabled by default)
###############################################################################

resource "aws_guardduty_ipset" "this" {
  count = var.enable_trusted_ip_sets ? 1 : 0

  detector_id = aws_guardduty_detector.this.id
  name        = "${var.name_prefix}-trusted-ips"
  format      = "TXT"
  location    = var.trusted_ip_set_location
  activate    = true

  tags = local.tags
}

###############################################################################
# Optional: Threat intelligence set (disabled by default)
###############################################################################

resource "aws_guardduty_threatintelset" "this" {
  count = var.enable_threat_intel_sets ? 1 : 0

  detector_id = aws_guardduty_detector.this.id
  name        = "${var.name_prefix}-threat-intel"
  format      = "TXT"
  location    = var.threat_intel_set_location
  activate    = true

  tags = local.tags
}

###############################################################################
# Optional: S3 malware protection plan (disabled by default)
###############################################################################

resource "aws_iam_role" "malware_protection_plan" {
  count = var.enable_s3_malware_protection_plan ? 1 : 0

  name = "${var.name_prefix}-malware-protection-plan"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "malware-protection-plan.guardduty.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "malware_protection_plan" {
  count = var.enable_s3_malware_protection_plan ? 1 : 0

  name = "${var.name_prefix}-malware-protection-plan"
  role = aws_iam_role.malware_protection_plan[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:PutObjectTagging",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${var.malware_protection_bucket_name}",
          "arn:${data.aws_partition.current.partition}:s3:::${var.malware_protection_bucket_name}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "events:PutRule",
          "events:DeleteRule",
          "events:DescribeRule",
          "events:PutTargets",
          "events:RemoveTargets",
          "events:ListTargetsByRule"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_guardduty_malware_protection_plan" "this" {
  count = var.enable_s3_malware_protection_plan ? 1 : 0

  role = aws_iam_role.malware_protection_plan[0].arn

  protected_resource {
    s3_bucket {
      bucket_name = var.malware_protection_bucket_name
    }
  }

  actions {
    tagging {
      status = "ENABLED"
    }
  }

  tags = local.tags
}

###############################################################################
# Optional: GuardDuty findings export (disabled by default)
#  - versioned, access-logged, KMS-encrypted, cross-region-replicated S3 bucket
###############################################################################

# --- KMS keys ---------------------------------------------------------------

data "aws_iam_policy_document" "findings_kms" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "AllowGuardDutyUseOfKey"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:CreateGrant"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAccountRoot"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "findings" {
  count = var.enable_findings_export ? 1 : 0

  description             = "KMS key for GuardDuty findings export"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  multi_region            = true
  policy                  = data.aws_iam_policy_document.findings_kms[0].json

  tags = local.tags
}

resource "aws_kms_replica_key" "findings" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica

  description             = "KMS replica key for GuardDuty findings export"
  deletion_window_in_days = 7
  primary_key_arn         = aws_kms_key.findings[0].arn

  tags = local.tags
}

# --- Source bucket ----------------------------------------------------------

resource "aws_s3_bucket" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = "${var.name_prefix}-findings-${data.aws_caller_identity.current.account_id}"

  tags = local.tags
}

resource "aws_s3_bucket_versioning" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.findings[0].arn
    }
    bucket_key_enabled = true
  }
}

# --- Access-log bucket ------------------------------------------------------

resource "aws_s3_bucket" "logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket = "${var.name_prefix}-findings-logs-${data.aws_caller_identity.current.account_id}"

  tags = local.tags
}

data "aws_iam_policy_document" "logs" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "S3ServerAccessLogsPolicy"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.logs[0].arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.logs[0].id
  policy = data.aws_iam_policy_document.logs[0].json
}

resource "aws_s3_bucket_logging" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket        = aws_s3_bucket.findings[0].id
  target_bucket = aws_s3_bucket.logs[0].id
  target_prefix = "log/"

  depends_on = [aws_s3_bucket_policy.logs]
}

# --- Replica bucket ---------------------------------------------------------

resource "aws_s3_bucket" "findings_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica

  bucket = "${var.name_prefix}-findings-replica-${data.aws_caller_identity.current.account_id}"

  tags = local.tags
}

resource "aws_s3_bucket_versioning" "findings_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.findings_replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.findings_replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_replica_key.findings[0].arn
    }
    bucket_key_enabled = true
  }
}

# --- Replication IAM role ---------------------------------------------------

data "aws_iam_policy_document" "replication_assume" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_findings_export ? 1 : 0

  name               = "${var.name_prefix}-findings-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume[0].json

  tags = local.tags
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "SourceBucketRead"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.findings[0].arn]
  }

  statement {
    sid    = "SourceObjectsRead"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectVersion",
      "s3:GetObject"
    ]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]
  }

  statement {
    sid    = "DestinationObjectsWrite"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner"
    ]
    resources = ["${aws_s3_bucket.findings_replica[0].arn}/*"]
  }

  statement {
    sid       = "SourceKmsDecrypt"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.findings[0].arn]
  }

  statement {
    sid    = "DestinationKmsEncrypt"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_replica_key.findings[0].arn]
  }
}

resource "aws_iam_policy" "replication" {
  count = var.enable_findings_export ? 1 : 0

  name   = "${var.name_prefix}-findings-replication"
  policy = data.aws_iam_policy_document.replication[0].json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = var.enable_findings_export ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# --- Replication configuration ---------------------------------------------

resource "aws_s3_bucket_replication_configuration" "findings" {
  count = var.enable_findings_export ? 1 : 0

  role   = aws_iam_role.replication[0].arn
  bucket = aws_s3_bucket.findings[0].id

  rule {
    id     = "replicate-all-guardduty-findings"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.findings_replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_replica_key.findings[0].arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.findings,
    aws_s3_bucket_versioning.findings_replica,
    aws_iam_role_policy_attachment.replication
  ]
}

# --- Bucket policy allowing GuardDuty to publish ---------------------------

data "aws_iam_policy_document" "findings_bucket" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "AllowGuardDutyPublishing"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
    actions = [
      "s3:PutObject",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.findings[0].arn,
      "${aws_s3_bucket.findings[0].arn}/*"
    ]
  }
}

resource "aws_s3_bucket_policy" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id
  policy = data.aws_iam_policy_document.findings_bucket[0].json
}

# --- GuardDuty publishing destination --------------------------------------

resource "aws_guardduty_publishing_destination" "this" {
  count = var.enable_findings_export ? 1 : 0

  detector_id     = aws_guardduty_detector.this.id
  destination_arn = aws_s3_bucket.findings[0].arn
  kms_key_arn     = aws_kms_key.findings[0].arn

  depends_on = [aws_s3_bucket_policy.findings]
}

###############################################################################
# Outputs
###############################################################################

output "guardduty_detector_id" {
  description = "ID of the created GuardDuty detector."
  value       = aws_guardduty_detector.this.id
}

output "guardduty_detector_arn" {
  description = "ARN of the created GuardDuty detector."
  value       = aws_guardduty_detector.this.arn
}

output "findings_export_bucket" {
  description = "Name of the findings export bucket (empty when export is disabled)."
  value       = var.enable_findings_export ? aws_s3_bucket.findings[0].bucket : ""
}
